import React, { useEffect, useRef, useState } from 'react';

interface PackCardFanProps {
  cards?: { imageUrl: string }[];
  /** 设计坐标系下的期望总高（横屏默认 104；竖屏传更大值，经 bodyScale 后视觉更小） */
  height?: number;
}

// 基准布局（scale=1，对应 height=104）：卡高 90、水平间距 33、弧高差 9、单卡宽约 卡高*0.72
const BASE_CARD_H = 90;
const BASE_X = 33;
const BASE_Y = 9;
const CARD_ASPECT = 0.72;

// 扇形（arc）展示最多 5 张球员卡面：中间卡居前，两侧向外旋转展开
const PackCardFan: React.FC<PackCardFanProps> = ({ cards, height = 104 }) => {
  const list = (cards ?? []).slice(0, 5);
  const [failed, setFailed] = useState<Record<number, boolean>>({});
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const [boxW, setBoxW] = useState<number>(0);

  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    const update = () => setBoxW(el.clientWidth || 0);
    update();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  if (list.length === 0) return <div ref={wrapRef} style={{ height }} />;

  const n = list.length;
  const mid = (n - 1) / 2;

  // 输入 list 已按总评降序。重排到展示槽位：最高放正中，
  // 其余按 左、右、左、右 交替（第2→左1，第3→右1，第4→左2，第5→右2）。
  const fillOrder: number[] = [];
  const leftStart = Math.floor(mid);
  const rightStart = Math.ceil(mid);
  if (n % 2 === 1) fillOrder.push(leftStart);
  let l = leftStart - (n % 2 === 1 ? 1 : 0);
  let r = rightStart + (n % 2 === 1 ? 1 : 0);
  while (l >= 0 || r < n) {
    if (l >= 0) fillOrder.push(l--);
    if (r < n) fillOrder.push(r++);
  }
  const display: { imageUrl: string }[] = [];
  list.forEach((card, rank) => {
    display[fillOrder[rank]] = card;
  });

  // 期望缩放（由 height 决定），再用容器实测宽度做上限，保证不溢出
  let s = (height - 14) / BASE_CARD_H;
  const maxStep = Math.max(...Array.from({ length: n }, (_, i) => Math.abs(i - mid)));
  const totalW = maxStep * 2 * BASE_X + BASE_CARD_H * CARD_ASPECT;
  if (boxW > 0 && totalW * s > boxW) s = boxW / totalW;
  if (!isFinite(s) || s <= 0) s = 0.01;

  const cardH = BASE_CARD_H * s;

  return (
    <div
      ref={wrapRef}
      className="relative w-full pointer-events-none select-none"
      style={{ height: cardH + 14 }}
      aria-hidden
    >
      {display.map((c, i) => {
        const step = i - mid;
        const rot = step * 11;
        const x = step * BASE_X * s;
        const y = Math.abs(step) * BASE_Y * s; // 中间卡抬升，两侧下沉成弧
        return (
          <img
            key={`${c.imageUrl}-${i}`}
            src={c.imageUrl}
            alt=""
            loading="lazy"
            decoding="async"
            onError={() => setFailed((p) => ({ ...p, [i]: true }))}
            className="absolute rounded-[6px] border border-white/25 shadow-[0_6px_14px_rgba(0,0,0,0.45)]
              bg-black/30 object-cover"
            style={{
              left: '50%',
              bottom: '2px',
              height: cardH,
              width: 'auto',
              transform: `translateX(calc(-50% + ${x}px)) translateY(${y}px) rotate(${rot}deg)`,
              zIndex: 10 - Math.abs(step),
              opacity: failed[i] ? 0 : 1,
            }}
          />
        );
      })}
    </div>
  );
};

export default PackCardFan;
