import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { useNavigate, useParams } from 'react-router-dom';
import {
  Save,
  Share2,
  Plus,
  Trash2,
  Loader2,
  FilePlus2,
  List,
  Download,
} from 'lucide-react';
import { toast } from 'sonner';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { showConfirm } from '@lark-apaas/client-toolkit';
import TierPlayerCard from './TierPlayerCard';
import { useLoginGuard } from '@client/src/hooks/useLoginGuard';
import {
  visitorLocalListDocs,
  visitorLocalGetDoc,
  visitorLocalUpsertDoc,
  visitorLocalRemoveDoc,
  visitorLocalDocId,
  toastVisitorLocal,
} from '@client/src/utils/visitor-mode';
import { useAuth } from '@client/src/context/AuthContext';
import type { MediaItem } from '@client/src/api/forum';
import { uploadMediaItem } from '@client/src/api/media-upload';
import { renderTierListCanvas } from '@client/src/utils/tier-image';
import { saveOrShareImage } from '@client/src/utils/native-image';
import ShareToForumDialog from '@client/src/components/ShareToForumDialog';
import BrandWatermark from '@client/src/components/BrandWatermark';
import VisitorModeBanner from '@client/src/components/VisitorModeBanner';
import PlayerPoolPanel from '@client/src/components/PlayerPoolPanel';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@client/src/components/ui/dialog';
import {
  saveTierList,
  getMyTierLists,
  getTierList,
  deleteTierList,
  type TierItemSnapshot,
  type TierRow,
  type TierListSummary,
} from '@client/src/api/tier-lists';

const COLOR_PRESETS = [
  '#ef4444',
  '#f97316',
  '#eab308',
  '#22c55e',
  '#06b6d4',
  '#3b82f6',
  '#8b5cf6',
  '#ec4899',
  '#64748b',
];

let seq = 0;
function newTierId(): string {
  seq += 1;
  return `t_${Date.now()}_${seq}`;
}

function defaultTiers(): TierRow[] {
  return [
    { id: newTierId(), name: 'S', color: '#ef4444' },
    { id: newTierId(), name: 'A', color: '#f97316' },
    { id: newTierId(), name: 'B', color: '#eab308' },
    { id: newTierId(), name: 'C', color: '#06b6d4' },
    { id: newTierId(), name: 'D', color: '#64748b' },
  ];
}

// 拖拽会话期间，是否已“抓起”（用于原生 touchmove 阻止滚动）
const ARMED = { current: false };

interface DragSession {
  item: TierItemSnapshot;
  fromTierId: string | null;
  pointerId: number;
  startX: number;
  startY: number;
  armed: boolean;
  timer: ReturnType<typeof setTimeout> | null;
  touch: boolean;
  el: HTMLElement | null;
}

// 游客本机强度榜文档结构（localStorage 持久化，与云端隔离）
interface LocalTierListDoc {
  id: string;
  name: string;
  tiers: TierRow[];
  items: Record<string, TierItemSnapshot[]>;
  userId: string;
  createdAt: string;
  updatedAt: string;
}

const MyTierList: React.FC = () => {
  const navigate = useNavigate();
  const { t } = useI18n();
  // i18n 翻译函数别名：层级 .map 内惯用 t 作行变量，遮蔽区改用 tr
  const tr = t;
  const { user, requireLogin, allowLocalAction } = useLoginGuard();
  const { getAuthHeaders } = useAuth();
  const { id: routeId } = useParams<{ id: string }>();

  const [listId, setListId] = useState<string | null>(null);
  const [listName, setListName] = useState(t('我的强度榜'));
  const [tiers, setTiers] = useState<TierRow[]>(() => defaultTiers());
  const [itemsByTier, setItemsByTier] = useState<Record<string, TierItemSnapshot[]>>(
    {},
  );
  const [readOnly, setReadOnly] = useState(false);
  const [ownerLoaded, setOwnerLoaded] = useState(false);

  // 球员筛选 / 选择已抽成共享组件 PlayerPoolPanel（见下方工作区）

  // 我的榜单
  const [myLists, setMyLists] = useState<TierListSummary[]>([]);
  const [showMy, setShowMy] = useState(false);

  const [saving, setSaving] = useState(false);
  const [sharing, setSharing] = useState(false);
  const [overTier, setOverTier] = useState<string | null>(null);
  // 表头日常只显示层级文字与人数；点击表头才弹出“层级设置”窗（改名/颜色/删除）
  const [tierSettingsId, setTierSettingsId] = useState<string | null>(null);
  const [ghost, setGhost] = useState<{ x: number; y: number; item: TierItemSnapshot } | null>(
    null,
  );
  const dragSession = useRef<DragSession | null>(null);

  // ---------- 拖拽到屏幕边缘：页面自动上/下滚动（便于把卡牌送到长榜单远端）----------
  const EDGE_ZONE = 96; // 距顶/底多少 px 进入自动滚动区
  const edgeRaf = useRef<number | null>(null);
  const edgeY = useRef<number | null>(null);
  const edgeTick = () => {
    const y = edgeY.current;
    if (y === null) {
      edgeRaf.current = null;
      return;
    }
    let dy = 0;
    if (y < EDGE_ZONE) dy = (y - EDGE_ZONE) / EDGE_ZONE; // 越靠顶越快（负值上滚）
    else if (y > window.innerHeight - EDGE_ZONE)
      dy = (y - (window.innerHeight - EDGE_ZONE)) / EDGE_ZONE; // 靠底（正值下滚）
    dy = Math.max(-1, Math.min(1, dy));
    if (dy !== 0) window.scrollBy(0, dy * 20);
    edgeRaf.current = requestAnimationFrame(edgeTick);
  };
  const edgeEnsure = (y: number) => {
    edgeY.current = y;
    if (edgeRaf.current === null) edgeRaf.current = requestAnimationFrame(edgeTick);
  };
  const edgeStop = () => {
    edgeY.current = null;
    if (edgeRaf.current !== null) {
      cancelAnimationFrame(edgeRaf.current);
      edgeRaf.current = null;
    }
  };
  // 离开页面时确保停止自动滚动
  useEffect(() => () => edgeStop(), []);

  const addedIds = useMemo(() => {
    const s = new Set<string>();
    for (const list of Object.values(itemsByTier)) for (const it of list) s.add(it.playerId);
    return s;
  }, [itemsByTier]);

  // 载入指定榜单
  useEffect(() => {
    if (!routeId) return;

    // 游客本机文档（local_ 前缀）：直接读 localStorage，不请求云端，且可编辑
    if (routeId.startsWith('local_')) {
      const rec = visitorLocalGetDoc<LocalTierListDoc>('tierlist', routeId);
      if (!rec) {
        toast.error(t('榜单不存在或已被删除'));
      } else {
        setListId(rec.id);
        setListName(rec.name);
        setTiers(rec.tiers?.length ? rec.tiers : defaultTiers());
        setItemsByTier(rec.items ?? {});
        setReadOnly(false);
        setOwnerLoaded(true);
      }
      return;
    }

    let cancelled = false;
    getTierList(routeId)
      .then((rec) => {
        if (cancelled) return;
        setListId(rec.id);
        setListName(rec.name);
        setTiers(rec.tiers.length > 0 ? rec.tiers : defaultTiers());
        setItemsByTier(rec.items ?? {});
        // 未登录、或非本人 → 一律只读（公开链接仅可查看，不可改动）
        setReadOnly(!user || rec.userId !== user.id);
        setOwnerLoaded(true);
      })
      .catch((e) => {
        logger.error('载入榜单失败', e);
        toast.error(t('榜单不存在或已被删除'));
      });
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [routeId]);

  // 筛选选项与卡包列表由共享组件 PlayerPoolPanel 自行加载

  const refreshMyLists = useCallback(() => {
    // 已登录：云端「我的榜单」；游客：本机 localStorage 文档
    if (user) {
      getMyTierLists(getAuthHeaders())
        .then((r) => setMyLists(r.items))
        .catch(() => undefined);
      return;
    }
    const docs = visitorLocalListDocs<LocalTierListDoc>('tierlist');
    setMyLists(
      docs.map((d) => ({
        id: d.id,
        name: d.name,
        itemCount: Object.values(d.items ?? {}).reduce((s, l) => s + l.length, 0),
        updatedAt: d.updatedAt ?? '',
      })),
    );
  }, [user, getAuthHeaders]);

  // 删除我保存的某个榜单
  const handleDeleteList = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    // 游客：删除本机文档（开关关时 allowLocalAction 会提示登录并跳转）
    if (!user) {
      if (!allowLocalAction(t('删除榜单'))) return;
      const ok = await showConfirm(t('确定删除这个强度榜吗？此操作不可恢复。'));
      if (!ok) return;
      visitorLocalRemoveDoc('tierlist', id);
      setMyLists((prev) => prev.filter((m) => m.id !== id));
      if (listId === id) startNew();
      toast.success(t('已删除榜单'));
      return;
    }
    if (!requireLogin(t('删除榜单'))) return;
    const ok = await showConfirm(t('确定删除这个强度榜吗？此操作不可恢复。'));
    if (!ok) return;
    try {
      await deleteTierList(id, getAuthHeaders());
      setMyLists((prev) => prev.filter((m) => m.id !== id));
      if (listId === id) startNew();
      toast.success(t('已删除榜单'));
    } catch (err) {
      logger.error('删除榜单失败', err);
      toast.error(t('删除失败，请稍后重试'));
    }
  };

  useEffect(() => {
    refreshMyLists();
  }, [refreshMyLists]);

  // 搜索 / 无限滚动逻辑已移入共享组件 PlayerPoolPanel

  const placeItem = useCallback((item: TierItemSnapshot, targetTierId: string) => {
    setItemsByTier((prev) => {
      const next: Record<string, TierItemSnapshot[]> = {};
      for (const [tid, list] of Object.entries(prev)) {
        next[tid] = list.filter((it) => it.playerId !== item.playerId);
      }
      if (!next[targetTierId]) next[targetTierId] = [];
      next[targetTierId] = [...next[targetTierId], item];
      return next;
    });
  }, []);

  const removeItem = useCallback((tid: string, playerId: string) => {
    setItemsByTier((prev) => ({
      ...prev,
      [tid]: (prev[tid] ?? []).filter((it) => it.playerId !== playerId),
    }));
  }, []);

  const renameTier = (tid: string, name: string) =>
    setTiers((prev) => prev.map((t) => (t.id === tid ? { ...t, name } : t)));

  const setTierColor = (tid: string, color: string) =>
    setTiers((prev) => prev.map((t) => (t.id === tid ? { ...t, color } : t)));

  const addTier = () =>
    setTiers((prev) => [
      ...prev,
      { id: newTierId(), name: t('新层级'), color: '#64748b' },
    ]);

  const deleteTier = (tid: string) => {
    setTiers((prev) => prev.filter((t) => t.id !== tid));
    setItemsByTier((prev) => {
      const next = { ...prev };
      delete next[tid];
      return next;
    });
  };

  // ---------- 统一指针拖拽（鼠标 + 触摸）----------
  const arm = (s: DragSession, x: number, y: number) => {
    s.armed = true;
    ARMED.current = true;
    // 抓起瞬间把源卡 touch-action 锁成 none：后续上/下/左/右移动都跟指，
    // 不会被浏览器当成纵向滚动（配合非被动 touchmove preventDefault 双保险）。
    try {
      s.el?.style.setProperty('touch-action', 'none');
    } catch {
      /* ignore */
    }
    try {
      navigator.vibrate?.(15);
    } catch {
      /* ignore */
    }
    setGhost({ x, y, item: s.item });
  };

  const onCardDown = (
    e: React.PointerEvent,
    item: TierItemSnapshot,
    fromTierId: string | null,
  ) => {
    if (readOnly) return;
    // 点到按钮（如 X 移出）时不启动拖拽/捕获指针，保证其 click 正常
    if ((e.target as HTMLElement).closest('button')) return;
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    try {
      (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    } catch {
      /* ignore */
    }
    const touch = e.pointerType === 'touch';
    const s: DragSession = {
      item,
      fromTierId,
      pointerId: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      armed: false,
      timer: null,
      touch,
      el: e.currentTarget as HTMLElement,
    };
    if (touch) {
      // 长按 150ms 抓起（手指先停住，有震动反馈）；抓起后即可全方向跟指拖动。
      // 长按期间若直接移动，则交给球员池纵向滚动。
      s.timer = setTimeout(() => arm(s, s.startX, s.startY), 150);
    }
    dragSession.current = s;
  };

  const onCardMove = (e: React.PointerEvent) => {
    const s = dragSession.current;
    if (!s) return;
    const dx = e.clientX - s.startX;
    const dy = e.clientY - s.startY;
    if (!s.armed) {
      if (s.touch) {
        if (Math.abs(dx) > 10 || Math.abs(dy) > 10) {
          if (s.timer) clearTimeout(s.timer);
          dragSession.current = null; // 让给页面滚动
        }
        return;
      }
      if (Math.hypot(dx, dy) > 5) arm(s, e.clientX, e.clientY);
      return;
    }
    e.preventDefault();
    setGhost({ x: e.clientX, y: e.clientY, item: s.item });
    edgeEnsure(e.clientY);
    const el = document.elementFromPoint(e.clientX, e.clientY);
    const tid = el?.closest('[data-drop-tier]')?.getAttribute('data-drop-tier') ?? null;
    setOverTier((prev) => (prev === tid ? prev : tid));
  };

  const onCardUp = (e: React.PointerEvent) => {
    const s = dragSession.current;
    if (!s) return;
    if (s.timer) clearTimeout(s.timer);
    // 还原源卡 touch-action，恢复球员池正常纵向滚动
    try {
      s.el?.style.removeProperty('touch-action');
    } catch {
      /* ignore */
    }
    if (s.armed) {
      const el = document.elementFromPoint(e.clientX, e.clientY);
      const tid = el?.closest('[data-drop-tier]')?.getAttribute('data-drop-tier');
      if (tid) placeItem(s.item, tid);
    }
    edgeStop();
    dragSession.current = null;
    ARMED.current = false;
    setGhost(null);
    setOverTier(null);
  };

  // 给卡片绑定非被动 touchmove（抓起后阻止页面滚动）
  const bindTouch = (el: HTMLElement | null) => {
    if (el && !(el as any).__ptsBound) {
      el.addEventListener(
        'touchmove',
        (ev) => {
          if (ARMED.current) ev.preventDefault();
        },
        { passive: false },
      );
      (el as any).__ptsBound = true;
    }
  };

  const buildPayload = () => ({
    name: listName.trim() || t('我的强度榜'),
    tiers,
    items: itemsByTier,
  });

  const handleSave = async () => {
    // 游客：仅本机 localStorage 保存，不发任何云端请求
    if (!user) {
      if (!allowLocalAction(t('保存强度榜'))) return;
      setSaving(true);
      try {
        const id = listId ?? visitorLocalDocId();
        const existing = listId
          ? visitorLocalGetDoc<LocalTierListDoc>('tierlist', listId)
          : null;
        const now = new Date().toISOString();
        visitorLocalUpsertDoc<LocalTierListDoc>('tierlist', {
          id,
          ...buildPayload(),
          userId: '',
          createdAt: existing?.createdAt ?? now,
          updatedAt: now,
        });
        setListId(id);
        toast.success(t('强度榜已保存'));
        toastVisitorLocal('tierlist');
        refreshMyLists();
      } finally {
        setSaving(false);
      }
      return;
    }
    setSaving(true);
    try {
      const r = await saveTierList(buildPayload(), listId, getAuthHeaders());
      setListId(r.id);
      toast.success(t('强度榜已保存'));
      refreshMyLists();
    } catch (e: any) {
      const msg =
        e?.response?.data?.error?.message || e?.message || t('保存失败，请稍后重试');
      toast.error(msg);
    } finally {
      setSaving(false);
    }
  };

  const handleDownloadImage = async () => {
    try {
      const canvas = await renderTierListCanvas(buildPayload());
      await saveOrShareImage(canvas.toDataURL('image/png'), `${listName || t('强度榜')}.png`);
    } catch {
      toast.error(t('生成图片失败，请稍后重试'));
    }
  };

  const [shareOpen, setShareOpen] = useState(false);

  // 点击分享：先确保榜单已保存（生成可访问链接），再打开分享弹窗
  const handleShare = async () => {
    if (!requireLogin(t('分享强度榜'))) return;
    setSharing(true);
    try {
      if (!listId) {
        const r = await saveTierList(buildPayload(), null, getAuthHeaders());
        setListId(r.id);
        refreshMyLists();
      }
      setShareOpen(true);
    } catch (e: any) {
      const msg = e?.response?.data?.error?.message || e?.message || t('保存榜单失败');
      toast.error(msg);
    } finally {
      setSharing(false);
    }
  };

  // 弹窗发布时：渲染榜单图并上传，作为帖子配图
  const buildShareMedia = async (): Promise<MediaItem[] | undefined> => {
    try {
      const canvas = await renderTierListCanvas(buildPayload());
      const blob: Blob = await new Promise((resolve, reject) =>
        canvas.toBlob((b) => (b ? resolve(b) : reject(new Error('toBlob failed'))), 'image/png'),
      );
      const file = new File([blob], `${listName || t('强度榜')}.png`, { type: 'image/png' });
      const media = await uploadMediaItem(file);
      return [{ url: media.url, type: 'image', filename: media.filename, size: media.size }];
    } catch (e) {
      logger.error('生成分享图失败', e);
      toast.error(t('生成分享图失败，请稍后重试'));
      return undefined;
    }
  };

  // 分享到论坛只带榜单图与一句引言，不附在线链接
  const shareContent = t('这是我整理的球员强度排行，欢迎大家讨论！');

  const startNew = () => {
    setListId(null);
    setListName(t('我的强度榜'));
    setTiers(defaultTiers());
    setItemsByTier({});
    setReadOnly(false);
    navigate('/tier');
  };

  const totalCount = Object.values(itemsByTier).reduce((s, l) => s + l.length, 0);

  const dragHandlers = (item: TierItemSnapshot, from: string | null) => ({
    ref: bindTouch,
    onPointerDown: (e: React.PointerEvent) => onCardDown(e, item, from),
    onPointerMove: onCardMove,
    onPointerUp: onCardUp,
    onPointerCancel: onCardUp,
  });

  return (
    <div className="tier-scope px-3 py-3 sm:px-5">
      {readOnly && ownerLoaded && (
        <div className="mb-3 flex flex-wrap items-center justify-between gap-2 rounded-xl border border-cyan-400/30 bg-cyan-500/10 px-4 py-2.5">
          <span className="text-sm text-cyan-100">{t('你正在查看他人分享的强度榜')}</span>
          <button
            type="button"
            onClick={startNew}
            className="rounded-lg bg-cyan-500 px-3 py-1.5 text-sm font-bold text-white hover:bg-cyan-400"
          >
            {t('我也要做一个')}
          </button>
        </div>
      )}

      {/* 标题与操作 */}
      <div className="mb-3 flex flex-wrap items-center gap-2 sm:gap-1.5">
        <input
          value={listName}
          onChange={(e) => setListName(e.target.value)}
          disabled={readOnly}
          className="min-w-0 w-28 flex-none rounded-lg border border-white/15 bg-white/5 px-3 py-2 text-base font-bold text-white outline-none focus:border-cyan-400 disabled:opacity-80 sm:w-auto sm:flex-1 sm:py-1.5 sm:text-xl"
          placeholder={t('给榜单起个名字')}
        />
        <div className="flex items-center gap-2 sm:gap-1.5">
          <button
            type="button"
            onClick={() => setShowMy((v) => !v)}
            className="flex h-11 w-11 items-center justify-center rounded-lg border border-white/15 bg-white/5 text-white hover:bg-white/10 sm:h-9 sm:w-9"
            aria-label={t('我的榜单')}
          >
            <List className="h-6 w-6 sm:h-[18px] sm:w-[18px]" />
          </button>
          {!readOnly && (
            <button
              type="button"
              onClick={startNew}
              className="flex h-11 w-11 items-center justify-center rounded-lg border border-white/15 bg-white/5 text-white hover:bg-white/10 sm:h-9 sm:w-9"
              aria-label={t('新建榜单')}
            >
              <FilePlus2 className="h-6 w-6 sm:h-[18px] sm:w-[18px]" />
            </button>
          )}
          {/* 图片下载按钮（全平台）：导出带水印的榜单图 */}
          <button
            type="button"
            onClick={handleDownloadImage}
            className="flex h-11 w-11 items-center justify-center rounded-lg border border-white/15 bg-white/5 text-white hover:bg-white/10 sm:h-9 sm:w-9"
            aria-label={t('下载榜单图片')}
            title={t('下载榜单图片')}
          >
            <Download className="h-6 w-6 sm:h-[18px] sm:w-[18px]" />
          </button>
          {!readOnly && (
            <button
              type="button"
              onClick={handleSave}
              disabled={saving}
              className="flex h-11 items-center gap-1.5 rounded-lg bg-blue-600 px-4 text-base font-bold text-white hover:bg-blue-500 disabled:opacity-60 sm:h-9 sm:px-3 sm:text-sm"
            >
              {saving ? <Loader2 className="h-5 w-5 animate-spin sm:h-4 sm:w-4" /> : <Save className="h-5 w-5 sm:h-4 sm:w-4" />}
              {t('保存')}
            </button>
          )}
          {!readOnly && (
            <button
              type="button"
              onClick={handleShare}
              disabled={sharing}
              className="flex h-11 items-center gap-1.5 rounded-lg bg-gradient-to-r from-pink-500 to-rose-500 px-4 text-base font-bold text-white hover:opacity-90 disabled:opacity-60 sm:h-9 sm:px-3 sm:text-sm"
            >
              {sharing ? <Loader2 className="h-5 w-5 animate-spin sm:h-4 sm:w-4" /> : <Share2 className="h-5 w-5 sm:h-4 sm:w-4" />}
              {t('分享论坛')}
            </button>
          )}
        </div>
      </div>

      {!user && <VisitorModeBanner className="mb-3" />}

      {showMy && (
        <div className="mb-3 rounded-xl border border-white/10 bg-white/5 p-3">
          <p className="mb-2 text-sm font-bold text-white">{t('我保存的强度榜')}</p>
          {myLists.length === 0 ? (
            <p className="text-sm text-white/50">{t('还没有保存过榜单')}</p>
          ) : (
            <div className="flex flex-wrap gap-2">
              {myLists.map((m) => (
                <div
                  key={m.id}
                  className="group relative rounded-lg border border-white/15 bg-[#141838] hover:border-cyan-400"
                >
                  <button
                    type="button"
                    onClick={() => {
                      navigate(`/tier/${m.id}`);
                      setShowMy(false);
                    }}
                    className="px-3 py-1.5 text-sm text-white"
                  >
                    {m.name}
                    <span className="ml-1.5 text-white/40">{m.itemCount}{t('人')}</span>
                  </button>
                  <button
                    type="button"
                    aria-label={t('删除榜单')}
                    title={t('删除榜单')}
                    onClick={(e) => void handleDeleteList(m.id, e)}
                    className="absolute -right-2 -top-2 flex h-6 w-6 items-center justify-center rounded-full bg-rose-500 text-white shadow transition hover:bg-rose-400"
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* ===== 双栏工作区：横屏 强度表左/球员池右；竖屏 强度表上/球员池下 ===== */}
      <div className="flex flex-col gap-3 lg:h-[calc(100vh-150px)] lg:flex-row lg:overflow-hidden">
        {/* —— 强度表（常驻主视角）——
            竖屏：不限高度、不出现模块内滚动，整张强度表始终完整，由页面整体上下滚动；
            横屏(lg)：固定 66% 宽、高度铺满，内部按需滚动。 */}
        <section className="relative z-20 rounded-xl border border-white/10 bg-white/[0.03] lg:max-h-none lg:w-[66%] lg:shrink-0 lg:overflow-y-auto">
          <div className="space-y-2 p-2">
            {tiers.map((t) => {
              const list = itemsByTier[t.id] ?? [];
              const isOver = overTier === t.id;
              return (
                <div
                  key={t.id}
                  data-drop-tier={t.id}
                  className={`flex overflow-hidden rounded-lg border ${
                    isOver ? 'border-cyan-300 ring-2 ring-cyan-300/50' : 'border-white/10'
                  } bg-white/[0.04]`}
                >
                  <div
                    role={readOnly ? undefined : 'button'}
                    onClick={readOnly ? undefined : () => setTierSettingsId(t.id)}
                    title={readOnly ? undefined : tr('点击设置该层级（改名 / 颜色 / 删除）')}
                    className={`flex w-14 flex-col items-center justify-center gap-1 py-1.5 lg:w-16 ${
                      readOnly ? '' : 'cursor-pointer hover:brightness-110'
                    }`}
                    style={{ backgroundColor: t.color }}
                  >
                    <span className="break-all px-0.5 text-center text-xs font-black text-white lg:text-sm">
                      {t.name}
                    </span>
                    <span className="rounded-full bg-black/30 px-1.5 text-[10px] font-bold leading-4 text-white/95">
                      {list.length}
                    </span>
                  </div>

                  <div className="min-w-0 flex-1 p-1.5">
                    {/* 竖屏也换行平铺，所有卡完整可见、不做层内横滑 */}
                    {list.length === 0 ? (
                      <div className="flex h-full min-h-[64px] items-center justify-center px-1 text-center text-[11px] text-white/35">
                        {readOnly ? tr('暂无球员') : tr('把球员拖到这里')}
                      </div>
                    ) : (
                      <div className="rank-scroll flex flex-wrap gap-1.5 pb-0.5 lg:overflow-visible">
                        {list.map((item) => (
                          <div
                            key={item.playerId}
                            className="drag-touch w-[117px] flex-shrink-0 lg:w-[88px]"
                            {...dragHandlers(item, t.id)}
                          >
                            <TierPlayerCard
                              item={item}
                              onRemove={
                                readOnly ? undefined : () => removeItem(t.id, item.playerId)
                              }
                            />
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              );
            })}

            {!readOnly && (
              <button
                type="button"
                onClick={addTier}
                className="flex w-full items-center justify-center gap-1.5 rounded-lg border border-dashed border-white/20 py-2 text-sm text-white/60 hover:border-cyan-400 hover:text-cyan-300"
              >
                <Plus className="h-4 w-4" /> {t('新增一个层级')}
              </button>
            )}
            <p className="pb-1 text-center text-[11px] text-white/40">
              {t('已放入')} {totalCount} {t('名球员')}
            </p>
          </div>
          {/* 右上角品牌水印：浅灰 + 行楷；不拦截任何操作 */}
          <BrandWatermark position="top-right" />
        </section>

        {/* —— 球员池（共享标准筛选模块）—— */}
        <PlayerPoolPanel
          show={!readOnly}
          getCardHandlers={(item) => dragHandlers(item as TierItemSnapshot, null)}
          isAdded={(item) => addedIds.has(item.playerId)}
          hintText={t('电脑：按住球员直接拖到左侧层级；手机：长按球员后拖到上方层级')}
        />
      </div>

      {/* 免责申明：移到核心编辑区之后，增大强度表/球员池显示面积 */}
      <p className="mt-1 text-center text-[11px] text-white/40 sm:text-left">
        {t('卡面版权归 KONAMI 所有 · 本内容仅用于学习交流，禁止商业用途')}
      </p>

      {/* 拖拽中的悬浮卡：跟随指针，抬起+微旋转+强阴影，明确“正在拖动” */}
      {ghost &&
        createPortal(
          <div
            className="pointer-events-none fixed z-[9999]"
            style={{
              left: ghost.x,
              top: ghost.y,
              transform: 'translate(-50%,-55%) rotate(-3deg) scale(1.08)',
            }}
          >
            <div className="w-[72px] overflow-hidden rounded-lg ring-2 ring-cyan-300/80 shadow-[0_18px_42px_rgba(0,0,0,0.65)]">
              <TierPlayerCard item={ghost.item} />
            </div>
          </div>,
          document.body,
        )}

      {/* 层级设置窗：改名 / 颜色 / 删除（点击表头才打开） */}
      <Dialog open={!!tierSettingsId} onOpenChange={(o) => { if (!o) setTierSettingsId(null); }}>
        <DialogContent className="w-[92vw] max-w-sm border-white/10 bg-[#0f1330] text-white">
          <DialogHeader>
            <DialogTitle className="text-white">{t('层级设置')}</DialogTitle>
          </DialogHeader>
          {(() => {
            const tier = tiers.find((x) => x.id === tierSettingsId);
            if (!tier) return <p className="text-sm text-white/50">{t('层级不存在')}</p>;
            return (
              <div className="space-y-4">
                <div>
                  <label className="mb-1 block text-xs font-bold text-white/60">{t('层级名称')}</label>
                  <input
                    value={tier.name}
                    onChange={(e) => renameTier(tier.id, e.target.value)}
                    maxLength={8}
                    className="h-10 w-full rounded-lg border border-white/15 bg-[#0A0E27] px-3 text-sm text-white outline-none focus:border-cyan-400"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-xs font-bold text-white/60">{t('层级颜色')}</label>
                  <div className="flex flex-wrap gap-2">
                    {COLOR_PRESETS.map((c) => (
                      <button
                        key={c}
                        type="button"
                        aria-label={c}
                        onClick={() => setTierColor(tier.id, c)}
                        className={`h-8 w-8 rounded-full border-2 ${
                          tier.color === c ? 'border-white' : 'border-white/20'
                        }`}
                        style={{ backgroundColor: c }}
                      />
                    ))}
                  </div>
                </div>
                <div className="flex items-center justify-between gap-2 pt-1">
                  <button
                    type="button"
                    onClick={() => { deleteTier(tier.id); setTierSettingsId(null); }}
                    className="flex items-center gap-1.5 rounded-lg border border-rose-400/40 bg-rose-500/15 px-3 py-2 text-sm font-bold text-rose-200 hover:bg-rose-500/25"
                  >
                    <Trash2 className="h-4 w-4" /> {t('删除该层级')}
                  </button>
                  <button
                    type="button"
                    onClick={() => setTierSettingsId(null)}
                    className="rounded-lg bg-cyan-500 px-4 py-2 text-sm font-bold text-white hover:bg-cyan-400"
                  >
                    {t('完成')}
                  </button>
                </div>
              </div>
            );
          })()}
        </DialogContent>
      </Dialog>

      <ShareToForumDialog
        open={shareOpen}
        onClose={() => setShareOpen(false)}
        defaultTitle={`${t('我的强度榜｜')}${listName.trim() || t('快来看看')}`}
        defaultContent={shareContent}
        buildMedia={buildShareMedia}
        onPosted={(p) => navigate(`/forum/${p.id}`)}
      />
    </div>
  );
};

export default MyTierList;
