// 统一后端基地址：
// 依赖恢复后 toolkit 默认 baseURL 变为 '/'，原生 App（origin https://localhost）会把
// 接口打到设备自身源导致列表全空、卡包 undefined 崩溃。这里在启动时显式按
// runtime-config 的 API_BASE_URL 还原为绝对地址（与历史可用版本一致）。
import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';
import { runtimeConfig } from '@client/src/utils/config';

export function setupApiBase(): void {
  const base = (runtimeConfig.API_BASE_URL || '').replace(/\/+$/, '');
  axiosForBackend.defaults.baseURL = base || '/';
}
