import React, { useState } from 'react';
import type { PlayerListItem } from '@shared/api.interface';
import { Image } from '@client/src/components/ui/image';
import { resolvePlayerCardImage, resolveSmallPlayerCardImage } from '@client/src/utils/player-card-url';
import { usePlayerName } from '@client/src/i18n/PlayerName';

interface PlayerCardProps {
  player: PlayerListItem;
  onClick: () => void;
  overlay?: boolean;
  bareCard?: boolean;
}

const positionColorMap: Record<string, string> = {
  中锋: 'from-red-500 to-orange-500',
  影锋: 'from-orange-500 to-yellow-500',
  左边锋: 'from-rose-500 to-pink-500',
  右边锋: 'from-rose-500 to-pink-500',
  前腰: 'from-cyan-500 to-pink-500',
  左前卫: 'from-cyan-500 to-violet-500',
  中前卫: 'from-blue-500 to-indigo-500',
  右前卫: 'from-cyan-500 to-violet-500',
  后腰: 'from-cyan-500 to-blue-500',
  左后卫: 'from-teal-500 to-emerald-500',
  中后卫: 'from-green-500 to-emerald-500',
  右后卫: 'from-teal-500 to-emerald-500',
  门将: 'from-yellow-500 to-amber-500',
};

function getInitial(name?: string | null): string {
  return name && name.length > 0 ? name.charAt(0).toUpperCase() : '?';
}

const PlayerCard: React.FC<PlayerCardProps> = ({ player, onClick, overlay = true, bareCard = false }) => {
  const [imgLoaded, setImgLoaded] = useState(false);
  const [imgError, setImgError] = useState(false);
  const [triedSmall, setTriedSmall] = useState(false);
  const playerName = usePlayerName();
  const largeImageUrl = resolvePlayerCardImage(player.playerImageUrl, player.playerId);
  const smallImageUrl = resolveSmallPlayerCardImage(player.playerId);
  const cardImageUrl = triedSmall ? smallImageUrl : largeImageUrl;
  const hasImage = cardImageUrl && !imgError;
  const showPlaceholder = !hasImage || !imgLoaded;

  if (overlay) {
    return (
      <div onClick={onClick} className="cursor-pointer">
      <div
        className="group relative overflow-hidden rounded-xl border border-white/10 transition-all duration-200 hover:-translate-y-0.5 hover:border-cyan-400/50 hover:shadow-[0_4px_20px_rgba(0_229_255_0.25)] aspect-[3/4]"
      >
        <div className="absolute inset-0 bg-gradient-to-br from-[#141A30] to-[#1B2340]" />
        <div className="absolute inset-0 bg-gradient-to-br from-cyan-500/10 via-transparent to-transparent animate-pulse" />
        <div className="relative h-full w-full">
          {hasImage && (
            <Image
              src={cardImageUrl}
              alt={player.nameZh}
              className={`h-full w-full object-contain object-bottom transition-opacity duration-500 ${imgLoaded ? 'opacity-100' : 'opacity-0'}`}
              onLoad={() => setImgLoaded(true)}
              onError={() => {
                if (!triedSmall && smallImageUrl) {
                  setTriedSmall(true);
                  setImgLoaded(false);
                } else {
                  setImgError(true);
                }
              }}
              loading="lazy"
              decoding="async"
            />
          )}
          {showPlaceholder && (
            <div className="absolute inset-0 flex items-center justify-center">
              <span className="text-5xl font-bold text-white/50 drop-shadow-lg select-none">
                {getInitial(playerName(player))}
              </span>
            </div>
          )}

          {!bareCard && (
            <>
              <div className="pointer-events-none absolute inset-0 bg-gradient-to-b from-black/30 via-transparent to-black/60" />

              <div className="absolute top-2.5 left-2.5 z-10 flex flex-col items-start">
                <span className="text-3xl font-black text-amber-300 leading-none drop-shadow-[0_2px_6px_rgba(0_0_0_0.8)]">
                  {player.overallRating}
                </span>
                <span className="mt-1.5 px-2 py-0.5 text-xs font-bold rounded bg-cyan-400/25 text-cyan-100 border border-cyan-400/50 backdrop-blur-sm drop-shadow-[0_1px_3px_rgba(0_0_0_0.6)]">
                  {player.position}
                </span>
              </div>

              <div className="absolute bottom-10 left-0 right-0 z-10 px-2">
                <h3 className="truncate text-base font-bold text-white text-center drop-shadow-[0_1px_3px_rgba(0_0_0_0.85)]">
                  {playerName(player)}
                </h3>
              </div>
            </>
          )}
        </div>
      </div>
      </div>
    );
  }

  return (
    <div
      onClick={onClick}
      className="group cursor-pointer transition-all duration-200 hover:-translate-y-0.5 hover:shadow-[0_4px_20px_rgba(0_229_255_0.25)]"
    >
      <div className="relative aspect-[3/4] overflow-hidden rounded-xl border border-white/10">
        <div className="absolute inset-0 bg-gradient-to-br from-[#141A30] to-[#1B2340]" />
        <div className="absolute inset-0 bg-gradient-to-br from-cyan-500/10 via-transparent to-transparent animate-pulse" />
        <div className="relative h-full w-full">
          {hasImage && (
            <Image
              src={cardImageUrl}
              alt={player.nameZh}
              className={`h-full w-full object-contain object-bottom transition-opacity duration-500 ${imgLoaded ? 'opacity-100' : 'opacity-0'}`}
              onLoad={() => setImgLoaded(true)}
              onError={() => {
                if (!triedSmall && smallImageUrl) {
                  setTriedSmall(true);
                  setImgLoaded(false);
                } else {
                  setImgError(true);
                }
              }}
              loading="lazy"
              decoding="async"
            />
          )}
          {showPlaceholder && (
            <div className="absolute inset-0 flex items-center justify-center">
              <span className="text-4xl font-bold text-white/50 drop-shadow-lg select-none">
                {getInitial(playerName(player))}
              </span>
            </div>
          )}
        </div>
      </div>
      <div className="mt-1 px-1">
        <p className="truncate text-xs font-medium text-white/90 text-center">
          {playerName(player)}
        </p>
      </div>
    </div>
  );
};

export default PlayerCard;
