import React, { useState, useMemo, useEffect, Component } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { ArrowLeft, Check, X, Search, Users, AlertTriangle } from 'lucide-react';
import { resolvePlayerCardImage } from '@client/src/utils/player-card-url';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { Input } from '@client/src/components/ui/input';
import { Button } from '@client/src/components/ui/button';
import { Image } from '@client/src/components/ui/image';
import PlayerCard from '@client/src/components/PlayerCard';
import { players } from '@client/src/api';
import { useIsLandscape } from '@client/src/hooks/useIsLandscape';
import type { PlayerListItem, Player } from '@shared/api.interface';

const MAX_SELECTED = 4;
const MIN_SELECTED = 2;

function toListItem(p: Player): PlayerListItem {
  return {
    id: p.id,
    nameZh: p.nameZh,
    nameEn: p.nameEn,
    teamSeason: p.teamSeason,
    position: p.position,
    overallRating: p.overallRating,
    level: p.level,
    age: p.age,
    height: p.height,
    weight: p.weight,
    style: p.style,
    tactic: p.tactic,
    avatarUrl: p.avatarUrl,
    isSample: p.isSample,
    maxLevel: p.maxLevel,
    playerType: p.playerType || '标准球员',
    playerImageUrl: p.playerImageUrl,
    league: p.league,
    club: p.club,
    nationality: p.nationality || null,
    skills: p.skills || [],
    preferredFoot: p.preferredFoot || null,
    weakFootFrequency: p.weakFootFrequency || 0,
    weakFootAccuracy: p.weakFootAccuracy || 0,
    formVariation: p.formVariation || 0,
    aiPlayStyle: p.aiPlayStyle,
    likeCount: p.likeCount,
    playerId: p.playerId,
  };
}

interface SelectedPlayerCardProps {
  player: PlayerListItem;
  onRemove: (id: string) => void;
}

const SelectedPlayerCard: React.FC<SelectedPlayerCardProps> = ({ player, onRemove }) => {
  const [imgError, setImgError] = useState(false);
  const cardImageUrl = resolvePlayerCardImage(player.playerImageUrl, player.playerId);
  const initial = player.nameZh ? player.nameZh.charAt(0) : '?';
  const hasImage = cardImageUrl && !imgError;

  return (
    <div
      className="relative flex-shrink-0 rounded-md border border-cyan-400/30 overflow-hidden w-12 h-16 bg-[#141A30]"
    >
      {hasImage ? (
        <Image
          src={cardImageUrl}
          alt={player.nameZh}
          className="w-full h-full object-contain object-bottom"
          onError={() => setImgError(true)}
        />
      ) : (
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="text-xl font-bold text-white/60 drop-shadow">
            {initial}
          </span>
        </div>
      )}
      <button
        onClick={(e) => {
          e.stopPropagation();
          onRemove(player.id);
        }}
        className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-black/70 text-gray-300 hover:text-white hover:bg-black/90 transition-colors border border-white/20"
      >
        <X className="h-2.5 w-2.5" />
      </button>
    </div>
  );
};

class CompareSelectErrorBoundary extends Component<
  { children: React.ReactNode },
  { hasError: boolean; error: Error | null }
> {
  constructor(props: { children: React.ReactNode }) {
    super(props);
    this.state = { hasError: false, error: null };
  }
  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }
  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[#0A0E27] flex items-center justify-center p-4">
          <div className="max-w-md w-full bg-red-900/30 border border-red-500/50 rounded-xl p-6">
            <div className="flex items-center gap-2 mb-3">
              <AlertTriangle className="w-6 h-6 text-red-400" />
              <h2 className="text-lg font-bold text-red-300">页面渲染错误</h2>
            </div>
            <p className="text-red-200 text-sm mb-2">错误名称: {this.state.error?.name}</p>
            <p className="text-red-200 text-sm mb-2">错误消息: {this.state.error?.message}</p>
            <pre className="text-red-300/70 text-xs bg-black/30 p-2 rounded overflow-auto max-h-48">
              {this.state.error?.stack || '无堆栈信息'}
            </pre>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

const PlayerCompareSelectPageInner: React.FC = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const landscape = useIsLandscape();
  const gridCls = landscape ? 'grid grid-cols-8 gap-2' : 'grid grid-cols-5 gap-2';

  const [allPlayers, setAllPlayers] = useState<PlayerListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [keyword, setKeyword] = useState('');
  const [debouncedKeyword, setDebouncedKeyword] = useState<string | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [selectedData, setSelectedData] = useState<Map<string, PlayerListItem>>(new Map());

  const sameName = searchParams.get('sameName') || '';
  const sameNameEn = searchParams.get('sameNameEn') || '';
  const isSameNameMode = !!sameName || !!sameNameEn;

  useEffect(() => {
    const timer = window.setTimeout(() => {
      setDebouncedKeyword(keyword.trim());
    }, 200);
    return () => window.clearTimeout(timer);
  }, [keyword]);

  // 仅恢复通过 URL initial 传入的已选球员，不预加载球员列表
  useEffect(() => {
    const initial = searchParams.get('initial');
    if (!initial) return;
    const ids = initial.split(',').filter(Boolean).slice(0, MAX_SELECTED);
    if (ids.length === 0) return;
    setSelectedIds(ids);
    players.getPlayersBulk(ids).then((bulkPlayers: Player[]) => {
      const listItems = bulkPlayers.map(toListItem);
      setSelectedData((prev) => {
        const m = new Map(prev);
        listItems.forEach((p) => m.set(p.id, p));
        return m;
      });
    }).catch((err: unknown) => {
      logger.error('加载初始球员信息失败', err);
    });
  }, [searchParams]);

  // 同名模式：自动加载同名球员（保留现状）；普通模式：仅在有关键词时按搜索加载，不预拉全量
  useEffect(() => {
    let cancelled = false;
    const run = async () => {
      if (isSameNameMode) {
        setLoading(true);
        try {
          const data = await players.getSameNamePlayers({
            nameZh: sameName || undefined,
            nameEn: sameNameEn || undefined,
          });
          if (!cancelled) setAllPlayers(data.items);
        } catch (error) {
          logger.error('加载同名球员失败', error);
          if (!cancelled) setAllPlayers([]);
        } finally {
          if (!cancelled) setLoading(false);
        }
      } else if (debouncedKeyword) {
        setLoading(true);
        try {
          const data = await players.getAllPlayers({ keyword: debouncedKeyword });
          if (!cancelled) setAllPlayers(data.items);
        } catch (error) {
          logger.error('搜索球员失败', error);
          if (!cancelled) setAllPlayers([]);
        } finally {
          if (!cancelled) setLoading(false);
        }
      } else {
        // 普通模式且无搜索词：不预加载，列表留空
        setAllPlayers([]);
        setLoading(false);
      }
    };
    run();
    return () => { cancelled = true; };
  }, [debouncedKeyword, isSameNameMode, sameName, sameNameEn]);

  const selectedPlayers = useMemo(
    () => selectedIds.map((id) => selectedData.get(id)).filter((p): p is PlayerListItem => !!p),
    [selectedIds, selectedData]
  );

  const isFull = selectedIds.length >= MAX_SELECTED;

  const togglePlayer = (id: string) => {
    setSelectedIds((prev) => {
      if (prev.includes(id)) {
        return prev.filter((x) => x !== id);
      }
      if (prev.length >= MAX_SELECTED) return prev;
      const p = allPlayers.find((x) => x.id === id);
      if (p) {
        setSelectedData((prevMap) => {
          const m = new Map(prevMap);
          m.set(id, p);
          return m;
        });
      }
      return [...prev, id];
    });
  };

  const removePlayer = (id: string) => {
    setSelectedIds((prev) => prev.filter((x) => x !== id));
  };

  const handleStartCompare = () => {
    if (selectedIds.length < MIN_SELECTED) return;
    navigate(`/compare?ids=${selectedIds.join(',')}`);
  };

  const canCompare = selectedIds.length >= MIN_SELECTED;

  return (
    <div className="min-h-screen bg-[#0A0E27] -mt-3" data-testid="compare-select-page">
      <div className="border-b border-white/10 bg-[#0A0E27]/95 backdrop-blur-md px-3 py-2">
        <div className="flex items-center gap-2">
          <div className="flex-1 flex items-center gap-1.5 overflow-x-auto min-h-[48px]">
            {selectedPlayers.length === 0 ? (
              <div className="text-sm text-gray-500 py-2">
                请选择至少 {MIN_SELECTED} 名球员进行对比
              </div>
            ) : (
              selectedPlayers.map((player) => (
                <SelectedPlayerCard
                  key={player.id}
                  player={player}
                  onRemove={removePlayer}
                />
              ))
            )}
          </div>
          <div className="flex-shrink-0 flex flex-col items-stretch gap-1.5">
            <div className="flex items-center gap-1.5">
              <div className="flex items-center gap-1 px-1.5 py-1 rounded-md bg-white/5 border border-white/10">
                <Users className="h-3 w-3 text-cyan-400" />
                <span className={`text-[10px] font-bold leading-none ${selectedIds.length >= MIN_SELECTED ? 'text-cyan-400' : 'text-gray-400'}`}>
                  {selectedIds.length}/{MAX_SELECTED}
                </span>
              </div>
              <Button
                variant="ghost"
                size="icon"
                onClick={() => navigate(-1)}
                className="text-gray-400 hover:text-white h-7 w-7 bg-white/5 border border-white/10"
              >
                <ArrowLeft className="h-3.5 w-3.5" />
              </Button>
            </div>
            <Button
              onClick={handleStartCompare}
              disabled={!canCompare}
              className="bg-gradient-to-r from-cyan-500 to-blue-500 text-white border-0 hover:from-cyan-400 hover:to-blue-400 shadow-[0_0_12px_rgba(0_229_255_0.3)] text-base h-10 px-5 w-full font-bold"
            >
              开始对比
            </Button>
          </div>
        </div>
      </div>

      <div className="px-3 py-2 lg:max-w-[1280px] lg:mx-auto">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-500" />
          <Input
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            placeholder="搜索球员姓名..."
            className="pl-9 bg-[#141838] border-white/10 text-white placeholder:text-gray-500 focus-visible:border-cyan-400/50"
          />
        </div>
      </div>

      <div className="px-3 pb-6 lg:max-w-[1280px] lg:mx-auto">
        {loading ? (
          <div className="text-center py-12 text-gray-400">加载中...</div>
        ) : allPlayers.length === 0 ? (
          <div className="text-center py-12 text-gray-500">
            {isSameNameMode || debouncedKeyword ? '暂无球员数据' : <span className="text-3xl font-semibold">输入球员姓名开始搜索</span>}
          </div>
        ) : (
          <div className={gridCls} data-ai-section-type="card-list">
            {allPlayers.map((player) => {
              const isSelected = selectedIds.includes(player.id);
              const isDisabled = isFull && !isSelected;
              return (
                <div
                  key={player.id}
                  className={[
                    'relative transition-all duration-200',
                    isSelected
                      ? 'ring-2 ring-cyan-400/70 rounded-xl shadow-[0_0_15px_rgba(0_229_255_0.4)]'
                      : '',
                    isDisabled
                      ? 'opacity-40 pointer-events-none'
                      : '',
                  ].join(' ')}
                >
                  {isSelected && (
                    <div className="absolute right-1.5 top-1.5 z-10 flex h-5 w-5 items-center justify-center rounded-full bg-cyan-500 shadow-[0_0_8px_rgba(0_229_255_0.6)] border border-cyan-300/50">
                      <Check className="h-3 w-3 text-white" />
                    </div>
                  )}
                  <PlayerCard
                    player={player}
                    onClick={() => !isDisabled && togglePlayer(player.id)}
                    overlay={false}
                  />
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

const PlayerCompareSelectPage: React.FC = () => (
  <CompareSelectErrorBoundary>
    <PlayerCompareSelectPageInner />
  </CompareSelectErrorBoundary>
);

export default PlayerCompareSelectPage;
