import React, { useCallback, useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { useNavigate, useParams } from 'react-router-dom';
import {
  Save,
  Share2,
  Trash2,
  Loader2,
  FilePlus2,
  List,
  Download,
} from 'lucide-react';
import { toast } from 'sonner';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { showConfirm } from '@lark-apaas/client-toolkit';
import { useLoginGuard } from '@client/src/hooks/useLoginGuard';
import {
  visitorLocalListDocs,
  visitorLocalGetDoc,
  visitorLocalUpsertDoc,
  visitorLocalRemoveDoc,
  visitorLocalDocId,
  toastVisitorLocal,
} from '@client/src/utils/visitor-mode';
import { useIsNativeApp } from '@client/src/hooks/use-native-app';
import { useAuth } from '@client/src/context/AuthContext';
import type { MediaItem } from '@client/src/api/forum';
import { uploadMediaItem } from '@client/src/api/media-upload';
import ShareToForumDialog from '@client/src/components/ShareToForumDialog';
import PlayerPoolPanel, {
  type PoolPlayer,
  type PoolCardPointerHandlers,
} from '@client/src/components/PlayerPoolPanel';
import TierPlayerCard from '@client/src/pages/tier-list/TierPlayerCard';
import {
  saveLineup,
  getMyLineups,
  getLineup,
  deleteLineup,
  type LineupItemSnapshot,
  type LineupSummary,
} from '@client/src/api/lineups';
import { renderLineupCanvas } from '@client/src/utils/lineup-image';
import { saveOrShareImage } from '@client/src/utils/native-image';
import { LOCAL_ASSETS } from '@client/src/utils/local-assets';
import BrandWatermark from '@client/src/components/BrandWatermark';
import VisitorModeBanner from '@client/src/components/VisitorModeBanner';
import { useI18n } from '@client/src/i18n/I18nProvider';

// 游客本机阵容文档结构（localStorage 持久化，与云端隔离）
interface LocalLineupDoc {
  id: string;
  name: string;
  items: LineupItemSnapshot[];
  userId: string;
  createdAt: string;
  updatedAt: string;
}

const ARMED = { current: false };

interface DragSession {
  item: LineupItemSnapshot;
  fromPitch: boolean;
  pointerId: number;
  startX: number;
  startY: number;
  armed: boolean;
  timer: ReturnType<typeof setTimeout> | null;
  touch: boolean;
  el: HTMLElement | null;
}

const MyLineup: React.FC = () => {
  const navigate = useNavigate();
  const { t } = useI18n();
  const { user, requireLogin, allowLocalAction } = useLoginGuard();
  const { getAuthHeaders } = useAuth();
  const { id: routeId } = useParams<{ id: string }>();

  // 是否运行在原生 APP 壳内：入阵卡缩小时，APP 端不再额外显示中文名
  const isNative = useIsNativeApp();

  const [lineupId, setLineupId] = useState<string | null>(null);
  const [lineupName, setLineupName] = useState(t('我的阵容'));
  const [items, setItems] = useState<LineupItemSnapshot[]>([]);
  const [readOnly, setReadOnly] = useState(false);
  const [ownerLoaded, setOwnerLoaded] = useState(false);

  const [myLineups, setMyLineups] = useState<LineupSummary[]>([]);
  const [showMy, setShowMy] = useState(false);

  const [saving, setSaving] = useState(false);
  const [sharing, setSharing] = useState(false);
  const [shareOpen, setShareOpen] = useState(false);
  const [overPitch, setOverPitch] = useState(false);
  const [ghost, setGhost] = useState<{
    x: number;
    y: number;
    item: LineupItemSnapshot;
  } | null>(null);
  const dragSession = useRef<DragSession | null>(null);
  const pitchRef = useRef<HTMLDivElement | null>(null);

  // ---------- 拖拽到屏幕边缘：页面自动上/下滚动（长榜单也能把卡牌送到远端）----------
  const EDGE_ZONE = 96;
  const edgeRaf = useRef<number | null>(null);
  const edgeY = useRef<number | null>(null);
  const edgeTick = () => {
    const y = edgeY.current;
    if (y === null) {
      edgeRaf.current = null;
      return;
    }
    let dy = 0;
    if (y < EDGE_ZONE) dy = (y - EDGE_ZONE) / EDGE_ZONE;
    else if (y > window.innerHeight - EDGE_ZONE)
      dy = (y - (window.innerHeight - EDGE_ZONE)) / EDGE_ZONE;
    dy = Math.max(-1, Math.min(1, dy));
    if (dy !== 0) window.scrollBy(0, dy * 20);
    edgeRaf.current = requestAnimationFrame(edgeTick);
  };
  const edgeEnsure = (y: number) => {
    edgeY.current = y;
    if (edgeRaf.current === null) edgeRaf.current = requestAnimationFrame(edgeTick);
  };
  const edgeStop = () => {
    edgeY.current = null;
    if (edgeRaf.current !== null) {
      cancelAnimationFrame(edgeRaf.current);
      edgeRaf.current = null;
    }
  };
  useEffect(() => () => edgeStop(), []);

  const addedIds = new Set(items.map((i) => i.playerId));

  // 载入指定阵容
  useEffect(() => {
    if (!routeId) return;

    // 游客本机文档（local_ 前缀）：直接读 localStorage，不请求云端，且可编辑
    if (routeId.startsWith('local_')) {
      const rec = visitorLocalGetDoc<LocalLineupDoc>('lineup', routeId);
      if (!rec) {
        toast.error(t('阵容不存在或已被删除'));
      } else {
        setLineupId(rec.id);
        setLineupName(rec.name);
        setItems(rec.items ?? []);
        setReadOnly(false);
        setOwnerLoaded(true);
      }
      return;
    }

    let cancelled = false;
    getLineup(routeId)
      .then((rec) => {
        if (cancelled) return;
        setLineupId(rec.id);
        setLineupName(rec.name);
        setItems(rec.items ?? []);
        setReadOnly(!user || rec.userId !== user.id);
        setOwnerLoaded(true);
      })
      .catch((e) => {
        logger.error('载入阵容失败', e);
        toast.error(t('阵容不存在或已被删除'));
      });
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [routeId]);

  const refreshMyLineups = useCallback(() => {
    // 已登录：云端「我的阵容」；游客：本机 localStorage 文档
    if (user) {
      getMyLineups(getAuthHeaders())
        .then((r) => setMyLineups(r.items))
        .catch(() => undefined);
      return;
    }
    const docs = visitorLocalListDocs<LocalLineupDoc>('lineup');
    setMyLineups(
      docs.map((d) => ({
        id: d.id,
        name: d.name,
        itemCount: (d.items ?? []).length,
        updatedAt: d.updatedAt ?? '',
      })),
    );
  }, [user, getAuthHeaders]);

  useEffect(() => {
    refreshMyLineups();
  }, [refreshMyLineups]);

  const startNew = () => {
    setLineupId(null);
    setLineupName(t('我的阵容'));
    setItems([]);
    setReadOnly(false);
    navigate('/lineup');
  };

  const handleDeleteList = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    // 游客：删除本机文档（开关关时 allowLocalAction 会提示登录并跳转）
    if (!user) {
      if (!allowLocalAction(t('删除阵容'))) return;
      const ok = await showConfirm(t('确定删除这个阵容吗？此操作不可恢复。'));
      if (!ok) return;
      visitorLocalRemoveDoc('lineup', id);
      setMyLineups((prev) => prev.filter((m) => m.id !== id));
      if (lineupId === id) startNew();
      toast.success(t('已删除阵容'));
      return;
    }
    if (!requireLogin(t('删除阵容'))) return;
    const ok = await showConfirm(t('确定删除这个阵容吗？此操作不可恢复。'));
    if (!ok) return;
    try {
      await deleteLineup(id, getAuthHeaders());
      setMyLineups((prev) => prev.filter((m) => m.id !== id));
      if (lineupId === id) startNew();
      toast.success(t('已删除阵容'));
    } catch (err) {
      logger.error('删除阵容失败', err);
      toast.error(t('删除失败，请稍后重试'));
    }
  };

  // 由指针坐标换算球场归一化坐标；不在球场上则返回 null
  const pointOnPitch = (
    clientX: number,
    clientY: number,
  ): { x: number; y: number } | null => {
    const el = pitchRef.current;
    if (!el) return null;
    const r = el.getBoundingClientRect();
    if (
      clientX < r.left ||
      clientX > r.right ||
      clientY < r.top ||
      clientY > r.bottom
    ) {
      return null;
    }
    const x = Math.min(1, Math.max(0, (clientX - r.left) / r.width));
    const y = Math.min(1, Math.max(0, (clientY - r.top) / r.height));
    return { x, y };
  };

  const upsertItem = useCallback(
    (item: LineupItemSnapshot, x: number, y: number) => {
      setItems((prev) => {
        const rest = prev.filter((i) => i.playerId !== item.playerId);
        return [...rest, { ...item, x, y }];
      });
    },
    [],
  );

  const removeItem = useCallback((playerId: string) => {
    setItems((prev) => prev.filter((i) => i.playerId !== playerId));
  }, []);

  // ---------- 指针拖拽 ----------
  const arm = (s: DragSession, x: number, y: number) => {
    s.armed = true;
    ARMED.current = true;
    // 抓起瞬间锁定源卡 touch-action:none，保证全方向跟指、不被纵向滚动抢走
    try {
      s.el?.style.setProperty('touch-action', 'none');
    } catch {
      /* ignore */
    }
    try {
      navigator.vibrate?.(15);
    } catch {
      /* ignore */
    }
    setGhost({ x, y, item: s.item });
  };

  const onCardDown = (
    e: React.PointerEvent,
    item: LineupItemSnapshot,
    fromPitch: boolean,
  ) => {
    if (readOnly) return;
    if ((e.target as HTMLElement).closest('button')) return;
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    try {
      (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    } catch {
      /* ignore */
    }
    const touch = e.pointerType === 'touch';
    const s: DragSession = {
      item,
      fromPitch,
      pointerId: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      armed: false,
      timer: null,
      touch,
      el: e.currentTarget as HTMLElement,
    };
    if (touch) {
      // 长按 150ms 抓起（有震动），抓起后全方向跟指；长按期间移动则交给滚动
      s.timer = setTimeout(() => arm(s, s.startX, s.startY), 150);
    }
    dragSession.current = s;
  };

  const onCardMove = (e: React.PointerEvent) => {
    const s = dragSession.current;
    if (!s) return;
    const dx = e.clientX - s.startX;
    const dy = e.clientY - s.startY;
    if (!s.armed) {
      if (s.touch) {
        if (Math.abs(dx) > 10 || Math.abs(dy) > 10) {
          if (s.timer) clearTimeout(s.timer);
          dragSession.current = null;
        }
        return;
      }
      if (Math.hypot(dx, dy) > 5) arm(s, e.clientX, e.clientY);
      return;
    }
    e.preventDefault();
    setGhost({ x: e.clientX, y: e.clientY, item: s.item });
    edgeEnsure(e.clientY);
    setOverPitch(pointOnPitch(e.clientX, e.clientY) !== null);
  };

  const onCardUp = (e: React.PointerEvent) => {
    const s = dragSession.current;
    if (!s) return;
    if (s.timer) clearTimeout(s.timer);
    try {
      s.el?.style.removeProperty('touch-action');
    } catch {
      /* ignore */
    }
    if (s.armed) {
      const p = pointOnPitch(e.clientX, e.clientY);
      if (p) {
        upsertItem(s.item, p.x, p.y);
      }
      // 落在球场外：保持原位，不删除（用 X 移除）
    }
    edgeStop();
    dragSession.current = null;
    ARMED.current = false;
    setGhost(null);
    setOverPitch(false);
  };

  const bindTouch = (el: HTMLElement | null) => {
    if (el && !(el as any).__ptsBound) {
      el.addEventListener(
        'touchmove',
        (ev) => {
          if (ARMED.current) ev.preventDefault();
        },
        { passive: false },
      );
      (el as any).__ptsBound = true;
    }
  };

  const dragHandlers = (
    item: LineupItemSnapshot,
    fromPitch: boolean,
  ): PoolCardPointerHandlers => ({
    ref: bindTouch,
    onPointerDown: (e: React.PointerEvent) => onCardDown(e, item, fromPitch),
    onPointerMove: onCardMove,
    onPointerUp: onCardUp,
    onPointerCancel: onCardUp,
  });

  const buildPayload = () => ({
    name: lineupName.trim() || t('我的阵容'),
    items,
  });

  const handleSave = async () => {
    // 游客：仅本机 localStorage 保存，不发任何云端请求
    if (!user) {
      if (!allowLocalAction(t('保存阵容'))) return;
      setSaving(true);
      try {
        const id = lineupId ?? visitorLocalDocId();
        const existing = lineupId
          ? visitorLocalGetDoc<LocalLineupDoc>('lineup', lineupId)
          : null;
        const now = new Date().toISOString();
        visitorLocalUpsertDoc<LocalLineupDoc>('lineup', {
          id,
          ...buildPayload(),
          userId: '',
          createdAt: existing?.createdAt ?? now,
          updatedAt: now,
        });
        setLineupId(id);
        toast.success(t('阵容已保存'));
        toastVisitorLocal('lineup');
        refreshMyLineups();
      } finally {
        setSaving(false);
      }
      return;
    }
    setSaving(true);
    try {
      const r = await saveLineup(buildPayload(), lineupId, getAuthHeaders());
      setLineupId(r.id);
      toast.success(t('阵容已保存'));
      refreshMyLineups();
    } catch (e: any) {
      const msg =
        e?.response?.data?.error?.message || e?.message || t('保存失败，请稍后重试');
      toast.error(msg);
    } finally {
      setSaving(false);
    }
  };

  const handleDownloadImage = async () => {
    try {
      const canvas = await renderLineupCanvas(buildPayload());
      await saveOrShareImage(canvas.toDataURL('image/png'), `${lineupName || t('阵容')}.png`);
    } catch {
      toast.error(t('生成图片失败，请稍后重试'));
    }
  };

  const handleShare = async () => {
    if (!requireLogin(t('分享阵容'))) return;
    setSharing(true);
    try {
      if (!lineupId) {
        const r = await saveLineup(buildPayload(), null, getAuthHeaders());
        setLineupId(r.id);
        refreshMyLineups();
      }
      setShareOpen(true);
    } catch (e: any) {
      const msg =
        e?.response?.data?.error?.message || e?.message || t('保存阵容失败');
      toast.error(msg);
    } finally {
      setSharing(false);
    }
  };

  const buildShareMedia = async (): Promise<MediaItem[] | undefined> => {
    try {
      const canvas = await renderLineupCanvas(buildPayload());
      const blob: Blob = await new Promise((resolve, reject) =>
        canvas.toBlob((b) => (b ? resolve(b) : reject(new Error('toBlob failed'))), 'image/png'),
      );
      const file = new File([blob], `${lineupName || t('阵容')}.png`, { type: 'image/png' });
      const media = await uploadMediaItem(file);
      return [{ url: media.url, type: 'image', filename: media.filename, size: media.size }];
    } catch (e) {
      logger.error('生成分享图失败', e);
      toast.error(t('生成分享图失败，请稍后重试'));
      return undefined;
    }
  };

  return (
    <div className="tier-scope px-3 py-3 sm:px-5">
      {readOnly && ownerLoaded && (
        <div className="mb-3 flex flex-wrap items-center justify-between gap-2 rounded-xl border border-sky-400/30 bg-sky-500/10 px-4 py-2.5">
          <span className="text-sm text-sky-100">{t('你正在查看他人分享的阵容')}</span>
          <button
            type="button"
            onClick={startNew}
            className="rounded-lg bg-sky-500 px-3 py-1.5 text-sm font-bold text-white hover:bg-sky-400"
          >
            {t('我也要排一个')}
          </button>
        </div>
      )}

      {/* 标题与操作 */}
      <div className="mb-3 flex flex-wrap items-center gap-2 sm:gap-1.5">
        <input
          value={lineupName}
          onChange={(e) => setLineupName(e.target.value)}
          disabled={readOnly}
          className="min-w-0 w-28 flex-none rounded-lg border border-white/15 bg-white/5 px-3 py-2 text-base font-bold text-white outline-none focus:border-sky-400 disabled:opacity-80 sm:w-auto sm:flex-1 sm:py-1.5 sm:text-xl"
          placeholder={t('给阵容起个名字')}
        />
        <div className="flex items-center gap-2 sm:gap-1.5">
          <button
            type="button"
            onClick={() => setShowMy((v) => !v)}
            className="flex h-11 w-11 items-center justify-center rounded-lg border border-white/15 bg-white/5 text-white hover:bg-white/10 sm:h-9 sm:w-9"
            aria-label={t('我的阵容')}
          >
            <List className="h-6 w-6 sm:h-[18px] sm:w-[18px]" />
          </button>
          {!readOnly && (
            <button
              type="button"
              onClick={startNew}
              className="flex h-11 w-11 items-center justify-center rounded-lg border border-white/15 bg-white/5 text-white hover:bg-white/10 sm:h-9 sm:w-9"
              aria-label={t('新建阵容')}
            >
              <FilePlus2 className="h-6 w-6 sm:h-[18px] sm:w-[18px]" />
            </button>
          )}
          {/* 图片下载按钮（全平台）：导出带水印的阵容图 */}
          <button
            type="button"
            onClick={handleDownloadImage}
            className="flex h-11 w-11 items-center justify-center rounded-lg border border-white/15 bg-white/5 text-white hover:bg-white/10 sm:h-9 sm:w-9"
            aria-label={t('下载阵容图片')}
            title={t('下载阵容图片')}
          >
            <Download className="h-6 w-6 sm:h-[18px] sm:w-[18px]" />
          </button>
          {!readOnly && (
            <button
              type="button"
              onClick={handleSave}
              disabled={saving}
              className="flex h-11 items-center gap-1.5 rounded-lg bg-blue-600 px-4 text-base font-bold text-white hover:bg-blue-500 disabled:opacity-60 sm:h-9 sm:px-3 sm:text-sm"
            >
              {saving ? <Loader2 className="h-5 w-5 animate-spin sm:h-4 sm:w-4" /> : <Save className="h-5 w-5 sm:h-4 sm:w-4" />}
              {t('保存')}
            </button>
          )}
          {!readOnly && (
            <button
              type="button"
              onClick={handleShare}
              disabled={sharing}
              className="flex h-11 items-center gap-1.5 rounded-lg bg-gradient-to-r from-sky-500 to-blue-600 px-4 text-base font-bold text-white hover:opacity-90 disabled:opacity-60 sm:h-9 sm:px-3 sm:text-sm"
            >
              {sharing ? <Loader2 className="h-5 w-5 animate-spin sm:h-4 sm:w-4" /> : <Share2 className="h-5 w-5 sm:h-4 sm:w-4" />}
              {t('分享论坛')}
            </button>
          )}
        </div>
      </div>

      {!user && <VisitorModeBanner className="mb-3" />}

      {showMy && (
        <div className="mb-3 rounded-xl border border-white/10 bg-white/5 p-3">
          <p className="mb-2 text-sm font-bold text-white">{t('我保存的阵容')}</p>
          {myLineups.length === 0 ? (
            <p className="text-sm text-white/50">{t('还没有保存过阵容')}</p>
          ) : (
            <div className="flex flex-wrap gap-2">
              {myLineups.map((m) => (
                <div
                  key={m.id}
                  className="group relative rounded-lg border border-white/15 bg-[#141838] hover:border-sky-400"
                >
                  <button
                    type="button"
                    onClick={() => {
                      navigate(`/lineup/${m.id}`);
                      setShowMy(false);
                    }}
                    className="px-3 py-1.5 text-sm text-white"
                  >
                    {m.name}
                    <span className="ml-1.5 text-white/40">{m.itemCount}{t('人')}</span>
                  </button>
                  <button
                    type="button"
                    aria-label={t('删除阵容')}
                    title={t('删除阵容')}
                    onClick={(e) => void handleDeleteList(m.id, e)}
                    className="absolute -right-2 -top-2 flex h-6 w-6 items-center justify-center rounded-full bg-rose-500 text-white shadow transition hover:bg-rose-400"
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* 双栏：横屏 球场左/球员池右；竖屏 球场上/球员池下 */}
      <div className="flex flex-col gap-3 lg:h-[calc(100vh-150px)] lg:flex-row lg:overflow-hidden">
        {/* —— 半场球场（常驻主视角）——
            竖屏：不限高度、不模块内滚动，球场始终完整，由页面整体滚动；
            横屏(lg)：固定 66% 宽、高度铺满，内部按需滚动。 */}
        <section className="z-20 rounded-xl border border-white/10 bg-white/[0.03] p-2 lg:max-h-none lg:w-[66%] lg:shrink-0 lg:overflow-y-auto">
          <div
            ref={pitchRef}
            data-drop-pitch
            className={`relative mx-auto aspect-square w-full overflow-hidden rounded-lg ${
              overPitch ? 'ring-4 ring-sky-300/60' : ''
            }`}
          >
            {/* 球场底图（1:1，完整显示、不裁切） */}
            <img
              src={LOCAL_ASSETS.pitchCandidates[0]}
              alt="球场"
              draggable={false}
              onError={(e) => {
                const imgEl = e.currentTarget;
                const idx = imgEl.dataset.i ? Number(imgEl.dataset.i) : 0;
                const nxt = idx + 1;
                if (nxt < LOCAL_ASSETS.pitchCandidates.length) {
                  imgEl.dataset.i = String(nxt);
                  imgEl.src = LOCAL_ASSETS.pitchCandidates[nxt];
                }
              }}
              className="pointer-events-none absolute inset-0 h-full w-full select-none object-cover"
            />

            {/* 已放置球员：竖屏入阵卡长宽较上版缩小约15%（116→99）；
                原生 APP 内卡已较小，不再叠加中文名 */}
            {items.map((item) => (
              <div
                key={item.playerId}
                className="drag-touch absolute z-10 w-[99px] -translate-x-1/2 -translate-y-1/2 sm:w-[66px]"
                style={{ left: `${item.x * 100}%`, top: `${item.y * 100}%` }}
                {...dragHandlers(item, true)}
              >
                <TierPlayerCard
                  item={item as any}
                  hideName={isNative}
                  onRemove={readOnly ? undefined : () => removeItem(item.playerId)}
                />
              </div>
            ))}

            {items.length === 0 && (
              <p className="pointer-events-none absolute inset-x-0 top-1/2 -translate-y-1/2 text-center text-sm font-bold text-white/70">
                {t('把球员拖到球场任意位置')}
              </p>
            )}

            {/* 右上角品牌水印（最上层，不拦截拖拽） */}
            <BrandWatermark position="top-right" />
          </div>
        </section>

        {/* —— 球员池（共享标准模块）—— */}
        <PlayerPoolPanel
          show={!readOnly}
          getCardHandlers={(p: PoolPlayer) =>
            dragHandlers(
              {
                playerId: p.playerId,
                nameZh: p.nameZh,
                nameEn: p.nameEn,
                position: p.position,
                playerImageUrl: p.playerImageUrl,
                x: 0,
                y: 0,
              },
              false,
            )
          }
          isAdded={(p) => addedIds.has(p.playerId)}
          hintText={t('电脑：按住球员直接拖到左侧球场；手机：长按球员后拖到上方球场，可任意摆放')}
        />
      </div>

      {/* 免责申明：移到核心编辑区之后，增大球场/球员池显示面积 */}
      <p className="mt-1 text-center text-[11px] text-white/40 sm:text-left">
        {t('卡面版权归 KONAMI 所有 · 本内容仅用于学习交流，禁止商业用途')}
      </p>

      {/* 拖拽悬浮卡 */}
      {ghost &&
        createPortal(
          <div
            className="pointer-events-none fixed z-[9999]"
            style={{
              left: ghost.x,
              top: ghost.y,
              transform: 'translate(-50%,-55%) rotate(-3deg) scale(1.08)',
            }}
          >
            <div className="w-[72px] overflow-hidden rounded-lg ring-2 ring-sky-300/80 shadow-[0_18px_42px_rgba(0,0,0,0.65)]">
              <TierPlayerCard item={ghost.item as any} />
            </div>
          </div>,
          document.body,
        )}

      <ShareToForumDialog
        open={shareOpen}
        onClose={() => setShareOpen(false)}
        defaultTitle={`${t('我的阵容｜')}${lineupName.trim() || t('快来看看')}`}
        defaultContent={t('这是我排布的球员阵容，欢迎大家讨论！')}
        buildMedia={buildShareMedia}
        onPosted={(p) => navigate(`/forum/${p.id}`)}
      />
    </div>
  );
};

export default MyLineup;
