import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { ChevronDown, ChevronUp, Zap } from 'lucide-react';
import type { HiddenAttributes } from '@shared/api.interface';
import { getFormConsistencyLabel } from '@client/src/utils/form-consistency';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';

interface HiddenAttributesProps {
  hiddenAttributes: HiddenAttributes;
  aiPlayStyle?: string;
  landscape?: boolean;
}

const attributeLabels: { key: keyof HiddenAttributes; label: string }[] = [
  { key: 'weakFootFrequency', label: 'common.weakFreq' },
  { key: 'weakFootAccuracy', label: 'common.weakAcc' },
  { key: 'formConsistency', label: 'common.form' },
  { key: 'injuryResistance', label: 'common.injury' },
];

function getLevelColor(level: number): string {
  if (level >= 4) return 'text-[#4ade80]';
  if (level >= 3) return 'text-[#fbbf24]';
  return 'text-[#f87171]';
}

// 状态波动只有 0/1/2（不稳定/标准/稳定），需单独分档；否则最高 2 会永远落入红色档
function getFormColor(level: number): string {
  if (level >= 2) return 'text-[#4ade80]'; // 稳定 → 绿
  if (level >= 1) return 'text-[#fbbf24]'; // 标准 → 琥珀
  return 'text-[#f87171]';                  // 不稳定 → 红
}

const HiddenAttributesComp: React.FC<HiddenAttributesProps> = ({ hiddenAttributes, aiPlayStyle, landscape = false }) => {
  const [open, setOpen] = useState(true);
  const { t, lang } = useI18n();
  const FORM_EN: Record<number, string> = { 0: 'Unstable', 1: 'Standard', 2: 'Stable' };
  const formLabel = (lv: number) =>
    lang === 'en' ? FORM_EN[lv] ?? getFormConsistencyLabel(lv) : getFormConsistencyLabel(lv);

  const boxes = (
    <div className={`grid grid-cols-4 ${landscape ? 'gap-1.5' : 'gap-3'}`}>
       {attributeLabels.map((attr) => {
         const attrData = hiddenAttributes?.[attr.key];
          const rawLevel = attrData?.level;
          const level = (typeof rawLevel === 'number' && Number.isFinite(rawLevel)) ? rawLevel : 0;
         return (
           <div
             key={attr.key}
             className={landscape
               ? 'rounded-lg bg-[#1a1f45]/50 border border-cyan-400/20 px-1 py-1.5 text-center'
               : 'rounded-xl bg-[#1a1f45]/50 border border-cyan-400/20 p-4 text-center'}
           >
              <p className={`font-semibold text-gray-300 ${landscape ? 'text-[11px] leading-tight' : 'text-lg md:text-base mb-2'}`}>
                <Link
                  to={{ pathname: `/encyclopedia/ability/${attr.key}` }}
                  state={{ from: window.location.pathname + window.location.search }}
                  className="hover:text-cyan-300 hover:underline underline-offset-2 transition-colors"
                  title="查看百科解释"
                >
                  {t(attr.label)}
                </Link>
              </p>
                <div className={`font-extrabold ${landscape ? 'text-base leading-tight' : 'text-2xl'} ${attr.key === 'formConsistency' ? getFormColor(level) : getLevelColor(level)}`}>
                  {attr.key === 'formConsistency' ? formLabel(level) : level}
                </div>
           </div>
         );
       })}
    </div>
  );

  const aiStyleRow = (
    (aiPlayStyle && typeof aiPlayStyle === 'string' && aiPlayStyle.trim() !== '') && (
      <div className={`flex items-center gap-2 rounded-lg bg-purple-500/10 border border-purple-400/20 ${landscape ? 'mt-2 px-2 py-1' : 'mt-3 px-3 py-2'}`}>
        <Zap className={`text-purple-400 flex-shrink-0 ${landscape ? 'w-3.5 h-3.5' : 'w-4 h-4'}`} />
        <span className="text-xs text-gray-400 whitespace-nowrap">{t('detail.aiStyle')}</span>
        <div className="flex flex-wrap gap-1 flex-1">
          {aiPlayStyle.split(',').map((s: string) => s.trim()).filter(Boolean).map((s: string) => (
            <span
              key={s}
              className={`px-2 py-0.5 font-bold rounded-md bg-purple-500/15 text-purple-300 border border-purple-400/30 ${landscape ? 'text-[11px]' : 'text-sm'}`}
            >
              {lang === 'en' ? trTerm(s) : s}
            </span>
          ))}
        </div>
      </div>
    )
  );

  if (landscape) {
    return (
      <div className="rounded-xl bg-card/80 border border-white/10 backdrop-blur px-2.5 py-2">
        <div className="flex items-center gap-2 mb-1.5">
          <span className="w-1 h-4 bg-gradient-to-b from-purple-400 to-indigo-500 rounded-full" />
          <h2 className="text-sm font-bold text-white">{t('detail.hiddenTitle')}</h2>
        </div>
        {boxes}
        {aiStyleRow}
      </div>
    );
  }

  return (
    <div className="rounded-2xl bg-card/80 border border-white/10 backdrop-blur overflow-hidden">
      <button
        onClick={() => setOpen(!open)}
        className="w-full flex items-center justify-between px-5 py-3 hover:bg-white/5 transition-colors"
      >
        <div className="flex items-center gap-2">
          <span className="w-1 h-5 bg-gradient-to-b from-purple-400 to-indigo-500 rounded-full" />
           <h2 className="text-4xl md:text-xl font-bold text-white">{t('detail.hiddenTitle')}</h2>
        </div>
        {open ? (
          <ChevronUp className="w-4 h-4 text-gray-400" />
        ) : (
          <ChevronDown className="w-4 h-4 text-gray-400" />
        )}
      </button>
      <div
        className={`transition-all duration-300 ease-in-out overflow-hidden ${
          open ? 'max-h-[500px] opacity-100' : 'max-h-0 opacity-0'
        }`}
      >
        <div className="px-5 pb-5">
          {boxes}
          {aiStyleRow}
        </div>
      </div>
    </div>
  );
};

export default HiddenAttributesComp;
