// 数据术语当前语言（由 I18nProvider 同步）。默认中文：正式页锁定中文时 trTerm 原样返回中文。
let termLang: 'zh' | 'en' = 'zh';
export function setTermLang(l: 'zh' | 'en'): void {
  termLang = l === 'en' ? 'en' : 'zh';
}

// 英文模式下把中文数据术语翻成英文；中文模式原样返回；查不到也原样返回（不报错）。
// 数据中出现的非标准中文变体 → 标准词条名（个别球员数据里技能写法与词库不一致时兜底）
const TERM_ALIAS: Record<string, string> = {
  '炮弹式头球': '炮弹头球',
  '伸腿抢截': '伸脚抢截',
  '伸腿拦截': '伸脚抢截',
};

export function trTerm(zh: string | null | undefined): string {
  if (zh == null) return '';
  const raw = String(zh);
  const s = TERM_ALIAS[raw] ?? raw;
  if (termLang !== 'en') return s;
  return SKILLS[s] ?? ST_SKILLS[s] ?? ATTACK[s] ?? DEFENSE[s] ??
    PTYPE[s] ?? PACK_LABEL[s] ?? AI_STYLE[s] ?? BOOSTERS[s] ?? STATS[s] ?? MODEL[s] ??
    BUILD_UI[s] ?? COACH[s] ?? FOOT[s] ?? NAT[s] ?? s;
}

// 国籍翻译：先按原值查；查不到再尝试去掉「共和国/联邦/王国」等全称后缀，按短名命中。
// 中文模式原样返回；去后缀后仍查不到则保留原值（不猜译）。
const NAT_FULL_SUFFIXES = ['人民共和国', '联邦共和国', '共和国', '联邦', '联合王国', '王国', '合众国'];
export function trNationality(zh: string | null | undefined): string {
  if (zh == null) return '';
  const s = String(zh).trim();
  if (!s) return '';
  if (termLang !== 'en') return s;
  if (trTerm(s) !== s) return trTerm(s);
  for (const suf of NAT_FULL_SUFFIXES) {
    if (s.endsWith(suf)) {
      const base = s.slice(0, -suf.length).trim();
      if (base && NAT[base]) return NAT[base];
    }
  }
  return s;
}

// 数组整体翻译（技能列表等）
export function trTerms(arr: string[] | null | undefined): string[] {
  return (arr ?? []).map(trTerm);
}
