import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';
import { useNavigate, useLocation } from 'react-router-dom';
import { Package, Users, ChevronRight, Calendar, Search, X } from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { getPackList } from '@client/src/api/packs';
import { getPackTypeInfo } from './pack-type-utils';
import PackCardFan from './PackCardFan';
import { useIsLandscape } from '@client/src/hooks/useIsLandscape';
import type { Pack } from '@shared/api.interface';

function parseCnDate(cnDate: string): string {
  if (!cnDate) return '0';
  // ISO 完整日期 YYYY-MM-DD（新导入包的存储格式）→ 与中文“年月日”同档，参与日期倒序
  const iso = cnDate.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (iso) {
    const [, y, m, d] = iso;
    return `2-${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
  }
  const full = cnDate.match(/(\d{4})年(\d{1,2})月(\d{1,2})日/);
  if (full) {
    const [, y, m, d] = full;
    return `2-${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
  }
  // ISO 仅到月 YYYY-MM
  const isoMonth = cnDate.match(/^(\d{4})-(\d{1,2})$/);
  if (isoMonth) {
    return `1-${isoMonth[1]}-${isoMonth[2].padStart(2, '0')}`;
  }
  const ym = cnDate.match(/(\d{4})年(\d{1,2})月/);
  if (ym) {
    const [, y, m] = ym;
    return `1-${y}-${m.padStart(2, '0')}`;
  }
  return `0-${cnDate}`;
}

// 统一日期展示：无论存的是 ISO 还是中文，一律显示“YYYY年M月D日”（仅到月则“YYYY年M月”）
function formatCnDate(cnDate: string): string {
  if (!cnDate) return '';
  let m = cnDate.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return `${m[1]}年${Number(m[2])}月${Number(m[3])}日`;
  m = cnDate.match(/(\d{4})年(\d{1,2})月(\d{1,2})日?/);
  if (m) return `${m[1]}年${Number(m[2])}月${Number(m[3])}日`;
  m = cnDate.match(/^(\d{4})-(\d{1,2})$/);
  if (m) return `${m[1]}年${Number(m[2])}月`;
  m = cnDate.match(/(\d{4})年(\d{1,2})月/);
  if (m) return `${m[1]}年${Number(m[2])}月`;
  return cnDate;
}

function extractYearMonth(cnDate: string): string {
  if (!cnDate) return '';
  const iso = cnDate.match(/^(\d{4})-(\d{1,2})(-\d{1,2})?$/);
  if (iso) return `${iso[1]}年${Number(iso[2])}月`;
  const match = cnDate.match(/(\d{4})年(\d{1,2})月/);
  if (!match) return '';
  const [, y, m] = match;
  return `${y}年${Number(m)}月`;
}

const MONTHS_EN = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const MONTHS_EN_SHORT = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

// 月份筛选标签：中文“YYYY年M月” / 英文“October 2026”
function formatMonthLabel(ym: string, lang: string): string {
  const m = ym.match(/(\d{4})年(\d{1,2})月/);
  if (!m || lang !== 'en') return ym;
  return `${MONTHS_EN[Number(m[2]) - 1]} ${m[1]}`;
}

// 卡片日期：中文“YYYY年M月D日” / 英文“Oct 1, 2026”
function formatDateDisplay(cnDate: string, lang: string): string {
  const zh = formatCnDate(cnDate);
  if (lang !== 'en') return zh;
  const full = cnDate.match(/(\d{4})-(\d{1,2})-(\d{1,2})/) || cnDate.match(/(\d{4})年(\d{1,2})月(\d{1,2})日?/);
  if (full) return `${MONTHS_EN_SHORT[Number(full[2]) - 1]} ${Number(full[3])}, ${full[1]}`;
  const mo = cnDate.match(/(\d{4})-(\d{1,2})/) || cnDate.match(/(\d{4})年(\d{1,2})月/);
  if (mo) return `${MONTHS_EN_SHORT[Number(mo[2]) - 1]} ${mo[1]}`;
  return zh;
}

function extractPackName(pack: Pack): string {
  if (pack.menuName && pack.menuName.includes('·')) {
    const parts = pack.menuName.split('·');
    return parts[parts.length - 1].trim();
  }
  return pack.packType || pack.menuName || '';
}

const SERVER_TABS: { key: 'global' | 'cn'; label: string; gradient: string }[] = [
  { key: 'global', label: 'packs.intl', gradient: 'from-cyan-500 to-blue-500' },
  { key: 'cn', label: 'packs.cn', gradient: 'from-red-500 to-rose-500' },
];

const STATE_CACHE_KEY = 'packs_list_restore_state';

interface PacksListState {
  serverTab: 'global' | 'cn';
  selectedMonth: string;
  searchKeyword: string;
  scrollY: number;
}

const PacksPage: React.FC = () => {
  const navigate = useNavigate();
  const landscape = useIsLandscape();
  const { t, lang } = useI18n();
  // 横屏：内容宽度与其他列表页一致（全宽），每行固定 2 个；竖屏沿用窄容器与响应式
  const containerCls = landscape
    ? 'mx-auto w-full pb-10 pt-6'
    : 'mx-auto w-full max-w-[820px] px-4 pb-10 pt-6';
  const gridCls = landscape
    ? 'grid grid-cols-2 gap-4'
    : 'grid grid-cols-1 gap-3 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4';
  const [packs, setPacks] = useState<Pack[]>([]);
  const [loading, setLoading] = useState(true);
  const [serverTab, setServerTab] = useState<'global' | 'cn'>('global');
  const [selectedMonth, setSelectedMonth] = useState<string>('all');
  const [searchInput, setSearchInput] = useState('');
  const [searchKeyword, setSearchKeyword] = useState('');
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const location = useLocation();
  // 导航优先：点主导航“卡包”（含已停留在本页时点该标签）产生新 location.key，
  // 退出搜索 / 月份 / 区服筛选，回到卡包默认内容
  const navKeyRef = useRef<string | null>(null);
  useEffect(() => {
    if (navKeyRef.current === null) { navKeyRef.current = location.key; return; }
    if (navKeyRef.current === location.key) return;
    navKeyRef.current = location.key;
    setServerTab('global');
    setSelectedMonth('all');
    setSearchInput('');
    setSearchKeyword('');
  }, [location.key]);
  const restoredRef = useRef(false);

  const fetchPacks = useCallback(async (server: string, keyword: string) => {
    setLoading(true);
    try {
      const res = await getPackList({
        server,
        keyword: keyword.trim() || undefined,
      });
      // 兜底：接口异常/返回非预期结构时绝不让 packs 变成 undefined（否则 packs.forEach 白屏崩溃）
      setPacks(Array.isArray(res?.items) ? res.items : []);
    } catch (error) {
      logger.error('加载卡包列表失败', error);
    } finally {
      setLoading(false);
    }
  }, []);

  const handleSearch = useCallback(() => {
    setSearchKeyword(searchInput);
  }, [searchInput]);

  const handleClearSearch = useCallback(() => {
    setSearchInput('');
    setSearchKeyword('');
  }, []);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (e.key === 'Enter') {
        handleSearch();
      }
    },
    [handleSearch],
  );

  useEffect(() => {
    fetchPacks(serverTab, searchKeyword);
  }, [serverTab, searchKeyword, fetchPacks]);

  useEffect(() => {
    if (restoredRef.current) return;
    restoredRef.current = true;
    const locState = (location as unknown as { state: { fromDetail?: boolean } | null }).state;
    if (!locState?.fromDetail) return;
    const cached = sessionStorage.getItem(STATE_CACHE_KEY);
    if (!cached) return;
    try {
      const state: PacksListState = JSON.parse(cached);
      setServerTab(state.serverTab);
      setSelectedMonth(state.selectedMonth);
      setSearchInput(state.searchKeyword);
      setSearchKeyword(state.searchKeyword);
      sessionStorage.removeItem(STATE_CACHE_KEY);
      const timer = setTimeout(() => {
        window.scrollTo(0, state.scrollY || 0);
      }, 100);
      return () => clearTimeout(timer);
    } catch {
      sessionStorage.removeItem(STATE_CACHE_KEY);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const saveStateAndNavigate = useCallback(
    (packId: string) => {
      const state: PacksListState = {
        serverTab,
        selectedMonth,
        searchKeyword,
        scrollY: window.scrollY,
      };
      sessionStorage.setItem(STATE_CACHE_KEY, JSON.stringify(state));
      navigate(`/pack/${packId}`);
    },
    [serverTab, selectedMonth, searchKeyword, navigate],
  );

  useEffect(() => {
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
    }
    debounceTimerRef.current = setTimeout(() => {
      setSelectedMonth('all');
      setSearchInput('');
      setSearchKeyword('');
    }, 0);
    return () => {
      if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    };
  }, [serverTab]);

  const monthOptions = useMemo(() => {
    const set = new Set<string>();
    packs.forEach((p: Pack) => {
      const ym = extractYearMonth(p.cnDate);
      if (ym) set.add(ym);
    });
    const arr = Array.from(set);
    arr.sort((a: string, b: string) => {
      const parse = (s: string) => {
        const m = s.match(/(\d{4})年(\d{1,2})月/);
        if (!m) return 0;
        return parseInt(m[1], 10) * 12 + parseInt(m[2], 10);
      };
      return parse(b) - parse(a);
    });
    return arr;
  }, [packs]);

  const sortedPacks = useMemo(() => {
    let list = packs;
    if (selectedMonth !== 'all') {
      list = list.filter((p: Pack) => extractYearMonth(p.cnDate) === selectedMonth);
    }
    const parsed = list.map((p: Pack) => ({
      pack: p,
      dateKey: parseCnDate(p.cnDate),
    }));
    parsed.sort((a, b) => {
      if (a.dateKey !== b.dateKey) return b.dateKey.localeCompare(a.dateKey);
      return b.pack.seq - a.pack.seq;
    });
    return parsed.map((item) => item.pack);
  }, [packs, selectedMonth]);

  const activeTab = SERVER_TABS.find((t) => t.key === serverTab)!;

  if (loading) {
    return (
      <div className="flex min-h-[400px] items-center justify-center">
        <div className="text-white/60">加载中...</div>
      </div>
    );
  }

  const showEmpty = serverTab === 'cn' && packs.length === 0;
  const showMonthEmpty = packs.length > 0 && sortedPacks.length === 0;

  return (
    <div className={containerCls}>
      <div className="mb-6 flex items-center gap-3">
        <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br from-orange-500 to-red-500 shadow-[0_0_20px_rgba(249_115_22_0.5)]">
          <Package className="h-6 w-6 text-white" />
        </div>
        <div>
          <h1 className="text-2xl font-black text-white">{t('packs.title')}</h1>
           <p className="text-sm text-white/60">
             {lang === 'en'
               ? `${packs.length} ${t(activeTab.label)} packs, newest first`
               : `共 ${packs.length} 个${t(activeTab.label)}，按日期倒序排列`}
           </p>
         </div>
       </div>

       <div className="mb-5">
         <div className="flex items-center gap-2">
           <div className="relative flex-1">
             <Search className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-white/40" />
             <input
               type="text"
               value={searchInput}
               onChange={(e) => setSearchInput(e.target.value)}
               onKeyDown={handleKeyDown}
               placeholder={t('packs.searchPlaceholder')}
               className="w-full rounded-xl border border-white/10 bg-[#141838] py-3 pl-11 pr-10 text-sm text-white placeholder:text-white/40 outline-none transition-all duration-200 focus:border-orange-400/50 focus:shadow-[0_0_0_3px_rgba(249_115_22_0.15)]"
             />
             {searchInput && (
               <button
                 onClick={handleClearSearch}
                 className="absolute right-3 top-1/2 flex h-6 w-6 -translate-y-1/2 items-center justify-center rounded-full text-white/40 transition-colors hover:bg-white/10 hover:text-white"
                 aria-label="清空搜索"
               >
                 <X className="h-4 w-4" />
               </button>
             )}
           </div>
           <button
             onClick={handleSearch}
             className="flex h-11 w-11 flex-shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-orange-500 to-red-500 text-white shadow-[0_0_14px_rgba(249_115_22_0.4)] transition-all hover:shadow-[0_0_20px_rgba(249_115_22_0.6)]"
             aria-label="搜索"
           >
             <Search className="h-5 w-5" />
           </button>
         </div>
       </div>

      <div className="mb-6 flex items-center justify-center">
        <div className="relative inline-flex items-center rounded-xl bg-[#141838] p-1 border border-white/10 shadow-inner">
          <div
            className={`absolute top-1 bottom-1 rounded-lg bg-gradient-to-r ${activeTab.gradient} shadow-[0_0_18px_rgba(249_115_22_0.4)] transition-all duration-300 ease-out`}
            style={{
              width: 'calc(50% - 4px)',
              left: serverTab === 'global' ? '4px' : 'calc(50% + 0px)',
            }}
          />
          {SERVER_TABS.map((tab) => {
            const isActive = serverTab === tab.key;
            return (
              <button
                key={tab.key}
                onClick={() => setServerTab(tab.key)}
                className={`relative z-10 px-5 py-3.5 text-2xl font-bold transition-all duration-300 rounded-lg min-w-[140px] text-center ${
                  isActive
                    ? 'text-white drop-shadow-[0_0_8px_rgba(255_255_255_0.5)]'
                    : 'text-white/50 hover:text-white/80'
                }`}
              >
                {t(tab.label)}
              </button>
            );
          })}
        </div>
      </div>

      {!showEmpty && monthOptions.length > 0 && (
        <div className="mb-5 -mx-4 px-4">
          <div className="flex items-center gap-2 overflow-x-auto pb-1 scrollbar-hide">
            <button
              onClick={() => setSelectedMonth('all')}
              className={`flex-shrink-0 flex items-center gap-1.5 px-5 h-12 rounded-full text-xl font-bold transition-all duration-200 ${
                selectedMonth === 'all'
                  ? 'bg-gradient-to-r from-orange-500 to-rose-500 text-white shadow-[0_0_14px_rgba(249_115_22_0.45)]'
                  : 'bg-white/5 text-white/60 border border-white/10 hover:bg-white/10 hover:text-white/80'
              }`}
            >
              <Calendar className="w-5 h-5" />
              {t('packs.all')}
            </button>
            {monthOptions.map((ym: string) => {
              const isActive = selectedMonth === ym;
              return (
                <button
                  key={ym}
                  onClick={() => setSelectedMonth(ym)}
                  className={`flex-shrink-0 px-5 h-12 rounded-full text-xl font-bold transition-all duration-200 ${
                    isActive
                      ? 'bg-gradient-to-r from-orange-500 to-rose-500 text-white shadow-[0_0_14px_rgba(249_115_22_0.45)]'
                      : 'bg-white/5 text-white/60 border border-white/10 hover:bg-white/10 hover:text-white/80'
                  }`}
                >
                  {formatMonthLabel(ym, lang)}
                </button>
              );
            })}
          </div>
        </div>
      )}

      {showEmpty ? (
        <div className="flex flex-col items-center justify-center py-20 rounded-xl border border-white/10 bg-white/5">
          <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-gradient-to-br from-rose-500/20 to-red-500/20 border border-rose-400/30">
            <Package className="h-8 w-8 text-rose-300" />
          </div>
          <h3 className="text-lg font-bold text-white mb-2">{t('packs.cnComingTitle')}</h3>
          <p className="text-sm text-white/50 max-w-xs text-center">
            {t('packs.cnComingDesc')}
          </p>
        </div>
      ) : showMonthEmpty ? (
        <div className="flex flex-col items-center justify-center py-16 rounded-xl border border-white/10 bg-white/5">
          <div className="mb-3 flex h-14 w-14 items-center justify-center rounded-2xl bg-gradient-to-br from-cyan-500/20 to-blue-500/20 border border-cyan-400/30">
            <Package className="h-7 w-7 text-cyan-300" />
          </div>
          <h3 className="text-base font-bold text-white mb-1">{t('packs.monthEmptyTitle')}</h3>
          <p className="text-sm text-white/50">{t('packs.monthEmptyDesc')}</p>
        </div>
      ) : (
        <div className={gridCls}>
          {sortedPacks.map((pack) => {
             const { label: typeLabel, gradient } = getPackTypeInfo(pack);
             const displayName = pack.originalName || pack.enName || pack.cnName || pack.menuName || extractPackName(pack);
             const showSubtitle = !!(pack.originalName || pack.enName) && (pack.cnName || pack.menuName) && pack.originalName !== pack.cnName && pack.originalName !== pack.menuName;
              return (
               <div
                 key={pack.id}
                  onClick={() => saveStateAndNavigate(pack.id)}
                 className="group relative cursor-pointer overflow-hidden rounded-xl border border-white/10 bg-gradient-to-br transition-all duration-200 hover:-translate-y-0.5 hover:border-orange-400/50 hover:shadow-[0_4_20px_rgba(249_115_22_0.25)]"
               >
                {landscape ? (
                  /* 横屏：左名称 · 中扇形Top5 · 右日期/人数 */
                  <div className={`relative bg-gradient-to-br ${gradient}`}>
                    <div className="absolute inset-0 bg-black/45" />
                    <div className="relative flex items-stretch gap-2 p-3">
                      <div className="w-[35%] min-w-0 flex flex-col justify-center gap-1.5">
                        <span className="self-start inline-flex items-center rounded-full bg-white/20 px-2.5 py-[2px] text-[11px] font-semibold text-white">
                          {typeLabel.split('+').map(trTerm).join('+')}
                        </span>
                        <h3 className="text-[17px] font-black text-white leading-tight line-clamp-2">
                          {displayName}
                        </h3>
                        {showSubtitle && (
                          <p className="text-[11px] text-white/55 truncate">{pack.cnName || pack.menuName}</p>
                        )}
                      </div>
                      <div className="flex-1 min-w-0 flex items-center justify-center overflow-hidden">
                        <PackCardFan cards={pack.topCards} />
                      </div>
                      <div className="shrink-0 flex flex-col items-end justify-center gap-1.5">
                        {pack.cnDate && (
                          <span className="text-[11px] font-medium text-white/60">{formatDateDisplay(pack.cnDate, lang)}</span>
                        )}
                        <span className="inline-flex items-center gap-1 text-sm font-bold text-white bg-black/25 rounded-full px-2.5 py-1">
                          <Users className="h-4 w-4" />
                          {pack.playerCount}
                        </span>
                      </div>
                    </div>
                  </div>
                ) : (
                 <div className={`relative p-4 bg-gradient-to-br ${gradient}`}>
                   <div className="absolute inset-0 bg-black/40" />
                   <div className="relative">
                     <div className="mb-2 flex items-center justify-between gap-2">
                       <div className="inline-flex items-center gap-1.5 rounded-full bg-white/20 px-3 py-1 text-base sm:text-sm md:text-xs font-semibold text-white backdrop-blur-sm">
                         {typeLabel.split('+').map(trTerm).join('+')}
                       </div>
                       {pack.cnDate && (
                         <p className="text-base sm:text-sm md:text-xs font-medium text-white/60">{formatDateDisplay(pack.cnDate, lang)}</p>
                       )}
                     </div>
                     <div className="flex items-start justify-between gap-2">
                       <div className="flex-1 min-w-0">
                         <h3 className="text-3xl sm:text-2xl md:text-xl font-black text-white leading-tight line-clamp-2">
                           {displayName}
                         </h3>
                       </div>
                       <span className="flex-shrink-0 inline-flex items-center gap-1.5 text-2xl sm:text-xl md:text-lg font-bold text-white/95 bg-black/25 rounded-full px-3.5 py-1.5 mt-0.5">
                         <Users className="h-7 w-7 sm:h-6 sm:w-6 md:h-5 md:w-5" />
                         {pack.playerCount}
                       </span>
                     </div>
                     {/* 竖屏缩小版扇形：卡面比横屏小一档，宽度自适应不溢出 */}
                     <div className="mt-1">
                       <PackCardFan cards={pack.topCards} height={150} />
                     </div>
                   </div>
                 </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default PacksPage;
