import React from 'react';
import { Newspaper, Pin } from 'lucide-react';

import type { NewsArticle } from '@shared/api.interface';

interface Props {
  article: NewsArticle;
  onOpen: (id: string) => void;
}

// 热讯卡片：封面 + 标题（博主名不在此外露，博主信息在详情页标签行最前面）。
const NewsCard: React.FC<Props> = ({ article, onOpen }) => {
  const cover = article.imageUrls[0];

  return (
    <article
      onClick={() => onOpen(article.id)}
      className="group flex cursor-pointer flex-col overflow-hidden rounded-2xl border border-white/10 bg-[#141838]/60 transition-all duration-200 hover:border-cyan-400/40 hover:bg-[#141838]/90 hover:shadow-[0_0_20px_rgba(34_211_238_0.12)]"
    >
      <div className="relative aspect-[3/4] w-full overflow-hidden bg-white/5">
        {article.isPinned && (
          <span className="absolute left-2 top-2 z-10 flex items-center gap-1 rounded-full bg-cyan-500/90 px-2 py-0.5 text-[10px] font-bold text-white shadow-lg">
            <Pin className="h-3 w-3" />
            置顶
          </span>
        )}
        {cover ? (
          <img
            src={cover}
            alt=""
            loading="lazy"
            className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-105"
          />
        ) : (
          <div className="flex h-full w-full items-center justify-center">
            <Newspaper className="h-8 w-8 text-white/20" />
          </div>
        )}
      </div>
      <div className="mt-auto portrait:p-3 landscape:p-2.5">
        <h3 className="line-clamp-2 font-semibold text-white group-hover:text-cyan-100 portrait:text-center portrait:text-2xl portrait:leading-snug landscape:text-left landscape:text-sm landscape:leading-snug">
          {article.title}
        </h3>
      </div>
    </article>
  );
};

export default NewsCard;
