function getCoachTop3Styles(
  coach: Coach,
): { key: keyof StyleProficiency; label: string; value: number }[] {
  return STYLE_LABELS.map((s) => ({
    key: s.key,
    label: s.label,
    value: coach.styleProficiency?.[s.key] ?? 0,
  }))
    .sort((a, b) => b.value - a.value)
    .slice(0, 3);
}

