function getCoachTopStyle(coach: Coach): { label: string; value: number; key: string } {
  let topKey: keyof StyleProficiency = 'possession';
  let topValue = -1;
  for (const { key, label } of STYLE_LABELS) {
    const v = coach.styleProficiency?.[key] ?? 0;
    if (v > topValue) {
      topValue = v;
      topKey = key;
    }
  }
  const topLabel = STYLE_LABELS.find((s) => s.key === topKey)?.label ?? topKey;
  return { key: topKey, label: topLabel, value: topValue };
}

// ===================== 标准教练（虚拟角色，仅前端注入）=====================
// 4 个无任何“教练能力增加值(managerBonus)”的虚拟教练，仅提供“球队风格熟练度”
// 所带来的 +1/+2/+3；六项风格熟练度全部相等（风格中立），等级分别为 87/88/89/90。
function makeStandardCoach(level: number): Coach {
  const styleProficiency: StyleProficiency = {
    possession: level,
    longBallCounter: level,
    quickCounter: level,
    longPass: level,
    wide: level,
    outWide: level,
  };
  return {
    id: `standard-coach-${level}`,
    nameZh: '标准教练',
    nameEn: 'Standard Coach',
    country: null,
    age: null,
    grade: String(level),
    type: '标准',
    fitType: '标准',
    avatarUrl: null,
    managerBonus: [],
    styleProficiency,
    linkupTactics: [],
    tacticId: null,
    tacticNameZh: null,
    efhubId: null,
    cardImageUrl: null,
  };
}
// 熟练度从高到低，便于在选择列表中靠前展示
const STANDARD_COACHES: Coach[] = [90, 89, 88, 87].map(makeStandardCoach);

function getStyleBonusThresholds(styleValue: number): {
  plus3: number;
  plus2: number;
  plus1: number;
  plus3OverCap: boolean;
} {
  // 官方规则（2026-09 校准）：裸值 ≥ 173−S → +3；裸值 ≥ 145−S → +2；其余 → +1（最低 +1，无 +0）
  const plus3 = 173 - styleValue;
  const plus2 = 145 - styleValue;
  return {
    plus3,
    plus2,
    plus1: plus2,
    plus3OverCap: false,
  };
}

function calcStyleBonus(
  value: number,
  thresholds: ReturnType<typeof getStyleBonusThresholds>,
): number {
  if (value >= thresholds.plus3) return 3;
  if (value >= thresholds.plus2) return 2;
  return 1;
}

