// 网页端：可直接输入点数的白底红字小框（失焦/回车提交，Esc 还原）
const PointsInput: React.FC<{
  value: number;
  onCommit: (n: number) => void;
  textCls: string;
  padCls: string;
}> = ({ value, onCommit, textCls, padCls }) => {
  const [text, setText] = useState(String(value));
  useEffect(() => {
    setText(String(value));
  }, [value]);
  const commit = () => {
    const n = parseInt(text, 10);
    onCommit(Number.isFinite(n) ? (n as number) : 0);
  };
  return (
    <input
      type="number"
      inputMode="numeric"
      min={0}
      value={text}
      onChange={(e) => setText(e.target.value)}
      onBlur={commit}
      onKeyDown={(e) => {
        if (e.key === 'Enter') e.currentTarget.blur();
        if (e.key === 'Escape') {
          setText(String(value));
          e.currentTarget.blur();
        }
      }}
      aria-label="直接输入本项点数"
      title="可直接输入点数"
      className={`inline-flex items-center justify-center rounded-full bg-white font-black leading-none text-red-600 shadow-[0_1px_4px_rgba(0,0,0,0.35)] tabular-nums outline-none ring-1 ring-transparent focus:ring-cyan-400 [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none ${textCls} ${padCls}`}
    />
  );
};

