import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ThumbsUp, Reply, Trash2, Flag, Ban } from 'lucide-react';
import { toast } from 'sonner';
import { blockUser, unblockUser } from '@client/src/api/blocks';
import type { CommentItem as CommentItemType } from '@shared/api.interface';
import CommentMediaDisplay from './CommentMediaDisplay';
import UserAvatar from '@client/src/components/ui/user-avatar';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';

interface CommentItemViewProps {
  item: CommentItemType;
  isReply?: boolean;
  currentUserId?: string;
  isAdmin?: boolean;
  authorAvatarUrl?: string | null;
  onLike: () => void;
  onReply: () => void;
  onDelete: () => void;
  onReport: () => void;
  formatTime: (dateStr: string) => string;
  large?: boolean;
}

const CommentItemView: React.FC<CommentItemViewProps> = ({
  item,
  isReply = false,
  currentUserId,
  isAdmin = false,
  authorAvatarUrl = null,
  onLike,
  onReply,
  onDelete,
  onReport,
  formatTime,
  large = false,
}) => {
  const navigate = useNavigate();
  const { lang } = useI18n();

  const canDelete = (): boolean => {
    if (!currentUserId) return false;
    if (isAdmin) return true;
    return item.userId === currentUserId;
  };

  // 拉黑 / 取消拉黑（能看到这条评论说明尚未拉黑，初始为 false）
  const [blocked, setBlocked] = useState(false);
  const [blockBusy, setBlockBusy] = useState(false);
  const handleToggleBlock = async () => {
    if (blockBusy || !currentUserId) return;
    setBlockBusy(true);
    try {
      if (blocked) {
        await unblockUser(item.userId);
        setBlocked(false);
        toast.success(trTerm('已取消拉黑'));
      } else {
        await blockUser(item.userId);
        setBlocked(true);
        toast.success(trTerm('已拉黑，刷新后不再显示该用户内容'));
      }
    } catch {
      toast.error(trTerm('操作失败，请重试'));
    } finally {
      setBlockBusy(false);
    }
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-1 gap-2">
        <button
          onClick={(e: React.MouseEvent) => {
            e.stopPropagation();
            navigate(`/user/${item.userId}`);
          }}
          className="flex items-center gap-1.5 min-w-0 flex-1 text-left group"
        >
            <UserAvatar
              avatarUrl={authorAvatarUrl}
              userName={item.userName}
              size={isReply ? 'xs' : 'sm'}
              className="transition-all group-hover:shadow-[0_0_8px_rgba(34_211_238_0.6)]"
            />
            <span
              className={`whitespace-nowrap font-medium text-cyan-300 transition-colors group-hover:text-cyan-200 group-hover:underline underline-offset-2 ${large ? 'text-4xl sm:text-sm' : 'text-xl sm:text-sm'}`}
             >
            {item.userName || trTerm('匿名球迷')}
          </span>
        </button>
        <span className={`text-gray-500 flex-shrink-0 ${large ? 'text-3xl sm:text-xs' : 'text-lg'}`}>
          {formatTime(item.createdAt)}
        </span>
      </div>
      {item.isDeleted ? (
              <p className={`italic text-gray-500 leading-6 sm:leading-7 break-words ${large ? 'text-4xl sm:text-sm' : isReply ? 'text-xl sm:text-sm' : 'text-2xl sm:text-sm'}`}>
            {trTerm('该评论已被删除')}
          </p>
      ) : (
        <>
         <p className={`text-gray-300 break-words ${large ? 'text-4xl leading-[3.6rem] sm:text-sm sm:leading-6' : 'text-xl leading-8 sm:text-sm sm:leading-6'}`}>
            {item.replyToUserName && (
              <span className="text-cyan-400">@{item.replyToUserName} </span>
            )}
            {item.content}
          </p>
          {item.mediaUrls && item.mediaUrls.length > 0 && (
            <div className="mt-1.5">
              <CommentMediaDisplay
                mediaList={item.mediaUrls}
                size="normal"
              />
            </div>
          )}
        </>
      )}
      {!item.isDeleted && (
        <div className="flex flex-wrap items-center gap-2 sm:gap-3 mt-1">
          <button
            onClick={onLike}
              className={`flex items-center gap-1 sm:gap-1 ${large ? 'text-2xl sm:text-xs' : 'text-lg sm:text-xs'} py-2 sm:py-1.5 transition-colors ${
                 item.likedByCurrentUser
                   ? 'text-cyan-400'
                   : 'text-gray-500 hover:text-cyan-400'
             }`}
           >
              <ThumbsUp
                className={`${large ? 'w-10 h-10 sm:w-5 sm:h-5' : 'w-4 h-4 sm:w-3.5 sm:h-3.5'} ${item.likedByCurrentUser ? 'fill-current' : ''}`}
            />
            <span>{item.likeCount}</span>
          </button>
          <button
            onClick={onReply}
             className={`flex items-center gap-1 sm:gap-1 ${large ? 'text-2xl sm:text-xs' : 'text-lg sm:text-xs'} py-2 sm:py-1.5 text-gray-500 hover:text-cyan-400 transition-colors`}
           >
             <Reply className={`${large ? 'w-10 h-10 sm:w-5 sm:h-5' : 'w-4 h-4 sm:w-3.5 sm:h-3.5'}`} />
            <span>{trTerm('回复')}</span>
          </button>
          {currentUserId && canDelete() && (
            <button
              onClick={onDelete}
               className={`flex items-center gap-1 sm:gap-1 ${large ? 'text-2xl sm:text-xs' : 'text-lg sm:text-xs'} py-2 sm:py-1.5 text-gray-500 hover:text-red-400 transition-colors`}
            >
               <Trash2 className={`${large ? 'w-10 h-10 sm:w-5 sm:h-5' : 'w-4 h-4 sm:w-3.5 sm:h-3.5'}`} />
              <span>{trTerm('删除')}</span>
            </button>
          )}
          {item.userId !== currentUserId && (
            <button
              onClick={onReport}
               className={`flex items-center gap-1 sm:gap-1 ${large ? 'text-2xl sm:text-xs' : 'text-lg sm:text-xs'} py-2 sm:py-1.5 text-gray-500 hover:text-orange-400 transition-colors`}
               title={trTerm('举报')}
             >
               <Flag className={`${large ? 'w-10 h-10 sm:w-5 sm:h-5' : 'w-4 h-4 sm:w-3.5 sm:h-3.5'}`} />
              <span>{trTerm('举报')}</span>
            </button>
          )}
          {currentUserId && item.userId !== currentUserId && (
            <button
              onClick={handleToggleBlock}
              disabled={blockBusy}
              className={`flex items-center gap-1 sm:gap-1 ${large ? 'text-2xl sm:text-xs' : 'text-lg sm:text-xs'} py-2 sm:py-1.5 transition-colors disabled:opacity-50 ${
                blocked
                  ? 'text-red-400 hover:text-red-300'
                  : 'text-gray-500 hover:text-red-400'
              }`}
              title={blocked ? trTerm('取消拉黑') : trTerm('拉黑')}
            >
              <Ban
                className={`${large ? 'w-10 h-10 sm:w-5 sm:h-5' : 'w-4 h-4 sm:w-3.5 sm:h-3.5'}`}
              />
              <span>
                {blocked ? trTerm('取消拉黑') : trTerm('拉黑')}
              </span>
            </button>
          )}
        </div>
      )}
    </div>
  );
};

export default CommentItemView;
