import React from 'react';
import { ChevronDown, ChevronUp, Swords, ShieldCheck } from 'lucide-react';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';
import {
  getOffenseStylePositions,
  getDefenseStylePositions,
} from '@client/src/utils/style-positions';

interface PositionHeatmapProps {
  allPositionOveralls: Record<string, number>;
  registeredPosition: string;
  officialOverall?: number;
  compact?: boolean;
  hideTitle?: boolean;
  collapsible?: boolean;
  defaultOpen?: boolean;
  positionProficiency?: Record<string, number>;
  offensiveStyle?: string;
  defensiveStyle?: string;
  showStyleButtons?: boolean;
  helperText?: string;
  aiStyle?: string;
  /** 覆盖进攻/防守风格按钮的字体类（APP 端放大用） */
  styleFontClass?: string;
  /** 覆盖进攻/防守风格按钮的图标类（APP 端放大用） */
  styleIconClass?: string;
  /** 当前选中的位置（点击格子联动卡面总评/位置）；默认注册位置 */
  selectedPosition?: string;
  /** 点击位置格子回调 */
  onSelectPosition?: (posKey: string) => void;
}

interface GridCell {
  key: string;
  row: number;
  col: number;
  rowSpan: number;
  colSpan: number;
  layout: 'horizontal' | 'vertical';
}

const GRID_LAYOUT: GridCell[] = [
  { key: 'LWF', row: 1, col: 1, rowSpan: 2, colSpan: 1, layout: 'vertical' },
  { key: 'CF', row: 1, col: 2, rowSpan: 1, colSpan: 1, layout: 'horizontal' },
  { key: 'RWF', row: 1, col: 3, rowSpan: 2, colSpan: 1, layout: 'vertical' },
  { key: 'SS', row: 2, col: 2, rowSpan: 1, colSpan: 1, layout: 'horizontal' },
  { key: 'LMF', row: 3, col: 1, rowSpan: 3, colSpan: 1, layout: 'vertical' },
  { key: 'AMF', row: 3, col: 2, rowSpan: 1, colSpan: 1, layout: 'horizontal' },
  { key: 'RMF', row: 3, col: 3, rowSpan: 3, colSpan: 1, layout: 'vertical' },
  { key: 'CMF', row: 4, col: 2, rowSpan: 1, colSpan: 1, layout: 'horizontal' },
  { key: 'DMF', row: 5, col: 2, rowSpan: 1, colSpan: 1, layout: 'horizontal' },
  { key: 'LB', row: 6, col: 1, rowSpan: 2, colSpan: 1, layout: 'vertical' },
  { key: 'CB', row: 6, col: 2, rowSpan: 1, colSpan: 1, layout: 'horizontal' },
  { key: 'RB', row: 6, col: 3, rowSpan: 2, colSpan: 1, layout: 'vertical' },
  { key: 'GK', row: 7, col: 2, rowSpan: 1, colSpan: 1, layout: 'horizontal' },
];

const POSITION_LABEL_MAP: Record<string, string> = {
  GK: '门将',
  LB: '左后卫',
  CB: '中后卫',
  RB: '右后卫',
  DMF: '后腰',
  LMF: '左边前卫',
  CMF: '中前卫',
  RMF: '右边前卫',
  AMF: '前腰',
  LWF: '左边锋',
  SS: '影锋',
  RWF: '右边锋',
  CF: '中锋',
};

function getProficiencyBgStyle(
  proficiency: number,
): React.CSSProperties {
  if (proficiency === 2) {
    return {
      background: 'linear-gradient(135deg, #22c55e 0%, #16a34a 100%)',
      color: '#ffffff',
      boxShadow: '0 0 10px rgba(34, 197, 94, 0.45)',
    };
  }
  if (proficiency === 1) {
    return {
      background: 'linear-gradient(135deg, #B0D4E8 0%, #8FC1D9 100%)',
      color: '#0f172a',
      boxShadow: '0 0 6px rgba(143, 193, 217, 0.3)',
    };
  }
  return {
    background: 'linear-gradient(135deg, #1e293b 0%, #334155 100%)',
    color: '#94a3b8',
    boxShadow: 'none',
  };
}

function getProficiencyLevel(
  posKey: string,
  registeredKey: string,
  positionProficiency: Record<string, number> = {},
): number {
  const level = positionProficiency[posKey];
  if (typeof level === 'number' && level === 2) return 2;
  if (typeof level === 'number' && level === 1) return 1;
  if (posKey === registeredKey) return 2;
  return 0;
}

function getRegisteredKey(labelOrKey: string): string {
  if (POSITION_LABEL_MAP[labelOrKey]) return labelOrKey;
  const entry = Object.entries(POSITION_LABEL_MAP).find(([, label]) => label === labelOrKey);
  return entry?.[0] ?? 'CF';
}

const PositionHeatmap: React.FC<PositionHeatmapProps> = ({
  allPositionOveralls,
  registeredPosition,
  officialOverall,
  compact = false,
  hideTitle = false,
  collapsible = true,
  defaultOpen = true,
  positionProficiency = {},
  offensiveStyle,
  defensiveStyle,
  showStyleButtons = false,
  helperText,
  aiStyle,
  styleFontClass,
  styleIconClass,
  selectedPosition,
  onSelectPosition,
}) => {
  const [open, setOpen] = React.useState(defaultOpen);
  const [offenseHighlight, setOffenseHighlight] = React.useState(false);
  const [defenseHighlight, setDefenseHighlight] = React.useState(false);
  const registeredKey = getRegisteredKey(registeredPosition);
  const selectedKey = selectedPosition ?? registeredKey;

  const { lang, t } = useI18n();
  // 仅风格按钮“显示文字”英文化；位置高亮判断仍用中文原值。
  const shown = (s: string) => (lang === 'en' ? trTerm(s) : s);
  const offensePositions = getOffenseStylePositions(offensiveStyle);
  const defensePositions = getDefenseStylePositions(defensiveStyle);
  const hasOffenseHighlight = offenseHighlight && offensePositions.length > 0;
  const hasDefenseHighlight = defenseHighlight && defensePositions.length > 0;

  const isHighlighted = (key: string): boolean => {
    if (hasOffenseHighlight && offensePositions.includes(key)) return true;
    if (hasDefenseHighlight && defensePositions.includes(key)) return true;
    return false;
  };

  const cells = GRID_LAYOUT.map((cell) => {
    const rawOverall = allPositionOveralls?.[cell.key];
    const overall = typeof rawOverall === 'number' && Number.isFinite(rawOverall)
      ? rawOverall
      : (typeof officialOverall === 'number' && Number.isFinite(officialOverall) ? officialOverall : 0);
    return {
      ...cell,
      overall,
      label: POSITION_LABEL_MAP[cell.key] ?? cell.key,
      isRegistered: cell.key === registeredKey,
      isSelected: cell.key === selectedKey,
      proficiency: getProficiencyLevel(cell.key, registeredKey, positionProficiency ?? {}),
      highlighted: isHighlighted(cell.key),
    };
  });

  const topOverall = Math.max(...cells.map((c) => Number.isFinite(c.overall) ? c.overall : 0), 0);

  const gridStyle: React.CSSProperties = {
    display: 'grid',
    gridTemplateColumns: '1fr 1fr 1fr',
    gridTemplateRows: 'repeat(7, minmax(0, 1fr))',
    gap: compact ? '2px' : '3px',
    height: compact ? '140px' : '200px',
  };

  const getCellStyle = (cell: typeof cells[number]): React.CSSProperties => {
    const bgStyle = getProficiencyBgStyle(cell.proficiency);
    const isHorizontal = cell.layout === 'horizontal';
    const baseStyle: React.CSSProperties = {
      ...bgStyle,
      gridRow: `${cell.row} / span ${cell.rowSpan}`,
      gridColumn: `${cell.col} / span ${cell.colSpan}`,
      borderRadius: compact ? '5px' : '8px',
      display: 'flex',
      flexDirection: isHorizontal ? 'row' : 'column',
      alignItems: 'center',
      justifyContent: 'center',
      gap: isHorizontal ? (compact ? '4px' : '6px') : (compact ? '1px' : '2px'),
      padding: compact ? '1px 3px' : '2px 4px',
      transition: 'all 0.2s ease',
      cursor: onSelectPosition ? 'pointer' : 'default',
      border: cell.isSelected
        ? `2px solid #00E5FF`
        : (cell.isRegistered
          ? `2px solid #fbbf24`
          : '1px solid rgba(255,255,255,0.08)'),
      boxShadow: cell.isSelected
        ? `0 0 12px rgba(0,229,255,0.6), 0 0 4px rgba(0,229,255,0.4)`
        : (cell.isRegistered
          ? `0 0 12px rgba(251,191,36,0.6), 0 0 4px rgba(251,191,36,0.4)`
          : bgStyle.boxShadow),
      position: 'relative',
      overflow: 'hidden',
    };
    return baseStyle;
  };

  const abbrStyle = (isHorizontal: boolean): React.CSSProperties => ({
     fontSize: compact ? '10px' : (isHorizontal ? '11px' : '12px'),
    fontWeight: 600,
    opacity: 0.85,
    lineHeight: 1,
    whiteSpace: 'nowrap',
  });

  const numStyle = (isHorizontal: boolean): React.CSSProperties => ({
     fontSize: compact ? '15px' : (isHorizontal ? '17px' : '22px'),
    fontWeight: 800,
    lineHeight: 1,
    letterSpacing: '-0.3px',
    whiteSpace: 'nowrap',
  });

  return (
    <div className={`${compact ? 'rounded-xl' : 'rounded-2xl'} bg-card/80 border border-white/10 backdrop-blur overflow-hidden`}>
      {!hideTitle && (
        <button
          onClick={() => collapsible && setOpen(!open)}
          className={`w-full flex items-center justify-between hover:bg-white/5 transition-colors ${
            compact ? 'px-2 py-1' : 'px-5 py-3'
          } ${!collapsible ? 'cursor-default hover:bg-transparent' : ''}`}
        >
          <div className="flex items-center gap-2">
            <span className={`w-1 rounded-full bg-neon-gradient ${compact ? 'h-4' : 'h-5'}`} />
             <h2 className={`font-bold text-white ${compact ? 'text-sm' : 'text-4xl md:text-xl'}`}>
               {t('detail.stylesPos')}
             </h2>
             {helperText && (
               <span className={`${compact ? 'text-[10px]' : 'text-xs'} text-gray-500 font-normal`}>
                 {helperText}
               </span>
             )}
          </div>
          {collapsible && (
            open ? (
              <ChevronUp className="w-4 h-4 text-gray-400" />
            ) : (
              <ChevronDown className="w-4 h-4 text-gray-400" />
            )
          )}
        </button>
      )}
      <div
        className={`transition-all duration-300 ease-in-out overflow-hidden ${
          open ? 'max-h-[800px] opacity-100' : 'max-h-0 opacity-0'
        }`}
      >
        <div className={`${compact ? 'p-3' : 'px-5 pb-5'}`}>
          {showStyleButtons && (
            <div className={`flex flex-wrap items-center gap-1.5 ${compact ? 'mb-2' : 'mb-3'}`}>
              {offensiveStyle && (
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    if (offensiveStyle && offensiveStyle !== '基础战术') {
                      setOffenseHighlight(!offenseHighlight);
                    }
                  }}
                  className={`flex items-center gap-1.5 rounded-md font-semibold transition-all border ${
                    compact ? `px-3 py-1.5 ${styleFontClass ?? 'text-[15px]'}` : 'px-4 py-2 text-xl'
                  } ${
                    offenseHighlight
                      ? 'bg-orange-500/30 text-orange-200 border-orange-400/60 shadow-[0_0_8px_rgba(249_115_22_0.4)]'
                      : 'bg-pink-500/10 text-pink-300 border-pink-400/30 hover:bg-pink-500/20'
                  }`}
                >
                  <Swords className={compact ? (styleIconClass ?? 'h-3.5 w-3.5') : 'h-4 w-4'} />
                  <span>{shown(offensiveStyle)}</span>
                </button>
              )}
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  if (defensiveStyle && defensiveStyle !== '基础战术') {
                    setDefenseHighlight(!defenseHighlight);
                  }
                }}
                 className={`flex items-center gap-1.5 rounded-md font-semibold transition-all border ${
                   compact ? `px-3 py-1.5 ${styleFontClass ?? 'text-[15px]'}` : 'px-4 py-2 text-xl'
                 } ${
                   defenseHighlight
                     ? 'bg-orange-500/30 text-orange-200 border-orange-400/60 shadow-[0_0_8px_rgba(249_115_22_0.4)]'
                     : 'bg-emerald-500/10 text-emerald-300 border-emerald-400/30 hover:bg-emerald-500/20'
                 }`}
               >
                 <ShieldCheck className={compact ? (styleIconClass ?? 'h-3.5 w-3.5') : 'h-4 w-4'} />
                <span>{shown(defensiveStyle || '基础战术')}</span>
              </button>
              {aiStyle && (
                <div
                  className="flex items-center gap-1 rounded-md border border-purple-400/30 bg-purple-500/10 px-2 py-1 text-[11px] font-medium text-purple-200"
                  title="AI 战术风格（COM 比赛风格）"
                >
                  <span className="rounded bg-purple-500 px-1 text-[8px] font-bold leading-tight text-white">AI</span>
                  <span>{aiStyle.split(',').map((x: string) => x.trim()).filter(Boolean).map((x: string) => shown(x)).join(',')}</span>
                </div>
              )}
            </div>
          )}
          <div style={gridStyle}>
            {cells.map((cell) => {
              const isHorizontal = cell.layout === 'horizontal';
              return (
                <div
                  key={cell.key}
                  style={getCellStyle(cell)}
                  title={`${cell.label} · 总评 ${cell.overall}`}
                  onClick={onSelectPosition ? () => onSelectPosition(cell.key) : undefined}
                >
                  {cell.highlighted && (
                    <div
                      style={{
                        position: 'absolute',
                        inset: 0,
                        backgroundColor: 'rgba(249, 115, 22, 0.8)',
                        pointerEvents: 'none',
                        zIndex: 1,
                        borderRadius: 'inherit',
                      }}
                    />
                  )}
                  <span style={{ ...abbrStyle(isHorizontal), position: 'relative', zIndex: 2 }}>
                    {cell.key}
                  </span>
                  <span style={{ ...numStyle(isHorizontal), position: 'relative', zIndex: 2 }}>
                    {cell.overall}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PositionHeatmap;
