import React, { useRef, useState } from 'react';
import { Send, Image as ImageIcon, Video as VideoIcon, X, Play, Loader2 } from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { toast } from 'sonner';
import { uploadMediaItem } from '@client/src/api/media-upload';
import type { CommentMediaItem } from '@shared/api.interface';
import { Image as UIImage } from '@client/src/components/ui/image';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';

const IMAGE_ACCEPT = '.jpg,.jpeg,.png,.gif,.webp';
const VIDEO_ACCEPT = '.mp4,.webm,.mov';

interface ReplyInputProps {
  replyToUserName?: string;
  variant?: 'inline' | 'dialog';
  onSubmit: (content: string, mediaUrls: CommentMediaItem[]) => Promise<void>;
  onCancel: () => void;
}

const ReplyInput: React.FC<ReplyInputProps> = ({
  replyToUserName,
  variant = 'inline',
  onSubmit,
  onCancel,
}) => {
  const [text, setText] = useState('');
  const [media, setMedia] = useState<CommentMediaItem[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [uploading, setUploading] = useState(false);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);
  const { lang } = useI18n();

  const imageCount = media.filter((m) => m.type === 'image').length;
  const videoCount = media.filter((m) => m.type === 'video').length;

  const handleImageClick = () => {
    if (imageCount >= 9) {
      toast.error(trTerm('最多上传 9 张图片'));
      return;
    }
    imageInputRef.current?.click();
  };

  const handleVideoClick = () => {
    if (videoCount >= 1) {
      toast.error(trTerm('最多上传 1 个视频'));
      return;
    }
    videoInputRef.current?.click();
  };

  const handleUpload = async (files: FileList, type: 'image' | 'video') => {
    const fileArray = Array.from(files);
    if (fileArray.length === 0) return;

    const maxCount = type === 'image' ? 9 : 1;
    const currentCount = media.filter((m) => m.type === type).length;
    const remaining = maxCount - currentCount;
    const maxSizeMB = type === 'image' ? 5 : 50;

    if (fileArray.length > remaining) {
      toast.error(lang === 'en'
        ? `You can upload ${remaining} more ${type === 'image' ? 'images' : 'videos'}`
        : `还可上传 ${remaining} 个${type === 'image' ? '图片' : '视频'}`);
      return;
    }
    for (const file of fileArray) {
      if (file.size > maxSizeMB * 1024 * 1024) {
        toast.error(lang === 'en'
          ? `${file.name} exceeds the ${maxSizeMB}MB limit`
          : `${file.name} 超过 ${maxSizeMB}MB 限制`);
        return;
      }
    }

    setUploading(true);
    try {
      const newItems: CommentMediaItem[] = [];
      for (const file of fileArray) {
        newItems.push(await uploadMediaItem(file));
      }
      setMedia((prev) => [...prev, ...newItems]);
      toast.success(trTerm('上传成功'));
    } catch (error) {
      logger.error('媒体上传失败', error);
      const msg = error instanceof Error ? error.message : trTerm('上传失败');
      toast.error(msg);
    } finally {
      setUploading(false);
    }
  };

  const handleRemove = (index: number) => {
    setMedia((prev) => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = async () => {
    if (!text.trim() || submitting) return;
    setSubmitting(true);
    try {
      await onSubmit(text.trim(), media);
      setText('');
      setMedia([]);
    } catch (error) {
      logger.error('提交回复失败', error);
    } finally {
      setSubmitting(false);
    }
  };

  const placeholder = replyToUserName
    ? (lang === 'en' ? `Reply @${replyToUserName}:` : `回复 @${replyToUserName}：`)
    : trTerm('说点什么...');

  if (variant === 'dialog') {
    return (
      <div className="flex flex-col h-full">
        {/* 顶部工具栏 */}
        <div className="flex items-center justify-between mb-3 shrink-0">
          <div className="flex gap-4">
            <button
              onClick={handleImageClick}
              disabled={uploading}
              className="flex items-center gap-1.5 text-sm text-gray-400 hover:text-cyan-400 transition-colors"
            >
              {uploading ? <Loader2 className="w-5 h-5 animate-spin" /> : <ImageIcon className="w-5 h-5" />}
              图片 {imageCount}/9
            </button>
            <button
              onClick={handleVideoClick}
              disabled={uploading}
              className="flex items-center gap-1.5 text-sm text-gray-400 hover:text-purple-400 transition-colors"
            >
              <VideoIcon className="w-5 h-5" />
              视频 {videoCount}/1
            </button>
          </div>
          <button
            onClick={handleSubmit}
            disabled={!text.trim() || submitting}
            className="h-9 px-4 rounded-lg bg-gradient-to-r from-cyan-400 to-cyan-600 text-white text-sm font-bold hover:opacity-90 transition-opacity disabled:opacity-40 disabled:cursor-not-allowed flex items-center justify-center gap-1.5 shadow-[0_0_12px_rgba(34_211_238_0.4)] whitespace-nowrap"
          >
            {submitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
            发送
          </button>
        </div>

        {/* 媒体预览 */}
        {media.length > 0 && (
          <div className="flex flex-wrap gap-1.5 mb-2 shrink-0">
            {media.map((item, index) => (
              <div
                key={`${item.url}-${index}`}
                className="relative overflow-hidden rounded-md border border-white/10 bg-black w-16 h-16"
              >
                {item.type === 'image' ? (
                  <UIImage src={item.url} alt={item.filename} className="h-full w-full object-cover" />
                ) : (
                  <div className="flex h-full w-full items-center justify-center bg-black/60">
                    <Play className="h-5 w-5 text-white/80" />
                  </div>
                )}
                <button
                  onClick={() => handleRemove(index)}
                  className="absolute right-0.5 top-0.5 flex h-5 w-5 items-center justify-center rounded-full bg-black/70 text-white hover:bg-red-500/80"
                  aria-label="删除"
                >
                  <X className="h-3 w-3" />
                </button>
              </div>
            ))}
          </div>
        )}

        {/* 大输入框 */}
        <div className="relative flex-1 min-h-0">
          <textarea
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder={placeholder}
            autoFocus
            className="w-full h-full min-h-[100px] sm:max-h-[50vh] px-3 py-3 rounded-lg bg-[#0A0E27] border border-white/10 text-white text-base placeholder:text-gray-600 focus:outline-none focus:border-cyan-400/70 resize-y"
            onKeyDown={(e) => {
              if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
                e.preventDefault();
                void handleSubmit();
              }
            }}
          />
          <p className="absolute bottom-2 right-3 text-xs text-gray-600 pointer-events-none">
            Ctrl + Enter 快捷发送
          </p>
        </div>

        <input
          ref={imageInputRef}
          type="file"
          accept={IMAGE_ACCEPT}
          multiple
          className="hidden"
          onChange={(e) => {
            if (e.target.files) {
              void handleUpload(e.target.files, 'image');
              e.target.value = '';
            }
          }}
        />
        <input
          ref={videoInputRef}
          type="file"
          accept={VIDEO_ACCEPT}
          className="hidden"
          onChange={(e) => {
            if (e.target.files) {
              void handleUpload(e.target.files, 'video');
              e.target.value = '';
            }
          }}
        />
      </div>
    );
  }

  return (
    <div className="mt-2 sm:mt-3 pl-3 sm:pl-4">
      <div className="flex gap-2">
        <textarea
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder={placeholder}
          autoFocus
           className="flex-1 px-3 py-2.5 sm:py-2 rounded-lg bg-[#0A0E27] border border-white/10 text-white text-[17px] sm:text-base placeholder:text-gray-600 focus:outline-none focus:border-cyan-400/70 resize-none min-h-[44px] sm:min-h-[56px]"
          onKeyDown={(e) => {
            if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
              e.preventDefault();
              void handleSubmit();
            }
          }}
        />
        <button
          onClick={handleSubmit}
          disabled={!text.trim() || submitting}
            className="px-3 sm:px-4 min-w-[80px] sm:min-w-0 rounded-lg bg-gradient-to-r from-cyan-400 to-cyan-600 text-primary-foreground text-base sm:text-sm font-bold sm:font-semibold hover:opacity-90 transition-opacity disabled:opacity-40 disabled:cursor-not-allowed flex items-center justify-center gap-1.5 sm:gap-1 h-10 sm:h-9 self-end flex-shrink-0 whitespace-nowrap"
         >
           {submitting ? <Loader2 className="w-4 h-4 sm:w-4 sm:h-4 animate-spin" /> : <Send className="w-4 h-4 sm:w-4 sm:h-4" />}
          发送
        </button>
      </div>
      <div className="flex items-center justify-between mt-2">
        <div className="flex gap-2">
          <button
            onClick={handleImageClick}
            disabled={uploading}
             className="flex items-center gap-1.5 sm:gap-1 py-2 sm:py-0 text-sm sm:text-sm text-gray-500 hover:text-cyan-400 transition-colors"
            >
             <ImageIcon className="w-4 h-4 sm:w-4 sm:h-4" /> 图片
          </button>
          <button
            onClick={handleVideoClick}
            disabled={uploading}
             className="flex items-center gap-1.5 sm:gap-1 py-2 sm:py-0 text-sm sm:text-sm text-gray-500 hover:text-purple-400 transition-colors"
            >
             <VideoIcon className="w-4 h-4 sm:w-4 sm:h-4" /> 视频
          </button>
        </div>
        <button
          onClick={onCancel}
           className="py-2 sm:py-0 text-sm sm:text-sm text-gray-500 hover:text-gray-400"
        >
          取消
        </button>
      </div>
      {media.length > 0 && (
        <div className="flex flex-wrap gap-1.5 mt-2">
          {media.map((item, index) => (
            <div
              key={`${item.url}-${index}`}
              className="relative overflow-hidden rounded-md border border-white/10 bg-black w-16 h-16"
            >
              {item.type === 'image' ? (
                <UIImage src={item.url} alt={item.filename} className="h-full w-full object-cover" />
              ) : (
                <div className="flex h-full w-full items-center justify-center bg-black/60">
                  <Play className="h-5 w-5 text-white/80" />
                </div>
              )}
              <button
                onClick={() => handleRemove(index)}
                className="absolute right-0.5 top-0.5 flex h-5 w-5 items-center justify-center rounded-full bg-black/70 text-white hover:bg-red-500/80"
                aria-label="删除"
              >
                <X className="h-3 w-3" />
              </button>
            </div>
          ))}
        </div>
      )}

      <input
        ref={imageInputRef}
        type="file"
        accept={IMAGE_ACCEPT}
        multiple
        className="hidden"
        onChange={(e) => {
          if (e.target.files) {
            void handleUpload(e.target.files, 'image');
            e.target.value = '';
          }
        }}
      />
      <input
        ref={videoInputRef}
        type="file"
        accept={VIDEO_ACCEPT}
        className="hidden"
        onChange={(e) => {
          if (e.target.files) {
            void handleUpload(e.target.files, 'video');
            e.target.value = '';
          }
        }}
      />
    </div>
  );
};

export default ReplyInput;
