import { useRef, useState, useCallback, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  MessageSquare,
  ThumbsUp,
  ThumbsDown,
  Plus,
  Loader2,
  Trash2,
  Pin,
  LogIn,
  UserSearch,
  AlertCircle,
  RefreshCw,
} from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { toast } from 'sonner';
import dayjs from 'dayjs';

import { Button } from '@client/src/components/ui/button';
import { Input } from '@client/src/components/ui/input';
import { Textarea } from '@client/src/components/ui/textarea';
import { Badge } from '@client/src/components/ui/badge';
import { useSetForumBoardBar } from '@client/src/components/Layout';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@client/src/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@client/src/components/ui/select';
import { useAuth } from '@client/src/context/AuthContext';
import UserAvatar from '@client/src/components/ui/user-avatar';
import {
  getPostList,
  createPost,
  deletePost,
  adminDeletePost,
  adminPinPost,
  type ForumPost,
  type BoardKey,
  type MediaItem,
} from '@client/src/api/forum';
import type { UserInfo } from '@shared/api.interface';
import MediaUpload from '@client/src/components/MediaUpload';
import PostMediaPreview from '@client/src/components/PostMediaPreview';
import { showConfirm } from '@lark-apaas/client-toolkit';
import FavoriteButton from '@client/src/components/FavoriteButton';
import { useInfiniteScroll } from '@client/src/hooks/useInfiniteScroll';
import InfiniteScrollFooter from '@client/src/components/InfiniteScrollFooter';
import PullToRefresh from '@client/src/components/PullToRefresh';
import { useIsMobile } from '@client/src/hooks/use-mobile';
import { useI18n } from '@client/src/i18n/I18nProvider';
import NewsFeed, { type NewsFeedHandle } from '@client/src/pages/news/NewsFeed';
import NewsHeader from '@client/src/pages/news/NewsHeader';

const PAGE_SIZE = 10;

interface BoardConfig {
  key: BoardKey;
  label: string;
  shortLabel?: string;
  emoji: string;
  theme: 'orange' | 'cyan' | 'purple';
}

// 热讯板全平台显示并置于最前（打开 /forum 默认选中，见下方 activeBoard）；
// 其后保留原讨论区各板块，用户随时可从顶部板块栏进入讨论区。
const BOARDS: BoardConfig[] = [
  { key: 'news', label: '热讯', emoji: '📰', theme: 'cyan' },
  { key: 'international', label: '国际服', emoji: '🌍', theme: 'orange' },
  { key: 'cn', label: '国服', emoji: '🇨🇳', theme: 'cyan' },
  { key: 'bug', label: '意见建议BUG反馈', shortLabel: '意见/BUG', emoji: '🐛', theme: 'purple' },
  { key: 'following', label: '关注', shortLabel: '关注', emoji: '👥', theme: 'cyan' },
];

const POST_BOARDS: BoardConfig[] = BOARDS.filter(
  (b) => b.key !== 'following' && b.key !== 'news',
);

const THEME_STYLES: Record<
  string,
  { border: string; bg: string; text: string; shadow: string }
> = {
  orange: {
    border: 'border-orange-400/80',
    bg: 'bg-[hsl(231_56%_10%_/_0.88)]',
    text: 'text-orange-100',
    shadow: 'shadow-[0_0_20px_rgba(249_115_22_0.5)]',
  },
  cyan: {
    border: 'border-cyan-400/80',
    bg: 'bg-[hsl(231_56%_10%_/_0.88)]',
    text: 'text-cyan-50',
    shadow: 'shadow-[0_0_20px_rgba(34_211_238_0.5)]',
  },
  purple: {
    border: 'border-purple-400/80',
    bg: 'bg-[hsl(231_56%_10%_/_0.88)]',
    text: 'text-purple-100',
    shadow: 'shadow-[0_0_20px_rgba(139_92_246_0.5)]',
  },
};

function getBoardConfig(key: string): BoardConfig {
  return BOARDS.find((b) => b.key === key) ?? BOARDS[0];
}

const ForumListPage: React.FC = () => {
   const navigate = useNavigate();
   const { user, getAuthHeaders } = useAuth();
   const isMobile = useIsMobile();
   const { t } = useI18n();

  const [allPosts, setAllPosts] = useState<ForumPost[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);
  // 打开 /forum 首先展示热讯瀑布；可从顶部板块栏切到讨论区各板。
  const [activeBoard, setActiveBoard] = useState<BoardKey>('news');

  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [newTitle, setNewTitle] = useState('');
  const [newContent, setNewContent] = useState('');
  const [newBoard, setNewBoard] = useState<BoardKey>('international');
  const [newMediaList, setNewMediaList] = useState<MediaItem[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const setForumBoardBar = useSetForumBoardBar();
  const boardBarRef = useRef<HTMLDivElement | null>(null);
  // 热讯板下拉刷新：直接调用 NewsFeed 暴露的 refresh（手势仍由外层 PullToRefresh 统一处理）
  const newsFeedRef = useRef<NewsFeedHandle>(null);

  const fetchPosts = useCallback(async () => {
    setLoading(true);
    setLoadError(null);
    try {
      const headers =
        activeBoard === 'following' ? getAuthHeaders() : undefined;
      const data = await getPostList(
        {
          board: activeBoard,
          page,
          pageSize: PAGE_SIZE,
        },
        headers,
        10000,
      );
      const items = Array.isArray(data?.items) ? data.items : [];
      const nextTotal = typeof data?.total === 'number' ? data.total : items.length;
      if (page === 1) {
        setAllPosts(items);
      } else {
        setAllPosts((prev) => [...prev, ...items]);
      }
      setTotal(nextTotal);
    } catch (error) {
      const msg = error instanceof Error ? error.message : '';
      if (msg.includes('timeout') || msg.includes('Timeout')) {
        setLoadError('请求超时，请检查网络后重试');
      } else {
        setLoadError('加载失败，点击重试');
      }
      logger.error('加载帖子列表失败', error);
      if (page === 1) {
        setAllPosts([]);
        setTotal(0);
      }
    } finally {
      setLoading(false);
    }
  }, [activeBoard, page, getAuthHeaders]);

  const handleRefresh = useCallback(async () => {
    // 热讯板：刷新 NewsFeed（不刷论坛帖子）
    if (activeBoard === 'news') {
      await newsFeedRef.current?.refresh();
      return;
    }
    setPage(1);
    setAllPosts([]);
    setLoadError(null);
    try {
      const headers =
        activeBoard === 'following' ? getAuthHeaders() : undefined;
      const data = await getPostList(
        {
          board: activeBoard,
          page: 1,
          pageSize: PAGE_SIZE,
        },
        headers,
        10000,
      );
      const items = Array.isArray(data?.items) ? data.items : [];
      setAllPosts(items);
      setTotal(typeof data?.total === 'number' ? data.total : items.length);
    } catch (error) {
      logger.error('下拉刷新讨论列表失败', error);
    }
  }, [activeBoard, getAuthHeaders]);

  useEffect(() => {
    fetchPosts();
  }, [fetchPosts]);

  const hasMore = (allPosts?.length ?? 0) < total;

  const { sentinelRef } = useInfiniteScroll({
    hasMore,
    loadMore: () => {
      if (hasMore && !loading) {
        setPage((p) => p + 1);
      }
    },
  });

  const handleBoardClick = useCallback((key: BoardKey) => {
    setActiveBoard(key);
    setPage(1);
    setAllPosts([]);
    setLoadError(null);
  }, []);

  const location = useLocation();
  // 导航优先：点主导航“热讯”（含已停留在本页时点该标签）产生新 location.key，回到默认热讯流
  const navKeyRef = useRef<string | null>(null);
  useEffect(() => {
    if (navKeyRef.current === null) { navKeyRef.current = location.key; return; }
    if (navKeyRef.current === location.key) return;
    navKeyRef.current = location.key;
    handleBoardClick('news');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.key]);

   const handleCreateClick = () => {
     if (!user) {
       toast.info('请先登录后发帖');
       navigate('/auth', { state: { from: window.location.pathname } });
       return;
     }
     setNewTitle('');
     setNewContent('');
     setNewMediaList([]);
     setNewBoard(
       activeBoard === 'following' ? 'international' : activeBoard,
     );
     const bar = document.querySelector('[data-board-bar="true"]');
     if (bar) {
       const rect = bar.getBoundingClientRect();
       const root = document.documentElement;
       root.style.setProperty('--board-bar-top', `${rect.top}px`);
       root.style.setProperty('--board-bar-height', `${rect.height}px`);
     }
     setShowCreateDialog(true);
   };

  useEffect(() => {
    if (!setForumBoardBar) return;
    setForumBoardBar({
      boards: BOARDS.map((b) => ({
        key: b.key,
        label: b.label,
        shortLabel: b.shortLabel,
        emoji: b.emoji,
        theme: b.theme,
      })),
      activeBoard,
      onBoardClick: handleBoardClick,
      onCreateClick: handleCreateClick,
      hideCreate: activeBoard === 'news',
      themeStyles: THEME_STYLES,
    });
    return () => setForumBoardBar(null);
  }, [setForumBoardBar, activeBoard, handleBoardClick, handleCreateClick]);

   const handleSubmitPost = async () => {
     if (!newContent.trim()) {
       toast.error('内容不能为空');
       return;
     }
     setSubmitting(true);
     try {
       const postTitle = newTitle.trim() || newContent.trim().slice(0, 30);
       await createPost(
         {
           title: postTitle,
           content: newContent.trim(),
           board: newBoard,
           mediaUrls: newMediaList.length > 0 ? newMediaList : undefined,
         },
         getAuthHeaders(),
       );
       toast.success('发布成功');
      setShowCreateDialog(false);
       setNewTitle('');
       setNewContent('');
       setPage(1);
       setAllPosts([]);
       fetchPosts();
    } catch (error: unknown) {
      const msg =
        error instanceof Error ? error.message : '发布失败，请稍后重试';
      toast.error(msg);
    } finally {
      setSubmitting(false);
    }
  };

  const handlePostClick = (id: string) => {
    navigate(`/forum/${id}`);
  };

  const isAdmin = user?.role === 'super_admin' || user?.role === 'admin';

  const canDeletePost = (post: ForumPost): boolean => {
    if (!user) return false;
    if (isAdmin) return true;
    return post.userId === user.id;
  };

  const handleDeletePost = async (postId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!user) return;
    const confirmed = await showConfirm('确定要删除这条帖子吗？此操作不可撤销。');
    if (!confirmed) return;
    try {
      if (isAdmin) {
        const reason = window.prompt('请输入删除原因（可选）：') || '';
        await adminDeletePost(postId, reason, getAuthHeaders());
      } else {
        await deletePost(postId, getAuthHeaders());
      }
      toast.success('删除成功');
       setAllPosts((prev) =>
         prev.map((p) =>
           p.id === postId ? { ...p, isDeleted: true } : p,
         ),
       );
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : '删除失败';
      toast.error(msg);
    }
  };

  // 管理员置顶 / 取消置顶（仅管理员，作者本人不可）
  const handleTogglePin = async (
    postId: string,
    pin: boolean,
    e: React.MouseEvent,
  ) => {
    e.stopPropagation();
    try {
      await adminPinPost(postId, pin, getAuthHeaders());
      toast.success(pin ? '已置顶到板块最前' : '已取消置顶');
      setAllPosts((prev) =>
        prev.map((p) =>
          p.id === postId
            ? {
                ...p,
                isPinned: pin,
                pinnedAt: pin ? new Date().toISOString() : undefined,
              }
            : p,
        ),
      );
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : '操作失败';
      toast.error(msg);
    }
  };

  return (
<>
       <div className="space-y-3 sm:space-y-3 text-white overflow-x-hidden">
         <PullToRefresh onRefresh={handleRefresh} disabled={!isMobile}>
        {/* 版块选择 + 发帖按钮（已移至Layout header，此处保留结构但隐藏） */}
        <div className="hidden">
          <div className="flex flex-1 min-w-0 gap-1.5 sm:gap-2">
            {BOARDS.map((board) => {
              const active = activeBoard === board.key;
              const style = THEME_STYLES[board.theme];
              return (
                <button
                  key={board.key}
                  onClick={() => handleBoardClick(board.key)}
                  className={`flex-1 min-w-0 flex flex-col sm:flex-row items-center justify-center gap-0.5 sm:gap-1 h-10 sm:h-12 rounded-lg sm:rounded-xl border text-xs sm:text-base font-medium transition-all duration-200 hover:-translate-y-0.5 px-1 sm:px-2 leading-tight text-center ${active ? `${style.border} ${style.bg} ${style.text} ${style.shadow}` : 'border-white/10 bg-[#141838]/80 text-white/80 hover:border-white/25'}`}
                >
                  <span className="text-sm sm:text-lg leading-none shrink-0">{board.emoji}</span>
                  <span className="sm:hidden">{t(board.shortLabel ?? board.label)}</span>
                  <span className="hidden sm:inline whitespace-nowrap">{t(board.label)}</span>
                </button>
              );
            })}
          </div>
          <Button
            onClick={handleCreateClick}
            size="icon"
            className="flex-shrink-0 h-10 w-10 sm:h-12 sm:w-auto bg-gradient-to-r from-orange-500 to-pink-500 text-sm sm:text-base shadow-[0_0_15px_rgba(249_115_22_0.5)] hover:shadow-[0_0_25px_rgba(249_115_22_0.7)] sm:px-4"
          >
            <Plus className="h-4 w-4 sm:h-5 sm:w-5 sm:mr-1" />
            <span className="hidden sm:inline">{t('forum.newPost')}</span>
          </Button>
        </div>

        {/* 资讯流（news 板由抓取 AI 发布，用户不在此发帖） */}
        {activeBoard === 'news' ? (
          <>
            <NewsHeader />
            <NewsFeed ref={newsFeedRef} />
          </>
        ) : (
        <div className="space-y-4 sm:space-y-2">
          {loading && allPosts.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 gap-3">
              <Loader2 className="h-8 w-8 animate-spin text-cyan-400" />
              <p className="text-sm text-gray-500">加载中...</p>
            </div>
          ) : loadError && allPosts.length === 0 ? (
            <div className="rounded-xl border border-white/10 bg-[#141838]/50 py-16 text-center">
              <div className="mb-4 flex justify-center">
                <AlertCircle className="h-12 w-12 text-orange-400/50" />
              </div>
              <p className="mb-2 text-base font-medium text-white/90">{loadError}</p>
              <p className="mb-4 text-sm text-gray-500">网络可能有点慢，点击下方按钮重试</p>
              <Button
                onClick={fetchPosts}
                className="bg-gradient-to-r from-cyan-500 to-purple-500 text-white shadow-[0_0_12px_rgba(34_211_238_0.5)]"
              >
                <RefreshCw className="mr-1.5 h-4 w-4" />重新加载
              </Button>
            </div>
          ) : allPosts.length === 0 ? (
            activeBoard === 'following' ? (
              <div className="rounded-xl border border-white/10 bg-[#141838]/50 py-16 text-center">
                {!user ? (
                  <>
                    <div className="mb-4 flex justify-center">
                      <LogIn className="h-12 w-12 text-cyan-400/50" />
                    </div>
                    <p className="mb-2 text-base font-medium text-white/90">
                      {t('forum.followLoginTitle')}
                    </p>
                    <p className="mb-4 text-sm text-gray-500">
                      {t('forum.followLoginDesc')}
                    </p>
                    <Button
                      onClick={() =>
                        navigate('/auth', {
                          state: { from: window.location.pathname },
                        })
                      }
                      className="bg-gradient-to-r from-cyan-500 to-purple-500 text-white shadow-[0_0_12px_rgba(34_211_238_0.5)]"
                    >
                      {t('forum.goLogin')}
                    </Button>
                  </>
                ) : (
                  <>
                    <div className="mb-4 flex justify-center">
                      <UserSearch className="h-12 w-12 text-purple-400/50" />
                    </div>
                    <p className="mb-2 text-base font-medium text-white/90">
                      {t('forum.followEmptyTitle')}
                    </p>
                    <p className="text-sm text-gray-500">
                      {t('forum.followEmptyDesc')}
                    </p>
                  </>
                )}
              </div>
            ) : (
  <div className="rounded-xl border border-white/10 bg-[#141838]/50 py-16 text-center">
                <div className="mb-4 flex justify-center">
                  <MessageSquare className="h-12 w-12 text-cyan-400/50" />
                </div>
                <p className="mb-2 text-base font-medium text-white/90">该板块暂无帖子</p>
                <p className="text-sm text-gray-500">快来抢沙发，发布第一篇吧~</p>
              </div>
            )
          ) : (
             allPosts.map((post) => {
              const boardCfg = getBoardConfig(post.board);
              const style = THEME_STYLES[boardCfg.theme];
              return (
                <div
                  key={post.id}
                  onClick={() => !post.isDeleted && handlePostClick(post.id)}
                   className={`group rounded-xl sm:rounded-xl border border-white/10 bg-[#141838]/60 p-3 sm:p-2.5 backdrop-blur-sm transition-all duration-300 ${post.isDeleted ? 'opacity-60' : 'cursor-pointer hover:-translate-y-0.5 hover:border-cyan-400/40 hover:shadow-[0_0_20px_rgba(34_211_238_0.2)]'}`}
                >
                  {post.isDeleted ? (
                    <div className="py-6 text-center">
                       <p className="text-xl text-gray-500">内容已删除</p>
                       <p className="mt-1 text-base text-gray-600">该帖子已被{post.userId === user?.id ? '您' : '管理员'}删除</p>
                    </div>
                  ) : (
                   <div className="min-w-0">
                        {post.isPinned && (
                          <div className="mb-1.5 flex items-center gap-1.5">
                            <span className="flex items-center gap-1 rounded-full bg-cyan-500/90 px-2.5 py-0.5 text-sm sm:text-[11px] font-bold text-white shadow">
                              <Pin className="h-3.5 w-3.5 sm:h-3 sm:w-3" />
                              置顶
                            </span>
                          </div>
                        )}
                        <div className="mb-1.5 sm:mb-2 flex items-start justify-between gap-2">
                          <h3 className="text-5xl sm:text-xl leading-tight sm:leading-normal font-bold text-white text-left group-hover:text-cyan-300">
                            {post.title}
                          </h3>
                          <div className="flex items-center gap-1.5 shrink-0">
                            <Badge
                              className={`${style.border} ${style.bg} ${style.text} border font-medium text-sm sm:text-sm shrink-0`}
                              variant="outline"
                            >
                              {boardCfg.emoji} {t(boardCfg.label)}
                            </Badge>
                            <FavoriteButton
                              targetType="forum_post"
                              targetId={post.id}
                              size="sm"
                            />
                            {isAdmin && (
                              <button
                                onClick={(e) =>
                                  handleTogglePin(post.id, !post.isPinned, e)
                                }
                                className={`flex items-center transition-colors ${
                                  post.isPinned
                                    ? 'text-cyan-300 hover:text-cyan-200'
                                    : 'text-gray-300 hover:text-cyan-300'
                                }`}
                                title={post.isPinned ? '取消置顶' : '置顶'}
                              >
                                <Pin
                                  className={`h-4 w-4 ${
                                    post.isPinned ? 'fill-cyan-300' : ''
                                  }`}
                                />
                              </button>
                            )}
                            {canDeletePost(post) && (
                              <button
                                onClick={(e) => handleDeletePost(post.id, e)}
                                className="flex items-center text-red-400 transition-colors hover:text-red-500"
                                title="删除帖子"
                              >
                                <Trash2 className="h-4 w-4" />
                              </button>
                            )}
                          </div>
                        </div>
                          <p
                             className="mb-3 sm:mb-3 text-4xl sm:text-lg leading-snug sm:leading-relaxed text-gray-400"
                          style={{
                           display: '-webkit-box',
                           WebkitLineClamp: 2,
                           WebkitBoxOrient: 'vertical',
                           overflow: 'hidden',
                         }}
                       >
                         {post.content}
                       </p>
                     {post.mediaUrls && post.mediaUrls.length > 0 && (
                       <div className="mb-3 sm:mb-3">
                         <PostMediaPreview mediaList={post.mediaUrls} />
                       </div>
                     )}
                        <div>
                          <button
                            onClick={(e: React.MouseEvent) => {
                              e.stopPropagation();
                              navigate(`/user/${post.userId}`);
                            }}
                            className="flex min-w-0 items-center gap-2 group"
                          >
                            <UserAvatar
                              avatarUrl={user?.id === post.userId ? user.avatarUrl : null}
                              userName={post.userName}
                              size="xl"
                            />
                            <span className="whitespace-nowrap text-4xl sm:text-base font-medium text-cyan-300 transition-colors group-hover:text-cyan-200 group-hover:underline underline-offset-2">{post.userName}</span>
                          </button>
                          <div className="mt-1.5 flex items-center gap-x-2 sm:gap-x-3 text-gray-500">
                            <span className="whitespace-nowrap text-lg sm:text-base">{dayjs(post.createdAt).format('MM-DD HH:mm')}</span>
                            <span className="ml-auto flex items-center gap-0.5 sm:gap-1 text-lg sm:text-base text-gray-400">
                              <ThumbsUp className="h-8 w-8 sm:h-6 sm:w-6" />
                              {post.likeCount}
                            </span>
                            <span className="flex items-center gap-0.5 sm:gap-1 text-lg sm:text-base text-gray-400">
                              <ThumbsDown className="h-8 w-8 sm:h-6 sm:w-6" />
                              {post.dislikeCount}
                            </span>
                            <span className="flex items-center gap-0.5 sm:gap-1 text-lg sm:text-base text-gray-400">
                              <MessageSquare className="h-8 w-8 sm:h-6 sm:w-6" />
                              {post.commentCount}
                            </span>
                          </div>
                        </div>
                   </div>
                  )}
                </div>
              );
             })
           )}
         </div>
        )}

         {/* 无限滚动加载尾部 */}
         {allPosts.length > 0 && (
           <>
             <div ref={sentinelRef} />
             <InfiniteScrollFooter
               loading={loading}
               hasMore={hasMore}
               hasItems={allPosts.length > 0}
             />
           </>
         )}

          {/* 发帖对话框 */}
          <Dialog open={showCreateDialog} onOpenChange={setShowCreateDialog}>
             <DialogContent className="fixed left-0 right-0 translate-x-0 translate-y-0 mx-auto w-full max-w-full top-[calc(var(--board-bar-top,0px)+var(--board-bar-height,0px))] max-h-[calc(100dvh-var(--board-bar-top,0px)-var(--board-bar-height,0px))] rounded-none border-white/10 bg-[#141838] text-white p-4 pt-8 overflow-y-auto sm:left-[50%] sm:right-auto sm:top-[50%] sm:translate-x-[-50%] sm:translate-y-[-50%] sm:max-w-[560px] sm:h-auto sm:max-h-[85vh] sm:rounded-2xl sm:p-6">
                <div className="flex flex-col h-full">
                {/* 顶部工具栏 */}
                <div className="flex items-center justify-between mb-3 shrink-0">
                  <div className="flex gap-4">
                    <MediaUpload
                      mediaList={newMediaList}
                      onChange={setNewMediaList}
                      maxImages={9}
                      maxVideos={1}
                      compact
                    />
                  </div>
                  <Button
                    onClick={handleSubmitPost}
                    disabled={submitting || (!newTitle.trim() && !newContent.trim())}
                    className="h-9 px-4 rounded-lg bg-gradient-to-r from-cyan-400 to-cyan-600 text-white text-sm font-bold shadow-[0_0_12px_rgba(34_211_238_0.4)] disabled:opacity-50 whitespace-nowrap"
                  >
                    {submitting && (
                      <Loader2 className="mr-1.5 h-4 w-4 animate-spin" />
                    )}
                    发布
                  </Button>
                </div>

                {/* 标题输入框 */}
                <input
                  type="text"
                  value={newTitle}
                  onChange={(e) => setNewTitle(e.target.value)}
                  placeholder="标题（可选）"
                  maxLength={50}
                  className="mb-2 w-full rounded-lg border border-white/10 bg-[#0A0E27] px-3 py-2.5 text-base font-semibold text-white placeholder:text-gray-600 focus:outline-none focus:border-cyan-400/70"
                />

                {/* 正文输入框 */}
                <div className="flex-1 min-h-0 flex flex-col">
                  <Textarea
                    value={newContent}
                    onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) =>
                      setNewContent(e.target.value)
                    }
                    onKeyDown={(e: React.KeyboardEvent<HTMLTextAreaElement>) => {
                      if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
                        e.preventDefault();
                        void handleSubmitPost();
                      }
                    }}
                    placeholder="说点什么吧..."
                    maxLength={2000}
                    className="flex-1 min-h-[100px] sm:min-h-[100px] sm:max-h-[50vh] border-cyan-400/50 bg-[#0A0E27] text-base text-white placeholder:text-gray-600 focus-visible:border-cyan-400 focus-visible:ring-1 focus-visible:ring-cyan-400/50 resize-y"
                  />
                  <div className="mt-1 shrink-0 flex items-center justify-between text-xs text-gray-600">
                    <span>Ctrl + Enter 快捷发布</span>
                    <span>{newContent.length}/2000</span>
                  </div>
                </div>
              </div>
             </DialogContent>
          </Dialog>
          </PullToRefresh>
       </div>
</>
);
};

export default ForumListPage;
