import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import { ArrowLeft, Loader2, Swords, Users, Zap, BookOpen } from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';
import { useAuth } from '@client/src/context/AuthContext';
import { useLoginGuard } from '@client/src/hooks/useLoginGuard';
import { ratings, coachTacticsApi } from '@client/src/api';
import RatingStars from '@client/src/components/RatingStars';
import CommentSection from '@client/src/components/CommentSection';
import type { CoachTactic, RatingSummary } from '@shared/api.interface';
import { toRouterPath } from '@client/src/utils/router-path';
import { useWebLandscape } from '@client/src/hooks/use-native-app';
import {
  visitorLocalGet,
  visitorLocalSet,
  toastVisitorLocal,
} from '@client/src/utils/visitor-mode';

// 网页横屏下字体缩小 2 档
const DOWN2: Record<string, string> = {
  'text-6xl': 'text-4xl',
  'text-5xl': 'text-3xl',
  'text-4xl': 'text-2xl',
  'text-3xl': 'text-xl',
  'text-2xl': 'text-base',
  'text-xl': 'text-sm',
  'text-lg': 'text-sm',
  'text-base': 'text-xs',
};

const GRADE_COLORS: Record<string, string> = {
  A: 'bg-amber-500/30 text-amber-200 border-amber-400/60',
  B: 'bg-blue-500/30 text-blue-200 border-blue-400/60',
  C: 'bg-gray-500/30 text-gray-300 border-gray-400/60',
};

const CoachTacticDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const location = useLocation();
  const { user, getAuthHeaders } = useAuth();
  const { allowLocalAction } = useLoginGuard();
  const { t, lang } = useI18n();
  const compact = useWebLandscape();
  const sc = (cls: string) => (compact ? DOWN2[cls] ?? cls : cls);

  const [tactic, setTactic] = useState<CoachTactic | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [ratingSummary, setRatingSummary] = useState<RatingSummary | null>(null);
  const [ratingLoading, setRatingLoading] = useState(false);
  // 游客本机评分（kind='rating'，key=`coach_tactic:${id}`）；已登录走云端 userScore
  const [visitorScore, setVisitorScore] = useState<number | null>(null);

  const targetType = 'coach_tactic';

  const backPath = useMemo(() => {
    const state = location.state as { from?: string } | undefined;
    if (state?.from) return state.from;
    return '/encyclopedia?tab=coach_tactics';
  }, [location.state]);

  // 返回：优先回到来源（如球员详情）；无来源时退回浏览器历史；再退回百科列表
  const handleBack = () => {
    if ((location.state as { from?: string } | undefined)?.from) {
      navigate(toRouterPath(backPath));
    } else if (window.history.length > 1) {
      navigate(-1);
    } else {
      navigate(toRouterPath(backPath));
    }
  };

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    coachTacticsApi
      .getCoachTacticDetail(id)
      .then((data) => setTactic(data))
      .catch((err: unknown) => {
        logger.error('加载战术详情失败', err);
        setError(t('detail.loadFail'));
      })
      .finally(() => setLoading(false));
  }, [id]);

  useEffect(() => {
    if (!id) return;
    ratings
      .getSummary(targetType, id)
      .then((data) => {
        setRatingSummary(data);
        // 游客：读取本机评分作为展示分（average/count 仍为服务端值）
        if (!user) {
          const local = visitorLocalGet('rating', `${targetType}:${id}`);
          setVisitorScore(local ? Number(local) : null);
        }
      })
      .catch((err: unknown) => {
        logger.error('加载评分失败', err);
      });
  }, [id, targetType, user]);

  const handleRate = async (score: number) => {
    if (!allowLocalAction('评分')) return;
    if (!id) return;
    // 游客：仅本机评分，不发云端请求
    if (!user) {
      visitorLocalSet('rating', `${targetType}:${id}`, score);
      setVisitorScore(score);
      toastVisitorLocal('rating');
      return;
    }
    setRatingLoading(true);
    try {
      const res = await ratings.submit(
        { targetType, targetId: id, score },
        getAuthHeaders(),
      );
      setRatingSummary(res);
    } catch (err) {
      logger.error('评分失败', err);
    } finally {
      setRatingLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-teal-400 animate-spin" />
      </div>
    );
  }

  if (error || !tactic) {
    return (
      <div className="flex min-h-[60vh] flex-col items-center justify-center">
        <p className={`text-gray-400 mb-4 ${sc('text-2xl')}`}>{error || t('detail.tacticNotFound')}</p>
        <button
          onClick={handleBack}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg bg-teal-500/20 border border-teal-400/50 text-teal-300 ${sc('text-xl')} hover:bg-teal-500/30 transition-colors`}
        >
          <ArrowLeft className="w-4 h-4" />
          {t('common.back')}
        </button>
      </div>
    );
  }

  return (
    <div className="min-h-screen text-white max-w-3xl mx-auto">
      <button
        onClick={handleBack}
        className={`mb-2 flex items-center gap-1.5 ${sc('text-xl')} text-gray-400 hover:text-teal-300 transition-colors`}
      >
        <ArrowLeft className="w-4 h-4" />
        {t('common.back')}
      </button>

      {/* 头部信息 */}
      <div className="relative rounded-2xl border border-teal-400/40 bg-gradient-to-br from-teal-500/10 to-cyan-600/10 p-5 mb-3 backdrop-blur-sm">
        <div className="absolute top-4 right-4 flex h-10 w-10 items-center justify-center rounded-lg bg-teal-500/20 border border-teal-400/40">
          <Swords className="w-5 h-5 text-teal-300" />
        </div>

        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <p className={`${sc('text-lg')} text-gray-400 mb-1`}>
              {t('enc.cat.coach_tactics')}
            </p>
            <h1 className={`${compact ? 'text-3xl md:text-4xl' : 'text-5xl md:text-6xl'} font-black text-white mb-1 drop-shadow-[0_0_10px_rgba(20_184_166_0.3)]`}>
              {lang === 'en' ? (tactic.nameEn || trTerm(tactic.nameZh)) : tactic.nameZh}
            </h1>
            {lang === 'zh' && tactic.nameEn && (
              <p className={`${compact ? 'text-sm md:text-base' : 'text-xl md:text-2xl'} text-gray-400`}>{tactic.nameEn}</p>
            )}
            <div className="mt-2">
              <span
                className={`${sc('text-lg')} font-bold px-2 py-0.5 rounded border ${
                  GRADE_COLORS[tactic.grade] || GRADE_COLORS.C
                }`}
              >
                {tactic.grade}{lang === 'en' ? '' : t('enc.gradeSuffix')}
              </span>
            </div>
          </div>

          <div className="flex-shrink-0">
            {ratingSummary ? (
              <div className="text-right">
                <RatingStars
                  value={
                    !user
                      ? (visitorScore ?? ratingSummary.average)
                      : (ratingSummary.userScore ?? ratingSummary.average)
                  }
                  count={ratingSummary.count}
                  interactive
                  size="lg"
                  onRate={handleRate}
                />
                 {ratingLoading && (
                   <p className="text-lg text-gray-500 mt-1">{t('detail.submitting')}</p>
                 )}
              </div>
            ) : (
              <div className="flex items-center justify-end">
                <Loader2 className="w-5 h-5 text-teal-400 animate-spin" />
              </div>
            )}
          </div>
        </div>
      </div>

      {/* 核心/关键球员 */}
      <div className="rounded-xl border border-white/10 bg-card/60 p-5 mb-3 backdrop-blur-sm space-y-4">
        <h3 className={`${sc('text-2xl')} font-semibold text-teal-300 mb-1 flex items-center gap-2`}>
          <span className="w-1 h-5 bg-gradient-to-b from-teal-400 to-cyan-500 rounded-full" />
          {t('detail.tacticConfig')}
        </h3>

        {tactic.coreStyleZh && tactic.corePosition && (
          <div className="flex items-start gap-3">
            <div className="flex h-7 w-7 items-center justify-center rounded bg-teal-500/30 flex-shrink-0">
              <Users className="h-4 w-4 text-teal-300" />
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <span className={`${sc('text-lg')} text-gray-400`}>{t('detail.corePlayer')}:</span>
                <span className={`${sc('text-xl')} font-medium text-teal-100`}>
                  {lang === 'en' ? (tactic.coreStyleEn || trTerm(tactic.coreStyleZh)) : tactic.coreStyleZh}
                </span>
                {lang === 'zh' && tactic.coreStyleEn && (
                  <span className={`${sc('text-lg')} text-teal-400/70`}>
                    {tactic.coreStyleEn}
                  </span>
                )}
              </div>
              <p className={`${sc('text-lg')} text-gray-400 mt-0.5`}>
                {t('detail.position')}: {tactic.corePosition}
              </p>
            </div>
          </div>
        )}

        {tactic.keyStyleZh && tactic.keyPosition && (
          <div className="flex items-start gap-3">
            <div className="flex h-7 w-7 items-center justify-center rounded bg-cyan-500/30 flex-shrink-0">
              <Zap className="h-4 w-4 text-cyan-300" />
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <span className={`${sc('text-lg')} text-gray-400`}>{t('detail.keyPlayer')}:</span>
                <span className={`${sc('text-xl')} font-medium text-cyan-100`}>
                  {lang === 'en' ? (tactic.keyStyleEn || trTerm(tactic.keyStyleZh)) : tactic.keyStyleZh}
                </span>
                {lang === 'zh' && tactic.keyStyleEn && (
                  <span className={`${sc('text-lg')} text-cyan-400/70`}>
                    {tactic.keyStyleEn}
                  </span>
                )}
              </div>
              <p className={`${sc('text-lg')} text-gray-400 mt-0.5`}>
                {t('detail.position')}: {tactic.keyPosition}
              </p>
            </div>
          </div>
        )}
      </div>

      {/* 战术说明 */}
      {tactic.descriptionCn && (
        <div className="rounded-xl border border-white/10 bg-card/60 p-5 mb-3 backdrop-blur-sm">
          <h3 className={`${sc('text-2xl')} font-semibold text-teal-300 mb-3 flex items-center gap-2`}>
            <span className="w-1 h-5 bg-gradient-to-b from-teal-400 to-cyan-500 rounded-full" />
            {t('detail.tacticDesc')}
          </h3>
          <p className={`${compact ? 'text-sm md:text-base' : 'text-xl md:text-2xl'} text-gray-200 leading-relaxed`}>
            {lang === 'en' ? (tactic.descriptionEn || tactic.descriptionCn) : tactic.descriptionCn}
          </p>
          {(lang === 'en' ? tactic.descriptionCn : tactic.descriptionEn) && (
            <p className={`${sc('text-lg')} text-gray-500 mt-3 leading-relaxed`}>
              {lang === 'en' ? tactic.descriptionCn : tactic.descriptionEn}
            </p>
          )}
        </div>
      )}

      {/* 备注 */}
      {tactic.remark && (
        <div className="rounded-xl border border-white/10 bg-card/60 p-5 mb-3 backdrop-blur-sm">
          <h3 className={`${sc('text-2xl')} font-semibold text-amber-300 mb-3 flex items-center gap-2`}>
            <span className="w-1 h-5 bg-gradient-to-b from-amber-400 to-orange-500 rounded-full" />
            {t('detail.remark')}
          </h3>
          <p className={`${sc('text-xl')} text-gray-200 leading-relaxed`}>
            {t(tactic.remark)}
          </p>
        </div>
      )}

      {/* 评论区 */}
      <CommentSection targetType={targetType} targetId={id!} />

      <div className="h-12" />
    </div>
  );
};

export default CoachTacticDetailPage;
