export function getProficiencyBgStyle(
  proficiency: number,
): React.CSSProperties {
  if (proficiency === 2) {
    return {
      background: 'linear-gradient(135deg, #22c55e 0%, #16a34a 100%)',
      color: '#ffffff',
      boxShadow: '0 0 10px rgba(34, 197, 94, 0.45)',
    };
  }
  if (proficiency === 1) {
    return {
      background: 'linear-gradient(135deg, #B0D4E8 0%, #8FC1D9 100%)',
      color: '#0f172a',
      boxShadow: '0 0 6px rgba(143, 193, 217, 0.3)',
    };
  }
  return {
    background: 'linear-gradient(135deg, #1e293b 0%, #334155 100%)',
    color: '#94a3b8',
    boxShadow: 'none',
  };
}

export function getProficiencyLevel(
  posKey: string,
  registeredKey: string,
  positionProficiency: Record<string, number> = {},
): number {
  const level = positionProficiency[posKey];
  if (typeof level === 'number' && level === 2) return 2;
  if (typeof level === 'number' && level === 1) return 1;
  if (posKey === registeredKey) return 2;
  return 0;
}

