import React, { useRef, useState } from 'react';
import { Image, Video, X, Loader2, Play } from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { toast } from 'sonner';

import { Button } from '@client/src/components/ui/button';
import { uploadFile, type MediaItem } from '@client/src/api/forum';
import { Image as UIImage } from '@client/src/components/ui/image';

interface MediaUploadProps {
  mediaList: MediaItem[];
  onChange: (list: MediaItem[]) => void;
  maxImages?: number;
  maxVideos?: number;
  maxImageSizeMB?: number;
  maxVideoSizeMB?: number;
  compact?: boolean;
}

const IMAGE_ACCEPT = '.jpg,.jpeg,.png,.gif,.webp';
const VIDEO_ACCEPT = '.mp4,.webm,.mov';

const MediaUpload: React.FC<MediaUploadProps> = ({
  mediaList,
  onChange,
  maxImages = 9,
  maxVideos = 1,
  maxImageSizeMB = 5,
  maxVideoSizeMB = 50,
  compact = false,
}) => {
  const imageInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);

  const imageCount = mediaList.filter((m) => m.type === 'image').length;
  const videoCount = mediaList.filter((m) => m.type === 'video').length;

  const handleImageClick = () => {
    if (imageCount >= maxImages) {
      toast.error(`最多上传 ${maxImages} 张图片`);
      return;
    }
    imageInputRef.current?.click();
  };

  const handleVideoClick = () => {
    if (videoCount >= maxVideos) {
      toast.error(`最多上传 ${maxVideos} 个视频`);
      return;
    }
    videoInputRef.current?.click();
  };

  const validateAndUpload = async (files: FileList, type: 'image' | 'video') => {
    const fileArray = Array.from(files);
    if (fileArray.length === 0) return;

    const maxSizeMB = type === 'image' ? maxImageSizeMB : maxVideoSizeMB;
    const maxCount = type === 'image' ? maxImages : maxVideos;
    const currentCount = type === 'image' ? imageCount : videoCount;
    const remaining = maxCount - currentCount;

    if (fileArray.length > remaining) {
      toast.error(`还可上传 ${remaining} 个${type === 'image' ? '图片' : '视频'}`);
      return;
    }

    for (const file of fileArray) {
      if (file.size > maxSizeMB * 1024 * 1024) {
        toast.error(`${file.name} 超过 ${maxSizeMB}MB 限制`);
        return;
      }
    }

    setUploading(true);
    try {
      const newItems: MediaItem[] = [];
      for (const file of fileArray) {
        const item = await uploadFile(file);
        newItems.push(item);
      }
      onChange([...mediaList, ...newItems]);
      toast.success('上传成功');
    } catch (error) {
      logger.error('媒体上传失败', error);
      const msg = error instanceof Error ? error.message : '上传失败';
      toast.error(msg);
    } finally {
      setUploading(false);
    }
  };

  const handleRemove = (index: number) => {
    const newList = mediaList.filter((_, i) => i !== index);
    onChange(newList);
  };

  const thumbSize = compact ? 'w-16 h-16' : 'w-20 h-20';
  const btnSize = compact ? 'h-7 px-2 text-xs' : 'h-8 px-3 text-sm';

  return (
    <div className="space-y-3">
      {/* 上传按钮 */}
      <div className="flex flex-wrap gap-2">
        <Button
          variant="outline"
          size="sm"
          onClick={handleImageClick}
          disabled={uploading || imageCount >= maxImages}
          className={`gap-1.5 border-cyan-400/30 bg-transparent text-cyan-300 transition-all hover:border-cyan-400/70 hover:bg-cyan-500/10 hover:text-cyan-200 disabled:opacity-40 ${btnSize}`}
        >
          {uploading ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <Image className="h-3.5 w-3.5" />
          )}
          图片 {imageCount}/{maxImages}
        </Button>
        <Button
          variant="outline"
          size="sm"
          onClick={handleVideoClick}
          disabled={uploading || videoCount >= maxVideos}
          className={`gap-1.5 border-purple-400/30 bg-transparent text-purple-300 transition-all hover:border-purple-400/70 hover:bg-purple-500/10 hover:text-purple-200 disabled:opacity-40 ${btnSize}`}
        >
          <Video className="h-3.5 w-3.5" />
          视频 {videoCount}/{maxVideos}
        </Button>
      </div>

      {/* 隐藏的 file input */}
      <input
        ref={imageInputRef}
        type="file"
        accept={IMAGE_ACCEPT}
        multiple
        className="hidden"
        onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
          if (e.target.files) {
            void validateAndUpload(e.target.files, 'image');
            e.target.value = '';
          }
        }}
      />
      <input
        ref={videoInputRef}
        type="file"
        accept={VIDEO_ACCEPT}
        className="hidden"
        onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
          if (e.target.files) {
            void validateAndUpload(e.target.files, 'video');
            e.target.value = '';
          }
        }}
      />

      {/* 缩略图网格 */}
      {mediaList.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {mediaList.map((item, index) => (
            <div
              key={`${item.url}-${index}`}
              className={`relative overflow-hidden rounded-lg border border-white/10 bg-black ${thumbSize}`}
            >
              {item.type === 'image' ? (
                <UIImage
                  src={item.url}
                  alt={item.filename}
                  className="h-full w-full object-cover"
                />
              ) : (
                <div className="flex h-full w-full items-center justify-center bg-black/60">
                  <Play className="h-6 w-6 text-white/80" />
                </div>
              )}
              <button
                onClick={() => handleRemove(index)}
                className="absolute right-1 top-1 flex h-5 w-5 items-center justify-center rounded-full bg-black/70 text-white transition-colors hover:bg-red-500/80"
                aria-label="删除"
              >
                <X className="h-3 w-3" />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default MediaUpload;
