import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Users, Package, AlertCircle } from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { getPackDetail } from '@client/src/api/packs';
 import PlayerCard from '@client/src/components/PlayerCard';
 import CommentSection from '@client/src/components/CommentSection';
 import FavoriteButton from '@client/src/components/FavoriteButton';
 import { getPackTypeInfo } from './pack-type-utils';
 import { useIsLandscape } from '@client/src/hooks/useIsLandscape';
 import type { Pack, PlayerListItem } from '@shared/api.interface';

const PackDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [pack, setPack] = useState<Pack | null>(null);
  const [players, setPlayers] = useState<PlayerListItem[]>([]);
  const [matchedCount, setMatchedCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const landscape = useIsLandscape();
  const gridCls = landscape ? 'grid grid-cols-8 gap-2' : 'grid grid-cols-5 gap-2';
  const containerCls = landscape
    ? 'mx-auto w-full max-w-[1440px] px-4 lg:px-6 pb-10 pt-6'
    : 'mx-auto w-full max-w-[820px] px-4 pb-10 pt-6';

  useEffect(() => {
    if (!id) return;
    const load = async () => {
      try {
        const res = await getPackDetail(id);
        setPack(res.pack);
        setPlayers(res.players);
        setMatchedCount(res.matchedCount);
      } catch (err) {
        logger.error('加载卡包详情失败', err);
        setError('卡包不存在或加载失败');
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [id]);

  if (loading) {
    return (
      <div className="flex min-h-[400px] items-center justify-center">
        <div className="text-white/60">加载中...</div>
      </div>
    );
  }

  if (error || !pack) {
    return (
      <div className="mx-auto w-full max-w-[820px] px-4 pb-10 pt-6">
         <button
           onClick={() => navigate('/packs', { state: { fromDetail: true } })}
           className="mb-6 flex items-center gap-2 text-white/70 transition-colors hover:text-white"
         >
           <ArrowLeft className="h-4 w-4" />
           <span>返回卡包列表</span>
         </button>
        <div className="flex min-h-[300px] flex-col items-center justify-center gap-3 rounded-xl border border-white/10 bg-white/5">
          <AlertCircle className="h-10 w-10 text-white/40" />
          <p className="text-white/70">{error || '卡包不存在'}</p>
        </div>
      </div>
    );
  }

  return (
    <div className={containerCls}>
       <button
         onClick={() => navigate('/packs', { state: { fromDetail: true } })}
         className="mb-4 flex items-center gap-2 text-white/70 transition-colors hover:text-white"
       >
        <ArrowLeft className="h-4 w-4" />
        <span>返回卡包列表</span>
      </button>

      <div className="mb-6 rounded-xl border border-orange-400/30 bg-gradient-to-r from-orange-500/10 via-red-500/10 to-pink-500/10 p-5 shadow-[0_0_30px_rgba(249_115_22_0.15)]">
        <div className="flex items-start gap-4">
          <div className="flex h-14 w-14 flex-shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-orange-500 to-red-500 shadow-lg">
            <Package className="h-7 w-7 text-white" />
          </div>
          <div className="flex-1 min-w-0">
             <div className="flex items-start justify-between gap-2">
               <div className="mb-1 inline-flex items-center gap-1.5 rounded-full bg-orange-500/20 px-2.5 py-0.5 text-xs font-semibold text-orange-300">
                 {getPackTypeInfo(pack).label}
               </div>
               <FavoriteButton targetType="pack" targetId={pack.id} size="md" />
             </div>
               <h1 className="text-2xl font-black text-white leading-tight">
                 {pack.originalName || pack.enName || pack.cnName || pack.menuName}
                </h1>
              <p className="mt-1 text-sm text-white/60">{pack.cnDate}</p>
            <div className="mt-3 flex items-center gap-4 text-sm">
              <div className="flex items-center gap-1.5 text-white/80">
                <Users className="h-4 w-4" />
                <span>标注 {pack.playerCount} 人</span>
              </div>
              <div className="flex items-center gap-1.5 text-emerald-300">
                <span>已入库 {matchedCount} 人</span>
              </div>
            </div>
          </div>
        </div>
      </div>

       {players.length > 0 ? (
         <div className={gridCls}>
           {players.map((player) => (
             <PlayerCard
               key={player.id}
               player={player}
               onClick={() => navigate(`/player/${player.id}`)}
             />
           ))}
         </div>
       ) : (
         <div className="flex min-h-[200px] flex-col items-center justify-center gap-2 rounded-xl border border-white/10 bg-white/5">
           <AlertCircle className="h-8 w-8 text-white/40" />
           <p className="text-white/60">该卡包暂无匹配到的球员</p>
         </div>
       )}

       <div className="mt-8">
         <CommentSection targetType="pack" targetId={id || ''} />
       </div>
    </div>
  );
};

export default PackDetailPage;
