import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { Capacitor } from '@capacitor/core';
import { registerPlugin } from '@capacitor/core';
import type { PluginListenerHandle } from '@capacitor/core';
import { App } from '@capacitor/app';
import {
  wechatWebLogin,
  wechatMobileLoginNative,
  wechatWebAuthorizeNative,
  wechatWebLoginNative,
  appleLoginNative,
  getToken,
  setToken,
} from '@client/src/api/auth';
import { SignInWithApple } from '@capacitor-community/apple-sign-in';
import { signInWithAppleWeb } from '@client/src/utils/apple-web';
import { useAuth } from '@client/src/context/AuthContext';
import { runtimeConfig } from '@client/src/utils/config';
import { Button } from '@client/src/components/ui/button';
import { UniversalLink } from '@lark-apaas/client-toolkit/components/UniversalLink';
import { toast } from 'sonner';

interface WechatAuthPlugin {
  login(): Promise<{ code: string }>;
}

/** 自定义原生插件：用系统外部浏览器打开 URL（强制外部浏览器，唤起鸿蒙原生微信） */
interface ExternalBrowserPlugin {
  open(opts: { url: string }): Promise<void>;
}

/** 期望 state 持久化 key（APP 被系统回收后冷启动仍可校验） */
const WEB_STATE_STORAGE_KEY = 'wx_web_app_state';
/** 网页授权安全超时：用户在微信里太慢就兜底，不卡死按钮 */
const WEB_AUTH_TIMEOUT_MS = 120_000;
/** 旧安卓 SDK 登录超时：卓易通容器调不起微信 SDK，不能一直转圈 */
const SDK_LOGIN_TIMEOUT_MS = 15_000;

/** 卓易通 / 鸿蒙环境判定：命中则主按钮默认走网页授权路径 */
const isWebAuthEnv =
  typeof navigator !== 'undefined' &&
  /卓易通|DroiTong|HarmonyOS|鸿蒙|OpenHarmony/i.test(navigator.userAgent);

const AuthPage: React.FC = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { fetchMe, setAuthUser } = useAuth();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [callbackCode, setCallbackCode] = useState<string | null>(null);

  // —— 临时诊断：逐步追踪登录流程（副页已验证，生产关闭，定位后可整体移除）——
  const LOGIN_DIAG_ENABLED = false;
  const [diag, setDiag] = useState<string[]>([]);
  const addDiag = (m: string) => {
    if (!LOGIN_DIAG_ENABLED) return;
    const line = `${new Date().toLocaleTimeString()} · ${m}`;
    try { logger.warn('[登录诊断]', line); } catch { /* ignore */ }
    setDiag((p) => [...p, line]);
  };
  const describeErr = (e: any): string => {
    if (!e) return String(e);
    const head = [e.name || 'Error', e.message || ''].filter(Boolean).join(': ');
    if (e && e.response) {
      let body = '';
      try { body = JSON.stringify(e.response.data).slice(0, 400); } catch { /* ignore */ }
      return `${head}\nstatus=${e.response.status} ${e.response.config?.method} ${e.response.config?.url}\nresp=${body}`;
    }
    return head;
  };
  // 微信内置浏览器中无法使用“扫码登录”，弹出引导（无认证服务号时的兜底）
  const [showWxBrowserTip, setShowWxBrowserTip] = useState(false);
  const isInWeChatBrowser =
    !Capacitor.isNativePlatform() && /MicroMessenger/i.test(navigator.userAgent);
  // iOS 原生：微信登录走原生 WechatAuth 插件；
  // 下方「鸿蒙/网页授权」依赖 ExternalBrowser（iOS 不提供），故 iOS 不显示该按钮。
  const isIosNative =
    Capacitor.isNativePlatform() && Capacitor.getPlatform() === 'ios';

  // 登录后后台刷新用户信息（带重试，不阻断跳转），解决刚回跳时 /me 瞬时失败导致的“不刷新”
  const backgroundRefreshMe = () => {
    void (async () => {
      for (let i = 0; i < 3; i++) {
        try {
          const u = await fetchMe();
          if (u) return;
        } catch { /* 稍后重试 */ }
        await new Promise((r) => setTimeout(r, 600));
      }
    })();
  };

  // 网页授权相关 ref（避免闭包捕获旧值）
  const expectedStateRef = useRef<string | null>(null);
  const deepLinkListenerRef = useRef<PluginListenerHandle | null>(null);
  const timeoutRef = useRef<number | null>(null);

  const code = searchParams.get('code');
  const state = searchParams.get('state');

  // 浏览器端既有回调：URL query 带 code 时（网站扫码登录回跳），保持原逻辑
  useEffect(() => {
    if (!code) return;
    // 已登录（如刷新/重开了已消费过 code 的回调地址）：直接回首页，不再用旧 code 换取
    if (getToken()) {
      navigate('/', { replace: true });
      return;
    }
    setCallbackCode(code);
    void handleWechatCallback(code);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [code]);

  // 卸载时清理深链监听与定时器
  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        window.clearTimeout(timeoutRef.current);
        timeoutRef.current = null;
      }
      if (deepLinkListenerRef.current) {
        deepLinkListenerRef.current.remove();
        deepLinkListenerRef.current = null;
      }
    };
  }, []);

  // 冷启动兜底：APP 被系统回收后，通过 https App Link / shikuang:// 深链直接冷启动。
  // 此时 appUrlOpen 来不及注册，用 getLaunchUrl 取本次冷启动的深链。
  useEffect(() => {
    if (!Capacitor.isNativePlatform()) return;
    App.getLaunchUrl()
      .then((result) => {
        if (result?.url) void handleDeepLinkCallback(result.url);
      })
      .catch((e) => logger.warn('getLaunchUrl 失败', e));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const cleanupWebAuth = () => {
    if (timeoutRef.current) {
      window.clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
    if (deepLinkListenerRef.current) {
      deepLinkListenerRef.current.remove();
      deepLinkListenerRef.current = null;
    }
  };

  /** 用一次性 code 向后端换 JWT（网页授权路径） */
  const exchangeWebCode = async (authCode: string) => {
    setLoading(true);
    setError(null);
    try {
      const result = await wechatWebLoginNative(authCode);
      setToken(result.token);
      // 先用响应里已带的 user 建立登录态，随后立即跳首页
      if (result.user) setAuthUser(result.user);
      cleanupWebAuth();
      expectedStateRef.current = null;
      try {
        window.localStorage.removeItem(WEB_STATE_STORAGE_KEY);
      } catch {
        // ignore
      }
      setLoading(false);
      toast.success('登录成功');
      navigate('/', { replace: true });
      // 后台带重试刷新，不阻断
      backgroundRefreshMe();
    } catch (err) {
      cleanupWebAuth();
      setLoading(false);
      logger.error('微信网页登录失败', err);
      const msg =
        err && typeof err === 'object' && 'message' in err
          ? String((err as any).message)
          : '登录失败，请重试';
      setError(msg);
      toast.error(msg);
    }
  };

  /** 解析深链回跳（https App Link 或 shikuang://），校验 state 后换 JWT */
  const handleDeepLinkCallback = async (rawUrl: string) => {
    if (!rawUrl) return;
    const isShikuang = rawUrl.startsWith('shikuang://');
    const isHttpsCb = rawUrl.startsWith(
      'https://playtostar.com/auth/wechat/callback',
    );
    if (!isShikuang && !isHttpsCb) return;

    let parsed: URL;
    try {
      parsed = new URL(rawUrl);
    } catch {
      return;
    }

    const authCode = parsed.searchParams.get('code');
    const returnedState = parsed.searchParams.get('state');

    if (!authCode) {
      cleanupWebAuth();
      setLoading(false);
      setError('未获取到微信授权码，请重试');
      return;
    }

    // state 校验：优先用内存中的期望值，其次 localStorage（冷启动回收后兜底）
    const expected =
      expectedStateRef.current ||
      (() => {
        try {
          return window.localStorage.getItem(WEB_STATE_STORAGE_KEY);
        } catch {
          return null;
        }
      })();

    if (expected && returnedState && returnedState !== expected) {
      cleanupWebAuth();
      setLoading(false);
      setError('状态校验失败，请重试');
      toast.error('状态校验失败，请重试');
      return;
    }

    // 极端情况：APP 被系统回收后冷启动，内存与 localStorage 都没有 state 参照。
    // 此时仍拿到了合法的一次性 code（微信服务端已校验过 state 签名才会回跳），
    // 继续用 code 换 JWT 是可接受的：code 单次有效、约 5 分钟过期，CSRF 风险极低。
    // 仅在此注释说明该兜底路径，不阻断登录。
    await exchangeWebCode(authCode);
  };

  /** APP 内网页授权主流程：拿授权 URL → 监听深链 → 系统外部浏览器打开 */
  const handleAppWebAuth = async () => {
    setLoading(true);
    setError(null);
    try {
      const { url, state: expectedState } = await wechatWebAuthorizeNative();
      expectedStateRef.current = expectedState;
      try {
        window.localStorage.setItem(WEB_STATE_STORAGE_KEY, expectedState);
      } catch {
        // ignore
      }

      // 先注册深链监听，再打开浏览器，避免回跳时监听器还没就绪
      const listener = await App.addListener('appUrlOpen', (event) => {
        void handleDeepLinkCallback(event.url);
      });
      deepLinkListenerRef.current = listener;

      // 安全超时：到点清理、恢复按钮，不卡死
      timeoutRef.current = window.setTimeout(() => {
        cleanupWebAuth();
        setLoading(false);
        setError('微信授权超时，请重试');
        toast.error('微信授权超时，请重试');
      }, WEB_AUTH_TIMEOUT_MS);

      // 用系统外部浏览器打开授权页（此路径实测可唤起鸿蒙原生微信）
      const ExternalBrowser = registerPlugin<ExternalBrowserPlugin>(
        'ExternalBrowser',
      );
      await ExternalBrowser.open({ url });
    } catch (err) {
      cleanupWebAuth();
      setLoading(false);
      logger.error('唤起微信网页授权失败', err);
      const msg =
        err && typeof err === 'object' && 'message' in err
          ? String((err as any).message)
          : '唤起微信登录失败，请重试';
      toast.error(msg);
      setError(msg);
    }
  };

  const handleWechatCallback = async (authCode: string) => {
    addDiag(`回调开始 code=${authCode.slice(0, 10)}… 已有token=${!!getToken()}`);
    setLoading(true);
    setError(null);
    try {
      const result = await wechatWebLogin(authCode);
      setToken(result.token);
      // 先用登录响应里已带的 user 建立登录态，随后立即跳首页
      if (result.user) setAuthUser(result.user);
      toast.success('登录成功');
      navigate('/', { replace: true });
      // /me 放后台带重试刷新，不阻断跳转（解决刚回跳瞬时失败导致的“不刷新”）
      backgroundRefreshMe();
    } catch (err) {
      addDiag(`外层catch: ${describeErr(err)}`);
      logger.error('微信登录失败', err);
      setError(`登录失败，请重试${LOGIN_DIAG_ENABLED ? `\n【诊断】\n${describeErr(err)}` : ''}`);
    } finally {
      setLoading(false);
    }
  };

  const handleWechatLogin = () => {
    if (Capacitor.isNativePlatform()) {
      // 卓易通 / 鸿蒙容器：安卓微信 SDK 调不起，主按钮直接走网页授权
      if (isWebAuthEnv) {
        void handleAppWebAuth();
        return;
      }
      void handleNativeWechatLogin();
    } else {
      handleWebWechatLogin();
    }
  };

  const handleWebWechatLogin = () => {
    // 微信内打开：扫码登录在同设备无法完成，引导用户在系统浏览器打开
    if (isInWeChatBrowser) {
      setShowWxBrowserTip(true);
      return;
    }
    const appId =
      runtimeConfig.WECHAT_WEB_APPID ||
      import.meta.env.VITE_WX_WEB_APPID ||
      process.env.VITE_WX_WEB_APPID ||
      '';
    const redirectUri = `${window.location.origin}${window.location.pathname}`;
    const wState = Math.random().toString(36).slice(2, 10);
    window.sessionStorage.setItem('wx_web_state', wState);
    const url =
      'https://open.weixin.qq.com/connect/qrconnect' +
      `?appid=${encodeURIComponent(appId)}` +
      `&redirect_uri=${encodeURIComponent(redirectUri)}` +
      `&response_type=code` +
      `&scope=snsapi_login` +
      `&state=${encodeURIComponent(wState)}#wechat_redirect`;
    // eslint-disable-next-line no-restricted-syntax
    window.location.href = url;
  };

  const handleNativeWechatLogin = async () => {
    setLoading(true);
    setError(null);
    try {
      const WechatAuth = registerPlugin<WechatAuthPlugin>('WechatAuth');
      // 15s 超时：卓易通容器里安卓微信 SDK 无法调起，不能一直卡在“登录中…”
      const timeoutPromise = new Promise<never>((_, reject) => {
        window.setTimeout(
          () => reject(new Error('SDK_TIMEOUT: 微信登录超时，当前环境可能不支持微信快捷登录')),
          SDK_LOGIN_TIMEOUT_MS,
        );
      });
      const { code: sdkCode } = await Promise.race([
        WechatAuth.login(),
        timeoutPromise,
      ]);
      const result = await wechatMobileLoginNative(sdkCode);
      setToken(result.token);
      // 先用响应里已带的 user 建立登录态，随后立即跳首页
      if (result.user) setAuthUser(result.user);
      toast.success('登录成功');
      navigate('/', { replace: true });
      // 后台带重试刷新，不阻断
      backgroundRefreshMe();
    } catch (err) {
      logger.error('原生微信登录失败', err);
      const msg =
        err && typeof err === 'object' && 'message' in err
          ? String((err as any).message)
          : '登录失败，请重试';

      // 超时 / 卓易通等不支持 SDK 的环境：提示并自动切换到网页授权
      if (
        msg.includes('SDK_TIMEOUT') ||
        msg.includes('超时') ||
        msg.includes('DroiTong') ||
        msg.includes('卓易通') ||
        msg.includes('暂不支持')
      ) {
        toast.info('当前环境不支持微信快捷登录，已切换网页授权');
        setLoading(false);
        void handleAppWebAuth();
        return;
      }

      if (msg.includes('cancel') || msg.includes('取消')) {
        toast.info('已取消登录');
      } else if (msg.includes('not installed') || msg.includes('未安装')) {
        toast.error('请先安装微信客户端');
      } else {
        toast.error(msg);
        setError(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  // Sign in with Apple（iOS 原生）
  const handleAppleLogin = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await SignInWithApple.authorize({
        clientId: 'com.playtostar.app',
        redirectURI: 'https://playtostar.com/auth/apple/callback',
        scopes: 'email fullName',
      });
      const r = result.response;
      if (!r.identityToken) {
        throw new Error('未获取到 Apple 凭证，请重试');
      }
      const fullName = [r.givenName, r.familyName].filter(Boolean).join(' ');
      const auth = await appleLoginNative({
        identityToken: r.identityToken,
        userName:
          fullName || r.email
            ? { name: fullName || undefined, email: r.email || undefined }
            : null,
      });
      setToken(auth.token);
      if (auth.user) setAuthUser(auth.user);
      toast.success('登录成功');
      navigate('/', { replace: true });
      backgroundRefreshMe();
    } catch (err: any) {
      const msg = err?.message || 'Apple 登录失败，请重试';
      if (err?.code === 'ERR_CANCELED' || /cancel|取消/i.test(msg)) {
        toast.info('已取消登录');
      } else {
        logger.error('Apple 登录失败', err);
        toast.error(msg);
        setError(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  // Sign in with Apple（网页 AppleID JS）
  const handleWebAppleLogin = async () => {
    setLoading(true);
    setError(null);
    try {
      const auth = await signInWithAppleWeb(
        runtimeConfig.APPLE_WEB_CLIENT_ID,
      );
      setToken(auth.token);
      if (auth.user) setAuthUser(auth.user);
      toast.success('登录成功');
      navigate('/', { replace: true });
      backgroundRefreshMe();
    } catch (err: any) {
      const msg = err?.message || 'Apple 登录失败，请重试';
      if (/cancel|取消/i.test(msg)) {
        toast.info('已取消登录');
      } else {
        logger.error('网页 Apple 登录失败', err);
        toast.error(msg);
        setError(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#0A0E27] text-white flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <h1 className="text-3xl font-black mb-2 bg-gradient-to-r from-cyan-400 via-blue-400 to-purple-500 bg-clip-text text-transparent">
            实况起点数据中心
          </h1>
          <p className="text-gray-400 text-sm">登录后解锁完整功能</p>
        </div>

        <div className="rounded-2xl bg-[#141838]/80 backdrop-blur-sm border border-white/10 p-6 shadow-[0_8px_32px_rgba(0_0_0_0.4)]">
          {callbackCode && loading ? (
            <div className="text-center py-12">
              <div className="w-12 h-12 border-3 border-cyan-400 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
              <p className="text-gray-300">正在登录...</p>
            </div>
          ) : (
            <>
              <div className="text-center mb-6">
                <div className="w-16 h-16 mx-auto mb-4 rounded-2xl flex items-center justify-center shadow-lg bg-gradient-to-br from-green-500 to-green-600">
                  <svg viewBox="0 0 24 24" fill="white" className="w-10 h-10">
                    <path d="M8.691 2C4.388 2 1 4.987 1 8.652c0 2.072 1.17 3.91 2.97 5.107a.566.566 0 0 1 .21.632l-.37 1.404c-.014.055.055.1.1.067l1.524-1.002a.57.57 0 0 1 .574-.046 10.06 10.06 0 0 0 2.683.723v-.167c0-.3.022-.595.06-.88-1.91-.607-3.35-1.983-3.35-3.61 0-2.238 2.382-4.052 5.312-4.052.242 0 .479.013.712.038C10.77 3.82 9.809 2 8.69 2zM6.25 5.5a1 1 0 1 1 0 2 1 1 0 0 1 0-2zm4.875 0a1 1 0 1 1 0 2 1 1 0 0 1 0-2zm6.008 3.75c-2.576 0-4.668 1.664-4.668 3.714 0 2.05 2.092 3.715 4.668 3.715.556 0 1.088-.076 1.583-.218a.472.472 0 0 1 .474.04l1.256.826a.082.082 0 0 0 .082.055.08.08 0 0 0 .08-.055l.307-1.164a.466.466 0 0 1-.173-.52c1.485-.988 2.448-2.422 2.448-3.675 0-2.05-2.092-3.714-4.668-3.714zm-1.86 2.062a.825.825 0 1 1 0 1.65.825.825 0 0 1 0-1.65zm3.96 0a.825.825 0 1 1 0 1.65.825.825 0 0 1 0-1.65z" />
                  </svg>
                </div>
                <h2 className="text-xl font-bold text-white mb-1">微信登录</h2>
                <p className="text-gray-400 text-sm">
                  {Capacitor.isNativePlatform()
                    ? '使用微信快速登录'
                    : isInWeChatBrowser
                      ? '微信内请在浏览器打开后登录'
                      : '使用微信扫码快速登录'}
                </p>
              </div>

              {error && (
                <div className="mb-4 p-3 rounded-lg bg-red-500/10 border border-red-500/30 text-red-300 text-xs text-center whitespace-pre-wrap break-words max-h-64 overflow-auto">
                  {error}
                </div>
              )}

              <Button
                onClick={handleWechatLogin}
                disabled={loading}
                className="w-full h-12 bg-gradient-to-r from-green-500 to-green-600 hover:from-green-400 hover:to-green-500 text-white text-base font-medium rounded-xl shadow-lg border-0"
              >
                {loading
                  ? '登录中...'
                  : Capacitor.isNativePlatform()
                    ? '微信登录'
                    : isInWeChatBrowser
                      ? '如何登录？'
                      : '微信扫码登录'}
              </Button>

              {/* 常驻第二按钮：网页授权（鸿蒙/卓易通/普通安卓；iOS 的 ExternalBrowser 未接入，不显示） */}
              {Capacitor.isNativePlatform() && !isIosNative && (
                <Button
                  onClick={() => void handleAppWebAuth()}
                  disabled={loading}
                  variant="outline"
                  className="w-full h-12 mt-3 bg-transparent text-green-300 border-green-500/40 hover:bg-green-500/10 hover:text-green-200 text-sm font-medium rounded-xl"
                >
                  微信登录（鸿蒙/网页授权）
                </Button>
              )}

              {/* Sign in with Apple（iOS 原生；审核要求与第三方登录并列） */}
              {Capacitor.isNativePlatform() &&
                Capacitor.getPlatform() === 'ios' && (
                  <Button
                    onClick={() => void handleAppleLogin()}
                    disabled={loading}
                    className="w-full h-12 mt-3 bg-black hover:bg-neutral-900 text-white text-base font-medium rounded-xl border border-white/25 flex items-center justify-center gap-2"
                  >
                    <svg
                      viewBox="0 0 24 24"
                      fill="currentColor"
                      className="w-5 h-5"
                    >
                      <path d="M17.05 12.04c-.03-2.7 2.2-3.99 2.3-4.05-1.25-1.84-3.2-2.09-3.89-2.12-1.66-.17-3.23.97-4.07.97-.84 0-2.13-.95-3.5-.92-1.8.03-3.46 1.05-4.39 2.66-1.87 3.25-.48 8.06 1.34 10.7.89 1.29 1.94 2.74 3.32 2.69 1.34-.06 1.85-.87 3.47-.87 1.62 0 2.08.87 3.5.84 1.45-.03 2.34-1.32 3.22-2.62 1.01-1.5 1.43-2.95 1.45-3.03-.03-.01-2.78-1.07-2.81-4.27zM14.7 4.25c.74-.9 1.24-2.15 1.1-3.4-1.06.04-2.35.71-3.12 1.6-.69.79-1.29 2.06-1.13 3.28 1.19.09 2.41-.6 3.15-1.48z" />
                    </svg>
                    通过 Apple 登录
                  </Button>
                )}

              {/* Sign in with Apple（网页；runtime-config 配置 Services ID 后才显示） */}
              {!Capacitor.isNativePlatform() &&
                runtimeConfig.APPLE_WEB_CLIENT_ID && (
                  <Button
                    onClick={() => void handleWebAppleLogin()}
                    disabled={loading}
                    className="w-full h-12 mt-3 bg-black hover:bg-neutral-900 text-white text-base font-medium rounded-xl border border-white/25 flex items-center justify-center gap-2"
                  >
                    <svg
                      viewBox="0 0 24 24"
                      fill="currentColor"
                      className="w-5 h-5"
                    >
                      <path d="M17.05 12.04c-.03-2.7 2.2-3.99 2.3-4.05-1.25-1.84-3.2-2.09-3.89-2.12-1.66-.17-3.23.97-4.07.97-.84 0-2.13-.95-3.5-.92-1.8.03-3.46 1.05-4.39 2.66-1.87 3.25-.48 8.06 1.34 10.7.89 1.29 1.94 2.74 3.32 2.69 1.34-.06 1.85-.87 3.47-.87 1.62 0 2.08.87 3.5.84 1.45-.03 2.34-1.32 3.22-2.62 1.01-1.5 1.43-2.95 1.45-3.03-.03-.01-2.78-1.07-2.81-4.27zM14.7 4.25c.74-.9 1.24-2.15 1.1-3.4-1.06.04-2.35.71-3.12 1.6-.69.79-1.29 2.06-1.13 3.28 1.19.09 2.41-.6 3.15-1.48z" />
                    </svg>
                    通过 Apple 登录
                  </Button>
                )}

              <p className="mt-4 text-xs text-gray-500 text-center">
                登录即表示同意
                <UniversalLink to="/terms" className="text-cyan-400 hover:underline mx-1">
                  《用户协议》
                </UniversalLink>
                和
                <UniversalLink to="/privacy" className="text-cyan-400 hover:underline mx-1">
                  《隐私政策》
                </UniversalLink>
              </p>
            </>
          )}
        </div>

        <p className="mt-6 text-center text-gray-600 text-xs">
          实况起点数据中心 · Web 版
        </p>
      </div>

      {LOGIN_DIAG_ENABLED && diag.length > 0 && (
        <div className="fixed bottom-0 left-0 right-0 z-40 max-w-2xl mx-auto p-2">
          <div className="rounded-lg border border-amber-400/40 bg-black/85 p-2 text-[11px] leading-snug text-amber-200 max-h-56 overflow-auto">
            <div className="mb-1 font-bold text-amber-300">登录步骤诊断（测试用）</div>
            {diag.map((d, i) => (
              <div key={i} className="whitespace-pre-wrap break-words">{d}</div>
            ))}
          </div>
        </div>
      )}

      {showWxBrowserTip && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4">
          <div className="w-full max-w-sm rounded-2xl border border-white/10 bg-[#141838] p-6 shadow-2xl">
            <h3 className="mb-3 text-lg font-bold text-white">请在浏览器中打开</h3>
            <p className="mb-2 text-sm leading-relaxed text-gray-300">
              你正在微信内打开网页。微信内的“扫码登录”需要用另一台设备扫码，当前无法完成。
            </p>
            <p className="mb-4 text-sm leading-relaxed text-gray-300">
              请点击微信右上角的 <span className="font-semibold text-white">「···」</span>，
              选择 <span className="font-semibold text-white">「在浏览器打开」</span>，
              然后再点“微信扫码登录”即可。
            </p>
            <Button
              onClick={() => setShowWxBrowserTip(false)}
              className="h-11 w-full rounded-xl bg-gradient-to-r from-cyan-500 to-blue-600 text-base font-medium text-white border-0"
            >
              我知道了
            </Button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AuthPage;
