import React from 'react';
import { Info } from 'lucide-react';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { VISITOR_TIP } from '@client/src/utils/visitor-mode';

interface VisitorModeBannerProps {
  className?: string;
  /** 自定义文案（默认：游客模式仅本机保存，登录后可永久保存） */
  text?: string;
}

/**
 * 游客模式提示横幅：在「游客可本地保存」的页面 / 面板内展示，
 * 明确告知数据仅保存在本机、登录后可永久保存。
 * 已登录用户不应渲染本组件（由调用方按 user 判断）。
 */
const VisitorModeBanner: React.FC<VisitorModeBannerProps> = ({
  className = '',
  text,
}) => {
  const { t } = useI18n();
  const msg = text ? t(text) : t(VISITOR_TIP);
  return (
    <div
      className={`flex items-center gap-2 rounded-lg border border-amber-400/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-200/90 ${className}`}
    >
      <Info className="h-3.5 w-3.5 flex-shrink-0 text-amber-300" />
      <span>{msg}</span>
    </div>
  );
};

export default VisitorModeBanner;
