// 每个能力键 → 所属加点分类（GK 优先 gk 分类；其余按顺序首个命中）
function buildStatCategoryMap(isGK?: boolean): Record<string, string> {
  const m: Record<string, string> = {};
  const gk = BUILD_CATEGORIES.filter((c) => c.key.startsWith('gk'));
  const rest = BUILD_CATEGORIES.filter((c) => !c.key.startsWith('gk'));
  for (const c of (isGK ? [...gk, ...rest] : [...rest, ...gk])) {
    for (const a of c.attributes) if (!(a.key in m)) m[a.key] = c.key;
  }
  return m;
}

interface StatRowProps {
  label: string;
  statKey: string;
  item: StatItem;
  finalValue?: number;
  boosterBonus?: number;
  boosterColorMap?: Record<string, BoosterColorConfig>;
  shineBonus?: number;
  landscape?: boolean;
  // 编辑（横屏 -/+）
  editing?: boolean;
  catKey?: string;
  catPoints?: number;
  availablePoints?: number;
  onAdjust?: (categoryKey: string, delta: 1 | -1) => void;
  // 滑屏加点（竖屏，直接在能力行左右滑）
  slideEnabled?: boolean;
  onSetPoints?: (target: number) => void;
  finalAttrValues?: Record<string, number>;
}

const StepperBtn: React.FC<{
  sign: '+' | '-'; disabled?: boolean; onClick: () => void; title: string;
}> = ({ sign, disabled, onClick, title }) => (
  <button
    type="button"
    title={title}
    disabled={disabled}
    onClick={onClick}
    className="w-4 h-5 rounded-[4px] flex items-center justify-center text-[11px] font-bold leading-none
      bg-white/10 text-cyan-200 border border-cyan-300/30
      hover:bg-cyan-400/30 active:scale-95 transition
      disabled:opacity-30 disabled:cursor-not-allowed"
  >
    {sign}
  </button>
);

const StatRow: React.FC<StatRowProps> = ({
  label, statKey, item, finalValue, boosterBonus, boosterColorMap, shineBonus,
  landscape = false, editing = false, catKey, catPoints = 0, availablePoints = 0, onAdjust,
  slideEnabled = false, onSetPoints, finalAttrValues,
}) => {
  const { lang } = useI18n();
  const fullLabel = trTerm(label);
  // 中文传全名：放得下显全名、放不下由 EllipsisText 按该行实际宽度截断；
  // 英文全名过长，沿用约定缩写（Def. Aware 等）。
  const shownLabel = lang === 'en' ? abbrStatEn(fullLabel) : fullLabel;
  // 竖屏：彩色数值固定右侧、垂直对齐；项目名占剩余宽度，中文按整字测量，放不下就隐藏末字（无省略号）
  const labelRef = React.useRef<HTMLAnchorElement>(null);
  const [labelFit, setLabelFit] = React.useState<number>(99);
  React.useLayoutEffect(() => {
    if (lang === 'en') return;
    const el = labelRef.current;
    if (!el) return;
    const compute = () => {
      const fs = parseFloat(getComputedStyle(el).fontSize) || 36;
      setLabelFit(Math.max(1, Math.floor(el.clientWidth / fs)));
    };
    compute();
    const ro = new ResizeObserver(compute);
    ro.observe(el);
    return () => ro.disconnect();
  }, [lang, fullLabel]);
  const displayLabel = lang === 'en'
    ? shownLabel
    : fullLabel.length <= labelFit ? fullLabel : fullLabel.slice(0, labelFit);
  const baseValue = item.rating;
  const displayValue = finalValue !== undefined ? finalValue : baseValue;
  const bColor = boosterColorMap?.[statKey] ?? { text: 'text-purple-300', bg: '', border: '', glow: '', hex: '#a855f7' };

  const nextCost = getCostForNextPoint(catPoints);
  const canAdd = editing && !!catKey && availablePoints >= nextCost;
  const canSub = editing && catPoints > 0;

  // —— 竖屏滑屏加点：右滑加、左滑减；步长 6px/点（更灵敏，约 1/3 屏 130px → 21 点，实际受预算钳制）——
  const SLIDE_STEP = 6;
  const gestureRef = React.useRef<{ x: number; y: number; pts: number; lock: null | 'h' | 'v'; step: number }>(
    { x: 0, y: 0, pts: 0, lock: null, step: 0 },
  );
  const [hud, setHud] = React.useState<{ visible: boolean; start: number } | null>(null);
  const hideTimerRef = React.useRef<number | null>(null);
  const clearHideTimer = () => {
    if (hideTimerRef.current != null) { window.clearTimeout(hideTimerRef.current); hideTimerRef.current = null; }
  };
  React.useEffect(() => () => clearHideTimer(), []);

  const onSlideStart = (e: React.TouchEvent) => {
    if (!slideEnabled) return;
    const t = e.touches[0];
    gestureRef.current = { x: t.clientX, y: t.clientY, pts: catPoints, lock: null, step: 0 };
  };
  const onSlideMove = (e: React.TouchEvent) => {
    if (!slideEnabled) return;
    const g = gestureRef.current;
    const t = e.touches[0];
    const dx = t.clientX - g.x;
    const dy = t.clientY - g.y;
    if (g.lock === null) {
      if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return;
      g.lock = Math.abs(dx) > Math.abs(dy) ? 'h' : 'v';
      if (g.lock === 'h') { clearHideTimer(); setHud({ visible: true, start: g.pts }); }
    }
    if (g.lock !== 'h') return;
    const s = Math.trunc(dx / SLIDE_STEP);
    if (s !== g.step) {
      g.step = s;
      onSetPoints!(Math.max(0, g.pts + s)); // 后端按预算钳制
    }
  };
  const onSlideEnd = () => {
    if (!slideEnabled) return;
    const g = gestureRef.current;
    if (g.lock === 'h') {
      onSetPoints!(Math.max(0, g.pts + g.step));
      setHud((h) => (h ? { ...h, visible: false } : h));
      clearHideTimer();
      hideTimerRef.current = window.setTimeout(() => setHud(null), 650);
    }
    g.lock = null; g.step = 0;
  };
  // HUD 展示：所属大项的名称，以及大项下属每个能力的即时数值
  const categoryDef = catKey ? BUILD_CATEGORIES.find((c) => c.key === catKey) : undefined;
  const hudTitle = categoryDef ? trTerm(categoryDef.name) : fullLabel;
  const hudAffects = categoryDef
    ? categoryDef.attributes
        // 浮窗横向空间足够：能力名全字段显示，不做缩写/省略
        .map((a) => `${trTerm(a.label)} ${finalAttrValues?.[a.key] ?? ''}`)
        .join('、')
    : '';

  if (landscape) {
    return (
      <div className="flex items-center justify-between gap-1 py-[3px] border-b border-white/5 last:border-b-0">
        <Link
          to={{ pathname: `/encyclopedia/ability/${statKey}` }}
          state={{ from: window.location.pathname + window.location.search }}
          className="text-[13px] text-gray-300 flex-shrink-0 hover:text-cyan-300 transition-colors truncate"
          title={lang === 'en' ? `${fullLabel} (view encyclopedia)` : `${label}（查看百科解释）`}
        >
          {shownLabel}
        </Link>
        <div className="flex items-center gap-0.5 flex-shrink-0">
          {shineBonus && shineBonus > 0 && !editing && (
            <span className="text-[10px] font-bold min-w-[14px] text-right text-amber-400" title={`闪耀加成 +${shineBonus}`}>+{shineBonus}</span>
          )}
          {boosterBonus && boosterBonus > 0 && !editing && (
            <span className={`text-[10px] font-bold min-w-[14px] text-right ${bColor.text}`} title={`增能加成 +${boosterBonus}`}>+{boosterBonus}</span>
          )}
          {editing && (
            <span className="flex items-center gap-[3px] mr-[2px]">
              {catPoints > 0 && (
                <span className="text-[11px] font-bold text-emerald-400 min-w-[17px] text-center leading-none" title={`本项已加 ${catPoints} 点`}>
                  +{catPoints}
                </span>
              )}
              <StepperBtn sign="-" disabled={!canSub} title="减点"
                onClick={() => catKey && onAdjust?.(catKey, -1)} />
              <StepperBtn sign="+" disabled={!canAdd} title={`加点（需 ${nextCost} 点）`}
                onClick={() => catKey && onAdjust?.(catKey, 1)} />
            </span>
          )}
          <span className={`w-7 h-6 rounded-md flex items-center justify-center text-xs font-bold ${getAttrColorClass(displayValue)}`}>
            {Math.round(displayValue)}
          </span>
        </div>
      </div>
    );
  }

  return (
    <div
      onTouchStart={onSlideStart}
      onTouchMove={onSlideMove}
      onTouchEnd={onSlideEnd}
      onTouchCancel={onSlideEnd}
      style={slideEnabled ? { touchAction: 'pan-y' } : undefined}
      className="flex items-center justify-between py-2 border-b border-white/5 last:border-b-0"
    >
      <Link
        ref={labelRef}
        to={{ pathname: `/encyclopedia/ability/${statKey}` }}
        state={{ from: window.location.pathname + window.location.search }}
        className="min-w-0 flex-1 truncate text-3xl md:text-2xl text-gray-300 hover:text-cyan-300 hover:underline underline-offset-2 transition-colors"
        title={lang === 'en' ? `${fullLabel} (view encyclopedia)` : `${fullLabel}（查看百科解释）`}
      >
        {displayLabel}
      </Link>
      <div className="flex flex-shrink-0 items-center gap-1.5">
        {(shineBonus && shineBonus > 0) || (boosterBonus && boosterBonus > 0) ? (
          <div className="flex flex-col items-end justify-center gap-0.5 leading-none">
            {shineBonus && shineBonus > 0 && (
              <span className="text-sm font-bold text-amber-400" title={`闪耀加成 +${shineBonus}`}>+{shineBonus}</span>
            )}
            {boosterBonus && boosterBonus > 0 && (
              <span className={`text-sm font-bold ${bColor.text}`} title={`增能加成 +${boosterBonus}`}>+{boosterBonus}</span>
            )}
          </div>
        ) : null}
        <span className={`w-12 h-11 flex items-center justify-center rounded-lg text-2xl font-bold ${getAttrColorClass(displayValue)}`}>
          {Math.round(displayValue)}
        </span>
      </div>
      {/* 滑屏加点提示：Portal 挂 body；位置下移、底色 70% 透明；渐入渐出 */}
      {hud && createPortal(
        <div
          className="pointer-events-none fixed left-1/2 z-[9999] w-[92vw] max-w-md transition-all duration-200"
          style={{
            top: 'calc(env(safe-area-inset-top, 0px) + 26vh)',
            opacity: hud.visible ? 1 : 0,
            transform: `translate(-50%, ${hud.visible ? '0' : '-8px'})`,
          }}
        >
          <div className="rounded-2xl border border-emerald-300/30 bg-[#0e4a32]/90 px-4 py-2.5 shadow-[0_8px_30px_rgba(0,0,0,0.55)] backdrop-blur-md">
            <div className="flex items-center justify-between gap-3">
              <span className="min-w-0 flex items-baseline gap-2">
                <span className="truncate text-base font-bold text-white">{hudTitle}</span>
                <span className="shrink-0 text-[10px] leading-none text-gray-400/80 whitespace-nowrap">{lang === 'en' ? 'Patented · No copy' : '专利设计，仿者必究'}</span>
              </span>
              <span className="flex shrink-0 items-baseline gap-2">
                <span className="flex items-baseline gap-1">
                  <span className="text-[10px] text-gray-400 whitespace-nowrap">{lang === 'en' ? 'Used' : '已加'}</span>
                  <span className="text-lg font-black tabular-nums text-red-400">{catPoints}</span>
                </span>
                <span className="flex items-baseline gap-1">
                  <span className="text-[10px] text-gray-400 whitespace-nowrap">{lang === 'en' ? 'Left' : '剩余'}</span>
                  <span className="text-lg font-black tabular-nums text-emerald-400">{availablePoints}</span>
                </span>
              </span>
            </div>
            <p className="mt-1 text-[12px] leading-snug text-gray-300">{hudAffects}</p>
          </div>
        </div>,
        document.body,
      )}
    </div>
  );
};

interface PanelProps {
  index: string;
  title: string;
  labels: StatEntry[];
  stats: Record<string, StatItem>;
  accentColor: string;
  finalAttrValues?: Record<string, number>;
  boosterBonusValues?: Record<string, number>;
  boosterColorMap?: Record<string, BoosterColorConfig>;
  shineBonusValues?: Record<string, number>;
  landscape?: boolean;
  editing?: boolean;
  catMap?: Record<string, string>;
  allocations?: Record<string, number>;
  availablePoints?: number;
  onAdjust?: (categoryKey: string, delta: 1 | -1) => void;
  // 竖屏滑屏
  slideEnabled?: boolean;
  onSetCategoryPoints?: (categoryKey: string, target: number) => void;
}

const Panel: React.FC<PanelProps> = ({
  index, title, labels, stats, accentColor, finalAttrValues, boosterBonusValues, boosterColorMap,
  shineBonusValues, landscape = false, editing = false, catMap, allocations, availablePoints, onAdjust,
  slideEnabled = false, onSetCategoryPoints,
}) => {
  if (landscape) {
    return (
      <div className="rounded-lg bg-card/80 border border-white/10 px-1.5 py-1 backdrop-blur min-w-0">
        <div className="flex items-center gap-1 mb-0.5">
          <span className={`text-[10px] font-mono font-bold ${accentColor}`}>{index}</span>
          <h3 className="text-xs font-bold text-white truncate">{title}</h3>
        </div>
        <div>
          {labels.map((entry: StatEntry) => {
            const item = stats?.[entry.key];
            if (!item) return null;
            const catKey = catMap?.[entry.key];
            const catPoints = catKey ? Number(allocations?.[catKey] ?? 0) || 0 : 0;
            return (
              <StatRow
                key={entry.key}
                label={entry.label}
                statKey={entry.key}
                item={item}
                finalValue={finalAttrValues?.[entry.key]}
                boosterBonus={boosterBonusValues?.[entry.key]}
                boosterColorMap={boosterColorMap}
                shineBonus={shineBonusValues?.[entry.key]}
                landscape
                editing={editing}
                catKey={catKey}
                catPoints={catPoints}
                availablePoints={availablePoints}
                onAdjust={onAdjust}
              />
            );
          })}
        </div>
      </div>
    );
  }
  return (
    <div className="rounded-xl bg-card/80 border border-white/10 p-4 backdrop-blur">
      <div className="flex items-center gap-2 mb-3">
        <span className={`text-sm font-mono font-bold ${accentColor}`}>{index}</span>
        <h3 className="text-3xl md:text-xl font-bold text-white">{title}</h3>
      </div>
      <div className="space-y-0">
        {labels.map((entry: StatEntry) => {
          const item = stats?.[entry.key];
          if (!item) return null;
          const catKey = catMap?.[entry.key];
          const catPoints = catKey ? Number(allocations?.[catKey] ?? 0) || 0 : 0;
          const rowSlide = slideEnabled && !!catKey && typeof onSetCategoryPoints === 'function';
          return (
            <StatRow
              key={entry.key}
              label={entry.label}
              statKey={entry.key}
              item={item}
              finalValue={finalAttrValues?.[entry.key]}
              boosterBonus={boosterBonusValues?.[entry.key]}
              boosterColorMap={boosterColorMap}
              shineBonus={shineBonusValues?.[entry.key]}
              catKey={catKey}
              catPoints={catPoints}
              availablePoints={availablePoints}
              slideEnabled={rowSlide}
              onSetPoints={rowSlide ? (target) => onSetCategoryPoints!(catKey, target) : undefined}
              finalAttrValues={finalAttrValues}
            />
          );
        })}
      </div>
    </div>
  );
};

const StatsPanel: React.FC<StatsPanelProps> = ({
  attackStats, defenseStats, powerStats, finalAttrValues, boosterBonusValues, boosterColorMap,
  shineBonusValues, landscape = false, editMode = false, availablePoints, isGK = false,
  allocations, onToggleEdit, onResetAll, onAdjust, onSetCategoryPoints, onSaveBuild,
}) => {
  const catMap = useMemo(() => buildStatCategoryMap(isGK), [isGK]);
  const { t } = useI18n();
  const [slideOn] = useSlidePoints();
  const narrow = useIsNarrowScreen();
  // 竖屏（手机/窄屏）才启用滑屏；需已注册加点 API
  const slideEnabled = !landscape && narrow && slideOn && typeof onSetCategoryPoints === 'function';

  if (landscape) {
    return (
      <div className="min-h-0 flex flex-col">
        <div className="flex items-center gap-1.5 mb-1 flex-wrap">
          <span className="w-1 h-4 bg-neon-gradient rounded-full" />
          <h2 className="text-sm font-bold text-white">{t('detail.attributes')}</h2>
          <div className="flex-1" />
          {availablePoints !== undefined && (
            <span className="flex items-baseline gap-1 px-2 py-[2px]" title="尚未使用的加点">
              <span className="text-[11px] font-medium text-gray-400">{t('detail.available')}</span>
              <span className="text-xl font-bold text-emerald-400 leading-none min-w-[2ch] text-center">
                {availablePoints}
              </span>
            </span>
          )}
          {onResetAll && (
            <button type="button" onClick={onResetAll}
              className="text-[11px] font-bold px-2 py-[3px] rounded-md
                bg-white/5 border border-white/15 text-gray-200 hover:bg-white/15 transition">
              {t('common.reset')}
            </button>
          )}
          {onToggleEdit && (
            <button type="button" onClick={onToggleEdit}
              className={
                editMode
                  ? 'text-[12px] font-bold px-3 py-[5px] rounded-md bg-gradient-to-r from-cyan-500 to-blue-600 text-white shadow-[0_0_12px_rgba(0_229_255_0.45)] transition active:scale-95'
                  : 'flex items-center gap-[2px] text-[12px] font-bold px-3 py-[5px] rounded-md bg-gradient-to-r from-cyan-400 to-blue-600 text-white ring-1 ring-cyan-300/50 shadow-[0_0_12px_rgba(0_229_255_0.5)] transition active:scale-95'
              }>
              {editMode ? t('common.confirm') : t('common.addPoints')}
            </button>
          )}
        </div>
        <div className="grid grid-cols-3 gap-1.5 flex-1 min-h-0 overflow-y-auto">
          <Panel
            index="01" title={t('detail.offense')} labels={attackLabels}
            stats={attackStats as unknown as Record<string, StatItem>}
            accentColor="text-[#f59e0b]"
            finalAttrValues={finalAttrValues} boosterBonusValues={boosterBonusValues}
            boosterColorMap={boosterColorMap} shineBonusValues={shineBonusValues}
            landscape editing={editMode} catMap={catMap} allocations={allocations}
            availablePoints={availablePoints} onAdjust={onAdjust}
          />
          <Panel
            index="02" title={t('detail.defense')} labels={defenseLabels}
            stats={defenseStats as unknown as Record<string, StatItem>}
            accentColor="text-[#3b82f6]"
            finalAttrValues={finalAttrValues} boosterBonusValues={boosterBonusValues}
            boosterColorMap={boosterColorMap} shineBonusValues={shineBonusValues}
            landscape editing={editMode} catMap={catMap} allocations={allocations}
            availablePoints={availablePoints} onAdjust={onAdjust}
          />
          <Panel
            index="03" title={t('detail.physical')} labels={powerLabels}
            stats={powerStats as unknown as Record<string, StatItem>}
            accentColor="text-[#10b981]"
            finalAttrValues={finalAttrValues} boosterBonusValues={boosterBonusValues}
            boosterColorMap={boosterColorMap} shineBonusValues={shineBonusValues}
            landscape editing={editMode} catMap={catMap} allocations={allocations}
            availablePoints={availablePoints} onAdjust={onAdjust}
          />
        </div>
      </div>
    );
  }
  return (
    <div>
      <div className="mb-3 flex items-center gap-2">
        <span className="w-1 h-6 bg-neon-gradient rounded-full" />
        <h2 className="text-4xl md:text-2xl font-bold text-white">{t('detail.attributes')}</h2>
        {onSaveBuild && (
          <button
            type="button"
            onClick={onSaveBuild}
            className="ml-auto flex items-center gap-1.5 rounded-xl border border-emerald-400/70 bg-gradient-to-r from-emerald-500 to-green-500 px-3.5 py-2 text-2xl font-bold text-white shadow-[0_0_12px_rgba(16_185_129_0.45)] transition-all active:scale-95 md:text-lg"
          >
            <Save className="w-5 h-5 md:w-4 md:h-4" />
            <span>{t('方案保存')}</span>
          </button>
        )}
      </div>
      <div className="grid grid-cols-3 gap-4">
        <Panel
          index="01" title={t('detail.offense')} labels={attackLabels}
          stats={attackStats as unknown as Record<string, StatItem>}
          accentColor="text-[#f59e0b]"
          finalAttrValues={finalAttrValues} boosterBonusValues={boosterBonusValues}
          boosterColorMap={boosterColorMap} shineBonusValues={shineBonusValues}
          catMap={catMap} allocations={allocations} availablePoints={availablePoints} slideEnabled={slideEnabled}
          onSetCategoryPoints={onSetCategoryPoints}
        />
        <Panel
          index="02" title={t('detail.defense')} labels={defenseLabels}
          stats={defenseStats as unknown as Record<string, StatItem>}
          accentColor="text-[#3b82f6]"
          finalAttrValues={finalAttrValues} boosterBonusValues={boosterBonusValues}
          boosterColorMap={boosterColorMap} shineBonusValues={shineBonusValues}
          catMap={catMap} allocations={allocations} availablePoints={availablePoints} slideEnabled={slideEnabled}
          onSetCategoryPoints={onSetCategoryPoints}
        />
        <Panel
          index="03" title={t('detail.physical')} labels={powerLabels}
          stats={powerStats as unknown as Record<string, StatItem>}
          accentColor="text-[#10b981]"
          finalAttrValues={finalAttrValues} boosterBonusValues={boosterBonusValues}
          boosterColorMap={boosterColorMap} shineBonusValues={shineBonusValues}
          catMap={catMap} allocations={allocations} availablePoints={availablePoints} slideEnabled={slideEnabled}
          onSetCategoryPoints={onSetCategoryPoints}
        />
      </div>
    </div>
  );
};

export default StatsPanel;
