import { BUILD_CATEGORIES } from './build-categories';
import {
  getBoostMap,
  getPositionByKey,
  getAllPositions,
  getPositionKeyByLabel,
  autoBuildForPosition,
  type StyleBonusThresholds,
} from './position-overall';
import { getBoosterAttrMap, apiBoosterToLocal, type Booster } from './booster-data';
import { getShineBonusMap, getShineRuleType, getLegendShineBonusMap } from './shine-data';
import type { Player, Coach, ManagerBonus, StyleProficiency, StatItem, PositionRatings } from '@shared/api.interface';

export interface ComparePlayerConfig {
  allocations: Record<string, number>;
  coach: Coach | null;
  booster1: Booster | null;
  booster2: Booster | null;
  shineLevel: number;
  level: number;
}

export interface CompareComputedStats {
  finalAttrs: Record<string, number>;
  baseStats: Record<string, number>;
  boostMap: Record<string, number>;
  coachBonusMap: Record<string, number>;
  styleBonusMap: Record<string, number>;
  boosterBonusMap: Record<string, number>;
  shineBonusMap: Record<string, number>;
  overall: number;
  positionRatings: PositionRatings;
  radarData: Record<string, number>;
  config: ComparePlayerConfig;
}

function buildPointsByAttr(allocations: Record<string, number>): Record<string, number> {
  const map: Record<string, number> = {};
  for (const cat of BUILD_CATEGORIES) {
    const points = allocations[cat.key] ?? 0;
    for (const attr of cat.attributes) {
      map[attr.key] = (map[attr.key] ?? 0) + points;
    }
  }
  return map;
}

function getStyleBonusThresholds(styleValue: number): {
  plus3: number;
  plus2: number;
  plus1: number;
} {
  // 官方规则（2026-09 校准）：裸值 ≥ 173−S → +3；裸值 ≥ 145−S → +2；其余 → +1（最低 +1）
  const plus3 = 173 - styleValue;
  const plus2 = 145 - styleValue;
  return { plus3, plus2, plus1: plus2 };
}

function calcStyleBonusForValue(value: number, thresholds: { plus3: number; plus2: number; plus1: number } | null): number {
  if (!thresholds) return 0;
  if (value >= thresholds.plus3) return 3;
  if (value >= thresholds.plus2) return 2;
  return 1;
}

export function buildBaseStatsMap(player: Player): Record<string, number> {
  const map: Record<string, number> = {};
  const attack = (player.attackStats ?? {}) as Record<string, StatItem>;
  const defense = (player.defenseStats ?? {}) as Record<string, StatItem>;
  const power = (player.powerStats ?? {}) as Record<string, StatItem>;
  for (const [k, v] of Object.entries(attack)) {
    if (v && typeof v.rating === 'number') map[k] = v.rating;
  }
  for (const [k, v] of Object.entries(defense)) {
    if (v && typeof v.rating === 'number') map[k] = v.rating;
  }
  for (const [k, v] of Object.entries(power)) {
    if (v && typeof v.rating === 'number') map[k] = v.rating;
  }
  return map;
}

export function buildCoachBonusMap(coach: Coach | null): Record<string, number> {
  const map: Record<string, number> = {};
  if (!coach) return map;
  const bonuses = (coach.managerBonus ?? []) as ManagerBonus[];
  for (const b of bonuses) {
    const key = b.stat?.toLowerCase().replace(/\s+/g, '');
    if (!key) continue;
    const normalizedKey = normalizeAttrKey(b.stat);
    if (normalizedKey) {
      map[normalizedKey] = (map[normalizedKey] || 0) + (b.value ?? 0);
    }
  }
  return map;
}

