  '罚定位球': 'setPieceTaking',
  '弧线球': 'curve',
  '防守意识': 'defensiveAwareness',
  '铲球': 'tackle',
  '积极性': 'aggression',
  '防守参与度': 'defensiveEngagement',
  '速度': 'speed',
  '加速': 'acceleration',
  '脚下力量': 'kickingPower',
  '跳起': 'jump',
  '身体接触': 'physicalContact',
  '平衡': 'balance',
  '体力': 'stamina',
  '守门员意识': 'gkAwareness',
  '接球能力': 'gkCatching',
  '守门员扑救': 'gkClearing',
  '扑救反应': 'gkReflexes',
  '守门员臂展': 'gkReach',
  'offensiveawareness': 'offensiveAwareness',
  'ballcontrol': 'ballControl',
  'tightpossession': 'tightPossession',
  'lowpass': 'lowPass',
  'loftedpass': 'loftedPass',
  'setpiecetaking': 'setPieceTaking',
  'defensiveawareness': 'defensiveAwareness',
