import React from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import { ErrorBoundary } from 'react-error-boundary';

import { AppContainer } from '@lark-apaas/client-toolkit/components/AppContainer';
import { ErrorRender } from '@lark-apaas/client-toolkit/components/ErrorRender';

import AppUpdateGate from '@client/src/components/AppUpdateGate';
import { I18nProvider } from '@client/src/i18n/I18nProvider';
import RoutesComponent from './app.tsx';
import './index.css';
import { createPortal } from 'react-dom';
import { Toaster } from '@client/src/components/ui/sonner';
import { setupStatusBar } from '@client/src/native/status-bar';
import { setupApiBase } from '@client/src/native/api-base';

// 还原后端绝对基地址（避免原生 App 请求落到 https://localhost）
setupApiBase();
// 原生 App：状态栏图标适配深色背景（浅色图标）
void setupStatusBar();

// 原生 App：在 <html> 上标记，供 CSS 隐藏横滑滚动条（APP 内直接手势滑动）
if (typeof window !== 'undefined') {
  const cap = (window as unknown as { Capacitor?: { isNativePlatform?: () => boolean } }).Capacitor;
  if (cap?.isNativePlatform?.()) {
    document.documentElement.classList.add('native-app');
  }
}

// 基路径优先级：index.html 注入的 window.__BASENAME__（web 子路径 /efootball、套壳 / 均可靠）
// → 构建期 ((typeof window !== "undefined" && window.__BASENAME__) || "") → 根路径 '/'
// window.__BASENAME__ 若为妙搭 hbs 未替换占位符（形如 "{{basename}}"）则视为无效，继续向后取环境变量
const WINDOW_BASENAME =
  typeof window !== 'undefined' &&
  typeof window.__BASENAME__ === 'string' &&
  !window.__BASENAME__.includes('{{')
    ? window.__BASENAME__
    : undefined;
// vite 会把构建 base 自动注入 import.meta.env.BASE_URL（副页为 /efootball-next/，正式为 /efootball/）
const VITE_BASENAME_RAW =
  typeof import.meta !== 'undefined' && (import.meta as any).env && (import.meta as any).env.BASE_URL
    ? String((import.meta as any).env.BASE_URL)
    : '';
// 相对 base（APP 套壳 VITE_BASE=./）：资源保持相对路径，但 Router basename 必须取根 '/'——
// 否则 '.' 被 Router 规范化成 '/.'，与实际路径 '/'（capacitor://localhost/）不匹配、整页不渲染（蓝屏实证）。
const VITE_BASENAME_TRIMMED = VITE_BASENAME_RAW.replace(/\/+$/, '');
const VITE_BASENAME =
  VITE_BASENAME_TRIMMED === '.' || VITE_BASENAME_TRIMMED === '' ? '/' : VITE_BASENAME_TRIMMED;
// 注意：妙搭 preset 会把 ((typeof window !== "undefined" && window.__BASENAME__) || "") 重写成 window.__BASENAME__（可能是 {{basename}} 未替换占位符），
// 故不采用该环境变量；统一以 vite 构建注入的 import.meta.env.BASE_URL 为准（副页 /efootball-next，正式 /efootball）。
// 第一优先级必须是 vite 注入的 BASE_URL：dev 下妙搭 preset 会把 window.__BASENAME__ 硬编码
// 成 “/”（不反映真实子路径），若让它优先会覆盖 /efootball、/efootball-next，导致所有子路由
// 匹配失败、整页落到兜底“页面不存在”。APP 套壳 vite base 为 './'，已在上方规范成 '/'，不受影响。
const RAW_BASE_PATH =
  VITE_BASENAME ||
  WINDOW_BASENAME ||
  '/';
// 仍残留 hbs 占位符时兜底为根路径 '/'
const CLIENT_BASE_PATH =
  typeof RAW_BASE_PATH === 'string' && RAW_BASE_PATH.includes('{{') ? '/' : RAW_BASE_PATH;

// 回写最终 basename，供 router-path 等工具与原生代码读取，确保与 BrowserRouter 完全同源
if (typeof window !== 'undefined') {
  (window as unknown as { __BASENAME__?: string }).__BASENAME__ = CLIENT_BASE_PATH;
}

const MainApp = () => {
  return (
    <I18nProvider>
    <BrowserRouter basename={CLIENT_BASE_PATH}>
      <AppContainer defaultTheme="light">
        <AppUpdateGate>
        <ErrorBoundary
          fallbackRender={({ error, resetErrorBoundary }) => (
            <div style={{ padding: '24px 18px', minHeight: '100vh', background: '#0b1220',
              color: '#e2e8f0', display: 'flex', flexDirection: 'column', alignItems: 'center',
              gap: '16px', fontSize: '14px', boxSizing: 'border-box' }}>
              <div style={{ fontSize: '18px', fontWeight: 600 }}>页面出错了</div>
              <button onClick={resetErrorBoundary}
                style={{ padding: '10px 28px', borderRadius: '999px', border: 'none',
                  background: '#38bdf8', color: '#06101f', fontSize: '14px' }}>
                点击重试
              </button>
              <a
                href="https://playtostar.com/download/playtostar.apk"
                target="_blank"
                rel="noopener noreferrer"
                onClick={() => { try { window.open('https://playtostar.com/download/playtostar.apk', '_system'); } catch { /* noop */ } }}
                style={{ padding: '10px 24px', borderRadius: '999px', border: '1px solid #38bdf8',
                  background: 'transparent', color: '#7dd3fc', fontSize: '14px', textDecoration: 'none' }}
              >
                仍无法使用？下载最新版
              </a>
              <div style={{ fontSize: '11px', opacity: 0.7, textAlign: 'center' }}>
                或用手机浏览器打开下载页 playtostar.com/efootball/download，<br />
                下载最新 APK 直接覆盖安装（包名签名一致、保留数据）
              </div>
              <pre style={{ whiteSpace: 'pre-wrap', wordBreak: 'break-all',
                background: 'rgba(255,255,.06)', padding: '12px', borderRadius: '8px',
                width: '100%', boxSizing: 'border-box', fontSize: '12px', color: '#fca5a5',
                margin: 0 }}>
                {String((error && (error.stack || error.message)) || error)}
              </pre>
            </div>
          )}
        >
          <RoutesComponent />
        </ErrorBoundary>
        </AppUpdateGate>
        {createPortal(<Toaster />, document.body)}
      </AppContainer>
    </BrowserRouter>
    </I18nProvider>
  );
};

createRoot(document.getElementById('root')!).render(<MainApp />);
