import { registerPlugin, type PluginListenerHandle } from '@capacitor/core';

/**
 * 应用内更新（原生 AppUpdater 插件的前端桥接）。
 * 仅在原生壳内可用；web 端调用会安全返回。
 */

export interface NativeAppInfo {
  packageName: string;
  versionCode: number;
  versionName: string;
}

export interface AppUpdaterPlugin {
  getAppInfo(): Promise<NativeAppInfo>;
  downloadAndInstall(options: { url: string }): Promise<{ file: string }>;
  addListener(
    eventName: 'downloadProgress' | 'installLaunched',
    listener: (event: { percent?: number; file?: string }) => void,
  ): Promise<PluginListenerHandle>;
}

export const AppUpdater = registerPlugin<AppUpdaterPlugin>('AppUpdater');

/** 远程版本清单结构（部署在已备案域名 download 目录） */
export interface VersionManifest {
  /** 最新版本整数号，越大越新 */
  versionCode: number;
  versionName: string;
  /** 新版 APK 直链（https） */
  apkUrl: string;
  /** 更新说明，按行展示 */
  releaseNotes: string[];
  /** 是否强制更新（true 时不可跳过） */
  forceUpdate?: boolean;
  /** 发布日期，仅展示 */
  publishedAt?: string;
}

export const DEFAULT_MANIFEST_URL =
  'https://playtostar.com/download/version.json';

export interface CheckUpdateResult {
  current: NativeAppInfo;
  manifest: VersionManifest;
  hasUpdate: boolean;
}

/** 读取当前安装版本 */
export async function getCurrentAppInfo(): Promise<NativeAppInfo | null> {
  try {
    return await AppUpdater.getAppInfo();
  } catch {
    return null;
  }
}

/** 拉取远程版本清单 */
export async function fetchVersionManifest(
  manifestUrl: string = DEFAULT_MANIFEST_URL,
): Promise<VersionManifest> {
  const res = await fetch(`${manifestUrl}?t=${Date.now()}`, {
    method: 'GET',
  });
  if (!res.ok) {
    throw new Error(`版本清单请求失败：${res.status}`);
  }
  const data = (await res.json()) as VersionManifest;
  if (!data.apkUrl || typeof data.versionCode !== 'number') {
    throw new Error('版本清单格式不正确');
  }
  return data;
}

/** 检查是否有新版本（仅原生） */
export async function checkForUpdate(
  manifestUrl: string = DEFAULT_MANIFEST_URL,
): Promise<CheckUpdateResult | null> {
  const current = await getCurrentAppInfo();
  if (!current) return null; // 非原生环境
  const manifest = await fetchVersionManifest(manifestUrl);
  return {
    current,
    manifest,
    hasUpdate: manifest.versionCode > current.versionCode,
  };
}

/**
 * 下载并安装更新。
 * @param onProgress 进度回调（0-100）
 */
export async function downloadAndInstallUpdate(
  apkUrl: string,
  onProgress?: (percent: number) => void,
): Promise<void> {
  // 监听原生下载进度
  const handle = await AppUpdater.addListener('downloadProgress', (ev) => {
    const percent = Number((ev as { percent?: number }).percent ?? 0);
    onProgress?.(percent);
  });
  try {
    await AppUpdater.downloadAndInstall({ url: apkUrl });
  } finally {
    handle.remove();
  }
}
