import React, { useState, useEffect, useCallback, useImperativeHandle, forwardRef, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { MessageCircle, Loader2, ChevronDown, MessageSquarePlus } from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { toast } from 'sonner';
import { comments as commentsApi } from '@client/src/api';
import { useAuth } from '@client/src/context/AuthContext';
import type {
  CommentThreadItem,
  CommentItem,
  CommentListResponse,
  CommentRepliesResponse,
  CommentMediaItem,
} from '@shared/api.interface';
import { showConfirm } from '@lark-apaas/client-toolkit';
import {
   Dialog,
   DialogContent,
 } from '@client/src/components/ui/dialog';
import CommentInput from './CommentInput';
import CommentItemView from './CommentItem';
import ReplyInput from './ReplyInput';
import ReportDialog from './ReportDialog';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';
import {
  visitorLocalHas,
  visitorLocalToggle,
  toastVisitorLocal,
} from '@client/src/utils/visitor-mode';
import { useLoginGuard } from '@client/src/hooks/useLoginGuard';

interface CommentSectionProps {
  targetType: string;
  targetId: string;
  pageSize?: number;
  collapsible?: boolean;
  defaultCollapsed?: boolean;
  sectionId?: string;
  initialCommentCount?: number;
  large?: boolean;
}

export interface CommentSectionRef {
  expandAndScroll: () => void;
  refresh: () => Promise<void>;
}

interface ReplyInputState {
  parentId: string;
  replyToUserId?: string;
  replyToUserName?: string;
}

const CommentSection = forwardRef<CommentSectionRef, CommentSectionProps>(({
  targetType,
  targetId,
  pageSize = 10,
  collapsible = false,
  defaultCollapsed = false,
  sectionId,
  initialCommentCount = 0,
  large = false,
}, ref) => {
  const navigate = useNavigate();
  const { user, loading: authLoading, getAuthHeaders } = useAuth();
  const { allowLocalAction } = useLoginGuard();
  const { lang } = useI18n();

  const [threadList, setThreadList] = useState<CommentThreadItem[]>([]);
  const [totalComments, setTotalComments] = useState(0);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loadingComments, setLoadingComments] = useState(false);

  const [reportDialogOpen, setReportDialogOpen] = useState(false);
  const [reportTargetId, setReportTargetId] = useState('');
  const [reportReason, setReportReason] = useState('');
  const [reportSubmitting, setReportSubmitting] = useState(false);

  const [collapsed, setCollapsed] = useState(defaultCollapsed && collapsible);
  const [loaded, setLoaded] = useState(!collapsible || !defaultCollapsed);
  const displayCommentCount = loaded ? totalComments : initialCommentCount;
  const sectionRef = useRef<HTMLDivElement>(null);

  const scrollToSection = useCallback(() => {
    const el = sectionRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const docTop = rect.top + window.scrollY;
    const targetY = Math.max(0, docTop - 90);
    window.scrollTo({ top: targetY, behavior: 'smooth' });
  }, []);

  useImperativeHandle(ref, () => ({
    expandAndScroll: () => {
      setCollapsed(false);
      setLoaded(true);
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          scrollToSection();
        });
      });
    },
    refresh: async () => {
      setLoaded(true);
      setPage(1);
      setThreadList([]);
      setHasMore(true);
      await loadComments(1, true);
    },
  }));

  useEffect(() => {
    if (!sectionRef.current) return;
    const el = sectionRef.current as HTMLElement & { __expandAndScroll?: () => void };
    el.__expandAndScroll = () => {
      setCollapsed(false);
      setLoaded(true);
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          scrollToSection();
        });
      });
    };
    return () => {
      delete el.__expandAndScroll;
    };
  }, []);

  const [replyDialogOpen, setReplyDialogOpen] = useState(false);
  const [commentDialogOpen, setCommentDialogOpen] = useState(false);
  const [replyTarget, setReplyTarget] = useState<ReplyInputState | null>(null);
  const [replyPages, setReplyPages] = useState<Record<string, number>>({});
  const [replyHasMore, setReplyHasMore] = useState<Record<string, boolean>>({});

  // 游客本机点赞：localStorage 非响应式，用 tick 触发重渲染以叠加点赞态
  const [likeTick, setLikeTick] = useState(0);

  const isAdmin = user?.role === 'super_admin' || user?.role === 'admin';
  const currentUserId = user?.id;

  const loadComments = useCallback(
    async (pageNum: number, replace: boolean = false) => {
      setLoadingComments(true);
      try {
        const res: CommentListResponse = await commentsApi.getList(
          targetType,
          targetId,
          pageNum,
          pageSize,
        );
        setTotalComments(res.total);
        if (replace) {
          setThreadList(res.items);
        } else {
          setThreadList((prev) => [...prev, ...res.items]);
        }
        setHasMore(res.items.length === pageSize);
        setPage(pageNum);
      } catch (error) {
        logger.error('加载评论失败', error);
      } finally {
        setLoadingComments(false);
      }
    },
    [targetType, targetId, pageSize],
  );

  useEffect(() => {
    if (!loaded) return;
    loadComments(1, true);
  }, [loaded, loadComments]);

  // 监听外部新增评论事件（如 FAB 弹窗提交）
  useEffect(() => {
    const handleCommentAdded = (e: Event) => {
      const customEvent = e as CustomEvent<CommentThreadItem>;
      const newComment = customEvent.detail;
      if (!newComment) return;
      const newThread: CommentThreadItem = {
        ...newComment,
        replies: [],
        replyCount: 0,
      };
      setThreadList((prev) => [newThread, ...prev]);
      setTotalComments((prev) => prev + 1);
    };
    window.addEventListener('forum-comment-added', handleCommentAdded);
    return () => window.removeEventListener('forum-comment-added', handleCommentAdded);
  }, []);

  const requireLogin = (): boolean => {
    if (!user && !authLoading) {
      navigate('/auth', { state: { from: window.location.pathname } });
      return false;
    }
    return !!user;
  };

  // 游客点赞叠加：公开列表拿到的 likeCount 不含本人本机点赞，按规范第4节叠加。
  // 已登录用户原样返回（云端值为准，零回归）。likeTick 用于在本机 toggle 后触发重算。
  const overlayVisitorLike = useCallback(
    (item: CommentItem): CommentItem => {
      if (user) return item;
      void likeTick; // 依赖项：本机点赞变化后重渲染时重新读取 localStorage
      const liked = visitorLocalHas('comment_like', item.id);
      return {
        ...item,
        likedByCurrentUser: liked,
        likeCount: item.likeCount + (liked ? 1 : 0),
      };
    },
    [user, likeTick],
  );

  // 发表主评论
  const handleSubmitComment = async (
    content: string,
    mediaUrls: CommentMediaItem[],
  ) => {
    if (!requireLogin()) return;
    const newComment = await commentsApi.create(
      {
        targetType,
        targetId,
        content,
        mediaUrls: mediaUrls.length > 0 ? mediaUrls : undefined,
      },
      getAuthHeaders(),
    );
    const newThread: CommentThreadItem = {
      ...newComment,
      replies: [],
      replyCount: 0,
    };
    setThreadList((prev) => [newThread, ...prev]);
    setTotalComments((prev) => prev + 1);
    setCommentDialogOpen(false);
    toast.success(trTerm('评论成功'));
  };

  const handleOpenCommentDialog = () => {
    if (!user && !authLoading) {
      toast.info(trTerm('请先登录后发表评论'));
      navigate('/auth', { state: { from: window.location.pathname } });
      return;
    }
    if (!user) return;
    setCommentDialogOpen(true);
  };

  // 打开回复弹窗
  const handleReplyClick = (
    parentId: string,
    replyToUserId?: string,
    replyToUserName?: string,
  ) => {
    if (!user && !authLoading) {
      toast.info(trTerm('请先登录后发表回复'));
      navigate('/auth', { state: { from: window.location.pathname } });
      return;
    }
    if (!user) return;
    setReplyTarget({ parentId, replyToUserId, replyToUserName });
    setReplyDialogOpen(true);
  };

  // 提交回复
  const handleSubmitReply = async (
    content: string,
    mediaUrls: CommentMediaItem[],
  ) => {
    if (!replyTarget) return;
    const newReply = await commentsApi.create(
      {
        targetType,
        targetId,
        content,
        parentId: replyTarget.parentId,
        replyToUserId: replyTarget.replyToUserId,
        replyToUserName: replyTarget.replyToUserName,
        mediaUrls: mediaUrls.length > 0 ? mediaUrls : undefined,
      },
      getAuthHeaders(),
    );
    setThreadList((prev) =>
      prev.map((thread) =>
        thread.id === replyTarget.parentId
          ? {
              ...thread,
              replies: [...thread.replies, newReply],
              replyCount: thread.replyCount + 1,
            }
          : thread,
      ),
    );
    setReplyDialogOpen(false);
    setReplyTarget(null);
    toast.success(trTerm('回复成功'));
  };

  // 加载更多回复
  const loadMoreReplies = async (parentId: string) => {
    const currentPage = replyPages[parentId] || 1;
    const nextPage = currentPage + 1;
    try {
      const res: CommentRepliesResponse = await commentsApi.getReplies(
        parentId,
        nextPage,
        5,
      );
      setThreadList((prev) =>
        prev.map((t) =>
          t.id === parentId
            ? { ...t, replies: [...t.replies, ...res.items] }
            : t,
        ),
      );
      setReplyPages((prev) => ({ ...prev, [parentId]: nextPage }));
      setReplyHasMore((prev) => ({ ...prev, [parentId]: res.hasMore }));
    } catch (error) {
      logger.error('加载更多回复失败', error);
    }
  };

  // 点赞
  const handleLike = async (
    id: string,
    isReply: boolean,
    parentId?: string,
  ) => {
    // b类闸门：已登录→true；游客+开关开→true；游客+开关关→toast+跳/auth+false
    if (!allowLocalAction('点赞')) return;
    // 游客：仅本机 localStorage 持久化，不请求云端、不跳登录；发表/回复/举报仍需登录
    if (!user && !authLoading) {
      const next = visitorLocalToggle('comment_like', id);
      setLikeTick((t) => t + 1);
      if (next) toastVisitorLocal('comment_like');
      return;
    }
    if (!user) return;

    const updateLiked = (item: CommentItem): CommentItem => {
      if (item.id !== id) return item;
      return {
        ...item,
        likedByCurrentUser: !item.likedByCurrentUser,
        likeCount: item.likedByCurrentUser
          ? item.likeCount - 1
          : item.likeCount + 1,
      };
    };

    if (isReply && parentId) {
      setThreadList((prev) =>
        prev.map((thread) =>
          thread.id === parentId
            ? { ...thread, replies: thread.replies.map(updateLiked) }
            : thread,
        ),
      );
    } else {
      setThreadList((prev) =>
        prev.map((t) =>
          t.id === id ? (updateLiked(t) as CommentThreadItem) : t,
        ),
      );
    }

    try {
      const res = await commentsApi.toggleLike(id, getAuthHeaders());
      const applyResult = (item: CommentItem): CommentItem => {
        if (item.id !== id) return item;
        return {
          ...item,
          likedByCurrentUser: res.liked,
          likeCount: res.likeCount,
        };
      };
      if (isReply && parentId) {
        setThreadList((prev) =>
          prev.map((thread) =>
            thread.id === parentId
              ? { ...thread, replies: thread.replies.map(applyResult) }
              : thread,
          ),
        );
      } else {
        setThreadList((prev) =>
          prev.map((t) =>
            t.id === id ? (applyResult(t) as CommentThreadItem) : t,
          ),
        );
      }
    } catch (error) {
      logger.error('点赞失败', error);
    }
  };

  // 删除
  const handleDelete = async (
    id: string,
    isReply: boolean,
    parentId?: string,
  ) => {
    if (!user) return;
    const confirmed = await showConfirm(trTerm('确定要删除这条评论吗？此操作不可撤销。'));
    if (!confirmed) return;
    try {
      if (isAdmin) {
        const reason = window.prompt(trTerm('请输入删除原因（可选）：')) || '';
        await commentsApi.adminRemove(id, reason, getAuthHeaders());
      } else {
        await commentsApi.remove(id, getAuthHeaders());
      }
      toast.info(trTerm('删除成功'));

      if (isAdmin) {
        // 管理员删除：始终保留占位
        const markDeleted = (item: CommentItem): CommentItem =>
          item.id === id
            ? { ...item, isDeleted: true, content: trTerm('该评论已被删除'), mediaUrls: [] }
            : item;
        if (isReply && parentId) {
          setThreadList((prev) =>
            prev.map((thread) =>
              thread.id === parentId
                ? { ...thread, replies: thread.replies.map(markDeleted) }
                : thread,
            ),
          );
        } else {
          setThreadList((prev) =>
            prev.map((t) =>
              t.id === id
                ? ({
                    ...t,
                    isDeleted: true,
                    content: trTerm('该评论已被删除'),
                    mediaUrls: [],
                  } as CommentThreadItem)
                : t,
            ),
          );
        }
        return;
      }

      // 本人删除：根据是否有有效子回复决定移除还是占位
      if (isReply && parentId) {
        // 删除回复：无有效子回复时直接移除（回复层级只有一级，默认直接移除）
        setThreadList((prev) =>
          prev.map((thread) =>
            thread.id === parentId
              ? {
                  ...thread,
                  replies: thread.replies.filter((r: CommentItem) => r.id !== id),
                  replyCount: Math.max(0, thread.replyCount - 1),
                }
              : thread,
          ),
        );
        setTotalComments((prev) => Math.max(0, prev - 1));
      } else {
        // 删除顶层评论：先找这条 thread
        const target = threadList.find((t) => t.id === id);
        const hasActiveReplies = target?.replies.some((r: CommentItem) => !r.isDeleted) ?? false;

        if (hasActiveReplies) {
          // 仍有有效回复：主楼占位保留，回复继续展示
          setThreadList((prev) =>
            prev.map((t) =>
              t.id === id
                ? ({
                    ...t,
                    isDeleted: true,
                    content: trTerm('该评论已被删除'),
                    mediaUrls: [],
                    userId: '',
                    userName: '',
                  } as CommentThreadItem)
                : t,
            ),
          );
        } else {
          // 无有效回复：整条楼移除
          setThreadList((prev) => prev.filter((t) => t.id !== id));
        }
        setTotalComments((prev) => Math.max(0, prev - 1));
      }
    } catch (error) {
      logger.error('删除评论失败', error);
      toast.error(trTerm('删除失败'));
    }
  };

  // 举报
  const handleReportClick = (commentId: string) => {
    if (!requireLogin()) return;
    setReportTargetId(commentId);
    setReportReason('');
    setReportDialogOpen(true);
  };

  const handleReportSubmit = async () => {
    setReportSubmitting(true);
    try {
      await commentsApi.report(reportTargetId, reportReason, getAuthHeaders());
      toast.success('举报已提交，感谢您的反馈');
      setReportDialogOpen(false);
      setReportReason('');
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : trTerm('举报失败');
      toast.error(msg);
    } finally {
      setReportSubmitting(false);
    }
  };

  const handleToggleCollapse = () => {
    const next = !collapsed;
    setCollapsed(next);
    if (next === false && !loaded) {
      setLoaded(true);
    }
  };
  const handleLoadMore = () => {
    if (!loadingComments && hasMore) {
      loadComments(page + 1, false);
    }
  };

  const formatTime = (dateStr: string): string => {
    const date = new Date(dateStr);
    const now = new Date();
    const diff = now.getTime() - date.getTime();
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(diff / 3600000);
    const days = Math.floor(diff / 86400000);
    if (minutes < 1) return '刚刚';
    if (minutes < 60) return `${minutes}分钟前`;
    if (hours < 24) return `${hours}小时前`;
    if (days < 7) return `${days}天前`;
    return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
  };

  // 游客：把本机点赞态叠加到展示用列表上（已登录原样透传云端值）
  const viewThreads: CommentThreadItem[] = threadList.map((t) => ({
    ...overlayVisitorLike(t),
    replies: t.replies.map((r) => overlayVisitorLike(r)),
  }));

  return (
    <div ref={sectionRef} id={sectionId} className="rounded-2xl border border-white/10 bg-[#141838]/60 p-3 sm:p-5 backdrop-blur-sm">
      <button
        onClick={collapsible ? handleToggleCollapse : undefined}
        className={`w-full mb-3 sm:mb-4 flex items-center gap-2 text-left ${collapsible ? 'cursor-pointer hover:opacity-80' : 'cursor-default'} transition-opacity`}
        aria-expanded={!collapsed}
      >
        <h2 className={`flex-1 flex items-center gap-2 ${large ? 'text-5xl sm:text-xl' : 'text-2xl sm:text-xl'} font-semibold sm:font-bold text-white`}>
          <span className="h-5 w-1 rounded-full bg-gradient-to-b from-cyan-400 to-purple-500" />
          {trTerm('评论区')}
           {displayCommentCount > 0 && (
             <span className={`${large ? 'text-3xl sm:text-sm' : 'text-xl'} font-normal text-gray-400`}>
               ({displayCommentCount}{lang === 'en' ? '' : '条'})
             </span>
           )}
        </h2>
        {collapsible && (
          <ChevronDown
            className={`w-5 h-5 text-gray-400 transition-transform duration-200 ${collapsed ? '' : 'rotate-180'}`}
          />
        )}
      </button>

      {(!collapsible || !collapsed) && (
        <>
          {/* 写评论入口 */}
          <button
            onClick={handleOpenCommentDialog}
            className="w-full mb-3 sm:mb-4 flex items-center gap-2 px-3 py-2.5 rounded-xl border border-white/10 bg-[#0A0E27] hover:border-cyan-400/40 hover:bg-cyan-500/5 transition-all text-left group"
          >
            <MessageSquarePlus className={`${large ? 'w-9 h-9 sm:w-5 sm:h-5' : 'w-5 h-5'} text-cyan-400 flex-shrink-0`} />
            <span className={`flex-1 ${large ? 'text-4xl sm:text-base' : 'text-2xl'} text-gray-400 group-hover:text-gray-300 transition-colors`}>
              {user ? trTerm('说点什么...') : trTerm('登录后可发表评论')}
            </span>
            <span className={`px-3 py-1 rounded-lg bg-gradient-to-r from-cyan-500/20 to-purple-500/20 text-cyan-300 ${large ? 'text-3xl sm:text-sm' : 'text-xl'} font-medium`}>
              {trTerm('发表评论')}
            </span>
          </button>

          {/* 评论列表 */}
      <div className="space-y-4 sm:space-y-6">
        {threadList.length === 0 && !loadingComments ? (
          <div className="text-center py-8">
            <MessageCircle className={`${large ? 'w-20 h-20 sm:w-8 sm:h-8' : 'w-12 h-12 sm:w-8 sm:h-8'} text-gray-700 mx-auto mb-2`} />
            <p className={`${large ? 'text-4xl sm:text-sm' : 'text-2xl sm:text-sm'} text-gray-500`}>{trTerm('暂无评论，快来抢沙发吧~')}</p>
          </div>
        ) : (
          viewThreads.map((thread: CommentThreadItem) => (
              <div
                key={thread.id}
                className="border-b border-white/5 pb-3 sm:pb-4 last:border-b-0 last:pb-0"
              >
              <CommentItemView
                item={thread}
                isReply={false}
                currentUserId={currentUserId}
                isAdmin={isAdmin}
                authorAvatarUrl={user?.id === thread.userId ? user.avatarUrl : null}
                onLike={() => handleLike(thread.id, false)}
                onReply={() => handleReplyClick(thread.id)}
                onDelete={() => handleDelete(thread.id, false)}
                onReport={() => handleReportClick(thread.id)}
                formatTime={formatTime}
                large={large}
              />

              {/* 回复列表 */}
              {thread.replies.length > 0 && (
                <div className="mt-2 sm:mt-3 ml-2 sm:ml-3 pl-3 sm:pl-4 border-l border-white/10 space-y-2 sm:space-y-3">
                  {thread.replies.map((reply: CommentItem) => (
                    <CommentItemView
                      key={reply.id}
                      item={reply}
                      isReply
                      currentUserId={currentUserId}
                      isAdmin={isAdmin}
                      authorAvatarUrl={user?.id === reply.userId ? user.avatarUrl : null}
                      onLike={() => handleLike(reply.id, true, thread.id)}
                      onReply={() =>
                        handleReplyClick(thread.id, reply.userId, reply.userName)
                      }
                      onDelete={() => handleDelete(reply.id, true, thread.id)}
                      onReport={() => handleReportClick(reply.id)}
                      formatTime={formatTime}
                      large={large}
                    />
                  ))}

                  {replyHasMore[thread.id] && (
                    <button
                      onClick={() => loadMoreReplies(thread.id)}
                     className={`flex items-center gap-1 ${large ? 'text-3xl sm:text-sm' : 'text-2xl sm:text-sm'} text-cyan-400 hover:text-cyan-300 transition-colors`}
                   >
                     <ChevronDown className={`${large ? 'w-9 h-9 sm:w-4 sm:h-4' : 'w-5 h-5 sm:w-4 sm:h-4'}`} />
                       {trTerm('查看更多回复')}
                    </button>
                  )}
                </div>
              )}

            </div>
          ))
        )}

        {loadingComments && (
          <p className={`text-center ${large ? 'text-3xl sm:text-sm' : 'text-2xl sm:text-sm'} text-gray-500 py-2`}>{trTerm('加载中...')}</p>
        )}
        {!loadingComments && hasMore && (
          <button
            onClick={handleLoadMore}
            className={`w-full py-2 ${large ? 'text-3xl sm:text-sm' : 'text-2xl sm:text-sm'} text-cyan-400 hover:text-cyan-300 transition-colors`}
          >
            {trTerm('加载更多评论')}
          </button>
        )}
        {!loadingComments && !hasMore && threadList.length > 0 && (
          <p className={`text-center ${large ? 'text-3xl sm:text-sm' : 'text-2xl sm:text-sm'} text-gray-600 py-2`}>
             {trTerm('没有更多评论了')}
           </p>
        )}
      </div>

      {/* 主评论对话框 */}
      <Dialog open={commentDialogOpen} onOpenChange={setCommentDialogOpen}>
        <DialogContent className="fixed bottom-0 left-0 right-0 translate-x-0 translate-y-0 mx-auto w-full max-w-[560px] max-h-[70vh] sm:max-h-[70vh] h-[80vh] sm:h-auto overflow-y-auto rounded-t-2xl rounded-b-none border-white/10 bg-[#141838] text-white p-4 pt-8">
          <CommentInput
            isLoggedIn={!!user}
            variant="dialog"
            onSubmit={handleSubmitComment}
          />
        </DialogContent>
      </Dialog>

      {/* 回复对话框 */}
      <Dialog open={replyDialogOpen} onOpenChange={setReplyDialogOpen}>
        <DialogContent className="fixed bottom-0 left-0 right-0 translate-x-0 translate-y-0 mx-auto w-full max-w-[560px] max-h-[70vh] sm:max-h-[70vh] h-[80vh] sm:h-auto overflow-y-auto rounded-t-2xl rounded-b-none border-white/10 bg-[#141838] text-white p-4 pt-8">
          <ReplyInput
            variant="dialog"
            replyToUserName={replyTarget?.replyToUserName}
            onSubmit={handleSubmitReply}
            onCancel={() => {
              setReplyDialogOpen(false);
              setReplyTarget(null);
            }}
          />
        </DialogContent>
      </Dialog>

        {/* 举报对话框 */}
      <ReportDialog
        open={reportDialogOpen}
        onOpenChange={setReportDialogOpen}
        reason={reportReason}
        onReasonChange={setReportReason}
        submitting={reportSubmitting}
        onSubmit={handleReportSubmit}
      />
        </>
      )}
    </div>
  );
});

export default CommentSection;
