import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import {
  Users,
  Search,
  VolumeX,
  Volume2,
  Ban,
  Shield,
  ChevronLeft,
  ChevronRight,
  Loader2,
} from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import {
  getUserList,
  muteUser,
  unmuteUser,
  banUser,
  unbanUser,
  setUserRole,
} from '@client/src/api/admin';
import type { AdminUserItem } from '@shared/api.interface';
import { toast } from 'sonner';
import { showConfirm } from '@lark-apaas/client-toolkit';
import { useAuth } from '@client/src/context/AuthContext';

const MUTE_OPTIONS = [
  { label: '1 天', hours: 24 },
  { label: '7 天', hours: 168 },
  { label: '30 天', hours: 720 },
  { label: '永久', hours: 0 },
];

function getRoleLabel(role: AdminUserItem['role']): string {
  switch (role) {
    case 'super_admin':
      return '超级管理员';
    case 'admin':
      return '管理员';
    default:
      return '普通用户';
  }
}

function getRoleColor(role: AdminUserItem['role']): string {
  switch (role) {
    case 'super_admin':
      return 'bg-pink-500/20 text-pink-300 border-pink-400/50';
    case 'admin':
      return 'bg-purple-500/20 text-purple-300 border-purple-400/50';
    default:
      return 'bg-cyan-500/20 text-cyan-300 border-cyan-400/50';
  }
}

function getStatusLabel(status: AdminUserItem['status']): string {
  switch (status) {
    case 'active':
      return '正常';
    case 'muted':
      return '禁言中';
    case 'banned':
      return '已封禁';
    default:
      return status;
  }
}

function getStatusColor(status: AdminUserItem['status']): string {
  switch (status) {
    case 'active':
      return 'bg-emerald-500/20 text-emerald-300 border-emerald-400/50';
    case 'muted':
      return 'bg-orange-500/20 text-orange-300 border-orange-400/50';
    case 'banned':
      return 'bg-red-500/20 text-red-300 border-red-400/50';
    default:
      return 'bg-white/10 text-white/70 border-white/20';
  }
}

const AdminUsersPage: React.FC = () => {
  const { user: currentUser } = useAuth();
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(true);
    return () => setMounted(false);
  }, []);
  const [keyword, setKeyword] = useState('');
  const [searchInput, setSearchInput] = useState('');
  const [page, setPage] = useState(1);
  const pageSize = 10;
  const [items, setItems] = useState<AdminUserItem[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  // 禁言弹窗
  const [muteDialogUserId, setMuteDialogUserId] = useState<string | null>(null);
  const [muteHours, setMuteHours] = useState(24);
  const [muteReason, setMuteReason] = useState('');

  const fetchList = useCallback(async () => {
    setLoading(true);
    try {
      const data = await getUserList({
        keyword: keyword || undefined,
        page,
        pageSize,
      });
      setItems(data.items);
      setTotal(data.total);
    } catch (error) {
      logger.error('加载用户列表失败', error);
      toast('加载失败，请刷新重试');
    } finally {
      setLoading(false);
    }
  }, [keyword, page]);

  useEffect(() => {
    fetchList();
  }, [fetchList]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setKeyword(searchInput.trim());
    setPage(1);
  };

  const doMute = async () => {
    if (!muteDialogUserId) return;
    if (!await showConfirm(`确定对该用户禁言 ${muteHours === 0 ? '永久' : `${muteHours} 小时`}吗？`)) return;
    setActionLoading(muteDialogUserId);
    try {
      await muteUser(muteDialogUserId, muteHours, muteReason || undefined);
      toast('禁言成功');
      setMuteDialogUserId(null);
      setMuteReason('');
      fetchList();
    } catch (error) {
      logger.error('禁言失败', error);
      toast('操作失败，请重试');
    } finally {
      setActionLoading(null);
    }
  };

  const doUnmute = async (user: AdminUserItem) => {
    if (!await showConfirm('确定解除该用户的禁言吗？')) return;
    setActionLoading(user.id);
    try {
      await unmuteUser(user.id);
      toast('已解除禁言');
      fetchList();
    } catch (error) {
      logger.error('解除禁言失败', error);
      toast('操作失败，请重试');
    } finally {
      setActionLoading(null);
    }
  };

  const doBan = async (user: AdminUserItem) => {
    if (!await showConfirm('确定封禁该用户吗？封禁后用户将无法登录。')) return;
    setActionLoading(user.id);
    try {
      await banUser(user.id);
      toast('已封禁');
      fetchList();
    } catch (error) {
      logger.error('封禁失败', error);
      toast('操作失败，请重试');
    } finally {
      setActionLoading(null);
    }
  };

  const doUnban = async (user: AdminUserItem) => {
    if (!await showConfirm('确定解封该用户吗？')) return;
    setActionLoading(user.id);
    try {
      await unbanUser(user.id);
      toast('已解封');
      fetchList();
    } catch (error) {
      logger.error('解封失败', error);
      toast('操作失败，请重试');
    } finally {
      setActionLoading(null);
    }
  };

  const isSuperAdmin = currentUser?.role === 'super_admin';

  const doSetAdmin = async (user: AdminUserItem) => {
    if (!await showConfirm(`确定将用户「${user.nickname}」设为管理员吗？`)) return;
    setActionLoading(user.id);
    try {
      await setUserRole(user.id, 'admin');
      toast('已设为管理员');
      fetchList();
    } catch (error) {
      logger.error('设置管理员失败', error);
      toast('操作失败，请重试');
    } finally {
      setActionLoading(null);
    }
  };

  const doRevokeAdmin = async (user: AdminUserItem) => {
    if (!await showConfirm(`确定取消用户「${user.nickname}」的管理员权限吗？`)) return;
    setActionLoading(user.id);
    try {
      await setUserRole(user.id, 'user');
      toast('已取消管理员权限');
      fetchList();
    } catch (error) {
      logger.error('取消管理员失败', error);
      toast('操作失败，请重试');
    } finally {
      setActionLoading(null);
    }
  };

  const totalPages = Math.max(1, Math.ceil(total / pageSize));

  return (
    <div className="min-h-[600px] px-4 py-6">
      {/* 标题 + 搜索 */}
      <div className="mb-6 flex flex-wrap items-center gap-4">
        <div className="flex items-center gap-3">
          <Users className="h-7 w-7 text-cyan-400" />
          <h1 className="text-2xl font-black text-white tracking-wide">
            用户管理
          </h1>
        </div>
        <form onSubmit={handleSearch} className="ml-auto flex items-center">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/40" />
            <input
              type="text"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              placeholder="搜索用户名 / 昵称"
              className="h-9 w-64 rounded-lg border border-white/10 bg-[#141838]/70 pl-9 pr-4 text-sm text-white placeholder-white/30 outline-none transition-all focus:border-cyan-400/50 focus:shadow-[0_0_12px_rgba(34_211_238_0.25)]"
            />
          </div>
          <button
            type="submit"
            className="ml-2 h-9 rounded-lg border border-cyan-400/40 bg-cyan-400/10 px-4 text-sm font-medium text-cyan-300 transition-all hover:bg-cyan-400/20 hover:shadow-[0_0_12px_rgba(34_211_238_0.4)]"
          >
            搜索
          </button>
        </form>
      </div>

      {/* 列表 */}
      {loading ? (
        <div className="flex items-center justify-center py-20">
          <Loader2 className="h-8 w-8 animate-spin text-cyan-400" />
        </div>
      ) : (items || []).length === 0 ? (
        <div className="rounded-xl border border-white/10 bg-[#141838]/40 py-20 text-center text-white/40">
          暂无用户
        </div>
      ) : (
        <div className="overflow-hidden rounded-xl border border-cyan-400/20 bg-[#141838]/50 backdrop-blur-sm">
          {/* 表头 */}
          <div className="grid grid-cols-12 gap-2 border-b border-white/10 bg-white/[0.02] px-4 py-3 text-sm font-semibold text-white/60">
            <div className="col-span-3">用户</div>
            <div className="col-span-2">角色</div>
            <div className="col-span-2">状态</div>
            <div className="col-span-2">注册时间</div>
            <div className="col-span-3 text-right">操作</div>
          </div>
          {/* 行 */}
          {(items || []).map((user) => (
            <div
              key={user.id}
              className="grid grid-cols-12 items-center gap-2 border-b border-white/5 px-4 py-3.5 transition-colors last:border-b-0 hover:bg-white/[0.03]"
            >
              <div className="col-span-3">
                <div className="text-base font-semibold text-white/90">{user.nickname}</div>
                <div className="text-sm text-white/40">@{user.username}</div>
              </div>
              <div className="col-span-2">
                <span
                  className={`inline-flex rounded-md border px-2 py-0.5 text-sm font-semibold ${getRoleColor(
                    user.role,
                  )}`}
                >
                  {getRoleLabel(user.role)}
                </span>
              </div>
              <div className="col-span-2">
                <span
                  className={`inline-flex rounded-md border px-2 py-0.5 text-sm font-semibold ${getStatusColor(
                    user.status,
                  )}`}
                >
                  {getStatusLabel(user.status)}
                </span>
                {user.status === 'muted' && user.muteUntil && (
                  <div className="mt-1 text-sm text-orange-300/70">
                    至 {new Date(user.muteUntil).toLocaleString('zh-CN', {
                      month: '2-digit',
                      day: '2-digit',
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                  </div>
                )}
              </div>
              <div className="col-span-2 text-sm text-white/60">
                {new Date(user.createdAt).toLocaleString('zh-CN', {
                  month: '2-digit',
                  day: '2-digit',
                  hour: '2-digit',
                  minute: '2-digit',
                })}
              </div>
              <div className="col-span-3 flex flex-wrap justify-end gap-1.5">
                {user.role === 'super_admin' ? (
                  <span className="inline-flex items-center gap-1 rounded-md border border-pink-400/40 bg-pink-400/10 px-2.5 py-1 text-sm font-semibold text-pink-300">
                    <Shield className="h-3 w-3" />
                    超级管理员
                  </span>
                ) : (
                  <>
                    {isSuperAdmin && (
                      <>
                        {user.role === 'user' ? (
                          <button
                            onClick={() => doSetAdmin(user)}
                            disabled={actionLoading === user.id}
                            className="flex items-center gap-1 rounded-md border border-purple-400/40 bg-purple-400/10 px-2.5 py-1 text-sm font-medium text-purple-300 transition-all hover:bg-purple-400/20 disabled:opacity-50"
                          >
                            <Shield className="h-3 w-3" />
                            设为管理员
                          </button>
                        ) : (
                          <button
                            onClick={() => doRevokeAdmin(user)}
                            disabled={actionLoading === user.id}
                            className="flex items-center gap-1 rounded-md border border-gray-400/40 bg-gray-400/10 px-2.5 py-1 text-sm font-medium text-gray-300 transition-all hover:bg-gray-400/20 disabled:opacity-50"
                          >
                            <Shield className="h-3 w-3" />
                            取消管理员
                          </button>
                        )}
                      </>
                    )}
                    {user.status === 'active' && (
                      <>
                    <button
                      onClick={() => {
                        setMuteDialogUserId(user.id);
                        setMuteHours(24);
                        setMuteReason('');
                      }}
                      disabled={actionLoading === user.id}
                      className="flex items-center gap-1 rounded-md border border-orange-400/40 bg-orange-400/10 px-2.5 py-1 text-sm font-medium text-orange-300 transition-all hover:bg-orange-400/20 disabled:opacity-50"
                    >
                      <VolumeX className="h-3 w-3" />
                      禁言
                    </button>
                    <button
                      onClick={() => doBan(user)}
                      disabled={actionLoading === user.id || user.role !== 'user'}
                      title={user.role !== 'user' ? '管理员不可封禁' : ''}
                      className="flex items-center gap-1 rounded-md border border-red-400/40 bg-red-400/10 px-2.5 py-1 text-sm font-medium text-red-300 transition-all hover:bg-red-400/20 disabled:opacity-50"
                    >
                      <Ban className="h-3 w-3" />
                      封禁
                    </button>
                  </>
                )}
                {user.status === 'muted' && (
                  <button
                    onClick={() => doUnmute(user)}
                    disabled={actionLoading === user.id}
                    className="flex items-center gap-1 rounded-md border border-emerald-400/40 bg-emerald-400/10 px-2.5 py-1 text-sm font-medium text-emerald-300 transition-all hover:bg-emerald-400/20 disabled:opacity-50"
                  >
                    <Volume2 className="h-3 w-3" />
                    解除禁言
                  </button>
                )}
                {user.status === 'banned' && (
                  <button
                    onClick={() => doUnban(user)}
                    disabled={actionLoading === user.id}
                    className="flex items-center gap-1 rounded-md border border-emerald-400/40 bg-emerald-400/10 px-2.5 py-1 text-sm font-medium text-emerald-300 transition-all hover:bg-emerald-400/20 disabled:opacity-50"
                  >
                    <Shield className="h-3 w-3" />
                    解封
                  </button>
                )}
                  </>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* 分页 */}
      {total > 0 && (
        <div className="mt-6 flex items-center justify-center gap-2">
          <button
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page === 1}
            className="flex h-8 w-8 items-center justify-center rounded-md border border-white/10 bg-[#141838]/50 text-white/70 transition-all hover:border-cyan-400/40 hover:text-white disabled:opacity-30"
          >
            <ChevronLeft className="h-4 w-4" />
          </button>
          <span className="px-3 text-sm text-white/60">
            第 <span className="text-cyan-300">{page}</span> / {totalPages} 页 · 共 {total} 条
          </span>
          <button
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page === totalPages}
            className="flex h-8 w-8 items-center justify-center rounded-md border border-white/10 bg-[#141838]/50 text-white/70 transition-all hover:border-cyan-400/40 hover:text-white disabled:opacity-30"
          >
            <ChevronRight className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* 禁言弹窗 */}
      {muteDialogUserId && mounted ? createPortal(
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <div className="w-[400px] rounded-xl border border-orange-400/40 bg-[#141838] p-6 shadow-[0_0_40px_rgba(251_146_60_0.25)]">
            <h3 className="mb-4 text-lg font-bold text-orange-300">禁言用户</h3>
            <div className="mb-4">
              <label className="mb-2 block text-sm text-white/70">禁言时长</label>
              <div className="grid grid-cols-2 gap-2">
                {MUTE_OPTIONS.map((opt) => (
                  <button
                    key={opt.hours}
                    type="button"
                    onClick={() => setMuteHours(opt.hours)}
                    className={`rounded-lg border px-4 py-2.5 text-sm font-semibold transition-all ${
                      muteHours === opt.hours
                        ? 'border-orange-400/70 bg-orange-500/15 text-orange-200 shadow-[0_0_16px_rgba(251_146_60_0.4)]'
                        : 'border-white/10 bg-[#0f1330]/60 text-white/70 hover:border-orange-400/40'
                    }`}
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
            </div>
            <div className="mb-6">
              <label className="mb-2 block text-sm text-white/70">禁言原因（可选）</label>
              <input
                type="text"
                value={muteReason}
                onChange={(e) => setMuteReason(e.target.value)}
                placeholder="请输入禁言原因"
                className="h-9 w-full rounded-lg border border-white/10 bg-[#0f1330]/60 px-3 text-sm text-white placeholder-white/30 outline-none transition-all focus:border-orange-400/50"
              />
            </div>
            <div className="flex justify-end gap-2">
              <button
                onClick={() => setMuteDialogUserId(null)}
                className="rounded-md border border-white/10 bg-white/5 px-4 py-2 text-sm text-white/70 transition-all hover:bg-white/10"
              >
                取消
              </button>
              <button
                onClick={doMute}
                disabled={actionLoading === muteDialogUserId}
                className="rounded-md bg-gradient-to-r from-orange-500 to-red-500 px-4 py-2 text-sm font-semibold text-white shadow-[0_0_16px_rgba(251_146_60_0.5)] transition-all hover:shadow-[0_0_24px_rgba(251_146_60_0.7)] disabled:opacity-50"
              >
                确认禁言
              </button>
            </div>
          </div>
        </div>,
        document.body,
      ) : null}
    </div>
  );
};

export default AdminUsersPage;
