import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';
import type {
  FavoriteListResponse,
  ToggleFavoriteResponse,
  BatchFavoriteResponse,
} from '@shared/api.interface';

export type FavoriteTargetType = 'player' | 'coach' | 'pack' | 'forum_post';

export async function checkFavorite(
  targetType: FavoriteTargetType,
  targetId: string,
): Promise<{ favorited: boolean }> {
  const res = await axiosForBackend.get('/api/favorites/check', {
    params: { targetType, targetId },
  });
  return res.data;
}

export async function toggleFavorite(
  targetType: FavoriteTargetType,
  targetId: string,
): Promise<ToggleFavoriteResponse> {
  const res = await axiosForBackend.post('/api/favorites', { targetType, targetId });
  return res.data;
}

export async function getMyFavorites(params: {
  targetType?: FavoriteTargetType;
  page?: number;
  pageSize?: number;
}): Promise<FavoriteListResponse> {
  const res = await axiosForBackend.get('/api/favorites/my', { params });
  return res.data;
}

export async function batchCheckFavorites(
  targetType: FavoriteTargetType,
  targetIds: string[],
): Promise<BatchFavoriteResponse> {
  const res = await axiosForBackend.post('/api/favorites/batch', {
    targetType,
    targetIds,
  });
  return res.data;
}
