import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';
import type { PackListResponse, PackDetailResponse } from '@shared/api.interface';

 export async function getPackList(params?: { server?: string; keyword?: string }): Promise<PackListResponse> {
   const response = await axiosForBackend.get<PackListResponse>('/api/packs', {
     params,
   });
   return response.data;
 }

export async function getPackDetail(id: string): Promise<PackDetailResponse> {
  const response = await axiosForBackend.get<PackDetailResponse>(`/api/packs/${id}`);
  return response.data;
}
