import React from 'react';
import { User } from 'lucide-react';

interface UserAvatarProps {
  avatarUrl?: string | null;
  userName?: string;
  size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
  className?: string;
}

export const UserAvatar: React.FC<UserAvatarProps> = ({
  avatarUrl,
  userName,
  size = 'md',
  className = '',
}) => {
  const sizeClass = {
    xs: 'h-5 w-5 sm:h-4 sm:w-4',
    sm: 'h-7 w-7 sm:h-6 sm:w-6',
    md: 'h-8 w-8 sm:h-7 sm:w-7',
    lg: 'h-10 w-10 sm:h-9 sm:w-9',
    xl: 'h-12 w-12 sm:h-11 sm:w-11',
  }[size];

  const iconSize = {
    xs: 'h-2.5 w-2.5 sm:h-2 sm:w-2',
    sm: 'h-3.5 w-3.5 sm:h-3 sm:w-3',
    md: 'h-4 w-4 sm:h-3.5 sm:w-3.5',
    lg: 'h-5 w-5 sm:h-4.5 sm:w-4.5',
    xl: 'h-6 w-6 sm:h-5 sm:w-5',
  }[size];

  return (
    <div
      className={`flex items-center justify-center rounded-full bg-gradient-to-br from-cyan-500 to-purple-500 overflow-hidden flex-shrink-0 ${sizeClass} ${className}`}
      title={userName}
    >
      {avatarUrl ? (
        <img
          src={avatarUrl}
          alt={userName || '用户头像'}
          className="h-full w-full object-cover"
          loading="lazy"
        />
      ) : (
        <User className={`${iconSize} text-white`} />
      )}
    </div>
  );
};

export default UserAvatar;
