import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';
import type {
  NotificationListResponse,
  UnreadCountResponse,
} from '@shared/api.interface';

export async function getNotifications(params: {
  page?: number;
  pageSize?: number;
  unreadOnly?: boolean;
}): Promise<NotificationListResponse> {
  const res = await axiosForBackend.get('/api/notifications', { params });
  return res.data;
}

export async function getUnreadCount(): Promise<UnreadCountResponse> {
  const res = await axiosForBackend.get('/api/notifications/unread-count');
  return res.data;
}

export async function markAsRead(id: string): Promise<{ success: boolean }> {
  const res = await axiosForBackend.post(`/api/notifications/${id}/read`);
  return res.data;
}

export async function markAllAsRead(): Promise<{ success: boolean }> {
  const res = await axiosForBackend.post('/api/notifications/read-all');
  return res.data;
}
