// 中文名空间不足时：优先保留“·”后的姓氏；名只留头一个字、中间省略，再不够只显示姓氏
const TruncatingZhName: React.FC<{ full: string; className?: string }> = ({ full, className }) => {
  const ref = React.useRef<HTMLParagraphElement>(null);
  const s = String(full || '');
  const parts = s.split(/[·•・]/);
  const hasSur = parts.length >= 2;
  const sur = hasSur ? parts.slice(1).join('·') : '';
  const variants = hasSur ? [s, `${parts[0].charAt(0)}…${sur}`, sur] : [s];
  const [level, setLevel] = React.useState(0);
  React.useLayoutEffect(() => setLevel(0), [s]);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (el && el.scrollWidth > el.clientWidth) setLevel((l) => Math.min(l + 1, variants.length - 1));
  });
  return (
    <p ref={ref} title={s} className={`${className || ''} truncate text-left`}>
      {variants[Math.min(level, variants.length - 1)]}
    </p>
  );
};

