const FLAG_ID_REGEX = /(?:Nationality|flags)\/(\d+)\.png/;

export function getNationalityName(avatarUrl: string | null | undefined): string {
  if (!avatarUrl) return '';
  const match = avatarUrl.match(FLAG_ID_REGEX);
  if (!match) return '';
  return NATIONALITY_MAP[match[1]] || '';
}

export function getNationalityFlagId(avatarUrl: string | null | undefined): string {
  if (!avatarUrl) return '';
  const match = avatarUrl.match(FLAG_ID_REGEX);
  return match ? match[1] : '';
}

