const NATIONAL_TEAM_LEAGUES = [
  'European Cup',
  'American Cup',
  'CAF AFRICA CUP OF NATIONS 25',
  'AFC Asian QualifiersTM',
];

export function isNationalTeamLeague(league: string | null | undefined): boolean {
  if (!league) return false;
  return NATIONAL_TEAM_LEAGUES.includes(league);
}

export function getCountryCnName(englishName: string | null | undefined): string {
  if (!englishName) return '';
  return EN_TO_CN_COUNTRY[englishName] || '';
}
