export async function getPlayers(
  params: PlayerListQuery,
): Promise<PlayerListResponse> {
  try {
    const {
      playerTypes,
      positions,
      attackStyles,
      defenseStyles,
      aiStyles,
      commonSkills,
      stSkills,
      teamSeasons,
      radarMins,
      excludeStandard,
      ...rest
    } = params;
    const queryParams: Record<string, string | number | undefined> = {
      ...rest,
    };
    if (playerTypes && playerTypes.length > 0) {
      queryParams.playerTypes = playerTypes.join(',');
    }
    if (positions && positions.length > 0) {
      queryParams.positions = positions.join(',');
    }
    if (attackStyles && attackStyles.length > 0) {
      queryParams.attackStyles = attackStyles.join(',');
    }
    if (defenseStyles && defenseStyles.length > 0) {
      queryParams.defenseStyles = defenseStyles.join(',');
    }
    if (aiStyles && aiStyles.length > 0) {
      queryParams.aiStyles = aiStyles.join(',');
    }
    if (commonSkills && commonSkills.length > 0) {
      queryParams.commonSkills = commonSkills.join(',');
    }
    if (stSkills && stSkills.length > 0) {
      queryParams.stSkills = stSkills.join(',');
    }
    if (teamSeasons && teamSeasons.length > 0) {
      queryParams.teamSeasons = teamSeasons.join(',');
    }
    if (excludeStandard) {
      queryParams.excludeStandard = 'true';
    }
    if (radarMins) {
      const radarKeys = ['attack', 'passing', 'shooting', 'defending', 'speed'];
      for (const key of radarKeys) {
        const val = radarMins[key];
        if (val !== undefined && val !== '') {
          queryParams[`radarMin_${key}`] = val;
        }
      }
    }
    const response = await axiosForBackend.get<PlayerListResponse>(
      '/api/players',
      { params: queryParams },
    );
    return response.data;
  } catch (error) {
    logger.error('获取球员列表失败', error);
    throw error;
  }
}

export async function getAllPlayers(
   params: {
     keyword?: string;
     league?: string;
     club?: string;
     playerType?: string;
     playerTypes?: string[];
     excludeStandard?: boolean;
   } = {},
): Promise<PlayerListAllResponse> {
  try {
     const { playerTypes, excludeStandard, ...rest } = params;
     const queryParams: Record<string, string | string[] | undefined> = { ...rest };
     if (playerTypes && playerTypes.length > 0) {
       queryParams.playerTypes = playerTypes.join(',');
     }
     if (excludeStandard) {
       queryParams.excludeStandard = 'true';
     }
    const response = await axiosForBackend.get<PlayerListAllResponse>(
      '/api/players/all',
      { params: queryParams },
    );
    return response.data;
  } catch (error) {
    logger.error('获取全部球员数据失败', error);
    throw error;
  }
}

