export type VoteType = 'like' | 'dislike';

export interface MediaItem {
  url: string;
  type: 'image' | 'video';
  filename: string;
  size: number;
}

export type BoardKey = 'news' | 'international' | 'cn' | 'bug' | 'following';

export interface ForumPost {
  id: string;
  board: string;
  title: string;
  content: string;
  userId: string;
  userName: string;
  likeCount: number;
  dislikeCount: number;
  commentCount: number;
  createdAt: string;
  mediaUrls: MediaItem[];
  isDeleted: boolean;
  isPinned: boolean;
  pinnedAt?: string;
}

export interface ForumPostDetail extends ForumPost {
  userVote: VoteType | null;
}

export interface ForumComment {
  id: string;
  postId: string;
  userId: string;
  userName: string;
  content: string;
  likeCount: number;
  createdAt: string;
  mediaUrls: MediaItem[];
  isDeleted: boolean;
}

export interface ForumPostListResponse {
  items: ForumPost[];
  total: number;
  page: number;
  pageSize: number;
}

export interface ForumCommentListResponse {
  items: ForumComment[];
  total: number;
  page: number;
  pageSize: number;
}

export interface CreatePostDto {
  title: string;
  content: string;
  board: BoardKey;
  mediaUrls?: MediaItem[];
}

export interface CreateCommentDto {
  content: string;
  mediaUrls?: MediaItem[];
}

export interface VoteResponse {
  likeCount: number;
  dislikeCount: number;
  userVote: VoteType | null;
}

export interface ReportDto {
  targetType: 'post' | 'comment';
  targetId: string;
  reason: string;
}

export async function getPostList(
  params: {
    board?: BoardKey;
    page?: number;
    pageSize?: number;
  },
  headers?: Record<string, string>,
  timeout?: number,
): Promise<ForumPostListResponse> {
  try {
    const response = await axiosForBackend.get<ForumPostListResponse>(
      '/api/forum/posts',
      { params, headers, timeout: timeout ?? 10000 },
    );
    return response.data;
  } catch (error) {
    logger.error('获取帖子列表失败', error);
    throw error;
  }
}

export async function getHotPosts(
  params?: { minLikes?: number; limit?: number },
): Promise<ForumPostListResponse> {
  try {
    const response = await axiosForBackend.get<ForumPostListResponse>(
      '/api/forum/posts/hot',
      { params, timeout: 10000 },
    );
    const d = response.data;
    // 补全媒体相对路径，保证 APP（localhost 源）内能加载
    return {
      ...d,
      items: (d.items || []).map((p) => ({
        ...p,
        mediaUrls: (p.mediaUrls || []).map((m) =>
          m.url ? { ...m, url: resolveBackendAsset(m.url) } : m,
        ),
      })),
    };
  } catch (error) {
    logger.error('获取热门帖子失败', error);
    throw error;
  }
}

