const VISITOR_KEY = 'pes_player_visitor_id';
const VISITOR_NAME_KEY = 'pes_player_visitor_name';

export function getVisitorId(): string {
  if (typeof window === 'undefined') return '';
  let visitorId = window.localStorage.getItem(VISITOR_KEY);
  if (!visitorId) {
    visitorId = `visitor_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
    window.localStorage.setItem(VISITOR_KEY, visitorId);
  }
  return visitorId;
}

export function getVisitorName(): string {
  if (typeof window === 'undefined') return '匿名球迷';
  let name = window.localStorage.getItem(VISITOR_NAME_KEY);
  if (!name) {
    const suffix = Math.floor(Math.random() * 10000).toString().padStart(4, '0');
    name = `球迷${suffix}`;
    window.localStorage.setItem(VISITOR_NAME_KEY, name);
  }
  return name;
}
