import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { X, ChevronLeft, ChevronRight, Play } from 'lucide-react';

import type { MediaItem } from '@client/src/api/forum';
import { Image } from '@client/src/components/ui/image';
import ZoomableImage from '@client/src/components/ZoomableImage';

interface MediaDisplayProps {
  mediaList: MediaItem[];
  size?: 'normal' | 'small';
}

const MediaDisplay: React.FC<MediaDisplayProps> = ({
  mediaList,
  size = 'normal',
}) => {
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(true);
    return () => setMounted(false);
  }, []);
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null);

  const images = mediaList.filter((m) => m.type === 'image');
  const videos = mediaList.filter((m) => m.type === 'video');

  const openLightbox = (index: number) => {
    setLightboxIndex(index);
  };

  const closeLightbox = useCallback(() => {
    setLightboxIndex(null);
  }, []);

  const prevImage = useCallback(() => {
    setLightboxIndex((prev) =>
      prev === null ? null : (prev - 1 + images.length) % images.length,
    );
  }, [images.length]);

  const nextImage = useCallback(() => {
    setLightboxIndex((prev) =>
      prev === null ? null : (prev + 1) % images.length,
    );
  }, [images.length]);

  // 键盘导航
  useEffect(() => {
    if (lightboxIndex === null) return;
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') closeLightbox();
      if (e.key === 'ArrowLeft') prevImage();
      if (e.key === 'ArrowRight') nextImage();
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [lightboxIndex, closeLightbox, prevImage, nextImage]);

  // 禁止背景滚动
  useEffect(() => {
    if (lightboxIndex !== null) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => {
      document.body.style.overflow = '';
    };
  }, [lightboxIndex]);

  const getImageGridClass = (count: number): string => {
    if (count === 0) return '';
    if (count === 1) return 'grid-cols-1 max-w-md';
    if (count <= 4) return 'grid-cols-2 max-w-lg';
    return 'grid-cols-3 max-w-2xl';
  };

  const smallImageClass = 'w-20 h-20';

  const renderImageGrid = () => {
    if (images.length === 0) return null;

    if (size === 'small') {
      return (
        <div className="flex flex-wrap gap-2">
          {images.map((img, idx) => (
            <button
              key={idx}
              onClick={() => openLightbox(idx)}
              className={`overflow-hidden rounded-lg border border-white/10 ${smallImageClass} transition-all hover:border-cyan-400/40`}
            >
              <Image
                src={img.url}
                alt={img.filename}
                className="h-full w-full object-cover"
                loading="lazy"
              />
            </button>
          ))}
        </div>
      );
    }

    return (
      <div className={`grid gap-2 ${getImageGridClass(images.length)}`}>
        {images.map((img, idx) => (
          <button
            key={idx}
            onClick={() => openLightbox(idx)}
            className="group relative aspect-square overflow-hidden rounded-lg border border-white/10 transition-all hover:border-cyan-400/40"
          >
            <Image
              src={img.url}
              alt={img.filename}
              className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-105"
              loading="lazy"
            />
          </button>
        ))}
      </div>
    );
  };

  const renderVideos = () => {
    if (videos.length === 0) return null;

    if (size === 'small') {
      return (
        <div className="space-y-2">
          {videos.map((video, idx) => (
            <div
              key={idx}
              className="relative aspect-video w-40 overflow-hidden rounded-lg border border-white/10 bg-black"
            >
              <Play className="absolute left-1/2 top-1/2 h-8 w-8 -translate-x-1/2 -translate-y-1/2 text-white/80" />
              <video
                src={video.url}
                preload="metadata"
                controls
                className="h-full w-full object-contain"
              />
            </div>
          ))}
        </div>
      );
    }

    return (
      <div className="space-y-3">
        {videos.map((video, idx) => (
          <div
            key={idx}
            className="overflow-hidden rounded-lg border border-white/10 bg-black"
          >
            <video
              src={video.url}
              preload="metadata"
              controls
              className="w-full"
            />
          </div>
        ))}
      </div>
    );
  };

  if (mediaList.length === 0) return null;

  return (
    <div className="space-y-3">
      {renderImageGrid()}
      {renderVideos()}

      {/* 灯箱 */}
      {lightboxIndex !== null && images.length > 0 && mounted ? createPortal(
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90">
          <button
            onClick={closeLightbox}
            className="absolute right-4 top-4 flex h-10 w-10 items-center justify-center rounded-full bg-white/10 text-white transition-colors hover:bg-white/20"
            aria-label="关闭"
          >
            <X className="h-5 w-5" />
          </button>

          {images.length > 1 && (
            <>
              <button
                onClick={prevImage}
                className="absolute left-4 top-1/2 flex h-12 w-12 -translate-y-1/2 items-center justify-center rounded-full bg-white/10 text-white transition-colors hover:bg-white/20"
                aria-label="上一张"
              >
                <ChevronLeft className="h-6 w-6" />
              </button>
              <button
                onClick={nextImage}
                className="absolute right-4 top-1/2 flex h-12 w-12 -translate-y-1/2 items-center justify-center rounded-full bg-white/10 text-white transition-colors hover:bg-white/20"
                aria-label="下一张"
              >
                <ChevronRight className="h-6 w-6" />
              </button>
            </>
          )}

          <div
            className="flex max-h-[85vh] max-w-[90vw] items-center justify-center"
            onClick={(e) => e.stopPropagation()}
          >
            <ZoomableImage
              src={images[lightboxIndex].url}
              alt={images[lightboxIndex].filename}
              className="max-h-[85vh] max-w-[90vw] object-contain"
            />
          </div>

          <div className="pointer-events-none absolute bottom-4 left-1/2 -translate-x-1/2 text-sm text-white/60">
            {lightboxIndex + 1} / {images.length}
          </div>
        </div>,
        document.body,
      ) : null}
    </div>
  );
};

export default MediaDisplay;
