// 导出图统一的品牌水印（canvas 自绘）
// 规则与界面 BrandWatermark 一致：整体浅灰、“实况起点”行楷、三行收紧、淡蓝圆形底纹。
// compact=true：仅图标 + PlayToStar APP（用于分享图角落小水印）。

const XINGKAI = "'STXingkai', '华文行楷', '华文楷体', 'KaiTi', 'STKaiti', cursive";

interface WatermarkOpts {
  scale?: number;
  compact?: boolean;
  noCircle?: boolean;
}

export function drawBrandWatermark(
  ctx: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  iconImg: HTMLImageElement | null,
  opts?: WatermarkOpts,
): void {
  const scale = opts?.scale ?? 1;
  const compact = opts?.compact ?? false;
  const noCircle = opts?.noCircle ?? false;
  ctx.save();
  ctx.scale(scale, scale);
  // scale 后，cx/cy 是缩放坐标系下的中心；换算回未缩放坐标
  const ox = cx / scale;
  const oy = cy / scale;

  if (!compact && !noCircle) {
    // 淡蓝色圆形底纹（直径缩小约30%，去掉浅色描边）
    ctx.beginPath();
    ctx.arc(ox, oy, 109, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(125,200,255,0.13)';
    ctx.fill();
  }

  // 文字与图标统一 70% 透明度
  ctx.globalAlpha = 0.7;

  // 图标（收紧：尺寸 96，中心略上移）
  if (iconImg) {
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.5)';
    ctx.shadowBlur = 12;
    ctx.shadowOffsetY = 4;
    if (compact) {
      ctx.drawImage(iconImg, ox - 48, oy - 60, 96, 96);
    } else {
      ctx.drawImage(iconImg, ox - 48, oy - 82, 96, 96);
    }
    ctx.restore();
  }

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#d6dbe6';
  ctx.shadowColor = 'rgba(0,0,0,0.5)';
  ctx.shadowBlur = 8;
  ctx.shadowOffsetY = 2;

  // 网址
  ctx.font = 'bold 34px system-ui, sans-serif';
  if (compact) {
    ctx.fillText('PlayToStar APP', ox, oy + 34);
  } else {
    ctx.fillText('PlayToStar APP', ox, oy + 32);
    // 实况起点（华文行楷），行距收紧
    ctx.font = `36px ${XINGKAI}`;
    ctx.fillText('实况起点', ox, oy + 70);
  }

  ctx.restore();
}
