import React, { useEffect, useRef, useState } from 'react';
import { toast } from 'sonner';
import UpdateDialog from '@client/src/components/UpdateDialog';
import { useIsNativeApp } from '@client/src/hooks/use-native-app';
import {
  checkForUpdate,
  type NativeAppInfo,
  type VersionManifest,
} from '@client/src/native/app-updater';

/**
 * 启动后自动检查更新（仅原生），有新版本则弹窗。
 * 包裹在业务外层，不影响页面渲染。
 */
const AppUpdateGate: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const isNative = useIsNativeApp();
  const checkedRef = useRef(false);
  const [open, setOpen] = useState(false);
  const [manifest, setManifest] = useState<VersionManifest | null>(null);
  const [current, setCurrent] = useState<NativeAppInfo | null>(null);

  useEffect(() => {
    if (!isNative || checkedRef.current) return;
    checkedRef.current = true;
    // 稍延迟，避免与首屏资源争抢
    const timer = setTimeout(() => {
      checkForUpdate()
        .then((result) => {
          if (result && result.hasUpdate) {
            setCurrent(result.current);
            setManifest(result.manifest);
            setOpen(true);
          }
        })
        .catch(() => {
          // 检查更新失败静默处理，不打扰用户
        });
    }, 2500);
    return () => clearTimeout(timer);
  }, [isNative]);

  // 手动检查（设置页触发）
  useEffect(() => {
    const onManual = () => {
      checkForUpdate()
        .then((result) => {
          if (!result) {
            toast.error('暂时无法检查更新，请稍后再试');
            return;
          }
          setCurrent(result.current);
          if (result.hasUpdate) {
            setManifest(result.manifest);
            setOpen(true);
          } else {
            setManifest(null);
            setOpen(false);
            toast.success('当前已是最新版本');
          }
        })
        .catch(() => {
          toast.error('检查更新失败，请稍后再试');
        });
    };
    window.addEventListener('app:check-update', onManual);
    return () => window.removeEventListener('app:check-update', onManual);
  }, []);

  return (
    <>
      {children}
      <UpdateDialog
        open={open}
        manifest={manifest}
        current={current}
        onClose={() => setOpen(false)}
      />
    </>
  );
};

export default AppUpdateGate;
