import React, { useState } from 'react';
import { ChevronDown, ChevronUp, Activity } from 'lucide-react';
import type { BodyModel, PlayerModel } from '@shared/api.interface';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';

interface BodyModelPanelProps {
  bodyModel: BodyModel;
  playerModel?: PlayerModel;
  landscape?: boolean;
}

const bodyLabels: { key: keyof BodyModel; label: string; unit: string }[] = [
  { key: 'legReachDiameter', label: '伸腿覆盖', unit: 'cm' },
  { key: 'legLengthEquivalent', label: '等效身高', unit: 'cm' },
  { key: 'upperLimbDiameter', label: '上肢覆盖', unit: 'cm' },
  { key: 'trunkCollisionDiameter', label: '躯干碰撞', unit: 'cm' },
  { key: 'jumpHeight', label: '跳跃高度', unit: 'cm' },
];

 const playerModelLabels: { key: keyof PlayerModel; label: string }[] = [
   { key: 'neckCircumference', label: '颈围' },
   { key: 'neckLength', label: '颈长' },
   { key: 'shoulderWidth', label: '肩宽' },
   { key: 'shoulderHeight', label: '肩高' },
   { key: 'armSize', label: '臂围' },
   { key: 'armLength', label: '臂长' },
   { key: 'chestMeasurement', label: '胸围' },
   { key: 'waistCircumference', label: '腰围' },
   { key: 'thighSize', label: '大腿围' },
   { key: 'calfSize', label: '小腿围' },
   { key: 'legLength', label: '腿长' },
 ];

const BodyModelPanel: React.FC<BodyModelPanelProps> = ({ bodyModel, playerModel, landscape = false }) => {
  const [expanded, setExpanded] = useState(true);
  const { t, lang } = useI18n();
  const hasPlayerModel = !!playerModel;

  const sizeGrid = (
    <div className={`grid ${landscape ? 'grid-cols-3 gap-1' : 'grid-cols-2 gap-2'}`}>
      {bodyLabels.map((item) => {
        const data = bodyModel?.[item.key];
        const value = data?.value ?? '--';
        return (
          <div
            key={item.key}
            className="flex items-center justify-between rounded-lg bg-cyan-400/5 border border-cyan-400/20 px-2 py-1.5"
          >
             <span className={`text-gray-400 truncate ${landscape ? 'text-[11px]' : 'text-3xl'}`} title={trTerm(item.label)}>{trTerm(item.label)}</span>
             <span className={`font-bold text-cyan-300 ml-1 shrink-0 ${landscape ? 'text-xs' : 'text-xl'}`}>
               {value}<span className={`text-gray-500 ml-0.5 font-normal ${landscape ? 'text-[10px]' : 'text-xs'}`}>{item.unit}</span>
             </span>
          </div>
        );
      })}
    </div>
  );

  const playerGrid = (
    hasPlayerModel && playerModel && (
      <div className={`grid ${landscape ? 'grid-cols-4 gap-1' : 'grid-cols-3 gap-2'}`}>
        {playerModelLabels.map((item) => {
           const rawValue = playerModel?.[item.key];
           const value = (typeof rawValue === 'number' && Number.isFinite(rawValue)) ? rawValue : 0;
          return (
            <div
              key={item.key}
              className={landscape
                ? "flex items-center justify-between rounded-lg bg-pink-500/5 border border-pink-400/20 px-1 py-1"
                : "flex items-center justify-between rounded-lg bg-pink-500/5 border border-pink-400/20 px-2 py-1.5"}
            >
               <span className={`truncate ${landscape ? 'text-[11px] text-gray-400' : 'text-xl text-gray-300'}`} title={trTerm(item.label)}>{trTerm(item.label)}</span>
               <span className={`font-bold text-pink-300 ml-1 shrink-0 ${landscape ? 'text-xs' : 'text-2xl'}`}>
                {value}
              </span>
            </div>
          );
        })}
      </div>
    )
  );

  if (landscape) {
    return (
      <div className="rounded-xl bg-card/80 border border-white/10 backdrop-blur px-2.5 py-2">
        <div className="flex items-center gap-2 mb-1.5">
          <span className="w-1 h-4 bg-gradient-to-b from-cyan-400 to-pink-500 rounded-full" />
          <h2 className="text-sm font-bold text-white">{t('detail.playerModel')}</h2>
          <span className="text-[10px] text-gray-500 font-mono">{5 + (hasPlayerModel ? 11 : 0)} {lang === 'en' ? 'items' : '项'}</span>
        </div>
        <div className="flex items-center gap-1.5 mb-1">
          <Activity className="w-3 h-3 text-cyan-400" />
          <span className="text-[11px] font-semibold text-cyan-300">{t('detail.sizeModel')}</span>
        </div>
        {sizeGrid}
        {hasPlayerModel && (
          <>
            <div className="flex items-center gap-1.5 mt-2 mb-1">
              <Activity className="w-3 h-3 text-pink-400" />
              <span className="text-[11px] font-semibold text-pink-300">{t('detail.modelValues')}</span>
            </div>
            {playerGrid}
          </>
        )}
      </div>
    );
  }

  return (
    <div className="rounded-2xl bg-card/80 border border-white/10 backdrop-blur overflow-hidden">
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-5 py-3 hover:bg-white/5 transition-colors"
      >
        <div className="flex items-center gap-2">
          <span className="w-1 h-5 bg-gradient-to-b from-cyan-400 to-pink-500 rounded-full" />
           <h2 className="text-4xl md:text-2xl font-bold text-white">{t('detail.playerModel')}</h2>
            <span className="text-base text-gray-500 font-mono">
             {5 + (hasPlayerModel ? 11 : 0)} {lang === 'en' ? 'items' : '项参数'}
           </span>
        </div>
        {expanded ? (
          <ChevronUp className="w-4 h-4 text-gray-400" />
        ) : (
          <ChevronDown className="w-4 h-4 text-gray-400" />
        )}
      </button>

      {expanded && (
        <div className="px-4 pb-3 space-y-3">
          <div>
            <div className="flex items-center gap-2 mb-1.5">
              <Activity className="w-3 h-3 text-cyan-400" />
                 <span className="text-2xl md:text-lg font-semibold text-cyan-300">{t('detail.sizeModel')}</span>
               </div>
               {sizeGrid}
            </div>

          {hasPlayerModel && (
            <div>
              <div className="flex items-center gap-2 mb-1.5">
                <Activity className="w-3 h-3 text-pink-400" />
                 <span className="text-2xl md:text-lg font-semibold text-pink-300">{t('detail.modelValues')}</span>
              </div>
                {playerGrid}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default BodyModelPanel;
