import React from 'react';
import { useI18n } from './I18nProvider';

interface NamedPlayer {
  nameZh?: string | null;
  nameEn?: string | null;
  name?: string | null;
}

/** 返回按当前语言取球员名字的函数 */
export function usePlayerName(): (p: NamedPlayer | null | undefined) => string {
  const { lang } = useI18n();
  return React.useCallback(
    (p: NamedPlayer | null | undefined): string => {
      if (!p) return '';
      const zhName = p.nameZh ?? p.name ?? '';
      const enName = p.nameEn ?? p.nameZh ?? p.name ?? '';
      return (lang === 'en' ? enName : zhName).trim();
    },
    [lang],
  );
}

/**
 * 中文卡面短名。
 * 默认取「·」分隔的最后一段（里奥·梅西→梅西）；无分隔则整体（梅西→梅西）。
 * 若英文通称是「单名」（Neymar Jr→Neymar、Ronaldo、Kaká 这类巴西/单名球员），
 * 中文通称取第一段（内马尔·达席尔瓦→内马尔），避免误取姓氏「达席尔瓦」。
 */
export function familyNameZh(zh?: string | null, en?: string | null): string {
  if (!zh) return '';
  const parts = zh
    .split(/[·・]/)
    .map((s) => s.trim())
    .filter(Boolean);
  if (parts.length <= 1) return zh.trim();
  if (en) {
    const enParts = en
      .trim()
      .replace(/\s+(jr|sr|ii|iii|iv)\.?$/i, '')
      .split(/\s+/)
      .filter(Boolean);
    if (enParts.length === 1) return parts[0];
  }
  return parts[parts.length - 1];
}

/** 姓氏中需要随姓一起保留的介词/前缀（De Bruyne、Van Dijk、Di María 等） */
const SURNAME_PARTICLES = new Set([
  'de', 'van', 'di', 'dos', 'das', 'da', 'der', 'den', 'ten', 'del',
  'la', 'el', 'al', 'bin', 'von', 'du', 'le', 'lo', 'dal', 'della',
  'do', 'don', 'san', 'santa', 'sainte', 'ter', 'het',
]);

/** 韩国/中国大陆等「姓在前、名在后」的常见姓氏（命中则取第一个词） */
const EAST_ASIAN_FIRST = new Set([
  'son', 'kim', 'lee', 'park', 'choi', 'cho', 'kang', 'jung', 'jeong',
  'hwang', 'hong', 'kwon', 'na', 'seol', 'ki', 'han', 'an',
  'wang', 'wu', 'zhang', 'zheng', 'hao', 'wei', 'shi', 'yu', 'zhao',
  'tan', 'bai', 'liu', 'chen', 'huang', 'lin', 'tsai', 'xie', 'zhou',
  'ma', 'gao', 'he', 'guo', 'luo', 'feng', 'deng', 'cao', 'peng',
  'zeng', 'xiao', 'tian', 'duan', 'lei',
]);

/** 英文卡面短名：取姓氏（Lionel Messi→Messi；Kevin De Bruyne→De Bruyne；Son Heung-min→Son；Neymar Jr→Neymar） */
export function familyNameEn(en?: string | null): string {
  if (!en) return '';
  const cleaned = en.trim().replace(/\s+(jr|sr|ii|iii|iv)\.?$/i, '');
  const p = cleaned.split(/\s+/).filter(Boolean);
  if (p.length === 0) return '';
  if (p.length > 1 && EAST_ASIAN_FIRST.has(p[0].toLowerCase())) return p[0];
  let i = p.length - 1;
  while (i > 0 && SURNAME_PARTICLES.has(p[i - 1].toLowerCase().replace(/\.$/, ''))) {
    i -= 1;
  }
  return p.slice(i).join(' ');
}

/** 返回按当前语言取「卡面姓氏/短名」的函数 */
export function useFamilyName(): (p: NamedPlayer | null | undefined) => string {
  const { lang } = useI18n();
  return React.useCallback(
    (p: NamedPlayer | null | undefined): string => {
      if (!p) return '';
      return lang === 'en'
        ? familyNameEn(p.nameEn ?? p.nameZh ?? p.name)
        : familyNameZh(p.nameZh ?? p.name, p.nameEn ?? p.name);
    },
    [lang],
  );
}

/** 直接渲染球员名字的小组件 */
const PlayerName: React.FC<{
  player: NamedPlayer;
  className?: string;
}> = ({ player, className }) => {
  const name = usePlayerName()(player);
  return <span className={className}>{name}</span>;
};

export default PlayerName;
