import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { useNavigate } from 'react-router-dom';
import {
  AlertTriangle,
  Eye,
  Trash2,
  VolumeX,
  XCircle,
  ChevronLeft,
  ChevronRight,
  Loader2,
  Flag,
} from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import {
  getMergedReportList,
  handleReport,
} from '@client/src/api/admin';
import type {
  ReportListItem,
  ReportStatus,
} from '@shared/api.interface';
import { toast } from 'sonner';
import { showConfirm } from '@lark-apaas/client-toolkit';

const STATUS_TABS: { key: string; label: string }[] = [
  { key: 'all', label: '全部' },
  { key: 'pending', label: '待处理' },
  { key: 'handled', label: '已处理' },
  { key: 'dismissed', label: '已驳回' },
];

const MUTE_OPTIONS = [
  { label: '1 天', hours: 24 },
  { label: '7 天', hours: 168 },
  { label: '30 天', hours: 720 },
  { label: '永久', hours: 0 },
];

function statusToTab(status: ReportStatus): 'pending' | 'handled' | 'dismissed' {
  if (status === 'pending') return 'pending';
  if (status === 'dismissed') return 'dismissed';
  return 'handled';
}

function getStatusLabel(status: ReportStatus): string {
  switch (status) {
    case 'pending':
      return '待处理';
    case 'removed':
      return '已删除';
    case 'muted':
      return '已禁言';
    case 'dismissed':
      return '已驳回';
    default:
      return status;
  }
}

function getStatusColor(status: ReportStatus): string {
  switch (status) {
    case 'pending':
      return 'bg-yellow-500/20 text-yellow-300 border-yellow-400/50';
    case 'removed':
      return 'bg-red-500/20 text-red-300 border-red-400/50';
    case 'muted':
      return 'bg-orange-500/20 text-orange-300 border-orange-400/50';
    case 'dismissed':
      return 'bg-gray-500/20 text-gray-300 border-gray-400/50';
    default:
      return 'bg-white/10 text-white/70 border-white/20';
  }
}

function truncateText(text: string, maxLen: number): string {
  if (text.length <= maxLen) return text;
  return text.slice(0, maxLen) + '...';
}

const AdminReportsPage: React.FC = () => {
  const navigate = useNavigate();
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(true);
    return () => setMounted(false);
  }, []);
  const [tab, setTab] = useState<string>('pending');
  const [page, setPage] = useState(1);
  const pageSize = 10;
  const [items, setItems] = useState<ReportListItem[]>([]);
  const [total, setTotal] = useState(0);
  const [pendingCount, setPendingCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [muteDialogId, setMuteDialogId] = useState<string | null>(null);
  const [muteHours, setMuteHours] = useState(24);

  const fetchList = useCallback(async () => {
    setLoading(true);
    try {
      const statusParam =
        tab === 'all'
          ? undefined
          : tab === 'handled'
            ? 'handled'
            : tab;
      const data = await getMergedReportList({
        status: statusParam,
        page,
        pageSize,
      });
      setItems(data.items);
      setTotal(data.total);
      setPendingCount(data.pendingCount);
    } catch (error) {
      logger.error('加载举报列表失败', error);
      toast('加载失败，请刷新重试');
    } finally {
      setLoading(false);
    }
  }, [tab, page]);

  useEffect(() => {
    fetchList();
  }, [fetchList]);

  const handleTabChange = (key: string) => {
    setTab(key);
    setPage(1);
  };

  const goToTarget = (item: ReportListItem) => {
    if (item.targetType === 'post') {
      navigate(`/forum/${item.targetId}`);
    } else {
      navigate(`/forum/${item.targetId}#comment-${item.targetId}`);
    }
  };

  const doAction = async (
    item: ReportListItem,
    action: 'remove' | 'mute' | 'dismiss',
    muteDurationHours?: number,
  ) => {
    const confirmMessages: Record<string, string> = {
      remove: item.targetType === 'post' ? '确定删除该帖子吗？' : '确定删除该评论吗？',
      dismiss: '确定驳回该举报吗？',
      mute: `确定${muteDurationHours === 0 ? '永久禁言' : `禁言 ${muteDurationHours} 小时`}该用户吗？`,
    };
    if (!await showConfirm(confirmMessages[action])) return;

    setActionLoading(item.id);
    try {
      await handleReport(item.id, { action, muteDurationHours });
      toast('操作成功');
      fetchList();
    } catch (error) {
      logger.error('操作失败', error);
      toast('操作失败，请重试');
    } finally {
      setActionLoading(null);
      setMuteDialogId(null);
    }
  };

  const totalPages = Math.max(1, Math.ceil(total / pageSize));

  return (
    <div className="min-h-[600px] px-4 py-6">
      {/* 标题 */}
      <div className="mb-6 flex items-center gap-3">
        <AlertTriangle className="h-7 w-7 text-cyan-400" />
        <h1 className="text-2xl font-black text-white tracking-wide">
          举报审核
        </h1>
        {pendingCount > 0 && (
          <span className="inline-flex h-6 min-w-[24px] items-center justify-center rounded-full bg-red-500 px-2 text-xs font-bold text-white shadow-[0_0_12px_rgba(239_68_68_0.7)]">
            {pendingCount}
          </span>
        )}
      </div>

      {/* 筛选 Tab */}
      <div className="mb-6 flex gap-2 flex-wrap">
        {STATUS_TABS.map((t) => (
          <button
            key={t.key}
            onClick={() => handleTabChange(t.key)}
            className={`relative rounded-lg border px-5 py-2 text-sm font-semibold transition-all ${
              tab === t.key
                ? 'border-cyan-400/70 bg-cyan-500/15 text-cyan-200 shadow-[0_0_20px_rgba(34_211_238_0.4)]'
                : 'border-white/10 bg-[#141838]/50 text-white/60 hover:border-cyan-400/40 hover:text-white/90'
            }`}
          >
            {t.label}
            {t.key === 'pending' && pendingCount > 0 && (
              <span className="ml-1.5 inline-flex h-4 min-w-[16px] items-center justify-center rounded-full bg-red-500 px-1 text-[10px] font-bold text-white shadow-[0_0_8px_rgba(239_68_68_0.7)]">
                {pendingCount > 99 ? '99+' : pendingCount}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* 列表 */}
      {loading ? (
        <div className="flex items-center justify-center py-20">
          <Loader2 className="h-8 w-8 animate-spin text-cyan-400" />
        </div>
      ) : (items || []).length === 0 ? (
        <div className="rounded-xl border border-white/10 bg-[#141838]/40 py-20 text-center text-white/40">
          暂无举报记录
        </div>
      ) : (
        <div className="space-y-4">
          {(items || []).map((item) => (
            <div
              key={item.id}
              className="group relative overflow-hidden rounded-xl border border-cyan-400/20 bg-gradient-to-br from-[#141838]/80 to-[#0f1330]/80 p-5 backdrop-blur-sm transition-all hover:border-cyan-400/50 hover:shadow-[0_0_30px_rgba(34_211_238_0.15)]"
            >
              {/* 顶部标签 */}
              <div className="mb-3 flex items-center gap-2 flex-wrap">
                <span
                  className={`rounded-md border px-2 py-0.5 text-xs font-semibold ${
                    item.targetType === 'post'
                      ? 'bg-purple-500/20 text-purple-300 border-purple-400/50'
                      : 'bg-pink-500/20 text-pink-300 border-pink-400/50'
                  }`}
                >
                  {item.targetType === 'post' ? '帖子' : '评论'}
                </span>
                <span
                  className={`rounded-md border px-2 py-0.5 text-xs font-semibold ${getStatusColor(
                    item.status,
                  )}`}
                >
                  {getStatusLabel(item.status)}
                </span>
                <span className="inline-flex items-center gap-1 rounded-md border border-yellow-400/30 bg-yellow-400/10 px-2 py-0.5 text-xs font-semibold text-yellow-300">
                  <Flag className="h-3 w-3" />
                  {item.reportCount} 人举报
                </span>
                <span className="ml-auto text-xs text-white/40">
                  最早举报：{new Date(item.earliestAt).toLocaleString('zh-CN')}
                </span>
              </div>

              {/* 内容摘要 */}
              <div className="mb-3">
                <div className="mb-1 text-xs text-white/50">内容摘要：</div>
                <p
                  className="line-clamp-2 text-sm text-white/80"
                  style={{
                    display: '-webkit-box',
                    WebkitLineClamp: 2,
                    WebkitBoxOrient: 'vertical',
                    overflow: 'hidden',
                  }}
                >
                  {item.targetIsDeleted
                    ? '（内容已被删除）'
                    : item.targetContent
                      ? truncateText(item.targetContent, 80)
                      : '（无内容）'}
                </p>
              </div>

              {/* 举报信息 */}
              <div className="mb-4 grid grid-cols-2 gap-2 text-xs text-white/60">
                <div>
                  被举报人：
                  <span className="text-white/80">
                    {item.targetAuthorName || '未知'}
                  </span>
                </div>
                <div>
                  最近举报：
                  <span className="text-white/80">
                    {new Date(item.latestAt).toLocaleString('zh-CN')}
                  </span>
                </div>
                <div className="col-span-2">
                  举报理由：
                  <span className="text-yellow-300/90">
                    {item.reasons.length > 0
                      ? item.reasons.join('、')
                      : '暂无理由'}
                  </span>
                </div>
              </div>

              {/* 操作按钮 */}
              {item.status === 'pending' && !item.targetIsDeleted && (
                <div className="flex flex-wrap gap-2">
                  <button
                    onClick={() => goToTarget(item)}
                    disabled={actionLoading === item.id}
                    className="flex items-center gap-1.5 rounded-md border border-cyan-400/40 bg-cyan-400/10 px-3 py-1.5 text-xs font-medium text-cyan-300 transition-all hover:bg-cyan-400/20 hover:shadow-[0_0_12px_rgba(34_211_238_0.4)] disabled:opacity-50"
                  >
                    <Eye className="h-3.5 w-3.5" />
                    查看原文
                  </button>
                  <button
                    onClick={() => doAction(item, 'remove')}
                    disabled={actionLoading === item.id}
                    className="flex items-center gap-1.5 rounded-md border border-red-400/40 bg-red-400/10 px-3 py-1.5 text-xs font-medium text-red-300 transition-all hover:bg-red-400/20 hover:shadow-[0_0_12px_rgba(248_113_113_0.4)] disabled:opacity-50"
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                    删除内容
                  </button>
                  <button
                    onClick={() => {
                      setMuteDialogId(item.id);
                      setMuteHours(24);
                    }}
                    disabled={actionLoading === item.id}
                    className="flex items-center gap-1.5 rounded-md border border-orange-400/40 bg-orange-400/10 px-3 py-1.5 text-xs font-medium text-orange-300 transition-all hover:bg-orange-400/20 hover:shadow-[0_0_12px_rgba(251_146_60_0.4)] disabled:opacity-50"
                  >
                    <VolumeX className="h-3.5 w-3.5" />
                    删除并禁言
                  </button>
                  <button
                    onClick={() => doAction(item, 'dismiss')}
                    disabled={actionLoading === item.id}
                    className="flex items-center gap-1.5 rounded-md border border-gray-400/40 bg-gray-400/10 px-3 py-1.5 text-xs font-medium text-gray-300 transition-all hover:bg-gray-400/20 disabled:opacity-50"
                  >
                    <XCircle className="h-3.5 w-3.5" />
                    驳回
                  </button>
                </div>
              )}

              {item.targetIsDeleted && item.status === 'pending' && (
                <div className="flex gap-2">
                  <button
                    onClick={() => doAction(item, 'dismiss')}
                    disabled={actionLoading === item.id}
                    className="flex items-center gap-1.5 rounded-md border border-gray-400/40 bg-gray-400/10 px-3 py-1.5 text-xs font-medium text-gray-300 transition-all hover:bg-gray-400/20 disabled:opacity-50"
                  >
                    <XCircle className="h-3.5 w-3.5" />
                    驳回（内容已删除）
                  </button>
                </div>
              )}

              {actionLoading === item.id && statusToTab(item.status) === 'pending' && (
                <div className="mt-2 text-xs text-cyan-300">处理中...</div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* 分页 */}
      {total > 0 && (
        <div className="mt-6 flex items-center justify-center gap-2">
          <button
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page === 1}
            className="flex h-8 w-8 items-center justify-center rounded-md border border-white/10 bg-[#141838]/50 text-white/70 transition-all hover:border-cyan-400/40 hover:text-white disabled:opacity-30"
          >
            <ChevronLeft className="h-4 w-4" />
          </button>
          <span className="px-3 text-sm text-white/60">
            第 <span className="text-cyan-300">{page}</span> / {totalPages} 页
          </span>
          <button
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page === totalPages}
            className="flex h-8 w-8 items-center justify-center rounded-md border border-white/10 bg-[#141838]/50 text-white/70 transition-all hover:border-cyan-400/40 hover:text-white disabled:opacity-30"
          >
            <ChevronRight className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* 禁言时长选择弹窗 */}
      {muteDialogId && mounted ? createPortal(
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <div className="w-[360px] rounded-xl border border-orange-400/40 bg-[#141838] p-6 shadow-[0_0_40px_rgba(251_146_60_0.25)]">
            <h3 className="mb-4 text-lg font-bold text-orange-300">
              选择禁言时长
            </h3>
            <p className="mb-4 text-sm text-white/60">
              删除内容并对用户执行禁言处罚
            </p>
            <div className="mb-6 grid grid-cols-2 gap-2">
              {MUTE_OPTIONS.map((opt) => (
                <button
                  key={opt.hours}
                  onClick={() => setMuteHours(opt.hours)}
                  className={`rounded-lg border px-4 py-3 text-sm font-semibold transition-all ${
                    muteHours === opt.hours
                      ? 'border-orange-400/70 bg-orange-500/15 text-orange-200 shadow-[0_0_16px_rgba(251_146_60_0.4)]'
                      : 'border-white/10 bg-[#0f1330]/60 text-white/70 hover:border-orange-400/40'
                  }`}
                >
                  {opt.label}
                </button>
              ))}
            </div>
            <div className="flex justify-end gap-2">
              <button
                onClick={() => setMuteDialogId(null)}
                className="rounded-md border border-white/10 bg-white/5 px-4 py-2 text-sm text-white/70 transition-all hover:bg-white/10"
              >
                取消
              </button>
              <button
                onClick={() => {
                  const item = (items || []).find((i) => i.id === muteDialogId);
                  if (item) doAction(item, 'mute', muteHours);
                }}
                className="rounded-md bg-gradient-to-r from-orange-500 to-red-500 px-4 py-2 text-sm font-semibold text-white shadow-[0_0_16px_rgba(251_146_60_0.5)] transition-all hover:shadow-[0_0_24px_rgba(251_146_60_0.7)]"
              >
                确认禁言
              </button>
            </div>
          </div>
        </div>,
        document.body,
      ) : null}
    </div>
  );
};

export default AdminReportsPage;
