/**
 * 球队风格熟练度进度条颜色工具
 * eFootball 6.0 霓虹赛博风格
 */

export function getStyleColor(value: number): string {
  if (value >= 80) return 'bg-gradient-to-r from-cyan-400 to-cyan-500';
  if (value >= 60) return 'bg-gradient-to-r from-cyan-500 to-violet-500';
  return 'bg-gradient-to-r from-violet-500 to-pink-500';
}

export function getStyleTextColor(value: number): string {
  if (value >= 80) return 'text-cyan-400';
  if (value >= 60) return 'text-violet-400';
  return 'text-pink-400';
}
