import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { ShieldCheck, ChevronRight } from 'lucide-react';
import { useIsNativeApp } from '@client/src/hooks/use-native-app';

/**
 * 首次启动隐私授权拦截。
 * - 仅原生 App 生效；web 直接放行。
 * - 用户同意前不渲染任何业务页面，不初始化网络/登录，确保不提前收集信息。
 * - 拒绝后进入中性页，不锁定、不收集，可随时重新查看并同意。
 */

// 隐私版本号：政策更新时递增，触发老用户重新授权
const PRIVACY_VERSION = '2026-09-24';
const CONSENT_KEY = 'pts_privacy_consent';

interface ConsentRecord {
  version: string;
  agreedAt: string;
}

function readConsent(): ConsentRecord | null {
  try {
    const raw = localStorage.getItem(CONSENT_KEY);
    if (!raw) return null;
    const rec = JSON.parse(raw) as ConsentRecord;
    if (rec.version !== PRIVACY_VERSION) return null;
    return rec;
  } catch {
    return null;
  }
}

const PrivacyGate: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const isNative = useIsNativeApp();
  const [consented, setConsented] = useState<boolean>(false);
  const [refused, setRefused] = useState<boolean>(false);

  useEffect(() => {
    if (isNative) {
      setConsented(!!readConsent());
    } else {
      setConsented(true);
    }
  }, [isNative]);

  // web 直接放行
  if (!isNative) return <>{children}</>;

  const agree = () => {
    const rec: ConsentRecord = {
      version: PRIVACY_VERSION,
      agreedAt: new Date().toISOString(),
    };
    localStorage.setItem(CONSENT_KEY, JSON.stringify(rec));
    setRefused(false);
    setConsented(true);
  };

  // 已同意：渲染业务
  if (consented) return <>{children}</>;

  // 拒绝后的中性页（不锁定、不收集，可重新同意）
  if (refused) {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center bg-[#070d1c] px-8 text-center">
        <ShieldCheck className="mb-4 h-12 w-12 text-slate-500" />
        <div className="mb-2 text-lg font-semibold text-slate-200">
          需同意隐私政策后才能使用
        </div>
        <p className="mb-8 text-sm leading-relaxed text-slate-400">
          实况起点的球员数据查询、加点模拟与社区功能均需联网并在你授权后运行。
          你可以重新查看政策并选择同意；在此之前我们不会收集你的任何信息。
        </p>
        <button
          onClick={() => setRefused(false)}
          className="w-full max-w-xs rounded-full bg-gradient-to-r from-cyan-500 to-pink-500 px-6 py-3 text-base font-medium text-white"
        >
          重新查看并同意
        </button>
      </div>
    );
  }

  // 首次授权页
  return (
    <div className="flex min-h-screen flex-col bg-[#070d1c] px-6 py-10">
      <div className="flex flex-1 flex-col">
        <div className="mb-6 flex items-center gap-3">
          <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-gradient-to-br from-cyan-400 to-pink-500 text-2xl font-bold text-[#04122a]">
            S
          </div>
          <div>
            <div className="text-xl font-bold text-white">实况起点</div>
            <div className="text-xs text-slate-400">eFootball 数据中心</div>
          </div>
        </div>

        <h1 className="mb-3 text-xl font-bold text-white">
          欢迎使用，请阅读并同意相关协议
        </h1>
        <p className="mb-5 text-sm leading-relaxed text-slate-300">
          为向你提供球员数据查询、加点模拟、榜单对比及社区服务，我们会在你授权后收集和使用必要信息。核心要点：
        </p>

        <div className="mb-6 space-y-3 text-sm text-slate-300">
          <div className="rounded-xl bg-white/5 p-3">
            <span className="font-medium text-cyan-300">微信登录：</span>
            仅获取微信标识（OpenID / UnionID）及昵称、头像用于识别身份，不收集手机号。
          </div>
          <div className="rounded-xl bg-white/5 p-3">
            <span className="font-medium text-cyan-300">你产生的内容：</span>
            帖子、评论、点赞收藏及保存的加点方案会存储在服务器，头像图片由你主动上传。
          </div>
          <div className="rounded-xl bg-white/5 p-3">
            <span className="font-medium text-cyan-300">设备与日志：</span>
            为保障安全，可能记录设备型号、系统、IP 与访问日志。
          </div>
        </div>

        <div className="space-y-2 text-sm">
          <Link
            to="/privacy"
            className="flex items-center justify-between rounded-xl border border-white/10 px-4 py-3 text-slate-200"
          >
            《隐私政策》
            <ChevronRight className="h-4 w-4 text-slate-400" />
          </Link>
          <Link
            to="/terms"
            className="flex items-center justify-between rounded-xl border border-white/10 px-4 py-3 text-slate-200"
          >
            《用户协议》
            <ChevronRight className="h-4 w-4 text-slate-400" />
          </Link>
        </div>
      </div>

      <div className="mt-6 space-y-3">
        <button
          onClick={agree}
          className="w-full rounded-full bg-gradient-to-r from-cyan-500 to-pink-500 px-6 py-3.5 text-base font-semibold text-white"
        >
          同意并继续
        </button>
        <button
          onClick={() => setRefused(true)}
          className="w-full rounded-full px-6 py-3 text-base text-slate-400"
        >
          不同意
        </button>
      </div>
    </div>
  );
};

export default PrivacyGate;
