export async function updateMyAvatar(
  avatarUrl: string,
): Promise<UpdateAvatarResponse> {
  try {
    const response = await axiosForBackend.patch<UpdateAvatarResponse>(
      '/api/users/me/avatar',
      { avatarUrl } satisfies UpdateAvatarRequest,
    );
    return response.data;
  } catch (error) {
    logger.error('更新头像失败', error);
    throw error;
  }
}

export async function updateMyProfile(
  data: UpdateProfileRequest,
): Promise<UpdateProfileResponse> {
  const response = await axiosForBackend.patch<UpdateProfileResponse>(
    '/api/users/me',
    data,
  );
  return response.data;
}

/**
 * 自建环境头像文件上传：multipart/form-data，字段名 file。
 * 返回包含可访问 URL 的结果。
 */
export async function uploadMyAvatarFile(
  file: File,
  onProgress?: (percent: number) => void,
): Promise<UpdateAvatarResponse> {
  const form = new FormData();
  form.append('file', file);
  const response = await axiosForBackend.post<UpdateAvatarResponse>(
    '/api/users/me/avatar/upload',
    form,
    {
      headers: { 'Content-Type': 'multipart/form-data' },
      onUploadProgress: (e) => {
        if (onProgress && e.total) onProgress(Math.round((e.loaded / e.total) * 100));
      },
    },
  );
  return response.data;
}
