import { useEffect, useRef, useState, useCallback } from 'react';

interface UseInfiniteScrollOptions {
  hasMore: boolean;
  loadMore: () => Promise<void> | void;
  rootMargin?: string;
  threshold?: number;
}

export function useInfiniteScroll({
  hasMore,
  loadMore,
  rootMargin = '120px',
  threshold = 0.1,
}: UseInfiniteScrollOptions): {
  sentinelRef: React.RefObject<HTMLDivElement>;
  loading: boolean;
} {
  const sentinelRef = useRef<HTMLDivElement>(null);
  const [loading, setLoading] = useState(false);
  const loadingRef = useRef(false);

  const onIntersect = useCallback(
    async (entries: IntersectionObserverEntry[]) => {
      const [entry] = entries;
      if (!entry.isIntersecting || !hasMore || loadingRef.current) return;
      loadingRef.current = true;
      setLoading(true);
      try {
        await loadMore();
      } finally {
        loadingRef.current = false;
        setLoading(false);
      }
    },
    [hasMore, loadMore],
  );

  useEffect(() => {
    const el = sentinelRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(onIntersect, {
      rootMargin,
      threshold,
    });
    observer.observe(el);

    // 首屏兜底：结果不足一屏、页面尚不能滚动时 IntersectionObserver 可能不触发，
    // 主动检测哨兵是否已在/接近视口，是则立即加载，循环直到撑满一屏或没有更多。
    const kick = () => {
      if (!hasMore || loadingRef.current) { return; }
      const r = el.getBoundingClientRect();
      const inRange = r.top < window.innerHeight + 200 && r.bottom > -200;
      if (inRange) {
        onIntersect([{ isIntersecting: true } as IntersectionObserverEntry]);
      }
    };
    const t1 = window.setTimeout(kick, 60);
    const t2 = window.setTimeout(kick, 300);

    return () => {
      observer.disconnect();
      window.clearTimeout(t1);
      window.clearTimeout(t2);
    };
  }, [onIntersect, rootMargin, threshold, hasMore]);

  return { sentinelRef, loading };
}
