import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  Loader2,
  ThumbsUp,
  MessageSquare,
  FileText,
  MessageSquareText,
  Edit3,
  UserPlus,
  UserCheck,
} from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { toast } from 'sonner';
import dayjs from 'dayjs';

import { Button } from '@client/src/components/ui/button';
import { Badge } from '@client/src/components/ui/badge';
import UserAvatar from '@client/src/components/ui/user-avatar';
import { useAuth } from '@client/src/context/AuthContext';
import { useLoginGuard } from '@client/src/hooks/useLoginGuard';
import { users as usersApi } from '@client/src/api';
import { toggleFollow } from '@client/src/api/follows';
import {
  visitorLocalHas,
  visitorLocalToggle,
  toastVisitorLocal,
} from '@client/src/utils/visitor-mode';
import type {
  UserProfile,
  ForumPost,
  UserCommentItem,
} from '@shared/api.interface';
import { useInfiniteScroll } from '@client/src/hooks/useInfiniteScroll';
import InfiniteScrollFooter from '@client/src/components/InfiniteScrollFooter';

type TabKey = 'posts' | 'comments';

const POST_BOARD_THEMES: Record<string, { border: string; bg: string; text: string; shadow: string }> = {
  international: {
    border: 'border-orange-400/80',
    bg: 'bg-[hsl(231_56%_10%_/_0.88)]',
    text: 'text-orange-100',
    shadow: 'shadow-[0_0_20px_rgba(249_115_22_0.5)]',
  },
  cn: {
    border: 'border-cyan-400/80',
    bg: 'bg-[hsl(231_56%_10%_/_0.88)]',
    text: 'text-cyan-50',
    shadow: 'shadow-[0_0_20px_rgba(34_211_238_0.5)]',
  },
  bug: {
    border: 'border-purple-400/80',
    bg: 'bg-[hsl(231_56%_10%_/_0.88)]',
    text: 'text-purple-100',
    shadow: 'shadow-[0_0_20px_rgba(139_92_246_0.5)]',
  },
};

function getBoardTheme(board: string) {
  return (
    POST_BOARD_THEMES[board] || {
      border: 'border-cyan-400/80',
      bg: 'bg-[hsl(231_56%_10%_/_0.88)]',
      text: 'text-cyan-50',
      shadow: 'shadow-[0_0_20px_rgba(34_211_238_0.5)]',
    }
  );
}

function getTargetPath(targetType: string, targetId: string): string {
  switch (targetType) {
    case 'forum_post':
      return `/forum/${targetId}`;
    case 'player':
      return `/player/${targetId}`;
    case 'coach':
      return `/coach/${targetId}`;
    default:
      return '';
  }
}

const PAGE_SIZE = 20;

const UserProfilePage: React.FC = () => {
  const { userId = '' } = useParams<{ userId: string }>();
  const navigate = useNavigate();
  const { user, getAuthHeaders } = useAuth();
  const { allowLocalAction } = useLoginGuard();

  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [profileLoading, setProfileLoading] = useState(true);
  const [profileError, setProfileError] = useState<string | null>(null);

  const [activeTab, setActiveTab] = useState<TabKey>('posts');
  const [posts, setPosts] = useState<ForumPost[]>([]);
  const [comments, setComments] = useState<UserCommentItem[]>([]);
  const [initialLoading, setInitialLoading] = useState(false);
  const [total, setTotal] = useState(0);

  const [followLoading, setFollowLoading] = useState(false);
  const [localFollowing, setLocalFollowing] = useState<boolean | null>(null);

  const isSelf = user?.id === userId;

  // 获取用户资料
  const fetchProfile = useCallback(async () => {
    if (!userId) return;
    setProfileLoading(true);
    setProfileError(null);
    try {
      const data = await usersApi.getUserProfile(userId);
      setProfile(data);
      // 游客：读取本机关注状态；已登录：用服务端 isFollowing
      setLocalFollowing(user ? data.isFollowing : visitorLocalHas('follow_user', userId));
    } catch (error: unknown) {
      const msg =
        error instanceof Error ? error.message : '加载用户信息失败';
      logger.error('加载用户信息失败', error);
      setProfileError(msg);
    } finally {
      setProfileLoading(false);
    }
  }, [userId, user]);

  useEffect(() => {
    fetchProfile();
  }, [fetchProfile]);

  const currentItems = activeTab === 'posts' ? posts : comments;
  const hasMore = currentItems.length < total && total > 0;

  // 加载更多（无限滚动）
  const loadMore = useCallback(async () => {
    if (!userId) return;
    const nextPage = Math.ceil(currentItems.length / PAGE_SIZE) + 1;
    try {
      if (activeTab === 'posts') {
        const data = await usersApi.getUserPosts(userId, {
          page: nextPage,
          pageSize: PAGE_SIZE,
        });
        setPosts((prev) => [...prev, ...data.items]);
        setTotal(data.total);
      } else {
        const data = await usersApi.getUserComments(userId, {
          page: nextPage,
          pageSize: PAGE_SIZE,
        });
        setComments((prev) => [...prev, ...data.items]);
        setTotal(data.total);
      }
    } catch (error) {
      logger.error('加载更多失败', error);
    }
  }, [userId, activeTab, currentItems.length]);

  // 切换 tab 时重新加载第一页
  useEffect(() => {
    let cancelled = false;
    if (!userId) return;

    setInitialLoading(true);
    setTotal(0);
    if (activeTab === 'posts') {
      setPosts([]);
    } else {
      setComments([]);
    }

    (async () => {
      try {
        if (activeTab === 'posts') {
          const data = await usersApi.getUserPosts(userId, {
            page: 1,
            pageSize: PAGE_SIZE,
          });
          if (cancelled) return;
          setPosts(data.items);
          setTotal(data.total);
        } else {
          const data = await usersApi.getUserComments(userId, {
            page: 1,
            pageSize: PAGE_SIZE,
          });
          if (cancelled) return;
          setComments(data.items);
          setTotal(data.total);
        }
      } catch (error) {
        logger.error('加载列表失败', error);
        if (cancelled) return;
        setPosts([]);
        setComments([]);
        setTotal(0);
      } finally {
        if (!cancelled) setInitialLoading(false);
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [activeTab, userId]);

  const { sentinelRef, loading: infiniteLoading } = useInfiniteScroll({
    hasMore,
    loadMore,
  });

  // 关注 / 取消关注
  const handleToggleFollow = async () => {
    if (!allowLocalAction('关注')) return;
    if (followLoading || !profile) return;

    // 游客：仅本机关注（kind='follow_user'，key=userId），粉丝数在展示层叠加，不改服务端值
    if (!user) {
      const next = visitorLocalToggle('follow_user', userId);
      setLocalFollowing(next);
      if (next) toastVisitorLocal('follow_user');
      return;
    }

    const prevFollowing = localFollowing ?? profile.isFollowing;
    const nextFollowing = !prevFollowing;

    // 乐观更新
    setLocalFollowing(nextFollowing);
    setProfile((prev) =>
      prev
        ? {
            ...prev,
            followerCount: nextFollowing
              ? prev.followerCount + 1
              : prev.followerCount - 1,
            isFollowing: nextFollowing,
          }
        : prev,
    );

    setFollowLoading(true);
    try {
      const result = await toggleFollow(userId, getAuthHeaders());
      setLocalFollowing(result.following);
      setProfile((prev) =>
        prev
          ? {
              ...prev,
              followerCount: result.followerCount,
              isFollowing: result.following,
            }
          : prev,
      );
      toast.success(result.following ? '关注成功' : '已取消关注');
    } catch (error: unknown) {
      // 回滚
      setLocalFollowing(prevFollowing);
      setProfile((prev) =>
        prev
          ? {
              ...prev,
              followerCount: prevFollowing
                ? prev.followerCount + 1
                : prev.followerCount - 1,
              isFollowing: prevFollowing,
            }
          : prev,
      );
      const msg =
        error instanceof Error ? error.message : '操作失败，请稍后重试';
      toast.error(msg);
    } finally {
      setFollowLoading(false);
    }
  };

  const handlePostClick = (id: string) => {
    navigate(`/forum/${id}`);
  };

  const handleCommentClick = (item: UserCommentItem) => {
    const path = getTargetPath(item.targetType, item.targetId);
    if (path) navigate(path);
  };

  if (profileLoading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="h-8 w-8 animate-spin text-cyan-400" />
      </div>
    );
  }

  if (profileError || !profile) {
    return (
      <div className="py-20 text-center">
        <p className="text-base text-gray-400">
          {profileError || '用户不存在'}
        </p>
        <Button
          variant="outline"
          onClick={() => navigate(-1)}
          className="mt-4 border-white/10 text-cyan-300"
        >
          <ArrowLeft className="mr-1.5 h-4 w-4" />返回
        </Button>
      </div>
    );
  }

  const displayFollowing = localFollowing ?? profile.isFollowing;
  // 游客本机关注叠加 1 个粉丝展示（服务端 count 不伪造改动）；已登录用云端已同步的 followerCount
  const displayFollowerCount = !user
    ? profile.followerCount + (displayFollowing ? 1 : 0)
    : profile.followerCount;

  return (
    <div className="space-y-3 sm:space-y-3 text-white overflow-x-hidden">
      {/* 顶部导航栏 */}
      <div className="flex items-center gap-3 py-2">
        <button
          onClick={() => navigate(-1)}
          className="flex h-9 w-9 items-center justify-center rounded-lg border border-white/10 bg-[#141838]/60 text-gray-300 transition-all hover:border-cyan-400/40 hover:text-cyan-300"
        >
          <ArrowLeft className="h-5 w-5" />
        </button>
        <h1 className="flex-1 text-center text-lg font-bold text-white">
          {isSelf ? '我的主页' : '用户主页'}
        </h1>
        <div className="w-9" />
      </div>

      {/* 用户信息卡片 */}
      <div className="rounded-2xl border border-white/10 bg-gradient-to-br from-[#141838]/90 via-[#1a1f4a]/80 to-[#0f1338]/90 p-4 sm:p-5 backdrop-blur-sm shadow-[0_0_30px_rgba(34_211_238_0.08)]">
        <div className="flex items-start gap-4">
          {/* 头像 */}
          <div className="flex-shrink-0">
            <div className="shadow-[0_0_20px_rgba(34_211_238_0.4)] rounded-full">
              <UserAvatar
                avatarUrl={profile.avatarUrl}
                userName={profile.nickname || profile.username}
                size="lg"
                className="h-16 w-16"
              />
            </div>
          </div>
          {/* 用户名 + 简介 */}
          <div className="flex-1 min-w-0">
            <h2 className="text-xl font-bold text-white truncate">
              {profile.nickname || profile.username}
            </h2>
            {profile.bio ? (
              <p
                className="mt-1 text-sm text-gray-400 leading-relaxed"
                style={{
                  display: '-webkit-box',
                  WebkitLineClamp: 2,
                  WebkitBoxOrient: 'vertical',
                  overflow: 'hidden',
                }}
              >
                {profile.bio}
              </p>
            ) : (
              <p className="mt-1 text-sm text-gray-600">这个人很懒，什么都没写~</p>
            )}
            <div className="mt-1.5 flex items-center gap-2">
              <span className="inline-block rounded bg-purple-500/20 px-2 py-0.5 text-xs font-medium text-purple-300">
                Lv.{profile.level}
              </span>
              <span className="text-xs text-gray-500">
                声望 {profile.reputation}
              </span>
            </div>
          </div>
        </div>

        {/* 关注 / 粉丝 / 发帖数 */}
        <div className="mt-4 flex justify-around border-t border-white/10 pt-4">
          <div className="flex flex-col items-center">
            <span className="text-lg font-bold text-white">
              {profile.followingCount}
            </span>
            <span className="text-xs text-gray-500">关注</span>
          </div>
          <div className="flex flex-col items-center">
            <span className="text-lg font-bold text-white">
              {displayFollowerCount}
            </span>
            <span className="text-xs text-gray-500">粉丝</span>
          </div>
          <div className="flex flex-col items-center">
            <span className="text-lg font-bold text-white">
              {profile.postCount}
            </span>
            <span className="text-xs text-gray-500">发帖</span>
          </div>
        </div>

        {/* 操作按钮 */}
        <div className="mt-4">
          {isSelf ? (
            <Button
              variant="outline"
              onClick={() => navigate('/profile')}
              className="w-full border-white/20 bg-transparent text-gray-200 hover:border-cyan-400/40 hover:text-cyan-200"
            >
              <Edit3 className="mr-1.5 h-4 w-4" />
              编辑资料
            </Button>
          ) : (
            <Button
              onClick={handleToggleFollow}
              disabled={followLoading}
              className={`w-full transition-all ${
                displayFollowing
                  ? 'border border-white/20 bg-transparent text-white hover:bg-white/5'
                  : 'bg-gradient-to-r from-cyan-500 to-purple-500 text-white shadow-[0_0_15px_rgba(34_211_238_0.5)] hover:shadow-[0_0_25px_rgba(34_211_238_0.7)]'
              }`}
              variant={displayFollowing ? 'outline' : 'default'}
            >
              {followLoading ? (
                <Loader2 className="mr-1.5 h-4 w-4 animate-spin" />
              ) : displayFollowing ? (
                <UserCheck className="mr-1.5 h-4 w-4" />
              ) : (
                <UserPlus className="mr-1.5 h-4 w-4" />
              )}
              {displayFollowing ? '已关注' : '关注'}
            </Button>
          )}
        </div>
      </div>

      {/* Tab 切换 */}
      <div className="flex gap-1 rounded-xl border border-white/10 bg-[#141838]/60 p-1.5">
        {([
          { key: 'posts', label: '发帖' },
          { key: 'comments', label: '回复' },
        ] as const).map((tab) => {
          const active = activeTab === tab.key;
          return (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`relative flex-1 rounded-lg px-4 py-2.5 text-base font-medium transition-all ${
                active
                  ? 'text-white'
                  : 'text-gray-400 hover:text-white/80'
              }`}
            >
              {tab.label}
              {active && (
                <span className="absolute bottom-0 left-1/2 h-0.5 w-8 -translate-x-1/2 rounded-full bg-gradient-to-r from-cyan-400 to-purple-400 shadow-[0_0_8px_rgba(34_211_238_0.6)]" />
              )}
            </button>
          );
        })}
      </div>

      {/* Tab 内容 */}
      <div>
        {initialLoading ? (
          <div className="flex items-center justify-center py-16">
            <Loader2 className="h-8 w-8 animate-spin text-cyan-400" />
          </div>
        ) : activeTab === 'posts' ? (
          posts.length === 0 ? (
            <div className="rounded-xl border border-white/10 bg-[#141838]/50 py-16 text-center">
              <div className="mb-3 flex justify-center">
                <FileText className="h-10 w-10 text-cyan-400/40" />
              </div>
              <p className="text-base text-gray-500">该用户还没有发过帖~</p>
            </div>
           ) : (
             <>
               <div className="space-y-2">
                 {posts.map((post) => {
                const style = getBoardTheme(post.board);
                return (
                  <div
                    key={post.id}
                    onClick={() => !post.isDeleted && handlePostClick(post.id)}
                    className={`group rounded-xl border border-white/10 bg-[#141838]/60 p-2.5 backdrop-blur-sm transition-all duration-300 ${
                      post.isDeleted
                        ? 'opacity-60'
                        : 'cursor-pointer hover:-translate-y-0.5 hover:border-cyan-400/40 hover:shadow-[0_0_20px_rgba(34_211_238_0.2)]'
                    }`}
                  >
                    <div className="mb-2 flex items-center justify-between gap-2">
                      <Badge
                        className={`${style.border} ${style.bg} ${style.text} border font-medium text-xs`}
                        variant="outline"
                      >
                        {post.board}
                      </Badge>
                    </div>
                    {post.isDeleted ? (
                      <div className="py-4 text-center">
                        <p className="text-base text-gray-500">内容已删除</p>
                      </div>
                    ) : (
                      <>
                        <h3 className="mb-1.5 text-lg font-bold text-white group-hover:text-cyan-300">
                          {post.title}
                        </h3>
                        <p
                          className="mb-2 text-base leading-relaxed text-gray-400"
                          style={{
                            display: '-webkit-box',
                            WebkitLineClamp: 2,
                            WebkitBoxOrient: 'vertical',
                            overflow: 'hidden',
                          }}
                        >
                          {post.content}
                        </p>
                        <div className="flex flex-wrap items-center gap-x-3 gap-y-0.5 text-sm text-gray-500">
                          <span className="whitespace-nowrap">
                            {dayjs(post.createdAt).format('MM-DD HH:mm')}
                          </span>
                          <span className="flex items-center gap-1 text-gray-400">
                            <ThumbsUp className="h-3.5 w-3.5" />
                            {post.likeCount}
                          </span>
                          <span className="flex items-center gap-1 text-gray-400">
                            <MessageSquare className="h-3.5 w-3.5" />
                            {post.commentCount}
                          </span>
                        </div>
                      </>
                    )}
                  </div>
                );
                 })}
               </div>
               <div ref={sentinelRef} />
               <InfiniteScrollFooter
                 loading={infiniteLoading}
                 hasMore={hasMore}
                 hasItems={posts.length > 0}
               />
             </>
           )
         ) : comments.length === 0 ? (
          <div className="rounded-xl border border-white/10 bg-[#141838]/50 py-16 text-center">
            <div className="mb-3 flex justify-center">
              <MessageSquareText className="h-10 w-10 text-purple-400/40" />
            </div>
            <p className="text-base text-gray-500">该用户还没有发过评论~</p>
          </div>
         ) : (
           <>
             <div className="space-y-2">
               {comments.map((item) => {
              const path = getTargetPath(item.targetType, item.targetId);
              const clickable = !!path;
              return (
                <div
                  key={item.id}
                  onClick={() => clickable && handleCommentClick(item)}
                  className={`group rounded-xl border border-white/10 bg-[#141838]/60 p-3 backdrop-blur-sm transition-all ${
                    clickable
                      ? 'cursor-pointer hover:border-purple-400/40 hover:shadow-[0_0_15px_rgba(168_85_247_0.15)]'
                      : ''
                  }`}
                >
                  {/* 顶部：帖子标题 */}
                  <div className="mb-2 flex items-center gap-2">
                    <span className="text-xs text-gray-500">回复了帖子 ·</span>
                    <span
                      className={`text-xs font-medium truncate ${
                        clickable
                          ? 'text-cyan-300 group-hover:text-cyan-200'
                          : 'text-gray-400'
                      }`}
                    >
                      {item.targetTitle || '未知内容'}
                    </span>
                  </div>
                  {/* 评论内容 */}
                  <p className="text-base text-white/90 leading-relaxed break-words">
                    {item.content}
                  </p>
                  {/* 底部 */}
                  <div className="mt-2 flex items-center gap-3 text-xs text-gray-500">
                    <span className="flex items-center gap-1">
                      <ThumbsUp className="h-3.5 w-3.5" />
                      {item.likeCount}
                    </span>
                    <span>{dayjs(item.createdAt).format('MM-DD HH:mm')}</span>
                  </div>
                </div>
              );
               })}
             </div>
             <div ref={sentinelRef} />
             <InfiniteScrollFooter
               loading={infiniteLoading}
               hasMore={hasMore}
               hasItems={comments.length > 0}
             />
           </>
         )}
      </div>
    </div>
  );
};

export default UserProfilePage;
