export function getAllPositions(): PositionWeight[] {
  return POSITIONS;
}

export function getPositionByKey(key: string): PositionWeight | undefined {
  return POSITIONS.find((p) => p.key === key);
}

export function getAttrLabel(key: string): string {
  return ATTR_LABEL_MAP[key] ?? key;
}

function buildPointsByAttr(allocations: Record<string, number>): Record<string, number> {
  const map: Record<string, number> = {};
  if (!allocations) return map;
  for (const cat of BUILD_CATEGORIES) {
    const points = Number(allocations[cat.key] ?? 0) || 0;
    for (const attr of cat.attributes) {
      map[attr.key] = (map[attr.key] ?? 0) + points;
    }
  }
  return map;
}

function getAttrCurrentValue(
  attrKey: string,
  baseStats: Record<string, number>,
  pointsByAttr: Record<string, number>,
  boostMap: Record<string, number>,
  coachBonusMap: Record<string, number>,
  styleBonusMap: Record<string, number> = {},
  boosterBonusMap: Record<string, number> = {},
  shineBonusMap: Record<string, number> = {},
): number {
  const base = Number(baseStats[attrKey] ?? 0) || 0;
  const boost = Number(boostMap[attrKey] ?? 0) || 0;
  const cBonus = Number(coachBonusMap[attrKey] ?? 0) || 0;
  const sBonus = Number(styleBonusMap[attrKey] ?? 0) || 0;
  const bBonus = Number(boosterBonusMap[attrKey] ?? 0) || 0;
  const shine = Number(shineBonusMap[attrKey] ?? 0) || 0;
  const points = Number(pointsByAttr[attrKey] ?? 0) || 0;
  const result = base + points + shine + boost + cBonus + sBonus + bBonus;
  return Number.isFinite(result) ? result : base;
}

export function calcPositionOverall(
  positionKey: string,
  baseStats: Record<string, number>,
  allocations: Record<string, number>,
  boostMap: Record<string, number>,
  coachBonusMap: Record<string, number>,
  height: number,
  styleBonusMap: Record<string, number> = {},
  boosterBonusMap: Record<string, number> = {},
  shineBonusMap: Record<string, number> = {},
): { overall: number; weightedSum: number } {
  const pos = POSITIONS.find((p) => p.key === positionKey);
  if (!pos) return { overall: 0, weightedSum: 0 };

  const safeHeight = Number.isFinite(height) ? height : 180;
  const safeBaseStats: Record<string, number> = baseStats || {};
  const safeAllocations: Record<string, number> = allocations || {};
  const safeBoostMap: Record<string, number> = boostMap || {};
  const safeCoachBonusMap: Record<string, number> = coachBonusMap || {};

  const pointsByAttr = buildPointsByAttr(safeAllocations);

  let sum = 0;
  for (const [attrKey, weight] of Object.entries(pos.weights)) {
    const w = Number.isFinite(weight) ? weight : 0;
    const value = attrKey === 'height'
      ? safeHeight
      : getAttrCurrentValue(attrKey, safeBaseStats, pointsByAttr, safeBoostMap, safeCoachBonusMap, styleBonusMap, boosterBonusMap, shineBonusMap);
    sum += value * w;
  }
  sum = Math.round(sum * 10000) / 10000;
  if (!Number.isFinite(sum)) sum = 0;
  const rawOverall = sum + (Number.isFinite(pos.intercept) ? pos.intercept : 0);
  const overall = Number.isFinite(rawOverall) ? Math.round(rawOverall) : 0;
  return { overall, weightedSum: sum };
}

export function getTopWeightedAttributes(
  positionKey: string,
  limit: number = 3,
): { key: string; label: string; weight: number }[] {
  const pos = POSITIONS.find((p) => p.key === positionKey);
  if (!pos) return [];
  return Object.entries(pos.weights)
    .filter(([k]) => k !== 'height')
    .map(([key, weight]) => ({
      key,
      label: ATTR_LABEL_MAP[key] ?? key,
      weight: Number.isFinite(weight) ? weight : 0,
    }))
    .sort((a, b) => b.weight - a.weight)
    .slice(0, limit);
}

export function getBoostMap(player: Player): Record<string, number> {
  const map: Record<string, number> = {};
  const traits = Array.isArray(player?.traitBonuses) ? player.traitBonuses as { name: string; bonus: number }[] : [];
  for (const trait of traits) {
    if (!trait || typeof trait.name !== 'string') continue;
    const attrKey = BOOST_TRAIT_MAP[trait.name];
    if (attrKey) {
      const bonus = Number(trait.bonus);
      map[attrKey] = (map[attrKey] || 0) + (Number.isFinite(bonus) ? bonus : 0);
    }
  }
  return map;
}

export function getPositionKeyByLabel(label: string): string {
  if (!label) return 'CF';
  const pos = POSITIONS.find((p) => p.label === label);
  if (pos) return pos.key;
  const byKey = POSITIONS.find((p) => p.key === label);
  if (byKey) return byKey.key;
  // 尝试大小写不敏感匹配
  const upperLabel = label.toUpperCase();
  const byUpper = POSITIONS.find((p) => p.key === upperLabel);
  if (byUpper) return byUpper.key;
  return 'CF';
}

export interface StyleBonusThresholds {
  plus3: number;
  plus2: number;
  plus1: number;
  plus3OverCap: boolean;
}

export interface AutoBuildResult {
  allocations: Record<string, number>;
  overall: number;
  pointsUsed: number;
}

function calcStyleBonusForValue(value: number, thresholds: StyleBonusThresholds | null): number {
  if (!thresholds) return 0;
  // 官方规则（2026-09 校准）：裸值 ≥ plus3 → +3；≥ plus2 → +2；其余 → +1（最低 +1，无 +0）
  if (value >= thresholds.plus3) return 3;
  if (value >= thresholds.plus2) return 2;
  return 1;
}

function buildStyleBonusMap(
  allocations: Record<string, number>,
  baseStats: Record<string, number>,
  boostMap: Record<string, number>,
  coachBonusMap: Record<string, number>,
  styleThresholds: StyleBonusThresholds | null,
  boosterBonusMap: Record<string, number> = {},
  shineBonusMap: Record<string, number> = {},
): Record<string, number> {
  const map: Record<string, number> = {};
  if (!styleThresholds) return map;
  const safeAllocations: Record<string, number> = allocations || {};
  const safeBaseStats: Record<string, number> = baseStats || {};
  const safeBoostMap: Record<string, number> = boostMap || {};
  const safeCoachBonusMap: Record<string, number> = coachBonusMap || {};
  const pointsByAttr = buildPointsByAttr(safeAllocations);
  for (const [key, baseVal] of Object.entries(safeBaseStats)) {
    const base = Number(baseVal) || 0;
    const shine = Number(shineBonusMap[key] ?? 0) || 0;
    const points = pointsByAttr[key] ?? 0;
    // 叠加顺序（2026-09 校正）：基础→闪耀→【熟练度】→第一增能→第二增能→教练能力值。
    // 熟练度在增能、教练能力值之前判定，门槛只取 base+points+shine。
    const current = base + points + shine;
    if (Number.isFinite(current)) {
      map[key] = calcStyleBonusForValue(current, styleThresholds);
    }
  }
  return map;
}

export function autoBuildForPosition(
  positionKey: string,
  baseStats: Record<string, number>,
  boostMap: Record<string, number>,
  coachBonusMap: Record<string, number>,
  height: number,
  maxLevel: number,
  styleThresholds: StyleBonusThresholds | null = null,
  boosterBonusMap: Record<string, number> = {},
  shineBonusMap: Record<string, number> = {},
  extraAvailablePoints: number = 0,
): AutoBuildResult {
  const allocations: Record<string, number> = {};
  const safeMaxLevel = Number.isFinite(maxLevel) ? maxLevel : 0;
  let available = calcAvailablePoints(safeMaxLevel, {}) + (Number.isFinite(extraAvailablePoints) ? extraAvailablePoints : 0);
  if (!Number.isFinite(available) || available < 0) available = 0;

  const calcWeighted = (allocs: Record<string, number>): number => {
    const sBonusMap = buildStyleBonusMap(allocs, baseStats, boostMap, coachBonusMap, styleThresholds, boosterBonusMap, shineBonusMap);
    const result = calcPositionOverall(positionKey, baseStats, allocs, boostMap, coachBonusMap, height, sBonusMap, boosterBonusMap, shineBonusMap).weightedSum;
    return Number.isFinite(result) ? result : 0;
  };

  const safeBaseStats: Record<string, number> = baseStats || {};
  const safeBoostMap: Record<string, number> = boostMap || {};
  const safeCoachBonusMap: Record<string, number> = coachBonusMap || {};
  const safeShineBonusMap: Record<string, number> = shineBonusMap || {};

  const hasRoomForCategory = (catKey: string): boolean => {
    const cat = BUILD_CATEGORIES.find((c) => c.key === catKey);
    if (!cat) return false;
    const points = allocations[catKey] ?? 0;
    return cat.attributes.some((attr) => {
      const base = Number(safeBaseStats[attr.key] ?? 0) || 0;
      const boost = Number(safeBoostMap[attr.key] ?? 0) || 0;
      const cBonus = Number(safeCoachBonusMap[attr.key] ?? 0) || 0;
      const shine = Number(safeShineBonusMap[attr.key] ?? 0) || 0;
      return true;
    });
  };

  while (true) {
    let bestCat: string | null = null;
    let bestEfficiency = -1;
    let bestCost = 0;

    for (const cat of BUILD_CATEGORIES) {
      const points = allocations[cat.key] ?? 0;
      const cost = getCostForNextPoint(points);
      if (cost > available) continue;
      if (!hasRoomForCategory(cat.key)) continue;

      const testAllocs = { ...allocations, [cat.key]: points + 1 };
      const currentW = calcWeighted(allocations);
      const newW = calcWeighted(testAllocs);
      const gain = newW - currentW;
      const efficiency = gain / cost;

      if (efficiency > bestEfficiency) {
        bestEfficiency = efficiency;
        bestCat = cat.key;
        bestCost = cost;
      }
    }

    if (!bestCat || bestEfficiency <= 0.00001) break;
    allocations[bestCat] = (allocations[bestCat] ?? 0) + 1;
    available -= bestCost;
  }

  const finalStyleBonusMap = buildStyleBonusMap(allocations, safeBaseStats, safeBoostMap, safeCoachBonusMap, styleThresholds, boosterBonusMap, safeShineBonusMap);
  const overallResult = calcPositionOverall(positionKey, safeBaseStats, allocations, safeBoostMap, safeCoachBonusMap, height, finalStyleBonusMap, boosterBonusMap, safeShineBonusMap);
  const overall = Number.isFinite(overallResult.overall) ? overallResult.overall : 0;
  const totalPoints = calcAvailablePoints(safeMaxLevel, {});
  return {
    allocations,
    overall,
    pointsUsed: totalPoints - available,
  };
}
