import React, { useState, useMemo, useEffect } from 'react';
import { Search, X } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@client/src/components/ui/dialog';
import { Input } from '@client/src/components/ui/input';
import {
  type Booster,
  BOOSTER_COLOR_MAP,
  getBoosterAttrMap,
} from '@client/src/utils/booster-data';

interface CompareBoosterDialogProps {
  open: boolean;
  boosterList: Booster[];
  selectedBooster: Booster | null;
  onClose: () => void;
  onConfirm: (booster: Booster | null) => void;
}

const CompareBoosterDialog: React.FC<CompareBoosterDialogProps> = ({
  open,
  boosterList,
  selectedBooster,
  onClose,
  onConfirm,
}) => {
  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState<'全部' | '普通' | '专项' | '团队' | '特殊'>('全部');

  useEffect(() => {
    if (open) {
      setSearch('');
      setTypeFilter('全部');
    }
  }, [open, selectedBooster]);

  const plusOneBoosters = useMemo(() => {
    return boosterList.filter((b) => b.bonusLevel === '+1');
  }, [boosterList]);

  const filtered = useMemo(() => {
    let result = plusOneBoosters;
    if (typeFilter !== '全部') {
      result = result.filter((b) => b.type === typeFilter);
    }
    if (search.trim()) {
      const keyword = search.trim().toLowerCase();
      result = result.filter((b) => b.name.toLowerCase().includes(keyword));
    }
    return result;
  }, [plusOneBoosters, search, typeFilter]);

  const typeOptions: ('全部' | '普通' | '专项' | '团队' | '特殊')[] = ['全部', '普通', '专项', '团队', '特殊'];

  const handleSelectNone = () => {
    onConfirm(null);
    onClose();
  };

  const handleSelect = (booster: Booster) => {
    onConfirm(booster);
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="w-[92vw] sm:max-w-[650px] max-h-[80vh] bg-[#0f1330] border border-white/10 text-white overflow-hidden p-0">
        <DialogHeader className="px-5 pt-5 pb-3 border-b border-white/10">
          <DialogTitle className="text-lg font-bold text-white">选择第二增能</DialogTitle>
          <Input
            type="text"
            placeholder="搜索增能名称..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="h-9 border-white/10 bg-[#0A0E27] text-sm text-white focus-visible:border-purple-400/70 mt-2"
          />
          <div className="flex gap-1.5 mt-3">
            {typeOptions.map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => setTypeFilter(t)}
                className={`px-3 py-1 rounded-md text-xs font-medium transition-all ${
                  typeFilter === t
                    ? 'bg-purple-500/30 text-purple-200 border border-purple-400/50'
                    : 'bg-white/5 text-gray-400 border border-white/10 hover:text-gray-300 hover:bg-white/10'
                }`}
              >
                {t}
              </button>
            ))}
          </div>
        </DialogHeader>

        <div className="overflow-y-auto p-4 space-y-2" style={{ maxHeight: 'calc(80vh - 130px)' }}>
          {/* 无增能 */}
          <button
            type="button"
            onClick={handleSelectNone}
            className="w-full text-left px-4 py-3 rounded-lg border transition-all border-white/10 bg-white/5 hover:border-purple-400/40 hover:bg-purple-500/5"
          >
            <div className="flex items-center justify-between">
              <span className="text-base font-medium text-gray-300">无增能</span>
              <span className="text-xs text-gray-500">不使用增能加成</span>
            </div>
          </button>

          {filtered.length === 0 ? (
            <div className="py-8 text-center text-sm text-gray-400">未找到匹配的增能</div>
          ) : (
            filtered.map((b) => {
              const colorConfig = BOOSTER_COLOR_MAP[b.color];
              const bonusText = b.bonusScope === '全部'
                ? `全部属性${b.bonusLevel}`
                : `${b.abilities.join('、')}${b.bonusLevel}`;
              return (
                <button
                  key={b.id}
                  type="button"
                  onClick={() => handleSelect(b)}
                  className="w-full text-left px-4 py-3 rounded-lg border transition-all border-white/10 bg-white/5 hover:border-purple-400/40 hover:bg-purple-500/5"
                >
                  <div className="flex items-start gap-3">
                    {/* 六边形图标 */}
                    <div className="shrink-0 mt-0.5">
                      <svg className="w-10 h-10" viewBox="0 0 24 24">
                        <polygon
                          points="12,2 22,7 22,17 12,22 2,17 2,7"
                          fill={colorConfig.hex}
                          fillOpacity={0.85}
                          stroke={colorConfig.hex}
                          strokeWidth={1}
                        />
                      </svg>
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between gap-2">
                        <div className="text-base font-bold text-white truncate">{b.name}</div>
                      </div>
                      <div className="flex items-center gap-2 mt-1">
                        <span className={`text-[10px] px-1.5 py-0.5 rounded ${colorConfig.bg} ${colorConfig.text} ${colorConfig.border} border font-medium`}>
                          {b.type}
                        </span>
                        <span className="text-xs text-gray-300">{b.bonusLevel}</span>
                      </div>
                      <div className="text-xs text-purple-300 mt-1.5 leading-relaxed">
                        {bonusText}
                      </div>
                    </div>
                  </div>
                </button>
              );
            })
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default CompareBoosterDialog;
