import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';
import type { Coach, CoachListResponse, CoachListQuery } from '@shared/api.interface';

export async function getCoachList(params: CoachListQuery = {}): Promise<CoachListResponse> {
  const response = await axiosForBackend.get('/api/coaches', { params });
  return response.data;
}

export async function getCoachDetail(id: string): Promise<Coach> {
  const response = await axiosForBackend.get(`/api/coaches/${id}`);
  return response.data;
}

export interface CoachFilterOptions {
  countries: string[];
  fitTypes: string[];
  managerBonuses: string[];
  ageRange: { min: number; max: number };
}

export async function getCoachFilterOptions(): Promise<CoachFilterOptions> {
  const response = await axiosForBackend.get('/api/coaches/filter-options');
  return response.data;
}
