export const FORM_CONSISTENCY_LABELS: Record<number, string> = {
  0: '不稳定',
  1: '标准',
  2: '稳定',
};

export function getFormConsistencyLabel(value: number): string {
  return FORM_CONSISTENCY_LABELS[value] ?? '—';
}

export const FORM_CONSISTENCY_FILTER_OPTIONS: { value: string; label: string }[] = [
  { value: '0', label: '不稳定' },
  { value: '1', label: '标准' },
  { value: '2', label: '稳定' },
];
