import React from 'react';
import { LOCAL_ASSETS } from '@client/src/utils/local-assets';
import { ICON_DATA_URI } from '@client/src/utils/brand-icon-data';

// 行楷字体栈：优先华文行楷，缺失时回退楷体/系统手写体
const XINGKAI = "'STXingkai', '华文行楷', '华文楷体', 'KaiTi', 'STKaiti', cursive";

interface BrandWatermarkProps {
  // 位置：居中（默认）或右上角
  position?: 'center' | 'top-right';
  // 是否显示淡蓝色圆形底纹（默认不显示——全平台水印已统一去掉圆形底纹）
  showCircle?: boolean;
  // 居中模式下的垂直定位（默认在容器约 16% 处）
  topClassName?: string;
  className?: string;
}

/**
 * 品牌水印（界面用）：
 * - 整体浅灰色；“实况起点”用华文行楷；
 * - 图标 / 网址 / 实况起点 三行收紧；
 * - 默认无圆形底纹；可置于居中或右上角。
 * 纯展示、不拦截任何指针操作。
 */
const BrandWatermark: React.FC<BrandWatermarkProps> = ({
  position = 'center',
  showCircle = false,
  topClassName = 'top-[16%]',
  className = '',
}) => {
  // 本地路径逐个兜底，最终用内联 data URI，保证水印 logo 永不丢失
  const iconCandidates = [...LOCAL_ASSETS.iconCandidates, ICON_DATA_URI];
  const inner = (
    <div className="relative flex flex-col items-center">
      {showCircle && (
        <div
          aria-hidden
          className="absolute left-1/2 top-1/2 h-[147px] w-[147px] -translate-x-1/2 -translate-y-1/2 rounded-full bg-sky-400/15 shadow-[0_0_30px_rgba(125,200,255,0.2)]"
        />
      )}
      <img
        src={iconCandidates[0]}
        alt=""
        draggable={false}
        onError={(e) => {
          const imgEl = e.currentTarget;
          const idx = imgEl.dataset.i ? Number(imgEl.dataset.i) : 0;
          const nxt = idx + 1;
          if (nxt < iconCandidates.length) {
            imgEl.dataset.i = String(nxt);
            imgEl.src = iconCandidates[nxt];
          }
        }}
        className="relative h-12 w-12 opacity-70 drop-shadow-[0_2px_5px_rgba(0,0,0,0.55)]"
      />
      <p className="relative mt-0.5 text-base font-black tracking-wide text-slate-300/70 drop-shadow-[0_1px_3px_rgba(0,0,0,0.6)]">
        PlayToStar APP
      </p>
      <p
        className="relative text-sm leading-tight text-slate-300/70 drop-shadow-[0_1px_3px_rgba(0,0,0,0.6)]"
        style={{ fontFamily: XINGKAI }}
      >
        实况起点
      </p>
    </div>
  );

  if (position === 'top-right') {
    return (
      <div className={`pointer-events-none absolute right-3 top-3 z-30 flex justify-end ${className}`}>
        {inner}
      </div>
    );
  }

  return (
    <div
      className={`pointer-events-none absolute inset-x-0 z-30 flex justify-center ${topClassName} ${className}`}
    >
      {inner}
    </div>
  );
};

export default BrandWatermark;
