// 跨组件共享当前球员的“培养草稿”（加点 allocations + 教练 coachId + 自定义新增技能 extraSkills）。
// BuildPanel 持有加点与教练、SkillsList 持有新增技能；任一保存时读取对方最新值，
// 实现“保存加点 / 保存技能”都把完整维度一起写入，避免个人中心培养方案只显示其一。
type Draft = {
  allocations: Record<string, number> | null;
  coachId: string | null;
  extraSkills: string[] | null;
  secondBooster: string | null;
  shineLevel: number | null;
};

const cache = new Map<string, Draft>();

function ensure(playerId: string): Draft {
  let d = cache.get(playerId);
  if (!d) {
    d = { allocations: null, coachId: null, extraSkills: null, secondBooster: null, shineLevel: null };
    cache.set(playerId, d);
  }
  return d;
}

export function setDraftAllocations(
  playerId: string,
  allocations: Record<string, number>,
): void {
  ensure(playerId).allocations = allocations;
}

export function setDraftCoach(playerId: string, coachId: string | null): void {
  ensure(playerId).coachId = coachId;
}

export function setDraftExtraSkills(playerId: string, skills: string[]): void {
  ensure(playerId).extraSkills = skills;
}

// 第二增能以“保存编码”形式共享：builtin:N（自带按档位）/ cat:ID（目录项）/ null（未选）
export function setDraftSecondBooster(playerId: string, encoded: string | null): void {
  ensure(playerId).secondBooster = encoded;
}

// 闪耀等级（0=无闪耀，1/2/3=对应档位）
export function setDraftShine(playerId: string, level: number): void {
  ensure(playerId).shineLevel = level;
}

export function getDraftAllocations(
  playerId: string,
): Record<string, number> | null {
  return cache.get(playerId)?.allocations ?? null;
}

export function getDraftCoach(playerId: string): string | null {
  return cache.get(playerId)?.coachId ?? null;
}

export function getDraftExtraSkills(playerId: string): string[] | null {
  return cache.get(playerId)?.extraSkills ?? null;
}

export function getDraftSecondBooster(playerId: string): string | null {
  return cache.get(playerId)?.secondBooster ?? null;
}

export function getDraftShine(playerId: string): number | null {
  return cache.get(playerId)?.shineLevel ?? null;
}
