  'offensiveAwareness', 'ballControl', 'dribbling', 'tightPossession',
  'lowPass', 'loftedPass', 'finishing', 'header', 'setPieceTaking', 'curve',
  'speed', 'acceleration', 'kickingPower', 'jump', 'physicalContact',
