// 统一颜色表改由 unified-colors.ts 维护（全平台唯一来源），这里直接转出
export { BOOSTER_COLOR_MAP } from './unified-colors';

const API_COLOR_TO_LOCAL: Record<number, '蓝' | '黄' | '橙' | '紫' | '灰'> = {
  0: '灰',
  1: '蓝',
  2: '紫',
  3: '黄',
};

const API_GROUP_TO_TYPE: Record<string, '普通' | '专项' | '团队' | '特殊'> = {
  left: '普通',
  right: '专项',
  center: '团队',
  special: '特殊',
};

export function parseBoosterBonusDetail(bonusDetail: string): { abilities: string[]; bonusValue: number } {
  const abilities: string[] = [];
  let bonusValue = 0;
  const parts = bonusDetail.split(/[；;\n]+/).filter(Boolean);
  for (const part of parts) {
    const match = part.trim().match(/^(.+?)\s*[+]\s*(\d+)\s*$/);
    if (match) {
      const attrName = match[1].trim();
      const val = parseInt(match[2], 10);
      if (ATTR_KEY_MAP[attrName]) {
        abilities.push(attrName);
        if (bonusValue === 0) bonusValue = val;
      }
    }
  }
  return { abilities, bonusValue };
}

export function apiBoosterToLocal(api: ApiBooster, playerType?: string | null): Booster {
  const { abilities, bonusValue } = parseBoosterBonusDetail(api.bonusDetail);
  let nameCn = api.nameCn || api.nameEn;
  const nameLevelMatch = nameCn.match(/^(.+?)\s*[+]\s*\d+\s*$/);
  if (nameLevelMatch) nameCn = nameLevelMatch[1].trim();
  let nameEn = api.nameEn || '';
  const nameEnLevelMatch = nameEn.match(/^(.+?)\s*[+]\s*\d+\s*$/);
  if (nameEnLevelMatch) nameEn = nameEnLevelMatch[1].trim();
  const isTotal = nameCn.includes('全面提升') || nameCn.toLowerCase().includes('total');
  const level = api.level || bonusValue || 1;
  // 颜色统一走 unified-colors：传入所属球员 player_type 以判定“状态火热→绿”
  const color = resolveBoosterColorKey({
    name: nameCn,
    abilityCount: abilities.length,
    level,
    isTotal,
    playerType,
  });
  const type = API_GROUP_TO_TYPE[api.groupKey] ?? '普通';
  let bonusScope: '4项' | '单项' | '全部' = '4项';
  if (abilities.length === 1) bonusScope = '单项';
  else if (abilities.length > 10) bonusScope = '全部';
  return {
    id: api.id,
    name: nameCn,
    nameEn: nameEn || undefined,
    type,
    color,
    bonusLevel: `+${level}`,
    bonusValue: level || bonusValue,
    bonusScope,
    abilities,
  };
}
