import { logger } from '@lark-apaas/client-toolkit/logger';
import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';
import type { RatingSummary, SubmitRatingDto } from '@shared/api.interface';

export async function getSummary(
  targetType: string,
  targetId: string,
): Promise<RatingSummary> {
  try {
    const response = await axiosForBackend.get<RatingSummary>(
      '/api/ratings/summary',
      { params: { targetType, targetId } },
    );
    return response.data;
  } catch (error) {
    logger.error('获取评分汇总失败', error);
    throw error;
  }
}

export async function submit(
  dto: SubmitRatingDto,
  headers?: Record<string, string>,
): Promise<RatingSummary> {
  try {
    const response = await axiosForBackend.post<RatingSummary>(
      '/api/ratings',
      dto,
      { headers },
    );
    return response.data;
  } catch (error) {
    logger.error('提交评分失败', error);
    throw error;
  }
}
