import React, { useRef, useState, useMemo, useLayoutEffect } from 'react';
import { Sparkles, Award, Eye, EyeOff } from 'lucide-react';
import type { Player } from '@shared/api.interface';
import { isStSkill, isSameSkill, isGKPosition } from '../players/player-utils';
import { isHiddenSkill } from '@shared/hidden-skills';

interface CompareSkillsProps {
  playerList: Player[];
  hideSame: boolean;
  onToggleHideSame: () => void;
}

const PLAYER_COLORS = [
  '#00E5FF',
  '#FF9F1C',
  '#4ADE80',
  '#A78BFA',
  '#22D3EE',
  '#F472B6',
];

const getPlayerShortName = (name: string): string => {
  if (!name) return '';
  const parts = name.split(/[·\s]+/).filter(Boolean);
  return parts.length > 1 ? parts[parts.length - 1] : name;
};

const SKILL_ROW_CLASS = 'grid items-center border-b border-white/5 last:border-b-0 px-2 sm:px-3 py-2 sm:py-2.5';

const CompareSkills: React.FC<CompareSkillsProps> = ({ playerList, hideSame, onToggleHideSame }) => {
  const playerCount = playerList.length;
  const containerRef = useRef<HTMLDivElement | null>(null);
  const [gridCols, setGridCols] = useState<string>(
    `120px repeat(${playerCount}, minmax(0, 1fr))`,
  );

  useLayoutEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const update = () => {
      const w = el.clientWidth;
      // 名称列加宽：完整容纳最长 7 字技能名（放大后），剩余给圆点列
      const nameColW = w < 640 ? 168 : 200;
      setGridCols(`${nameColW}px repeat(${playerCount}, minmax(0, 1fr))`);
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => ro.disconnect();
  }, [playerCount]);

  const { stSkills, normalSkills } = useMemo(() => {
    const allSkills = new Set<string>();
    for (const p of playerList) {
      for (const s of p.skills || []) {
        if (!isHiddenSkill(s)) allSkills.add(s);
      }
    }
    const sorted = [...allSkills].sort((a, b) => a.localeCompare(b, 'zh-CN'));
    const hasGK = playerList.some((p) => isGKPosition(p.position));
    const merged: string[] = [];
    const seen = new Set<string>();
    for (const s of sorted) {
      if (seen.has(s)) continue;
      const group = sorted.filter((x) => isSameSkill(x, s));
      for (const g of group) seen.add(g);
      const displayName = hasGK && group.some((g) => isSameSkill(g, '大力手抛球'))
        ? '门将大力手抛球'
        : group[0];
      merged.push(displayName);
    }
    const st = merged.filter((s) => isStSkill(s));
    const normal = merged.filter((s) => !isStSkill(s));
    return { stSkills: st, normalSkills: normal };
  }, [playerList]);

  const hasSkill = (player: Player, skill: string): boolean => {
    return (player.skills || []).some((s) => isSameSkill(s, skill));
  };

  const isSkillSame = (skill: string): boolean => {
    const first = hasSkill(playerList[0], skill);
    return playerList.every((p) => hasSkill(p, skill) === first);
  };

  const visibleStSkills = hideSame ? stSkills.filter((s) => !isSkillSame(s)) : stSkills;
  const visibleNormalSkills = hideSame ? normalSkills.filter((s) => !isSkillSame(s)) : normalSkills;
  const totalCount = stSkills.length + normalSkills.length;
  const visibleCount = visibleStSkills.length + visibleNormalSkills.length;

  const renderSkillName = (skill: string, isSt: boolean) => {
    const colorClass = isSt ? 'text-[#FFB3D9]' : 'text-gray-300';
    return (
      <span className={`text-2xl sm:text-base font-medium leading-tight ${colorClass} whitespace-nowrap truncate`}>
        {skill}
      </span>
    );
  };

  const renderPlayerDot = (p: Player, idx: number, skill: string) => {
    const has = hasSkill(p, skill);
    const color = PLAYER_COLORS[idx % PLAYER_COLORS.length];
    if (has) {
      return (
        <span
          className="w-4 h-4 sm:w-5 sm:h-5 rounded-full mx-auto"
          style={{
            backgroundColor: color,
            boxShadow: `0 0 8px ${color}`,
          }}
        />
      );
    }
    return (
      <span className="w-4 h-4 sm:w-5 sm:h-5 rounded-full border border-white/15 mx-auto" />
    );
  };

  const renderGroupHeader = (label: string, count: number, accent: 'st' | 'normal') => (
    <div
      className={`px-2 sm:px-3 py-1.5 sm:py-2 border-b border-white/5 ${
        accent === 'st' ? 'bg-[#FF2D95]/5' : 'bg-white/[0.02]'
      }`}
    >
      <span
        className={`text-base sm:text-base font-semibold ${
          accent === 'st' ? 'text-[#FF6BB5]' : 'text-gray-400'
        }`}
      >
        {label} · {count} 项
      </span>
    </div>
  );

  return (
    <div className="rounded-xl bg-[#141838] border border-white/10 overflow-hidden">
      <div className="px-3 sm:px-4 py-2 sm:py-3 bg-white/[0.03]">
        <div className="flex items-center justify-between gap-2">
          <div className="flex items-center gap-2 min-w-0">
            <span className="w-1 h-4 sm:h-5 bg-gradient-to-b from-pink-400 to-rose-500 rounded-full flex-shrink-0" />
            <h3 className="text-2xl sm:text-2xl font-bold text-white truncate">球员技能对比</h3>
            <span className="text-lg sm:text-lg text-gray-500 flex-shrink-0">
              共 {hideSame ? `${visibleCount}/${totalCount}` : totalCount} 项
            </span>
          </div>
          <button
            type="button"
            onClick={onToggleHideSame}
            className={`flex items-center gap-1.5 px-2.5 sm:px-3 py-1 rounded-lg text-base sm:text-sm font-medium transition-colors flex-shrink-0 ${
              hideSame
                ? 'bg-pink-500/20 text-pink-300 border border-pink-400/40'
                : 'bg-white/5 text-gray-400 border border-white/10 hover:bg-white/10 hover:text-gray-200'
            }`}
          >
            {hideSame ? <EyeOff className="w-3.5 h-3.5 sm:w-4 sm:h-4" /> : <Eye className="w-3.5 h-3.5 sm:w-4 sm:h-4" />}
            <span className="hidden sm:inline">隐藏相同</span>
            <span className="sm:hidden">隐藏相同</span>
          </button>
        </div>
      </div>

      {totalCount === 0 ? (
        <div className="px-3 sm:px-4 py-6 sm:py-8 text-center text-base sm:text-xl text-gray-500">
          暂无技能数据
        </div>
      ) : visibleCount === 0 && hideSame ? (
        <div className="px-3 sm:px-4 py-6 sm:py-8 text-center text-base sm:text-xl text-gray-500">
          所有技能状态相同，已全部隐藏
        </div>
      ) : (
        <div ref={containerRef} className="w-full min-w-0">
          <div
            className="grid border-b border-white/10 bg-white/[0.02] px-2 sm:px-3 py-1.5 sm:py-2 items-center"
            style={{ gridTemplateColumns: gridCols }}
          >
            <span className="text-lg sm:text-base font-semibold text-gray-400">技能名</span>
            {playerList.map((p, idx) => (
              <span
                key={p.id}
                className="text-lg sm:text-base font-semibold text-center truncate"
                style={{ color: PLAYER_COLORS[idx % PLAYER_COLORS.length] }}
                title={p.nameZh}
              >
                {getPlayerShortName(p.nameZh)}
              </span>
            ))}
          </div>

          {visibleStSkills.length > 0 && (
            <>
              {renderGroupHeader('⚡ ST 技能', visibleStSkills.length, 'st')}
              {visibleStSkills.map((s) => (
                <div
                  key={s}
                  className={`${SKILL_ROW_CLASS} bg-[#FF2D95]/[0.03]`}
                  style={{ gridTemplateColumns: gridCols }}
                >
                  <div className="flex items-center gap-1.5 sm:gap-2 min-w-0">
                    <Sparkles className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-[#FF2D95] flex-shrink-0" />
                    {renderSkillName(s, true)}
                  </div>
                  {playerList.map((p, idx) => (
                    <div key={p.id} className="flex justify-center items-center">
                      {renderPlayerDot(p, idx, s)}
                    </div>
                  ))}
                </div>
              ))}
            </>
          )}

          {visibleNormalSkills.length > 0 && (
            <>
              {renderGroupHeader('普通技能', visibleNormalSkills.length, 'normal')}
              {visibleNormalSkills.map((s) => (
                <div
                  key={s}
                  className={SKILL_ROW_CLASS}
                  style={{ gridTemplateColumns: gridCols }}
                >
                  <div className="flex items-center gap-1.5 sm:gap-2 min-w-0">
                    <Award className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-gray-500 flex-shrink-0" />
                    {renderSkillName(s, false)}
                  </div>
                  {playerList.map((p, idx) => (
                    <div key={p.id} className="flex justify-center items-center">
                      {renderPlayerDot(p, idx, s)}
                    </div>
                  ))}
                </div>
              ))}
            </>
          )}
        </div>
      )}

      <div className="px-3 sm:px-4 py-2 sm:py-3 flex flex-wrap justify-center gap-3 sm:gap-4 border-t border-white/5">
        {playerList.map((p, idx) => (
          <div key={p.id} className="flex items-center gap-1.5 sm:gap-2">
            <span
              className="w-2.5 h-2.5 sm:w-3 sm:h-3 rounded-full"
              style={{
                backgroundColor: PLAYER_COLORS[idx % PLAYER_COLORS.length],
                boxShadow: `0 0 6px ${PLAYER_COLORS[idx % PLAYER_COLORS.length]}`,
              }}
            />
            <span className="text-lg sm:text-lg text-gray-400">{p.nameZh}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default CompareSkills;
