import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { Play, X } from 'lucide-react';
import type { CommentMediaItem } from '@shared/api.interface';
import { Image as UIImage } from '@client/src/components/ui/image';
import ZoomableImage from '@client/src/components/ZoomableImage';

interface CommentMediaDisplayProps {
  mediaList: CommentMediaItem[];
  size?: 'small' | 'normal';
}

const CommentMediaDisplay: React.FC<CommentMediaDisplayProps> = ({
  mediaList,
  size = 'normal',
}) => {
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(true);
    return () => setMounted(false);
  }, []);
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null);
  const images = mediaList.filter((m) => m.type === 'image');
  const videos = mediaList.filter((m) => m.type === 'video');

  if (mediaList.length === 0) return null;

  // 评论区（含回帖，回帖与主帖统一用 normal）附图/视频预览放大到约 1.5 倍：
  // 图 96→144（sm 160），视频 144×96→224×144（sm 240×160）；small（个人中心等）同步放大
  const imgSize = size === 'small' ? 'w-32 h-32' : 'w-36 h-36 sm:w-40 sm:h-40';
  const videoW = size === 'small' ? 'w-48 h-32' : 'w-56 h-36 sm:w-60 sm:h-40';

  return (
    <div className="space-y-2">
      {images.length > 0 && (
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-1.5 max-w-md">
          {images.map((img, idx) => (
            <button
              key={idx}
              onClick={() => setLightboxIndex(idx)}
              className={`relative aspect-square overflow-hidden rounded-lg border border-white/10 transition-all hover:border-cyan-400/40 ${imgSize}`}
            >
              <UIImage src={img.url} alt={img.filename} className="h-full w-full object-cover" loading="lazy" />
            </button>
          ))}
        </div>
      )}
      {videos.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {videos.map((video, idx) => (
            <div
              key={idx}
              className={`relative overflow-hidden rounded-lg border border-white/10 bg-black ${videoW}`}
            >
              <Play className="absolute left-1/2 top-1/2 h-5 w-5 -translate-x-1/2 -translate-y-1/2 text-white/80" />
              <video src={video.url} preload="metadata" controls className="h-full w-full object-contain" />
            </div>
          ))}
        </div>
      )}

      {/* 灯箱 */}
      {lightboxIndex !== null && images.length > 0 && mounted ? createPortal(
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/90"
          onClick={() => setLightboxIndex(null)}
        >
          <button
            onClick={(e) => { e.stopPropagation(); setLightboxIndex(null); }}
            className="absolute right-4 top-4 flex h-10 w-10 items-center justify-center rounded-full bg-white/10 text-white hover:bg-white/20"
            aria-label="关闭"
          >
            <X className="h-5 w-5" />
          </button>
          <div
            className="flex max-h-[85vh] max-w-[90vw] items-center justify-center"
            onClick={(e) => e.stopPropagation()}
          >
            <ZoomableImage
              src={images[lightboxIndex].url}
              alt={images[lightboxIndex].filename}
              className="max-h-[85vh] max-w-[90vw] object-contain"
            />
          </div>
          <div className="pointer-events-none absolute bottom-4 left-1/2 -translate-x-1/2 text-sm text-white/60">
            {lightboxIndex + 1} / {images.length}
          </div>
        </div>,
        document.body,
      ) : null}
    </div>
  );
};

export default CommentMediaDisplay;
