import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import { ArrowLeft, Loader2, BookOpen } from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { useAuth } from '@client/src/context/AuthContext';
import { useLoginGuard } from '@client/src/hooks/useLoginGuard';
import { ratings } from '@client/src/api';
import RatingStars from '@client/src/components/RatingStars';
import CommentSection from '@client/src/components/CommentSection';
import { ABILITY_VALUE_GROUPS } from './abilityValues';
import { toRouterPath } from '@client/src/utils/router-path';
import type { RatingSummary } from '@shared/api.interface';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';
import { useWebLandscape } from '@client/src/hooks/use-native-app';
import {
  visitorLocalGet,
  visitorLocalSet,
  toastVisitorLocal,
} from '@client/src/utils/visitor-mode';

// 网页横屏下字体缩小 2 档
const DOWN2: Record<string, string> = {
  'text-6xl': 'text-4xl',
  'text-5xl': 'text-3xl',
  'text-4xl': 'text-2xl',
  'text-3xl': 'text-xl',
  'text-2xl': 'text-base',
  'text-xl': 'text-sm',
  'text-lg': 'text-sm',
  'text-base': 'text-xs',
};

const AbilityValueDetailPage: React.FC = () => {
  const { key } = useParams<{ key: string }>();
  const navigate = useNavigate();
  const location = useLocation();
  const { user, getAuthHeaders } = useAuth();
  const { allowLocalAction } = useLoginGuard();
  const { t, lang } = useI18n();
  const compact = useWebLandscape();
  const sc = (cls: string) => (compact ? DOWN2[cls] ?? cls : cls);

  const [ratingSummary, setRatingSummary] = useState<RatingSummary | null>(null);
  const [ratingLoading, setRatingLoading] = useState(false);
  // 游客本机评分（kind='rating'，key=`ability_value:${ability.key}`）；已登录走云端 userScore
  const [visitorScore, setVisitorScore] = useState<number | null>(null);

  const ability = useMemo(() => {
    if (!key) return null;
    for (const group of ABILITY_VALUE_GROUPS) {
      const found = group.items.find((item) => item.key === key);
      if (found) {
        return { ...found, groupKey: group.groupKey, groupName: group.groupName };
      }
    }
    return null;
  }, [key]);

  const targetType = 'ability_value';

  const backPath = useMemo(() => {
    const state = location.state as { from?: string } | undefined;
    if (state?.from) return state.from;
    return '/encyclopedia?tab=ability_values';
  }, [location.state]);

  // 返回：优先回到来源（如球员详情）；无来源时退回浏览器历史；再退回百科列表
  const handleBack = () => {
    if ((location.state as { from?: string } | undefined)?.from) {
      navigate(toRouterPath(backPath));
    } else if (window.history.length > 1) {
      navigate(-1);
    } else {
      navigate(toRouterPath(backPath));
    }
  };

  useEffect(() => {
    if (!ability) return;
    ratings
      .getSummary(targetType, ability.key)
      .then((data) => {
        setRatingSummary(data);
        // 游客：读取本机评分作为展示分（average/count 仍为服务端值）
        if (!user) {
          const local = visitorLocalGet('rating', `${targetType}:${ability.key}`);
          setVisitorScore(local ? Number(local) : null);
        }
      })
      .catch((err: unknown) => {
        logger.error('加载评分失败', err);
      });
  }, [ability, targetType, user]);

  const handleRate = async (score: number) => {
    if (!allowLocalAction('评分')) return;
    if (!ability) return;
    // 游客：仅本机评分，不发云端请求
    if (!user) {
      visitorLocalSet('rating', `${targetType}:${ability.key}`, score);
      setVisitorScore(score);
      toastVisitorLocal('rating');
      return;
    }
    setRatingLoading(true);
    try {
      const res = await ratings.submit(
        { targetType, targetId: ability.key, score },
        getAuthHeaders(),
      );
      setRatingSummary(res);
    } catch (error) {
      logger.error('评分失败', error);
    } finally {
      setRatingLoading(false);
    }
  };

  if (!ability) {
    return (
      <div className="flex min-h-[60vh] flex-col items-center justify-center">
        <p className={`text-gray-400 mb-4 ${sc('text-2xl')}`}>{t('detail.abilityNotFound')}</p>
        <button
          onClick={handleBack}
          className={`flex items-center gap-2 px-4 py-2 rounded-lg bg-cyan-500/20 border border-cyan-400/50 text-cyan-300 ${sc('text-xl')} hover:bg-cyan-500/30 transition-colors`}
        >
          <ArrowLeft className="w-4 h-4" />
          {t('common.back')}
        </button>
      </div>
    );
  }

  return (
    <div className="min-h-screen text-white max-w-3xl mx-auto">
      <button
        onClick={handleBack}
        className={`mb-2 flex items-center gap-1.5 ${sc('text-xl')} text-gray-400 hover:text-cyan-300 transition-colors`}
      >
        <ArrowLeft className="w-4 h-4" />
        {t('common.back')}
      </button>

      {/* 头部信息 */}
      <div className="relative rounded-2xl border border-violet-400/40 bg-gradient-to-br from-violet-500/10 to-indigo-600/10 p-5 mb-3 backdrop-blur-sm">
        <div className="absolute top-4 right-4 flex h-10 w-10 items-center justify-center rounded-lg bg-violet-500/20 border border-violet-400/40">
          <BookOpen className="w-5 h-5 text-violet-300" />
        </div>

        <div className="flex items-start justify-between gap-4">
          <div>
            <p className={`${sc('text-lg')} text-gray-400 mb-1`}>
              {lang === 'en'
                ? `${t('enc.cat.ability_values')} · ${t('av.group.' + ability.groupKey)}`
                : `能力值 · ${ability.groupName}`}
            </p>
            <h1 className={`${sc('text-6xl')} font-black text-white mb-1 drop-shadow-[0_0_10px_rgba(139_92_246_0.3)]`}>
              {lang === 'en' ? trTerm(ability.name) : ability.name}
            </h1>
            <p className={`${sc('text-xl')} text-gray-400`}>{ability.key}</p>
          </div>

          <div className="flex-shrink-0">
            {ratingSummary ? (
              <div className="text-right">
                <RatingStars
                  value={
                    !user
                      ? (visitorScore ?? ratingSummary.average)
                      : (ratingSummary.userScore ?? ratingSummary.average)
                  }
                  count={ratingSummary.count}
                  interactive
                  size="lg"
                  onRate={handleRate}
                />
                 {ratingLoading && (
                   <p className="text-lg text-gray-500 mt-1">{t('detail.submitting')}</p>
                 )}
              </div>
            ) : (
              <div className="flex items-center justify-end">
                <Loader2 className="w-5 h-5 text-violet-400 animate-spin" />
              </div>
            )}
          </div>
        </div>
      </div>

      {/* 官方解释 */}
      <div className="rounded-xl border border-white/10 bg-card/60 p-5 mb-3 backdrop-blur-sm">
        <h3 className={`${sc('text-3xl')} font-semibold text-violet-300 mb-3 flex items-center gap-2`}>
          <span className="w-1 h-5 bg-gradient-to-b from-violet-400 to-indigo-500 rounded-full" />
          {t('detail.officialDesc')}
        </h3>
        <p className={`${sc('text-3xl')} text-gray-200 leading-relaxed`}>
          {lang === 'en' ? t('av.desc.' + ability.key) : ability.description}
        </p>
      </div>

      {/* 评论区 */}
      <CommentSection targetType={targetType} targetId={ability.key} />

      <div className="h-12" />
    </div>
  );
};

export default AbilityValueDetailPage;
