import {
  Plus,
  Minus,
  X,
  Sparkles,
  Target,
  ArrowRight,
  Triangle,
  Zap,
  Footprints,
  ArrowUp,
  Shield,
  Hand,
  Award,
  RotateCcw,
  TrendingUp,
} from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@client/src/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@client/src/components/ui/select';
import type { Player, Coach } from '@shared/api.interface';
import {
  BUILD_CATEGORIES,
  getCostForNextPoint,
  getRefundForCurrentPoints,
  calcAvailablePoints,
  MAX_POINTS_PER_CATEGORY,
  getTotalStatsSum,
} from '@client/src/utils/build-categories';
import { buildBaseStatsMap, buildStyleBonusMap, buildCoachBonusMap } from '@client/src/utils/compare-stats';
import { getBoosterAttrMap, BOOSTER_COLOR_MAP, buildBoosterColorMap, apiBoosterToLocal, type Booster } from '@client/src/utils/booster-data';
import { getShineBonusMap } from '@client/src/utils/shine-data';
