const ICON_MAP: Record<string, React.ComponentType<{ className?: string }>> = {
  Target,
  ArrowRight,
  Triangle,
  Zap,
  Footprints,
  ArrowUp,
  Shield,
  Hand,
};

function getAttrLabel(categoryKey: string, attrKey: string): string {
  const cat = BUILD_CATEGORIES.find((c) => c.key === categoryKey);
  if (!cat) return attrKey;
  const attr = cat.attributes.find((a) => a.key === attrKey);
  return attr?.label ?? attrKey;
}

interface CategoryDetail {
  key: string;
  name: string;
  icon: string;
  points: number;
  maxPoints: number;
  nextCost: number;
  canAdd: boolean;
  canRemove: boolean;
  attributes: {
    key: string;
    baseRating: number;
    boostBonus: number;
    cap: number;
    currentRating: number;
  }[];
}

interface CategoryCardProps {
  category: CategoryDetail;
  boostMap: Record<string, number>;
  coachBonusMap: Record<string, number>;
  styleBonusMap: Record<string, number>;
  boosterBonusMap: Record<string, number>;
  boosterColorMap: Record<string, string>;
  shineBonusMap: Record<string, number>;
  onAdd: () => void;
  onRemove: () => void;
}

const CategoryCard: React.FC<CategoryCardProps> = ({
  category,
  boostMap,
  coachBonusMap,
  styleBonusMap,
  boosterBonusMap,
  boosterColorMap,
  shineBonusMap,
  onAdd,
  onRemove,
}) => {
  const Icon = ICON_MAP[category.icon] || Triangle;

  const renderBoosterBadge = (attrKey: string): React.ReactNode => {
    const boosterBonus = boosterBonusMap[attrKey] ?? 0;
    if (boosterBonus <= 0) return null;
    const colorKey = boosterColorMap[attrKey] ?? '紫';
    const color = BOOSTER_COLOR_MAP[colorKey] ?? BOOSTER_COLOR_MAP['紫'];
    return (
      <span
        className={`inline-flex items-center gap-0.5 text-xs font-bold ${color.text} ${color.bg} border ${color.border} px-1.5 py-0.5 rounded-md ml-1 flex-shrink-0`}
        title={`增能加成 +${boosterBonus}`}
      >
        +{boosterBonus}
      </span>
    );
  };

  const renderShineBadge = (attrKey: string): React.ReactNode => {
    const shineBonus = shineBonusMap[attrKey] ?? 0;
    if (shineBonus <= 0) return null;
    return (
      <span
        className="inline-flex items-center gap-0.5 text-xs font-bold text-yellow-300 bg-yellow-500/15 border border-yellow-500/40 px-1.5 py-0.5 rounded-md ml-1 flex-shrink-0"
        title={`闪耀加成 +${shineBonus}`}
      >
        +{shineBonus}
      </span>
    );
  };

  const attrChips = category.attributes.map((attr) => {
    const key = attr.key;
    const base = attr.baseRating;
    const points = attr.currentRating - attr.baseRating;
    const shineBonus = shineBonusMap[key] ?? 0;
    const boostBonus = boostMap[key] ?? 0;
    const coachBonus = coachBonusMap[key] ?? 0;
    const styleBonus = styleBonusMap[key] ?? 0;
    const boosterBonus = boosterBonusMap[key] ?? 0;
    const finalValue = base + points + shineBonus + boostBonus + coachBonus + styleBonus + boosterBonus;
    const buildBonus = Math.round(finalValue - base - boosterBonus - shineBonus);
    return (
      <div
        key={key}
        className="flex items-center gap-1 px-1.5 md:px-2 py-1 rounded-xl bg-white/5 border border-white/5 shrink-0"
        title={getAttrLabel(category.key, key)}
      >
        <span className="text-xs md:text-sm font-semibold text-gray-300 truncate max-w-[60px] md:max-w-[80px]">
          {getAttrLabel(category.key, key)}
        </span>
        {buildBonus > 0 && (
          <span className="text-xs md:text-sm font-bold text-emerald-400" title="加点/教练/战术熟练度加成">+{buildBonus}</span>
        )}
        {renderShineBadge(key)}
        {renderBoosterBadge(key)}
        <span
          className={`text-base md:text-lg font-extrabold px-2 md:px-2.5 py-0.5 md:py-1 rounded-xl ${getAttrColorClass(finalValue)}`}
        >
          {Math.round(finalValue)}
        </span>
      </div>
    );
  });

  const hasBoost = category.attributes.some((a) => (boostMap[a.key] ?? 0) > 0);
  const hasCoachBonus = category.attributes.some((a) => (coachBonusMap[a.key] ?? 0) > 0);
  const hasBooster = category.attributes.some((a) => (boosterBonusMap[a.key] ?? 0) > 0);
  const hasShine = category.attributes.some((a) => (shineBonusMap[a.key] ?? 0) > 0);

  return (
    <div className="bg-[#141838] rounded-xl border border-white/10 overflow-hidden shadow-sm">
      <div className="flex items-center justify-between px-2 md:px-3 py-1.5 md:py-2 border-b border-white/10">
        <div className="flex items-center gap-1.5 md:gap-2">
          <div className="w-6 h-6 md:w-7 md:h-7 rounded-lg bg-cyan-400/15 flex items-center justify-center">
            <Icon className="w-3.5 h-3.5 md:w-4 md:h-4 text-cyan-400" />
          </div>
          <span className="text-sm md:text-base font-bold text-white">{category.name}</span>
          <span className="text-[10px] md:text-xs font-bold text-cyan-300 bg-cyan-400/15 px-1.5 md:px-2 py-0.5 rounded-full">
            {category.points}
          </span>
          {hasBoost && (
            <Sparkles className="w-3.5 h-3.5 text-amber-500" aria-label="含增能加成" />
          )}
          {hasCoachBonus && (
            <Award className="w-3.5 h-3.5 text-orange-500" aria-label="含教练加成" />
          )}
          {hasBooster && (
            <svg className="w-3.5 h-3.5 text-purple-400" viewBox="0 0 24 24" fill="currentColor" aria-label="含增能加成">
              <polygon points="12,2 22,7 22,17 12,22 2,17 2,7" />
            </svg>
          )}
          {hasShine && (
            <Sparkles className="w-3.5 h-3.5 text-yellow-400" aria-label="含闪耀加成" />
          )}
        </div>
        <div className="flex items-center gap-1">
          <button
            onClick={onRemove}
            disabled={!category.canRemove}
            className={`w-7 h-7 md:w-8 md:h-8 rounded-lg flex items-center justify-center transition-all ${
              category.canRemove
                ? 'bg-white/10 hover:bg-white/20 text-gray-300'
                : 'bg-white/5 text-gray-600 cursor-not-allowed'
            }`}
            title={category.canRemove ? '减少1点' : '无法减少'}
          >
            <Minus className="w-3.5 h-3.5 md:w-4 md:h-4" />
          </button>
          <button
            onClick={onAdd}
            disabled={!category.canAdd}
            className={`w-7 h-7 md:w-8 md:h-8 rounded-lg flex items-center justify-center transition-all ${
              category.canAdd
                ? 'bg-primary text-primary-foreground shadow-md hover:opacity-90'
                : 'bg-white/5 text-gray-600 cursor-not-allowed'
            }`}
            title={category.canAdd ? `加1点（消耗 ${category.nextCost} 能力点）` : '已达上限或点数不足'}
          >
            <Plus className="w-3.5 h-3.5 md:w-4 md:h-4" />
          </button>
        </div>
      </div>
      <div className="px-1.5 md:px-2 py-1.5 md:py-2 flex items-center gap-1.5 md:gap-2 flex-wrap overflow-hidden">{attrChips}</div>
    </div>
  );
};

interface CompareBuildDialogProps {
  open: boolean;
  player: Player | null;
  initialAllocations: Record<string, number>;
  initialLevel: number;
  coach: Coach | null;
  booster2: Booster | null;
  shineLevel: number;
  maxLevel: number;
  onClose: () => void;
  onConfirm: (data: { allocations: Record<string, number>; level: number }) => void;
}

function getStyleBonusThresholdsLocal(styleValue: number): {
  plus3: number;
  plus2: number;
  plus1: number;
  plus3OverCap: boolean;
} {
  // 官方规则（2026-09 校准）：裸值 ≥ 173−S → +3；裸值 ≥ 145−S → +2；其余 → +1（最低 +1）
  const plus3 = 173 - styleValue;
  const plus2 = 145 - styleValue;
  return { plus3, plus2, plus1: plus2, plus3OverCap: plus3 > 99 };
}

function getCoachTopStyleLocal(coach: Coach): { label: string; value: number; key: string } {
  const sp = coach.styleProficiency as unknown as Record<string, number> | undefined;
  if (!sp) return { key: 'possession', label: '控球游戏', value: 0 };
  const STYLE_KEYS: { key: string; label: string }[] = [
    { key: 'possession', label: '控球游戏' },
    { key: 'longBallCounter', label: '长传反击' },
    { key: 'quickCounter', label: '快速反攻' },
    { key: 'longPass', label: '长传球' },
    { key: 'wide', label: '外侧' },
    { key: 'outWide', label: '压上进攻' },
  ];
  let topKey = 'possession';
  let topValue = -1;
  for (const { key, label } of STYLE_KEYS) {
    const v = sp[key] ?? 0;
    if (v > topValue) {
      topValue = v;
      topKey = key;
    }
  }
  const topLabel = STYLE_KEYS.find((s) => s.key === topKey)?.label ?? topKey;
  return { key: topKey, label: topLabel, value: topValue };
}

const CompareBuildDialog: React.FC<CompareBuildDialogProps> = ({
  open,
  player,
  initialAllocations,
  initialLevel,
  coach,
  booster2,
  shineLevel,
  maxLevel,
  onClose,
  onConfirm,
}) => {
  const [allocations, setAllocations] = useState<Record<string, number>>(initialAllocations);
  const [level, setLevel] = useState<number>(initialLevel);

  useEffect(() => {
    if (open) {
      setAllocations(initialAllocations);
      setLevel(initialLevel);
    }
  }, [open, initialAllocations, initialLevel]);

  const baseStats = useMemo(() => {
    if (!player) return {};
    return buildBaseStatsMap(player);
  }, [player]);

  const boostMap = useMemo(() => {
    if (!player) return {};
    return getBoostMap(player);
  }, [player]);

  const coachBonusMap = useMemo(
    () => buildCoachBonusMap(coach),
    [coach],
  );

  const coachTopStyle = useMemo(() => {
    if (!coach) return null;
    return getCoachTopStyleLocal(coach);
  }, [coach]);

  const styleThresholds = useMemo(() => {
    if (!coachTopStyle) return null;
    return getStyleBonusThresholdsLocal(coachTopStyle.value);
  }, [coachTopStyle]);

  const innateBoosterLocal = useMemo((): Booster | null => {
    if (!player?.innateBooster) return null;
    try {
      return apiBoosterToLocal(player.innateBooster, player.playerType);
    } catch {
      return null;
    }
  }, [player]);

  const booster2Local = useMemo((): Booster | null => booster2 ?? null, [booster2]);

  const boosterBonusMap = useMemo((): Record<string, number> => {
    const map: Record<string, number> = {};
    const add = (b: Booster | null) => {
      if (!b) return;
      const m = getBoosterAttrMap(b);
      for (const [k, v] of Object.entries(m)) map[k] = (map[k] ?? 0) + v;
    };
    add(innateBoosterLocal);
    add(booster2Local);
    return map;
  }, [innateBoosterLocal, booster2Local]);

  const boosterColorMap = useMemo((): Record<string, string> => {
    return buildBoosterColorMap(
      [innateBoosterLocal, booster2Local].filter((b): b is Booster => b !== null),
    );
  }, [innateBoosterLocal, booster2Local]);

  const positionKey = useMemo(() => {
    if (!player) return 'CF';
    return getPositionKeyByLabel(player.position);
  }, [player]);

  const shineBonusMap = useMemo(() => {
    if (!shineLevel) return {};
    return getShineBonusMap(positionKey, shineLevel);
  }, [positionKey, shineLevel]);

  const styleBonusMap = useMemo(() => {
    return buildStyleBonusMap(baseStats, allocations, boostMap, coachBonusMap, coach, boosterBonusMap, shineBonusMap);
  }, [baseStats, allocations, boostMap, coachBonusMap, coach, boosterBonusMap, shineBonusMap]);

  const availablePoints = useMemo(
    () => calcAvailablePoints(level, allocations),
    [level, allocations],
  );

  const totalSpent = useMemo(
    () => Object.values(allocations).reduce((s, v) => s + v, 0),
    [allocations],
  );

  const totalStatsSum = useMemo(() => {
    return getTotalStatsSum(allocations, baseStats, boostMap, coachBonusMap, styleBonusMap, boosterBonusMap, shineBonusMap);
  }, [allocations, baseStats, boostMap, coachBonusMap, styleBonusMap, boosterBonusMap, shineBonusMap]);

  const computeCategoryDetails = useCallback(
    (allocs: Record<string, number>, available: number): CategoryDetail[] => {
      return BUILD_CATEGORIES.map((cat) => {
        const points = allocs[cat.key] ?? 0;
        const attributes = cat.attributes.map((attr) => {
          const base = baseStats[attr.key] ?? 0;
          const boost = boostMap[attr.key] ?? 0;
          const cBonus = coachBonusMap[attr.key] ?? 0;
          const cap = 99 + boost + cBonus;
          const current = Math.min(base + points, cap);
          return { key: attr.key, baseRating: base, boostBonus: boost, cap, currentRating: current };
        });
        const nextCost = getCostForNextPoint(points);
        const hasRoom = attributes.some((a) => a.baseRating + points < a.cap);
        const canAdd =
          points < MAX_POINTS_PER_CATEGORY &&
          hasRoom &&
          nextCost !== Infinity &&
          available >= nextCost;
        return {
          key: cat.key,
          name: cat.name,
          icon: cat.icon,
          points,
          maxPoints: MAX_POINTS_PER_CATEGORY,
          nextCost: canAdd ? nextCost : 0,
          refundCost: points > 0 ? getRefundForCurrentPoints(points) : 0,
          canAdd,
          canRemove: points > 0,
          attributes,
        };
      });
    },
    [baseStats, boostMap, coachBonusMap],
  );

  const categoryDetails = useMemo(
    () => computeCategoryDetails(allocations, availablePoints),
    [allocations, availablePoints, computeCategoryDetails],
  );

  const handleAdd = useCallback(
    (catKey: string) => {
      setAllocations((prev) => {
        const points = prev[catKey] ?? 0;
        const newAllocs = { ...prev, [catKey]: points + 1 };
        const newAvail = calcAvailablePoints(level, newAllocs);
        const catConfig = BUILD_CATEGORIES.find((c) => c.key === catKey);
        if (!catConfig) return prev;
        const hasRoom = catConfig.attributes.some((attr) => {
          const base = baseStats[attr.key] ?? 0;
          const cBonus = coachBonusMap[attr.key] ?? 0;
          const boost = boostMap[attr.key] ?? 0;
          return base + (points + 1) < 99 + boost + cBonus;
        });
        const cost = getCostForNextPoint(points);
        if (points + 1 > MAX_POINTS_PER_CATEGORY) return prev;
        if (!hasRoom) return prev;
        if (calcAvailablePoints(level, prev) < cost) return prev;
        return newAllocs;
      });
    },
    [level, baseStats, coachBonusMap, boostMap],
  );

  const handleRemove = useCallback(
    (catKey: string) => {
      setAllocations((prev) => {
        const points = prev[catKey] ?? 0;
        if (points <= 0) return prev;
        return { ...prev, [catKey]: points - 1 };
      });
    },
    [],
  );

  const handleReset = useCallback(() => {
    const reset: Record<string, number> = {};
    for (const cat of BUILD_CATEGORIES) {
      reset[cat.key] = 0;
    }
    setAllocations(reset);
  }, []);

  const handleLevelChange = useCallback(
    (newLevelStr: string) => {
      const newLevel = Number(newLevelStr);
      if (isNaN(newLevel)) return;
      const newAllocs: Record<string, number> = { ...allocations };
      let available = (newLevel - 1) * 2;
      const catKeys = Object.keys(newAllocs);
      for (const key of catKeys) {
        while (newAllocs[key] > 0) {
          const cost = getCostForNextPoint(newAllocs[key] - 1);
          if (available >= cost) {
            available -= cost;
            break;
          }
          newAllocs[key] -= 1;
        }
      }
      setLevel(newLevel);
      setAllocations(newAllocs);
    },
    [allocations],
  );

  const handleAutoBuild = useCallback(() => {
    if (!player) return;
    const result = autoBuildForPosition(
      positionKey,
      baseStats,
      boostMap,
      coachBonusMap,
      player.height,
      level,
      styleThresholds,
      boosterBonusMap,
      shineBonusMap,
    );
    setAllocations(result.allocations);
  }, [player, positionKey, baseStats, boostMap, coachBonusMap, level, styleThresholds, boosterBonusMap, shineBonusMap]);

  const handleConfirm = useCallback(() => {
    onConfirm({ allocations, level });
  }, [allocations, level, onConfirm]);

  if (!player) return null;

  const fieldCategories = categoryDetails.filter((c) => !c.key.startsWith('gk'));
  const gkCategories = categoryDetails.filter((c) => c.key.startsWith('gk'));
  const isGK = positionKey === 'GK';
  const displayCategories = isGK ? gkCategories : fieldCategories;

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent showCloseButton={false} className="bg-[#0f1435] border-white/10 text-white w-[95vw] max-w-[720px] flex flex-col p-0" style={{ maxHeight: '85vh' }}>
        <DialogHeader className="px-3 md:px-4 py-2 md:py-3 border-b border-white/10 flex flex-row items-center justify-between">
          <DialogTitle className="text-base md:text-lg font-bold">加点配置 - {player.nameZh}</DialogTitle>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-white transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto">
          {/* 控制区域 */}
          <div className="bg-[#1a1f45]/60 px-3 md:px-4 py-2 md:py-3 border-b border-white/10">
            {/* 教练 + 增能 加成展示 */}
            {(coach || booster2) && (
              <div className="mb-3 space-y-2">
                {coach && (
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="text-sm text-gray-500 shrink-0">教练加成：</span>
                    {coach.managerBonus && coach.managerBonus.length > 0 && (
                      <>
                        <span className="text-sm text-gray-400">主教练</span>
                        {coach.managerBonus.slice(0, 2).map((b, idx) => (
                          <span
                            key={idx}
                            className="inline-flex items-center gap-1 text-sm font-bold text-orange-300 bg-orange-500/15 border border-orange-500/40 px-2 py-0.5 rounded-full"
                          >
                            <Award className="w-4 h-4" />
                            {b.label || b.stat} +{b.value}
                          </span>
                        ))}
                        {coachTopStyle && styleThresholds && (
                          <span className="text-sm text-gray-500">|</span>
                        )}
                      </>
                    )}
                    {coachTopStyle && styleThresholds && (
                      <>
                        <span className="text-sm text-gray-400">风格</span>
                        <span className="inline-flex items-center gap-1 text-sm font-bold text-emerald-300 bg-emerald-500/15 border border-emerald-500/40 px-2 py-0.5 rounded-full">
                          {coachTopStyle.label} {coachTopStyle.value}
                        </span>
                        <span className="text-xs text-gray-500">
                          +3: {styleThresholds.plus3OverCap ? '>99' : `≥${styleThresholds.plus3}`} · +2: ≥{styleThresholds.plus2} · +1: ≥{styleThresholds.plus1}
                        </span>
                      </>
                    )}
                  </div>
                )}
                {booster2 && (
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="text-sm text-gray-500 shrink-0">增能加成：</span>
                    <span className="inline-flex items-center gap-1 text-sm font-bold text-purple-300 bg-purple-500/15 border border-purple-500/40 px-2 py-1 rounded-full">
                      {booster2.name}
                    </span>
                    <span className={`text-xs px-1.5 py-0.5 rounded ${BOOSTER_COLOR_MAP[booster2.color].bg} ${BOOSTER_COLOR_MAP[booster2.color].text} ${BOOSTER_COLOR_MAP[booster2.color].border} border`}>
                      {booster2.type}
                    </span>
                    {booster2.bonusScope === '全部' ? (
                      <span className="text-sm text-purple-300 font-bold">
                        全部属性{booster2.bonusLevel}
                      </span>
                    ) : (
                      <span className="text-sm text-purple-300 font-bold">
                        {booster2.abilities.join('、')} {booster2.bonusLevel}
                      </span>
                    )}
                  </div>
                )}
              </div>
            )}

            {/* 信息行：移动端上下两行，桌面端一行 */}
            <div className="flex flex-col gap-2 md:flex-row md:items-center md:gap-3 md:flex-nowrap">
              {/* 第一行：数据 */}
              <div className="flex flex-row items-center gap-2 md:gap-3 flex-nowrap overflow-x-auto">
                <div className="text-center flex-shrink-0">
                  <div className="text-xs text-gray-500 mb-0.5">可用点数</div>
                  <div className="text-xl md:text-2xl font-black text-emerald-400 leading-none">{availablePoints}</div>
                </div>
                <div className="w-px h-8 md:h-10 bg-white/10 flex-shrink-0" />
                <div className="text-center flex-shrink-0">
                  <div className="text-xs text-gray-500 mb-0.5">已用点数</div>
                  <div className="text-xl md:text-2xl font-black text-cyan-400 leading-none">{totalSpent}</div>
                </div>
                <div className="w-px h-8 md:h-10 bg-white/10 flex-shrink-0" />
                <div className="text-center flex-shrink-0">
                  <div className="text-xs text-gray-500 mb-0.5">总能力值</div>
                  <div className="flex items-baseline gap-1 justify-center">
                    <span className="text-xl md:text-2xl font-black text-amber-300 leading-none">
                      {totalStatsSum}
                    </span>
                  </div>
                </div>
                <div className="w-px h-8 md:h-10 bg-white/10 flex-shrink-0" />

                {/* 等级选择 */}
                <div className="flex-shrink-0">
                  <div className="text-xs text-gray-500 mb-0.5">等级</div>
                  <Select value={String(level)} onValueChange={handleLevelChange}>
                    <SelectTrigger className="h-8 md:h-9 w-16 md:w-20 bg-[#141838] border-white/10 text-white text-xs md:text-sm">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent className="bg-[#141838] border-white/10 text-white max-h-60">
                      {Array.from({ length: maxLevel }, (_, i) => i + 1).map((lv) => (
                        <SelectItem key={lv} value={String(lv)} className="text-white">
                          {lv}级
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              {/* 第二行：按钮（移动端）/ 同一行（桌面端） */}
              <div className="flex flex-row items-center gap-2 flex-shrink-0 md:ml-auto">
                <button
                  onClick={handleAutoBuild}
                  className="flex items-center gap-1.5 px-2 md:px-3 h-8 md:h-9 rounded-md text-xs md:text-sm font-bold bg-neon-gradient text-white shadow-md transition-all hover:opacity-90 flex-shrink-0"
                >
                  <Zap className="w-3.5 h-3.5 md:w-4 md:h-4" />
                  <span>自动加点</span>
                </button>

                <button
                  onClick={handleReset}
                  disabled={totalSpent === 0}
                  className={`flex items-center gap-1.5 px-2 md:px-3 h-8 md:h-9 rounded-md text-xs md:text-sm font-medium transition-all flex-shrink-0 ${
                    totalSpent > 0
                      ? 'bg-white/10 hover:bg-white/20 text-gray-300'
                      : 'bg-white/5 text-gray-600 cursor-not-allowed'
                  }`}
                >
                  <RotateCcw className="w-3.5 h-3.5 md:w-4 md:h-4" />
                  <span>重置</span>
                </button>
              </div>
            </div>
          </div>

          {/* 10大项分类卡片 */}
          <div className="p-2 md:p-3 flex flex-col gap-2">
            {/* 射门 + 下肢力量 */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {displayCategories
                .filter((c) => c.key === 'shooting' || c.key === 'lowerBody')
                .sort((a, b) => ['shooting', 'lowerBody'].indexOf(a.key) - ['shooting', 'lowerBody'].indexOf(b.key))
                .map((cat) => (
                  <CategoryCard
                    key={cat.key}
                    category={cat}
                    boostMap={boostMap}
                    coachBonusMap={coachBonusMap}
                    styleBonusMap={styleBonusMap}
                    boosterBonusMap={boosterBonusMap}
                    boosterColorMap={boosterColorMap}
                    shineBonusMap={shineBonusMap}
                    onAdd={() => handleAdd(cat.key)}
                    onRemove={() => handleRemove(cat.key)}
                  />
                ))}
            </div>
            {/* 传球 + 灵巧 */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {displayCategories
                .filter((c) => c.key === 'passing' || c.key === 'dexterity')
                .sort((a, b) => ['passing', 'dexterity'].indexOf(a.key) - ['passing', 'dexterity'].indexOf(b.key))
                .map((cat) => (
                  <CategoryCard
                    key={cat.key}
                    category={cat}
                    boostMap={boostMap}
                    coachBonusMap={coachBonusMap}
                    styleBonusMap={styleBonusMap}
                    boosterBonusMap={boosterBonusMap}
                    boosterColorMap={boosterColorMap}
                    shineBonusMap={shineBonusMap}
                    onAdd={() => handleAdd(cat.key)}
                    onRemove={() => handleRemove(cat.key)}
                  />
                ))}
            </div>
            {/* 盘球 + 空中力量 */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {displayCategories
                .filter((c) => c.key === 'dribbling' || c.key === 'aerial')
                .sort((a, b) => ['dribbling', 'aerial'].indexOf(a.key) - ['dribbling', 'aerial'].indexOf(b.key))
                .map((cat) => (
                  <CategoryCard
                    key={cat.key}
                    category={cat}
                    boostMap={boostMap}
                    coachBonusMap={coachBonusMap}
                    styleBonusMap={styleBonusMap}
                    boosterBonusMap={boosterBonusMap}
                    boosterColorMap={boosterColorMap}
                    shineBonusMap={shineBonusMap}
                    onAdd={() => handleAdd(cat.key)}
                    onRemove={() => handleRemove(cat.key)}
                  />
                ))}
            </div>
            {/* 防守 */}
            <div>
              {displayCategories
                .filter((c) => c.key === 'defending')
                .map((cat) => (
                  <CategoryCard
                    key={cat.key}
                    category={cat}
                    boostMap={boostMap}
                    coachBonusMap={coachBonusMap}
                    styleBonusMap={styleBonusMap}
                    boosterBonusMap={boosterBonusMap}
                    boosterColorMap={boosterColorMap}
                    shineBonusMap={shineBonusMap}
                    onAdd={() => handleAdd(cat.key)}
                    onRemove={() => handleRemove(cat.key)}
                  />
                ))}
            </div>
            {/* 门将（仅GK时显示） */}
            {isGK && (
              <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
                {gkCategories
                  .sort((a, b) => ['gk1', 'gk2', 'gk3'].indexOf(a.key) - ['gk1', 'gk2', 'gk3'].indexOf(b.key))
                  .map((cat) => (
                    <CategoryCard
                      key={cat.key}
                      category={cat}
                      boostMap={boostMap}
                      coachBonusMap={coachBonusMap}
                      styleBonusMap={styleBonusMap}
                      boosterBonusMap={boosterBonusMap}
                      boosterColorMap={boosterColorMap}
                      shineBonusMap={shineBonusMap}
                      onAdd={() => handleAdd(cat.key)}
                      onRemove={() => handleRemove(cat.key)}
                    />
                  ))}
              </div>
            )}
          </div>

          {/* 说明 */}
          <div className="px-3 py-2 bg-[#1a1f45]/60 border-t border-white/10">
            <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-gray-500">
              <span>• 球员满级后共有 (满级等级-1)×2 个能力点</span>
              <span>• 大项每加 1 点，下属所有属性同步 +1</span>
              <span>• 0-4 点每点耗 1，5-8 点耗 2，9-13 点耗 3，14-16 点耗 4</span>
              <span>
                • <span className="text-amber-400 font-bold">金色+N</span> 为闪耀加成
              </span>
              <span>
                • <Award className="w-3 h-3 inline text-orange-500" /> 标记为教练加成
              </span>
              <span>• 绿色数字为教练风格加成（+1~+3）</span>
            </div>
          </div>
        </div>

        {/* 底部按钮 */}
        <div className="flex gap-2 p-3 border-t border-white/10">
          <button
            onClick={onClose}
            className="flex-1 py-2.5 rounded-lg bg-white/10 text-white text-sm font-medium hover:bg-white/15 transition-colors"
          >
            取消
          </button>
          <button
            onClick={handleConfirm}
            className="flex-1 py-2.5 rounded-lg bg-cyan-500 text-white text-sm font-medium hover:bg-cyan-400 transition-colors"
          >
            确定
          </button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default CompareBuildDialog;
