const PLAYER_CARD_URL_TEMPLATE = 'https://efootballpsbete-1488358463.cos.ap-shanghai.myqcloud.com/EF20270916/EF2027/player_cards/{id}_l.png';
const PLAYER_CARD_SMALL_TEMPLATE = 'https://efootballpsbete-1488358463.cos.ap-shanghai.myqcloud.com/EF20270916/EF2027/player_cards_small/{id}_s.png';

export function resolvePlayerCardImage(
  imageUrl: string | null | undefined,
  playerId: string | null | undefined,
): string {
  if (imageUrl && imageUrl.trim() !== '') return imageUrl;
  if (playerId && playerId.trim() !== '') {
    return PLAYER_CARD_URL_TEMPLATE.replace('{id}', playerId.trim());
  }
  return '';
}

export function resolveSmallPlayerCardImage(
  playerId: string | null | undefined,
): string {
  if (!playerId || playerId.trim() === '') return '';
  return PLAYER_CARD_SMALL_TEMPLATE.replace('{id}', playerId.trim());
}
