import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
} from 'react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import * as authApi from '@client/src/api/auth';
import { updateMyAvatar, updateMyProfile } from '@client/src/api/users';
import type { UserInfo, AuthResponse } from '@shared/api.interface';

interface AuthContextType {
  user: UserInfo | null;
  loading: boolean;
  login: (username: string, password: string) => Promise<AuthResponse>;
  register: (
    username: string,
    password: string,
    nickname?: string,
    agreeTerms?: boolean,
    agreePrivacy?: boolean,
  ) => Promise<AuthResponse>;
  logout: () => void;
  deactivate: (password: string) => Promise<void>;
  fetchMe: () => Promise<UserInfo | null>;
  /** 直接写入当前登录用户（用于微信等已在响应里带 user 的登录，避免再依赖一次 /me） */
  setAuthUser: (u: UserInfo) => void;
  updateAvatar: (avatarUrl: string) => Promise<void>;
  updateProfile: (data: { nickname?: string; bio?: string }) => Promise<void>;
  getAuthHeaders: () => Record<string, string>;
}

export const AuthContext = createContext<AuthContextType | null>(null);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const [user, setUser] = useState<UserInfo | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    authApi
      .getCurrentUser()
      .then((u) => setUser(u))
      .catch(() => setUser(null))
      .finally(() => setLoading(false));
  }, []);

  const fetchMe = useCallback(async (): Promise<UserInfo | null> => {
    const u = await authApi.fetchMe();
    if (u) setUser(u);
    return u;
  }, []);

  const setAuthUser = useCallback((u: UserInfo) => {
    setUser(u);
  }, []);

  const login = useCallback(
    async (username: string, password: string) => {
      const res = await authApi.login({ username, password });
      authApi.setToken(res.token);
      try {
        const fullUser = await authApi.fetchMe();
        setUser(fullUser || res.user);
      } catch {
        setUser(res.user);
      }
      return res;
    },
    [],
  );

  const register = useCallback(
    async (username: string, password: string, nickname?: string, agreeTerms = true, agreePrivacy = true) => {
      const res = await authApi.register({ username, password, nickname, agreeTerms, agreePrivacy });
      authApi.setToken(res.token);
      try {
        const fullUser = await authApi.fetchMe();
        setUser(fullUser || res.user);
      } catch {
        setUser(res.user);
      }
      return res;
    },
    [],
  );

  const logout = useCallback(() => {
    authApi.logout();
    setUser(null);
  }, []);

  const deactivate = useCallback(async (password: string): Promise<void> => {
    await authApi.deactivate(password);
    setUser(null);
  }, []);

  const getAuthHeaders = useCallback((): Record<string, string> => {
    const token = authApi.getToken();
    return token ? { Authorization: `Bearer ${token}` } : {};
  }, []);

  const updateAvatar = useCallback(async (avatarUrl: string): Promise<void> => {
    const result = await updateMyAvatar(avatarUrl);
    if (result.success) {
      setUser((prev) => (prev ? { ...prev, avatarUrl: result.avatarUrl } : prev));
    }
  }, []);

  const updateProfile = useCallback(
    async (data: { nickname?: string; bio?: string }): Promise<void> => {
      const result = await updateMyProfile(data);
      if (result.success) {
        setUser((prev) =>
          prev
            ? { ...prev, nickname: result.nickname || prev.nickname, bio: result.bio }
            : prev,
        );
      }
    },
    [],
  );

  return (
    <AuthContext.Provider
      value={{
        user,
        loading,
        login,
        register,
        logout,
        deactivate,
        fetchMe,
        setAuthUser,
        updateAvatar,
        updateProfile,
        getAuthHeaders,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export function useAuth(): AuthContextType {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}
