import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { zh, en } from './locales';
import { trTerm, setTermLang } from './terms';

export type Lang = 'zh' | 'en';
const STORAGE_KEY = 'pts.lang';

// 英文化改版开关：仅副页构建（VITE_ENABLE_I18N=1）开启；正式页不设 → 锁定中文、无切换入口。
// 注意：与语言无关的功能修复（如第二增能保存）不受此开关影响，正式/副页都会生效。
export const I18N_ENABLED: boolean =
  String((import.meta as any).env?.VITE_ENABLE_I18N ?? '') === '1' ||
  String((import.meta as any).env?.VITE_ENABLE_I18N ?? '').toLowerCase() === 'true';

function detectLang(): Lang {
  if (!I18N_ENABLED) return 'zh'; // 正式页：不读本地偏好、不按浏览器语言，固定中文
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === 'en' || saved === 'zh') return saved;
  } catch {
    /* ignore */
  }
  if (typeof navigator !== 'undefined' &&
      (navigator.language || '').toLowerCase().startsWith('en')) {
    return 'en';
  }
  return 'zh';
}

// 把模板里的 {name} 占位替换为参数值；未提供的占位保留原样
function interpolate(s: string, params?: Record<string, string | number>): string {
  if (!params) return s;
  return s.replace(/\{(\w+)\}/g, (m, k) =>
    params[k] === undefined || params[k] === null ? m : String(params[k]),
  );
}

interface I18nValue {
  lang: Lang;
  setLang: (l: Lang) => void;
  toggleLang: () => void;
  t: (key: string, params?: Record<string, string | number>) => string;
}

const I18nContext = createContext<I18nValue | null>(null);

export const I18nProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [lang, setLangState] = useState<Lang>(detectLang);
  // 同步数据术语语言：正式页 lang=zh → trTerm 返回中文；副页 en → 英文
  useEffect(() => { setTermLang(lang); }, [lang]);

  const setLang = useCallback((l: Lang) => {
    if (!I18N_ENABLED) return; // 正式页锁定中文，忽略任何切换
    setLangState(l);
    try { localStorage.setItem(STORAGE_KEY, l); } catch { /* ignore */ }
  }, []);

  const toggleLang = useCallback(
    () => setLang(lang === 'zh' ? 'en' : 'zh'),
    [lang, setLang],
  );

  const t = useCallback(
    (key: string, params?: Record<string, string | number>) => {
      // 英文态：UI 字典 → 中文字典 → 数据术语表(trTerm) → 原文
      const base = lang === 'en' ? (en[key] ?? zh[key] ?? trTerm(key) ?? key) : (zh[key] ?? key);
      return interpolate(base, params);
    },
    [lang],
  );

  const value = useMemo(
    () => ({ lang, setLang, toggleLang, t }),
    [lang, setLang, toggleLang, t],
  );

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
};

export function useI18n(): I18nValue {
  const ctx = useContext(I18nContext);
  // 未被 Provider 包裹时的安全兜底（保持中文）
  if (!ctx) {
    return { lang: 'zh', setLang: () => {}, toggleLang: () => {}, t: (k) => zh[k] ?? k };
  }
  return ctx;
}
