import React, { useState, useMemo, useEffect } from 'react';
import { Search, X } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@client/src/components/ui/dialog';
import type { Coach } from '@shared/api.interface';
import { useI18n } from '@client/src/i18n/I18nProvider';

interface CompareCoachDialogProps {
  open: boolean;
  coachList: Coach[];
  selectedCoach: Coach | null;
  onClose: () => void;
  onConfirm: (coach: Coach | null) => void;
}

const CompareCoachDialog: React.FC<CompareCoachDialogProps> = ({
  open,
  coachList,
  selectedCoach,
  onClose,
  onConfirm,
}) => {
  const { t } = useI18n();
  const [search, setSearch] = useState('');
  const [gradeFilter, setGradeFilter] = useState<string>('全部');
  const [tempSelected, setTempSelected] = useState<string | null>(null);

  useEffect(() => {
    if (open) {
      setTempSelected(selectedCoach?.id ?? null);
      setSearch('');
      setGradeFilter('全部');
    }
  }, [open, selectedCoach]);

  const gradeOptions = useMemo(() => {
    const grades = new Set<string>();
    for (const c of coachList) {
      if (c.grade) grades.add(c.grade);
    }
    return ['全部', ...Array.from(grades).sort()];
  }, [coachList]);

  const filtered = useMemo(() => {
    return coachList.filter((c) => {
      if (gradeFilter !== '全部' && c.grade !== gradeFilter) return false;
      if (search) {
        const s = search.toLowerCase();
        return (
          c.nameZh?.toLowerCase().includes(s) ||
          c.nameEn?.toLowerCase().includes(s)
        );
      }
      return true;
    });
  }, [coachList, search, gradeFilter]);

  const handleConfirm = () => {
    const coach = tempSelected
      ? coachList.find((c) => c.id === tempSelected) ?? null
      : null;
    onConfirm(coach);
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent showCloseButton={false} className="bg-[#0f1435] border-white/10 text-white max-w-lg w-[92vw] max-h-[80vh] flex flex-col p-0">
        <DialogHeader className="px-4 py-3 border-b border-white/10 flex flex-row items-center justify-between">
          <DialogTitle className="text-base font-bold">{t('选择主教练')}</DialogTitle>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-white transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </DialogHeader>

        <div className="p-3 space-y-2 border-b border-white/10">
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder={t('搜索教练名称...')}
              className="w-full pl-8 pr-3 py-2 rounded-lg bg-white/5 border border-white/10 text-sm text-white placeholder-gray-500 focus:outline-none focus:border-cyan-400/50"
            />
          </div>
          <div className="flex gap-1 flex-wrap">
            {gradeOptions.map((g) => (
              <button
                key={g}
                onClick={() => setGradeFilter(g)}
                className={`px-2 py-1 rounded-md text-xs font-medium transition-colors ${
                  gradeFilter === g
                    ? 'bg-cyan-500/30 text-cyan-200 border border-cyan-400/50'
                    : 'bg-white/5 text-gray-400 border border-white/10 hover:text-white'
                }`}
              >
                {t(g)}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto">
          <button
            onClick={() => setTempSelected(null)}
            className={`w-full px-3 py-2.5 text-left border-b border-white/5 transition-colors ${
              tempSelected === null
                ? 'bg-cyan-500/10'
                : 'hover:bg-white/5'
            }`}
          >
            <span className="text-sm text-gray-300">{t('无教练')}</span>
          </button>
          {filtered.map((c) => (
            <button
              key={c.id}
              onClick={() => setTempSelected(c.id)}
              className={`w-full px-3 py-2.5 text-left border-b border-white/5 transition-colors ${
                tempSelected === c.id
                  ? 'bg-cyan-500/10'
                  : 'hover:bg-white/5'
              }`}
            >
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium text-white">
                  {c.nameZh}
                </span>
                <span
                  className={`text-[10px] px-1.5 py-0.5 rounded font-bold ${
                    c.grade === 'S+'
                      ? 'bg-amber-500/30 text-amber-200'
                      : c.grade === 'S'
                      ? 'bg-purple-500/30 text-purple-200'
                      : c.grade === 'A+'
                      ? 'bg-cyan-500/30 text-cyan-200'
                      : c.grade === 'A'
                      ? 'bg-blue-500/30 text-blue-200'
                      : 'bg-white/10 text-gray-300'
                  }`}
                >
                  {c.grade}
                </span>
              </div>
              {c.managerBonus && Array.isArray(c.managerBonus) && c.managerBonus.length > 0 && (
                <div className="flex flex-wrap gap-1 mt-1">
                  {(c.managerBonus as { stat?: string; value?: number }[]).slice(0, 3).map((b, i) => (
                    <span
                      key={i}
                      className="text-[10px] text-green-400 bg-green-500/10 px-1.5 py-0.5 rounded"
                    >
                      {t(b.stat)} +{b.value}
                    </span>
                  ))}
                </div>
              )}
            </button>
          ))}
          {filtered.length === 0 && (
            <div className="py-8 text-center text-sm text-gray-500">
              {t('未找到匹配的教练')}
            </div>
          )}
        </div>

        <div className="flex gap-2 p-3 border-t border-white/10">
          <button
            onClick={onClose}
            className="flex-1 py-2 rounded-lg bg-white/10 text-white text-sm font-medium hover:bg-white/15 transition-colors"
          >
            {t('取消')}
          </button>
          <button
            onClick={handleConfirm}
            className="flex-1 py-2 rounded-lg bg-cyan-500 text-white text-sm font-medium hover:bg-cyan-400 transition-colors"
          >
            {t('确定')}
          </button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default CompareCoachDialog;
