import { logger } from '@lark-apaas/client-toolkit/logger';
import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';

export interface TierItemSnapshot {
  playerId: string;
  nameZh: string;
  nameEn: string;
  position?: string;
  playerImageUrl?: string | null;
}

export interface TierRow {
  id: string;
  name: string;
  color: string;
}

export interface TierListPayload {
  name: string;
  tiers: TierRow[];
  items: Record<string, TierItemSnapshot[]>;
}

export interface TierListSummary {
  id: string;
  name: string;
  itemCount: number;
  updatedAt: string;
}

export interface TierListDetail extends TierListPayload {
  id: string;
  userId: string;
  createdAt: string;
  updatedAt: string;
}

export async function saveTierList(
  payload: TierListPayload,
  id: string | null,
  headers?: Record<string, string>,
): Promise<{ id: string; updatedAt: string }> {
  try {
    const res = await axiosForBackend.post<{ id: string; updatedAt: string }>(
      '/api/tier-lists',
      { id, ...payload },
      { headers },
    );
    return res.data;
  } catch (error) {
    logger.error('保存强度榜失败', error);
    throw error;
  }
}

export async function getMyTierLists(
  headers?: Record<string, string>,
): Promise<{ items: TierListSummary[] }> {
  try {
    const res = await axiosForBackend.get<{ items: TierListSummary[] }>(
      '/api/tier-lists/my',
      { headers },
    );
    return res.data;
  } catch (error) {
    logger.error('获取我的强度榜失败', error);
    throw error;
  }
}

export async function getTierList(id: string): Promise<TierListDetail> {
  try {
    const res = await axiosForBackend.get<TierListDetail>(
      `/api/tier-lists/${id}`,
    );
    return res.data;
  } catch (error) {
    logger.error(`获取强度榜失败: ${id}`, error);
    throw error;
  }
}

export async function deleteTierList(
  id: string,
  headers?: Record<string, string>,
): Promise<void> {
  try {
    await axiosForBackend.delete(`/api/tier-lists/${id}`, { headers });
  } catch (error) {
    logger.error(`删除强度榜失败: ${id}`, error);
    throw error;
  }
}
