// 资讯详情「分享」竖版长图：主视觉 banner（右下角宣传语）+ 标题（右侧横排小 LOGO）+ 摘要 + 截图（截图后即收尾）。
import type { NewsArticle } from '@shared/api.interface';
import { LOCAL_ASSETS } from '@client/src/utils/local-assets';
import { loadImage, viaProxy } from './lineup-image';

const BANNER_URL =
  'https://efootballpsbete-1488358463.cos.ap-shanghai.myqcloud.com/EF20270916/EF2027/banner/banner.png';

const PROMO_TEXT = '获得最新的全球资讯，赶紧访问PlayToStar.com！';

interface ShotGeom {
  img: HTMLImageElement;
  dw: number;
  dh: number;
}

// 切分：连续拉丁字母/数字/域名字符作为一个“词”整体，其余（中文、全角标点、空格）单字。
function tokenizeWrap(seg: string): string[] {
  const toks: string[] = [];
  let i = 0;
  const isWordStart = /[A-Za-z0-9]/;
  const isWordMore = /[A-Za-z0-9.'@&%#_+-]/;
  while (i < seg.length) {
    if (isWordStart.test(seg[i])) {
      let s = seg[i];
      i++;
      while (i < seg.length && isWordMore.test(seg[i])) {
        s += seg[i];
        i++;
      }
      toks.push(s);
    } else {
      toks.push(seg[i]);
      i++;
    }
  }
  return toks;
}

// 按最大宽度自动换行（中文逐字、拉丁词整体不拆；保留原文已有的 \n）
function wrapLines(
  ctx: CanvasRenderingContext2D,
  text: string,
  maxW: number,
): string[] {
  const out: string[] = [];
  String(text).split('\n').forEach((seg) => {
    let line = '';
    for (const tk of tokenizeWrap(seg)) {
      const test = line + tk;
      if (line && ctx.measureText(test).width > maxW) {
        out.push(line);
        line = tk; // 拉丁词整体落到下一行，不会从中间拆开
      } else {
        line = test;
      }
    }
    out.push(line);
  });
  return out;
}

export async function renderNewsShareCanvas(
  article: NewsArticle,
): Promise<HTMLCanvasElement> {
  const W = 1080;
  const m = 48;
  const cw = W - m * 2;

  const icon = await loadImage(LOCAL_ASSETS.icon);
  let banner: HTMLImageElement | null = null;
  try {
    banner = await loadImage(viaProxy(BANNER_URL));
  } catch {
    banner = null;
  }

  // 截图最多取 3 张，避免长图过长
  const shots: ShotGeom[] = [];
  const urls = article.imageUrls.slice(0, 3);
  for (const u of urls) {
    let im: HTMLImageElement | null = null;
    try {
      im = await loadImage(viaProxy(u));
    } catch {
      im = null;
    }
    if (!im) continue;
    let dw = cw;
    let dh = (im.height / im.width) * dw;
    // 宽度优先：截图一律接近内容全宽（与 APP 详情一致），高度按比例自适应、画布随之增高；
    // 仅对极端竖长图（会逼近手机 canvas 纹理上限）才用高阈值兜底，正常长文截图（比例≤5）不受影响、保持全宽。
    const maxH = urls.length > 1 ? 2600 : 5200;
    if (dh > maxH) {
      dh = maxH;
      dw = (im.width / im.height) * dh;
    }
    shots.push({ img: im, dw, dh });
  }

  // 离屏测量文字
  const measure = document.createElement('canvas').getContext('2d')!;
  measure.font = 'bold 54px system-ui, sans-serif';
  // 标题右侧预留横排小 LOGO 的宽度
  const logoReserve = 330;
  let titleLines = wrapLines(
    measure,
    article.title || article.summary.slice(0, 24),
    cw - logoReserve,
  );
  if (titleLines.length > 3) {
    titleLines = titleLines.slice(0, 3);
    titleLines[2] = titleLines[2].slice(0, -1) + '…';
  }
  measure.font = '42px system-ui, sans-serif';
  const summaryLines = wrapLines(measure, article.summary, cw);
  // banner 右下角宣传语（小字号、限定角块宽度，右对齐）
  measure.font = 'bold 28px system-ui, sans-serif';
  const promoLines = wrapLines(measure, PROMO_TEXT, 440);

  // 几何常量
  const bannerH = 400;
  const titleLH = 68;
  const sumLH = 66;
  const shotGap = 28;

  // ===== 先算总高（与下方绘制路径逐段对应；截图后即收尾，无底部宣传框/水印）=====
  let y = bannerH + 56;
  y += titleLines.length * titleLH + 8;
  y += 48; // 标题下分隔线区
  y += summaryLines.length * sumLH + 40;
  shots.forEach((s) => {
    y += s.dh + shotGap;
  });
  if (shots.length) y += 10;
  const H = Math.ceil(y + 48); // 底部仅留少量边距

  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d')!;

  // 背景
  const bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, '#0a0f2e');
  bg.addColorStop(0.4, '#0b1130');
  bg.addColorStop(1, '#0a0e26');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // banner cover 到顶部 bannerH
  if (banner) {
    const ir = banner.width / banner.height;
    let dw = W;
    let dh = W / ir;
    let dx = 0;
    let dy = (bannerH - dh) / 2;
    if (dh < bannerH) {
      dh = bannerH;
      dw = bannerH * ir;
      dx = (W - dw) / 2;
      dy = 0;
    }
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, 0, W, bannerH);
    ctx.clip();
    ctx.drawImage(banner, dx, dy, dw, dh);
    ctx.restore();
  }
  // banner 压暗 + 底部过渡到深色
  const bsh = ctx.createLinearGradient(0, 0, 0, bannerH);
  bsh.addColorStop(0, 'rgba(6,9,26,0.72)');
  bsh.addColorStop(0.55, 'rgba(6,9,26,0.35)');
  bsh.addColorStop(1, 'rgba(10,14,38,1)');
  ctx.fillStyle = bsh;
  ctx.fillRect(0, 0, W, bannerH);

  // 顶部品牌带
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.font = 'bold 30px system-ui, sans-serif';
  ctx.shadowColor = 'rgba(0,0,0,0.8)';
  ctx.shadowBlur = 8;
  ctx.shadowOffsetY = 2;
  ctx.fillStyle = '#ffffff';
  ctx.fillText('PlayToStar APP', m, 56);
  // 右侧“资讯”胶囊
  const tagText = '资讯';
  ctx.font = 'bold 26px system-ui, sans-serif';
  const tagW = ctx.measureText(tagText).width + 40;
  const tagX = W - m - tagW;
  const tagY = 56 - 22;
  const tagH = 44;
  ctx.fillStyle = 'rgba(34,211,238,0.22)';
  ctx.beginPath();
  ctx.roundRect(tagX, tagY, tagW, tagH, 22);
  ctx.fill();
  ctx.strokeStyle = 'rgba(34,211,238,0.6)';
  ctx.lineWidth = 1.5;
  ctx.stroke();
  ctx.fillStyle = '#cffafe';
  ctx.textAlign = 'center';
  ctx.fillText(tagText, tagX + tagW / 2, tagY + tagH / 2 + 1);
  ctx.shadowColor = 'transparent';

  // banner 右下角宣传语（右对齐，落在主视觉区域内）
  const promoLH = 40;
  let promoYTop = bannerH - 26 - promoLines.length * promoLH;
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  ctx.font = 'bold 28px system-ui, sans-serif';
  ctx.shadowColor = 'rgba(0,0,0,0.85)';
  ctx.shadowBlur = 10;
  ctx.shadowOffsetY = 2;
  ctx.fillStyle = '#cffafe';
  promoLines.forEach((ln) => {
    promoYTop += promoLH;
    ctx.fillText(ln, W - m, promoYTop);
  });
  ctx.shadowColor = 'transparent';

  // 标题
  let cy = bannerH + 56;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 54px system-ui, sans-serif';
  titleLines.forEach((ln) => {
    cy += titleLH;
    ctx.fillText(ln, m, cy);
  });
  cy += 8;

  // 标题首行右侧：横排小 LOGO（图标 + PlayToStar.com）
  const logoText = 'PlayToStar.com';
  ctx.font = 'bold 30px system-ui, sans-serif';
  const ltW = ctx.measureText(logoText).width;
  const iconS = 58;
  const gap = 12;
  const blockW = iconS + gap + ltW;
  const rightEdge = W - m;
  const iconLeft = rightEdge - blockW;
  const textLeft = iconLeft + iconS + gap;
  const logoCenterY = bannerH + 56 + titleLH - 20;
  if (icon) {
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.6)';
    ctx.shadowBlur = 10;
    ctx.shadowOffsetY = 2;
    ctx.drawImage(icon, iconLeft, logoCenterY - iconS / 2, iconS, iconS);
    ctx.restore();
  }
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#e6f7ff';
  ctx.shadowColor = 'rgba(0,0,0,0.7)';
  ctx.shadowBlur = 8;
  ctx.shadowOffsetY = 2;
  ctx.fillText(logoText, textLeft, logoCenterY);
  ctx.shadowColor = 'transparent';
  ctx.textBaseline = 'alphabetic';

  // 标题下青色短分隔线
  cy += 18;
  ctx.strokeStyle = 'rgba(34,211,238,0.45)';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(m, cy);
  ctx.lineTo(m + 90, cy);
  ctx.stroke();
  cy += 30;

  // 摘要
  ctx.fillStyle = '#d4dbec';
  ctx.font = '42px system-ui, sans-serif';
  summaryLines.forEach((ln) => {
    cy += sumLH;
    ctx.fillText(ln, m, cy);
  });
  cy += 40;

  // 截图（圆角）
  shots.forEach((s) => {
    const sx = m + (cw - s.dw) / 2;
    const sy = cy;
    ctx.save();
    ctx.beginPath();
    ctx.roundRect(sx, sy, s.dw, s.dh, 18);
    ctx.clip();
    ctx.drawImage(s.img, sx, sy, s.dw, s.dh);
    ctx.restore();
    ctx.strokeStyle = 'rgba(255,255,255,0.16)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.roundRect(sx, sy, s.dw, s.dh, 18);
    ctx.stroke();
    cy += s.dh + shotGap;
  });
  if (shots.length) cy += 10;

  return canvas;
}
