import React, { useState, useEffect, useMemo } from 'react';
import { X, Sparkles } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@client/src/components/ui/dialog';
import {
  getShineLevelsByPosition,
  getShineRuleType,
  getLegendShineLevels,
  type ShineLevel,
  type LegendShineLevel,
  type ShineRuleType,
} from '@client/src/utils/shine-data';

interface CompareShineDialogProps {
  open: boolean;
  position: string;
  playerType?: string | null;
  currentLevel: number;
  onClose: () => void;
  onConfirm: (level: number) => void;
}

const ATTR_NAME_MAP: Record<string, string> = {
  offensiveAwareness: '进攻意识', ballControl: '控球', dribbling: '盘球',
  tightPossession: '紧密控球', lowPass: '地面传球', loftedPass: '空中传球',
  finishing: '射门', header: '头球', setPieceTaking: '罚定位球',
  curve: '弧线球', speed: '速度', acceleration: '加速',
  kickingPower: '脚下力量', jump: '跳起', physicalContact: '身体接触',
  balance: '平衡', stamina: '体力', defensiveAwareness: '防守意识',
  tackle: '铲球', aggression: '积极性', defensiveEngagement: '防守参与度',
  gkAwareness: '守门员意识', gkReflexes: '扑救反应', gkClearing: '守门员扑救',
  gkCatching: '接球能力', gkReach: '守门员臂展',
};

const CompareShineDialog: React.FC<CompareShineDialogProps> = ({
  open,
  position,
  playerType,
  currentLevel,
  onClose,
  onConfirm,
}) => {
  const [tempLevel, setTempLevel] = useState<number>(currentLevel);

  useEffect(() => {
    if (open) {
      setTempLevel(currentLevel);
    }
  }, [open, currentLevel]);

  const shineRuleType: ShineRuleType = getShineRuleType(playerType);

  const shineLevels = useMemo((): (ShineLevel | LegendShineLevel)[] => {
    if (shineRuleType === 'normal') {
      return getShineLevelsByPosition(position);
    }
    return getLegendShineLevels(shineRuleType, position);
  }, [shineRuleType, position]);

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="w-[92vw] sm:max-w-[650px] max-h-[80vh] bg-[#0f1330] border border-white/10 text-white overflow-hidden p-0">
        <DialogHeader className="px-5 pt-5 pb-3 border-b border-white/10">
          <DialogTitle className="text-lg font-bold text-white">选择闪耀等级</DialogTitle>
        </DialogHeader>
        <div className="overflow-y-auto p-4 space-y-2" style={{ maxHeight: 'calc(80vh - 80px)' }}>
          {/* 无闪耀 */}
          <button
            type="button"
            onClick={() => setTempLevel(0)}
            className={`w-full text-left px-4 py-3 rounded-lg border transition-all ${
              tempLevel === 0
                ? 'border-yellow-400/60 bg-yellow-500/15'
                : 'border-white/10 bg-white/5 hover:border-yellow-400/40 hover:bg-yellow-500/5'
            }`}
          >
            <div className="flex items-start justify-between gap-3">
              <div className="flex items-center gap-2">
                <Sparkles className="w-5 h-5 text-gray-500" />
                <span className="text-lg font-bold text-gray-400">无闪耀</span>
              </div>
              <div className="text-right shrink-0">
                <div className="text-xs text-gray-500">— 碎片</div>
                <div className="text-xs text-gray-500 mt-0.5">—</div>
              </div>
            </div>
            <div className="text-xs text-gray-500 mt-1.5">无闪耀加成效果</div>
          </button>

          {shineLevels.map((s, idx) => {
            const lv = 'level' in s ? s.level : idx + 1;
            const isSelected = tempLevel === lv;
            const fragText = 'fragment' in s ? `${s.fragment} 碎片` : s.unlockCondition;
            const slotText = 'skillSlot' in s
              ? (typeof s.skillSlot === 'number' ? (s.skillSlot > 0 ? `技巧位${s.skillSlot}` : '—') : s.skillSlot)
              : '—';
            const hasAllAttr = 'allAttrPlus' in s && s.allAttrPlus && s.allAttrPlus > 0;
            const hasApBonus = 'abilityPointBonus' in s && s.abilityPointBonus && s.abilityPointBonus > 0;
            const bonusParts: string[] = [];
            if (hasAllAttr) bonusParts.push('全属性+1');
            if (hasApBonus) bonusParts.push(`能力点+${(s as { abilityPointBonus: number }).abilityPointBonus}`);
            const attrBonusText = Object.entries(s.attrs)
              .map(([k, v]) => `${ATTR_NAME_MAP[k] ?? k}+${v}`)
              .join('、');
            if (attrBonusText) bonusParts.push(attrBonusText);
            const bonusText = bonusParts.join('、');
            const key = 'level' in s ? s.level : `legend-${idx}`;
            return (
              <button
                key={key}
                type="button"
                onClick={() => setTempLevel(lv)}
                className={`w-full text-left px-4 py-3 rounded-lg border transition-all relative ${
                  isSelected
                    ? 'border-yellow-400/60 bg-yellow-500/15'
                    : 'border-white/10 bg-white/5 hover:border-yellow-400/40 hover:bg-yellow-500/5'
                }`}
              >
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-center gap-2">
                    <Sparkles className="w-5 h-5 text-yellow-400" />
                    <span className="text-lg font-bold text-yellow-300">闪耀 {lv}</span>
                  </div>
                  <div className="text-right shrink-0">
                    <div className="text-xs text-yellow-500 font-medium">{fragText}</div>
                    <div className="text-xs text-gray-400 mt-0.5">{slotText}</div>
                  </div>
                </div>
                <div className="text-xs text-yellow-300/90 mt-1.5 leading-relaxed">
                  奖励：{bonusText || '无'}
                </div>
                {lv >= 2 && (
                  <div className="text-[10px] text-gray-500 mt-1.5 text-right">
                    包含闪耀1-{lv}全部效果
                  </div>
                )}
              </button>
            );
          })}
        </div>

        <div className="flex gap-2 p-3 border-t border-white/10">
          <button
            onClick={onClose}
            className="flex-1 py-2 rounded-lg bg-white/10 text-white text-sm font-medium hover:bg-white/15 transition-colors"
          >
            取消
          </button>
          <button
            onClick={() => onConfirm(tempLevel)}
            className="flex-1 py-2 rounded-lg bg-amber-500 text-white text-sm font-medium hover:bg-amber-400 transition-colors"
          >
            确定
          </button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default CompareShineDialog;
