import React, { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@client/src/components/ui/dialog';
import { Button } from '@client/src/components/ui/button';
import { Download, Loader2, RefreshCw } from 'lucide-react';
import type { VersionManifest, NativeAppInfo } from '@client/src/native/app-updater';
import { downloadAndInstallUpdate } from '@client/src/native/app-updater';

interface UpdateDialogProps {
  open: boolean;
  manifest: VersionManifest | null;
  current: NativeAppInfo | null;
  /** 用户关闭（非强制时可关闭） */
  onClose: () => void;
}

const UpdateDialog: React.FC<UpdateDialogProps> = ({
  open,
  manifest,
  current,
  onClose,
}) => {
  const [phase, setPhase] = useState<'idle' | 'downloading' | 'launched' | 'error'>(
    'idle',
  );
  const [percent, setPercent] = useState(0);
  const [errorMsg, setErrorMsg] = useState('');

  if (!manifest) return null;
  const force = !!manifest.forceUpdate;
  const notes: string[] = Array.isArray(manifest.releaseNotes)
    ? manifest.releaseNotes
    : Array.isArray((manifest as VersionManifest & { updateContent?: string[] }).updateContent)
      ? (manifest as VersionManifest & { updateContent?: string[] }).updateContent!
      : [];

  const handleUpdate = async () => {
    setPhase('downloading');
    setPercent(0);
    setErrorMsg('');
    try {
      await downloadAndInstallUpdate(manifest.apkUrl, (p) => setPercent(p));
      setPhase('launched');
    } catch (e) {
      setErrorMsg(e instanceof Error ? e.message : '更新失败');
      setPhase('error');
    }
  };

  const handleOpenChange = (next: boolean) => {
    if (!next && !force && phase !== 'downloading') {
      onClose();
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="max-w-sm">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-lg">
            <RefreshCw className="h-5 w-5 text-cyan-400" />
            发现新版本 v{manifest.versionName}
          </DialogTitle>
          <DialogDescription>
            当前版本 v{current?.versionName ?? '?'}
            {manifest.publishedAt ? ` · 发布于 ${manifest.publishedAt}` : ''}
          </DialogDescription>
        </DialogHeader>

        <div className="max-h-48 overflow-y-auto rounded-lg bg-white/5 p-3 text-sm text-slate-200">
          {notes.length > 0 ? (
            <ul className="list-disc space-y-1 pl-4">
              {notes.map((line, i) => (
                <li key={i}>{line}</li>
              ))}
            </ul>
          ) : (
            <span className="text-slate-400">性能与体验优化。</span>
          )}
        </div>

        {phase === 'downloading' && (
          <div className="space-y-2">
            <div className="h-2 w-full overflow-hidden rounded-full bg-white/10">
              <div
                className="h-full rounded-full bg-gradient-to-r from-cyan-400 to-pink-500 transition-all"
                style={{ width: `${percent}%` }}
              />
            </div>
            <div className="text-center text-xs text-slate-400">
              正在下载更新包… {percent}%
            </div>
          </div>
        )}

        {phase === 'launched' && (
          <div className="rounded-lg bg-cyan-500/10 p-3 text-center text-sm text-cyan-200">
            安装包已准备好，请在系统弹窗中点击「安装」完成更新。
          </div>
        )}

        {phase === 'error' && (
          <div className="rounded-lg bg-red-500/10 p-3 text-center text-sm text-red-200">
            {errorMsg}
            <div className="mt-1 text-xs text-slate-400">
              也可前往官网 playtostar.com 手动下载最新版。
            </div>
          </div>
        )}

        <DialogFooter className="flex-col gap-2 sm:flex-col">
          {phase === 'idle' || phase === 'error' ? (
            <>
              <Button
                className="w-full bg-gradient-to-r from-cyan-500 to-pink-500 text-white"
                onClick={handleUpdate}
              >
                <Download className="mr-1 h-4 w-4" />
                立即更新
              </Button>
              {!force && (
                <Button variant="ghost" className="w-full" onClick={onClose}>
                  稍后再说
                </Button>
              )}
            </>
          ) : phase === 'downloading' ? (
            <Button disabled className="w-full">
              <Loader2 className="mr-1 h-4 w-4 animate-spin" />
              下载中 {percent}%
            </Button>
          ) : (
            <Button variant="ghost" className="w-full" onClick={onClose}>
              关闭
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default UpdateDialog;
