export function getAttrColorClass(value: number): string {
  if (value >= 100) return 'bg-[#A855F7] text-white shadow-[0_0_10px_rgba(168_85_247_0.6)]';
  if (value >= 90) return 'bg-[#3B82F6] text-white shadow-[0_0_8px_rgba(59_130_246_0.5)]';
  if (value >= 80) return 'bg-[#22C55E] text-white shadow-[0_0_6px_rgba(34_197_94_0.4)]';
  if (value >= 70) return 'bg-[#F59E0B] text-white';
  return 'bg-[#EF4444] text-white';
}

export function getAttrTextColorClass(value: number): string {
  if (value >= 100) return 'text-[#C084FC]';
  if (value >= 90) return 'text-[#60A5FA]';
  if (value >= 80) return 'text-[#4ADE80]';
  if (value >= 70) return 'text-[#FBBF24]';
  return 'text-[#F87171]';
}

export function getAttrHexColor(value: number): string {
  if (value >= 100) return '#C084FC';
  if (value >= 90) return '#60A5FA';
  if (value >= 80) return '#4ADE80';
  if (value >= 70) return '#FBBF24';
  return '#F87171';
}
