import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';
import type {
  ReputationSummary,
  ReputationLogListResponse,
} from '@shared/api.interface';

export async function getReputationSummary(): Promise<ReputationSummary> {
  const res = await axiosForBackend.get('/api/reputation/summary');
  return res.data;
}

export async function getReputationLogs(params: {
  page?: number;
  pageSize?: number;
  filter?: 'all' | 'gain' | 'loss';
}): Promise<ReputationLogListResponse> {
  const { page = 1, pageSize = 20, filter = 'all' } = params;
  const res = await axiosForBackend.get('/api/reputation/logs', {
    params: { page, pageSize, filter },
  });
  return res.data;
}
