import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft } from 'lucide-react';
import { Loader2 } from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import PlayerCard from '@client/src/components/PlayerCard';
import CommentSection from '@client/src/components/CommentSection';
import { getPositionRankingByPosition } from '@client/src/api/players';
import { useIsLandscape } from '@client/src/hooks/useIsLandscape';
import type { RankedPlayerItem } from '@shared/api.interface';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';

const POSITION_THEME: Record<string, { gradient: string; glow: string; label: string }> = {
  CF: { gradient: 'from-red-500 to-orange-500', glow: 'shadow-[0_0_20px_rgba(249_115_22_0.4)]', label: '中锋' },
  SS: { gradient: 'from-orange-500 to-yellow-500', glow: 'shadow-[0_0_20px_rgba(234_179_8_0.4)]', label: '影锋' },
  LWF: { gradient: 'from-rose-500 to-pink-500', glow: 'shadow-[0_0_20px_rgba(236_72_153_0.4)]', label: '左边锋' },
  RWF: { gradient: 'from-rose-500 to-pink-500', glow: 'shadow-[0_0_20px_rgba(236_72_153_0.4)]', label: '右边锋' },
  AMF: { gradient: 'from-cyan-500 to-pink-500', glow: 'shadow-[0_0_20px_rgba(34_211_238_0.4)]', label: '前腰' },
  LMF: { gradient: 'from-cyan-500 to-violet-500', glow: 'shadow-[0_0_20px_rgba(139_92_246_0.4)]', label: '左前卫' },
  RMF: { gradient: 'from-cyan-500 to-violet-500', glow: 'shadow-[0_0_20px_rgba(139_92_246_0.4)]', label: '右前卫' },
  CMF: { gradient: 'from-blue-500 to-indigo-500', glow: 'shadow-[0_0_20px_rgba(99_102_241_0.4)]', label: '中前卫' },
  DMF: { gradient: 'from-cyan-500 to-blue-500', glow: 'shadow-[0_0_20px_rgba(59_130_246_0.4)]', label: '后腰' },
  LB: { gradient: 'from-teal-500 to-emerald-500', glow: 'shadow-[0_0_20px_rgba(20_184_166_0.4)]', label: '左后卫' },
  RB: { gradient: 'from-teal-500 to-emerald-500', glow: 'shadow-[0_0_20px_rgba(20_184_166_0.4)]', label: '右后卫' },
  CB: { gradient: 'from-green-500 to-emerald-500', glow: 'shadow-[0_0_20px_rgba(34_197_94_0.4)]', label: '中后卫' },
  GK: { gradient: 'from-yellow-500 to-amber-500', glow: 'shadow-[0_0_20px_rgba(245_158_11_0.4)]', label: '门将' },
};

const RankingPositionPage: React.FC = () => {
  const { position } = useParams<{ position: string }>();
  const navigate = useNavigate();
  const { lang } = useI18n();
  const [data, setData] = useState<{ positionKey: string; positionLabel: string; items: RankedPlayerItem[] } | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const landscape = useIsLandscape();
  const gridCls = landscape ? 'grid grid-cols-8 gap-2' : 'grid grid-cols-5 gap-2';

  useEffect(() => {
    if (!position) return;
    let cancelled = false;
    setLoading(true);
    setError(null);
    getPositionRankingByPosition(position)
      .then((res) => {
        if (!cancelled) setData(res);
      })
      .catch((err) => {
        logger.error('加载位置榜单失败', err);
        if (!cancelled) setError(lang === 'en' ? 'Failed to load, please try again later' : '加载失败，请稍后重试');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [position, lang]);

  const theme = position && POSITION_THEME[position]
    ? POSITION_THEME[position]
    : { gradient: 'from-gray-500 to-gray-600', glow: '', label: position || '' };

  const handleBack = () => {
    navigate(-1);
  };

  const handleCardClick = (player: RankedPlayerItem) => {
    navigate(`/player/${player.id}`);
  };

  if (loading) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-cyan-400" />
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="px-4 py-6 sm:px-6 sm:py-8">
        <button
          onClick={handleBack}
          className="mb-4 flex items-center gap-1 text-white/60 hover:text-white/90"
        >
          <ArrowLeft className="h-4 w-4" />
          {lang === 'en' ? 'Back to Rankings' : '返回榜单'}
        </button>
        <div className="flex min-h-[40vh] items-center justify-center text-white/70">
          {error || (lang === 'en' ? 'No data' : '暂无数据')}
        </div>
      </div>
    );
  }

  return (
    <div className="px-4 py-6 sm:px-6 sm:py-8">
      <button
        onClick={handleBack}
        className="mb-4 flex items-center gap-1 text-sm text-white/60 transition hover:text-white/90 sm:text-base"
      >
        <ArrowLeft className="h-4 w-4" />
        {lang === 'en' ? 'Back to Rankings' : '返回榜单'}
      </button>

      <div className="mb-4 sm:mb-6">
        <div className="flex items-center gap-3">
          <span className={`inline-flex h-8 w-2 flex-shrink-0 rounded-full bg-gradient-to-b ${theme.gradient} ${theme.glow}`} />
          <h1 className="text-2xl font-black tracking-wider text-white sm:text-3xl" style={{ textShadow: '0 0 12px rgba(34,211,238,0.6)' }}>
            {lang === 'en' ? data.positionKey : data.positionLabel} TOP 10
          </h1>
        </div>
        <p className="mt-1 text-xs text-white/50 sm:text-sm">
          {lang === 'en'
            ? 'Rankings are sorted by player rating, then by ability on ties. Go rate your favorite stars!'
            : '榜单按照玩家评分排序，评分相同按照能力值。快去给你喜欢的球星打分吧！'}
        </p>
      </div>

      <div className={gridCls}>
        {data.items.map((player, index) => (
          <div key={player.id} className="relative">
            <div className="absolute left-1.5 top-1.5 z-20 flex h-6 w-6 items-center justify-center rounded-full bg-gradient-to-br from-yellow-400 to-orange-500 text-xs font-black text-white shadow-[0_0_6px_rgba(249_115_22_0.7)] sm:h-7 sm:w-7 sm:text-sm">
              {index + 1}
            </div>
            <PlayerCard player={player} onClick={() => handleCardClick(player)} bareCard />
          </div>
        ))}
      </div>

      {data.items.length === 0 && (
        <div className="rounded-xl border border-white/10 bg-[#141838]/50 py-10 text-center text-white/40">
          {lang === 'en' ? 'Not enough ratings yet' : '暂无足够评分数据'}
        </div>
      )}

      <div className="mt-10 sm:mt-12">
        <CommentSection
          targetType="ranking_position"
          targetId={data.positionKey}
          pageSize={10}
          collapsible={false}
        />
      </div>
    </div>
  );
};

export default RankingPositionPage;
