import React, { useState } from 'react';
import { Loader2, X } from 'lucide-react';
import { toast } from 'sonner';
import { createPost, type BoardKey, type MediaItem } from '@client/src/api/forum';
import { useAuth } from '@client/src/context/AuthContext';

/** 可发帖的板块（与论坛发帖一致，排除“关注”） */
const SHARE_BOARDS: { key: BoardKey; label: string }[] = [
  { key: 'international', label: '国际服' },
  { key: 'cn', label: '国服' },
  { key: 'bug', label: '意见/BUG' },
];

export interface ShareToForumDialogProps {
  open: boolean;
  onClose: () => void;
  /** 预填标题（用户可改） */
  defaultTitle: string;
  /** 预填正文（系统生成内容，如加点/技能明细），用户补充的文字会追加在其后 */
  defaultContent?: string;
  /** 可选：异步生成并上传要附带的媒体（如榜单图） */
  buildMedia?: () => Promise<MediaItem[] | undefined>;
  onPosted?: (post: { id: string }) => void;
}

/**
 * 可复用的“分享到论坛”弹窗：
 * 可选板块 + 可编辑标题 + 可补充正文，支持附带媒体。
 * 强度榜、培养方案等场景共用。
 */
const ShareToForumDialog: React.FC<ShareToForumDialogProps> = ({
  open,
  onClose,
  defaultTitle,
  defaultContent,
  buildMedia,
  onPosted,
}) => {
  const { user, getAuthHeaders } = useAuth();
  const [title, setTitle] = useState(defaultTitle);
  const [note, setNote] = useState('');
  const [board, setBoard] = useState<BoardKey>('cn');
  const [busy, setBusy] = useState(false);

  // 每次打开时同步外部最新的默认标题
  React.useEffect(() => {
    if (open) {
      setTitle(defaultTitle);
      setNote('');
      setBoard('cn');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  if (!open) return null;

  const handlePublish = async (): Promise<void> => {
    if (!user) {
      toast.info('请先登录后再分享');
      return;
    }
    if (busy) return;
    setBusy(true);
    try {
      let media: MediaItem[] | undefined;
      if (buildMedia) media = await buildMedia();
      const content = [defaultContent?.trim(), note.trim()].filter(Boolean).join('\n\n');
      const post = await createPost(
        {
          title: title.trim() || defaultTitle || '来自 PlayToStar APP 的分享',
          content,
          board,
          mediaUrls: media && media.length > 0 ? media : undefined,
        },
        getAuthHeaders(),
      );
      toast.success('已分享到论坛');
      onPosted?.(post);
      setNote('');
      onClose();
    } catch {
      toast.error('分享失败，请稍后重试');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="share-overlay-mobile fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-3 sm:p-4">
      {/* 移动端（窄屏）整体放大：宽度上限提到 640、内边距 p-8，字号/行高全面加大，面积约翻倍；sm: 桌面恢复紧凑 */}
      <div className="share-dialog-mobile w-full max-w-[640px] rounded-2xl border border-white/10 bg-[#12172e] p-8 shadow-2xl sm:max-w-md sm:p-5">
        <div className="mb-5 flex items-center justify-between sm:mb-4">
          <h3 className="share-title text-2xl font-bold text-white sm:text-base">分享到论坛</h3>
          <button
            type="button"
            onClick={onClose}
            className="share-close rounded-lg p-1 text-white/50 hover:bg-white/10 hover:text-white"
            aria-label="关闭"
          >
            <X className="h-8 w-8 sm:h-5 sm:w-5" />
          </button>
        </div>

        {/* 标题 */}
        <label className="mb-1.5 block text-base font-bold text-white/50 sm:mb-1 sm:text-xs">标题</label>
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          maxLength={60}
          className="mb-4 w-full rounded-lg border border-white/15 bg-[#0d1230] px-4 py-3.5 text-lg text-white outline-none focus:border-cyan-400 sm:mb-3 sm:px-3 sm:py-2 sm:text-sm"
        />

        {/* 板块 */}
        <label className="mb-1.5 block text-base font-bold text-white/50 sm:mb-1 sm:text-xs">选择板块</label>
        <div className="mb-4 flex gap-2 sm:mb-3">
          {SHARE_BOARDS.map((b) => (
            <button
              key={b.key}
              type="button"
              onClick={() => setBoard(b.key)}
              className={`flex-1 rounded-lg px-2 py-3.5 text-lg font-bold transition sm:py-1.5 sm:text-sm ${
                board === b.key
                  ? 'bg-cyan-500 text-white shadow-[0_2px_10px_rgba(34,229,255,0.35)]'
                  : 'bg-white/10 text-white/60 hover:bg-white/15'
              }`}
            >
              {b.label}
            </button>
          ))}
        </div>

        {/* 系统预填正文（只读预览） */}
        {defaultContent && defaultContent.trim() && (
          <>
            <label className="mb-1.5 block text-base font-bold text-white/50 sm:mb-1 sm:text-xs">内容预览</label>
            <div className="mb-3 max-h-44 overflow-y-auto whitespace-pre-wrap rounded-lg border border-white/10 bg-black/30 px-4 py-3 text-base leading-relaxed text-white/55 sm:max-h-28 sm:px-3 sm:py-2 sm:text-[11px]">
              {defaultContent.trim()}
            </div>
          </>
        )}

        {/* 用户补充正文 */}
        <label className="mb-1.5 block text-base font-bold text-white/50 sm:mb-1 sm:text-xs">补充说明（可选）</label>
        <textarea
          value={note}
          onChange={(e) => setNote(e.target.value)}
          rows={4}
          maxLength={1000}
          placeholder="说点什么…"
          className="mb-5 w-full resize-none rounded-lg border border-white/15 bg-[#0d1230] px-4 py-3.5 text-lg text-white outline-none focus:border-cyan-400 sm:mb-4 sm:px-3 sm:py-2 sm:text-sm"
        />

        <button
          type="button"
          onClick={() => void handlePublish()}
          disabled={busy}
          className="share-publish w-full rounded-lg bg-gradient-to-r from-pink-500 to-rose-500 py-5 text-lg font-bold text-white hover:opacity-90 disabled:opacity-60 sm:py-2.5 sm:text-sm"
        >
          {busy ? <Loader2 className="mx-auto h-7 w-7 animate-spin sm:h-5 sm:w-5" /> : '发布到论坛'}
        </button>
      </div>
    </div>
  );
};

export default ShareToForumDialog;
