import React, { useRef, useEffect } from 'react';

/**
 * 可缩放、可拖动的图片（用于评论区/讨论区灯箱）。
 * 触摸：单指拖动（已放大时）、双指捏合缩放、双击放大/还原；
 * 鼠标：滚轮缩放、按住拖动（网页端）。
 * 缩放以图片中心为基准，平移会被钳制在合理范围内，不会把图拖丢。
 */
interface ZoomableImageProps {
  src: string;
  alt?: string;
  className?: string;
}

const MIN_S = 1;
const MAX_S = 5;

const clamp = (v: number, min: number, max: number): number =>
  Math.min(max, Math.max(min, v));

const ZoomableImage: React.FC<ZoomableImageProps> = ({ src, alt = '', className = '' }) => {
  const imgRef = useRef<HTMLImageElement | null>(null);

  useEffect(() => {
    const el = imgRef.current;
    if (!el) return;

    let mode: 'none' | 'pan' | 'pinch' = 'none';
    let s = 1;
    let tx = 0;
    let ty = 0;

    // pan 起点
    let panX0 = 0;
    let panY0 = 0;
    let tx0 = 0;
    let ty0 = 0;
    // pinch 起点
    let pinchDist0 = 1;
    let pinchMidX0 = 0;
    let pinchMidY0 = 0;
    let s0 = 1;
    // 双击判定
    let lastTapT = 0;
    let lastTapX = 0;
    let lastTapY = 0;
    let moved = false;

    const apply = (): void => {
      el.style.transform = `translate(${tx}px, ${ty}px) scale(${s})`;
    };

    const baseSize = (): { w: number; h: number } => ({
      w: el.clientWidth || 1,
      h: el.clientHeight || 1,
    });

    // 依据当前缩放钳制平移范围
    const clampTranslate = (): void => {
      const { w, h } = baseSize();
      const maxX = (w * (s - 1)) / 2;
      const maxY = (h * (s - 1)) / 2;
      tx = s <= 1.001 ? 0 : clamp(tx, -maxX, maxX);
      ty = s <= 1.001 ? 0 : clamp(ty, -maxY, maxY);
    };

    const dist = (t1: Touch, t2: Touch): number =>
      Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
    const mid = (t1: Touch, t2: Touch): { x: number; y: number } => ({
      x: (t1.clientX + t2.clientX) / 2,
      y: (t1.clientY + t2.clientY) / 2,
    });

    // 以某点为中心缩放到目标比例
    const zoomAt = (cx: number, cy: number, target: number): void => {
      const rect = el.getBoundingClientRect();
      const centerX = rect.left + rect.width / 2;
      const centerY = rect.top + rect.height / 2;
      const vx = cx - centerX;
      const vy = cy - centerY;
      const newS = clamp(target, MIN_S, MAX_S);
      // 保持焦点不动：t' = (F-C)(1 - s') （基准比例为1）
      tx = vx * (1 - newS);
      ty = vy * (1 - newS);
      s = newS;
      clampTranslate();
      apply();
    };

    // ————— 触摸 —————
    const onTouchStart = (e: TouchEvent): void => {
      moved = false;
      if (e.touches.length === 1) {
        const t = e.touches[0];
        mode = 'pan';
        panX0 = t.clientX;
        panY0 = t.clientY;
        tx0 = tx;
        ty0 = ty;
      } else if (e.touches.length === 2) {
        mode = 'pinch';
        const m = mid(e.touches[0], e.touches[1]);
        pinchDist0 = dist(e.touches[0], e.touches[1]) || 1;
        pinchMidX0 = m.x;
        pinchMidY0 = m.y;
        s0 = s;
        tx0 = tx;
        ty0 = ty;
      }
    };

    const onTouchMove = (e: TouchEvent): void => {
      if (mode === 'pan' && e.touches.length === 1) {
        const t = e.touches[0];
        const dx = t.clientX - panX0;
        const dy = t.clientY - panY0;
        if (Math.abs(dx) > 6 || Math.abs(dy) > 6) moved = true;
        if (s > 1.01) {
          e.preventDefault();
          tx = tx0 + dx;
          ty = ty0 + dy;
          clampTranslate();
          apply();
        }
      } else if (mode === 'pinch' && e.touches.length === 2) {
        e.preventDefault();
        moved = true;
        const m = mid(e.touches[0], e.touches[1]);
        const ratio = (dist(e.touches[0], e.touches[1]) || 1) / pinchDist0;
        s = clamp(s0 * ratio, MIN_S, MAX_S);
        // 跟随双指中点平移
        tx = tx0 + (m.x - pinchMidX0);
        ty = ty0 + (m.y - pinchMidY0);
        clampTranslate();
        apply();
      }
    };

    const onTouchEnd = (e: TouchEvent): void => {
      if (mode === 'pan' && e.touches.length === 0 && !moved) {
        // 单击/双击判定
        const t = e.changedTouches[0];
        const now = Date.now();
        const dt = now - lastTapT;
        const near = Math.hypot(t.clientX - lastTapX, t.clientY - lastTapY) < 28;
        if (dt < 300 && near) {
          if (s > 1.05) {
            s = 1; tx = 0; ty = 0;
          } else {
            zoomAt(t.clientX, t.clientY, 2.5);
          }
          lastTapT = 0;
        } else {
          lastTapT = now;
          lastTapX = t.clientX;
          lastTapY = t.clientY;
        }
      }
      if (e.touches.length === 0) {
        mode = 'none';
      } else if (e.touches.length === 1) {
        // 从捏合回到单指：重置为平移起点
        const t = e.touches[0];
        mode = 'pan';
        panX0 = t.clientX;
        panY0 = t.clientY;
        tx0 = tx;
        ty0 = ty;
      }
    };

    // ————— 鼠标（网页） —————
    const onWheel = (e: WheelEvent): void => {
      e.preventDefault();
      const factor = e.deltaY < 0 ? 1.15 : 1 / 1.15;
      zoomAt(e.clientX, e.clientY, s * factor);
    };
    let mouseDown = false;
    const onMouseDown = (e: MouseEvent): void => {
      if (s <= 1.01) return;
      mouseDown = true;
      panX0 = e.clientX; panY0 = e.clientY; tx0 = tx; ty0 = ty;
      el.style.cursor = 'grabbing';
    };
    const onMouseMove = (e: MouseEvent): void => {
      if (!mouseDown) return;
      tx = tx0 + (e.clientX - panX0);
      ty = ty0 + (e.clientY - panY0);
      clampTranslate();
      apply();
    };
    const onMouseUp = (): void => {
      mouseDown = false;
      el.style.cursor = s > 1.01 ? 'grab' : '';
    };

    el.addEventListener('touchstart', onTouchStart, { passive: true });
    el.addEventListener('touchmove', onTouchMove, { passive: false });
    el.addEventListener('touchend', onTouchEnd, { passive: true });
    el.addEventListener('touchcancel', onTouchEnd, { passive: true });
    el.addEventListener('wheel', onWheel, { passive: false });
    el.addEventListener('mousedown', onMouseDown);
    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);

    // 切图时复位
    s = 1; tx = 0; ty = 0;
    apply();

    return () => {
      el.removeEventListener('touchstart', onTouchStart);
      el.removeEventListener('touchmove', onTouchMove);
      el.removeEventListener('touchend', onTouchEnd);
      el.removeEventListener('touchcancel', onTouchEnd);
      el.removeEventListener('wheel', onWheel);
      el.removeEventListener('mousedown', onMouseDown);
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    };
  }, [src]);

  return (
    <img
      ref={imgRef}
      src={src}
      alt={alt}
      draggable={false}
      className={`${className} touch-none select-none will-change-transform`}
      style={{ transform: 'translate(0px,0px) scale(1)' }}
    />
  );
};

export default ZoomableImage;
