import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';
import { useNavigate, useSearchParams, useLocation } from 'react-router-dom';
import {
  Search,
  Loader2,
  Users,
  Filter,
  X,
  Flame,
  Clock,
  Crown,
  Zap,
  Star,
  Newspaper,
  Heart,
  Gift,
} from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';

import { Input } from '@client/src/components/ui/input';
import { Button } from '@client/src/components/ui/button';

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@client/src/components/ui/select';
import PlayerCard from '@client/src/components/PlayerCard';
import InfiniteScrollFooter from '@client/src/components/InfiniteScrollFooter';
import { useInfiniteScroll } from '@client/src/hooks/useInfiniteScroll';
import { useIsLandscape } from '@client/src/hooks/useIsLandscape';
import { getPlayers, getHotPlayers, getLatestPlayers, getPlayerTypes, getDefensiveStyles, getLatestPlayersGrouped, getNationalities } from '@client/src/api/players';
import { getNewsList } from '@client/src/api/news';
import { getPackList } from '@client/src/api/packs';
import { getHotPosts, type ForumPost } from '@client/src/api/forum';
import PackCardFan from '@client/src/pages/packs/PackCardFan';
import { getPackTypeInfo, formatPackDateDisplay } from '@client/src/pages/packs/pack-type-utils';
import type { NewsArticle, Pack } from '@shared/api.interface';
import { getVisitorId } from '@client/src/utils/visitor';
import type { PlayerListItem, PlayerSortField, HotPlayerItem, LatestPlayersGroupedResponse } from '@shared/api.interface';
import { AdvancedFilterDialog } from './AdvancedFilterDialog';
import { ActiveFilterBadges } from './ActiveFilterBadges';
import {
  SORT_PRESET_OPTIONS,
  hasActiveFilters,
  type PlayerFilterState,
} from './player-utils';

const initialFilters: PlayerFilterState = {
  positions: [],
  attackStyles: [],
  defenseStyles: [],
  aiStyles: [],
  nationality: '',
  club: '',
  commonSkills: [],
  stSkills: [],
  preferredFoot: '',
  weakFootFreq: '',
  weakFootAcc: '',
  formConsistency: '',
  playerTypes: [],
  league: '',
  teamSeasons: [],
  overallMin: '',
  overallMax: '',
  ageMin: '',
  ageMax: '',
  heightMin: '',
  heightMax: '',
  weightMin: '',
  weightMax: '',
  radarMins: {},
};

const PlayersPage: React.FC<{ variant?: 'home' | 'list' }> = ({ variant = 'home' }) => {
  // home = 主页（单行横滑 + 热讯）；list = 球员页（传统网格，首批 2 行 10 个）
  const isList = variant === 'list';
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const location = useLocation();
  const landscape = useIsLandscape();
  const { t, lang } = useI18n();
  // 球员页：横屏每行 5 个（2 行=10）、竖屏每行 2 个；
  // 主页内搜索结果：横屏每行 8 个、竖屏每行 5 个
  // 所有结果/分组网格统一：横屏每行 8、竖屏每行 5（与正式页一致）
  const gridCls = landscape
    ? 'grid grid-cols-8 gap-2'
    : 'grid grid-cols-5 gap-2';

  const homeCacheRef = useRef<{
    hot: HotPlayerItem[];
    latest: LatestPlayersGroupedResponse;
    types: string[];
    defStyles: string[];
    nationalities: string[];
    loaded: boolean;
  }>({
    hot: [],
    latest: { epicBt: [], st: [], featuredLegend: [] },
    types: [],
    defStyles: [],
    nationalities: [],
    loaded: false,
  });

  const [searchPlayers, setSearchPlayers] = useState<PlayerListItem[]>([]);
  const [allPlayers, setAllPlayers] = useState<PlayerListItem[]>([]);
  const [totalPlayers, setTotalPlayers] = useState(0);
  const [loading, setLoading] = useState(false);

  const [keyword, setKeyword] = useState('');
  const [debouncedKeyword, setDebouncedKeyword] = useState('');

   // 球员页首批 10 个（横屏正好 2 行）；主页搜索结果每页 30
   const pageSize = isList ? 10 : 30;

   const [hideStandard, setHideStandard] = useState<boolean>(true);

   const STORAGE_KEY = 'players_page_state';

  const savedState = useMemo(() => {
    try {
      const raw = sessionStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  }, []);

  const [page, setPage] = useState<number>(1);
  const [sortPreset, setSortPreset] = useState<string>('overall-desc');

  const [filters, setFilters] = useState<PlayerFilterState>(initialFilters);

  const currentSortField: PlayerSortField = SORT_PRESET_OPTIONS.find(
    (o) => o.key === sortPreset,
  )?.field as PlayerSortField || 'overallRating';
  const currentSortOrder: 'asc' | 'desc' = SORT_PRESET_OPTIONS.find(
    (o) => o.key === sortPreset,
  )?.order || 'desc';

  useMemo(() => {
    getVisitorId();
  }, []);

  useEffect(() => {
    // 页面打开时默认不恢复任何筛选条件
  }, []);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      setDebouncedKeyword(keyword);
    }, 300);
    return () => window.clearTimeout(timer);
  }, [keyword]);

  const [isSearchMode, setIsSearchMode] = useState(false);
  const [hotPlayers, setHotPlayers] = useState<HotPlayerItem[]>([]);
  const [latestGrouped, setLatestGrouped] = useState<LatestPlayersGroupedResponse>({ epicBt: [], st: [], featuredLegend: [] });
  const [homeNews, setHomeNews] = useState<NewsArticle[]>([]);
  const [hotPosts, setHotPosts] = useState<ForumPost[]>([]);
  // 首页“活动包”：国际服/国服各取最新 3 个，交错成每行 2 个、共 3 行
  const [eventPacks, setEventPacks] = useState<{ pack: Pack; server: 'global' | 'cn' }[]>([]);
  const [hotLoading, setHotLoading] = useState(false);
  const [latestLoading, setLatestLoading] = useState(false);
  const [playerTypeList, setPlayerTypeList] = useState<string[]>([]);
  const [defensiveStyleList, setDefensiveStyleList] = useState<string[]>([]);
  const [nationalityList, setNationalityList] = useState<string[]>([]);

  const fetchHomeData = useCallback(() => {
    if (homeCacheRef.current.loaded) {
      setHotPlayers(Array.isArray(homeCacheRef.current.hot) ? homeCacheRef.current.hot : []);
      const cachedLatest = homeCacheRef.current.latest;
      setLatestGrouped({
        epicBt: Array.isArray(cachedLatest?.epicBt) ? cachedLatest.epicBt : [],
        st: Array.isArray(cachedLatest?.st) ? cachedLatest.st : [],
        featuredLegend: Array.isArray(cachedLatest?.featuredLegend) ? cachedLatest.featuredLegend : [],
      });
      setPlayerTypeList(Array.isArray(homeCacheRef.current.types) ? homeCacheRef.current.types : []);
      setDefensiveStyleList(Array.isArray(homeCacheRef.current.defStyles) ? homeCacheRef.current.defStyles : []);
      setNationalityList(Array.isArray(homeCacheRef.current.nationalities) ? homeCacheRef.current.nationalities : []);
      return;
    }
    setHotLoading(true);
    setLatestLoading(true);

    getHotPlayers(10, 12)
      .then((res) => {
        const items = Array.isArray(res?.items) ? res.items : [];
        setHotPlayers(items);
        homeCacheRef.current.hot = items;
      })
      .catch((error) => {
        logger.error('加载热门球员失败', error);
        setHotPlayers([]);
      })
      .finally(() => setHotLoading(false));

    getLatestPlayersGrouped(10)
      .then((res) => {
        const safe: LatestPlayersGroupedResponse = {
          epicBt: Array.isArray(res?.epicBt) ? res.epicBt : [],
          st: Array.isArray(res?.st) ? res.st : [],
          featuredLegend: Array.isArray(res?.featuredLegend) ? res.featuredLegend : [],
        };
        setLatestGrouped(safe);
        homeCacheRef.current.latest = safe;
      })
      .catch((error) => {
        logger.error('加载最新球员失败', error);
        setLatestGrouped({ epicBt: [], st: [], featuredLegend: [] });
      })
      .finally(() => setLatestLoading(false));

    getPlayerTypes()
      .then((res) => {
        const items = Array.isArray(res?.items) ? res.items : [];
        setPlayerTypeList(items);
        homeCacheRef.current.types = items;
      })
      .catch(() => setPlayerTypeList([]));

    getDefensiveStyles()
      .then((res) => {
        const items = Array.isArray(res?.items) ? res.items : [];
        setDefensiveStyleList(items);
        homeCacheRef.current.defStyles = items;
      })
      .catch(() => setDefensiveStyleList([]));

    getNationalities()
      .then((res) => {
        const items = Array.isArray(res?.items) ? res.items : [];
        setNationalityList(items);
        homeCacheRef.current.nationalities = items;
        homeCacheRef.current.loaded = true;
      })
      .catch(() => {
        setNationalityList([]);
        homeCacheRef.current.loaded = true;
      });
  }, []);

  const fetchPlayers = useCallback(async () => {
    const hasAnySearch =
      debouncedKeyword ||
      hasActiveFilters(filters);
    if (!hasAnySearch) {
      setIsSearchMode(false);
      return;
    }
    setIsSearchMode(true);
    setLoading(true);
    try {
      const data = await getPlayers({
        page,
        pageSize,
        keyword: debouncedKeyword,
        league: filters.league,
        nationality: filters.nationality,
        club: filters.club,
        playerTypes: filters.playerTypes,
        excludeStandard: hideStandard,
        sortBy: currentSortField,
        sortOrder: currentSortOrder,
        positions: filters.positions,
        attackStyles: filters.attackStyles,
        defenseStyles: filters.defenseStyles,
        aiStyles: filters.aiStyles,
        commonSkills: filters.commonSkills,
        stSkills: filters.stSkills,
        preferredFoot: filters.preferredFoot,
        weakFootFreq: filters.weakFootFreq,
        weakFootAcc: filters.weakFootAcc,
        formConsistency: filters.formConsistency,
        teamSeasons: filters.teamSeasons,
        overallMin: filters.overallMin,
        overallMax: filters.overallMax,
        ageMin: filters.ageMin,
        ageMax: filters.ageMax,
        heightMin: filters.heightMin,
        heightMax: filters.heightMax,
        weightMin: filters.weightMin,
        weightMax: filters.weightMax,
        radarMins: filters.radarMins,
      });
      setSearchPlayers(data.items);
      setTotalPlayers(data.total);
      if (page === 1) {
        setAllPlayers(data.items);
      } else {
        setAllPlayers((prev) => [...prev, ...data.items]);
      }
    } catch (error) {
      logger.error('加载球员列表失败', error);
      setSearchPlayers([]);
      setAllPlayers([]);
      setTotalPlayers(0);
    } finally {
      setLoading(false);
    }
  }, [
    isList,
    debouncedKeyword,
    filters,
    hideStandard,
    page,
    pageSize,
    currentSortField,
    currentSortOrder,
  ]);

  useEffect(() => {
    fetchHomeData();
  }, [fetchHomeData]);

  // 首页“最新资讯 + 热门帖子（>50赞）”：每次进入/刷新拉取当前集合，
  // 新达标内容会出现；集合稳定后自然不再变化。球员页不加载。
  useEffect(() => {
    if (isList) {
      setHomeNews([]);
      setHotPosts([]);
      setEventPacks([]);
      return;
    }
    getNewsList({ pageSize: 8 })
      .then((r) => setHomeNews(Array.isArray(r?.items) ? r.items : []))
      .catch(() => setHomeNews([]));
    getHotPosts({ minLikes: 50, limit: 8 })
      .then((r) => setHotPosts(Array.isArray(r?.items) ? r.items : []))
      .catch(() => setHotPosts([]));
    // 活动包：国际服/国服各拉列表，按日期倒序取最新 3，交错成 [g,cn,g,cn,g,cn]
    void (async () => {
      // 卡包日期（ISO 或中文）统一折成可比较数值，仅到月的给当月首日档
      const dateKey = (s?: string | null): number => {
        const v = s || '';
        let m = v.match(/(\d{4})-(\d{1,2})-(\d{1,2})/) || v.match(/(\d{4})年(\d{1,2})月(\d{1,2})/);
        if (m) return +m[1] * 10000 + +m[2] * 100 + +m[3];
        m = v.match(/(\d{4})-(\d{1,2})/) || v.match(/(\d{4})年(\d{1,2})月/);
        if (m) return +m[1] * 10000 + +m[2] * 100;
        return 0;
      };
      // 首页『最新活动包』6 个展示位：只展示含「史诗/BT/ST」球员的包（卡包列表页仍显示全部）
      const isHomePack = (p: Pack): boolean =>
        (p.playerTypes || []).some((t) => ['史诗', 'BT', 'ST球员'].includes(t));
      const top3 = (list: Pack[]): Pack[] =>
        [...list]
          .filter(isHomePack)
          .sort((a, b) => dateKey(b.cnDate) - dateKey(a.cnDate) || b.seq - a.seq)
          .slice(0, 3);
      try {
        const [gRes, cnRes] = await Promise.all([
          getPackList({ server: 'global' }),
          getPackList({ server: 'cn' }),
        ]);
        const g = top3(Array.isArray(gRes?.items) ? gRes.items : []);
        const cn = top3(Array.isArray(cnRes?.items) ? cnRes.items : []);
        const mixed: { pack: Pack; server: 'global' | 'cn' }[] = [];
        for (let i = 0; i < 3; i++) {
          if (g[i]) mixed.push({ pack: g[i], server: 'global' });
          if (cn[i]) mixed.push({ pack: cn[i], server: 'cn' });
        }
        setEventPacks(mixed);
      } catch {
        setEventPacks([]);
      }
    })();
  }, [isList]);

  useEffect(() => {
    const urlNationality = searchParams.get('nationality');
    const urlClub = searchParams.get('club');
    const urlLeague = searchParams.get('league');
    const urlKeyword = searchParams.get('keyword');
    const urlHideStd = searchParams.get('excludeStandard');
    if (!urlNationality && !urlClub && !urlLeague && !urlKeyword && !urlHideStd) return;

    const newFilters = { ...initialFilters };
    let hasChanges = false;
    if (urlNationality) {
      newFilters.nationality = urlNationality;
      hasChanges = true;
    }
    if (urlClub) {
      newFilters.club = urlClub;
      hasChanges = true;
    }
    if (urlLeague) {
      newFilters.league = urlLeague;
      hasChanges = true;
    }
    if (hasChanges) {
      setFilters(newFilters);
    }
    if (urlKeyword) {
      setKeyword(urlKeyword);
    }
    if (urlHideStd === 'true') {
      setHideStandard(true);
    } else if (urlHideStd === 'false') {
      setHideStandard(false);
    }
  }, [searchParams, initialFilters]);

  // 挂载时恢复上次的筛选/关键字/排序/页码（如从球员详情按返回回到本页）。
  // URL 参数（从详情点国籍/俱乐部跳转）优先级更高，此时不恢复会话。
  const sessionRestoredRef = useRef(false);
  useEffect(() => {
    if (sessionRestoredRef.current) return;
    sessionRestoredRef.current = true;
    const hasUrlParams = ['nationality', 'club', 'league', 'keyword', 'excludeStandard']
      .some((k) => searchParams.get(k) != null);
    if (hasUrlParams || !savedState) return;
    if (savedState.filters) setFilters({ ...initialFilters, ...savedState.filters });
    if (typeof savedState.keyword === 'string') setKeyword(savedState.keyword);
    if (savedState.sortPreset) setSortPreset(savedState.sortPreset);
    if (savedState.page) setPage(savedState.page);
  }, [savedState, searchParams, initialFilters]);

  useEffect(() => {
    if (isList || debouncedKeyword || hasActiveFilters(filters)) {
      fetchPlayers();
    } else {
      setIsSearchMode(false);
      setSearchPlayers([]);
      setAllPlayers([]);
      setTotalPlayers(0);
    }
  }, [fetchPlayers, isList, debouncedKeyword, filters, hideStandard, page, sortPreset]);

  useEffect(() => {
    if (loading) return;
    const savedScroll = savedState?.scrollTop;
    if (savedScroll != null && savedScroll > 0) {
      const restoreTimer = window.requestAnimationFrame(() => {
        window.scrollTo(0, savedScroll);
      });
      return () => window.cancelAnimationFrame(restoreTimer);
    }
  }, [loading, savedState]);

  useEffect(() => {
    const saveState = () => {
      try {
        sessionStorage.setItem(
          STORAGE_KEY,
          JSON.stringify({
            keyword,
            filters,
            sortPreset,
            page,
            scrollTop: window.scrollY,
          }),
        );
      } catch {
        // ignore storage errors
      }
    };
    window.addEventListener('beforeunload', saveState);
    window.addEventListener('pagehide', saveState);
    return () => {
      saveState();
      window.removeEventListener('beforeunload', saveState);
      window.removeEventListener('pagehide', saveState);
    };
  }, [keyword, filters, sortPreset, page]);

  // 高级筛选弹窗中国家队选项来自全量接口数据
  const filterOptions = useMemo(() => ({
    nationalities: nationalityList,
    clubs: [] as string[],
  }), [nationalityList]);

  const hasFilters = useMemo(
    () => hasActiveFilters(filters),
    [filters],
  );

  useEffect(() => {
    setPage(1);
    setAllPlayers([]);
  }, [filters, sortPreset, debouncedKeyword, hideStandard]);

  const resetFilters = () => {
    setKeyword('');
    setDebouncedKeyword('');
    setFilters({
      positions: [],
      attackStyles: [],
      defenseStyles: [],
      aiStyles: [],
      nationality: '',
      club: '',
      commonSkills: [],
      stSkills: [],
      preferredFoot: '',
      weakFootFreq: '',
      weakFootAcc: '',
      formConsistency: '',
      playerTypes: [],
      league: '',
      teamSeasons: [],
      overallMin: '',
      overallMax: '',
      ageMin: '',
      ageMax: '',
      heightMin: '',
      heightMax: '',
      weightMin: '',
      weightMax: '',
      radarMins: {},
    });
    setSortPreset('overall-desc');
    setPage(1);
    try {
      sessionStorage.removeItem(STORAGE_KEY);
    } catch {
      // ignore
    }
  };

  // 导航优先：点主导航大标签（含已在本页时点“球员”）会产生新的 location.key，
  // 自动退出筛选/搜索，回到该栏默认内容，而不是停留在筛选结果
  const navKeyRef = useRef<string | null>(location.key);
  useEffect(() => {
    if (navKeyRef.current === location.key) return;
    navKeyRef.current = location.key;
    resetFilters();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.key]);

  const activeFilterCount = useMemo(() => {
    let count = 0;
    count += filters.positions.length;
    count += filters.attackStyles.length;
    count += filters.defenseStyles.length;
    if (filters.nationality) count += 1;
    if (filters.club) count += 1;
    count += filters.commonSkills.length;
    count += filters.stSkills.length;
    if (filters.preferredFoot) count += 1;
    if (filters.weakFootFreq) count += 1;
    if (filters.weakFootAcc) count += 1;
    if (filters.formConsistency) count += 1;
    count += filters.playerTypes.length;
    if (filters.league) count += 1;
    count += filters.teamSeasons.length;
    if (filters.overallMin || filters.overallMax) count += 1;
    if (filters.ageMin || filters.ageMax) count += 1;
    if (filters.heightMin || filters.heightMax) count += 1;
    if (filters.weightMin || filters.weightMax) count += 1;
    return count;
  }, [filters]);

  const total = totalPlayers;
  const hasMore = allPlayers.length < total;

  const { sentinelRef, loading: sentinelLoading } = useInfiniteScroll({
    hasMore,
    loadMore: () => {
      if (hasMore && !loading) {
        setPage((p) => p + 1);
      }
    },
  });

  const handleCardClick = (id: string) => {
    navigate(`/player/${id}`);
  };

  // 单行横滑行：卡片宽度与原网格单元格一致（横屏 8 个/行、竖屏 5 个/行），
  // 只改外层容器为横向滚动，PlayerCard 内部图片尺寸不变。
  const railItemCls =
    'shrink-0 snap-start landscape:w-[calc(12.5%-7px)] portrait:w-[calc(20%-6.4px)]';
  const renderRail = (
    list: Array<{ id: string }>,
    loading: boolean,
    skeletonCount: number,
  ) => {
    if (loading) {
      return (
        <div className="flex gap-2 overflow-hidden pb-2">
          {Array.from({ length: skeletonCount }).map((_, i) => (
            <div
              key={i}
              className={`${railItemCls} aspect-[3/4] animate-pulse rounded-xl bg-white/5`}
            />
          ))}
        </div>
      );
    }
    if (!list.length) {
      return (
        <div className="flex min-h-[120px] items-center justify-center rounded-xl border border-dashed border-white/10 bg-card/30 text-sm text-gray-500">
          暂无数据
        </div>
      );
    }
    return (
      <div className="rail-scroll flex snap-x gap-2 overflow-x-auto pb-2">
        {list.map((p) => (
          <div key={p.id} className={railItemCls}>
            <PlayerCard
              player={p as PlayerListItem}
              onClick={() => handleCardClick(p.id)}
            />
          </div>
        ))}
      </div>
    );
  };

  // 分组网格（球员页，与正式页一致）：每组多行、整页纵向滚动，无横滑
  const renderGroupGrid = (
    list: Array<{ id: string }>,
    isLoading: boolean,
    skeletonCount: number,
  ) => {
    if (isLoading) {
      return (
        <div className={gridCls}>
          {Array.from({ length: skeletonCount }).map((_, i) => (
            <div
              key={i}
              className="aspect-[3/4] animate-pulse rounded-xl bg-white/5"
            />
          ))}
        </div>
      );
    }
    if (!list.length) {
      return (
        <div className="flex min-h-[120px] items-center justify-center rounded-xl border border-dashed border-white/10 bg-card/30 text-sm text-gray-500">
          暂无数据
        </div>
      );
    }
    return (
      <div className={gridCls}>
        {list.map((p) => (
          <PlayerCard
            key={p.id}
            player={p as PlayerListItem}
            onClick={() => handleCardClick(p.id)}
          />
        ))}
      </div>
    );
  };

  // 首页“最新资讯 + 热门帖子”方块数据
  interface HomeBlock {
    key: string;
    img?: string;
    title: string;
    likes?: number;
    to: string;
  }
  const homeBlocks: HomeBlock[] = [];
  homeNews.forEach((n) => {
    homeBlocks.push({
      key: `n-${n.id}`,
      img: n.imageUrls[0],
      title: n.title,
      to: `/news/${n.id}`,
    });
  });
  hotPosts.forEach((p) => {
    homeBlocks.push({
      key: `p-${p.id}`,
      img: p.mediaUrls?.[0]?.url,
      title: p.title || p.content,
      likes: p.likeCount,
      to: `/forum/${p.id}`,
    });
  });

  return (
    <div className="space-y-3">
      <div className="rounded-xl border border-white/10 bg-card/80 p-3 backdrop-blur-sm space-y-3">
        <div className="flex flex-row items-center gap-2">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 h-5 w-5 -translate-y-1/2 text-gray-500" />
            <Input
              type="text"
              placeholder={t('players.searchPlaceholder')}
              value={keyword}
              onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                setKeyword(e.target.value)
              }
               className="h-12 pl-11 border-white/10 bg-[#141838] text-base text-white placeholder:text-gray-500 focus-visible:border-cyan-400/70 focus-visible:ring-cyan-400/20"
            />
            {keyword && (
              <button
                onClick={() => setKeyword('')}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-500 hover:text-white"
              >
                <X className="h-5 w-5" />
              </button>
            )}
          </div>

             <AdvancedFilterDialog
               filters={filters}
               nationalities={filterOptions.nationalities}
               clubs={filterOptions.clubs}
               playerTypes={playerTypeList}
               defensiveStyles={defensiveStyleList}
               onApply={(f) => {
                setFilters(f);
                setPage(1);
              }}
             onReset={resetFilters}
             activeCount={activeFilterCount}
              trigger={
                <Button
                   variant="outline"
                   className="h-11 px-6 border-cyan-400/50 bg-gradient-to-r from-cyan-500/20 to-blue-600/20 text-cyan-100 hover:from-cyan-400/30 hover:to-blue-500/30 hover:text-white font-bold text-lg shadow-[0_0_20px_rgba(34_211_238_0.25)] ring-1 ring-cyan-400/30"
                 >
                   <Filter className="mr-2 h-5 w-5" />
                   {t('players.advanced')}
                 {activeFilterCount > 0 && (
                   <span className="ml-1.5 inline-flex items-center justify-center min-w-[22px] h-5.5 px-1.5 rounded-full bg-gradient-to-r from-amber-400 to-orange-400 text-[#0f1430] text-xs font-bold">
                     {activeFilterCount}
                   </span>
                 )}
               </Button>
             }
          />

             <Select value={sortPreset} onValueChange={setSortPreset}>
             <SelectTrigger className="h-12 w-44 border-white/10 bg-[#141838] text-base text-white">
               <SelectValue placeholder="排序方式" />
             </SelectTrigger>
             <SelectContent className="border-white/10 bg-[#141838] text-white">
               {SORT_PRESET_OPTIONS.map((opt) => (
                 <SelectItem
                   key={opt.key}
                   value={opt.key}
                   className="focus:bg-cyan-400/15 focus:text-white data-[state=checked]:text-cyan-400"
                 >
                   {trTerm(opt.label)}
                 </SelectItem>
               ))}
             </SelectContent>
           </Select>

           <button
             onClick={() => setHideStandard(!hideStandard)}
             className={`flex items-center gap-2 h-12 px-4 rounded-md border text-sm font-semibold transition-all ${
               hideStandard
                 ? 'bg-amber-500/20 text-amber-200 border-amber-400/50 shadow-[0_0_12px_rgba(251_191_36_0.25)]'
                 : 'bg-[#141838] text-gray-300 border-white/10 hover:border-white/20'
             }`}
           >
             <span className={`w-4 h-4 rounded-full border-2 flex items-center justify-center transition-all ${
               hideStandard
                 ? 'border-amber-300 bg-amber-400'
                 : 'border-gray-500 bg-transparent'
             }`}>
               {hideStandard && <span className="w-2 h-2 rounded-full bg-white" />}
             </span>
             <span>{t('players.hideStandard')}</span>
           </button>
        </div>

        {hasFilters && (
           <ActiveFilterBadges
             filters={filters}
             onRemovePosition={(p) =>
               setFilters({
                 ...filters,
                 positions: filters.positions.filter((v: string) => v !== p),
               })
             }
             onRemoveAttackStyle={(s) =>
               setFilters({
                 ...filters,
                 attackStyles: filters.attackStyles.filter((v: string) => v !== s),
               })
             }
              onRemoveDefenseStyle={(s) =>
                setFilters({
                  ...filters,
                  defenseStyles: filters.defenseStyles.filter((v: string) => v !== s),
                })
              }
              onRemoveAiStyle={(s) =>
                setFilters({
                  ...filters,
                  aiStyles: filters.aiStyles.filter((v: string) => v !== s),
                })
              }
              onRemoveNationality={() =>
               setFilters({ ...filters, nationality: '' })
             }
             onClearClub={() => setFilters({ ...filters, club: '' })}
             onRemoveCommonSkill={(s) =>
               setFilters({
                 ...filters,
                 commonSkills: filters.commonSkills.filter((v: string) => v !== s),
               })
             }
             onRemoveStSkill={(s) =>
               setFilters({
                 ...filters,
                stSkills: filters.stSkills.filter((v: string) => v !== s),
                })
              }
              onClearPreferredFoot={() =>
                setFilters({ ...filters, preferredFoot: '' })
              }
              onClearWeakFootFreq={() =>
               setFilters({ ...filters, weakFootFreq: '' })
             }
             onClearWeakFootAcc={() =>
               setFilters({ ...filters, weakFootAcc: '' })
             }
             onClearFormConsistency={() =>
               setFilters({ ...filters, formConsistency: '' })
             }
               onClearPlayerType={() =>
                 setFilters({ ...filters, playerTypes: [] })
               }
              onRemovePlayerType={(t) =>
                setFilters({
                  ...filters,
                  playerTypes: filters.playerTypes.filter((v: string) => v !== t),
                })
              }
             onClearLeague={() => setFilters({ ...filters, league: '' })}
             onRemoveTeam={(t) =>
               setFilters({
                 ...filters,
                 teamSeasons: filters.teamSeasons.filter((v: string) => v !== t),
               })
             }
             onClearOverall={() =>
               setFilters({ ...filters, overallMin: '', overallMax: '' })
             }
             onClearAge={() =>
               setFilters({ ...filters, ageMin: '', ageMax: '' })
             }
             onClearHeight={() =>
               setFilters({ ...filters, heightMin: '', heightMax: '' })
             }
             onClearWeight={() =>
               setFilters({ ...filters, weightMin: '', weightMax: '' })
             }
             onClearRadar={(key) =>
               setFilters({
                 ...filters,
                 radarMins: { ...filters.radarMins, [key]: '' },
               })
             }
           />
        )}
      </div>

        {isSearchMode ? (
        <>
          {allPlayers.length === 0 && loading ? (
             <div className={`${gridCls}`}>
               {Array.from({ length: 20 }).map((_, i: number) => (
                 <div key={i} className="aspect-[3/4] animate-pulse rounded-xl bg-white/5" />
               ))}
             </div>
           ) : allPlayers.length === 0 ? (
             <div className="flex min-h-[400px] flex-col items-center justify-center rounded-xl border border-dashed border-white/10 bg-card/30">
               <Users className="mb-3 h-12 w-12 text-gray-600" />
               <p className="text-gray-400">没有找到匹配的球员</p>
               <p className="mt-1 text-xs text-gray-600">
                 试试调整筛选条件或搜索关键词
               </p>
             </div>
           ) : (
             <>
               <div
                 className={`${gridCls}`}
                 data-ai-section-type="card-list"
               >
                  {allPlayers.map((player: PlayerListItem) => (
                   <PlayerCard
                     key={player.id}
                     player={player}
                     onClick={() => handleCardClick(player.id)}
                   />
                 ))}
               </div>
               <div ref={sentinelRef} />
               <InfiniteScrollFooter
                 loading={sentinelLoading || (loading && allPlayers.length > 0)}
                 hasMore={hasMore}
                 hasItems={allPlayers.length > 0}
               />
             </>
           )}
         </>
        ) : isList ? (
        <div className="space-y-5">
          {/* 热门球员：分组网格（与正式页一致，多行、整页纵向滚动） */}
          <section className="space-y-2">
            <div className="flex items-center gap-2">
              <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-orange-500 to-red-500 shadow-[0_0_12px_rgba(249_115_22_0.5)]">
                <Flame className="h-4 w-4 text-white" />
              </div>
              <h2 className="text-2xl font-bold text-white">{t('players.hot')}</h2>
            </div>
            {renderGroupGrid(hotPlayers, hotLoading, 10)}
          </section>

          {/* 最新史诗·BT：分组网格 */}
          <section className="space-y-2">
            <div className="flex items-center gap-2">
              <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-purple-500 to-pink-500 shadow-[0_0_12px_rgba(168_85_247_0.5)]">
                <Crown className="h-4 w-4 text-white" />
              </div>
              <h2 className="text-2xl font-bold text-white">{t('players.latestEpic')}</h2>
            </div>
            {renderGroupGrid(latestGrouped.epicBt, latestLoading, 10)}
          </section>

          {/* 最新 ST：分组网格 */}
          <section className="space-y-2">
            <div className="flex items-center gap-2">
              <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-amber-500 to-orange-500 shadow-[0_0_12px_rgba(245_158_11_0.5)]">
                <Zap className="h-4 w-4 text-white" />
              </div>
              <h2 className="text-2xl font-bold text-white">{t('players.latestST')}</h2>
            </div>
            {renderGroupGrid(latestGrouped.st, latestLoading, 10)}
          </section>

          {/* 最新精选：分组网格 */}
          <section className="space-y-2">
            <div className="flex items-center gap-2">
              <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-cyan-500 to-blue-500 shadow-[0_0_12px_rgba(34_211_238_0.5)]">
                <Star className="h-4 w-4 text-white" />
              </div>
              <h2 className="text-2xl font-bold text-white">{t('players.latestSelected')}</h2>
            </div>
            {renderGroupGrid(latestGrouped.featuredLegend, latestLoading, 10)}
          </section>
        </div>
        ) : (
        <div className="space-y-5">
          {/* 热门球员：单行横滑（卡片图片尺寸不变） */}
          <section className="space-y-2">
            <div className="flex items-center gap-2">
              <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-orange-500 to-red-500 shadow-[0_0_12px_rgba(249_115_22_0.5)]">
                <Flame className="h-4 w-4 text-white" />
              </div>
              <h2 className="text-2xl font-bold text-white">{t('players.hot')}</h2>
            </div>
            {renderRail(hotPlayers, hotLoading, 8)}
          </section>

          {/* 最新热讯（资讯 + >50赞热帖）：单行横滑、封面 cover 撑满、整卡可点入全文 */}
          {homeBlocks.length > 0 && (
            <section className="space-y-2">
              <div className="flex items-center gap-2">
                <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-cyan-500 to-blue-600 shadow-[0_0_12px_rgba(34_211_238_0.5)]">
                  <Newspaper className="h-4 w-4 text-white" />
                </div>
                <h2 className="text-2xl font-bold text-white">最新热讯</h2>
              </div>
              <div className="rail-scroll flex snap-x gap-3 overflow-x-auto pb-2">
                {homeBlocks.map((b) => (
                  <div
                    key={b.key}
                    onClick={() => navigate(b.to)}
                    className="shrink-0 snap-start cursor-pointer overflow-hidden rounded-2xl border border-white/10 bg-[#141838]/60 transition hover:border-cyan-400/50 portrait:w-[calc(33.333%-8px)] landscape:w-[calc(16.667%-10px)]"
                  >
                    <div className="relative aspect-[4/3] w-full overflow-hidden bg-black/30">
                      {b.img ? (
                        <img src={b.img} alt="" loading="lazy" className="h-full w-full object-cover" />
                      ) : (
                        <div className="flex h-full w-full items-center justify-center">
                          <Newspaper className="h-7 w-7 text-white/20" />
                        </div>
                      )}
                      {b.likes != null && (
                        <span className="absolute right-1.5 top-1.5 flex items-center gap-0.5 rounded-full bg-black/60 px-1.5 py-0.5 text-[10px] font-bold text-rose-300">
                          <Heart className="h-2.5 w-2.5" />
                          {b.likes}
                        </span>
                      )}
                    </div>
                    <div className="p-2">
                      <h3 className="line-clamp-2 text-center text-base portrait:text-2xl font-semibold leading-snug text-white">
                        {b.title}
                      </h3>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          )}

          {/* 活动包：国际服/国服各 3，每行 2 个、共 3 行；包名 + 同款 5 扇形 */}
          {eventPacks.length > 0 && (
            <section className="space-y-2">
              <div className="flex items-center gap-2">
                <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-fuchsia-500 to-purple-600 shadow-[0_0_12px_rgba(217_70_239_0.5)]">
                  <Gift className="h-4 w-4 text-white" />
                </div>
                <h2 className="text-2xl font-bold text-white">最新活动包</h2>
              </div>
              <div className="grid grid-cols-2 gap-3">
                {eventPacks.map(({ pack, server }) => {
                  const packName =
                    pack.originalName || pack.enName || pack.cnName || pack.menuName || pack.packType || '';
                  // 背景照搬卡包卡片：按包类型取同款渐变
                  const { gradient } = getPackTypeInfo(pack);
                  return (
                    <div
                      key={`${server}-${pack.id}`}
                      onClick={() => navigate(`/pack/${pack.id}`)}
                      className="flex cursor-pointer flex-col overflow-hidden rounded-2xl border border-white/10 transition hover:-translate-y-0.5 hover:border-white/30 hover:shadow-[0_6px_20px_rgba(0,0,0,0.35)]"
                    >
                      {/* 与卡包卡片一致：类型渐变底 + 黑色遮罩 */}
                      <div className={`relative flex flex-1 flex-col bg-gradient-to-br ${gradient}`}>
                        <div className="absolute inset-0 bg-black/40" />
                        <div className="relative flex flex-1 flex-col p-3">
                          <div className="mb-1 flex items-center justify-between gap-1.5">
                            <div className="flex min-w-0 items-center gap-1.5">
                              <span
                                className={`shrink-0 rounded-full px-3 py-1 text-lg font-bold ${
                                  server === 'cn'
                                    ? 'bg-rose-500/25 text-rose-100'
                                    : 'bg-cyan-500/25 text-cyan-100'
                                }`}
                              >
                                {server === 'cn' ? '国服' : '国际服'}
                              </span>
                              {pack.cnDate && (
                                <span className="truncate text-sm font-medium text-white/70">
                                  {formatPackDateDisplay(pack.cnDate, lang)}
                                </span>
                              )}
                            </div>
                            {pack.playerCount != null && (
                              <span className="flex shrink-0 items-center gap-1 text-lg font-bold text-white">
                                <Users className="h-5 w-5" />
                                {pack.playerCount}
                              </span>
                            )}
                          </div>
                          <h3 className="mb-1 line-clamp-2 text-center text-xl portrait:text-3xl md:text-3xl font-bold leading-snug text-white">
                            {packName}
                          </h3>
                          <div className="mt-auto flex items-center">
                            <PackCardFan cards={pack.topCards} height={108} />
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          )}

          {/* 最新史诗·BT：单行横滑 */}
          <section className="space-y-2">
            <div className="flex items-center gap-2">
              <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-purple-500 to-pink-500 shadow-[0_0_12px_rgba(168_85_247_0.5)]">
                <Crown className="h-4 w-4 text-white" />
              </div>
              <h2 className="text-2xl font-bold text-white">{t('players.latestEpic')}</h2>
            </div>
            {renderRail(latestGrouped.epicBt, latestLoading, 8)}
          </section>

          {/* 最新 ST：单行横滑 */}
          <section className="space-y-2">
            <div className="flex items-center gap-2">
              <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-amber-500 to-orange-500 shadow-[0_0_12px_rgba(245_158_11_0.5)]">
                <Zap className="h-4 w-4 text-white" />
              </div>
              <h2 className="text-2xl font-bold text-white">{t('players.latestST')}</h2>
            </div>
            {renderRail(latestGrouped.st, latestLoading, 8)}
          </section>

          {/* 最新精选：单行横滑 */}
          <section className="space-y-2">
            <div className="flex items-center gap-2">
              <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-cyan-500 to-blue-500 shadow-[0_0_12px_rgba(34_211_238_0.5)]">
                <Star className="h-4 w-4 text-white" />
              </div>
              <h2 className="text-2xl font-bold text-white">{t('players.latestSelected')}</h2>
            </div>
            {renderRail(latestGrouped.featuredLegend, latestLoading, 8)}
          </section>
        </div>
      )}
    </div>
  );
};

export default PlayersPage;
