function newsAuthHeaders(): Record<string, string> {
  const token = getToken();
  return token ? { Authorization: `Bearer ${token}` } : {};
}

// 后端图片地址补全：APP 源 https://localhost，接口给的根相对路径（/uploads/...）
// 在 APP 内会被解析到设备本地而 404；统一补成后端绝对地址。
// 打包进 APP 的本地资源（brand/...，不以 / 开头）保持原样。
export function resolveBackendAsset(url: string): string {
  if (!url) return url;
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith('data:') || url.startsWith('blob:') || url.startsWith('//'))
    return url;
  if (!url.startsWith('/')) return url; // 相对本地资源（./brand/...）
  const apiBase = String(
    (window as unknown as { RUNTIME_CONFIG?: { API_BASE_URL?: string } })
      .RUNTIME_CONFIG?.API_BASE_URL || 'https://playtostar.com',
  ).replace(/\/+$/, '');
  return apiBase + url;
}

function normalizeNewsArticle(a: NewsArticle): NewsArticle {
  if (!a) return a;
  return { ...a, imageUrls: (a.imageUrls || []).map(resolveBackendAsset) };
}

