function applyMockFilters(
  items: NewsArticle[],
  query: NewsListQuery,
): NewsListResponse {
  const page = query.page || 1;
  const pageSize = query.pageSize || 10;
  let filtered = items;
  if (query.platform) {
    filtered = filtered.filter((a) => a.platform === query.platform);
  }
  if (query.keyword) {
    const kw = query.keyword.toLowerCase();
    filtered = filtered.filter(
      (a) =>
        a.title.toLowerCase().includes(kw) ||
        a.summary.toLowerCase().includes(kw) ||
        a.author.toLowerCase().includes(kw),
    );
  }
  const total = filtered.length;
  const start = (page - 1) * pageSize;
  return {
    items: filtered.slice(start, start + pageSize),
    total,
    page,
    pageSize,
  };
}

export async function getNewsList(
  query: NewsListQuery = {},
): Promise<NewsListResponse> {
  try {
    const res = await axiosForBackend.get('/api/news', { params: query });
    const d = res.data as NewsListResponse;
    // 前端再排一次（双保险）：置顶优先（置顶间按置顶时间倒序），其余按【上传/入库时间 publishedAt】倒序
    const timeKey = (a: NewsArticle): string =>
      a.publishedAt || a.postedAt || '';
    const items = (d.items || [])
      .map(normalizeNewsArticle)
      .sort((a, b) => {
        if (!!a.isPinned !== !!b.isPinned) return a.isPinned ? -1 : 1;
        if (a.isPinned && b.isPinned)
          return (b.pinnedAt || '').localeCompare(a.pinnedAt || '');
        return timeKey(b).localeCompare(timeKey(a));
      });
    return { ...d, items };
  } catch {
    // 后端资讯接口尚未部署：回退 mock
    return applyMockFilters(MOCK_ARTICLES, query);
  }
}

export async function getNewsDetail(id: string): Promise<NewsArticle | null> {
  try {
    const res = await axiosForBackend.get(`/api/news/${id}`);
    return normalizeNewsArticle(res.data as NewsArticle);
  } catch {
    return MOCK_ARTICLES.find((a) => a.id === id) ?? null;
  }
}

// 管理员编辑热讯（PATCH）；失败直接抛出，由页面提示
export async function updateNews(
  id: string,
  dto: NewsUpdateRequest,
): Promise<NewsArticle> {
  const res = await axiosForBackend.patch<NewsArticle>(
    `/api/news/${id}`,
    dto,
    { headers: newsAuthHeaders() },
  );
  return normalizeNewsArticle(res.data);
}

// 管理员删除热讯（DELETE）
export async function deleteNews(
  id: string,
): Promise<{ success: boolean; deleted: number }> {
  const res = await axiosForBackend.delete<{
    success: boolean;
    deleted: number;
  }>(`/api/news/${id}`, { headers: newsAuthHeaders() });
  return res.data;
}

