import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Search, X, Check, Filter as FilterIcon } from 'lucide-react';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogTrigger,
} from '@client/src/components/ui/dialog';
import { Button } from '@client/src/components/ui/button';
import { getFormConsistencyLabel } from '@client/src/utils/form-consistency';
import { Input } from '@client/src/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@client/src/components/ui/select';
import {
  POSITION_LABEL_MAP,
  ATTACK_STYLES,
  AI_STYLES,
  COMMON_SKILLS,
  ST_SKILLS,
  PREFERRED_FOOT_OPTIONS,
  WEAK_FOOT_OPTIONS,
  sortOptions,
  getPlayerTypeLabel,
  type PlayerFilterState,
} from './player-utils';

interface AdvancedFilterDialogProps {
  filters: PlayerFilterState;
  nationalities: string[];
  clubs: string[];
  playerTypes: string[];
  defensiveStyles: string[];
  onApply: (filters: PlayerFilterState) => void;
  onReset: () => void;
  activeCount: number;
  trigger: React.ReactNode;
}

interface SearchMultiSelectProps {
  label: string;
  options: string[];
  selected: string[];
  onChange: (values: string[]) => void;
  placeholder?: string;
}

const SearchMultiSelect: React.FC<SearchMultiSelectProps> = ({
  label,
  options,
  selected,
  onChange,
  placeholder,
}) => {
  const { t } = useI18n();
  const [open, setOpen] = useState(false);
  const [keyword, setKeyword] = useState('');
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node))
        setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const sortedOptions = useMemo(() => sortOptions(options), [options]);

  const filtered = useMemo(() => {
    if (!keyword) return sortedOptions;
    const lower = keyword.toLowerCase();
    return sortedOptions.filter((o: string) =>
      o.toLowerCase().includes(lower) ||
      trTerm(o).toLowerCase().includes(lower),
    );
  }, [sortedOptions, keyword]);

  const toggle = (val: string) => {
    if (selected.includes(val))
      onChange(selected.filter((v: string) => v !== val));
    else onChange([...selected, val]);
  };

  return (
    <div className="space-y-1.5">
      <label className="text-xs font-medium text-gray-400">{label}</label>
      <div ref={ref} className="relative">
        <button
          type="button"
          onClick={() => setOpen(!open)}
          className="flex h-9 w-full items-center justify-between rounded-md border border-white/10 bg-[#141838] px-3 text-left text-sm text-white hover:border-cyan-400/50"
        >
          <span className="truncate">
            {selected.length > 0
              ? t('af.selectedN', { n: selected.length })
              : placeholder || t('players.all')}
          </span>
          <span className="text-xs text-cyan-400">
            {selected.length > 0 ? t('af.expand') : t('af.select')}
          </span>
        </button>
        {open && (
          <div className="absolute left-0 right-0 top-full z-30 mt-1 max-h-60 overflow-hidden rounded-md border border-white/10 bg-[#141838] py-1 shadow-xl">
            <div className="px-2 pb-1 border-b border-white/5">
              <div className="relative">
                <Search className="absolute left-2 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-gray-500" />
                <Input
                  value={keyword}
                  onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                    setKeyword(e.target.value)
                  }
                  placeholder={t('af.searchPh')}
                  className="h-7 pl-7 border-white/10 bg-[#0d1128] text-xs text-white placeholder:text-gray-500 focus-visible:border-cyan-400/70"
                />
              </div>
            </div>
            <div className="max-h-44 overflow-y-auto">
              {filtered.length === 0 ? (
                <div className="px-3 py-2 text-xs text-gray-500 text-center">
                  {t('af.noMatch')}
                </div>
              ) : (
                filtered.map((opt: string) => (
                  <button
                    key={opt}
                    type="button"
                    onClick={() => toggle(opt)}
                    className={`flex w-full items-center justify-between px-3 py-1.5 text-left text-xs hover:bg-cyan-400/15 ${
                      selected.includes(opt) ? 'text-cyan-300' : 'text-gray-300'
                    }`}
                  >
                    <span>{trTerm(opt)}</span>
                    {selected.includes(opt) && (
                      <Check className="h-3.5 w-3.5 text-cyan-400" />
                    )}
                  </button>
                ))
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

interface ChipsMultiSelectProps {
  label: string;
  options: string[];
  selected: string[];
  onChange: (values: string[]) => void;
  renderLabel?: (val: string) => string;
}

const ChipsMultiSelect: React.FC<ChipsMultiSelectProps> = ({
  label,
  options,
  selected,
  onChange,
  renderLabel,
}) => {
  const sorted = useMemo(() => sortOptions(options), [options]);

  const toggle = (val: string) => {
    if (selected.includes(val))
      onChange(selected.filter((v: string) => v !== val));
    else onChange([...selected, val]);
  };

  return (
    <div className="space-y-1.5">
      <label className="text-xs font-medium text-gray-400">{label}</label>
      <div className="flex flex-wrap gap-1.5">
        {sorted.map((opt: string) => {
          const active = selected.includes(opt);
          return (
            <button
              key={opt}
              type="button"
              onClick={() => toggle(opt)}
              className={`px-2.5 py-1 rounded-md text-xs font-medium border transition-colors ${
                active
                  ? 'bg-cyan-400/20 text-cyan-200 border-cyan-400/50'
                  : 'bg-white/5 text-gray-300 border-white/10 hover:border-cyan-400/40 hover:text-cyan-200'
              }`}
            >
              {renderLabel ? renderLabel(opt) : opt}
            </button>
          );
        })}
      </div>
    </div>
  );
};

interface SingleNumberSelectProps {
  label: string;
  value: string;
  onChange: (v: string) => void;
  options: string[];
}

const SingleNumberSelect: React.FC<SingleNumberSelectProps> = ({
  label,
  value,
  onChange,
  options,
}) => {
  return (
    <div className="space-y-1.5">
      <label className="text-xs font-medium text-gray-400">{label}</label>
      <div className="flex gap-1">
        {options.map((n: string) => {
          const active = value === n;
          return (
            <button
              key={n}
              type="button"
              onClick={() => onChange(active ? '' : n)}
              className={`flex-1 h-8 rounded-md text-sm font-bold border transition-colors ${
                active
                  ? 'bg-amber-400/20 text-amber-200 border-amber-400/50'
                  : 'bg-white/5 text-gray-400 border-white/10 hover:border-amber-400/40 hover:text-amber-200'
              }`}
            >
              {n}
            </button>
          );
        })}
      </div>
    </div>
  );
};

interface SingleLabeledSelectOption {
  value: string;
  label: string;
}

interface SingleLabeledSelectProps {
  label: string;
  value: string;
  onChange: (v: string) => void;
  options: SingleLabeledSelectOption[];
}

const SingleLabeledSelect: React.FC<SingleLabeledSelectProps> = ({
  label,
  value,
  onChange,
  options,
}) => {
  return (
    <div className="space-y-1.5">
      <label className="text-xs font-medium text-gray-400">{label}</label>
      <div className="flex gap-1">
        {options.map((opt: SingleLabeledSelectOption) => {
          const active = value === opt.value;
          return (
            <button
              key={opt.value}
              type="button"
              onClick={() => onChange(active ? '' : opt.value)}
              className={`flex-1 h-8 rounded-md text-sm font-bold border transition-colors ${
                active
                  ? 'bg-amber-400/20 text-amber-200 border-amber-400/50'
                  : 'bg-white/5 text-gray-400 border-white/10 hover:border-amber-400/40 hover:text-amber-200'
              }`}
            >
              {opt.label}
            </button>
          );
        })}
      </div>
    </div>
  );
};

export const AdvancedFilterDialog: React.FC<AdvancedFilterDialogProps> = ({
  filters,
  nationalities,
  clubs,
  playerTypes,
  defensiveStyles,
  onApply,
  onReset,
  activeCount,
  trigger,
}) => {
  const { t } = useI18n();
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState<PlayerFilterState>(filters);
  const [defStyleOptions, setDefStyleOptions] = useState<string[]>(defensiveStyles || []);

  useEffect(() => {
    if (defensiveStyles && defensiveStyles.length > 0) {
      setDefStyleOptions(defensiveStyles);
    }
  }, [defensiveStyles]);

  useEffect(() => {
    if (open) setDraft(filters);
  }, [open, filters]);

  const handleApply = () => {
    onApply(draft);
    setOpen(false);
  };

  const handleReset = () => {
    const reset: PlayerFilterState = {
      positions: [],
      attackStyles: [],
      defenseStyles: [],
      aiStyles: [],
      nationality: '',
      club: '',
      commonSkills: [],
      stSkills: [],
      preferredFoot: '',
      weakFootFreq: '',
      weakFootAcc: '',
      formConsistency: '',
      playerTypes: [],
      league: '',
      teamSeasons: [],
      overallMin: '',
      overallMax: '',
      ageMin: '',
      ageMax: '',
      heightMin: '',
      heightMax: '',
      weightMin: '',
      weightMax: '',
      radarMins: {},
    };
    setDraft(reset);
  };

  const positionOptions = Object.keys(POSITION_LABEL_MAP);
  const sortedClubs = useMemo(() => sortOptions(clubs), [clubs]);
  const sortedNationalities = useMemo(
    () => sortOptions(nationalities),
    [nationalities],
  );

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>{trigger}</DialogTrigger>
      <DialogContent className="max-w-3xl max-h-[85vh] flex flex-col overflow-hidden bg-[#0f1430] border-white/10 p-0">
        <DialogHeader className="px-6 py-4 border-b border-white/10">
          <DialogTitle className="text-lg font-bold text-white">
            {t('players.advanced')}
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 px-6 py-4 overflow-y-auto space-y-5 min-h-0">
          <ChipsMultiSelect
            label={t('af.registeredPos')}
            options={positionOptions}
            selected={draft.positions}
            onChange={(v: string[]) => setDraft({ ...draft, positions: v })}
            renderLabel={(val: string) =>
              POSITION_LABEL_MAP[val]
                ? `${val} - ${trTerm(POSITION_LABEL_MAP[val])}`
                : val
            }
          />

          <div className="grid grid-cols-2 gap-4">
            <SearchMultiSelect
              label={t('af.attackStyle')}
              options={ATTACK_STYLES}
              selected={draft.attackStyles}
              onChange={(v: string[]) =>
                setDraft({ ...draft, attackStyles: v })
              }
              placeholder={t('af.allAttack')}
            />
            <SearchMultiSelect
              label={t('af.defenseStyle')}
              options={defStyleOptions}
              selected={draft.defenseStyles}
              onChange={(v: string[]) =>
                setDraft({ ...draft, defenseStyles: v })
              }
              placeholder={t('af.allDefense')}
            />
          </div>

          <SearchMultiSelect
            label={t('af.aiStyle')}
            options={AI_STYLES}
            selected={draft.aiStyles}
            onChange={(v: string[]) => setDraft({ ...draft, aiStyles: v })}
            placeholder={t('af.allAi')}
          />

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-gray-400">
                {t('af.nationalTeam')}
              </label>
              <Select
                value={draft.nationality || '__all__'}
                onValueChange={(v: string) =>
                  setDraft({
                    ...draft,
                    nationality: v === '__all__' ? '' : v,
                  })
                }
              >
                <SelectTrigger className="h-9 border-white/10 bg-[#141838] text-sm text-white">
                  <SelectValue placeholder={t('af.allNat')} />
                </SelectTrigger>
                <SelectContent className="z-[120] border-white/10 bg-[#141838] text-white max-h-60">
                  <SelectItem value="__all__" className="focus:bg-cyan-400/15">
                    {t('af.allNat')}
                  </SelectItem>
                  {sortedNationalities.map((n: string) => (
                    <SelectItem
                      key={n}
                      value={n}
                      className="focus:bg-cyan-400/15 focus:text-white data-[state=checked]:text-cyan-400"
                    >
                      {trTerm(n)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-medium text-gray-400">
                {t('common.club')}
              </label>
              <Select
                value={draft.club || '__all__'}
                onValueChange={(v: string) =>
                  setDraft({ ...draft, club: v === '__all__' ? '' : v })
                }
              >
                <SelectTrigger className="h-9 border-white/10 bg-[#141838] text-sm text-white">
                  <SelectValue placeholder={t('af.allClub')} />
                </SelectTrigger>
                <SelectContent className="z-[120] border-white/10 bg-[#141838] text-white max-h-60">
                  <SelectItem value="__all__" className="focus:bg-cyan-400/15">
                    {t('af.allClub')}
                  </SelectItem>
                  {sortedClubs.map((c: string) => (
                    <SelectItem
                      key={c}
                      value={c}
                      className="focus:bg-cyan-400/15 focus:text-white data-[state=checked]:text-cyan-400"
                    >
                      {c}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <SearchMultiSelect
            label={t('af.commonSkill')}
            options={COMMON_SKILLS}
            selected={draft.commonSkills}
            onChange={(v: string[]) =>
              setDraft({ ...draft, commonSkills: v })
            }
            placeholder={t('af.pickCommon')}
          />

          <SearchMultiSelect
            label={t('af.stSkill')}
            options={ST_SKILLS}
            selected={draft.stSkills}
            onChange={(v: string[]) => setDraft({ ...draft, stSkills: v })}
            placeholder={t('af.pickSt')}
          />

           <ChipsMultiSelect
             label={t('af.playerType')}
             options={playerTypes}
             selected={draft.playerTypes}
             onChange={(v: string[]) => setDraft({ ...draft, playerTypes: v })}
             renderLabel={(val: string) => trTerm(getPlayerTypeLabel(val))}
           />

           <div className="space-y-1.5">
             <label className="text-xs font-medium text-gray-400">{t('af.preferredFoot')}</label>
            <div className="flex gap-2">
              {PREFERRED_FOOT_OPTIONS.map((f: string) => {
                const active = draft.preferredFoot === f;
                return (
                  <button
                    key={f}
                    type="button"
                    onClick={() =>
                      setDraft({ ...draft, preferredFoot: active ? '' : f })
                    }
                    className={`flex-1 h-9 rounded-md text-sm font-semibold border transition-colors ${
                      active
                        ? 'bg-cyan-400/20 text-cyan-200 border-cyan-400/50'
                        : 'bg-white/5 text-gray-300 border-white/10 hover:border-cyan-400/40 hover:text-cyan-200'
                    }`}
                  >
                    {trTerm(f)}
                  </button>
                );
              })}
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <SingleNumberSelect
              label={t('common.weakFreq')}
              value={draft.weakFootFreq}
              onChange={(v: string) =>
                setDraft({ ...draft, weakFootFreq: v })
              }
              options={WEAK_FOOT_OPTIONS}
            />
            <SingleNumberSelect
              label={t('common.weakAcc')}
              value={draft.weakFootAcc}
              onChange={(v: string) =>
                setDraft({ ...draft, weakFootAcc: v })
              }
              options={WEAK_FOOT_OPTIONS}
            />
            <SingleLabeledSelect
              label={t('af.formConsistency')}
              value={draft.formConsistency}
              onChange={(v: string) =>
                setDraft({ ...draft, formConsistency: v })
              }
              options={[
                { value: '0', label: trTerm(getFormConsistencyLabel(0)) },
                { value: '1', label: trTerm(getFormConsistencyLabel(1)) },
                { value: '2', label: trTerm(getFormConsistencyLabel(2)) },
              ]}
            />
          </div>
        </div>

        <DialogFooter className="flex-none px-6 py-3 border-t border-white/10 gap-3 bg-[#0f1430]">
          <Button
            variant="outline"
            onClick={handleReset}
            className="flex-1 border-white/10 text-gray-300 hover:bg-white/5 hover:text-white"
          >
            {t('common.reset')}
          </Button>
          <Button
            onClick={handleApply}
            className="flex-1 bg-gradient-to-r from-cyan-500 to-blue-500 text-white hover:from-cyan-400 hover:to-blue-400"
          >
            {t('af.apply')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};
