export const MAX_POINTS_PER_CATEGORY = 9999;

export function getCostForNextPoint(currentPoints: number): number {
  if (currentPoints < 4) return 1;
  if (currentPoints < 8) return 2;
  if (currentPoints < 12) return 3;
  if (currentPoints < 16) return 4;
  return 5;
}

export function getRefundForCurrentPoints(currentPoints: number): number {
  if (currentPoints <= 4) return 1;
  if (currentPoints <= 8) return 2;
  if (currentPoints <= 12) return 3;
  if (currentPoints <= 16) return 4;
  return 5;
}

export function calcAvailablePoints(
  level: number,
  allocations: Record<string, number>,
): number {
  const safeLevel = Number.isFinite(level) ? level : 0;
  const totalEarned = (safeLevel - 1) * 2;
  let totalSpent = 0;
  if (allocations) {
    for (const points of Object.values(allocations)) {
      const pts = Number.isFinite(points) ? points : 0;
      for (let i = 0; i < pts; i++) {
        totalSpent += getCostForNextPoint(i);
      }
    }
  }
  return totalEarned - totalSpent;
}

export function getRatingColorClass(rating: number): string {
  if (rating >= 90) return 'bg-[#84cc16] text-white';
  if (rating >= 80) return 'bg-[#eab308] text-white';
  if (rating >= 70) return 'bg-[#f97316] text-white';
  return 'bg-[#ef4444] text-white';
}

