export function getTotalStatsSum(
  allocations: Record<string, number>,
  baseStats: Record<string, number>,
  boostMap: Record<string, number>,
  coachBonus: Record<string, number> = {},
  styleBonus: Record<string, number> = {},
  boosterBonus: Record<string, number> = {},
  shineBonus: Record<string, number> = {},
): number {
  const pointsByAttr: Record<string, number> = {};
  if (allocations) {
    for (const cat of BUILD_CATEGORIES) {
      const points = Number(allocations[cat.key] ?? 0) || 0;
      for (const attr of cat.attributes) {
        pointsByAttr[attr.key] = (pointsByAttr[attr.key] ?? 0) + points;
      }
    }
  }
  let sum = 0;
  const safeBaseStats: Record<string, number> = baseStats || {};
  for (const [key, baseVal] of Object.entries(safeBaseStats)) {
    const base = Number(baseVal) || 0;
    const boost = Number(boostMap[key] ?? 0) || 0;
    const cBonus = Number(coachBonus[key] ?? 0) || 0;
    const bBonus = Number(boosterBonus[key] ?? 0) || 0;
    const shine = Number(shineBonus[key] ?? 0) || 0;
    const points = pointsByAttr[key] ?? 0;
    const val = base + points + shine + boost + cBonus + bBonus;
    sum += Number.isFinite(val) ? val : base;
  }
  return sum;
}
