import React from 'react';
import { Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@client/src/components/ui/dialog';
import { Button } from '@client/src/components/ui/button';

const REPORT_REASONS = ['垃圾广告', '色情低俗', '人身攻击', '违法违规', '内容不实', '其他原因'];

interface ReportDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  reason: string;
  onReasonChange: (reason: string) => void;
  submitting: boolean;
  onSubmit: () => Promise<void> | void;
}

const ReportDialog: React.FC<ReportDialogProps> = ({
  open,
  onOpenChange,
  reason,
  onReasonChange,
  submitting,
  onSubmit,
}) => {
  const handleCancel = () => {
    onOpenChange(false);
    onReasonChange('');
  };

  const handleSubmit = async () => {
    if (!reason) {
      toast.error('请选择举报原因');
      return;
    }
    await onSubmit();
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="border-white/10 bg-[#141838] text-white sm:max-w-[420px]">
        <DialogHeader>
          <DialogTitle className="text-2xl font-bold text-white">举报评论</DialogTitle>
        </DialogHeader>
        <div className="py-2">
          <p className="mb-3 text-lg text-gray-400">请选择举报原因：</p>
          <div className="space-y-2">
            {REPORT_REASONS.map((r) => (
              <button
                key={r}
                onClick={() => onReasonChange(r)}
                className={`w-full rounded-lg border px-4 py-2.5 text-left text-lg transition-all ${
                  reason === r
                    ? 'border-cyan-400/60 bg-cyan-500/15 text-cyan-200 shadow-[0_0_12px_rgba(34_211_238_0.3)]'
                    : 'border-white/10 bg-[#0A0E27] text-gray-300 hover:border-white/20'
                }`}
              >
                {r}
              </button>
            ))}
          </div>
        </div>
        <DialogFooter>
          <Button
            variant="outline"
            onClick={handleCancel}
            className="border-white/10 bg-transparent text-gray-300 hover:bg-white/5 hover:text-white"
          >
            取消
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={submitting || !reason}
            className="bg-gradient-to-r from-orange-500 to-pink-500 text-white shadow-[0_0_12px_rgba(249_115_22_0.5)] disabled:opacity-50"
          >
            {submitting && <Loader2 className="mr-1.5 h-4 w-4 animate-spin" />}
            提交举报
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default ReportDialog;
