import React, { useEffect, useState } from 'react';
import { ArrowLeft, Loader2, Newspaper } from 'lucide-react';
import { useNavigate, useParams } from 'react-router-dom';

import { getNewsList } from '@client/src/api/news';
import type { NewsArticle } from '@shared/api.interface';
import { useI18n } from '@client/src/i18n/I18nProvider';
import NewsCard from './NewsCard';

// 博主发帖页：展示该博主在“最近外显100条”内的全部发帖。
// 取最近100条 published，前端按博主显示名精确过滤（严格符合“最近100条内”窗口）。
const NewsAuthorPage: React.FC = () => {
  const { author = '' } = useParams<{ author: string }>();
  const name = decodeURIComponent(author);
  const navigate = useNavigate();
  const { t } = useI18n();
  const [items, setItems] = useState<NewsArticle[] | null>(null);

  useEffect(() => {
    let mounted = true;
    setItems(null);
    getNewsList({ pageSize: 100 })
      .then((res) => {
        if (!mounted) return;
        const key = name.trim();
        setItems(res.items.filter((a) => (a.author || '').trim() === key));
      })
      .catch(() => {
        if (mounted) setItems([]);
      });
    return () => {
      mounted = false;
    };
  }, [name]);

  const goDetail = (id: string) => navigate(`/news/${id}`);

  return (
    <div className="mx-auto max-w-4xl px-3 py-5">
      <button
        onClick={() => navigate('/news')}
        className="mb-4 flex items-center gap-1.5 text-sm text-gray-400 transition hover:text-cyan-300"
      >
        <ArrowLeft className="h-4 w-4" /> {t('news.backToList')}
      </button>

      <div className="mb-5 flex items-center gap-3">
        <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-neon-gradient text-lg font-bold text-white">
          {(name.trim().slice(0, 1) || '?').toUpperCase()}
        </div>
        <div className="min-w-0">
          <h1 className="truncate font-bold text-white landscape:text-2xl portrait:text-4xl">
            @{name}
          </h1>
          <p className="text-gray-400 landscape:text-xs portrait:text-base">
            {items === null
              ? t('加载中…')
              : `最近100条内外显 ${items.length} 条发帖`}
          </p>
        </div>
      </div>

      {items === null ? (
        <div className="flex items-center justify-center py-20">
          <Loader2 className="h-8 w-8 animate-spin text-cyan-400" />
        </div>
      ) : items.length === 0 ? (
        <div className="rounded-2xl border border-white/10 bg-[#141838]/40 p-12 text-center">
          <Newspaper className="mx-auto mb-3 h-10 w-10 text-white/25" />
          <p className="text-sm text-gray-500">该博主在最近100条内暂无发帖</p>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-3 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5">
          {items.map((a) => (
            <NewsCard key={a.id} article={a} onOpen={goDetail} />
          ))}
        </div>
      )}
    </div>
  );
};

export default NewsAuthorPage;
