import React, { useRef, useState } from 'react';
import { Camera, Loader2, User } from 'lucide-react';
import { toast } from 'sonner';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { useAuth } from '@client/src/context/AuthContext';
import { uploadMyAvatarFile } from '@client/src/api/users';
import { Button } from '@client/src/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@client/src/components/ui/dialog';

const MAX_SIZE_MB = 5;
const ALLOWED_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];

interface AvatarUploadProps {
  size?: 'sm' | 'md' | 'lg';
  showLabel?: boolean;
}

export const AvatarUpload: React.FC<AvatarUploadProps> = ({
  size = 'md',
  showLabel = true,
}) => {
  const { user, updateAvatar } = useAuth();
  const inputRef = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [pendingFile, setPendingFile] = useState<File | null>(null);
  const sizeClass = {
    sm: 'h-12 w-12',
    md: 'h-20 w-20',
    lg: 'h-24 w-24',
  }[size];

  const iconSize = {
    sm: 'h-6 w-6',
    md: 'h-10 w-10',
    lg: 'h-12 w-12',
  }[size];

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!ALLOWED_TYPES.includes(file.type)) {
      toast.error('仅支持 JPG、PNG、WebP、GIF 格式');
      return;
    }
    if (file.size > MAX_SIZE_MB * 1024 * 1024) {
      toast.error(`图片大小不能超过 ${MAX_SIZE_MB}MB`);
      return;
    }

    const reader = new FileReader();
    reader.onload = () => {
      setPreviewUrl(reader.result as string);
      setPendingFile(file);
      setConfirmOpen(true);
    };
    reader.onerror = () => {
      toast.error('读取图片失败');
    };
    reader.readAsDataURL(file);

    if (inputRef.current) inputRef.current.value = '';
  };

  const handleConfirmUpload = async () => {
    if (!pendingFile) return;
    setUploading(true);
    try {
      const result = await uploadMyAvatarFile(pendingFile);
      if (!result?.success || !result.avatarUrl) {
        throw new Error('上传失败');
      }
      // 同步本地登录态头像
      await updateAvatar(result.avatarUrl);
      toast.success('头像上传成功');
      setConfirmOpen(false);
      setPreviewUrl(null);
      setPendingFile(null);
    } catch (err: unknown) {
      logger.error('头像上传失败', err);
      const msg = err instanceof Error ? err.message : '上传失败，请稍后重试';
      toast.error(msg);
    } finally {
      setUploading(false);
    }
  };

  const handleCancel = () => {
    setConfirmOpen(false);
    setPreviewUrl(null);
    setPendingFile(null);
  };

  const avatarSrc = user?.avatarUrl || null;

  return (
    <>
      <div className="flex items-center gap-4">
        <button
          type="button"
          onClick={() => inputRef.current?.click()}
          className={`group relative ${sizeClass} flex-shrink-0 rounded-full overflow-hidden bg-neon-gradient shadow-lg box-glow-cyan transition-all hover:box-glow-pink`}
          title={avatarSrc ? '更换头像' : '上传头像'}
        >
          {avatarSrc ? (
            <img
              src={avatarSrc}
              alt="头像"
              className="h-full w-full object-cover"
            />
          ) : (
            <div className="h-full w-full flex items-center justify-center">
              <User className={`${iconSize} text-white`} />
            </div>
          )}
          <div className="absolute inset-0 flex items-center justify-center bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity">
            <Camera className="h-5 w-5 text-white" />
          </div>
        </button>

        {showLabel && (
          <div className="flex flex-col gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => inputRef.current?.click()}
              className="w-fit"
            >
              <Camera className="mr-1.5 h-4 w-4" />
              {avatarSrc ? '更换头像' : '上传头像'}
            </Button>
            <p className="text-xs text-gray-500">
              支持 JPG/PNG/WebP/GIF，最大 {MAX_SIZE_MB}MB
            </p>
          </div>
        )}
      </div>

      <input
        ref={inputRef}
        type="file"
        accept={ALLOWED_TYPES.join(',')}
        onChange={handleFileChange}
        className="hidden"
      />

      <Dialog open={confirmOpen} onOpenChange={setConfirmOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle>确认上传头像</DialogTitle>
            <DialogDescription>
              预览效果如下，确认使用这张图片作为头像？
            </DialogDescription>
          </DialogHeader>
          <div className="flex justify-center py-4">
            {previewUrl && (
              <div className="h-32 w-32 rounded-full overflow-hidden border-2 border-cyan-400/30 shadow-lg box-glow-cyan">
                <img
                  src={previewUrl}
                  alt="头像预览"
                  className="h-full w-full object-cover"
                />
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={handleCancel} disabled={uploading}>
              取消
            </Button>
            <Button onClick={handleConfirmUpload} disabled={uploading}>
              {uploading && (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              )}
              {uploading ? '上传中...' : '确认上传'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
};

export default AvatarUpload;
