import React, { useState, useEffect, useCallback, useRef } from 'react';
import {
  Bell,
  MessageSquare,
  Heart,
  UserPlus,
  AlertTriangle,
  Info,
  Award,
  Loader2,
  CheckCheck,
} from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { toast } from 'sonner';
import dayjs from 'dayjs';
import { useNavigate } from 'react-router-dom';

import {
  getNotifications,
  markAsRead,
  markAllAsRead,
} from '@client/src/api/notifications';
import type { NotificationItem } from '@shared/api.interface';
import { useAuth } from '@client/src/context/AuthContext';
import { useInfiniteScroll } from '@client/src/hooks/useInfiniteScroll';
import InfiniteScrollFooter from '@client/src/components/InfiniteScrollFooter';
import { useI18n } from '@client/src/i18n/I18nProvider';
import {
  renderNotificationTitle,
  renderNotificationContent,
} from '@client/src/i18n/notifications-i18n';

const PAGE_SIZE = 20;

const NOTIFICATION_ICONS: Record<string, { icon: React.ReactNode; color: string }> = {
  comment: { icon: <MessageSquare className="h-5 w-5" />, color: 'text-cyan-400 bg-cyan-500/20' },
  like: { icon: <Heart className="h-5 w-5" />, color: 'text-pink-400 bg-pink-500/20' },
  follow: { icon: <UserPlus className="h-5 w-5" />, color: 'text-emerald-400 bg-emerald-500/20' },
  warning: { icon: <AlertTriangle className="h-5 w-5" />, color: 'text-amber-400 bg-amber-500/20' },
  system: { icon: <Info className="h-5 w-5" />, color: 'text-blue-400 bg-blue-500/20' },
  achievement: { icon: <Award className="h-5 w-5" />, color: 'text-yellow-400 bg-yellow-500/20' },
  mute: { icon: <AlertTriangle className="h-5 w-5" />, color: 'text-amber-400 bg-amber-500/20' },
  unmute: { icon: <Info className="h-5 w-5" />, color: 'text-emerald-400 bg-emerald-500/20' },
  ban: { icon: <AlertTriangle className="h-5 w-5" />, color: 'text-red-400 bg-red-500/20' },
  unban: { icon: <Info className="h-5 w-5" />, color: 'text-emerald-400 bg-emerald-500/20' },
  content_removed: { icon: <AlertTriangle className="h-5 w-5" />, color: 'text-amber-400 bg-amber-500/20' },
  content_deleted: { icon: <AlertTriangle className="h-5 w-5" />, color: 'text-amber-400 bg-amber-500/20' },
  report_result: { icon: <Info className="h-5 w-5" />, color: 'text-blue-400 bg-blue-500/20' },
};

function getNotificationIcon(type: string) {
  return NOTIFICATION_ICONS[type] || NOTIFICATION_ICONS.system;
}

function getTargetPath(targetType?: string, targetId?: string): string | null {
  if (!targetType || !targetId) return null;
  switch (targetType) {
    case 'player':
      return `/player/${targetId}`;
    case 'coach':
      return `/coach/${targetId}`;
    case 'pack':
      return `/pack/${targetId}`;
    case 'forum_post':
      return `/forum/${targetId}`;
    case 'post':
      return `/forum/${targetId}`;
    case 'comment':
      return `/forum/${targetId}`;
    case 'forum_comment':
      return `/forum/${targetId}`;
    default:
      return null;
  }
}

const NotificationsPage: React.FC = () => {
  const { user } = useAuth();
  const { t, lang } = useI18n();
  const navigate = useNavigate();
  const [tab, setTab] = useState<'all' | 'unread'>('all');
  const [items, setItems] = useState<NotificationItem[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [markingAll, setMarkingAll] = useState(false);
  const mountedRef = useRef(true);

  const fetchList = useCallback(
    async (pageNum: number) => {
      if (!user) return;
      if (pageNum === 1) setLoading(true);
      try {
        const res = await getNotifications({
          page: pageNum,
          pageSize: PAGE_SIZE,
          unreadOnly: tab === 'unread',
        });
        if (!mountedRef.current) return;
        if (pageNum === 1) {
          setItems(res.items);
        } else {
          setItems((prev) => [...prev, ...res.items]);
        }
        setTotal(res.total);
      } catch (err: unknown) {
        logger.error('加载通知失败', err);
        toast.error(t('notif.loadFail'));
      } finally {
        if (mountedRef.current && pageNum === 1) setLoading(false);
      }
    },
    [tab, user],
  );

  useEffect(() => {
    mountedRef.current = true;
    fetchList(1);
    return () => {
      mountedRef.current = false;
    };
  }, [fetchList]);

  useEffect(() => {
    setPage(1);
    setItems([]);
    setTotal(0);
  }, [tab]);

  const hasMore = items.length < total;

  const loadMore = useCallback(async () => {
    if (!hasMore) return;
    const nextPage = page + 1;
    setPage(nextPage);
    await fetchList(nextPage);
  }, [hasMore, page, fetchList]);

  const { sentinelRef, loading: loadingMore } = useInfiniteScroll({
    hasMore,
    loadMore,
  });

  const handleItemClick = async (item: NotificationItem) => {
    if (!item.isRead) {
      try {
        await markAsRead(item.id);
        setItems((prev) =>
          prev.map((i) => (i.id === item.id ? { ...i, isRead: true } : i)),
        );
      } catch (err: unknown) {
        logger.error('标记已读失败', err);
      }
    }
    const path = getTargetPath(item.targetType, item.targetId);
    if (path) {
      navigate(path);
    }
  };

  const handleMarkAllRead = async () => {
    if (markingAll) return;
    setMarkingAll(true);
    try {
      await markAllAsRead();
      setItems((prev) => prev.map((i) => ({ ...i, isRead: true })));
      toast.success(t('notif.allMarkedRead'));
    } catch (err: unknown) {
      logger.error('全部标记已读失败', err);
      toast.error(t('notif.actionFail'));
    } finally {
      setMarkingAll(false);
    }
  };

  if (!user) {
    return (
      <div className="mx-auto max-w-3xl px-4 py-8">
        <div className="rounded-2xl border border-white/10 bg-[#141838]/40 p-10 text-center">
          <Bell className="mx-auto mb-4 h-14 w-14 md:h-10 md:w-10 text-white/30" />
          <p className="text-2xl md:text-base text-white/60">{t('notif.loginPrompt')}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-3xl px-4 py-8">
      {/* 标题 */}
      <div className="mb-6 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="flex h-14 w-14 md:h-10 md:w-10 items-center justify-center rounded-full bg-neon-gradient shadow-lg box-glow-cyan">
            <Bell className="h-7 w-7 md:h-5 md:w-5 text-white" />
          </div>
          <h1 className="text-5xl md:text-2xl font-bold text-white">{t('notif.title')}</h1>
        </div>
        <button
          onClick={handleMarkAllRead}
          disabled={markingAll || total === 0}
          className="flex items-center gap-1.5 rounded-lg border border-cyan-400/30 bg-cyan-500/10 px-5 py-3 md:px-3 md:py-1.5 text-xl md:text-sm text-cyan-300 transition-all hover:border-cyan-400/60 hover:bg-cyan-500/20 disabled:opacity-50"
        >
          <CheckCheck className="h-6 w-6 md:h-4 md:w-4" />
          {t('notif.markAllRead')}
        </button>
      </div>

      {/* Tabs */}
      <div className="mb-4 flex gap-1 rounded-xl border border-white/10 bg-[#141838]/60 p-1">
        <button
          onClick={() => setTab('all')}
          className={`flex-1 rounded-lg py-3 md:py-2 text-xl md:text-sm font-medium transition-all ${
            tab === 'all'
              ? 'bg-cyan-500/20 text-cyan-300 shadow-[0_0_12px_rgba(34_211_238_0.3)]'
              : 'text-white/60 hover:text-white/90'
          }`}
        >
          {t('notif.all')}
        </button>
        <button
          onClick={() => setTab('unread')}
          className={`flex-1 rounded-lg py-3 md:py-2 text-xl md:text-sm font-medium transition-all ${
            tab === 'unread'
              ? 'bg-pink-500/20 text-pink-300 shadow-[0_0_12px_rgba(236_72_153_0.3)]'
              : 'text-white/60 hover:text-white/90'
          }`}
        >
          {t('notif.unread')}
        </button>
      </div>

      {/* 列表 */}
      {loading ? (
        <div className="flex items-center justify-center py-16">
          <Loader2 className="h-8 w-8 animate-spin text-cyan-400" />
        </div>
      ) : items.length === 0 ? (
        <div className="rounded-2xl border border-white/10 bg-[#141838]/40 p-10 text-center">
          <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-full bg-white/5">
            <Bell className="h-7 w-7 text-cyan-400/60" />
          </div>
          <h3 className="text-3xl md:text-lg font-semibold text-white/80 mb-2">{t('notif.empty')}</h3>
          <p className="text-xl md:text-sm text-gray-500">
            {tab === 'unread' ? t('notif.noUnread') : t('notif.noMessages')}
          </p>
        </div>
      ) : (
        <div className="space-y-2">
          {items.map((item) => {
            const iconInfo = getNotificationIcon(item.type);
            const targetPath = getTargetPath(item.targetType, item.targetId);
            return (
              <div
                key={item.id}
                onClick={() => handleItemClick(item)}
                className={`group relative flex gap-3 rounded-xl border p-3 transition-all duration-200 ${
                  targetPath ? 'cursor-pointer' : ''
                } ${
                  item.isRead
                    ? 'border-white/5 bg-[#141838]/30 opacity-70'
                    : 'border-cyan-400/20 bg-[#141838]/70 backdrop-blur hover:border-cyan-400/40 hover:shadow-[0_0_15px_rgba(34_211_238_0.15)]'
                }`}
              >
                {/* 未读小圆点 */}
                {!item.isRead && (
                  <span className="absolute right-3 top-3 h-2 w-2 rounded-full bg-pink-500 shadow-[0_0_8px_rgba(236_72_153_0.8)]" />
                )}
                {/* 图标 */}
                <div
                  className={`flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-full ${iconInfo.color}`}
                >
                  {iconInfo.icon}
                </div>
                {/* 内容 */}
                <div className="flex-1 min-w-0">
                  <h4 className={`text-[30px] md:text-base font-medium ${item.isRead ? 'text-white/70' : 'text-white'}`}>
                    {renderNotificationTitle(item, lang)}
                  </h4>
                  <p
                    className="mt-0.5 text-[26px] md:text-sm text-gray-400"
                    style={{
                      display: '-webkit-box',
                      WebkitLineClamp: 2,
                      WebkitBoxOrient: 'vertical',
                      overflow: 'hidden',
                    }}
                  >
                    {renderNotificationContent(item, lang)}
                  </p>
                  <p className="mt-1 text-[22px] md:text-xs text-gray-500">
                    {dayjs(item.createdAt).format('YYYY-MM-DD HH:mm')}
                  </p>
                </div>
              </div>
            );
          })}

          <div ref={sentinelRef}>
            <InfiniteScrollFooter
              loading={loadingMore}
              hasMore={hasMore}
              hasItems={items.length > 0}
            />
          </div>
        </div>
      )}
    </div>
  );
};

export default NotificationsPage;
