import { appleLoginNative } from '@client/src/api/auth';
import type { AuthResponse } from '@shared/api.interface';

const APPLE_JS_URL =
  'https://appleid.cdn-apple.com/appleauth/static/jsapi/appleid/1/zh_CN/appleid.auth.js';

let loadingPromise: Promise<void> | null = null;

declare global {
  interface Window {
    AppleID?: {
      auth: {
        init(config: Record<string, unknown>): void;
        signIn(): Promise<{
          authorization?: { id_token?: string; code?: string };
          user?: {
            email?: string;
            name?: { firstName?: string; lastName?: string };
          };
        }>;
      };
    };
  }
}

function loadAppleJs(): Promise<void> {
  if (window.AppleID?.auth) return Promise.resolve();
  if (loadingPromise) return loadingPromise;
  loadingPromise = new Promise<void>((resolve, reject) => {
    const s = document.createElement('script');
    s.src = APPLE_JS_URL;
    s.async = true;
    s.onload = () => resolve();
    s.onerror = () => reject(new Error('Apple 登录脚本加载失败'));
    document.head.appendChild(s);
  });
  return loadingPromise;
}

/** 网页端 Apple 登录：AppleID JS 弹窗拿 id_token，再走统一后端验签 */
export async function signInWithAppleWeb(
  clientId: string,
): Promise<AuthResponse> {
  if (!clientId) {
    throw new Error('网页 Apple 登录未配置 Services ID');
  }
  await loadAppleJs();
  if (!window.AppleID?.auth) {
    throw new Error('Apple 登录脚本未就绪');
  }
  const redirectURI = `${window.location.origin}${window.location.pathname}`;
  window.AppleID.auth.init({
    clientId,
    scope: 'name email',
    redirectURI,
    usePopup: true,
  });
  const res = await window.AppleID.auth.signIn();
  const idToken = res?.authorization?.id_token;
  if (!idToken) {
    throw new Error('未获取到 Apple 凭证，请重试');
  }
  const appleUser = res?.user;
  const fullName = appleUser?.name
    ? [appleUser.name.firstName, appleUser.name.lastName]
        .filter(Boolean)
        .join(' ')
    : '';
  return appleLoginNative({
    identityToken: idToken,
    userName:
      fullName || appleUser?.email
        ? {
            name: fullName || undefined,
            email: appleUser?.email || undefined,
          }
        : null,
  });
}
