import React, { useState, useEffect, useCallback } from 'react';
import { Heart } from 'lucide-react';
import { toast } from 'sonner';
import { useLoginGuard } from '@client/src/hooks/useLoginGuard';
import {
  checkFavorite,
  toggleFavorite,
  type FavoriteTargetType,
} from '@client/src/api/favorites';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { trTerm } from '@client/src/i18n/terms';
import {
  visitorLocalHas,
  visitorLocalToggle,
  toastVisitorLocal,
  type VisitorSetKind,
} from '@client/src/utils/visitor-mode';

interface FavoriteButtonProps {
  targetType: FavoriteTargetType;
  targetId: string;
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

const SIZE_MAP = {
  sm: 'h-4 w-4',
  md: 'h-5 w-5',
  lg: 'h-6 w-6',
};

const BTN_SIZE_MAP = {
  sm: 'p-1.5',
  md: 'p-2',
  lg: 'p-2.5',
};

// 收藏目标类型 -> 游客本地集合类型
const VISITOR_SET_KIND: Record<FavoriteTargetType, VisitorSetKind> = {
  player: 'favorite_player',
  coach: 'favorite_coach',
  pack: 'favorite_pack',
  forum_post: 'favorite_forum_post',
};

const FavoriteButton: React.FC<FavoriteButtonProps> = ({
  targetType,
  targetId,
  size = 'md',
  className = '',
}) => {
  const { user, allowLocalAction } = useLoginGuard();
  const [favorited, setFavorited] = useState(false);
  const [loading, setLoading] = useState(true);
  const [animating, setAnimating] = useState(false);

  useEffect(() => {
    // 游客：读取本机收藏状态
    if (!user) {
      setFavorited(visitorLocalHas(VISITOR_SET_KIND[targetType], targetId));
      setLoading(false);
      return;
    }
    // 已登录：读取云端收藏状态
    setLoading(true);
    checkFavorite(targetType, targetId)
      .then((data) => setFavorited(data.favorited))
      .catch((err: unknown) => {
        logger.error('检查收藏状态失败', err);
      })
      .finally(() => setLoading(false));
  }, [targetType, targetId, user]);

  const handleClick = useCallback(
    async (e: React.MouseEvent) => {
      e.stopPropagation();
      if (loading) return;
      // 开关关闭且未登录时：toast + 跳登录，返回 false
      if (!allowLocalAction('收藏')) return;

      const nextState = !favorited;
      setFavorited(nextState);
      setAnimating(true);
      setTimeout(() => setAnimating(false), 400);

      // 游客：仅本机保存，不请求云端
      if (!user) {
        const next = visitorLocalToggle(
          VISITOR_SET_KIND[targetType],
          targetId,
        );
        setFavorited(next);
        if (next) toastVisitorLocal('favorite');
        return;
      }

      try {
        const res = await toggleFavorite(targetType, targetId);
        setFavorited(res.favorited);
      } catch (err: unknown) {
        setFavorited(!nextState);
        const msg = err instanceof Error ? err.message : '操作失败';
        toast.error(msg);
      }
    },
    [user, favorited, loading, targetType, targetId],
  );

  if (loading) return null;

  return (
    <button
      onClick={handleClick}
      className={`rounded-full border transition-all duration-200 ${BTN_SIZE_MAP[size]} ${
        favorited
          ? 'border-pink-400/60 bg-pink-500/20 text-pink-400 shadow-[0_0_12px_rgba(236_72_153_0.4)] hover:shadow-[0_0_18px_rgba(236_72_153_0.6)]'
          : 'border-white/15 bg-[#141838]/60 text-white/50 hover:border-pink-400/40 hover:text-pink-300 hover:bg-pink-500/10'
      } ${animating ? 'scale-125' : 'scale-100'} ${className}`}
      style={{
        transition: 'transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1), all 0.2s',
      }}
      title={favorited ? trTerm('取消收藏') : trTerm('收藏')}
      aria-label={favorited ? trTerm('取消收藏') : trTerm('收藏')}
    >
      <Heart
        className={`${SIZE_MAP[size]} ${favorited ? 'fill-pink-400' : ''}`}
      />
    </button>
  );
};

export default FavoriteButton;
