import React, { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@client/src/components/ui/dialog';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { Megaphone, Smartphone, Heart } from 'lucide-react';

// 公告版本 key：更新公告内容时把 v1 改成 v2，已关闭的用户会重新看到一次
export const ANNOUNCE_STORAGE_KEY = 'pts_announce_v1';

interface Props {
  open: boolean;
  onClose: () => void;
}

const BetaAnnouncementDialog: React.FC<Props> = ({ open, onClose }) => {
  const { lang } = useI18n();
  const en = lang === 'en';
  // 默认勾选「下次不再展示」：用户看到一次、直接关闭即不再打扰
  const [dontShow, setDontShow] = useState(true);

  const handleClose = () => {
    if (dontShow) {
      try {
        localStorage.setItem(ANNOUNCE_STORAGE_KEY, 'dismissed');
      } catch {
        /* 隐私模式等写入失败时忽略，仅本次关闭 */
      }
    }
    onClose();
  };

  return (
    <Dialog
      open={open}
      onOpenChange={(o) => {
        if (!o) handleClose();
      }}
    >
      <DialogContent className="border-cyan-400/30 bg-[#141838]/95 text-white backdrop-blur-md shadow-xl shadow-cyan-500/10 max-w-lg max-sm:top-[5%] max-sm:translate-y-0 max-sm:max-h-[46%] max-sm:overflow-y-auto max-sm:overscroll-contain">
        <DialogHeader>
          <DialogTitle className="text-lg md:text-xl font-bold text-cyan-200 tracking-wider flex items-center gap-2">
            <Megaphone className="h-5 w-5 flex-shrink-0" />
            {en ? 'Public Beta Notice' : '公测公告 · 随身助教正在成长'}
          </DialogTitle>
        </DialogHeader>

        <div className="py-2 space-y-3 text-sm leading-relaxed text-white/80">
          <p className="flex gap-2">
            <Heart className="h-4 w-4 mt-0.5 text-pink-300 flex-shrink-0" />
            <span>
              {en ? (
                <>
                  Thanks for opening PlayToStar APP! We're still in public beta, polishing data and features. If you
                  hit any bug or have ideas to make it better, leave a comment in the forum or email{' '}
                  <b className="text-cyan-300">efootballchina@yeah.net</b> — we read every one.
                </>
              ) : (
                <>
                  感谢你打开 PlayToStar APP！产品目前仍处于公测阶段，数据与功能还在持续打磨。若遇到任何 Bug，或有让它
                  更好用的建议，欢迎在评论区留言，或直接发邮件到{' '}
                  <b className="text-cyan-300">efootballchina@yeah.net</b>，我们会逐条查看。
                </>
              )}
            </span>
          </p>
          <p className="flex gap-2">
            <Smartphone className="h-4 w-4 mt-0.5 text-cyan-300 flex-shrink-0" />
            <span>
              {en ? (
                <>
                  The iOS app is under App Store review. Meanwhile you can use the web version. Due to review
                  rules, web login currently only supports WeChat QR scan confirmed on a second phone.
                </>
              ) : (
                <>
                  iOS 版 App 正在苹果审核中，在此之前可直接使用网页版登录；受审核规则限制，网页端暂时仅支持
                  「第二部手机微信扫码」登录（即用另一台设备的微信扫码确认），请放心使用。
                </>
              )}
            </span>
          </p>
          <p className="text-center text-white/70 pt-2 border-t border-white/10">
            {en
              ? 'Our goal is simple: a smooth, clean, ad-free eFootball companion. Thanks for your support!'
              : '我们的目标很简单：做一个顺手、干净、没有广告的实况随身助教。感谢你的支持与耐心，我们会越做越好。'}
          </p>
        </div>

        <label className="flex items-center gap-2 text-sm text-white/80 cursor-pointer select-none pt-1">
          <input
            type="checkbox"
            checked={dontShow}
            onChange={(e) => setDontShow(e.target.checked)}
            className="h-4 w-4 accent-cyan-400"
          />
          {en ? "Don't show again" : '下次不再展示'}
        </label>

        <DialogFooter>
          <button
            onClick={handleClose}
            className="inline-flex w-full items-center justify-center rounded-md bg-neon-gradient px-4 py-2 text-sm font-bold text-white shadow-lg box-glow-cyan hover:opacity-90"
          >
            {en ? 'Got it' : '我知道了'}
          </button>
        </DialogFooter>
        <DialogDescription className="sr-only">
          {en ? 'PlayToStar APP public beta announcement' : 'PlayToStar APP 公测公告'}
        </DialogDescription>
      </DialogContent>
    </Dialog>
  );
};

export default BetaAnnouncementDialog;
