import type { LineupPayload, LineupItemSnapshot } from '@client/src/api/lineups';
import { resolvePlayerCardImage } from '@client/src/utils/player-card-url';
import { LOCAL_ASSETS, loadFirstImage } from '@client/src/utils/local-assets';
import { ICON_DATA_URI } from '@client/src/utils/brand-icon-data';
import { drawBrandWatermark } from '@client/src/utils/brand-watermark';

// 品牌主视觉底图（与球员分享图 player-share-image、强度榜 tier-image 同一张 banner）
const BANNER_URL =
  'https://efootballpsbete-1488358463.cos.ap-shanghai.myqcloud.com/EF20270916/EF2027/banner/banner.png';

export function viaProxy(src: string): string {
  try {
    const u = new URL(src);
    if (u.host.endsWith('myqcloud.com')) {
      return `https://playtostar.com/cosimg${u.pathname}`;
    }
  } catch {
    /* 非绝对地址，原样返回 */
  }
  return src;
}

export function loadImage(src: string): Promise<HTMLImageElement | null> {
  return new Promise((resolve) => {
    if (!src) {
      resolve(null);
      return;
    }
    const img = new Image();
    img.crossOrigin = 'anonymous';
    let done = false;
    const timer = setTimeout(() => {
      if (!done) {
        done = true;
        resolve(null);
      }
    }, 7000);
    img.onload = () => {
      if (!done) {
        done = true;
        clearTimeout(timer);
        resolve(img);
      }
    };
    img.onerror = () => {
      if (!done) {
        done = true;
        clearTimeout(timer);
        resolve(null);
      }
    };
    img.src = src;
  });
}

export function roundRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
): void {
  ctx.beginPath();
  const rr = (ctx as any).roundRect;
  if (rr) {
    rr.call(ctx, x, y, w, h, r);
    return;
  }
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function drawContain(
  ctx: CanvasRenderingContext2D,
  img: HTMLImageElement,
  x: number,
  y: number,
  w: number,
  h: number,
): void {
  const scale = Math.min(w / img.width, h / img.height);
  const dw = img.width * scale;
  const dh = img.height * scale;
  ctx.drawImage(img, x + (w - dw) / 2, y + (h - dh) / 2, dw, dh);
}


function drawPlayerOnPitch(
  ctx: CanvasRenderingContext2D,
  item: LineupItemSnapshot,
  img: HTMLImageElement | null,
  iconImg: HTMLImageElement | null,
  px: number,
  py: number,
  pw: number,
  ph: number,
  cardW: number,
  cardH: number,
): void {
  // 归一化坐标 → 像素（卡心），并夹取在场地内
  const nx = Math.min(1, Math.max(0, item.x));
  const ny = Math.min(1, Math.max(0, item.y));
  const cx = px + nx * pw;
  const cy = py + ny * ph;
  const x0 = cx - cardW / 2;
  const y0 = cy - cardH / 2;

  // 卡底
  const cg = ctx.createLinearGradient(x0, y0, x0, y0 + cardH);
  cg.addColorStop(0, '#161d3d');
  cg.addColorStop(1, '#10162f');
  ctx.fillStyle = cg;
  roundRect(ctx, x0, y0, cardW, cardH, 10);
  ctx.fill();

  if (img) {
    drawContain(ctx, img, x0 + 3, y0 + 3, cardW - 6, cardH - 10);
  } else {
    ctx.fillStyle = 'rgba(255,255,255,0.5)';
    ctx.font = 'bold 34px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(
      item.nameZh?.charAt(0) || item.nameEn?.charAt(0) || '?',
      cx,
      cy - 8,
    );
  }

  // 球员名药丸
  const nm = item.nameZh || item.nameEn || '';
  const showNm = nm.length > 6 ? `${nm.slice(0, 6)}…` : nm;
  ctx.font = 'bold 14px system-ui, sans-serif';
  const tw = ctx.measureText(showNm).width;
  const nameCy = y0 + cardH * 0.8;
  ctx.fillStyle = 'rgba(0,0,0,0.62)';
  roundRect(ctx, cx - tw / 2 - 7, nameCy - 11, tw + 14, 22, 7);
  ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(showNm, cx, nameCy);

  // 小水印
  if (iconImg) {
    const ws = 20;
    ctx.drawImage(iconImg, x0 + cardW - ws - 4, y0 + 4, ws, ws);
  }
}

export async function renderLineupCanvas(
  payload: LineupPayload,
): Promise<HTMLCanvasElement> {
  const W = 1080;
  const pad = 26;
  const titleH = 140;
  const pw0 = W - pad * 2; // 球场宽
  const ph0 = pw0; // 球场高（1:1，与新底图一致）
  const H = titleH + ph0 + pad;

  const iconImg = await loadFirstImage([...LOCAL_ASSETS.iconCandidates, ICON_DATA_URI]);
  const pitchBgImg = await loadFirstImage(LOCAL_ASSETS.pitchCandidates);
  // 主视觉底图（与球员分享图 / 强度榜同款）
  const bgImg = await loadImage(viaProxy(BANNER_URL));
  const imgMap = new Map<string, HTMLImageElement | null>();
  await Promise.all(
    payload.items.map(async (item) => {
      if (imgMap.has(item.playerId)) return;
      const im = await loadImage(
        viaProxy(resolvePlayerCardImage(item.playerImageUrl, item.playerId)),
      );
      imgMap.set(item.playerId, im);
    }),
  );

  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d')!;

  // 背景：深色渐变打底（与球员分享图 / 强度榜一致）
  const bg = ctx.createLinearGradient(0, 0, W, H);
  bg.addColorStop(0, '#0a0f2e');
  bg.addColorStop(0.55, '#0c1338');
  bg.addColorStop(1, '#141a4a');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // 主视觉图（cover）+ 压暗（与球员分享图 / 强度榜一致；球场底图后续不透明覆盖中部）
  if (bgImg) {
    const ir = bgImg.width / bgImg.height;
    let dw = W;
    let dh = W / ir;
    let dx = 0;
    let dy = (H - dh) / 2;
    if (dh < H) { dh = H; dw = H * ir; dx = (W - dw) / 2; dy = 0; }
    ctx.drawImage(bgImg, dx, dy, dw, dh);
    ctx.fillStyle = 'rgba(7,10,28,0.66)';
    ctx.fillRect(0, 0, W, H);
  }

  // 斜向渐变条纹（与球员分享图 / 强度榜一致）
  ctx.save();
  ctx.strokeStyle = 'rgba(255,255,255,0.055)';
  ctx.lineWidth = 2;
  for (let d = -H; d < W; d += 84) {
    ctx.beginPath();
    ctx.moveTo(d, H);
    ctx.lineTo(d + H, 0);
    ctx.stroke();
  }
  ctx.restore();

  // 标题
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 50px system-ui, sans-serif';
  ctx.textBaseline = 'alphabetic';
  ctx.fillText(payload.name || '我的阵容', pad, 66);
  ctx.fillStyle = '#22e5ff';
  ctx.font = '24px system-ui, sans-serif';
  ctx.fillText('绘制源自 PlayToStar APP', pad, 100);
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  ctx.font = '19px system-ui, sans-serif';
  ctx.fillText('卡面版权归 KONAMI 所有 · 本图仅用于学习交流，禁止商业用途', pad, 128);

  // 球场区域（1:1 底图）
  const px = pad;
  const py = titleH;
  const pw = pw0;
  const ph = ph0;
  if (pitchBgImg) {
    ctx.drawImage(pitchBgImg, px, py, pw, ph);
  } else {
    ctx.fillStyle = '#1f7a3d';
    ctx.fillRect(px, py, pw, ph);
  }

  // 球员
  const cardW = 90;
  const cardH = Math.round(cardW * (4 / 3));
  payload.items.forEach((item) => {
    drawPlayerOnPitch(
      ctx,
      item,
      imgMap.get(item.playerId) ?? null,
      iconImg,
      px,
      py,
      pw,
      ph,
      cardW,
      cardH,
    );
  });

  // 品牌水印（右上方，最上层；无圆形底纹）
  drawBrandWatermark(ctx, W - 118, 82, iconImg, { scale: 0.62, noCircle: true });

  return canvas;
}
