import React, { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@client/src/components/ui/dialog';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { Hand } from 'lucide-react';

// 滑屏引导版本 key：更新引导文案时把 v1 改成 v2，已关闭的用户会重新看到一次
export const SLIDE_TIP_STORAGE_KEY = 'pts_slide_tip_v1';

interface Props {
  open: boolean;
  onClose: () => void;
}

const SlidePointsTipDialog: React.FC<Props> = ({ open, onClose }) => {
  const { lang } = useI18n();
  const en = lang === 'en';
  // 默认勾选「下次不再展示」
  const [dontShow, setDontShow] = useState(true);

  const handleClose = () => {
    if (dontShow) {
      try {
        localStorage.setItem(SLIDE_TIP_STORAGE_KEY, 'dismissed');
      } catch {
        /* 写入失败时仅本次关闭 */
      }
    }
    onClose();
  };

  return (
    <Dialog
      open={open}
      onOpenChange={(o) => {
        if (!o) handleClose();
      }}
    >
      <DialogContent className="border-pink-400/30 bg-[#141838]/95 text-white backdrop-blur-md shadow-xl shadow-pink-500/10 max-w-md max-sm:top-[5%] max-sm:translate-y-0 max-sm:max-h-[46%] max-sm:overflow-y-auto max-sm:overscroll-contain">
        <DialogHeader>
          <DialogTitle className="text-lg font-bold text-pink-200 flex items-center gap-2">
            <Hand className="h-5 w-5 flex-shrink-0" />
            {en ? 'Swipe to Allocate' : '试试滑屏加点'}
          </DialogTitle>
        </DialogHeader>

        <div className="py-1 space-y-2 text-sm leading-relaxed text-white/80">
          <p>
            {en
              ? 'On the stats panel, swipe left or right directly on an ability value to add or remove points — no need to open the point panel.'
              : '在属性面板的能力数值上，手指左右一滑就能加 / 减点，不用再展开加点面板。'}
          </p>
          <p className="font-bold text-pink-300">
            {en ? 'Patented design — please do not copy.' : '专利设计，仿者必究。'}
          </p>
        </div>

        <label className="flex items-center gap-2 text-sm text-white/80 cursor-pointer select-none pt-1">
          <input
            type="checkbox"
            checked={dontShow}
            onChange={(e) => setDontShow(e.target.checked)}
            className="h-4 w-4 accent-pink-400"
          />
          {en ? "Don't show again" : '下次不再展示'}
        </label>

        <DialogFooter>
          <button
            onClick={handleClose}
            className="inline-flex w-full items-center justify-center rounded-md bg-gradient-to-r from-pink-500 to-amber-400 px-4 py-2 text-sm font-bold text-white shadow-lg hover:opacity-90"
          >
            {en ? 'Got it' : '我知道了'}
          </button>
        </DialogFooter>
        <DialogDescription className="sr-only">
          {en ? 'Swipe to allocate tip' : '滑屏加点提示'}
        </DialogDescription>
      </DialogContent>
    </Dialog>
  );
};

export default SlidePointsTipDialog;
