import React, { useMemo, useRef, useState, useEffect } from 'react';
import ReactECharts from 'echarts-for-react';
import * as echarts from 'echarts/core';
import { RadarComponent, TooltipComponent, LegendComponent } from 'echarts/components';
import { RadarChart } from 'echarts/charts';
import { CanvasRenderer } from 'echarts/renderers';
import type { EChartsOption } from 'echarts';
import type { Player } from '@shared/api.interface';
import type { CompareComputedStats } from '@client/src/utils/compare-stats';
import { getAttrHexColor } from '@client/src/utils/attr-color';

echarts.use([RadarComponent, TooltipComponent, LegendComponent, RadarChart, CanvasRenderer]);

const PLAYER_COLORS = [
  { line: '#00E5FF', area: 'rgba(0, 229, 255, 0.35)', point: '#FF2D95' },
  { line: '#FF9F1C', area: 'rgba(255, 159, 28, 0.35)', point: '#FF9F1C' },
  { line: '#4ADE80', area: 'rgba(74, 222, 128, 0.35)', point: '#4ADE80' },
  { line: '#A78BFA', area: 'rgba(167, 139, 250, 0.35)', point: '#A78BFA' },
  { line: '#22D3EE', area: 'rgba(34, 211, 238, 0.35)', point: '#22D3EE' },
  { line: '#F472B6', area: 'rgba(244, 114, 182, 0.35)', point: '#F472B6' },
];

interface IndicatorDef {
  key: string;
  name: string;
}

// 12 点方向顺时针：进攻、射门、对抗、制空、防守、速度、盘带、传球
const OUT_FIELD_INDICATORS: IndicatorDef[] = [
  { key: 'attack', name: '进攻' },
  { key: 'shooting', name: '射门' },
  { key: 'physical', name: '对抗' },
  { key: 'aerial', name: '制空' },
  { key: 'defending', name: '防守' },
  { key: 'speed', name: '速度' },
  { key: 'dribbling', name: '盘带' },
  { key: 'passing', name: '传球' },
];

const GK_INDICATORS: IndicatorDef[] = [
  { key: 'gkAwareness', name: '守门意识' },
  { key: 'gkCatching', name: '接球能力' },
  { key: 'gkReflexes', name: '扑救反应' },
  { key: 'gkClearing', name: '扑救范围' },
  { key: 'gkReach', name: '臂展范围' },
];

interface CompareRadarChartProps {
  playerList: Player[];
  computedStatsMap?: Record<string, CompareComputedStats>;
}

const isGKPlayer = (player: Player): boolean => {
  if (player.position === 'GK' || player.position === '门将') return true;
  const pr = player.positionRatings;
  if (!pr) return false;
  const gkVal = pr.goalkeeper ?? 0;
  const otherVals = [
    pr.leftWing, pr.centerForward, pr.rightWing, pr.secondStriker,
    pr.attackingMidfielder, pr.leftMidfielder, pr.centralMidfielder,
    pr.rightMidfielder, pr.defensiveMidfielder, pr.leftBack,
    pr.centerBack, pr.rightBack,
  ].map((v) => v ?? 0);
  const maxOther = Math.max(...otherVals, 0);
  return gkVal >= maxOther;
};

function getPlayerRadarValue(
  player: Player,
  indicators: IndicatorDef[],
  computedStatsMap?: Record<string, CompareComputedStats>,
): number[] {
  const computed = computedStatsMap?.[player.id];
  if (computed) {
    return indicators.map((ind) => computed.radarData[ind.key] ?? 0);
  }
  if (isGKPlayer(player)) {
    const ds = player.defenseStats as unknown as Record<string, { rating: number }>;
    return GK_INDICATORS.map((ind) => ds[ind.key]?.rating ?? 0);
  }
  return indicators.map((ind) => {
    const v = player.radarData[ind.key as keyof typeof player.radarData];
    return typeof v === 'number' ? v : 0;
  });
}

const CompareRadarChart: React.FC<CompareRadarChartProps> = ({ playerList, computedStatsMap }) => {
  // 关键：是否放大只看“竖屏窄屏（内宽<768）”，覆盖原生手机 APP 与手机竖屏网页；
  // 平板/桌面/横屏保持紧凑。不依赖容器宽度（容器在挂载瞬间可能量错）。
  const [isNarrow, setIsNarrow] = useState<boolean>(
    () => typeof window !== 'undefined' && window.innerWidth < 768,
  );
  useEffect(() => {
    const onResize = () => setIsNarrow(window.innerWidth < 768);
    setIsNarrow(window.innerWidth < 768);
    window.addEventListener('resize', onResize);
    window.addEventListener('orientationchange', onResize);
    return () => {
      window.removeEventListener('resize', onResize);
      window.removeEventListener('orientationchange', onResize);
    };
  }, []);
  const phone = isNarrow;

  const allGK = playerList.every((p) => isGKPlayer(p));
  const anyGK = playerList.some((p) => isGKPlayer(p));
  const mixedMode = anyGK && !allGK;
  const indicators = allGK ? GK_INDICATORS : OUT_FIELD_INDICATORS;

  const containerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<ReactECharts | null>(null);
  // 关键：窄屏原生页外层按 DESIGN_WIDTH(860) 布局再 bodyScale 缩放到视口，
  // 容器真实布局宽≈808（不是 window.innerWidth 的390）。初始用接近值，挂载后以实测 clientWidth 为准。
  const [containerWidth, setContainerWidth] = useState<number>(() =>
    typeof window !== 'undefined' && window.innerWidth < 768 ? 820 : 320);

  useEffect(() => {
    // 直接以容器实测布局宽为准（bodyScale 缩放容器内≈808，普通网页即真实卡片宽）；
    // 不用 window.innerWidth 做上限——那是缩放后的视口宽，会把画布错误压小。
    const calc = (): void => {
      const measured = containerRef.current?.clientWidth ?? 0;
      if (measured > 200) setContainerWidth(measured);
    };
    calc();
    const raf1 = requestAnimationFrame(calc);
    const raf2 = requestAnimationFrame(() => requestAnimationFrame(calc));
    const timers = [60, 150, 300, 600, 1000].map((t) => window.setTimeout(calc, t));
    const ro = new ResizeObserver(calc);
    if (containerRef.current) ro.observe(containerRef.current);
    return () => {
      ro.disconnect();
      cancelAnimationFrame(raf1);
      cancelAnimationFrame(raf2);
      timers.forEach((t) => window.clearTimeout(t));
    };
  }, []);

  // 画布以 100% 跟随容器，宽度变化后只需让 ECharts 自动重排（不再传可能误报的显式宽）
  useEffect(() => {
    const inst = chartRef.current?.getEchartsInstance?.();
    if (!inst) return undefined;
    const raf = requestAnimationFrame(() => inst.resize());
    return () => cancelAnimationFrame(raf);
  }, [containerWidth, phone]);

  const option = useMemo<EChartsOption>(() => {
    const playerValues: number[][] = playerList.map((p) =>
      getPlayerRadarValue(p, indicators, computedStatsMap),
    );

    // 竖屏：轴上只显示项目名称（取消每个球员的数值，数值已在下方图例与悬停中给出），
    // 把外围空间让给多边形，从而真正放大面积；名称围绕一周，无换行。
    const indicatorList = indicators.map((item, idx) => ({
      name: `{name${idx}|${item.name}}`,
      max: 100,
      min: 40,
    }));

    const richStyles: Record<string, Record<string, unknown>> = {};
    // 竖屏窄屏：轴上只留项目名；字号收敛到18（旧23过大，会挤压并裁掉右侧标签），
    // 配合半径90%让多边形真正放大并居中。网页/平板保持15。
    const labelFontSize = phone ? 18 : 15;

    indicators.forEach((_item, idx) => {
      richStyles[`name${idx}`] = {
        color: '#e2e8f0',
        fontSize: labelFontSize,
        fontWeight: 700,
        lineHeight: labelFontSize + 6,
        align: 'center',
        padding: [0, 2, 2, 2],
      };
    });

    const seriesData = playerList.map((player, idx) => {
      const color = PLAYER_COLORS[idx % PLAYER_COLORS.length];
      return {
        value: playerValues[idx],
        name: player.nameZh,
        areaStyle: { color: color.area },
        lineStyle: {
          color: color.line,
          width: 3.5,
          shadowColor: color.line + '99',
          shadowBlur: 8,
        },
        itemStyle: {
          color: color.point,
          borderColor: '#fff',
          borderWidth: 1,
        },
      };
    });

    return {
      tooltip: {
        trigger: 'item',
        backgroundColor: 'rgba(15, 23, 42, 0.95)',
        borderColor: 'rgba(255, 255, 255, 0.15)',
        borderWidth: 1,
        textStyle: { color: '#e2e8f0', fontSize: 14 },
        confine: true,
        padding: [10, 14],
        formatter: (params: { marker?: string; name?: string; value?: number[] }) => {
          const vals = Array.isArray(params.value) ? params.value : [];
          const rows = indicators
            .map((ind, i) => {
              const v = vals[i];
              return `<div style="display:flex;justify-content:space-between;gap:18px;font-size:13px;line-height:20px;"><span style="color:#cbd5e1;">${ind.name}</span><span style="font-weight:700;color:#e2e8f0;">${v ?? '-'}</span></div>`;
            })
            .join('');
          return `<div style="font-weight:700;margin-bottom:6px;font-size:14px;">${params.marker ?? ''}${params.name ?? ''}</div>${rows}`;
        },
      },
      legend: { show: false },
      radar: {
        indicator: indicatorList,
        shape: 'polygon',
        splitNumber: 4,
        nameGap: phone ? 6 : 4,
        axisName: { rich: richStyles, textAlign: 'center' },
        splitLine: { lineStyle: { color: 'rgba(255, 255, 255, 0.18)' } },
        splitArea: {
          show: true,
          areaStyle: {
            color: [
              'rgba(0, 229, 255, 0.015)',
              'rgba(0, 229, 255, 0.03)',
              'rgba(255, 45, 149, 0.025)',
              'rgba(255, 45, 149, 0.04)',
            ],
          },
        },
        axisLine: { lineStyle: { color: 'rgba(255, 255, 255, 0.12)' } },
        center: ['50%', '50%'],
        // 画布显式正确宽度、尺寸稳定后用 key 重建实例：竖屏 72%（r≈131，
        // 为正左/正右"射门/制空"整词标签预留宽度不被裁，垂直靠 1.2 倍高度不裁"进攻/速度"），
        // 多边形较旧版（画布尺寸错误）显著放大；网页/平板保持90%。
        radius: phone ? '72%' : '90%',
      },
      series: [{ type: 'radar', symbol: 'none', data: seriesData }],
    };
  }, [playerList, indicators, computedStatsMap, phone]);

  const playerAvgs = playerList.map((p) => {
    const values = getPlayerRadarValue(p, indicators, computedStatsMap);
    const avg = values.length > 0
      ? Math.round(values.reduce((s, v) => s + v, 0) / values.length)
      : 0;
    return { avg, maxVal: Math.max(...values, 0) };
  });

  // 手机：高度=宽×1.2（旧1.05 上下"进攻/速度"标签被裁），给顶/底轴名留足空间；网页紧凑
  const chartHeight = Math.round(containerWidth * (phone ? 1.2 : 0.4));

  return (
    <div className="rounded-xl bg-[#141838] border border-white/10 overflow-hidden">
      <div className="px-3 sm:px-4 py-2 sm:py-3 bg-white/[0.03]">
        <div className="flex items-center gap-2">
          <span className="w-1 h-4 sm:h-5 bg-gradient-to-b from-cyan-400 to-purple-500 rounded-full" />
          <h3 className={`font-bold text-white ${phone ? 'text-2xl' : 'text-xl'}`}>
            {allGK ? '门将五维对比' : mixedMode ? '八维能力对比（门将单独显示五维）' : '八维能力对比'}
          </h3>
        </div>
      </div>

      <div className="px-3 sm:px-6 pt-2 sm:pt-3 pb-4 sm:pb-5">
        <div ref={containerRef} className="w-full max-w-full overflow-hidden flex justify-center" style={{ height: `${chartHeight}px` }}>
          <ReactECharts
            key={`radar-${containerWidth}-${chartHeight}-${phone ? 'p' : 'w'}`}
            ref={chartRef}
            option={option}
            style={{ height: `${chartHeight}px`, width: `${containerWidth}px` }}
            notMerge
            lazyUpdate
            onChartReady={() => {
              const inst = chartRef.current?.getEchartsInstance?.();
              if (inst) requestAnimationFrame(() => inst.resize());
            }}
          />
        </div>

        <div className={`flex flex-wrap justify-center ${phone ? 'gap-3 mt-3' : 'gap-2 sm:gap-3 mt-2'}`}>
          {playerList.map((p, idx) => {
            const color = PLAYER_COLORS[idx % PLAYER_COLORS.length];
            const { avg, maxVal } = playerAvgs[idx];
            return (
              <div key={p.id} className={`flex items-center ${phone ? 'gap-2' : 'gap-1.5 sm:gap-2'}`}>
                <span
                  className={`rounded-full ${phone ? 'w-3.5 h-3.5' : 'w-2.5 h-2.5 sm:w-3 sm:h-3'}`}
                  style={{ backgroundColor: color.line, boxShadow: `0 0 6px ${color.line}` }}
                />
                <span className={`text-gray-300 ${phone ? 'text-xl' : 'text-lg'}`}>{p.nameZh}</span>
                <span className={`font-bold ${phone ? 'text-xl' : 'text-base'}`} style={{ color: getAttrHexColor(maxVal) }}>
                  {avg}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default CompareRadarChart;
