/**
 * 昵称长度规则：最多 8 个汉字（视觉宽度）。
 * 中日韩/全角字符按宽度 2 计，其余（英文、数字、常见符号）按宽度 1 计，
 * 因此上限视觉宽度 = 16，即：8 个汉字，或最多 16 个英文字母/数字。
 */
export const NICKNAME_MAX_CJK = 8;
export const NICKNAME_MAX_WIDTH = NICKNAME_MAX_CJK * 2;

function isWideCodePoint(cp: number): boolean {
  return (
    (cp >= 0x2e80 && cp <= 0x9fff) || // CJK 部首、汉字、假名等
    (cp >= 0xac00 && cp <= 0xd7a3) || // 韩文音节
    (cp >= 0xf900 && cp <= 0xfaff) || // CJK 兼容表意文字
    (cp >= 0xfe30 && cp <= 0xfe6f) || // CJK 兼容标点、小符号
    (cp >= 0xff00 && cp <= 0xff60) || // 全角拉丁
    (cp >= 0xffe0 && cp <= 0xffe6) || // 全角符号
    (cp >= 0x1f300 && cp <= 0x1faff) || // emoji 及补充符号
    (cp >= 0x20000 && cp <= 0x3fffd) // 扩展区汉字
  );
}

/** 计算昵称的视觉宽度 */
export function nicknameWidth(value: string): number {
  let width = 0;
  for (const ch of value) {
    const cp = ch.codePointAt(0) ?? 0;
    width += isWideCodePoint(cp) ? 2 : 1;
  }
  return width;
}

/** 去掉首尾空白后是否符合昵称规则（非空且不超宽） */
export function isNicknameValid(value: string): boolean {
  const trimmed = value.trim();
  if (!trimmed) return false;
  return nicknameWidth(trimmed) <= NICKNAME_MAX_WIDTH;
}

/** 剩余可输入宽度（用于实时提示） */
export function nicknameRemaining(value: string): number {
  return Math.max(0, NICKNAME_MAX_WIDTH - nicknameWidth(value));
}
