import React, { useState, useMemo, useEffect, useRef } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { balanceText } from '@client/src/utils/balance-text';
import { Search, BookOpen, Users, Zap, ChevronRight } from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import encyclopediaData from '@client/src/assets/data/encyclopedia.json';
import { coachTacticsApi } from '@client/src/api';
import type { CoachTactic } from '@shared/api.interface';
import { ABILITY_VALUE_GROUPS, ABILITY_VALUE_COUNT } from './abilityValues';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';
import { isHiddenSkill } from '@shared/hidden-skills';
import { skillIconUrl } from '@client/src/utils/skill-icons';

type CategoryKey =
  | 'attack_styles'
  | 'defense_styles'
  | 'ai_styles'
  | 'team_styles'
  | 'normal_skills'
  | 'showtime_skills'
  | 'coach_tactics'
  | 'ability_values';

interface CategoryTab {
  key: CategoryKey;
  label: string;
  count: number;
  color: 'cyan' | 'magenta' | 'teal' | 'violet';
}

const CATEGORIES: CategoryTab[] = [
  { key: 'attack_styles', label: '进攻风格', count: 21, color: 'cyan' },
  { key: 'defense_styles', label: '防守风格', count: 14, color: 'cyan' },
  { key: 'ai_styles', label: 'AI风格', count: 7, color: 'cyan' },
  { key: 'team_styles', label: '球队风格', count: 6, color: 'cyan' },
  { key: 'normal_skills', label: '普通技能', count: 48, color: 'cyan' },
  { key: 'showtime_skills', label: 'ST技能', count: 23, color: 'magenta' },
  { key: 'coach_tactics', label: '教练战术', count: 13, color: 'teal' },
  { key: 'ability_values', label: '能力值', count: ABILITY_VALUE_COUNT, color: 'violet' },
];

interface EncyclopediaItem {
  id: string;
  nameZh: string;
  nameEn: string;
  type: string;
  positions: string;
  descriptionZh: string;
  descriptionEn: string;
  notes: string | null;
}

function normalizeItems(
  data: any[],
  categoryKey: CategoryKey,
): EncyclopediaItem[] {
  return data.map((item: any) => {
    const isAiOrTeam =
      categoryKey === 'ai_styles' || categoryKey === 'team_styles';
    const isSkillCategory =
      categoryKey === 'normal_skills' || categoryKey === 'showtime_skills';

    if (isAiOrTeam) {
      return {
        id: item.id,
        nameZh: item.name_cn || '',
        nameEn: item.name_en || '',
        type: item.category || '',
        positions: item.positions || '',
        descriptionZh: item.description_cn || '',
        descriptionEn: item.description_en || '',
        notes: item.notes || null,
      };
    }

    if (isSkillCategory) {
      return {
        id: item.id,
        nameZh: item['中文名'] || '',
        nameEn: item['英文名'] || '',
        type: item['类型'] || '',
        positions: '',
        descriptionZh: item['英文描述'] || '',
        descriptionEn: item['适用位置'] || '',
        notes: item['备注'] || item['日文描述'] || null,
      };
    }

    return {
      id: item.id,
      nameZh: item['中文名'] || '',
      nameEn: item['英文名'] || '',
      type: item['类型'] || '',
      positions: item['适用位置'] || '',
      descriptionZh: item['中文描述'] || '',
      descriptionEn: item['英文描述'] || '',
      notes: item['日文描述'] || null,
    };
  });
}

const GRADE_COLORS: Record<string, string> = {
  A: 'bg-amber-500/30 text-amber-200 border-amber-400/60',
  B: 'bg-blue-500/30 text-blue-200 border-blue-400/60',
  C: 'bg-gray-500/30 text-gray-300 border-gray-400/60',
};

const EncyclopediaPage: React.FC = () => {
  const { t, lang } = useI18n();
  const navigate = useNavigate();
  const location = useLocation();
  const [activeTab, setActiveTab] = useState<CategoryKey>('showtime_skills');
  const [searchKeyword, setSearchKeyword] = useState('');
  const [typeFilter, setTypeFilter] = useState('');
  const [coachTactics, setCoachTactics] = useState<CoachTactic[]>([]);
  const [tacticsLoading, setTacticsLoading] = useState(false);
  const [tacticsError, setTacticsError] = useState<string | null>(null);

  // 导航优先：点主导航“百科”（含已停留在本页时点该标签）产生新 location.key，
  // 回到默认分类并退出搜索 / 类型筛选
  const navKeyRef = useRef<string | null>(null);
  useEffect(() => {
    if (navKeyRef.current === null) { navKeyRef.current = location.key; return; }
    if (navKeyRef.current === location.key) return;
    navKeyRef.current = location.key;
    setActiveTab('showtime_skills');
    setSearchKeyword('');
    setTypeFilter('');
  }, [location.key]);

  const rawItems = (encyclopediaData as any)[activeTab] || [];
  const items = useMemo(
    () => normalizeItems(rawItems, activeTab),
    [rawItems, activeTab],
  );

  // 类型筛选选项
  const typeOptions = useMemo(() => {
    const types = new Set<string>();
    items.forEach((item) => {
      if (item.type) types.add(item.type);
    });
    return Array.from(types).sort();
  }, [items]);

  // 过滤
  const filteredItems = useMemo(() => {
    return items.filter((item) => {
      // 全平台隐藏技能（如内侧反弹）不在百科列表显示；底层数据保留
      if (isHiddenSkill(item.nameZh) || isHiddenSkill(item.nameEn)) {
        return false;
      }
      if (
        searchKeyword &&
        !item.nameZh.toLowerCase().includes(searchKeyword.toLowerCase())
      ) {
        return false;
      }
      if (typeFilter && item.type !== typeFilter) {
        return false;
      }
      return true;
    });
  }, [items, searchKeyword, typeFilter]);

  // 教练战术数据获取
  useEffect(() => {
    if (activeTab !== 'coach_tactics') return;
    if (coachTactics.length > 0) return;
    const fetchTactics = async () => {
      setTacticsLoading(true);
      setTacticsError(null);
      try {
        const res = await coachTacticsApi.getCoachTacticList({
          pageSize: 50,
        });
        setCoachTactics(res.items);
      } catch (error) {
        logger.error('获取教练战术列表失败', error);
        setTacticsError(t('enc.tacticsFail'));
      } finally {
        setTacticsLoading(false);
      }
    };
    fetchTactics();
  }, [activeTab, coachTactics.length]);

  // 教练战术后分组
  const tacticGroups = useMemo(() => {
    const groups = new Map<string, CoachTactic[]>();
    const filtered = coachTactics.filter((t) => {
      if (!searchKeyword) return true;
      return t.nameZh.toLowerCase().includes(searchKeyword.toLowerCase());
    });
    for (const tactic of filtered) {
      const key = tactic.nameZh;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key)!.push(tactic);
    }
    return Array.from(groups.entries()).sort((a, b) => b[1].length - a[1].length);
  }, [coachTactics, searchKeyword]);

  const isStCategory = activeTab === 'showtime_skills';
  const isSkillTab =
    activeTab === 'normal_skills' || activeTab === 'showtime_skills';
  const isTacticCategory = activeTab === 'coach_tactics';
  const isAbilityCategory = activeTab === 'ability_values';
  const tabConfig = CATEGORIES.find((c) => c.key === activeTab)!;

  const scrollToAbility = (anchor: string) => {
    setTimeout(() => {
      const el = document.getElementById(`ability-${anchor}`);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }, 50);
  };

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const tab = params.get('tab') as CategoryKey | null;
    const ability = params.get('ability');
    if (tab && CATEGORIES.some((c) => c.key === tab)) {
      setActiveTab(tab);
      setTypeFilter('');
      if (ability && tab === 'ability_values') {
        scrollToAbility(ability);
      }
    }
  }, [location.search]);

  const handleCardClick = (item: EncyclopediaItem) => {
    navigate(`/encyclopedia/${activeTab}/${item.id}`);
  };

  return (
    <div className="min-h-screen text-white">
      {/* 页面标题 */}
      <div className="mb-3 flex items-center gap-2">
        <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-cyan-500 to-purple-600 shadow-[0_0_20px_rgba(34_211_238_0.4)]">
          <BookOpen className="h-5 w-5 text-white" />
        </div>
        <div>
           <h1 className="text-3xl font-bold text-white text-glow-cyan">
              {t('enc.title')}
            </h1>
            <p className="text-xl text-gray-400">
              {t('enc.subtitle')}
            </p>
        </div>
      </div>

      {/* Tab 切换 */}
      <div className="mb-2.5 flex flex-wrap gap-2">
        {CATEGORIES.map((cat) => {
          const active = cat.key === activeTab;
          const isMagenta = cat.color === 'magenta';
          return (
             <button
               key={cat.key}
               onClick={() => {
                 setActiveTab(cat.key);
                 setTypeFilter('');
               }}
                className={`rounded-lg px-3 py-1.5 text-2xl font-medium transition-all border ${
                 active
                   ? isMagenta
                     ? 'bg-pink-500/35 text-pink-100 border-pink-400/70 shadow-[0_0_14px_rgba(236_72_153_0.5)]'
                     : cat.color === 'teal'
                       ? 'bg-teal-500/35 text-teal-50 border-teal-400/70 shadow-[0_0_14px_rgba(20_184_166_0.5)]'
                       : cat.color === 'violet'
                         ? 'bg-violet-500/35 text-violet-100 border-violet-400/70 shadow-[0_0_14px_rgba(139_92_246_0.5)]'
                         : 'bg-cyan-500/35 text-cyan-50 border-cyan-400/70 shadow-[0_0_14px_rgba(34_211_238_0.5)]'
                   : 'bg-[#141838]/50 text-white/70 border-white/10 hover:text-white hover:border-white/20'
               }`}
             >
                {t('enc.cat.' + cat.key)}
                <span className="ml-1 text-lg opacity-60">({cat.count})</span>
             </button>
          );
        })}
      </div>

      {/* 搜索 + 筛选 */}
      <div className="mb-2.5 flex flex-row gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-500" />
          <input
            type="text"
            value={searchKeyword}
            onChange={(e) => setSearchKeyword(e.target.value)}
            placeholder={t('enc.searchPh')}
             className={`w-full pl-9 pr-3 py-2 rounded-lg bg-[#141838]/60 border border-white/10 text-white text-xl placeholder:text-gray-600 focus:outline-none ${
               isTacticCategory
                 ? 'focus:border-teal-400/50'
                 : 'focus:border-cyan-400/50'
             }`}
          />
        </div>
         {!isTacticCategory && !isAbilityCategory && typeOptions.length > 0 && (
          <select
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
             className="px-3 py-2 rounded-lg bg-[#141838]/60 border border-white/10 text-white text-xl focus:outline-none focus:border-cyan-400/50 cursor-pointer"
          >
            <option value="">{t('enc.allTypes')}</option>
            {typeOptions.map((tp) => (
              <option key={tp} value={tp}>
                {trTerm(tp)}
              </option>
            ))}
          </select>
        )}
      </div>

       {/* 能力值展示 */}
       {isAbilityCategory ? (
         <div className="space-y-6">
           {ABILITY_VALUE_GROUPS.map((group) => (
             <div key={group.groupKey}>
               <div className="mb-3 flex items-center gap-2">
                 <div className="h-5 w-1 rounded-full bg-gradient-to-b from-violet-400 to-indigo-500" />
                 <h2 className="text-5xl font-bold text-violet-200">
                   {lang === 'en' ? t('av.group.' + group.groupKey) : group.groupName}
                 </h2>
                 <span className="text-lg text-gray-500">
                   ({group.items.length}{t('enc.items')})
                 </span>
               </div>
                <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
                  {group.items.map((item) => (
                    <Link
                      key={item.key}
                      to={`/encyclopedia/ability/${item.key}`}
                      state={{ from: '/encyclopedia?tab=ability_values' }}
                      className="rounded-xl p-4 border border-violet-400/30 bg-gradient-to-br from-violet-500/10 to-indigo-600/5 backdrop-blur-sm transition-all duration-300 hover:border-violet-400/60 hover:shadow-[0_0_20px_rgba(139_92_246_0.3)] block group"
                    >
                       <h3 className="text-xl md:text-2xl font-bold text-white mb-2 flex items-center justify-between">
                         {lang === 'en' ? trTerm(item.name) : item.name}
                         <ChevronRight className="w-4 h-4 text-violet-400/60 group-hover:text-violet-300 transition-colors" />
                       </h3>
                      <p className="text-xl md:text-2xl text-gray-300 leading-relaxed line-clamp-2">
                        {lang === 'en' ? t('av.desc.' + item.key) : item.description}
                      </p>
                    </Link>
                  ))}
                </div>
             </div>
           ))}
         </div>
       ) : isTacticCategory ? (
        tacticsLoading ? (
          <div className="text-center py-16">
            <p className="text-gray-500 text-xl">{t('enc.loading')}</p>
          </div>
        ) : tacticsError ? (
          <div className="text-center py-16">
            <p className="text-red-400 text-xl">{tacticsError}</p>
          </div>
        ) : tacticGroups.length === 0 ? (
          <div className="text-center py-16">
            <p className="text-gray-500 text-xl">{t('enc.noResult')}</p>
          </div>
        ) : (
          <div className="space-y-5">
            {/* ===== 科普卡片：教练战术熟练度 → 球员能力加成 ===== */}
            <div className="rounded-2xl border border-teal-300/40 bg-gradient-to-br from-teal-500/15 via-cyan-600/10 to-slate-900/40 p-5 md:p-6 shadow-[0_0_30px_rgba(20_184_166_0.15)]">
              <div className="mb-3 flex items-center gap-2.5">
                <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-teal-500/25">
                  <BookOpen className="h-5 w-5 text-teal-200" />
                </span>
                <h3 className="text-2xl md:text-3xl font-bold text-white">
                  {t('enc.sci.title')}
                </h3>
              </div>

              <p className="text-lg md:text-xl text-gray-300 leading-relaxed">
                {t('enc.sci.p1a')}
                <span className="text-teal-200 font-semibold">{t('enc.sci.p1b')}</span>
                {t('enc.sci.p1c')}
                <span className="text-teal-200 font-semibold">{t('enc.sci.p1d')}</span>
                {t('enc.sci.p1e')}
              </p>

              <p className="mt-3 text-lg md:text-xl text-gray-300 leading-relaxed">
                {t('enc.sci.p2a')}<span className="text-amber-300 font-semibold">{t('enc.sci.p2b')}</span>{t('enc.sci.p2c')}
              </p>

              <div className="mt-4 overflow-x-auto rounded-xl border border-teal-400/20">
                <table className="w-full min-w-[560px] border-collapse text-center text-base md:text-lg">
                  <thead>
                    <tr className="bg-teal-500/20 text-teal-100">
                      <th className="px-3 py-2.5 font-semibold">{t('enc.sci.colTop')}</th>
                      <th className="px-3 py-2.5 font-semibold">{t('enc.sci.col1')}</th>
                      <th className="px-3 py-2.5 font-semibold">{t('enc.sci.col2')}</th>
                      <th className="px-3 py-2.5 font-semibold">{t('enc.sci.col3')}</th>
                    </tr>
                  </thead>
                  <tbody className="text-gray-200">
                    {[
                      { s: 88, a: '≤ 56', b: '57 ~ 84', c: '≥ 85' },
                      { s: 89, a: '≤ 55', b: '56 ~ 83', c: '≥ 84' },
                      { s: 90, a: '≤ 54', b: '55 ~ 82', c: '≥ 83' },
                    ].map((r, i) => (
                      <tr key={r.s} className={i % 2 ? 'bg-white/[0.03]' : 'bg-white/[0.06]'}>
                        <td className="px-3 py-2.5 font-bold text-teal-200">{r.s}</td>
                        <td className="px-3 py-2.5">{r.a}</td>
                        <td className="px-3 py-2.5">{r.b}</td>
                        <td className="px-3 py-2.5 font-semibold text-amber-300">{r.c}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <p className="mt-4 text-base md:text-lg text-gray-400 leading-relaxed">
                {t('enc.sci.p3a')}<span className="font-mono text-teal-200">173 − S</span>{t('enc.sci.p3b')}<span className="font-mono text-teal-200">145 − S</span>{t('enc.sci.p3c')}
              </p>
            </div>

            {tacticGroups.map(([groupName, tactics]) => (
              <div key={groupName}>
                <div className="mb-2 flex items-center gap-2">
                  <div className="h-5 w-1 rounded-full bg-gradient-to-b from-teal-400 to-cyan-500" />
                  <h2 className="text-5xl font-bold text-teal-200">
                    {lang === 'en' ? tactics[0].nameEn : groupName}
                  </h2>
                  <span className="text-lg text-gray-500">
                    ({tactics.length}{t('enc.kinds')})
                  </span>
                </div>
                 <div className="grid grid-cols-1 gap-3 md:grid-cols-2 lg:grid-cols-3">
                   {tactics.map((tactic) => (
                     <Link
                       key={tactic.id}
                       to={`/encyclopedia/coach-tactic/${tactic.id}`}
                       state={{ from: '/encyclopedia?tab=coach_tactics' }}
                       className="relative rounded-xl p-3 border border-teal-400/30 bg-gradient-to-br from-teal-500/10 to-cyan-600/5 backdrop-blur-sm transition-all duration-300 hover:border-teal-400/60 hover:shadow-[0_0_20px_rgba(20_184_166_0.3)] hover:-translate-y-0.5 group"
                     >
                       {/* 顶部：名称 + 等级标签 */}
                       <div className="mb-1.5 flex items-start justify-between">
                         <h3 className="text-lg md:text-xl font-bold text-white leading-tight">
                           {lang === 'en' ? tactic.nameEn : tactic.nameZh}
                         </h3>
                         <span
                           className={`text-base font-bold px-1.5 py-0.5 rounded border ${
                             GRADE_COLORS[tactic.grade] ||
                             GRADE_COLORS.C
                           }`}
                         >
                           {tactic.grade}{lang === 'en' ? '' : t('enc.gradeSuffix')}
                         </span>
                       </div>

                       {/* 另一语言名 */}
                       <p className="mb-2.5 text-lg text-gray-500">
                         {lang === 'en' ? tactic.nameZh : tactic.nameEn}
                       </p>

                      {/* 核心球员 + 关键球员 */}
                       <div className="mb-2.5 space-y-1.5">
                         {tactic.coreStyleZh && tactic.corePosition && (
                           <div className="flex items-center gap-1.5">
                             <div className="flex h-5 w-5 items-center justify-center rounded bg-teal-500/30">
                               <Users className="h-3 w-3 text-teal-300" />
                             </div>
                             <span className="text-base text-gray-400">{t('enc.core')}</span>
                             <span className="text-lg font-medium text-teal-100">
                               {lang === 'en' ? tactic.coreStyleEn : tactic.coreStyleZh}
                             </span>
                             {lang !== 'en' && tactic.coreStyleEn && (
                               <span className="text-base text-teal-400/70">
                                 {tactic.coreStyleEn}
                               </span>
                             )}
                             <span className="text-base text-gray-400">
                               · {tactic.corePosition}
                             </span>
                           </div>
                         )}
                         {tactic.keyStyleZh && tactic.keyPosition && (
                           <div className="flex items-center gap-1.5">
                             <div className="flex h-5 w-5 items-center justify-center rounded bg-cyan-500/30">
                               <Zap className="h-3 w-3 text-cyan-300" />
                             </div>
                             <span className="text-base text-gray-400">{t('enc.key')}</span>
                             <span className="text-lg font-medium text-cyan-100">
                               {lang === 'en' ? tactic.keyStyleEn : tactic.keyStyleZh}
                             </span>
                             {lang !== 'en' && tactic.keyStyleEn && (
                               <span className="text-base text-cyan-400/70">
                                 {tactic.keyStyleEn}
                               </span>
                             )}
                             <span className="text-base text-gray-400">
                               · {tactic.keyPosition}
                             </span>
                           </div>
                         )}
                       </div>

                       {/* 描述 */}
                       {(tactic.descriptionCn || tactic.descriptionEn) && (
                         <div className="flex items-start justify-between gap-2">
                           <p
                             className="text-lg md:text-xl text-gray-400 leading-relaxed flex-1"
                             style={{
                               display: '-webkit-box',
                               WebkitLineClamp: 3,
                               WebkitBoxOrient: 'vertical',
                               overflow: 'hidden',
                             }}
                           >
                             {lang === 'en' ? tactic.descriptionEn : tactic.descriptionCn}
                           </p>
                           <ChevronRight className="w-4 h-4 text-teal-400/60 group-hover:text-teal-300 transition-colors flex-shrink-0 mt-1" />
                         </div>
                       )}
                     </Link>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )
      ) : (
        /* 原有百科卡片网格 */
        filteredItems.length === 0 ? (
          <div className="text-center py-16">
             <p className="text-gray-500 text-xl">{t('enc.noResult')}</p>
          </div>
        ) : (
          <div className="grid grid-cols-4 gap-2">
            {filteredItems.map((item) => (
              <div
                key={item.id}
                onClick={() => handleCardClick(item)}
                className={`relative rounded-xl p-2 cursor-pointer transition-all duration-300 hover:-translate-y-1 border backdrop-blur-sm ${
                  isStCategory
                    ? 'border-pink-400/50 bg-gradient-to-br from-pink-500/10 to-purple-600/10 hover:border-pink-400/80 hover:shadow-[0_0_25px_rgba(236_72_153_0.5)]'
                    : 'border-cyan-400/30 bg-[#141838]/50 hover:border-cyan-400/60 hover:shadow-[0_0_20px_rgba(34_211_238_0.35)]'
                }`}
              >
                {/* ST 徽章 */}
                {isStCategory && (
                   <div className="absolute -top-1 -right-1 z-20 flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-pink-500 to-rose-600 text-lg font-bold text-white shadow-[0_0_10px_rgba(236_72_153_0.6)]">
                     ST
                   </div>
                )}

                {/* 技能场景配图（仅技能分类；风格类不显示图区。无图给等比占位，保持卡片高度一致） */}
                {isSkillTab &&
                  (skillIconUrl(item.id) ? (
                    <div className="relative overflow-hidden rounded-lg mb-2 border border-white/10 bg-white/5">
                      <img
                        src={skillIconUrl(item.id)!}
                        alt={lang === 'en' ? item.nameEn : item.nameZh}
                        loading="lazy"
                        className="w-full aspect-[288/173] object-cover"
                      />
                      <span className="absolute bottom-0.5 right-1 px-1 rounded bg-black/35 text-white/75 text-[7px] leading-tight pointer-events-none">
                        {lang === 'en'
                          ? 'Images sourced from the internet'
                          : '图片素材来自网络'}
                      </span>
                    </div>
                  ) : (
                    <div className="w-full aspect-[288/173] rounded-lg mb-2 bg-white/5" />
                  ))}

                <div className="flex items-start justify-between mb-2">
                    <h3
                      className={`whitespace-nowrap text-3xl font-bold leading-tight ${
                       isStCategory ? 'text-pink-200' : 'text-white'
                      }`}
                    >
                      {lang === 'en' ? item.nameEn : item.nameZh}
                    </h3>
                </div>

                  <p className="text-xl text-gray-500 mb-2">{lang === 'en' ? item.nameZh : item.nameEn}</p>

                <div className="flex flex-wrap gap-1.5 mb-2.5">
                  {item.type && (
                    <span
                       className={`text-lg px-2 py-0.5 rounded-full border font-semibold ${
                          isStCategory
                            ? 'border-pink-400/60 text-pink-100 bg-pink-500/25'
                            : 'border-cyan-400/60 text-cyan-100 bg-cyan-500/25'
                        }`}
                   >
                     {trTerm(item.type)}
                   </span>
                  )}
                  {item.positions && (
                      <span className="text-lg px-2 py-0.5 rounded-full border border-white/20 text-gray-300 bg-white/10 font-medium">
                       {item.positions}
                     </span>
                  )}
                </div>

                  <p
                    className="text-xl text-gray-400 leading-relaxed line-clamp-2"
                   style={{
                     display: '-webkit-box',
                     WebkitLineClamp: 2,
                     WebkitBoxOrient: 'vertical',
                     overflow: 'hidden',
                   }}
                 >
                   {lang === 'en' ? item.descriptionEn : item.descriptionZh}
                 </p>
              </div>
            ))}
          </div>
        )
      )}
    </div>
  );
};

export default EncyclopediaPage;
