const STYLE_LABELS: { key: keyof StyleProficiency; label: string }[] = [
  { key: 'possession', label: '控球游戏' },
  { key: 'longBallCounter', label: '长传反击' },
  { key: 'quickCounter', label: '快速反攻' },
  { key: 'longPass', label: '长传球' },
  { key: 'wide', label: '外侧' },
  { key: 'outWide', label: '压上进攻' },
];

// 风格 key → 中文名映射（用于 linkup_tactics 等可能传英文 key 的场景）
const STYLE_LABEL_MAP: Record<string, string> = STYLE_LABELS.reduce(
  (acc, { key, label }) => {
    acc[key] = label;
    return acc;
  },
  {} as Record<string, string>,
);

function getStyleLabel(styleKey: string): string {
  return STYLE_LABEL_MAP[styleKey] ?? styleKey;
}

function getGradeBadgeClass(grade: string): string {
  switch (grade) {
    case 'S':
      return 'bg-gradient-to-br from-pink-500 to-rose-600 text-white border-pink-400/60 shadow-[0_0_16px_rgba(236_72_153_0.5)] text-glow-magenta';
    case 'A':
      return 'bg-gradient-to-br from-cyan-400 to-cyan-600 text-white border-cyan-400/60 shadow-[0_0_14px_rgba(34_211_238_0.5)] text-glow-cyan';
    case 'B':
      return 'bg-gradient-to-br from-violet-500 to-purple-600 text-white border-violet-400/60 shadow-[0_0_12px_rgba(139_92_246_0.4)]';
    case 'C':
      return 'bg-white/10 text-white/60 border-white/20';
    default:
      return 'bg-white/10 text-white/60 border-white/20';
  }
}

function getInitial(nameZh: string, nameEn: string | null): string {
  if (nameZh && nameZh.length > 0) return nameZh.charAt(0);
  if (nameEn && nameEn.length > 0) return nameEn.charAt(0).toUpperCase();
  return '?';
}

// 位置映射到球场坐标 (百分比：x 横向 0-100, y 纵向 0-100)
function positionToCoord(position: string): { x: number; y: number } {
  const pos = position || '';
  // 简化映射
  if (pos.includes('CF') || pos.includes('中锋') || pos.includes('ST')) return { x: 85, y: 50 };
  if (pos.includes('SS') || pos.includes('影锋')) return { x: 75, y: 50 };
  if (pos.includes('LWF') || pos.includes('左边锋')) return { x: 80, y: 20 };
  if (pos.includes('RWF') || pos.includes('右边锋')) return { x: 80, y: 80 };
  if (pos.includes('AMF') || pos.includes('前腰')) return { x: 65, y: 50 };
  if (pos.includes('LMF') || pos.includes('左前卫')) return { x: 55, y: 15 };
  if (pos.includes('RMF') || pos.includes('右前卫')) return { x: 55, y: 85 };
  if (pos.includes('CMF') || pos.includes('中前卫')) return { x: 50, y: 50 };
  if (pos.includes('DMF') || pos.includes('后腰')) return { x: 35, y: 50 };
  if (pos.includes('LB') || pos.includes('左后卫')) return { x: 25, y: 15 };
  if (pos.includes('RB') || pos.includes('右后卫')) return { x: 25, y: 85 };
  if (pos.includes('CB') || pos.includes('中后卫')) return { x: 15, y: 50 };
  if (pos.includes('GK') || pos.includes('门将')) return { x: 5, y: 50 };
  return { x: 50, y: 50 };
}

interface FootballPitchProps {
  centerPosition: string;
  keyPosition: string;
}

const FootballPitch: React.FC<FootballPitchProps> = ({
  centerPosition,
  keyPosition,
}) => {
  const center = positionToCoord(centerPosition);
  const key = positionToCoord(keyPosition);

  const width = 300;
  const height = 180;

  const cx = (center.x / 100) * width;
  const cy = (center.y / 100) * height;
  const kx = (key.x / 100) * width;
  const ky = (key.y / 100) * height;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className="w-full rounded-lg"
      xmlns="http://www.w3.org/2000/svg"
    >
      {/* Pitch background */}
      <defs>
        <linearGradient id="pitchGradient" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stopColor="#166534" />
          <stop offset="100%" stopColor="#14532d" />
        </linearGradient>
        <pattern
          id="pitchPattern"
          patternUnits="userSpaceOnUse"
          width={width / 8}
          height={height}
        >
          <rect width={width / 16} height={height} fill="#15803d" opacity="0.4" />
        </pattern>
      </defs>
      <rect
        x="1"
        y="1"
        width={width - 2}
        height={height - 2}
        rx="4"
        fill="url(#pitchGradient)"
        stroke="#22c55e"
        strokeOpacity="0.4"
        strokeWidth="1"
      />
      <rect
        x="1"
        y="1"
        width={width - 2}
        height={height - 2}
        rx="4"
        fill="url(#pitchPattern)"
        opacity="0.5"
      />

      {/* Center line */}
      <line
        x1={width / 2}
        y1="2"
        x2={width / 2}
        y2={height - 2}
        stroke="#ffffff"
        strokeOpacity="0.5"
        strokeWidth="1"
      />
      {/* Center circle */}
      <circle
        cx={width / 2}
        cy={height / 2}
        r="25"
        stroke="#ffffff"
        strokeOpacity="0.5"
        strokeWidth="1"
        fill="none"
      />
      <circle
        cx={width / 2}
        cy={height / 2}
        r="2"
        fill="#ffffff"
        fillOpacity="0.6"
      />

      {/* Left penalty area */}
      <rect
        x="2"
        y={height / 2 - 40}
        width="40"
        height="80"
        stroke="#ffffff"
        strokeOpacity="0.4"
        strokeWidth="1"
        fill="none"
      />
      <rect
        x="2"
        y={height / 2 - 20}
        width="15"
        height="40"
        stroke="#ffffff"
        strokeOpacity="0.4"
        strokeWidth="1"
        fill="none"
      />
      <line x1="2" y1={height / 2 - 5} x2="6" y2={height / 2 - 5} stroke="#ffffff" strokeOpacity="0.5" strokeWidth="1" />
      <line x1="2" y1={height / 2 + 5} x2="6" y2={height / 2 + 5} stroke="#ffffff" strokeOpacity="0.5" strokeWidth="1" />

      {/* Right penalty area */}
      <rect
        x={width - 42}
        y={height / 2 - 40}
        width="40"
        height="80"
        stroke="#ffffff"
        strokeOpacity="0.4"
        strokeWidth="1"
        fill="none"
      />
      <rect
        x={width - 17}
        y={height / 2 - 20}
        width="15"
        height="40"
        stroke="#ffffff"
        strokeOpacity="0.4"
        strokeWidth="1"
        fill="none"
      />
      <line x1={width - 2} y1={height / 2 - 5} x2={width - 6} y2={height / 2 - 5} stroke="#ffffff" strokeOpacity="0.5" strokeWidth="1" />
      <line x1={width - 2} y1={height / 2 + 5} x2={width - 6} y2={height / 2 + 5} stroke="#ffffff" strokeOpacity="0.5" strokeWidth="1" />

      {/* Linkup line */}
      <line
        x1={cx}
        y1={cy}
        x2={kx}
        y2={ky}
        stroke="#fbbf24"
        strokeWidth="2"
        strokeDasharray="4 3"
        opacity="0.8"
      />

      {/* Center point */}
      <circle cx={cx} cy={cy} r="7" fill="#8b5cf6" stroke="#ffffff" strokeWidth="1.5" />
      <text
        x={cx}
        y={cy - 10}
        textAnchor="middle"
        fontSize="9"
        fill="#ffffff"
        fontWeight="bold"
      >
        Center
      </text>

      {/* Key point */}
      <circle cx={kx} cy={ky} r="7" fill="#f59e0b" stroke="#ffffff" strokeWidth="1.5" />
      <text
        x={kx}
        y={ky - 10}
        textAnchor="middle"
        fontSize="9"
        fill="#ffffff"
        fontWeight="bold"
      >
        Key
      </text>
    </svg>
  );
};

