const CoachDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { t } = useI18n();
  const { user, getAuthHeaders } = useAuth();
  const { allowLocalAction } = useLoginGuard();
  const [coach, setCoach] = useState<Coach | null>(null);
  const [loading, setLoading] = useState(true);
  const [imgError, setImgError] = useState(false);
  const hasCardImage = coach?.cardImageUrl && !imgError;
  const [error, setError] = useState<string | null>(null);
  const [ratingSummary, setRatingSummary] = useState<RatingSummary | null>(null);
  const [ratingLoading, setRatingLoading] = useState(false);
  // 游客本机评分（kind='rating'，key=`coach:${id}`）；已登录走云端 ratingSummary.userScore
  const [visitorScore, setVisitorScore] = useState<number | null>(null);
  const phone = useIsNarrowScreen();

  useEffect(() => {
    if (!id) return;

    let cancelled = false;
    setLoading(true);
    setError(null);

    getCoachDetail(id)
      .then((data: Coach) => {
        if (!cancelled) {
          setCoach(data);
        }
      })
      .catch((err: unknown) => {
        if (!cancelled) {
          logger.error('加载教练详情失败', err);
          setError(t('加载失败，请稍后重试'));
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [id]);

  // 加载评分
  useEffect(() => {
    if (!id) return;
    ratings
      .getSummary('coach', id)
      .then((data) => {
        setRatingSummary(data);
        // 游客：读取本机评分作为展示分（average/count 仍为服务端值）
        if (!user) {
          const local = visitorLocalGet('rating', `coach:${id}`);
          setVisitorScore(local ? Number(local) : null);
        }
      })
      .catch((err) => {
        logger.error('加载评分失败', err);
      });
  }, [id, user]);

  const handleRate = async (score: number) => {
    if (!allowLocalAction('评分')) return;
    if (!coach) return;
    // 游客：仅本机评分，不发云端请求
    if (!user) {
      visitorLocalSet('rating', `coach:${coach.id}`, score);
      setVisitorScore(score);
      toastVisitorLocal('rating');
      return;
    }
    setRatingLoading(true);
    try {
      const res = await ratings.submit(
        { targetType: 'coach', targetId: coach.id, score },
        getAuthHeaders(),
      );
      setRatingSummary(res);
    } catch (error) {
      logger.error('评分失败', error);
    } finally {
      setRatingLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
     <div className="text-center">
           <Loader2 className="mx-auto mb-4 h-12 w-12 animate-spin text-cyan-400" />
          <p className="text-base text-gray-400">{t('加载中...')}</p>
        </div>
      </div>
    );
  }

  if (error || !coach) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <div className="text-center">
          <p className="mb-4 text-gray-400">{error || t('教练不存在')}</p>
          <button
            onClick={() => navigate(-1)}
             className="rounded-lg bg-primary text-primary-foreground px-4 py-2 text-base font-medium hover:opacity-90 transition-opacity"
          >
            {t('返回')}
          </button>
        </div>
      </div>
    );
  }

  const gradeClass = getGradeBadgeClass(coach.grade);
  const bonuses: ManagerBonus[] = coach.managerBonus || [];
  const linkupTactics: LinkupTactic[] = coach.linkupTactics || [];

  return (
    <div className="relative">
      {/* 顶部渐变装饰 */}
       <div className="fixed top-0 left-0 right-0 h-64 bg-gradient-to-b from-cyan-500/10 to-transparent pointer-events-none -z-0" />

      <div className="relative z-10 mx-auto max-w-4xl space-y-2.5 px-2 py-2.5">
        {/* 顶部区 */}
         <div className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-[#141838] via-[#1a1f45] to-[#141838] border border-white/10 shadow-[0_0_30px_rgba(0_229_255_0.1)]">
           <div className="absolute top-0 right-0 w-64 h-64 bg-cyan-400/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
           <div className="absolute bottom-0 left-0 w-48 h-48 bg-pink-500/10 rounded-full blur-3xl translate-y-1/2 -translate-x-1/2" />

          <div className="relative p-3">
            {/* 返回按钮 */}
            <button
              onClick={() => navigate('/coaches')}
              className="flex items-center gap-1 text-gray-400 hover:text-white transition-colors mb-4"
            >
              <ArrowLeft className="w-4 h-4" />
              <span className="text-base">{t('返回教练列表')}</span>
            </button>

              <div className="flex flex-row gap-3">
                {/* 左侧：教练卡面大图 */}
                <div className="w-1/3 flex-shrink-0">
                  <div className="relative w-full rounded-2xl bg-gradient-to-b from-[#1a2350] to-[#0d1230] shadow-lg box-glow-cyan border border-cyan-400/30 overflow-hidden aspect-square">
                    <div className="absolute inset-0 bg-gradient-to-b from-cyan-500/5 via-transparent to-transparent pointer-events-none" />
                    {hasCardImage ? (
                      <Image
                        src={coach.cardImageUrl!}
                        alt={coach.nameZh}
                        className="absolute inset-0 w-full h-full object-cover object-top"
                        onError={() => setImgError(true)}
                      />
                    ) : (
                      <div className="absolute inset-0 flex items-center justify-center">
                        <span className="text-5xl font-bold text-white drop-shadow-lg">
                          {getInitial(coach.nameZh, coach.nameEn)}
                        </span>
                      </div>
                    )}

                    {/* 左上角：等级徽章 */}
                    <div className="absolute top-2 left-2 z-10 flex flex-col items-start">
                      <span
                        className={`text-3xl font-black leading-none drop-shadow-[0_2px_6px_rgba(0_0_0_0.8)] w-9 h-9 flex items-center justify-center rounded-full border-2 border-white/50 bg-black/30 ${gradeClass}`}
                      >
                        {coach.grade}
                      </span>
                    </div>

                  </div>

                  {/* 卡面图下方：教练姓名 */}
                   <div className="mt-3 flex flex-col items-center">
                     <div className="flex items-center gap-2">
                       <p className="text-lg font-bold text-white truncate">
                         {coach.nameZh}
                       </p>
                       <FavoriteButton targetType="coach" targetId={coach.id} size="sm" />
                     </div>
                     {coach.nameEn && (
                       <p className="mt-0.5 text-sm text-gray-300 truncate">
                         {coach.nameEn}
                       </p>
                     )}
                   </div>
                </div>

                {/* 右侧：教练信息 */}
                <div className="flex-1 min-w-0 flex flex-col justify-between">
                  {/* 顶部：评分区 + 返回（已在外面） */}
                  <div className="flex justify-end mb-1">
                    {ratingSummary ? (
                      <div>
                        <RatingStars
                          value={
                            !user
                              ? (visitorScore ?? ratingSummary.average)
                              : (ratingSummary.userScore ?? ratingSummary.average)
                          }
                          count={ratingSummary.count}
                          interactive
                          size="md"
                          onRate={handleRate}
                        />
                         {ratingLoading && (
                           <p className="text-lg text-gray-500 mt-1 text-right">{t('提交中...')}</p>
                         )}
                      </div>
                    ) : (
                      <Loader2 className="w-4 h-4 text-cyan-400 animate-spin" />
                    )}
                  </div>

                   {/* 教练信息网格 */}
                   <div className="grid grid-cols-2 gap-2">
                     {coach.age !== null && coach.age !== undefined && (
                       <div className="rounded-xl border border-white/10 bg-[#1a1f45]/60 p-2">
                         <p className="text-sm text-gray-500 mb-0.5">{t('年龄')}</p>
                         <p className="text-4xl font-semibold text-white">{coach.age} {t('岁')}</p>
                       </div>
                     )}
                     {coach.type && (
                       <div className="rounded-xl border border-white/10 bg-[#1a1f45]/60 p-2">
                         <p className="text-sm text-gray-500 mb-0.5">{t('类型')}</p>
                         <p className="text-base font-semibold text-pink-300">{t(coach.type)}</p>
                       </div>
                     )}
                     {coach.fitType && (
                       <div className="rounded-xl border border-white/10 bg-[#1a1f45]/60 p-2">
                         <p className="text-sm text-gray-500 mb-0.5">{t('培育契合度')}</p>
                         <p className="text-base font-semibold text-emerald-300">{t(coach.fitType)}</p>
                       </div>
                     )}
                   </div>

                    {/* 主教练加成 */}
                    {bonuses.length > 0 && (
                      <div className="mt-2">
                        <h3 className="mb-2 text-lg font-bold text-emerald-300">{t('主教练增能')}</h3>
                        <div className="grid grid-cols-2 gap-2">
                          {bonuses.map((bonus: ManagerBonus, idx: number) => (
                            <div
                              key={idx}
                              className="flex items-center gap-2 rounded-xl border border-white/10 bg-gradient-to-br from-[#1a1f45]/80 to-[#0A0E27]/80 p-2"
                            >
                              <div className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-emerald-500/20 to-emerald-600/20 text-xl">
                                ⚡
                              </div>
                              <div className="flex-1 min-w-0">
                                <p className="text-lg font-semibold text-gray-200 truncate">
                                  {t(bonus.label)}
                                </p>
                                <p className="text-4xl font-black text-emerald-400">
                                  +{bonus.value}
                                </p>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                </div>
              </div>
          </div>
        </div>

        {/* 球队风格熟练度 */}
         <div className="rounded-2xl border border-white/10 bg-card/80 p-3 backdrop-blur-sm">
           <h2 className="mb-4 text-3xl font-bold text-white">{t('球队风格熟练度')}</h2>
           <div className="space-y-2">
            {STYLE_LABELS.map(({ key, label }) => {
              const value = coach.styleProficiency[key];
              const barColor = getStyleColor(value);
              const textColor = getStyleTextColor(value);
              return (
                <div key={key} className="flex items-center gap-3">
                   <span className={`${phone ? 'w-24 text-2xl' : 'w-28 text-lg'} shrink-0 text-gray-300`}>
                    {t(label)}
                  </span>
                  <div className="relative h-3 flex-1 overflow-hidden rounded-full bg-cyan-950/40">
                    <div
                      className={`h-full rounded-full transition-all ${barColor}`}
                      style={{ width: `${value}%` }}
                    />
                  </div>
                   <span
                     className={`${phone ? 'w-14 text-2xl' : 'w-12 text-xl'} shrink-0 text-right font-bold ${textColor}`}
                   >
                    {value}
                  </span>
                </div>
              );
            })}
          </div>
        </div>

         {/* 教练战术（LINK-UP） */}
            <div className="rounded-2xl border border-white/10 bg-card/80 p-3 backdrop-blur-sm">
              <h2 className="mb-4 flex items-center gap-2 text-3xl font-bold text-white">
                <span className="h-5 w-1 rounded-full bg-gradient-to-b from-cyan-400 to-pink-500" />
                {t('教练战术')}
              </h2>
            {linkupTactics.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-8 text-center">
                <p className="text-gray-400">{t('暂无教练战术数据')}</p>
              </div>
            ) : (
             <div className="grid grid-cols-2 gap-2">
               {linkupTactics.map((tactic: LinkupTactic, idx: number) => (
                 <LinkupCard key={idx} tactic={tactic} />
               ))}
             </div>
           )}
         </div>

         {/* 评论区 */}
         {coach && (
           <CommentSection targetType="coach" targetId={coach.id} />
         )}

         {/* 底部留白 */}
        <div className="h-8" />
      </div>
    </div>
  );
};

export default CoachDetailPage;
