import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Sparkles, Award, Lightbulb, X, Plus, Check, Save } from 'lucide-react';
import { toast } from 'sonner';
import { isStSkill, isSameSkill, normalizeSkillForPlayer, normalizeStSkillName } from '../players/player-utils';
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogDescription,
} from '@client/src/components/ui/dialog';
import {
  getMissingRecommendedSkills,
  POSITION_LABEL_MAP,
} from './recommended-skills';
import encyclopediaData from '@client/src/assets/data/encyclopedia.json';
import { useLoginGuard } from '@client/src/hooks/useLoginGuard';
import { useAuth } from '@client/src/context/AuthContext';
import { saveBuildPlan } from '@client/src/api/player-builds';
import { setDraftExtraSkills, getDraftAllocations, getDraftCoach, getDraftSecondBooster, getDraftShine } from '@client/src/utils/build-draft-store';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';
import { filterVisibleSkills, isHiddenSkill } from '@shared/hidden-skills';

interface SkillsListProps {
  skills: string[];
  registeredPosition?: string;
  positionProficiency?: Record<string, number>;
  landscape?: boolean;
  isWeb?: boolean;
  playerId?: string;
}

const SkillsList: React.FC<SkillsListProps> = ({
  skills,
  registeredPosition,
  positionProficiency = {},
  landscape = false,
  isWeb = false,
  playerId,
}) => {
  const { user, requireLogin } = useLoginGuard();
  const { getAuthHeaders } = useAuth();
  const [open, setOpen] = useState(false);
  // 网页横屏：本地新增技能
  const [addOpen, setAddOpen] = useState(false);
  const [extraSkills, setExtraSkills] = useState<string[]>([]);
  const [picked, setPicked] = useState<Set<string>>(new Set());
  const { lang, t } = useI18n();
  // 仅“显示文本”英文化；点击跳转仍用中文 displaySkill，保持百科路由映射不变。
  const shown = (s: string) => (lang === 'en' ? trTerm(s) : s);
  const SKILL_CAT_EN: Record<string, string> = {
    '射门': 'Shooting', '传球': 'Passing', '盘带': 'Dribbling',
    '通用': 'General', '门将': 'Goalkeeping', '防守': 'Defending',
  };
  const catShown = (c: string) => (lang === 'en' ? (SKILL_CAT_EN[c] ?? c) : c);

  const safeSkills: string[] = Array.isArray(skills) ? skills : [];
  // 全平台隐藏技能（如内侧反弹）在显示层剔除；safeSkills 仍保留原始值用于"已掌握"判断，避免系统推荐它
  const visibleSkills = filterVisibleSkills(safeSkills);
  const sortedSkills = [...visibleSkills].sort((a, b) => {
    const aSt = isStSkill(a) ? 0 : 1;
    const bSt = isStSkill(b) ? 0 : 1;
    if (aSt !== bSt) return aSt - bSt;
    return a.localeCompare(b, 'zh-CN');
  });

  const greenPositions: string[] = [];
  if (registeredPosition && !greenPositions.includes(registeredPosition)) {
    greenPositions.push(registeredPosition);
  }
  for (const [key, level] of Object.entries(positionProficiency)) {
    if (level === 2 && !greenPositions.includes(key)) {
      greenPositions.push(key);
    }
  }

  const missing = getMissingRecommendedSkills(greenPositions, safeSkills);
  const totalMissing = missing['1'].length + missing['2'].length + missing['3'].length;

  const groups: { level: '1' | '2' | '3'; title: string; desc: string; color: string }[] = [
    { level: '1', title: '推荐新增', desc: '优先级最高，强烈建议补充', color: 'from-amber-500 to-pink-500' },
    { level: '2', title: '参考新增', desc: '次优先级，可根据打法选择', color: 'from-cyan-500 to-blue-500' },
    { level: '3', title: '可新增', desc: '可选补充，锦上添花', color: 'from-gray-400 to-gray-600' },
  ];

  // 普通技能（非ST）按类型分组，归一为标准名，去重，剔除球员已掌握与已新增（按同技能判定，别名也算）
  const normalSkillGroups = useMemo(() => {
    const ns = (encyclopediaData as { normal_skills: Record<string, unknown>[] }).normal_skills;
    const map = new Map<string, string[]>();
    const seen = new Set<string>(); // 已加入的标准名
    const owned = [...safeSkills, ...extraSkills];
    for (const s of ns) {
      const raw = s['中文名'] as string;
      const cat = s['类型'] as string;
      if (!raw || isHiddenSkill(raw)) continue;
      const name = normalizeSkillForPlayer(raw, registeredPosition); // 别名 → 标准短名（门将按位置区分）
      if (seen.has(name)) continue;                                  // 同一标准名只出现一次
      if (owned.some((o) => isSameSkill(o, name))) continue;        // 球员已拥有（任一别名）则不显示
      seen.add(name);
      if (!map.has(cat)) map.set(cat, []);
      map.get(cat)!.push(name);
    }
    return Array.from(map.entries())
      .map(([cat, names]) => ({ cat, names }))
      .filter((g) => g.names.length > 0);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [safeSkills.join('|'), extraSkills.join('|'), registeredPosition]);

  const navigate = useNavigate();

  // 技能“显示名” → 百科（普通技能 normal_skills / ST 技能 showtime_skills）的 id 映射，
  // 用于点击技能名跳转百科详情页
  const skillLinkMap = useMemo(() => {
    const m = new Map<string, { cat: string; id: string }>();
    const enc = encyclopediaData as {
      normal_skills: Record<string, unknown>[];
      showtime_skills: Record<string, unknown>[];
    };
    (['normal_skills', 'showtime_skills'] as const).forEach((cat) => {
      for (const s of enc[cat]) {
        const name = s['中文名'] as string;
        const id = s.id as string;
        if (name && id && !m.has(name)) m.set(name, { cat, id });
      }
    });
    return m;
  }, []);

  const goSkill = (e: React.MouseEvent, displaySkill: string) => {
    const link = skillLinkMap.get(displaySkill);
    if (!link) return;
    e.stopPropagation();
    navigate(`/encyclopedia/${link.cat}/${link.id}`, {
      state: { from: window.location.pathname + window.location.search },
    });
  };

  const togglePicked = (name: string) => {
    setPicked((prev) => {
      const next = new Set(prev);
      if (next.has(name)) next.delete(name);
      else next.add(name);
      return next;
    });
  };

  const openAddModal = () => {
    setPicked(new Set());
    setAddOpen(true);
  };

  const confirmAdd = () => {
    if (picked.size > 0) {
      setExtraSkills((prev) => {
        const merged = [...prev];
        for (const n of picked) if (!merged.includes(n)) merged.push(n);
        return merged;
      });
    }
    setAddOpen(false);
  };

  // 把当前自定义新增技能同步到共享草稿，供“保存加点”时一并写入
  const savedExtraSkills = useMemo(
    () => extraSkills.filter((n) => !safeSkills.includes(n)),
    [extraSkills, safeSkills],
  );
  useEffect(() => {
    if (playerId) setDraftExtraSkills(playerId, savedExtraSkills);
  }, [playerId, savedExtraSkills]);

  // 个人中心「培养方案」跳转过来时，自动填充该方案保存的“新增技能”（仅一次）。
  // 剔除球员默认已掌握技能与重复项，剩余以黄色自定义技能展示。
  const afLocation = useLocation();
  const appliedSkillSigRef = useRef<string | null>(null);
  useEffect(() => {
    const af = (afLocation.state as { autoFill?: { skills?: string[]; nonce?: number } } | null)?.autoFill;
    if (!af) return;
    const skillSig = `${playerId}:${af.nonce ?? 0}`;
    if (appliedSkillSigRef.current === skillSig) return;
    appliedSkillSigRef.current = skillSig;
    // 以方案保存的“新增技能”为准整体替换（剔除默认技能、去重），多方案切换时正确还原
    const saved = Array.isArray(af.skills) ? af.skills : [];
    const want = [
      ...new Set(
        saved
          .map((n) => String(n || '').trim())
          .filter((n) => n && !safeSkills.includes(n)),
      ),
    ];
    setExtraSkills((prev) => {
      if (prev.length === want.length && prev.every((x, i) => x === want[i])) return prev;
      return want;
    });
    if (want.length > 0) {
      toast.success(lang === 'en' ? 'Saved skills loaded' : trTerm('已为你载入该培养方案的新增技能'));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [afLocation.state, playerId]);

  // 保存技能方案：与“加点保存”一致，一次性写入完整快照（加点 + 教练 + 新增技能）。
  // 仅用户手动“新增”的黄色技能随方案保存，球员默认技能不存。
  const handleSaveSkills = async () => {
    if (!requireLogin('保存技能方案')) return;
    if (!playerId) { toast.error(trTerm('缺少球员信息，无法保存')); return; }
    const finalSkills = displayList
      .filter((entry) => entry.extra)
      .map((entry) => entry.name);
    try {
      const allocations = getDraftAllocations(playerId) ?? {};
      const coachId = getDraftCoach(playerId);
      const secondBooster = getDraftSecondBooster(playerId);
      const shineLevel = getDraftShine(playerId) ?? 0;
      await saveBuildPlan(
        playerId,
        allocations,
        getAuthHeaders(),
        { coachId, skills: finalSkills, secondBooster, shineLevel },
      );
      toast.success(
        finalSkills.length > 0
          ? (lang === 'en'
            ? `Saved ${finalSkills.length} added skills; view under Profile - Build Plans`
            : `已保存 ${finalSkills.length} 个新增技能，可在个人中心“培养方案”查看`)
          : trTerm('已保存当前培养方案'),
      );
    } catch (err: unknown) {
      const e = err as any;
      const msg =
        e?.response?.data?.error?.message ||
        e?.response?.data?.message ||
        e?.message ||
        trTerm('技能方案保存失败，请稍后重试');
      toast.error(msg);
    }
  };

  // 展示清单：原有技能 + 本地新增（黄色）
  const displayList = [
    ...sortedSkills.map((name) => ({ name, extra: false })),
    ...filterVisibleSkills(extraSkills.filter((n) => !safeSkills.includes(n))).map((name) => ({ name, extra: true })),
  ];

  if (landscape) {
    return (
      <div className="rounded-xl bg-card/80 border border-white/10 px-2.5 py-2 backdrop-blur">
        <div className="flex items-center justify-between gap-2 mb-1">
          <h2 className="text-sm font-bold text-white flex items-center gap-1.5">
            <span className="w-1 h-4 rounded-full bg-neon-gradient" />
            {t('detail.playerSkills')}
            <span className="text-[10px] font-normal text-gray-400">({visibleSkills.length})</span>
          </h2>
          <div className="flex items-center gap-1">
            {isWeb && (
              <button
                type="button"
                onClick={openAddModal}
                className="flex items-center gap-1 px-2 py-0.5 rounded-md bg-gradient-to-r from-orange-500 to-amber-500 border border-orange-400/70 text-white text-[11px] font-bold shadow-[0_0_10px_rgba(249_115_22_0.45)] hover:shadow-[0_0_14px_rgba(249_115_22_0.7)] transition-all active:scale-95"
              >
                <Plus className="w-3 h-3" />
                <span>{t('detail.addNew')}</span>
              </button>
            )}
            {isWeb && extraSkills.length > 0 && (
              <button
                type="button"
                onClick={() => setExtraSkills([])}
                className="flex items-center gap-1 px-2 py-0.5 rounded-md bg-white/5 border border-white/15 text-gray-300 text-[11px] font-semibold hover:bg-white/10 hover:text-white transition-all active:scale-95"
                title={trTerm('清除新增技能，恢复默认')}
              >
                <X className="w-3 h-3" />
                <span>{t('common.reset')}</span>
              </button>
            )}
            <button
              type="button"
              onClick={() => setOpen(true)}
              className="flex items-center gap-1 px-2 py-0.5 rounded-md bg-gradient-to-r from-amber-500/20 to-pink-500/20 border border-amber-500/40 text-amber-300 text-[11px] font-semibold"
            >
              <Lightbulb className="w-3 h-3" />
              <span>{t('detail.recommendSkill')}</span>
            </button>
            <button
              type="button"
              onClick={handleSaveSkills}
              className="flex items-center gap-1 px-2 py-0.5 rounded-md bg-gradient-to-r from-emerald-500 to-green-500 border border-emerald-400/70 text-white text-[11px] font-bold shadow-[0_0_10px_rgba(16_185_129_0.45)] hover:shadow-[0_0_14px_rgba(16_185_129_0.7)] transition-all active:scale-95"
            >
              <Save className="w-3 h-3" />
              <span>{t('detail.saveSkill')}</span>
            </button>
          </div>
        </div>
        {displayList.length === 0 ? (
          <p className="text-[11px] text-gray-500 text-center py-2">{t('common.noData')}</p>
        ) : (
          <div className="grid grid-cols-3 gap-1">
            {displayList.map((entry) => {
              const { extra } = entry;
              const displaySkill = extra ? entry.name : normalizeSkillForPlayer(entry.name, registeredPosition);
              const st = !extra && isStSkill(displaySkill);
              // ST 名可能以别名存储（如“炮弹式头球”），跳转前归一到百科标准名（“炮弹头球”）
              const linkKey = st ? normalizeStSkillName(displaySkill) : displaySkill;
              return (
                <div
                  key={`${extra ? 'x' : 's'}-${entry.name}`}
                  className={`flex items-center justify-center gap-1 px-1.5 py-1 rounded-md border text-[13px] truncate ${
                    extra
                      ? 'bg-yellow-400/20 border-yellow-400/70 text-yellow-100'
                      : st
                        ? 'bg-[#FF2D95]/10 border-[#FF2D95]/50 text-[#FF6BB5]'
                        : 'bg-white/[0.03] border-white/10 text-gray-200'
                  }`}
                  title={displaySkill}
                >
                  {extra ? (
                    <Plus className="w-3 h-3 flex-shrink-0 text-yellow-300" />
                  ) : st ? (
                    <Sparkles className="w-3 h-3 flex-shrink-0 text-[#FF2D95]" />
                  ) : (
                    <Sparkles className="w-3 h-3 flex-shrink-0 text-cyan-400" />
                  )}
                  <span
                    className={`truncate text-center ${skillLinkMap.has(linkKey) ? 'cursor-pointer hover:underline underline-offset-2' : ''}`}
                    onClick={(e) => goSkill(e, linkKey)}
                    title={skillLinkMap.has(linkKey) ? `查看百科：${linkKey}` : displaySkill}
                  >
                    {shown(displaySkill)}
                  </span>
                </div>
              );
            })}
          </div>
        )}

        <Dialog open={open} onOpenChange={setOpen}>
          <DialogContent
            showCloseButton={false}
            className="bg-[#0f142e]/95 border-white/10 max-w-lg max-h-[85vh] overflow-hidden flex flex-col p-0"
          >
            <div className="flex items-center justify-between px-5 py-4 border-b border-white/10 flex-shrink-0">
              <div className="min-w-0">
                <DialogTitle className="text-2xl md:text-xl font-bold text-white flex items-center gap-2">
                  <Lightbulb className="w-5 h-5 text-amber-400" />
                  {trTerm('推荐增补技能')}
                </DialogTitle>
              </div>
              <button
                type="button"
                onClick={() => setOpen(false)}
                className="flex-shrink-0 w-8 h-8 flex items-center justify-center rounded-md text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
                aria-label={trTerm('关闭')}
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto px-5 py-4">
              {greenPositions.length === 0 ? (
                <div className="text-center py-10">
                  <div className="text-5xl mb-3">🤔</div>
                  <p className="text-xl font-bold text-white mb-2">{trTerm('暂无绿色适配位置')}</p>
                  <p className="text-base text-gray-400">{trTerm('该球员暂无绿色适配位置，无法生成针对性增补推荐')}</p>
                </div>
              ) : totalMissing === 0 ? (
                 <div className="text-center py-10">
                   <div className="text-5xl mb-3">🎉</div>
                   <p className="text-xl font-bold text-white mb-2">{trTerm('技能搭配已很完整')}</p>
                   <p className="text-base text-gray-400">{trTerm('该位置推荐技能全部掌握，暂无缺失')}</p>
                 </div>
               ) : (
                 <div className="space-y-5">
                   {groups.map((g) => {
                     const list = missing[g.level];
                     return (
                       <div key={g.level}>
                         <div className="flex items-center gap-2 mb-2.5">
                           <span className={`w-1 h-5 bg-gradient-to-b ${g.color} rounded-full`} />
                           <h3 className="text-lg font-bold text-white">{trTerm(g.title)}</h3>
                           <span className="text-sm text-gray-500">{list.length} {trTerm('项')}</span>
                         </div>
                         <p className="text-sm text-gray-500 mb-2.5 -mt-1.5 ml-3">{trTerm(g.desc)}</p>
                         {list.length > 0 ? (
                           <div className="flex flex-wrap gap-2">
                             {list.map((skill) => (
                               <span
                                 key={skill}
                                 className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg bg-white/[0.04] border border-white/10 text-gray-200 text-sm font-medium"
                               >
                                 <Award className="w-3.5 h-3.5 text-gray-500" />
                                 {shown(skill)}
                               </span>
                             ))}
                           </div>
                         ) : (
                           <p className="text-sm text-gray-600 ml-3">{trTerm('暂无')}</p>
                         )}
                       </div>
                     );
                   })}
                 </div>
               )}
            </div>
          </DialogContent>
        </Dialog>

        {/* 新增普通技能（多选，黄色标识，仅本地预览） */}
        <Dialog open={addOpen} onOpenChange={setAddOpen}>
          <DialogContent showCloseButton={false} className="bg-[#0f142e]/95 border-white/10 max-w-xl max-h-[85vh] overflow-hidden flex flex-col p-0">
            <div className="flex items-center justify-between px-5 py-3 border-b border-white/10">
              <DialogTitle className="text-lg font-bold text-white flex items-center gap-2">
                <span className="w-1 h-5 rounded-full bg-gradient-to-b from-orange-400 to-amber-500" />
                {trTerm('新增普通技能')}
              </DialogTitle>
              <button type="button" onClick={() => setAddOpen(false)} className="text-gray-400 hover:text-white">
                <X className="h-5 w-5" />
              </button>
            </div>
            <div className="flex-1 space-y-3 overflow-y-auto px-4 py-3">
              <DialogDescription className="text-xs text-gray-400">
                {trTerm('按类型选择要新增的普通技能（不含 ST 技能），确认后以黄色标识显示在技能栏；仅本地预览，不写入球员数据。')}
              </DialogDescription>
              {normalSkillGroups.length === 0 && (
                <p className="py-4 text-center text-xs text-gray-500">{trTerm('暂无可新增的普通技能')}</p>
              )}
              {normalSkillGroups.map((g) => (
                <div key={g.cat}>
                  <p className="mb-1 text-[11px] font-bold text-cyan-300">{catShown(g.cat)}</p>
                  <div className="flex flex-wrap gap-1.5">
                    {g.names.map((n) => {
                      const on = picked.has(n);
                      return (
                        <button
                          key={n}
                          type="button"
                          onClick={() => togglePicked(n)}
                          className={`flex items-center gap-1 rounded-md border px-2 py-1 text-[12px] transition ${
                            on
                              ? 'border-yellow-400 bg-yellow-400/25 text-yellow-100'
                              : 'border-white/15 bg-white/5 text-gray-300 hover:border-white/30'
                          }`}
                        >
                          {on ? <Check className="h-3 w-3" /> : <Plus className="h-3 w-3" />}
                          {shown(n)}
                        </button>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
            <div className="flex items-center justify-end gap-2 border-t border-white/10 bg-[#1a1f45]/40 px-4 py-3">
              <button
                type="button"
                onClick={() => setAddOpen(false)}
                className="h-8 rounded-lg border border-white/15 bg-white/10 px-4 text-xs font-bold text-gray-200"
              >
                {trTerm('取消')}
              </button>
              <button
                type="button"
                onClick={confirmAdd}
                className="h-8 rounded-lg bg-gradient-to-r from-orange-500 to-amber-500 px-5 text-xs font-bold text-white"
              >
                {trTerm('确认新增')}{picked.size > 0 ? ` (${picked.size})` : ''}
              </button>
            </div>
          </DialogContent>
        </Dialog>
      </div>
    );
  }

  return (
    <div className="rounded-2xl bg-card/80 border border-white/10 p-5 backdrop-blur">
      <div className="flex items-stretch justify-between gap-3 mb-1">
        <div className="min-w-0 py-1">
          <h2 className="text-3xl md:text-xl font-bold text-white flex items-center gap-2">
            <span className="w-1 h-5 bg-gradient-to-b from-gray-400 to-gray-600 rounded-full" />
            {t('detail.playerSkills')}
            <span className="text-base font-normal text-gray-400">({visibleSkills.length})</span>
          </h2>
          <p className="text-lg md:text-sm text-gray-500 mt-0.5">{trTerm('球员掌握的特殊技巧')}</p>
        </div>
        <div className="flex flex-shrink-0 flex-wrap items-center justify-end gap-2">
          <button
            type="button"
            onClick={openAddModal}
            className="flex items-center gap-1.5 rounded-xl border border-orange-400/70 bg-gradient-to-r from-orange-500 to-amber-500 px-3.5 py-2 text-2xl font-bold text-white shadow-[0_0_12px_rgba(249_115_22_0.45)] transition-all active:scale-95 md:text-lg"
          >
            <Plus className="w-5 h-5 md:w-4 md:h-4" />
            <span>{trTerm('新增')}</span>
          </button>
          {extraSkills.length > 0 && (
            <button
              type="button"
              onClick={() => setExtraSkills([])}
              className="flex items-center gap-1.5 rounded-xl border border-white/15 bg-white/5 px-3.5 py-2 text-2xl font-semibold text-gray-300 hover:bg-white/10 hover:text-white transition-all active:scale-95 md:text-lg"
              title={trTerm('清除新增技能，恢复默认')}
            >
              <X className="w-5 h-5 md:w-4 md:h-4" />
              <span>{trTerm('重置')}</span>
            </button>
          )}
          <button
            type="button"
            onClick={() => setOpen(true)}
            className="flex-shrink-0 flex items-center gap-2 px-4 rounded-xl bg-gradient-to-r from-amber-500/20 to-pink-500/20 border border-amber-500/40 text-amber-300 hover:from-amber-500/30 hover:to-pink-500/30 transition-colors text-2xl md:text-lg font-semibold"
          >
            <Lightbulb className="w-5 h-5 md:w-4 md:h-4" />
            <span>推荐增补</span>
          </button>
          <button
            type="button"
            onClick={handleSaveSkills}
            className="flex items-center gap-1.5 rounded-xl border border-emerald-400/70 bg-gradient-to-r from-emerald-500 to-green-500 px-3.5 py-2 text-2xl font-bold text-white shadow-[0_0_12px_rgba(16_185_129_0.45)] transition-all active:scale-95 md:text-lg"
          >
            <Save className="w-5 h-5 md:w-4 md:h-4" />
            <span>保存技能</span>
          </button>
        </div>
      </div>

      {displayList.length === 0 ? (
        <p className="text-lg md:text-sm text-gray-500 text-center py-6">暂无技巧数据</p>
      ) : (
        <div className="grid grid-cols-2 gap-2.5 md:grid-cols-4">
          {displayList.map((entry) => {
             const { extra } = entry;
             const displaySkill = extra ? entry.name : normalizeSkillForPlayer(entry.name, registeredPosition);
             const st = !extra && isStSkill(displaySkill);
             return (
               <div
                 key={`${extra ? 'x' : 's'}-${entry.name}`}
                 className={`flex items-center justify-center gap-2 px-3 py-2 rounded-lg border backdrop-blur-sm transition-transform hover:scale-[1.02] ${
                   extra
                     ? 'bg-yellow-400/20 border-yellow-400/70 text-yellow-100'
                     : st
                       ? 'bg-[#FF2D95]/10 border-[#FF2D95]/50 text-[#FF6BB5] shadow-[0_0_8px_rgba(255_45_149_0.25)]'
                       : 'bg-white/[0.03] border-white/10 text-gray-200'
                 }`}
               >
                 {extra ? (
                   <Plus className="w-4 h-4 flex-shrink-0 text-yellow-300" />
                 ) : st ? (
                   <Sparkles className="w-4 h-4 flex-shrink-0 text-[#FF2D95]" />
                 ) : (
                   <Award className="w-4 h-4 flex-shrink-0 text-gray-400" />
                 )}
                 <span
                   className={`text-3xl md:text-xl font-medium truncate text-center ${st ? 'text-[#FFB3D9]' : ''} ${skillLinkMap.has(displaySkill) ? 'cursor-pointer hover:underline underline-offset-2' : ''}`}
                   onClick={(e) => goSkill(e, displaySkill)}
                   title={skillLinkMap.has(displaySkill) ? `查看百科：${displaySkill}` : displaySkill}
                 >
                   {shown(displaySkill)}
                 </span>
               </div>
             );
           })}
        </div>
      )}

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent
          showCloseButton={false}
          className="bg-[#0f142e]/95 border-white/10 max-w-lg max-h-[85vh] overflow-hidden flex flex-col p-0"
        >
          <div className="flex items-center justify-between px-5 py-4 border-b border-white/10 flex-shrink-0">
            <div className="min-w-0">
              <DialogTitle className="text-2xl md:text-xl font-bold text-white flex items-center gap-2">
                <Lightbulb className="w-5 h-5 text-amber-400" />
                推荐增补技能
              </DialogTitle>
              <DialogDescription className="text-sm text-gray-400 mt-0.5">
                基于绿色适配位置：{greenPositions.map((p) => POSITION_LABEL_MAP[p] || p).join('、')}
              </DialogDescription>
            </div>
            <button
              type="button"
              onClick={() => setOpen(false)}
              className="flex-shrink-0 w-8 h-8 flex items-center justify-center rounded-md text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
              aria-label="关闭"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto px-5 py-4">
            {greenPositions.length === 0 ? (
              <div className="text-center py-10">
                <div className="text-5xl mb-3">🤔</div>
                <p className="text-xl font-bold text-white mb-2">暂无绿色适配位置</p>
                <p className="text-base text-gray-400">该球员暂无绿色适配位置，无法生成针对性增补推荐</p>
              </div>
            ) : totalMissing === 0 ? (
               <div className="text-center py-10">
                 <div className="text-5xl mb-3">🎉</div>
                 <p className="text-xl font-bold text-white mb-2">技能搭配已很完整</p>
                 <p className="text-base text-gray-400">该位置推荐技能全部掌握，暂无缺失</p>
               </div>
             ) : (
               <div className="space-y-5">
                 {groups.map((g) => {
                   const list = missing[g.level];
                   return (
                     <div key={g.level}>
                       <div className="flex items-center gap-2 mb-2.5">
                         <span className={`w-1 h-5 bg-gradient-to-b ${g.color} rounded-full`} />
                         <h3 className="text-lg font-bold text-white">{g.title}</h3>
                         <span className="text-sm text-gray-500">{list.length}项</span>
                       </div>
                       <p className="text-sm text-gray-500 mb-2.5 -mt-1.5 ml-3">{g.desc}</p>
                       {list.length > 0 ? (
                         <div className="flex flex-wrap gap-2">
                           {list.map((skill) => (
                             <span
                               key={skill}
                               className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg bg-white/[0.04] border border-white/10 text-gray-200 text-sm font-medium"
                             >
                               <Award className="w-3.5 h-3.5 text-gray-500" />
                               {skill}
                             </span>
                           ))}
                         </div>
                       ) : (
                         <p className="text-sm text-gray-600 ml-3">暂无</p>
                       )}
                     </div>
                   );
                 })}
               </div>
             )}
          </div>
        </DialogContent>
      </Dialog>

      {/* 新增普通技能（多选，黄色标识，仅本地预览） */}
      <Dialog open={addOpen} onOpenChange={setAddOpen}>
        <DialogContent showCloseButton={false} className="bg-[#0f142e]/95 border-white/10 max-w-xl max-h-[85vh] overflow-hidden flex flex-col p-0">
          <div className="flex items-center justify-between px-5 py-3 border-b border-white/10">
            <DialogTitle className="text-2xl font-bold text-white flex items-center gap-2">
              <span className="w-1 h-6 rounded-full bg-gradient-to-b from-orange-400 to-amber-500" />
              新增普通技能
            </DialogTitle>
            <button type="button" onClick={() => setAddOpen(false)} className="text-gray-400 hover:text-white">
              <X className="h-6 w-6" />
            </button>
          </div>
          <div className="flex-1 space-y-3 overflow-y-auto px-4 py-3">
            <DialogDescription className="text-base text-gray-400">
              按类型选择要新增的普通技能（不含 ST 技能），确认后以黄色标识显示在技能栏；仅本地预览，不写入球员数据。
            </DialogDescription>
            {normalSkillGroups.length === 0 && (
              <p className="py-4 text-center text-base text-gray-500">暂无可新增的普通技能</p>
            )}
            {normalSkillGroups.map((g) => (
              <div key={g.cat}>
                <p className="mb-1 text-lg font-bold text-cyan-300">{g.cat}</p>
                <div className="flex flex-wrap gap-1.5">
                  {g.names.map((n) => {
                    const on = picked.has(n);
                    return (
                      <button
                        key={n}
                        type="button"
                        onClick={() => togglePicked(n)}
                        className={`flex items-center gap-1 rounded-md border px-2.5 py-1.5 text-base transition ${
                          on
                            ? 'border-yellow-400 bg-yellow-400/25 text-yellow-100'
                            : 'border-white/15 bg-white/5 text-gray-300 hover:border-white/30'
                        }`}
                      >
                        {on ? <Check className="h-4 w-4" /> : <Plus className="h-4 w-4" />}
                        {n}
                      </button>
                    );
                  })}
                </div>
              </div>
            ))}
          </div>
          <div className="flex items-center justify-end gap-2 border-t border-white/10 bg-[#1a1f45]/40 px-4 py-3">
            <button
              type="button"
              onClick={() => setAddOpen(false)}
              className="h-10 rounded-lg border border-white/15 bg-white/10 px-5 text-base font-bold text-gray-200"
            >
              取消
            </button>
            <button
              type="button"
              onClick={confirmAdd}
              className="h-10 rounded-lg bg-gradient-to-r from-orange-500 to-amber-500 px-6 text-base font-bold text-white"
            >
              确认新增{picked.size > 0 ? `（${picked.size}）` : ''}
            </button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default SkillsList;
