import { useState, useEffect, useCallback } from 'react';
import {
  ArrowLeft,
  Trophy,
  TrendingUp,
  TrendingDown,
  ListFilter,
  Loader2,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { reputation as reputationApi } from '@client/src/api';
import type {
  ReputationSummary,
  ReputationLogItem,
} from '@shared/api.interface';

const FILTERS: { key: 'all' | 'gain' | 'loss'; label: string }[] = [
  { key: 'all', label: '全部' },
  { key: 'gain', label: '获得' },
  { key: 'loss', label: '扣减' },
];

export default function ReputationPage() {
  const navigate = useNavigate();
  const [summary, setSummary] = useState<ReputationSummary | null>(null);
  const [logs, setLogs] = useState<ReputationLogItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [logLoading, setLogLoading] = useState(false);
  const [filter, setFilter] = useState<'all' | 'gain' | 'loss'>('all');
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const pageSize = 20;

  const loadSummary = useCallback(async () => {
    try {
      setLoading(true);
      const data = await reputationApi.getReputationSummary();
      setSummary(data);
    } catch (err) {
      logger.error('加载声望概览失败', err);
    } finally {
      setLoading(false);
    }
  }, []);

  const loadLogs = useCallback(async () => {
    try {
      setLogLoading(true);
      const data = await reputationApi.getReputationLogs({
        page,
        pageSize,
        filter,
      });
      setLogs((prev) => (page === 1 ? data.items : [...prev, ...data.items]));
      setTotal(data.total);
    } catch (err) {
      logger.error('加载声望流水失败', err);
    } finally {
      setLogLoading(false);
    }
  }, [page, filter]);

  useEffect(() => {
    loadSummary();
  }, [loadSummary]);

  useEffect(() => {
    setLogs([]);
    setPage(1);
  }, [filter]);

  useEffect(() => {
    loadLogs();
  }, [loadLogs]);

  const loadMore = () => {
    if (logLoading || logs.length >= total) return;
    setPage((p) => p + 1);
  };

  const hasMore = logs.length < total;

  return (
    <div className="min-h-screen bg-gradient-to-b from-[#0a0f24] via-[#0e1438] to-[#0a0f24] pb-20">
      {/* 顶部导航 */}
      <div className="sticky top-0 z-10 flex items-center gap-3 border-b border-white/5 bg-[#0a0f24]/90 px-5 py-3 backdrop-blur-md md:px-6">
        <button
          onClick={() => navigate(-1)}
          className="flex h-10 w-10 items-center justify-center rounded-lg text-white/70 transition-colors hover:bg-white/5 hover:text-white"
        >
          <ArrowLeft className="h-5 w-5" />
        </button>
        <h1 className="text-xl font-bold text-white">我的声望</h1>
      </div>

      <div className="mx-auto max-w-2xl px-5 py-6 md:px-6">
        {/* 声望概览卡 */}
        <div className="relative overflow-hidden rounded-2xl border border-yellow-500/20 bg-gradient-to-br from-yellow-500/10 via-[#1a1f4a] to-[#1a1f4a] p-6 shadow-[0_0_40px_rgba(234_179_8_0.1)]">
          <div className="absolute -right-10 -top-10 h-40 w-40 rounded-full bg-yellow-500/10 blur-3xl" />
          <div className="relative">
            <div className="flex items-center gap-2 text-yellow-400/70">
              <Trophy className="h-5 w-5" />
              <span className="text-sm">当前声望</span>
            </div>
            {loading ? (
              <div className="mt-2 flex h-10 items-center">
                <Loader2 className="h-5 w-5 animate-spin text-yellow-400" />
              </div>
            ) : (
              <>
                <div className="mt-2 flex items-baseline gap-3">
                  <span className="text-4xl font-bold text-yellow-400">
                    {summary?.reputation ?? 0}
                  </span>
                  <span className="text-lg font-semibold text-emerald-400">
                    Lv.{summary?.level ?? 1}
                  </span>
                  <span className="text-base text-white/50">
                    {summary?.title ?? ''}
                  </span>
                </div>
                {summary && summary.nextLevelMin !== null && (
                  <div className="mt-4">
                    <div className="mb-1.5 flex items-center justify-between text-sm">
                      <span className="text-white/50">
                        距 Lv.{summary.level + 1} {summary.nextLevelTitle}
                      </span>
                      <span className="text-yellow-400/80">
                        {summary.progress}%
                      </span>
                    </div>
                    <div className="h-2 overflow-hidden rounded-full bg-white/10">
                      <div
                        className="h-full rounded-full bg-gradient-to-r from-yellow-500 to-amber-400 transition-all duration-500"
                        style={{ width: `${summary.progress}%` }}
                      />
                    </div>
                  </div>
                )}
                {summary && summary.nextLevelMin === null && (
                  <div className="mt-3 text-sm text-emerald-400/80">
                    已达最高等级
                  </div>
                )}
              </>
            )}
          </div>
        </div>

        {/* 筛选 */}
        <div className="mt-6 flex items-center justify-between">
          <div className="flex items-center gap-2 text-white/90">
            <ListFilter className="h-4 w-4" />
            <span className="text-base font-medium">积分明细</span>
          </div>
          <div className="flex gap-1 rounded-lg border border-white/10 bg-[#141838]/60 p-1">
            {FILTERS.map((f) => (
              <button
                key={f.key}
                onClick={() => setFilter(f.key)}
                className={`rounded-md px-3 py-1.5 text-sm font-medium transition-all ${
                  filter === f.key
                    ? 'bg-cyan-500/20 text-cyan-300'
                    : 'text-white/50 hover:text-white/80'
                }`}
              >
                {f.label}
              </button>
            ))}
          </div>
        </div>

        {/* 流水列表 */}
        <div className="mt-3 space-y-2">
          {logs.length === 0 && !logLoading && (
            <div className="rounded-xl border border-white/5 bg-[#141838]/40 py-12 text-center">
              <div className="text-base text-white/30">暂无积分记录</div>
            </div>
          )}
          {logs.map((log) => (
            <div
              key={log.id}
              className="flex items-center justify-between rounded-xl border border-white/5 bg-[#141838]/40 px-4 py-3.5 transition-colors hover:border-white/10"
            >
              <div className="flex items-center gap-3">
                <div
                  className={`flex h-9 w-9 items-center justify-center rounded-lg ${
                    log.changeAmount >= 0
                      ? 'bg-emerald-500/15 text-emerald-400'
                      : 'bg-red-500/15 text-red-400'
                  }`}
                >
                  {log.changeAmount >= 0 ? (
                    <TrendingUp className="h-4 w-4" />
                  ) : (
                    <TrendingDown className="h-4 w-4" />
                  )}
                </div>
                <div>
                  <div className="text-base font-medium text-white">
                    {log.reasonLabel}
                  </div>
                  <div className="mt-0.5 text-xs text-white/40">
                    {new Date(log.createdAt).toLocaleString('zh-CN', {
                      month: '2-digit',
                      day: '2-digit',
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                  </div>
                </div>
              </div>
              <div className="text-right">
                <div
                  className={`text-lg font-bold ${
                    log.changeAmount > 0
                      ? 'text-emerald-400'
                      : log.changeAmount < 0
                      ? 'text-red-400'
                      : 'text-white/40'
                  }`}
                >
                  {log.changeAmount > 0 ? '+' : ''}
                  {log.changeAmount}
                </div>
                <div className="mt-0.5 text-xs text-white/30">
                  余额 {log.balanceAfter}
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* 加载更多 */}
        {logLoading && (
          <div className="flex items-center justify-center py-6">
            <Loader2 className="h-5 w-5 animate-spin text-cyan-400" />
          </div>
        )}
        {!logLoading && hasMore && (
          <button
            onClick={loadMore}
            className="mt-3 w-full rounded-xl border border-white/10 bg-[#141838]/40 py-3 text-sm text-white/60 transition-colors hover:border-cyan-400/30 hover:text-cyan-300"
          >
            加载更多
          </button>
        )}
        {!logLoading && !hasMore && logs.length > 0 && (
          <div className="py-4 text-center text-xs text-white/30">
            共 {total} 条记录，已全部加载
          </div>
        )}
      </div>
    </div>
  );
}
