import React, { useMemo } from 'react';
import { Eye, EyeOff } from 'lucide-react';
import type { Player, BodyModel, PlayerModel } from '@shared/api.interface';

interface CompareBodyModelProps {
  playerList: Player[];
  hideSame: boolean;
  onToggleHideSame: () => void;
}

const PLAYER_COLORS = [
  '#00E5FF',
  '#FF9F1C',
  '#4ADE80',
  '#A78BFA',
  '#22D3EE',
  '#F472B6',
];

interface ScalarItem {
  key: string;
  label: string;
  unit?: string;
  decimals?: number;
}

// 身体测量
const PHYS_ITEMS: ScalarItem[] = [
  { key: 'height', label: '身高', unit: 'cm' },
  { key: 'weight', label: '体重', unit: 'kg' },
];

// 尺寸模型（bodyModel，值为 {value}）
const BODY_ITEMS: ScalarItem[] = [
  { key: 'legReachDiameter', label: '伸腿覆盖', unit: 'cm', decimals: 1 },
  { key: 'legLengthEquivalent', label: '等效身高', unit: 'cm', decimals: 1 },
  { key: 'upperLimbDiameter', label: '上肢覆盖', unit: 'cm', decimals: 1 },
  { key: 'trunkCollisionDiameter', label: '躯干碰撞', unit: 'cm', decimals: 1 },
  { key: 'jumpHeight', label: '跳跃高度', unit: 'cm', decimals: 1 },
];

// 模型数值（playerModel，标量）
const MODEL_ITEMS: ScalarItem[] = [
  { key: 'neckCircumference', label: '颈围' },
  { key: 'neckLength', label: '颈长' },
  { key: 'shoulderWidth', label: '肩宽' },
  { key: 'shoulderHeight', label: '肩高' },
  { key: 'armSize', label: '臂围' },
  { key: 'armLength', label: '臂长' },
  { key: 'chestMeasurement', label: '胸围' },
  { key: 'waistCircumference', label: '腰围' },
  { key: 'thighSize', label: '大腿围' },
  { key: 'calfSize', label: '小腿围' },
  { key: 'legLength', label: '腿长' },
];

const areValuesSame = (values: number[]): boolean => {
  if (values.length <= 1) return true;
  return values.every((v) => v === values[0]);
};

const CompareBodyModel: React.FC<CompareBodyModelProps> = ({ playerList, hideSame, onToggleHideSame }) => {
  // 各 item 的取值数组
  const getValues = useMemo(() => (item: ScalarItem): number[] => {
    return playerList.map((p) => {
      if (item.key === 'height') return p.height || 0;
      if (item.key === 'weight') return p.weight || 0;
      const bm = p.bodyModel as Partial<BodyModel> | undefined;
      if (bm && item.key in bm) return bm[item.key as keyof BodyModel]?.value ?? 0;
      const pm = p.playerModel as Partial<PlayerModel> | undefined;
      if (pm && item.key in pm) {
        const v = pm[item.key as keyof PlayerModel];
        return typeof v === 'number' && Number.isFinite(v) ? v : 0;
      }
      return 0;
    });
  }, [playerList]);

  const buildVisible = (items: ScalarItem[]) =>
    items
      .map((it) => ({ item: it, values: getValues(it) }))
      .filter(({ values }) => !hideSame || !areValuesSame(values));

  const visiblePhys = useMemo(() => buildVisible(PHYS_ITEMS), [playerList, hideSame]);
  const visibleBody = useMemo(() => buildVisible(BODY_ITEMS), [playerList, hideSame]);
  const visibleModel = useMemo(() => buildVisible(MODEL_ITEMS), [playerList, hideSame]);

  const totalCount = PHYS_ITEMS.length + BODY_ITEMS.length + MODEL_ITEMS.length;
  const visibleCount = visiblePhys.length + visibleBody.length + visibleModel.length;

  const renderScalarRow = (item: ScalarItem, values: number[]) => {
    const decimals = item.decimals ?? 0;
    const maxVal = Math.max(...values);
    const minVal = Math.min(...values);
    const hasDiff = values.length > 1 && maxVal !== minVal;
    const fmt = (n: number) => (decimals > 0 ? n.toFixed(decimals) : `${Math.round(n)}`);

    return (
      <div key={item.key} className="flex items-center border-b border-white/5 last:border-b-0">
        <div className="w-[100px] sm:w-24 flex-shrink-0 text-center py-1">
          <span className="text-2xl sm:text-sm text-gray-500 whitespace-nowrap">{item.label}</span>
        </div>
        {values.map((val, idx) => {
          const isMax = val === maxVal && val > 0;
          const isMin = val === minVal && val > 0 && hasDiff;
          return (
            <div key={playerList[idx].id} className="flex-1 flex items-center justify-center gap-1 py-1">
              <span
                className={`text-2xl sm:text-lg font-bold ${
                  isMax ? 'text-cyan-300' : isMin ? 'text-rose-400' : 'text-gray-400'
                }`}
              >
                {fmt(val)}
                {item.unit && (
                  <span className="text-sm sm:text-xs text-gray-500 ml-0.5 font-normal">{item.unit}</span>
                )}
              </span>
              {isMax && hasDiff && (
                <span className="text-sm sm:text-xs font-semibold text-green-400">+{fmt(maxVal - minVal)}</span>
              )}
              {isMin && hasDiff && (
                <span className="text-sm sm:text-xs font-semibold text-red-400">-{fmt(maxVal - minVal)}</span>
              )}
            </div>
          );
        })}
      </div>
    );
  };

  const SubHeader: React.FC<{ text: string }> = ({ text }) => (
    <div className="flex items-center gap-1.5 px-3 pt-2 pb-0.5">
      <span className="w-1 h-3 bg-gradient-to-b from-cyan-400 to-pink-500 rounded-full" />
      <span className="text-xl sm:text-sm font-semibold text-cyan-200">{text}</span>
    </div>
  );

  return (
    <div className="rounded-xl bg-[#141838] border border-white/10 overflow-hidden">
      <div className="px-3 sm:px-4 py-2 sm:py-3 bg-white/[0.03]">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="w-1 h-4 sm:h-5 bg-gradient-to-b from-emerald-400 to-teal-500 rounded-full" />
            <div className="flex items-center gap-2 min-w-0">
              <h3 className="text-2xl sm:text-xl font-bold text-white truncate">模型对比</h3>
              <span className="text-lg sm:text-sm text-gray-500 flex-shrink-0">
                {hideSame ? `${visibleCount}/${totalCount} 项` : `共 ${totalCount} 项`}
              </span>
            </div>
          </div>
          <button
            type="button"
            onClick={onToggleHideSame}
            className={`flex items-center gap-1.5 px-2.5 sm:px-3 py-1 rounded-lg text-base sm:text-sm font-medium transition-colors flex-shrink-0 ${
              hideSame
                ? 'bg-emerald-500/20 text-emerald-300 border border-emerald-400/40'
                : 'bg-white/5 text-gray-400 border border-white/10 hover:bg-white/10 hover:text-gray-200'
            }`}
          >
            {hideSame ? <EyeOff className="w-3.5 h-3.5 sm:w-4 sm:h-4" /> : <Eye className="w-3.5 h-3.5 sm:w-4 sm:h-4" />}
            隐藏相同
          </button>
        </div>
      </div>

      {visibleCount === 0 && hideSame ? (
        <div className="px-3 sm:px-4 py-6 sm:py-8 text-center text-sm sm:text-lg text-gray-500">
          所有项数值相同，已全部隐藏
        </div>
      ) : (
        <div className="px-2 pb-1">
          {visiblePhys.length > 0 && <SubHeader text="身体测量" />}
          {visiblePhys.map(({ item, values }) => (
            <React.Fragment key={item.key}>{renderScalarRow(item, values)}</React.Fragment>
          ))}

          {visibleBody.length > 0 && <SubHeader text="尺寸模型" />}
          {visibleBody.map(({ item, values }) => (
            <React.Fragment key={item.key}>{renderScalarRow(item, values)}</React.Fragment>
          ))}

          {visibleModel.length > 0 && <SubHeader text="模型数值" />}
          {visibleModel.map(({ item, values }) => (
            <React.Fragment key={item.key}>{renderScalarRow(item, values)}</React.Fragment>
          ))}
        </div>
      )}

      <div className="px-3 sm:px-4 py-2 sm:py-3 flex flex-wrap justify-center gap-2 sm:gap-3 border-t border-white/5">
        {playerList.map((p, idx) => (
          <div key={p.id} className="flex items-center gap-1.5 sm:gap-2">
            <span
              className="w-2 h-2 sm:w-2.5 sm:h-2.5 rounded-full"
              style={{
                backgroundColor: PLAYER_COLORS[idx % PLAYER_COLORS.length],
                boxShadow: `0 0 4px ${PLAYER_COLORS[idx % PLAYER_COLORS.length]}`,
              }}
            />
            <span className="text-sm sm:text-base text-gray-400">{p.nameZh}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default CompareBodyModel;
