import React, { useCallback, useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Search, Loader2, X, RotateCcw } from 'lucide-react';
import { getPlayers, getPlayersBulk } from '@client/src/api/players';
import { getPlayerTypes, getAttackStyles, getDefensiveStyles } from '@client/src/api/players';
import { getPackList, getPackDetail } from '@client/src/api/packs';
import { getMyFavorites } from '@client/src/api/favorites';
import TierPlayerCard from '@client/src/pages/tier-list/TierPlayerCard';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';
import { useAuth } from '@client/src/context/AuthContext';
import { pushBackHandler } from '@client/src/utils/back-intercept';
import { visitorLocalList } from '@client/src/utils/visitor-mode';
import VisitorModeBanner from '@client/src/components/VisitorModeBanner';

// 球员池里的球员（结构与强度榜快照一致）
export interface PoolPlayer {
  playerId: string;
  nameZh: string;
  nameEn: string;
  position?: string;
  playerImageUrl?: string | null;
}

export interface PoolCardPointerHandlers {
  ref?: (el: HTMLElement | null) => void;
  onPointerDown?: (e: React.PointerEvent) => void;
  onPointerMove?: (e: React.PointerEvent) => void;
  onPointerUp?: (e: React.PointerEvent) => void;
  onPointerCancel?: (e: React.PointerEvent) => void;
}

interface PlayerPoolPanelProps {
  // 每个结果卡片要绑定的指针拖拽行为（由使用方决定拖到哪、怎么落点）
  getCardHandlers: (item: PoolPlayer) => PoolCardPointerHandlers;
  // 是否已加入（展示“已加入”角标）
  isAdded?: (item: PoolPlayer) => boolean;
  // 操作提示小字
  hintText: string;
  // 是否显示（只读时可隐藏）
  show?: boolean;
  // 外层 section 的布局类名
  sectionClassName?: string;
}

const POSITION_OPTIONS: { v: string; l: string }[] = [
  { v: 'CF', l: '中锋' },
  { v: 'SS', l: '影锋' },
  { v: 'LWF', l: '左边锋' },
  { v: 'RWF', l: '右边锋' },
  { v: 'AMF', l: '前腰' },
  { v: 'LMF', l: '左前卫' },
  { v: 'RMF', l: '右前卫' },
  { v: 'CMF', l: '中前卫' },
  { v: 'DMF', l: '后腰' },
  { v: 'LB', l: '左后卫' },
  { v: 'RB', l: '右后卫' },
  { v: 'CB', l: '中后卫' },
  { v: 'GK', l: '门将' },
];

const toggleIn = (list: string[], v: string, setter: (n: string[]) => void): void =>
  setter(list.includes(v) ? list.filter((x) => x !== v) : [...list, v]);

// 按球员 id 列表批量映射成球员卡：bulk 接口每次最多 10 个，分批并行拉取后合并。
// 已登录（云端收藏）与游客（本机 localStorage 收藏）共用此映射。
const mapIdsToPoolPlayers = async (ids: string[]): Promise<PoolPlayer[]> => {
  if (ids.length === 0) return [];
  const chunks: string[][] = [];
  for (let i = 0; i < ids.length; i += 10) chunks.push(ids.slice(i, i + 10));
  const lists = await Promise.all(
    chunks.map((c) => getPlayersBulk(c).catch(() => [])),
  );
  return lists.flat().map((it) => ({
    playerId: it.playerId,
    nameZh: it.nameZh,
    nameEn: it.nameEn,
    position: it.position,
    playerImageUrl: it.playerImageUrl,
  }));
};

/**
 * 标准球员筛选 / 选择面板（强度榜、阵容共用）。
 * 自带：关键字、位置/类型/进攻风格/防守风格多选、卡包选择、无限滚动；
 * 初始不加载球员，用户搜索/选卡包后才请求。
 */
const PlayerPoolPanel: React.FC<PlayerPoolPanelProps> = ({
  getCardHandlers,
  isAdded,
  hintText,
  show = true,
  sectionClassName = 'min-w-0 flex-1 lg:overflow-y-auto',
}) => {
  const { t, lang } = useI18n();
  const { user } = useAuth();
  const [keyword, setKeyword] = useState('');
  const [posSel, setPosSel] = useState<string[]>([]);
  const [typeSel, setTypeSel] = useState<string[]>([]);
  const [attackSel, setAttackSel] = useState<string[]>([]);
  const [styleSel, setStyleSel] = useState<string[]>([]);
  const [filterOpen, setFilterOpen] = useState(false);
  // 筛选弹窗内的草稿选择：确认才提交，取消还原
  const [draftPos, setDraftPos] = useState<string[]>([]);
  const [draftType, setDraftType] = useState<string[]>([]);
  const [draftAttack, setDraftAttack] = useState<string[]>([]);
  const [draftStyle, setDraftStyle] = useState<string[]>([]);
  const [didSearch, setDidSearch] = useState(false);
  const [typeOptions, setTypeOptions] = useState<string[]>([]);
  const [attackOptions, setAttackOptions] = useState<string[]>([]);
  const [styleOptions, setStyleOptions] = useState<string[]>([]);
  const [results, setResults] = useState<PoolPlayer[]>([]);
  const [searching, setSearching] = useState(false);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(false);
  const loadedOnce = useRef(false);
  const sentinelRef = useRef<HTMLDivElement | null>(null);

  // 卡包选择
  const [packs, setPacks] = useState<{ id: string; label: string }[]>([]);
  const [packMode, setPackMode] = useState(false);
  // “我的球员”为特殊值：始终排第一、默认选中，球员池显示本账号收藏
  const MY_PLAYERS = '__my_players__';
  const [packId, setPackId] = useState(MY_PLAYERS);
  const [myMode, setMyMode] = useState(true);

  // 筛选选项 + 卡包列表
  useEffect(() => {
    getPlayerTypes?.()
      .then((r) => setTypeOptions(r.items ?? []))
      .catch(() => undefined);
    getAttackStyles?.()
      .then((r) => setAttackOptions(r.items ?? []))
      .catch(() => undefined);
    getDefensiveStyles?.()
      .then((r) => setStyleOptions(r.items ?? []))
      .catch(() => undefined);
    getPackList()
      .then((r) =>
        setPacks(
          (r.items ?? []).map((p) => ({
            id: p.id,
            // 与卡包页统一：优先官方真实名 originalName/enName，翻译名仅兜底
            label: p.originalName || p.enName || p.cnName || p.menuName,
          })),
        ),
      )
      .catch(() => undefined);
  }, []);

  const runSearch = useCallback(
    async (p = 1, overrides?: {
      keyword?: string;
      positions?: string[];
      playerTypes?: string[];
      attackStyles?: string[];
      defenseStyles?: string[];
    }) => {
      if (searching) return;
      setSearching(true);
      setPackMode(false);
      setMyMode(false);
      setDidSearch(true);
      try {
        const res = await getPlayers({
          page: p,
          pageSize: 24,
          keyword: (overrides?.keyword ?? keyword).trim() || undefined,
          positions: overrides?.positions ?? posSel,
          playerTypes: overrides?.playerTypes ?? typeSel,
          attackStyles: overrides?.attackStyles ?? attackSel,
          defenseStyles: overrides?.defenseStyles ?? styleSel,
          excludeStandard: true,
        } as any);
        const mapped: PoolPlayer[] = (res.items ?? []).map((it) => ({
          playerId: it.playerId,
          nameZh: it.nameZh,
          nameEn: it.nameEn,
          position: it.position,
          playerImageUrl: it.playerImageUrl,
        }));
        setResults(p === 1 ? mapped : (prev) => [...prev, ...mapped]);
        setPage(p);
        setHasMore(mapped.length === 24);
        loadedOnce.current = true;
      } catch {
        // 失败提示由调用方统一 toast 风格；这里轻量处理
        setDidSearch(true);
      } finally {
        setSearching(false);
      }
    },
    [keyword, posSel, typeSel, attackSel, styleSel, searching],
  );

  // 选择某个卡包：把该包全部球员载入球员池（替换），关闭无限滚动
  const onPickPack = async (id: string) => {
    setMyMode(false);
    if (!id) {
      setPackMode(false);
      setKeyword('');
      setPosSel([]);
      setTypeSel([]);
      setStyleSel([]);
      void runSearch(1);
      return;
    }
    setSearching(true);
    try {
      const det = await getPackDetail(id);
      const mapped: PoolPlayer[] = (det.players ?? []).map((it) => ({
        playerId: it.playerId,
        nameZh: it.nameZh,
        nameEn: it.nameEn,
        position: it.position,
        playerImageUrl: it.playerImageUrl,
      }));
      setResults(mapped);
      setHasMore(false);
      setPackMode(true);
      setDidSearch(true);
      loadedOnce.current = true;
    } catch {
      // ignore
    } finally {
      setSearching(false);
    }
  };

  // 选择“我的球员”：载入收藏的全部球员（替换球员池），关闭无限滚动
  const onPickMyPlayers = useCallback(async () => {
    setSearching(true);
    setPackMode(true);
    setMyMode(true);
    try {
      let mapped: PoolPlayer[];
      if (!user) {
        // 游客：展示本机 localStorage 收藏的球员（id 映射成球员卡），不再提示登录或空列表
        const ids = visitorLocalList('favorite_player');
        mapped = await mapIdsToPoolPlayers(ids);
      } else {
        // 已登录：分页拉完云端收藏（后端单页最多 50 条，设 10 页上限兜底）
        const favItems: { targetId: string }[] = [];
        for (let page = 1; page <= 10; page += 1) {
          const fav = await getMyFavorites({ targetType: 'player', page, pageSize: 50 });
          favItems.push(...(fav.items ?? []));
          if (favItems.length >= fav.total || (fav.items ?? []).length < 50) break;
        }
        const ids = favItems.map((x) => x.targetId).filter(Boolean);
        mapped = await mapIdsToPoolPlayers(ids);
      }
      setResults(mapped);
      setHasMore(false);
      setDidSearch(true);
      loadedOnce.current = true;
    } catch {
      setResults([]);
    } finally {
      setSearching(false);
    }
  }, [user]);

  // 重置：清空搜索/筛选条件，回到默认“我的球员”
  const resetPack = () => {
    setKeyword('');
    setPosSel([]);
    setTypeSel([]);
    setAttackSel([]);
    setStyleSel([]);
    setPackId(MY_PLAYERS);
    setMyMode(true);
    void onPickMyPlayers();
  };

  // 无限滚动
  useEffect(() => {
    const el = sentinelRef.current;
    if (!el) return;
    const io = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasMore && !searching && !packMode) {
          void runSearch(page + 1);
        }
      },
      { rootMargin: '200px' },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [hasMore, searching, page, runSearch, packMode]);

  // 打开筛选弹窗：把当前选择复制为草稿
  const openFilter = () => {
    setDraftPos(posSel);
    setDraftType(typeSel);
    setDraftAttack(attackSel);
    setDraftStyle(styleSel);
    setFilterOpen(true);
  };
  const cancelFilter = () => setFilterOpen(false);
  const resetFilter = () => {
    setDraftPos([]);
    setDraftType([]);
    setDraftAttack([]);
    setDraftStyle([]);
  };
  // 确认：草稿提交为正式筛选条件，并立即按新条件搜索（无需再点搜索）
  const confirmFilter = () => {
    setPosSel(draftPos);
    setTypeSel(draftType);
    setAttackSel(draftAttack);
    setStyleSel(draftStyle);
    setFilterOpen(false);
    void runSearch(1, {
      positions: draftPos,
      playerTypes: draftType,
      attackStyles: draftAttack,
      defenseStyles: draftStyle,
    });
  };

  // 首次进入默认加载“我的球员”（只执行一次）
  const didInitMy = useRef(false);
  useEffect(() => {
    if (didInitMy.current) return;
    didInitMy.current = true;
    void onPickMyPlayers();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 登录态异步恢复（null -> 有）后，若仍停在“我的球员”，重新载入
  const firstUserTick = useRef(true);
  useEffect(() => {
    if (firstUserTick.current) {
      firstUserTick.current = false;
      return;
    }
    if (user && myMode) void onPickMyPlayers();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id]);

  // 筛选弹窗打开时，APP 硬件返回/边缘内滑先关闭弹窗，而不是退出上一页
  useEffect(() => {
    if (!filterOpen) return undefined;
    return pushBackHandler(() => {
      setFilterOpen(false);
      return true;
    });
  }, [filterOpen]);

  if (!show) return null;

  const selCount = posSel.length + typeSel.length + attackSel.length + styleSel.length;
  const draftCount = draftPos.length + draftType.length + draftAttack.length + draftStyle.length;

  return (
    <section className={sectionClassName}>
      <div className="pool-font-scope rounded-xl border border-white/10 bg-white/[0.03] p-2.5">
        <div className="mb-1.5 flex items-center justify-between px-0.5">
          <p className="text-sm font-bold text-white">{t('pool.title')}</p>
          <p className="text-[11px] leading-tight text-white/40">
            {t('pool.hint')}
          </p>
        </div>
        <div className="pool-header flex flex-wrap items-center gap-1.5">
          <div className="pool-search flex min-w-[150px] flex-1 items-center gap-1.5 rounded-lg border border-white/15 bg-[#0d1230] px-2">
            <Search className="h-4 w-4 flex-shrink-0 text-white/40" />
            <input
              value={keyword}
              onChange={(e) => setKeyword(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && runSearch(1)}
              placeholder={t('pool.searchPh')}
              className="w-full bg-transparent py-1.5 text-sm text-white outline-none"
            />
          </div>
          <select
            value={packId}
            onChange={(e) => {
              const v = e.target.value;
              setPackId(v);
              setMyMode(v === MY_PLAYERS);
              if (v === MY_PLAYERS) void onPickMyPlayers();
              else void onPickPack(v);
            }}
            title={t('选择我的球员或者实时卡包')}
            aria-label={t('选择我的球员或者实时卡包')}
            className="pack-select max-w-[200px] rounded-lg border border-emerald-400/40 bg-[#0e1a18] px-1.5 py-1.5 text-emerald-200 outline-none"
          >
            {/* 我的球员：始终第一、默认选中，绿色区别于实时卡包 */}
            <option value={MY_PLAYERS} className="bg-[#0e1a18] font-bold text-emerald-300">
              {t('我的球员')}
            </option>
            {packs.map((p) => (
              <option key={p.id} value={p.id} className="bg-[#1a1430] text-amber-200">
                {p.label}
              </option>
            ))}
          </select>
          {packId && (
            <button
              type="button"
              onClick={resetPack}
              title={t('pool.resetPack')}
              aria-label={t('pool.resetPack')}
              className="flex h-[34px] w-[34px] items-center justify-center rounded-lg border border-amber-400/40 bg-amber-500/15 text-amber-200 hover:bg-amber-500/25"
            >
              <RotateCcw className="h-4 w-4" />
            </button>
          )}
          <button
            type="button"
            onClick={openFilter}
            className={`rounded-lg border px-3 py-1.5 text-sm font-bold transition ${
              selCount > 0
                ? 'border-cyan-400/60 bg-cyan-500/15 text-cyan-200'
                : 'border-white/15 bg-[#0d1230] text-white/80'
            }`}
          >
            {t('pool.filters')}{selCount > 0 ? ` ${selCount}` : ''}
          </button>
          <button
            type="button"
            onClick={() => runSearch(1)}
            className="rounded-lg bg-cyan-500 px-3.5 py-1.5 text-sm font-bold text-white hover:bg-cyan-400"
          >
            {t('pool.search')}
          </button>
        </div>

        {/* 多选筛选弹窗（确认/取消），草稿选择，确认才提交 */}
        {filterOpen &&
          createPortal(
            <div
              className="fixed inset-0 z-[9998] flex items-end justify-center bg-black/65 sm:items-center"
              onClick={cancelFilter}
            >
              <div
                className="filter-modal-mobile flex max-h-[88vh] w-full flex-col rounded-t-2xl bg-[#0e1430] sm:max-w-lg sm:rounded-2xl"
                onClick={(e) => e.stopPropagation()}
              >
                <div className="flex items-center justify-between border-b border-white/10 px-4 py-3">
                  <p className="fm-title text-lg font-black text-white">
                    {t('pool.filters')}{draftCount > 0
                      ? (lang === 'en' ? ` (${draftCount} selected)` : `（已选 ${draftCount}）`)
                      : ''}
                  </p>
                  <button
                    type="button"
                    onClick={cancelFilter}
                    aria-label={t('common.close')}
                    className="flex h-9 w-9 items-center justify-center rounded-full bg-white/10 text-white"
                  >
                    <X className="h-5 w-5" />
                  </button>
                </div>

                <div className="flex-1 space-y-4 overflow-y-auto p-4">
                  <div>
                    <p className="fm-label mb-2 text-sm font-bold text-white/55">{t('pool.posMulti')}</p>
                    <div className="flex flex-wrap gap-1.5">
                      {POSITION_OPTIONS.map((p) => {
                        const on = draftPos.includes(p.v);
                        return (
                          <button
                            key={p.v}
                            type="button"
                            onClick={() => toggleIn(draftPos, p.v, setDraftPos)}
                            className={`fm-pill rounded-full px-3 py-1 text-sm ${
                              on ? 'bg-cyan-500 text-white' : 'bg-white/10 text-white/65'
                            }`}
                          >
                            {lang === 'en' ? p.v : p.l}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                  {typeOptions.length > 0 && (
                    <div>
                      <p className="fm-label mb-2 text-sm font-bold text-white/55">{t('pool.typeMulti')}</p>
                      <div className="flex flex-wrap gap-1.5">
                        {typeOptions.map((t) => {
                          const on = draftType.includes(t);
                          return (
                            <button
                              key={t}
                              type="button"
                              onClick={() => toggleIn(draftType, t, setDraftType)}
                              className={`fm-pill rounded-full px-3 py-1 text-sm ${
                                on ? 'bg-fuchsia-500 text-white' : 'bg-white/10 text-white/65'
                              }`}
                            >
                              {trTerm(t)}
                            </button>
                          );
                        })}
                      </div>
                    </div>
                  )}
                  {attackOptions.length > 0 && (
                    <div>
                      <p className="fm-label mb-2 text-sm font-bold text-white/55">{t('pool.attackMulti')}</p>
                      <div className="flex flex-wrap gap-1.5">
                        {attackOptions.map((s) => {
                          const on = draftAttack.includes(s);
                          return (
                            <button
                              key={s}
                              type="button"
                              onClick={() => toggleIn(draftAttack, s, setDraftAttack)}
                              className={`fm-pill rounded-full px-3 py-1 text-sm ${
                                on ? 'bg-amber-500 text-white' : 'bg-white/10 text-white/65'
                              }`}
                            >
                              {trTerm(s)}
                            </button>
                          );
                        })}
                      </div>
                    </div>
                  )}
                  {styleOptions.length > 0 && (
                    <div>
                      <p className="fm-label mb-2 text-sm font-bold text-white/55">{t('pool.defenseMulti')}</p>
                      <div className="flex flex-wrap gap-1.5">
                        {styleOptions.map((s) => {
                          const on = draftStyle.includes(s);
                          return (
                            <button
                              key={s}
                              type="button"
                              onClick={() => toggleIn(draftStyle, s, setDraftStyle)}
                              className={`fm-pill rounded-full px-3 py-1 text-sm ${
                                on ? 'bg-emerald-500 text-white' : 'bg-white/10 text-white/65'
                              }`}
                            >
                              {trTerm(s)}
                            </button>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex gap-2 border-t border-white/10 p-3">
                  <button
                    type="button"
                    onClick={resetFilter}
                    className="fm-btn rounded-lg border border-white/15 bg-white/5 px-4 text-sm font-bold text-white/80"
                  >
                    {t('common.reset')}
                  </button>
                  <button
                    type="button"
                    onClick={cancelFilter}
                    className="fm-btn rounded-lg border border-white/15 bg-white/5 px-4 text-sm font-bold text-white/80"
                  >
                    {t('common.cancel')}
                  </button>
                  <button
                    type="button"
                    onClick={confirmFilter}
                    className="fm-btn flex-1 rounded-lg bg-cyan-500 text-sm font-black text-white active:bg-cyan-400"
                  >
                    {t('common.confirm')}{draftCount > 0 ? ` (${draftCount})` : ''}
                  </button>
                </div>
              </div>
            </div>,
            document.body,
          )}

        <p className="mt-2 text-[11px] text-white/40">{hintText}</p>

        {/* 游客在“我的球员”（本机收藏）视图时，提示数据仅保存在本机 */}
        {!user && myMode && (
          <div className="mt-2">
            <VisitorModeBanner />
          </div>
        )}

        {/* 竖屏：仅结果区在球员池内部滚动（搜索/筛选/卡包栏固定不动）；横屏由外层滚动 */}
        <div className="pool-scroll-mobile max-h-[46vh] lg:max-h-none lg:overflow-visible">
        {searching && results.length === 0 ? (
          <div className="flex items-center justify-center gap-2 py-12 text-white/60">
            <Loader2 className="h-5 w-5 animate-spin" /> {t('pool.loading')}
          </div>
        ) : results.length === 0 ? (
          <p className="py-12 text-center text-sm text-white/50">
            {myMode
              ? (user
                ? t('还没有收藏球员，去球员详情点右上角爱心收藏吧')
                : t('本机暂无收藏的球员，去球员详情点爱心收藏吧'))
              : (didSearch ? t('pool.noResult') : t('pool.empty'))}
          </p>
        ) : (
          <div className="mt-2 grid grid-cols-5 gap-1 lg:grid-cols-6">
            {results.map((item) => {
              const h = getCardHandlers(item);
              return (
                <div key={item.playerId} className="drag-touch relative" {...h}>
                  <TierPlayerCard item={item as any} />
                  {isAdded?.(item) && (
                    <span className="absolute bottom-5 left-1/2 z-10 -translate-x-1/2 rounded bg-green-500/90 px-1.5 py-0.5 text-[9px] font-bold text-white">
                      {t('pool.added')}
                    </span>
                  )}
                </div>
              );
            })}
          </div>
        )}

        <div ref={sentinelRef} className="h-4" />
        {searching && results.length > 0 && (
          <div className="flex items-center justify-center gap-2 py-2 text-white/50">
            <Loader2 className="h-4 w-4 animate-spin" /> {t('pool.loadMore')}
          </div>
        )}
        </div>
      </div>
    </section>
  );
};

export default PlayerPoolPanel;
