import React from 'react';
import { X } from 'lucide-react';
import { Badge } from '@client/src/components/ui/badge';
import { RADAR_MIN_LABELS, POSITION_LABEL_MAP, getPlayerTypeLabel, type PlayerFilterState } from './player-utils';
import { getFormConsistencyLabel } from '@client/src/utils/form-consistency';

interface ActiveFilterBadgesProps {
  filters: PlayerFilterState;
  onRemovePosition: (pos: string) => void;
  onRemoveAttackStyle: (s: string) => void;
  onRemoveDefenseStyle: (s: string) => void;
  onRemoveAiStyle: (s: string) => void;
  onRemoveNationality: () => void;
  onClearClub: () => void;
  onRemoveCommonSkill: (s: string) => void;
  onRemoveStSkill: (s: string) => void;
  onClearPreferredFoot: () => void;
  onClearWeakFootFreq: () => void;
  onClearWeakFootAcc: () => void;
  onClearFormConsistency: () => void;
  onClearPlayerType: () => void;
  onRemovePlayerType: (t: string) => void;
  onClearLeague: () => void;
  onRemoveTeam: (t: string) => void;
  onClearOverall: () => void;
  onClearAge: () => void;
  onClearHeight: () => void;
  onClearWeight: () => void;
  onClearRadar: (key: string) => void;
}

export const ActiveFilterBadges: React.FC<ActiveFilterBadgesProps> = ({
  filters,
  onRemovePosition,
  onRemoveAttackStyle,
  onRemoveDefenseStyle,
  onRemoveAiStyle,
  onRemoveNationality,
  onClearClub,
  onRemoveCommonSkill,
  onRemoveStSkill,
  onClearPreferredFoot,
  onClearWeakFootFreq,
  onClearWeakFootAcc,
  onClearFormConsistency,
  onClearPlayerType,
  onRemovePlayerType,
  onClearLeague,
  onRemoveTeam,
  onClearOverall,
  onClearAge,
  onClearHeight,
  onClearWeight,
  onClearRadar,
}) => {
  const {
    positions,
    attackStyles,
    defenseStyles,
    aiStyles,
    nationality,
    club,
    commonSkills,
    stSkills,
    preferredFoot,
    weakFootFreq,
    weakFootAcc,
    formConsistency,
    playerTypes,
    league,
    teamSeasons,
    overallMin,
    overallMax,
    ageMin,
    ageMax,
    heightMin,
    heightMax,
    weightMin,
    weightMax,
    radarMins,
  } = filters;

  return (
     <div className="flex flex-wrap items-center gap-1.5 pt-1">
       <span className="text-[11px] text-gray-500">已选条件：</span>
       {positions.map((p: string) => (
         <Badge
           key={`pos-${p}`}
           variant="secondary"
            className="bg-cyan-400/15 text-cyan-300 text-[10px]"
         >
           位置: {POSITION_LABEL_MAP[p] || p}
           <button
             onClick={() => onRemovePosition(p)}
             className="ml-1 hover:text-white"
           >
             <X className="h-3 w-3" />
           </button>
         </Badge>
       ))}
       {attackStyles.map((s: string) => (
         <Badge
           key={`attack-${s}`}
           variant="secondary"
            className="bg-cyan-400/15 text-cyan-300 text-[10px]"
         >
           进攻: {s}
           <button
             onClick={() => onRemoveAttackStyle(s)}
             className="ml-1 hover:text-white"
           >
             <X className="h-3 w-3" />
           </button>
         </Badge>
       ))}
        {defenseStyles.map((s: string) => (
          <Badge
            key={`defense-${s}`}
            variant="secondary"
             className="bg-cyan-400/15 text-cyan-300 text-[10px]"
          >
            防守: {s}
            <button
              onClick={() => onRemoveDefenseStyle(s)}
              className="ml-1 hover:text-white"
            >
              <X className="h-3 w-3" />
            </button>
          </Badge>
        ))}
        {aiStyles.map((s: string) => (
          <Badge
            key={`ai-${s}`}
            variant="secondary"
            className="bg-purple-500/20 text-purple-300 text-[10px]"
          >
            AI: {s}
            <button
              onClick={() => onRemoveAiStyle(s)}
              className="ml-1 hover:text-white"
            >
              <X className="h-3 w-3" />
            </button>
          </Badge>
        ))}
        {nationality && (
         <Badge
           variant="secondary"
           className="bg-orange-500/20 text-orange-300 text-[10px]"
         >
           国家队: {nationality}
           <button onClick={onRemoveNationality} className="ml-1 hover:text-white">
             <X className="h-3 w-3" />
           </button>
         </Badge>
       )}
       {club && (
         <Badge
           variant="secondary"
           className="bg-orange-500/20 text-orange-300 text-[10px]"
         >
           俱乐部: {club}
           <button onClick={onClearClub} className="ml-1 hover:text-white">
             <X className="h-3 w-3" />
           </button>
         </Badge>
       )}
       {commonSkills.map((s: string) => (
         <Badge
           key={`cskill-${s}`}
           variant="secondary"
           className="bg-purple-500/20 text-purple-300 text-[10px]"
         >
           技能: {s}
           <button
             onClick={() => onRemoveCommonSkill(s)}
             className="ml-1 hover:text-white"
           >
             <X className="h-3 w-3" />
           </button>
         </Badge>
       ))}
       {stSkills.map((s: string) => (
         <Badge
           key={`stskill-${s}`}
           variant="secondary"
           className="bg-amber-500/20 text-amber-300 text-[10px]"
         >
           ST: {s}
           <button
             onClick={() => onRemoveStSkill(s)}
             className="ml-1 hover:text-white"
           >
             <X className="h-3 w-3" />
           </button>
         </Badge>
        ))}
        {preferredFoot && (
          <Badge
            variant="secondary"
            className="bg-teal-500/20 text-teal-300 text-[10px]"
          >
            惯用脚: {preferredFoot}
            <button
              onClick={onClearPreferredFoot}
              className="ml-1 hover:text-white"
            >
              <X className="h-3 w-3" />
            </button>
          </Badge>
        )}
        {weakFootFreq && (
         <Badge
           variant="secondary"
           className="bg-emerald-500/20 text-emerald-300 text-[10px]"
         >
           逆足频率 ≥ {weakFootFreq}
           <button onClick={onClearWeakFootFreq} className="ml-1 hover:text-white">
             <X className="h-3 w-3" />
           </button>
         </Badge>
       )}
       {weakFootAcc && (
         <Badge
           variant="secondary"
           className="bg-emerald-500/20 text-emerald-300 text-[10px]"
         >
           逆足精度 ≥ {weakFootAcc}
           <button onClick={onClearWeakFootAcc} className="ml-1 hover:text-white">
             <X className="h-3 w-3" />
           </button>
         </Badge>
       )}
       {formConsistency && (
         <Badge
           variant="secondary"
           className="bg-emerald-500/20 text-emerald-300 text-[10px]"
         >
           状态波动 ≥ {getFormConsistencyLabel(parseInt(formConsistency, 10))}
           <button onClick={onClearFormConsistency} className="ml-1 hover:text-white">
             <X className="h-3 w-3" />
           </button>
         </Badge>
       )}
        {playerTypes.map((t: string) => (
          <Badge
            key={`pt-${t}`}
            variant="secondary"
            className="bg-purple-500/20 text-purple-300 text-[10px]"
          >
            类型: {getPlayerTypeLabel(t)}
            <button onClick={() => onRemovePlayerType(t)} className="ml-1 hover:text-white">
              <X className="h-3 w-3" />
            </button>
          </Badge>
        ))}
        {league !== '' && (
          <Badge
            variant="secondary"
            className="bg-orange-500/20 text-orange-300 text-[10px]"
          >
            联赛: {league}
            <button onClick={onClearLeague} className="ml-1 hover:text-white">
              <X className="h-3 w-3" />
            </button>
          </Badge>
        )}
        {teamSeasons.map((t: string) => (
          <Badge
            key={`team-${t}`}
            variant="secondary"
             className="bg-cyan-400/15 text-cyan-300 text-[10px]"
          >
            {t}
            <button
              onClick={() => onRemoveTeam(t)}
              className="ml-1 hover:text-white"
            >
              <X className="h-3 w-3" />
            </button>
          </Badge>
        ))}
        {(overallMin !== '' || overallMax !== '') && (
         <Badge
           variant="secondary"
           className="bg-yellow-500/20 text-yellow-300 text-[10px]"
         >
           总评 {overallMin || '?'}-{overallMax || '?'}
           <button onClick={onClearOverall} className="ml-1 hover:text-white">
             <X className="h-3 w-3" />
           </button>
         </Badge>
       )}
       {(ageMin !== '' || ageMax !== '') && (
         <Badge
           variant="secondary"
           className="bg-blue-500/20 text-blue-300 text-[10px]"
         >
           年龄 {ageMin || '?'}-{ageMax || '?'}
           <button onClick={onClearAge} className="ml-1 hover:text-white">
             <X className="h-3 w-3" />
           </button>
         </Badge>
       )}
       {(heightMin !== '' || heightMax !== '') && (
         <Badge
           variant="secondary"
           className="bg-blue-500/20 text-blue-300 text-[10px]"
         >
           身高 {heightMin || '?'}-{heightMax || '?'}
           <button onClick={onClearHeight} className="ml-1 hover:text-white">
             <X className="h-3 w-3" />
           </button>
         </Badge>
       )}
       {(weightMin !== '' || weightMax !== '') && (
         <Badge
           variant="secondary"
           className="bg-blue-500/20 text-blue-300 text-[10px]"
         >
           体重 {weightMin || '?'}-{weightMax || '?'}
           <button onClick={onClearWeight} className="ml-1 hover:text-white">
             <X className="h-3 w-3" />
           </button>
         </Badge>
       )}
       {RADAR_MIN_LABELS.map(({ key, label }) =>
          radarMins[key] != null && radarMins[key] !== '' ? (
           <Badge
             key={`radar-${key}`}
             variant="secondary"
             className="bg-emerald-500/20 text-emerald-300 text-[10px]"
           >
             {label} ≥ {radarMins[key]}
             <button
               onClick={() => onClearRadar(key)}
               className="ml-1 hover:text-white"
             >
               <X className="h-3 w-3" />
             </button>
           </Badge>
         ) : null,
       )}
     </div>
  );
};
