/**
 * 统一媒体上传：
 * - 自建环境（Capacitor 原生 APP，或 playtostar.com 网页）：走后端 multipart /api/forum/media/upload
 * - 妙达 authoring 环境：保留平台 dataloom 存储 SDK
 */
import { Capacitor } from '@capacitor/core';
import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';
import { getDataloom } from '@lark-apaas/client-toolkit/dataloom';
import { getDefaultBucketId } from '@lark-apaas/client-toolkit/tools/storage';

export interface UploadedMedia {
  url: string;
  type: 'image' | 'video';
  filename: string;
  size: number;
}

export function isSelfHostedRuntime(): boolean {
  if (Capacitor.isNativePlatform()) return true;
  if (typeof window !== 'undefined' && window.location) {
    const host = window.location.hostname;
    if (host === 'playtostar.com' || host.endsWith('.playtostar.com')) return true;
  }
  return false;
}

async function uploadViaBackend(file: File): Promise<UploadedMedia> {
  const form = new FormData();
  form.append('file', file);
  const response = await axiosForBackend.post<UploadedMedia>(
    '/api/forum/media/upload',
    form,
    {
      headers: { 'Content-Type': 'multipart/form-data' },
    },
  );
  return response.data;
}

async function uploadViaDataloom(file: File): Promise<UploadedMedia> {
  const dataloom = await getDataloom();
  const { data, error } = await dataloom.storage
    .from(getDefaultBucketId())
    .uploadFile(file);
  if (error) {
    throw new Error(typeof error === 'string' ? error : error.message || '上传失败');
  }
  const isVideo = file.type.startsWith('video/');
  return {
    url: data.download_url,
    type: isVideo ? 'video' : 'image',
    filename: file.name,
    size: file.size,
  };
}

export async function uploadMediaItem(file: File): Promise<UploadedMedia> {
  if (isSelfHostedRuntime()) {
    return uploadViaBackend(file);
  }
  return uploadViaDataloom(file);
}
