export function getTotalStats(player: Player): number {
  let sum = 0;
  const s = player.attackStats;
  sum +=
    s.offensiveAwareness.rating +
    s.ballControl.rating +
    s.dribbling.rating +
    s.tightPossession.rating +
    s.lowPass.rating +
    s.loftedPass.rating +
    s.finishing.rating +
    s.header.rating +
    s.setPieceTaking.rating +
    s.curve.rating;
  const d = player.defenseStats;
  sum +=
    d.defensiveAwareness.rating +
    d.tackle.rating +
    d.aggression.rating +
    d.defensiveEngagement.rating +
    d.gkAwareness.rating +
    d.gkCatching.rating +
    d.gkClearing.rating +
    d.gkReflexes.rating +
    d.gkReach.rating;
  const p = player.powerStats;
  sum +=
    p.speed.rating +
    p.acceleration.rating +
    p.kickingPower.rating +
    p.jump.rating +
    p.physicalContact.rating +
    p.balance.rating +
    p.stamina.rating;
  return sum;
}

export function getSortValue(
  player: PlayerListItem,
  field: PlayerSortField,
): number | string {
  switch (field) {
    case 'overallRating':
      return player.overallRating;
    case 'height':
      return player.height;
    case 'offensiveAwareness': {
      const r = player.attackStats?.offensiveAwareness?.rating ?? 0;
      return r as number;
    }
    case 'passing': {
      const s = player.attackStats;
      if (!s) return 0;
      const low = (s as any).lowPass?.rating ?? 0;
      const lofted = (s as any).loftedPass?.rating ?? 0;
      const curve = (s as any).curve?.rating ?? 0;
      return (low + lofted + curve) / 3;
    }
    case 'shooting': {
      const s = player.attackStats;
      if (!s) return 0;
      const finishing = (s as any).finishing?.rating ?? 0;
      const kickingPower = (player.powerStats as any)?.kickingPower?.rating ?? 0;
      const setPiece = (s as any).setPieceTaking?.rating ?? 0;
      const curve = (s as any).curve?.rating ?? 0;
      return (finishing + kickingPower + setPiece + curve) / 4;
    }
    case 'defending': {
      const d = player.defenseStats;
      if (!d) return 0;
      const awareness = (d as any).defensiveAwareness?.rating ?? 0;
      const tackle = (d as any).tackle?.rating ?? 0;
      const aggression = (d as any).aggression?.rating ?? 0;
      const engagement = (d as any).defensiveEngagement?.rating ?? 0;
      return (awareness + tackle + aggression + engagement) / 4;
    }
    case 'speed': {
      const p = player.powerStats;
      const a = player.attackStats;
      if (!p) return 0;
      const speed = (p as any).speed?.rating ?? 0;
      const acceleration = (p as any).acceleration?.rating ?? 0;
      const dribbling = (a as any).dribbling?.rating ?? 0;
      return (speed + acceleration + dribbling) / 3;
    }
    case 'dribbling': {
      const s = player.attackStats;
      if (!s) return 0;
      const ballControl = (s as any).ballControl?.rating ?? 0;
      const dribbling = (s as any).dribbling?.rating ?? 0;
      const tightPossession = (s as any).tightPossession?.rating ?? 0;
      return (ballControl + dribbling + tightPossession) / 3;
    }
    case 'physical': {
      const p = player.powerStats;
      if (!p) return 0;
      const balance = (p as any).balance?.rating ?? 0;
      const physicalContact = (p as any).physicalContact?.rating ?? 0;
      return (balance + physicalContact) / 2;
    }
    case 'aerial': {
      const p = player.powerStats;
      const a = player.attackStats;
      if (!p) return 0;
      const jump = (p as any).jump?.rating ?? 0;
      const physicalContact = (p as any).physicalContact?.rating ?? 0;
      const header = (a as any).header?.rating ?? 0;
      return (jump + physicalContact + header) / 3;
    }
    default:
      return 0;
  }
}

export function sortPlayers(
  players: PlayerListItem[],
  sortBy: PlayerSortField,
  sortOrder: 'asc' | 'desc',
): PlayerListItem[] {
  return [...players].sort((a: PlayerListItem, b: PlayerListItem) => {
    const va = getSortValue(a, sortBy);
    const vb = getSortValue(b, sortBy);
    if (typeof va === 'number' && typeof vb === 'number') {
      return sortOrder === 'desc' ? vb - va : va - vb;
    }
    const sa = String(va);
    const sb = String(vb);
    return sortOrder === 'desc'
      ? sb.localeCompare(sa, 'zh-CN')
      : sa.localeCompare(sb, 'zh-CN');
  });
}

