export function normalizePreferredFoot(value: string | null | undefined): string {
  if (!value) return '--';
  const v = value.trim().toLowerCase();
  if (['右', '右脚', 'right', 'r', '右脚'].includes(v) || value === '右' || value === '右脚') return '右';
  if (['左', '左脚', 'left', 'l', '左脚'].includes(v) || value === '左' || value === '左脚') return '左';
  return value;
}

const GK_POSITIONS = ['GK', '门将', '守门员'];
// 长距离手抛类技能：外场“大力手抛球”（界外球）与门将“门将大力手抛球”是两个技能，
// 对比页按是否含门将做展示合并；百科长名“门将远距离投掷”等异名已由 shared 归一
const LONG_THROW_SKILLS = ['大力手抛球', '门将大力手抛球', '门将远距离投掷'];

export function isGKPosition(pos?: string | null): boolean {
  if (!pos) return false;
  return GK_POSITIONS.some((gk) => pos.includes(gk) || pos === gk);
}

export function normalizeSkillForPlayer(skill: string, position?: string | null): string {
  // 先归一 ST 技能（伸腿抢截/伸腿拦截 → 伸脚抢截），再做普通技能别名归一
  const canon = normalizeCommonSkillName(normalizeStSkillName(skill));
  if (LONG_THROW_SKILLS.includes(canon) && isGKPosition(position)) {
    return '门将大力手抛球';
  }
  if (LONG_THROW_SKILLS.includes(canon) && !isGKPosition(position)) {
    return '大力手抛球';
  }
  return canon;
}

export function isSameSkill(a: string, b: string): boolean {
  // 先归一 ST 技能（如 伸腿抢截/伸腿拦截 → 伸脚抢截），再归一普通技能
  const ca = normalizeCommonSkillName(normalizeStSkillName(a));
  const cb = normalizeCommonSkillName(normalizeStSkillName(b));
  if (ca === cb) return true;
  return LONG_THROW_SKILLS.includes(ca) && LONG_THROW_SKILLS.includes(cb);
}

export const WEAK_FOOT_OPTIONS = ['1', '2', '3', '4'];

export function compareByPinyin(a: string, b: string): number {
  return a.localeCompare(b, 'zh-CN', { sensitivity: 'base' });
}

export function sortOptions(list: string[]): string[] {
  return [...list].sort(compareByPinyin);
}

export function filterPlayers(
  players: PlayerListItem[],
  filters: PlayerFilterState,
): PlayerListItem[] {
  let result = [...players];
  const {
    positions,
    attackStyles,
    defenseStyles,
    aiStyles,
    nationality,
    club,
    commonSkills,
    stSkills,
    preferredFoot,
    weakFootFreq,
    weakFootAcc,
    formConsistency,
    playerTypes,
    league,
    teamSeasons,
    overallMin,
    overallMax,
    ageMin,
    ageMax,
    heightMin,
    heightMax,
    weightMin,
    weightMax,
    radarMins,
  } = filters;

  if (positions.length > 0) {
    result = result.filter((p: PlayerListItem) => positions.includes(p.position));
  }
  if (attackStyles.length > 0) {
    result = result.filter((p: PlayerListItem) => attackStyles.includes(p.style));
  }
  if (defenseStyles.length > 0) {
    result = result.filter((p: PlayerListItem) => defenseStyles.includes(p.style));
  }  if (aiStyles.length > 0) {
    result = result.filter((p: PlayerListItem) => {
      const ai = p.aiPlayStyle || '';
      return aiStyles.every((s: string) => ai.includes(s));
    });
  }
  if (nationality !== '') {
    result = result.filter((p: PlayerListItem) => p.nationality === nationality);
  }
  if (club !== '') {
    const lower = club.toLowerCase();
    result = result.filter(
      (p: PlayerListItem) => p.club && p.club.toLowerCase().includes(lower),
    );
  }
  if (commonSkills.length > 0) {
    result = result.filter((p: PlayerListItem) => {
      const skills = p.skills || [];
      return commonSkills.every((s: string) => skills.includes(s));
    });
  }
  if (stSkills.length > 0) {
    result = result.filter((p: PlayerListItem) => {
      const skills = p.skills || [];
      const normalizedSkills = skills.map(normalizeStSkillName);
      return stSkills.every((s: string) => normalizedSkills.includes(s));
    });
  }
  if (preferredFoot !== '') {
    result = result.filter((p: PlayerListItem) => p.preferredFoot === preferredFoot);
  }
  if (weakFootFreq !== '') {
    const v = parseInt(weakFootFreq, 10);
    result = result.filter((p: PlayerListItem) => (p.weakFootFrequency || 0) >= v);
  }
  if (weakFootAcc !== '') {
    const v = parseInt(weakFootAcc, 10);
    result = result.filter((p: PlayerListItem) => (p.weakFootAccuracy || 0) >= v);
  }
  if (formConsistency !== '') {
    const v = parseInt(formConsistency, 10);
    result = result.filter((p: PlayerListItem) => (p.formVariation || 0) >= v);
  }
  if (playerTypes && playerTypes.length > 0) {
    result = result.filter((p: PlayerListItem) =>
      p.playerType != null && playerTypes.includes(p.playerType),
    );
  }
  if (league !== '') {
    const lower = league.toLowerCase();
    result = result.filter(
      (p: PlayerListItem) => p.league && p.league.toLowerCase().includes(lower),
    );
  }
  if (teamSeasons.length > 0) {
    result = result.filter((p: PlayerListItem) =>
      teamSeasons.includes(p.teamSeason),
    );
  }
  if (overallMin !== '') {
    const v = parseInt(overallMin, 10);
    result = result.filter((p: PlayerListItem) => p.overallRating >= v);
  }
  if (overallMax !== '') {
    const v = parseInt(overallMax, 10);
    result = result.filter((p: PlayerListItem) => p.overallRating <= v);
  }
  if (ageMin !== '') {
    const v = parseInt(ageMin, 10);
    result = result.filter((p: PlayerListItem) => p.age >= v);
  }
  if (ageMax !== '') {
    const v = parseInt(ageMax, 10);
    result = result.filter((p: PlayerListItem) => p.age <= v);
  }
  if (heightMin !== '') {
    const v = parseInt(heightMin, 10);
    result = result.filter((p: PlayerListItem) => p.height >= v);
  }
  if (heightMax !== '') {
    const v = parseInt(heightMax, 10);
    result = result.filter((p: PlayerListItem) => p.height <= v);
  }
  if (weightMin !== '') {
    const v = parseInt(weightMin, 10);
    result = result.filter((p: PlayerListItem) => p.weight >= v);
  }
  if (weightMax !== '') {
    const v = parseInt(weightMax, 10);
    result = result.filter((p: PlayerListItem) => p.weight <= v);
  }

  const radarKeys = Object.keys(radarMins || {});
  for (const key of radarKeys) {
    const raw = radarMins[key];
    if (raw === '' || raw == null) continue;
    const v = parseInt(raw, 10);
    if (isNaN(v)) continue;
    result = result.filter((p: PlayerListItem) => {
      const val = getSortValue(p, key as PlayerSortField);
      return typeof val === 'number' && val >= v;
    });
  }

  return result;
}

export function hasActiveFilters(filters: PlayerFilterState): boolean {
  return (
    filters.positions.length > 0 ||
    filters.attackStyles.length > 0 ||
    filters.defenseStyles.length > 0 ||
    filters.aiStyles.length > 0 ||
    filters.nationality !== '' ||
    filters.club !== '' ||
    filters.commonSkills.length > 0 ||
    filters.stSkills.length > 0 ||
    filters.weakFootFreq !== '' ||
    filters.weakFootAcc !== '' ||
    filters.formConsistency !== '' ||
    filters.playerTypes.length > 0 ||
    filters.league !== '' ||
    filters.teamSeasons.length > 0 ||
    filters.overallMin !== '' ||
    filters.overallMax !== '' ||
    filters.ageMin !== '' ||
    filters.ageMax !== '' ||
    filters.heightMin !== '' ||
    filters.heightMax !== '' ||
    filters.weightMin !== '' ||
    filters.weightMax !== '' ||
    Object.values(filters.radarMins).some((v: string) => v !== '')
  );
}
