import React, { useRef, useState, useCallback, useEffect } from 'react';
import { Loader2, RefreshCw } from 'lucide-react';

interface PullToRefreshProps {
  onRefresh: () => Promise<void> | void;
  children: React.ReactNode;
  /** 是否禁用下拉刷新，默认 false */
  disabled?: boolean;
  /** 触发刷新所需的下拉距离，默认 70px */
  threshold?: number;
  /** 最大允许下拉距离，默认 120px */
  maxPullDistance?: number;
  /** 刷新中指示器停留距离，默认 50px */
  loadingDistance?: number;
}

const PullToRefresh: React.FC<PullToRefreshProps> = ({
  onRefresh,
  children,
  disabled = false,
  threshold = 70,
  maxPullDistance = 120,
  loadingDistance = 50,
}) => {
  const [pullDistance, setPullDistance] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const startYRef = useRef<number | null>(null);
  const isPullingRef = useRef(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const isAtTop = useCallback((): boolean => {
    return window.scrollY <= 0;
  }, []);

  const handleTouchStart = useCallback((e: React.TouchEvent) => {
    if (disabled) return;
    if (isRefreshing) return;
    if (!isAtTop()) return;
    startYRef.current = e.touches[0].clientY;
    isPullingRef.current = true;
  }, [disabled, isAtTop, isRefreshing]);

  const handleTouchMove = useCallback((e: React.TouchEvent) => {
    if (disabled) return;
    if (!isPullingRef.current || startYRef.current === null) return;
    if (isRefreshing) return;

    const currentY = e.touches[0].clientY;
    const delta = currentY - startYRef.current;

    if (delta <= 0) {
      setPullDistance(0);
      return;
    }

    if (!isAtTop() && delta > 0) {
      startYRef.current = currentY;
      return;
    }

    const damped = delta * 0.5;
    const clamped = Math.min(damped, maxPullDistance);
    setPullDistance(clamped);
  }, [isAtTop, isRefreshing, maxPullDistance]);

  const handleTouchEnd = useCallback(async () => {
    if (disabled) return;
    if (!isPullingRef.current) return;
    isPullingRef.current = false;
    startYRef.current = null;

    if (isRefreshing) return;

    if (pullDistance >= threshold) {
      setPullDistance(loadingDistance);
      setIsRefreshing(true);
      try {
        await onRefresh();
      } finally {
        setIsRefreshing(false);
        setPullDistance(0);
      }
    } else {
      setPullDistance(0);
    }
  }, [pullDistance, threshold, isRefreshing, loadingDistance, onRefresh]);

  const showIndicator = pullDistance > 0;
  const canRefresh = pullDistance >= threshold;

  if (disabled) {
    return <>{children}</>;
  }

  return (
    <div
      ref={containerRef}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
      onTouchCancel={handleTouchEnd}
      className="relative"
      style={{ touchAction: 'pan-y' }}
    >
      <div
        className="pointer-events-none absolute left-0 right-0 flex items-center justify-center overflow-hidden transition-[height,opacity] duration-200"
        style={{
          top: 0,
          height: pullDistance,
          opacity: pullDistance > 5 ? 1 : 0,
          zIndex: 0,
        }}
      >
        <div className="flex items-center gap-2 text-xs text-gray-400">
          {isRefreshing ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin text-cyan-400" />
              <span>刷新中...</span>
            </>
          ) : canRefresh ? (
            <>
              <RefreshCw className="h-4 w-4 text-cyan-400" />
              <span className="text-cyan-300">松开刷新</span>
            </>
          ) : (
            <>
              <RefreshCw className="h-4 w-4 text-gray-500" />
              <span>下拉刷新</span>
            </>
          )}
        </div>
      </div>
      <div
        className="relative transition-transform duration-200 ease-out"
        style={{
          transform: `translateY(${pullDistance}px)`,
          zIndex: 1,
        }}
      >
        {children}
      </div>
    </div>
  );
};

export default PullToRefresh;
