import React, {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from 'react';
import { Newspaper, Loader2, Search } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

import { getNewsList } from '@client/src/api/news';
import type { NewsArticle } from '@shared/api.interface';
import { useI18n } from '@client/src/i18n/I18nProvider';
import NewsCard from './NewsCard';

// 热讯信息流：搜索 + 瀑布卡片。
// 懒加载：初始只拉第一页 PAGE_SIZE 条，滚动到接近底部再拉下一页追加（不全拉100条）。
// 从详情返回时用 sessionStorage 恢复已加载内容 / 页码 / 浏览位置。

const STORAGE_KEY = 'news_feed_state';
const PAGE_SIZE = 12;

interface FeedCache {
  items: NewsArticle[];
  page: number;
  total: number;
  keyword: string;
  scrollTop: number;
}

function readCache(): FeedCache | null {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    return raw ? (JSON.parse(raw) as FeedCache) : null;
  } catch {
    return null;
  }
}

export interface NewsFeedHandle {
  refresh: () => Promise<void>;
}

const NewsFeed = forwardRef<NewsFeedHandle>((_, ref) => {
  const { t } = useI18n();
  const navigate = useNavigate();

  // 首次挂载若有缓存（从详情返回、且无搜索词），立即恢复、不闪 loading
  const initialCache = readCache();
  const hasCache = !!initialCache && !initialCache.keyword;

  const [items, setItems] = useState<NewsArticle[]>(
    hasCache && initialCache ? initialCache.items : [],
  );
  const [page, setPage] = useState(
    hasCache && initialCache ? initialCache.page : 0,
  );
  const [total, setTotal] = useState(
    hasCache && initialCache ? initialCache.total : 0,
  );
  const [loading, setLoading] = useState(!hasCache);
  const [loadingMore, setLoadingMore] = useState(false);
  const [keyword, setKeyword] = useState('');
  const savedScrollRef = useRef<number | null>(
    hasCache && initialCache ? initialCache.scrollTop : null,
  );
  const sentinelRef = useRef<HTMLDivElement | null>(null);

  const hasMore = items.length < total;

  // 加载指定页：p=1 替换（首屏/搜索）；其余追加并按 id 去重
  const loadPage = useCallback(async (kw: string, p: number) => {
    const isFirst = p === 1;
    if (isFirst) setLoading(true);
    else setLoadingMore(true);
    try {
      const res = await getNewsList({
        keyword: kw.trim() || undefined,
        page: p,
        pageSize: PAGE_SIZE,
      });
      setTotal(res.total);
      setPage(p);
      setItems((prev) => {
        if (isFirst) return res.items;
        const map = new Map(prev.map((a) => [a.id, a]));
        res.items.forEach((a) => map.set(a.id, a));
        return Array.from(map.values());
      });
    } finally {
      if (isFirst) setLoading(false);
      else setLoadingMore(false);
    }
  }, []);

  // 顶部下拉刷新：重新拉第一页（供合体页 PullToRefresh 在热讯板调用）
  const refresh = useCallback(async () => {
    await loadPage(keyword, 1);
  }, [loadPage, keyword]);

  useImperativeHandle(ref, () => ({ refresh }), [refresh]);

  // 首次挂载：无缓存拉首页；有缓存先恢复（位置/内容），再后台静默校验第一页，
  // 用最新的首页条目与 total 覆盖缓存——避免 sessionStorage 里旧 total 偏小、
  // 误判“已经到底”而漏加载新内容（网页端反复测试时极易残留这种旧缓存）。
  useEffect(() => {
    if (!hasCache) {
      void loadPage('', 1);
    } else {
      void (async () => {
        try {
          const res = await getNewsList({ page: 1, pageSize: PAGE_SIZE });
          setTotal(res.total);
          setItems((prev) => {
            // 最新首页置前，缓存里已加载的更老条目去重后接在后面，不丢已加载内容
            const freshIds = new Set(res.items.map((a) => a.id));
            const older = prev.filter((a) => !freshIds.has(a.id));
            return [...res.items, ...older];
          });
        } catch {
          /* 静默失败：保留缓存内容，不影响浏览 */
        }
      })();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 搜索：关键词变化（首次恢复场景除外）防抖后重置回首页
  useEffect(() => {
    if (!keyword && hasCache) return;
    const tm = setTimeout(() => void loadPage(keyword, 1), 300);
    return () => clearTimeout(tm);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [keyword]);

  // 恢复缓存后的浏览位置
  useEffect(() => {
    if (loading) return;
    const y = savedScrollRef.current;
    if (y != null && y > 0) {
      const raf = requestAnimationFrame(() => window.scrollTo(0, y));
      savedScrollRef.current = null;
      return () => cancelAnimationFrame(raf);
    }
  }, [loading, items]);

  // 无限滚动：到哨兵附近加载下一页
  const loadMore = useCallback(() => {
    if (loading || loadingMore) return;
    if (items.length >= total) return;
    void loadPage(keyword, page + 1);
  }, [loading, loadingMore, items.length, total, keyword, page, loadPage]);

  useEffect(() => {
    const el = sentinelRef.current;
    if (!el) return;
    const ob = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) loadMore();
      },
      { rootMargin: '500px' },
    );
    ob.observe(el);
    return () => ob.disconnect();
  }, [loadMore]);

  // 进详情前缓存已加载内容 / 页码 / 关键词 / 位置
  const goDetail = useCallback(
    (id: string) => {
      try {
        sessionStorage.setItem(
          STORAGE_KEY,
          JSON.stringify({
            items,
            page,
            total,
            keyword,
            scrollTop: window.scrollY,
          }),
        );
      } catch {
        // ignore storage errors
      }
      navigate(`/news/${id}`);
    },
    [items, page, total, keyword, navigate],
  );

  return (
    <div className="px-3 py-4 md:px-4">
      {/* 搜索 */}
      <div className="relative mb-4">
        <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-500" />
        <input
          value={keyword}
          onChange={(e) => setKeyword(e.target.value)}
          placeholder={t('news.searchPlaceholder')}
          className="w-full rounded-xl border border-white/10 bg-[#141838]/70 py-2.5 pl-9 pr-3 text-sm text-white placeholder-gray-500 outline-none transition focus:border-cyan-400/50"
        />
      </div>

      {loading ? (
        <div className="flex items-center justify-center py-20">
          <Loader2 className="h-8 w-8 animate-spin text-cyan-400" />
        </div>
      ) : items.length === 0 ? (
        <div className="rounded-2xl border border-white/10 bg-[#141838]/40 p-12 text-center">
          <Newspaper className="mx-auto mb-3 h-10 w-10 text-white/25" />
          <p className="text-sm text-gray-500">{t('news.empty')}</p>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-2 gap-3 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5">
            {items.map((article) => (
              <NewsCard key={article.id} article={article} onOpen={goDetail} />
            ))}
          </div>

          {/* 分页哨兵 + 状态 */}
          <div ref={sentinelRef} className="flex items-center justify-center py-6">
            {loadingMore ? (
              <Loader2 className="h-6 w-6 animate-spin text-cyan-400" />
            ) : hasMore ? (
              <button
                onClick={loadMore}
                className="rounded-lg border border-white/15 px-4 py-1.5 text-xs text-gray-300 transition hover:bg-white/5"
              >
                加载更多
              </button>
            ) : (
              <span className="text-xs text-gray-500">— 已经到底啦 —</span>
            )}
          </div>
        </>
      )}
    </div>
  );
});
NewsFeed.displayName = 'NewsFeed';

export default NewsFeed;
