import React, { useState } from 'react';
import { X, FolderInput } from 'lucide-react';
import { Image } from '@client/src/components/ui/image';
import {
  resolvePlayerCardImage,
  resolveSmallPlayerCardImage,
} from '@client/src/utils/player-card-url';
import { LOCAL_ASSETS } from '@client/src/utils/local-assets';
import { useFamilyName } from '@client/src/i18n/PlayerName';
import type { TierItemSnapshot } from '@client/src/api/tier-lists';

interface TierPlayerCardProps {
  item: TierItemSnapshot;
  draggable?: boolean;
  onDragStart?: (e: React.DragEvent) => void;
  onRemove?: () => void;
  onMoveTap?: () => void;
  onCardClick?: () => void;
  /** 为 true 时不渲染额外的球员名浮层（用于原生 APP 内已缩小的入阵卡） */
  hideName?: boolean;
}

const TierPlayerCard: React.FC<TierPlayerCardProps> = ({
  item,
  draggable = false,
  onDragStart,
  onRemove,
  onMoveTap,
  onCardClick,
  hideName = false,
}) => {
  const family = useFamilyName();
  const [imgError, setImgError] = useState(false);
  const [triedSmall, setTriedSmall] = useState(false);
  const large = resolvePlayerCardImage(item.playerImageUrl, item.playerId);
  const small = resolveSmallPlayerCardImage(item.playerId);
  const url = triedSmall ? small : large;
  const hasImage = url && !imgError;

  const initial = family(item).charAt(0).toUpperCase() || '?';

  const [coarse] = useState(
    () =>
      typeof window !== 'undefined' &&
      window.matchMedia?.('(pointer: coarse)').matches,
  );

  return (
    <div
      className="group relative w-full select-none"
      draggable={false}
      onDragStart={(e) => {
        e.preventDefault();
        onDragStart?.(e);
      }}
      onClick={onCardClick}
    >
      <div className="relative aspect-[3/4] overflow-hidden rounded-lg border border-white/15 bg-gradient-to-br from-[#141A30] to-[#1B2340]">
        {hasImage ? (
          <Image
            src={url}
            alt={item.nameZh}
            className="h-full w-full object-contain object-bottom"
            loading="lazy"
            decoding="async"
            onError={() => {
              if (!triedSmall && small) {
                setTriedSmall(true);
              } else {
                setImgError(true);
              }
            }}
          />
        ) : (
          <div className="flex h-full w-full items-center justify-center">
            <span className="text-3xl font-bold text-white/50">{initial}</span>
          </div>
        )}

        {/* 球员名：约在卡面从上往下 6/7 处（此尺寸卡名字体标准：小一档），深色药丸衬底 */}
        {!hideName && (
          <div className="pointer-events-none absolute inset-x-0 top-[76%] flex justify-center px-1">
            <span className="max-w-full truncate rounded bg-black/55 px-1.5 py-px text-center text-[10px] font-bold leading-tight text-white sm:text-[11px]">
              {family(item)}
            </span>
          </div>
        )}

        {/* PlayToStar APP 水印（APP 图标） */}
        <img
          src={LOCAL_ASSETS.icon}
          alt="PlayToStar APP"
          className="pointer-events-none absolute right-1 top-1 h-4 w-4 drop-shadow-[0_1px_2px_rgba(0,0,0,0.9)] sm:h-5 sm:w-5"
        />

        {/* 编辑控件 */}
        {(onRemove || onMoveTap) && (
          <div
            className={`absolute left-1 top-1 flex gap-0.5 ${
              coarse ? 'opacity-100' : 'opacity-0 transition group-hover:opacity-100'
            }`}
          >
            {onMoveTap && (
              <button
                type="button"
                aria-label="移动到其他层级"
                onClick={(e) => {
                  e.stopPropagation();
                  onMoveTap();
                }}
                className="flex h-5 w-5 items-center justify-center rounded bg-black/60 text-cyan-300 hover:bg-cyan-500/80 hover:text-white"
              >
                <FolderInput className="h-3 w-3" />
              </button>
            )}
            {onRemove && (
              <button
                type="button"
                aria-label="移出榜单"
                onClick={(e) => {
                  e.stopPropagation();
                  onRemove();
                }}
                className="flex h-5 w-5 items-center justify-center rounded bg-black/60 text-rose-300 hover:bg-rose-500/80 hover:text-white"
              >
                <X className="h-3 w-3" />
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default TierPlayerCard;
