const WINDOW_SIZE_MS = 5000;
class RateLimiter_RateLimiter {
    constructor(maxRequests){
        this.maxRequests = maxRequests;
        this.windowSizeMs = WINDOW_SIZE_MS;
        this.requestCount = 0;
        this.windowStart = Date.now();
    }
    checkAndResetWindow() {
        const now = Date.now();
        const windowElapsed = now - this.windowStart;
        if (windowElapsed >= this.windowSizeMs) {
            this.requestCount = 0;
            this.windowStart = now;
            return true;
        }
        return false;
    }
    canRequest() {
        this.checkAndResetWindow();
        if (this.requestCount < this.maxRequests) {
            this.requestCount++;
            return true;
        }
        return false;
    }
}
const RateLimiter = RateLimiter_RateLimiter;
export { RateLimiter as default };
