import * as React from 'react';

/**
 * 判断当前是否为「窄屏 / 竖屏手机」：window.innerWidth < 768。
 *
 * 纯宽度判断，不依赖 Capacitor.isNativePlatform()——后者在浏览器/部分安卓
 * WebView 首帧取值不稳，会导致竖屏字体放大被跳过。手机竖屏（网页与 APP）
 * 内宽恒 < 768，判定确定可靠；平板与桌面网页为 false。
 *
 * 口径：横屏 = 网页/APP 横屏版（≥768）；竖屏 = 手机竖屏网页/APP（<768）。
 */
export function useIsNarrowScreen(breakpoint = 768): boolean {
  const compute = React.useCallback(
    (): boolean =>
      typeof window !== 'undefined' && window.innerWidth < breakpoint,
    [breakpoint],
  );

  const [isNarrow, setIsNarrow] = React.useState<boolean>(compute);

  React.useEffect(() => {
    const onChange = () => setIsNarrow(compute());
    setIsNarrow(compute());
    window.addEventListener('resize', onChange);
    window.addEventListener('orientationchange', onChange);
    return () => {
      window.removeEventListener('resize', onChange);
      window.removeEventListener('orientationchange', onChange);
    };
  }, [compute]);

  return isNarrow;
}
