import encyclopedia from '@client/src/assets/data/encyclopedia.json';

type StyleEntry = {
  中文名: string;
  适用位置: string;
};

function buildPositionMap(entries: StyleEntry[]): Record<string, string[]> {
  const map: Record<string, string[]> = {};
  for (const entry of entries) {
    const positions = entry['适用位置'];
    if (!positions || positions === '全部') {
      map[entry['中文名']] = [];
      continue;
    }
    const list = positions
      .split('/')
      .map((p) => p.trim())
      .filter(Boolean);
    map[entry['中文名']] = list;
  }
  return map;
}

export const OFFENSE_STYLE_POSITIONS: Record<string, string[]> =
  buildPositionMap(
    (encyclopedia as { attack_styles: StyleEntry[] }).attack_styles,
  );

export const DEFENSE_STYLE_POSITIONS: Record<string, string[]> =
  buildPositionMap(
    (encyclopedia as { defense_styles: StyleEntry[] }).defense_styles,
  );

export function getOffenseStylePositions(
  style: string | undefined | null,
): string[] {
  if (!style) return [];
  return OFFENSE_STYLE_POSITIONS[style] ?? [];
}

export function getDefenseStylePositions(
  style: string | undefined | null,
): string[] {
  if (!style) return [];
  return DEFENSE_STYLE_POSITIONS[style] ?? [];
}
