import { Filesystem, Directory } from '@capacitor/filesystem';
import { Share } from '@capacitor/share';
import { toast } from 'sonner';
import { isNativeApp } from '@client/src/hooks/use-native-app';

/**
 * 统一的“保存 / 分享图片”能力，拆成两个独立入口：
 *
 * - saveImageLocal（保存到本地）：
 *   · 桌面 / 安卓浏览器 → blobURL + <a download> 直接下载（不弹系统共享面板）；
 *   · iOS Safari → 网页无法直接写相册：有 Web Share(files) 则弹面板选“存储图像”，否则新标签长按保存；
 *   · 微信/QQ 内置（下载与分享均被拦截）→ 引导在浏览器中打开；
 *   · 原生 APP → 写缓存后弹系统面板（含保存到相册）。
 * - shareImage（分享）：走 Web Share / 原生 Share 系统面板；不支持时退化为下载。
 * - saveOrShareImage：兼容旧调用，等同 saveImageLocal。
 *
 * @param dataUrl 形如 data:image/png;base64,xxxx
 * @param fileName 仅文件名（不含目录）
 */

type NavShare = Navigator & {
  canShare?: (d?: ShareData) => boolean;
  share?: (d?: ShareData) => Promise<void>;
};

function dataUrlToBlob(dataUrl: string): Blob {
  const [meta, b64 = ''] = dataUrl.split(',');
  const mime = /data:([^;]+)/.exec(meta)?.[1] || 'image/png';
  const bin = atob(b64);
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return new Blob([arr], { type: mime });
}

function detectEnv() {
  const ua = navigator.userAgent || '';
  const isWeChat = /MicroMessenger/i.test(ua);
  const isQQ = /\bQQ\//i.test(ua); // QQ 内置（独立 QQ浏览器 UA 为 QQBrowser，其支持下载）
  const isAndroid = /Android/i.test(ua);
  const isIOS =
    /iPad|iPhone|iPod/.test(ua) ||
    ((navigator.platform || '') === 'MacIntel' && (navigator.maxTouchPoints || 0) > 1);
  const isDesktop = !isIOS && !isAndroid; // Windows / macOS / Linux 笔记本与台式
  return { isIOS, isAndroid, isDesktop, inAppBrowser: isWeChat || isQQ };
}

function canShareFiles(blob: Blob, fileName: string): boolean {
  const nav = navigator as NavShare;
  const file = new File([blob], fileName, { type: blob.type || 'image/png' });
  try {
    return !!nav.canShare && nav.canShare({ files: [file] });
  } catch {
    return false;
  }
}

function downloadByAnchor(objUrl: string, fileName: string) {
  const a = document.createElement('a');
  a.href = objUrl;
  a.download = fileName;
  a.rel = 'noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();
}

/** 网页：直接保存到本地 */
async function webSaveLocal(dataUrl: string, fileName: string): Promise<void> {
  const { isIOS, inAppBrowser } = detectEnv();

  // 微信/QQ 内置：下载与系统分享均被拦截
  if (inAppBrowser) {
    toast.info(isIOS ? '请点右上角 ···，选择在 Safari 中打开后再保存图片' : '请点右上角 ···，选择在浏览器中打开后再保存图片');
    return;
  }

  const blob = dataUrlToBlob(dataUrl);
  const objUrl = URL.createObjectURL(blob);

  // iOS Safari：网页无法直接写相册，借系统面板“存储图像”；旧版则新标签长按
  if (isIOS) {
    const nav = navigator as NavShare;
    if (canShareFiles(blob, fileName) && nav.share) {
      try {
        await nav.share({ files: [new File([blob], fileName, { type: blob.type || 'image/png' })], title: fileName });
        setTimeout(() => URL.revokeObjectURL(objUrl), 60000);
        return;
      } catch (err) {
        if ((err as DOMException)?.name === 'AbortError') return;
      }
    }
    const opened = window.open(objUrl, '_blank');
    if (opened) {
      toast.info('请长按打开的图片，选择“存储图像”');
      setTimeout(() => URL.revokeObjectURL(objUrl), 60000);
      return;
    }
    downloadByAnchor(objUrl, fileName);
    toast.info('若未自动保存，请长按图片选择“存储图像”');
    setTimeout(() => URL.revokeObjectURL(objUrl), 60000);
    return;
  }

  // 桌面 / 安卓：直接下载，不经过系统共享面板
  downloadByAnchor(objUrl, fileName);
  setTimeout(() => URL.revokeObjectURL(objUrl), 5000);
}

/** 网页：系统分享（转发到其他 App）；不支持时退化为下载 */
async function webShare(dataUrl: string, fileName: string): Promise<void> {
  const { isIOS, inAppBrowser } = detectEnv();

  if (inAppBrowser) {
    toast.info(isIOS ? '请点右上角 ···，选择在 Safari 中打开后再分享' : '请点右上角 ···，选择在浏览器中打开后再分享');
    return;
  }

  const blob = dataUrlToBlob(dataUrl);
  const nav = navigator as NavShare;
  if (canShareFiles(blob, fileName) && nav.share) {
    try {
      await nav.share({ files: [new File([blob], fileName, { type: blob.type || 'image/png' })], title: fileName });
      return;
    } catch (err) {
      if ((err as DOMException)?.name === 'AbortError') return;
    }
  }

  const objUrl = URL.createObjectURL(blob);
  downloadByAnchor(objUrl, fileName);
  toast.info('当前浏览器不支持系统分享，已改为下载图片');
  setTimeout(() => URL.revokeObjectURL(objUrl), 5000);
}

/** 原生 APP：写缓存（base64 不可用 UTF8）→ 系统分享/保存面板 */
async function nativeShare(dataUrl: string, fileName: string): Promise<void> {
  const [, base64Data] = dataUrl.split(',');
  const safeName = fileName.replace(/[\\/:*?"<>|]/g, '_');
  const result = await Filesystem.writeFile({
    path: safeName,
    data: base64Data,
    directory: Directory.Cache,
    recursive: true,
  });
  try {
    await Share.share({ files: [result.uri], title: safeName });
  } catch {
    await Share.share({ url: result.uri, title: safeName });
  }
}

/** 保存到本地 */
export async function saveImageLocal(dataUrl: string, fileName: string): Promise<void> {
  if (!isNativeApp()) {
    await webSaveLocal(dataUrl, fileName);
    return;
  }
  await nativeShare(dataUrl, fileName);
}

/** 分享到其他 App */
export async function shareImage(dataUrl: string, fileName: string): Promise<void> {
  if (!isNativeApp()) {
    await webShare(dataUrl, fileName);
    return;
  }
  await nativeShare(dataUrl, fileName);
}

/** 兼容旧调用：等同保存到本地 */
export async function saveOrShareImage(dataUrl: string, fileName: string): Promise<void> {
  await saveImageLocal(dataUrl, fileName);
}
