export interface RuntimeConfig {
  API_BASE_URL: string;
  WECHAT_MOBILE_APPID: string;
  WECHAT_WEB_APPID: string;
  WECHAT_MINI_APPID: string;
  APPLE_WEB_CLIENT_ID: string;
}

declare global {
  interface Window {
    RUNTIME_CONFIG?: Partial<RuntimeConfig>;
  }
}

export const runtimeConfig: RuntimeConfig = {
  API_BASE_URL: window.RUNTIME_CONFIG?.API_BASE_URL ?? '',
  WECHAT_MOBILE_APPID: window.RUNTIME_CONFIG?.WECHAT_MOBILE_APPID ?? '',
  WECHAT_WEB_APPID: window.RUNTIME_CONFIG?.WECHAT_WEB_APPID ?? '',
  WECHAT_MINI_APPID: window.RUNTIME_CONFIG?.WECHAT_MINI_APPID ?? '',
  APPLE_WEB_CLIENT_ID: window.RUNTIME_CONFIG?.APPLE_WEB_CLIENT_ID ?? '',
};
