import React from 'react';
import { Target, ArrowRight, Triangle, Zap, Footprints, ArrowUp, Shield, Hand } from 'lucide-react';
import { BUILD_CATEGORIES } from '@client/src/utils/build-categories';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';

interface BuildSummaryProps {
  allocations: Record<string, number>;
  compact?: boolean;
  landscape?: boolean;
  /** 加点方案标题右侧动作位（如“我的方案”按钮的 Portal 目标） */
  actionRef?: React.RefObject<HTMLDivElement | null>;
}

const ICON_MAP: Record<string, React.ComponentType<{ className?: string }>> = {
  Target,
  ArrowRight,
  Triangle,
  Zap,
  Footprints,
  ArrowUp,
  Shield,
  Hand,
};

const BuildSummary: React.FC<BuildSummaryProps> = ({ allocations, compact = false, landscape = false, actionRef }) => {
  const { t } = useI18n();
  const items = BUILD_CATEGORIES.map((cat) => ({
    key: cat.key,
    name: cat.name,
    icon: cat.icon,
    points: allocations[cat.key] ?? 0,
  }));

  if (landscape) {
    return (
      <div className="w-full">
        <div className="flex items-center gap-1.5 mb-1">
          <span className="w-1 h-3 bg-cyan-400/60 rounded-full" />
          <span className="text-[10px] font-bold text-gray-400">{t('detail.addPointPlan')}</span>
          <div ref={actionRef} className="ml-auto flex items-center" />
        </div>
        <div className="grid grid-cols-10 gap-0.5">
          {items.map((item) => {
            const Icon = ICON_MAP[item.icon] || Triangle;
            const hasPoints = item.points > 0;
            return (
              <div
                key={item.key}
                className={`flex items-center justify-center gap-0.5 px-0.5 py-1 rounded border ${
                  hasPoints
                    ? 'bg-cyan-400/10 border-cyan-400/30'
                    : 'bg-white/[0.03] border-white/5'
                }`}
                title={`${trTerm(item.name)}: ${item.points}`}
              >
                <Icon className={`w-3 h-3 flex-shrink-0 ${hasPoints ? 'text-cyan-300' : 'text-gray-600'}`} />
                <span className={`text-[10px] font-bold leading-none ${hasPoints ? 'text-cyan-200' : 'text-gray-600'}`}>
                  {item.points}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="w-full">
      <div className="flex items-center gap-2 mb-2.5">
        <span className="w-1.5 h-4 bg-cyan-400/60 rounded-full" />
         <span className="text-lg font-bold text-gray-400">{t('detail.addPointPlan')}</span>
         <div ref={actionRef} className="ml-auto flex items-center" />
      </div>
      <div
        className={`grid gap-2 ${
          compact ? 'grid-cols-5' : 'grid-cols-10'
        }`}
      >
        {items.map((item) => {
          const Icon = ICON_MAP[item.icon] || Triangle;
          const hasPoints = item.points > 0;
          return (
            <div
              key={item.key}
               className={`flex items-center justify-center gap-1.5 px-3 py-2.5 rounded-lg border transition-all ${
                  hasPoints
                  ? 'bg-cyan-400/10 border-cyan-400/30'
                  : 'bg-white/[0.03] border-white/5'
              }`}
              title={`${trTerm(item.name)}: ${item.points}`}
            >
               <Icon
                  className={`w-5 h-5 flex-shrink-0 ${
                    hasPoints ? 'text-cyan-300' : 'text-gray-600'
                  }`}
                />
               <span
                  className={`text-xl font-bold leading-none ${
                   hasPoints ? 'text-cyan-200' : 'text-gray-600'
                 }`}
                >
                {item.points}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default BuildSummary;
