const OFFENSE_STYLES = [
  '偷猎者', '禁区之狐', '站桩式中锋', '虚假跑位', '组织型前锋', '影子前锋',
  '传统十号位', '创意指挥官', '传中专家', '自由侧翼', '高产翼锋',
  '指挥官', '靠山', '全能中场', '进攻型后卫', '防守型后卫',
  '迭瓦式终结者', '组织大师', '额外前锋', '高位防线门将',
];

function getOffenseStyleDisplay(style: string | undefined | null): string {
  if (!style || !style.trim()) return '基础战术';
  return OFFENSE_STYLES.includes(style) ? style : '基础战术';
}

// ===================== 球员详情缓存：缓存优先 + 后台静默刷新 =====================
// 目标：再次进入曾打开过的卡片时瞬时渲染、无整屏“加载中”闪现；仅首次（无缓存）才显示 spinner。
// 内存 Map 供同会话秒切；sessionStorage 键 player_cache_<id> 让刷新页面后仍可秒开，读写均包 try/catch。
const playerCache = new Map<string, Player>();
const CACHE_PREFIX = 'player_cache_';

function readPlayerCache(id: string): Player | null {
  const mem = playerCache.get(id);
  if (mem) return mem;
  try {
    const raw = window.sessionStorage.getItem(CACHE_PREFIX + id);
    if (raw) {
      const p = JSON.parse(raw) as Player;
      playerCache.set(id, p);
      return p;
    }
  } catch {
    /* 缓存损坏 / 不可用则忽略，走正常加载 */
  }
  return null;
}

function writePlayerCache(id: string, player: Player): void {
  try {
    playerCache.set(id, player);
    try {
      window.sessionStorage.setItem(CACHE_PREFIX + id, JSON.stringify(player));
    } catch {
      /* sessionStorage 满 / 隐私模式下不可用，不影响主流程 */
    }
  } catch {
    /* ignore */
  }
}

const PlayerDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  // player 初始值尽量从当前 id 的缓存惰性初始化；loading 仅在“无缓存”时才为 true
  const [player, setPlayer] = useState<Player | null>(() => (id ? readPlayerCache(id) : null));
  const commentSectionRef = useRef<CommentSectionRef>(null);
  const [loading, setLoading] = useState<boolean>(() => (id ? !readPlayerCache(id) : true));
  const [error, setError] = useState<string | null>(null);
  const [adjustedOverall, setAdjustedOverall] = useState<number | null>(null);
  const [derivedStats, setDerivedStats] = useState<DerivedPlayerStats | null>(null);
  const [statsEditMode, setStatsEditMode] = useState(false);
  const [statsEditor, setStatsEditor] = useState<StatsEditorApi | null>(null);
  const registerStatsEditor = useCallback(
    (api: StatsEditorApi | null) => setStatsEditor(api),
    [],
  );
  const [customLevel, setCustomLevel] = useState<number | null>(null);
  const [innateBoosterLevel, setInnateBoosterLevel] = useState<number>(0);
  const [sharingImage, setSharingImage] = useState(false);
  const [shareImageUrl, setShareImageUrl] = useState<string | null>(null);
  const isLandscape = useIsLandscape();
  const isNarrow = useIsNarrowScreen();
  // 滑屏加点引导：仅窄屏（滑屏可用）且未看过时弹一次，默认勾选不再展示
  const [slideTipOpen, setSlideTipOpen] = useState(false);
  useEffect(() => {
    if (!isNarrow) return;
    try {
      if (localStorage.getItem(SLIDE_TIP_STORAGE_KEY) !== 'dismissed') setSlideTipOpen(true);
    } catch {
      setSlideTipOpen(true);
    }
  }, [isNarrow]);
  const { t, lang } = useI18n();
  // 网页（含 /efootball 与手机浏览器）为 true；Capacitor 原生壳（APP/平板）为 false
  const isWeb = !isNativeApp();

  // 横屏网页重排插槽：Header 挂载容器，BuildPanel 通过 Portal 注入
  const slotControlsRef = useRef<HTMLDivElement>(null);
  const slotSynthesisRef = useRef<HTMLDivElement>(null);
  // 竖屏：总能力值 / 位置选择 插槽
  const slotTotalSumRef = useRef<HTMLDivElement>(null);
  const slotPositionRef = useRef<HTMLDivElement>(null);
  // 加点方案标题右侧动作位（我的方案按钮）
  const slotAddPointActionRef = useRef<HTMLDivElement>(null);
  const [slotsReady, setSlotsReady] = useState(false);
  useLayoutEffect(() => {
    setSlotsReady(true);
  }, []);

  useEffect(() => {
    if (!id) return;

    let cancelled = false;

    // 缓存优先：命中缓存则立即渲染、不进整屏 loading；未命中才 setLoading(true) 显示 spinner
    const cached = readPlayerCache(id);
    if (cached) {
      setPlayer(cached);
      setError(null);
      setLoading(false);
    } else {
      setPlayer(null);
      setError(null);
      setLoading(true);
    }

    // 无论是否命中缓存，都后台静默拉取最新数据；返回后刷新视图并写入缓存
    players.getPlayer(id)
      .then((data: Player) => {
        if (cancelled) return;
        writePlayerCache(id, data);
        setPlayer(data);
        setError(null);
        const viewKey = `viewed_${id}`;
        if (!sessionStorage.getItem(viewKey)) {
          sessionStorage.setItem(viewKey, '1');
          recordView(id, getVisitorId()).catch((viewErr: unknown) => {
            logger.error('上报浏览量失败', viewErr);
          });
        }
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        logger.error('加载球员详情失败', err);
        // 仅当“请求失败且无缓存”时才展示错误页；有缓存则保留已渲染的缓存内容
        if (!playerCache.has(id)) {
          setError('加载失败，请稍后重试');
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [id]);

  // 浏览器标签标题：球员详情页显示“球员名 · PlayToStar APP”，离开后恢复默认
  useEffect(() => {
    if (!player) return;
    const name = lang === 'en'
      ? (player.nameEn || player.nameZh || 'PlayToStar APP')
      : (player.nameZh || player.nameEn || 'PlayToStar APP');
    const full = `${name} · PlayToStar APP`;
    document.title = full;
    // 平台外壳在挂载后也会写一次标题，延迟到其后再写，确保球员名最终生效
    const timer = window.setTimeout(() => {
      document.title = full;
    }, 0);
    return () => {
      window.clearTimeout(timer);
      document.title = 'PlayToStar APP';
    };
  }, [player, lang]);

  if (loading) {
    return (
       <div className="min-h-screen bg-background flex items-center justify-center">
         <div className="text-center">
           <div className="w-12 h-12 border-4 border-cyan-400/30 border-t-cyan-400 rounded-full animate-spin mx-auto mb-4 box-glow-cyan" />
          <p className="text-gray-400 text-sm">加载中...</p>
        </div>
      </div>
    );
  }

  if (error || !player) {
    return (
       <div className="min-h-screen bg-background flex items-center justify-center">
         <div className="text-center">
           <p className="text-gray-400 mb-4">{error || '球员不存在'}</p>
           <button
             onClick={() => window.history.back()}
             className="px-4 py-2 rounded-lg bg-primary text-primary-foreground text-sm font-medium hover:opacity-90 transition-opacity"
           >
            返回
          </button>
        </div>
      </div>
    );
  }

  // 生成当前培养方案分享横图
  const handleShareImage = async () => {
    if (!derivedStats) {
      toast.error('培养数据尚未就绪，请稍后再试');
      return;
    }
    setSharingImage(true);
    try {
      const ib = player.innateBooster;
      const firstMaxLv = ib?.level ?? 0;
      const firstLv = innateBoosterLevel || derivedStats.innateBoosterLevel || firstMaxLv;
      let firstBooster: { label: string; colorHex: string } | null = null;
      if (ib) {
        let colorHex = '#3de3e1';
        let localIb: { nameEn?: string; color?: string } | null = null;
        try {
          localIb = apiBoosterToLocal(ib, player.playerType);
          colorHex = BOOSTER_COLOR_MAP[localIb.color]?.hex ?? colorHex;
        } catch { /* 用默认色 */ }
        const rawName = String(ib.nameCn ?? '').replace(/\+\d+\s*$/, '').trim();
        const enName = (localIb?.nameEn ?? '').trim();
        const baseName = lang === 'en'
          ? (enName || trTerm(rawName) || rawName)
          : (rawName || enName);
        firstBooster = {
          label: `${baseName} +${firstLv}`,
          colorHex,
        };
      }
      const secondBooster = derivedStats.secondBoosterNameLabel
        ? { label: derivedStats.secondBoosterNameLabel, colorHex: derivedStats.secondBoosterColorHex ?? '#3de3e1' }
        : null;
      const shine = derivedStats.shineLevel > 0
        ? { label: `${lang === 'en' ? 'Shine' : '闪耀'} +${derivedStats.shineLevel}`, colorHex: '#fbbf24' }
        : null;
      const coach = derivedStats.coachLabel ? { label: derivedStats.coachLabel } : null;
      const canvas = await renderPlayerShareCanvas({
        player,
        overallRating: derivedStats.adjustedOverall,
        finalAttrValues: derivedStats.finalAttrValues,
        allocations: derivedStats.allocations ?? {},
        shine,
        firstBooster,
        secondBooster,
        coach,
        extraSkills: getDraftExtraSkills(player.id) ?? [],
      });
      const url = canvas.toDataURL('image/png');
      setShareImageUrl(url);
    } catch (shareErr) {
      logger.error('生成分享图失败', shareErr);
      toast.error('生成分享图失败，请稍后重试');
    } finally {
      setSharingImage(false);
    }
  };

  const shareFileName = `实况起点_${player.nameZh || player.nameEn || player.id}.png`;
  const downloadShareImage = async () => {
    if (!shareImageUrl) return;
    try {
      await saveImageLocal(shareImageUrl, shareFileName);
    } catch (saveErr) {
      logger.error('保存分享图失败', saveErr);
      toast.error('保存失败，请长按图片尝试保存或分享');
    }
  };
  const shareShareImage = async () => {
    if (!shareImageUrl) return;
    try {
      await shareImage(shareImageUrl, shareFileName);
    } catch (shareErr) {
      logger.error('分享失败', shareErr);
      toast.error('分享失败，请改点保存本地');
    }
  };

  const shareDialog = (
    <Dialog open={!!shareImageUrl} onOpenChange={(open) => { if (!open) setShareImageUrl(null); }}>
      <DialogContent showCloseButton={false} className="bg-[#0f142e]/95 border-white/10 max-w-3xl p-0 overflow-hidden">
        <div className="flex items-center justify-between px-4 py-2.5 border-b border-white/10">
          <span className="text-sm font-bold text-white">{trTerm('培养方案分享图')}</span>
          <button type="button" onClick={() => setShareImageUrl(null)} className="text-gray-400 hover:text-white">
            <X className="h-5 w-5" />
          </button>
        </div>
        {shareImageUrl && (
          <img src={shareImageUrl} alt={trTerm('培养方案分享图')} className="w-full block" />
        )}
        <div className="flex items-center justify-between gap-3 px-4 py-3 border-t border-white/10">
          <span className="text-xs text-gray-400">
            {isWeb ? trTerm('可保存到本地，或分享到社交平台') : trTerm('长按图片可保存到相册或分享')}
          </span>
          <div className="flex items-center gap-2">
            {isWeb && (
              <button
                type="button"
                onClick={shareShareImage}
                className="flex items-center gap-1.5 rounded-lg border border-cyan-400/50 px-3.5 py-2 text-sm font-bold text-cyan-200 hover:bg-cyan-400/10"
              >
                <Share2 className="h-4 w-4" />
                {trTerm('分享')}
              </button>
            )}
            <button
              type="button"
              onClick={downloadShareImage}
              className="flex items-center gap-1.5 rounded-lg bg-gradient-to-r from-cyan-500 to-blue-500 px-4 py-2 text-sm font-bold text-white"
            >
              <Download className="h-4 w-4" />
              {isWeb ? trTerm('保存本地') : trTerm('保存图片')}
            </button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );

  // ===================== 横屏：居中三栏 + 底部评论区（保留顶部导航、页面可滚动） =====================
  if (isLandscape) {
    return (
      <DetailSlotsContext.Provider
        value={{ slotControls: slotControlsRef, slotSynthesis: slotSynthesisRef, slotAddPointAction: slotAddPointActionRef, ready: slotsReady }}
      >
        <div className={`min-h-screen w-full text-white relative ${isWeb ? 'pl-[84px] pr-3 lg:pr-6' : ''}`}>
          {isWeb && (
            /* 网页横屏：玩家评分悬挂牌外侧轨道（页面左缘红框位置） */
            <div id="player-rating-rail" className="absolute left-2 top-[112px] z-30 w-[76px]" />
          )}
          <div className="mx-auto w-full max-w-[1440px] rounded-xl bg-background px-4 lg:px-6 py-4 border border-white/10">
            <div className="grid grid-cols-[minmax(0,1fr)_minmax(0,1.3fr)_minmax(0,1fr)] gap-4 items-start">
              {/* 左栏 */}
              <div className="flex flex-col gap-3">
                <PlayerDetailHeader
                  player={player}
                  adjustedOverall={derivedStats?.adjustedOverall ?? adjustedOverall ?? undefined}
                  customLevel={customLevel}
                  onLevelChange={setCustomLevel}
                  allPositionOveralls={derivedStats?.allPositionOveralls}
                  allocations={derivedStats?.allocations ?? {}}
                  innateBoosterLevel={innateBoosterLevel}
                  onInnateBoosterLevelChange={setInnateBoosterLevel}
                  isWeb={isWeb}
                  landscape
                  onShareImage={handleShareImage}
                  sharingImage={sharingImage}
                  selectedPosition={derivedStats?.selectedPosition}
                />
                {shareDialog}

                {isWeb ? (
                  /* 网页：BuildPanel 仅渲染 Portal 控制区/综合面板与弹窗；球员模型互换后置于左栏 */
                  <>
                    <BuildPanel
                      player={player}
                      customLevel={customLevel}
                      onOverallChange={setAdjustedOverall}
                      onStatsChange={setDerivedStats}
                      registerEditor={registerStatsEditor}
                      innateBoosterLevel={innateBoosterLevel}
                      onInnateBoosterLevelChange={setInnateBoosterLevel}
                      isWeb
                      landscape
                    />
                    {derivedStats?.allPositionOveralls && (
                      <PositionHeatmap
                        allPositionOveralls={derivedStats.allPositionOveralls}
                        registeredPosition={player.position}
                        officialOverall={player.overallRating}
                        positionProficiency={player.positionProficiency}
                        offensiveStyle={getOffenseStyleDisplay(player.style)}
                        defensiveStyle={player.defensivePlayStyle || '基础战术'}
                        showStyleButtons
                        compact
                        collapsible={false}
                        helperText={t('detail.clickStyleHint')}
                        aiStyle={player.aiPlayStyle}
                        selectedPosition={derivedStats.selectedPosition}
                        onSelectPosition={(k) => statsEditor?.setSelectedPosition(k)}
                      />
                    )}
                  </>
                ) : (
                  <>
                    <BuildPanel
                      player={player}
                      customLevel={customLevel}
                      onOverallChange={setAdjustedOverall}
                      onStatsChange={setDerivedStats}
                      innateBoosterLevel={innateBoosterLevel}
                      onInnateBoosterLevelChange={setInnateBoosterLevel}
                      isWeb={false}
                      landscape
                    />
                    {/* 球员模型（原生平板保持左栏） */}
                    <BodyModelPanel
                      bodyModel={player.bodyModel}
                      playerModel={player.playerModel}
                      landscape
                    />
                  </>
                )}
              </div>

              {/* 中：三大属性面板 + 球员技能（网页不渲染状态属性框） */}
              <div className="flex flex-col gap-3">
                <StatsPanel
                  attackStats={player.attackStats}
                  defenseStats={player.defenseStats}
                  powerStats={player.powerStats}
                  finalAttrValues={derivedStats?.finalAttrValues}
                  boosterBonusValues={derivedStats?.boosterBonusValues}
                  boosterColorMap={derivedStats?.boosterColorMap ? Object.fromEntries(
                    Object.entries(derivedStats.boosterColorMap).map(([k, v]) => [k, BOOSTER_COLOR_MAP[v]]),
                  ) : undefined}
                  shineBonusValues={derivedStats?.shineBonusValues}
                  landscape
                  editMode={statsEditMode}
                  availablePoints={derivedStats?.availablePoints}
                  isGK={derivedStats?.isGK}
                  allocations={derivedStats?.allocations}
                  onToggleEdit={() => {
                    if (!statsEditMode) {
                      // 进入加点：若当前无已分配点数，先自动加点给基本盘；已有方案(培养方案autoFill/微调)则仅展开、不覆盖
                      const total = Object.values(derivedStats?.allocations ?? {}).reduce(
                        (s: number, v) => s + (Number(v) || 0), 0);
                      if (total === 0) statsEditor?.autoBuild();
                      setStatsEditMode(true);
                    } else {
                      setStatsEditMode(false);
                    }
                  }}
                  onResetAll={() => statsEditor?.resetAll()}
                  onAdjust={(catKey, delta) =>
                    delta > 0 ? statsEditor?.addCategory(catKey) : statsEditor?.removeCategory(catKey)
                  }
                />
                <SkillsList
                  skills={player.skills}
                  registeredPosition={player.position}
                  positionProficiency={player.positionProficiency}
                  isWeb={isWeb}
                  playerId={player.id}
                  landscape
                />
                <img
                  src={LOCAL_ASSETS.banner}
                  alt="PlayToStar APP 实况起点"
                  className="w-full rounded-lg border border-white/10 object-cover"
                />
                {!isWeb && (
                  <HiddenAttributesComp
                    hiddenAttributes={player.hiddenAttributes}
                    aiPlayStyle={player.aiPlayStyle}
                    landscape
                  />
                )}
              </div>

              {/* 右栏 */}
              <div className="flex flex-col gap-3">
                {isWeb ? (
                  /* 网页右栏：八维能力置顶，球员模型在其下 */
                  <>
                    {derivedStats && (
                      <RadarChartComp
                        radarStats={derivedStats.radarStats}
                        finalAttrValues={derivedStats.finalAttrValues}
                        isGK={derivedStats.isGK}
                        compact
                      />
                    )}
                    <BodyModelPanel
                      bodyModel={player.bodyModel}
                      playerModel={player.playerModel}
                      landscape
                    />
                  </>
                ) : (
                  /* 原生平板右栏（保持原始）：风格位置 + 八维能力 */
                  <>
                    {derivedStats?.allPositionOveralls && (
                      <PositionHeatmap
                        allPositionOveralls={derivedStats.allPositionOveralls}
                        registeredPosition={player.position}
                        officialOverall={player.overallRating}
                        positionProficiency={player.positionProficiency}
                        offensiveStyle={getOffenseStyleDisplay(player.style)}
                        defensiveStyle={player.defensivePlayStyle || '基础战术'}
                        showStyleButtons
                        compact
                        collapsible={false}
                        aiStyle={player.aiPlayStyle}
                        {...(!isWeb ? { styleFontClass: 'text-[21px]', styleIconClass: 'h-5 w-5' } : {})}
                        selectedPosition={derivedStats.selectedPosition}
                        onSelectPosition={(k) => statsEditor?.setSelectedPosition(k)}
                      />
                    )}
                    {derivedStats && (
                      <RadarChartComp
                        radarStats={derivedStats.radarStats}
                        finalAttrValues={derivedStats.finalAttrValues}
                        isGK={derivedStats.isGK}
                        compact
                      />
                    )}
                  </>
                )}
              </div>
            </div>

            {/* 评论区：整页下方，全宽 */}
            <div className="mt-5">
              <CommentSection
                ref={commentSectionRef}
                targetType="player"
                targetId={player.id}
                sectionId="player-comment-section"
                initialCommentCount={player.commentCount ?? 0}
                collapsible={false}
              />
            </div>
          </div>
        </div>
      </DetailSlotsContext.Provider>
    );
  }

  // ===================== 竖屏：原有布局 =====================
  return (
    <DetailSlotsContext.Provider
      value={{
        slotControls: slotControlsRef,
        slotSynthesis: slotSynthesisRef,
        slotPortraitTotalSum: slotTotalSumRef,
        slotPortraitPosition: slotPositionRef,
        slotAddPointAction: slotAddPointActionRef,
        ready: slotsReady,
      }}
    >
     <div className="min-h-screen bg-background text-white">
       {/* 顶部渐变背景装饰 */}
       <div className="fixed top-0 left-0 right-0 h-64 bg-gradient-to-b from-cyan-500/10 to-transparent pointer-events-none -z-0" />

       <div className="detail-scope relative z-10 max-w-4xl mx-auto px-2 py-2.5 space-y-2.5">
         {/* 1. 头部信息（含风格/位置展示） */}
         <div className="scope-style">
         <PlayerDetailHeader
            player={player}
            adjustedOverall={derivedStats?.adjustedOverall ?? adjustedOverall ?? undefined}
            customLevel={customLevel}
            onLevelChange={setCustomLevel}
            allPositionOveralls={derivedStats?.allPositionOveralls}
            allocations={derivedStats?.allocations ?? {}}
            innateBoosterLevel={innateBoosterLevel}
            onInnateBoosterLevelChange={setInnateBoosterLevel}
            onShareImage={handleShareImage}
            sharingImage={sharingImage}
            selectedPosition={derivedStats?.selectedPosition}
            onSelectPosition={(k) => statsEditor?.setSelectedPosition(k)}
          />
          {shareDialog}
         </div>

          {/* 2. 加点系统（总览：闪耀/教练/第二增能选择器） */}
          <div className="scope-selectors">
          <BuildPanel
            player={player}
            customLevel={customLevel}
            onOverallChange={setAdjustedOverall}
            onStatsChange={setDerivedStats}
            registerEditor={registerStatsEditor}
            innateBoosterLevel={innateBoosterLevel}
            onInnateBoosterLevelChange={setInnateBoosterLevel}
          />
          </div>

          {/* 3. 三大属性面板 */}
          <StatsPanel
            attackStats={player.attackStats}
            defenseStats={player.defenseStats}
            powerStats={player.powerStats}
            finalAttrValues={derivedStats?.finalAttrValues}
            boosterBonusValues={derivedStats?.boosterBonusValues}
           boosterColorMap={derivedStats?.boosterColorMap ? Object.fromEntries(
             Object.entries(derivedStats.boosterColorMap).map(([k, v]) => [k, BOOSTER_COLOR_MAP[v]]),
           ) : undefined}
            shineBonusValues={derivedStats?.shineBonusValues}
            isGK={derivedStats?.isGK}
            allocations={derivedStats?.allocations}
            availablePoints={derivedStats?.availablePoints}
            onSetCategoryPoints={(catKey, target) => statsEditor?.setCategoryPoints(catKey, target)}
            onSaveBuild={() => statsEditor?.saveBuild()}
          />

         {/* 4. 球员技能 */}
         <SkillsList skills={player.skills} registeredPosition={player.position} positionProficiency={player.positionProficiency} playerId={player.id} />

         {/* 5. 状态属性 + 八维能力图（两列同行；原位置适配已移除，评分区已有风格显示） */}
         {derivedStats && (
           <div className="grid grid-cols-2 gap-2.5">
              <div className="scope-status">
              <HiddenAttributesComp hiddenAttributes={player.hiddenAttributes} aiPlayStyle={player.aiPlayStyle} />
              </div>
             <RadarChartComp
               radarStats={derivedStats.radarStats}
               finalAttrValues={derivedStats.finalAttrValues}
               isGK={derivedStats.isGK}
             />
           </div>
         )}

         {/* 7. 球员模型（模型数值 / 尺寸模型） */}
         <div className="scope-model">
         <BodyModelPanel
           bodyModel={player.bodyModel}
           playerModel={player.playerModel}
         />
         </div>

          {/* 8. 评论区（详情页内统一放大，不含讨论区页） */}
            <div className="scope-comments">
            <CommentSection
              ref={commentSectionRef}
              targetType="player"
              targetId={player.id}
              collapsible
              defaultCollapsed
              sectionId="player-scope-comments"
              initialCommentCount={player.commentCount ?? 0}
            />
            </div>
       </div>

       {/* 底部留白 */}
       <div className="h-6" />
       <SlidePointsTipDialog open={slideTipOpen} onClose={() => setSlideTipOpen(false)} />
    </div>
    </DetailSlotsContext.Provider>
  );
};

export default PlayerDetailPage;
