import React, { useState, useRef, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Loader2, Trophy, Layers, Users2, ChevronLeft, ChevronRight } from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { useI18n } from '@client/src/i18n/I18nProvider';
import PlayerCard from '@client/src/components/PlayerCard';
import { useIsLandscape } from '@client/src/hooks/useIsLandscape';
import { pushBackHandler } from '@client/src/utils/back-intercept';
import { getPositionRankings } from '@client/src/api/players';
import MyTierList from '@client/src/pages/tier-list/MyTierList';
import MyLineup from '@client/src/pages/lineup/MyLineup';
import type { PositionRankingsResponse, RankedPlayerItem } from '@shared/api.interface';

const POSITION_THEME: Record<string, { gradient: string; glow: string; label: string }> = {
  CF: { gradient: 'from-red-500 to-orange-500', glow: 'shadow-[0_0_20px_rgba(249_115_22_0.4)]', label: '中锋' },
  SS: { gradient: 'from-orange-500 to-yellow-500', glow: 'shadow-[0_0_20px_rgba(234_179_8_0.4)]', label: '影锋' },
  LWF: { gradient: 'from-rose-500 to-pink-500', glow: 'shadow-[0_0_20px_rgba(236_72_153_0.4)]', label: '左边锋' },
  RWF: { gradient: 'from-rose-500 to-pink-500', glow: 'shadow-[0_0_20px_rgba(236_72_153_0.4)]', label: '右边锋' },
  AMF: { gradient: 'from-cyan-500 to-pink-500', glow: 'shadow-[0_0_20px_rgba(34_211_238_0.4)]', label: '前腰' },
  LMF: { gradient: 'from-cyan-500 to-violet-500', glow: 'shadow-[0_0_20px_rgba(139_92_246_0.4)]', label: '左前卫' },
  RMF: { gradient: 'from-cyan-500 to-violet-500', glow: 'shadow-[0_0_20px_rgba(139_92_246_0.4)]', label: '右前卫' },
  CMF: { gradient: 'from-blue-500 to-indigo-500', glow: 'shadow-[0_0_20px_rgba(99_102_241_0.4)]', label: '中前卫' },
  DMF: { gradient: 'from-cyan-500 to-blue-500', glow: 'shadow-[0_0_20px_rgba(59_130_246_0.4)]', label: '后腰' },
  LB: { gradient: 'from-teal-500 to-emerald-500', glow: 'shadow-[0_0_20px_rgba(20_184_166_0.4)]', label: '左后卫' },
  RB: { gradient: 'from-teal-500 to-emerald-500', glow: 'shadow-[0_0_20px_rgba(20_184_166_0.4)]', label: '右后卫' },
  CB: { gradient: 'from-green-500 to-emerald-500', glow: 'shadow-[0_0_20px_rgba(34_197_94_0.4)]', label: '中后卫' },
  GK: { gradient: 'from-yellow-500 to-amber-500', glow: 'shadow-[0_0_20px_rgba(245_158_11_0.4)]', label: '门将' },
};

const RankingsPage: React.FC = () => {
  const navigate = useNavigate();
  const landscape = useIsLandscape();
  const { t, lang } = useI18n();
  // 默认停在图标入口（home），不预加载任何榜单，减少请求消耗
  const [tab, setTab] = useState<'home' | 'position' | 'tier' | 'lineup'>('home');
  const [data, setData] = useState<PositionRankingsResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const positionLoaded = useRef(false);

  const loadPosition = () => {
    if (positionLoaded.current) return;
    positionLoaded.current = true;
    let cancelled = false;
    setLoading(true);
    setError(null);
    getPositionRankings()
      .then((res) => {
        if (!cancelled) setData(res);
      })
      .catch((err) => {
        logger.error('加载榜单失败', err);
        if (!cancelled) setError(t('加载失败，请稍后重试'));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  };

  // 点击图标才切换并按需加载
  const goTab = (which: 'home' | 'position' | 'tier' | 'lineup') => {
    setTab(which);
    if (which === 'position') loadPosition();
  };

  // 竖屏（APP/手机）：进入子内容后，硬件返回/边缘内滑先回到本菜单，而不是退出
  useEffect(() => {
    if (landscape || tab === 'home') return undefined;
    return pushBackHandler(() => {
      setTab('home');
      return true;
    });
  }, [landscape, tab]);

  const goHome = () => setTab('home');

  const location = useLocation();
  // 导航优先：点主导航“榜单”（含已停留在本页时点该标签）产生新 location.key，回到榜单默认主页
  const navKeyRef = useRef<string | null>(null);
  useEffect(() => {
    if (navKeyRef.current === null) { navKeyRef.current = location.key; return; }
    if (navKeyRef.current === location.key) return;
    navKeyRef.current = location.key;
    setTab('home');
  }, [location.key]);

  const handleCardClick = (player: RankedPlayerItem) => {
    navigate(`/player/${player.id}`);
  };

  // 子栏目入口：图标在上，主标题 + 二级说明在下（非标签条）
  const tabBar = (
    <div className="mb-4 flex gap-3">
      <button
        type="button"
        onClick={() => goTab('tier')}
        className={`flex flex-1 flex-col items-center gap-2 rounded-2xl px-4 py-4 transition sm:flex-none sm:gap-1.5 sm:rounded-xl sm:px-6 sm:py-3 ${
          tab === 'tier'
            ? 'bg-[#2a1740] text-white ring-1 ring-pink-400/70 shadow-[0_2px_16px_rgba(236,72,153,0.3)]'
            : 'bg-[#151b3d] text-white/80 hover:bg-[#1d1a45]'
        }`}
      >
        <span className="flex h-20 w-20 items-center justify-center rounded-xl bg-gradient-to-br from-pink-400 to-rose-600 text-white shadow-[0_3px_10px_rgba(236,72,153,0.42)] sm:h-10 sm:w-10 sm:rounded-lg">
          <Layers className="h-10 w-10 sm:h-5 sm:w-5" />
        </span>
        <span className="text-2xl font-bold sm:text-sm">{t('我的强度榜')}</span>
        <span className="text-sm text-white/45 sm:text-[10px]">{t('我也能建立自己的权威榜单，一键分享我的观点。')}</span>
      </button>
      <button
        type="button"
        onClick={() => goTab('lineup')}
        className={`flex flex-1 flex-col items-center gap-2 rounded-2xl px-4 py-4 transition sm:flex-none sm:gap-1.5 sm:rounded-xl sm:px-6 sm:py-3 ${
          tab === 'lineup'
            ? 'bg-[#10243f] text-white ring-1 ring-sky-400/70 shadow-[0_2px_16px_rgba(56,189,248,0.3)]'
            : 'bg-[#151b3d] text-white/80 hover:bg-[#16223f]'
        }`}
      >
        <span className="flex h-20 w-20 items-center justify-center rounded-xl bg-gradient-to-br from-sky-400 to-blue-600 text-white shadow-[0_3px_10px_rgba(56,189,248,0.42)] sm:h-10 sm:w-10 sm:rounded-lg">
          <Users2 className="h-10 w-10 sm:h-5 sm:w-5" />
        </span>
        <span className="text-2xl font-bold sm:text-sm">{t('我的阵容')}</span>
        <span className="text-sm text-white/45 sm:text-[10px]">{t('不上游戏也一键分享我的排兵布阵！')}</span>
      </button>
      <button
        type="button"
        onClick={() => goTab('position')}
        className={`flex flex-1 flex-col items-center gap-2 rounded-2xl px-4 py-4 transition sm:flex-none sm:gap-1.5 sm:rounded-xl sm:px-6 sm:py-3 ${
          tab === 'position'
            ? 'bg-[#16224d] text-white ring-1 ring-cyan-400/70 shadow-[0_2px_16px_rgba(34,229,255,0.28)]'
            : 'bg-[#151b3d] text-white/80 hover:bg-[#1a2148]'
        }`}
      >
        <span className="flex h-20 w-20 items-center justify-center rounded-xl bg-gradient-to-br from-cyan-400 to-blue-600 text-white shadow-[0_3px_10px_rgba(34,229,255,0.4)] sm:h-10 sm:w-10 sm:rounded-lg">
          <Trophy className="h-10 w-10 sm:h-5 sm:w-5" />
        </span>
        <span className="text-2xl font-bold sm:text-sm">{t('位置强度榜')}</span>
        <span className="text-sm text-white/45 sm:text-[10px]">{t('根据玩家打分评出，还不赶紧来给你喜欢的球星打个分？！')}</span>
      </button>
    </div>
  );

  // 竖屏（APP/手机）子页通用返回头：大返回按钮 + 标题
  const subHeader = (title: string) => (
    <div className="mb-3 flex items-center gap-3">
      <button
        type="button"
        onClick={goHome}
        aria-label={t('返回榜单菜单')}
        className="flex h-12 w-12 flex-shrink-0 items-center justify-center rounded-full bg-white/10 text-white active:bg-white/25"
      >
        <ChevronLeft className="h-7 w-7" />
      </button>
      <h2 className="text-2xl font-black text-white">{t(title)}</h2>
    </div>
  );

  // 竖屏主菜单：纵向大卡片列表（上下级导航，点入子内容）
  const portraitMenu = (
    <div className="flex flex-col gap-4 py-2">
      {[
        { key: 'tier', Icon: Layers, grad: 'from-pink-400 to-rose-600', title: '我的强度榜', sub: '我也能建立自己的权威榜单，一键分享我的观点。' },
        { key: 'lineup', Icon: Users2, grad: 'from-sky-400 to-blue-600', title: '我的阵容', sub: '不上游戏也一键分享我的排兵布阵！' },
        { key: 'position', Icon: Trophy, grad: 'from-cyan-400 to-blue-600', title: '位置强度榜', sub: '根据玩家打分评出，还不赶紧来给你喜欢的球星打个分？！' },
      ].map(({ key, Icon, grad, title, sub }) => (
        <button
          key={key}
          type="button"
          onClick={() => goTab(key as 'position' | 'tier' | 'lineup')}
          className="flex items-center gap-4 rounded-2xl bg-[#151b3d] p-5 text-left transition active:bg-[#1e2654]"
        >
          <span className={`flex h-20 w-20 flex-shrink-0 items-center justify-center rounded-xl bg-gradient-to-br ${grad}`}>
            <Icon className="h-10 w-10 text-white" />
          </span>
          <span className="flex min-w-0 flex-1 flex-col gap-1">
            <span className="text-4xl font-bold text-white">{t(title)}</span>
            <span className="text-xl leading-snug text-white/55">{t(sub)}</span>
          </span>
          <ChevronRight className="ml-auto h-8 w-8 flex-shrink-0 text-white/30" />
        </button>
      ))}
    </div>
  );

  if (tab === 'home') {
    return landscape ? (
      <div className="px-4 py-4 sm:px-6 sm:py-6">
        {tabBar}
        <div className="flex min-h-[46vh] items-center justify-center px-6 text-center text-sm text-white/45">
          {t('请选择上方榜单类型，榜单内容会在点击后加载')}
        </div>
      </div>
    ) : (
      <div className="px-4 py-4">{portraitMenu}</div>
    );
  }

  if (tab === 'tier') {
    return landscape ? (
      <div className="px-4 py-4 sm:px-6 sm:py-6">
        {tabBar}
        <MyTierList />
      </div>
    ) : (
      <div className="px-3 py-3">
        {subHeader('我的强度榜')}
        <MyTierList />
      </div>
    );
  }

  if (tab === 'lineup') {
    return landscape ? (
      <div className="px-4 py-4 sm:px-6 sm:py-6">
        {tabBar}
        <MyLineup />
      </div>
    ) : (
      <div className="px-3 py-3">
        {subHeader('我的阵容')}
        <MyLineup />
      </div>
    );
  }

  let body: React.ReactNode = null;
  if (loading) {
    body = (
      <div className="flex min-h-[60vh] items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-cyan-400" />
      </div>
    );
  } else if (error) {
    body = (
      <div className="flex min-h-[60vh] items-center justify-center text-white/70">
        {error}
      </div>
    );
  } else if (!data || !data.positions || data.positions.length === 0) {
    body = (
      <div className="flex min-h-[60vh] items-center justify-center text-white/70">
        {t('暂无榜单数据')}
      </div>
    );
  } else {
    body = (
      <div className="space-y-5 sm:space-y-6">
        {data.positions.map((pos) => {
          const theme = POSITION_THEME[pos.positionKey] ?? { gradient: 'from-gray-500 to-gray-600', glow: '', label: pos.positionLabel };
          const hasEnough = pos.items.length > 0;
          return (
            <section key={pos.positionKey}>
              <div className="mb-2 flex items-center gap-3 sm:mb-2.5">
                <span className={`inline-flex h-7 w-1.5 flex-shrink-0 rounded-full bg-gradient-to-b ${theme.gradient} ${theme.glow}`} />
                <button
                  onClick={() => navigate(`/rankings/${pos.positionKey}`)}
                  className="group flex items-center gap-2 text-left text-4xl font-bold text-white transition hover:text-cyan-300 sm:text-xl"
                >
                  {lang === 'en' ? pos.positionKey : pos.positionLabel}
                  <span className="text-2xl font-normal text-white/40 group-hover:text-cyan-400/70 sm:text-sm">
                    TOP {pos.items.length}
                  </span>
                  <span className="text-white/30 transition group-hover:translate-x-0.5 group-hover:text-cyan-400/70">→</span>
                </button>
              </div>

              {!hasEnough ? (
                <div className="rounded-xl border border-white/10 bg-[#141838]/50 py-10 text-center text-white/40">
                  {t('暂无足够评分数据')}
                </div>
              ) : (
                <PositionRow items={pos.items} onCardClick={handleCardClick} />
              )}
            </section>
          );
        })}
      </div>
    );
  }

  return landscape ? (
    <div className="px-4 py-4 sm:px-6 sm:py-6">
      {tabBar}
      <div className="mb-3 sm:mb-4">
        <p className="text-xs text-white/50 sm:text-sm">
          {t('榜单按照玩家评分排序，评分相同按照能力值。快去给你喜欢的球星打分吧！')}
        </p>
      </div>
      {body}
    </div>
  ) : (
    <div className="px-3 py-3">
      {subHeader('位置强度榜')}
      {body}
    </div>
  );
};

interface PositionRowProps {
  items: RankedPlayerItem[];
  onCardClick: (player: RankedPlayerItem) => void;
}

const PositionRow: React.FC<PositionRowProps> = ({ items, onCardClick }) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);
  const startX = useRef(0);
  const scrollLeftStart = useRef(0);
  const moved = useRef(false);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!scrollRef.current) return;
    isDragging.current = true;
    moved.current = false;
    startX.current = e.pageX - scrollRef.current.offsetLeft;
    scrollLeftStart.current = scrollRef.current.scrollLeft;
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging.current || !scrollRef.current) return;
    e.preventDefault();
    const x = e.pageX - scrollRef.current.offsetLeft;
    const walk = x - startX.current;
    if (Math.abs(walk) > 3) moved.current = true;
    scrollRef.current.scrollLeft = scrollLeftStart.current - walk;
  };

  const handleMouseUp = () => {
    isDragging.current = false;
  };

  const handleMouseLeave = () => {
    isDragging.current = false;
  };

  const handleCardClickInner = (player: RankedPlayerItem) => {
    if (moved.current) return;
    onCardClick(player);
  };

  const landscape = useIsLandscape();

  if (landscape) {
    return (
      <div className="grid grid-cols-8 gap-2">
        {items.map((player, index) => (
          <div key={player.id} className="relative">
            <div className="absolute left-1.5 top-1.5 z-20 flex h-5 w-5 items-center justify-center rounded-full bg-gradient-to-br from-yellow-400 to-orange-500 text-[10px] font-black text-white shadow-[0_0_6px_rgba(249_115_22_0.7)]">
              {index + 1}
            </div>
            <PlayerCard player={player} onClick={() => onCardClick(player)} bareCard />
          </div>
        ))}
      </div>
    );
  }

  return (
      <div
        ref={scrollRef}
        className="rank-scroll flex gap-2 overflow-x-auto pb-2"
        style={{
          scrollbarWidth: 'none',
          msOverflowStyle: 'none',
          cursor: isDragging.current ? 'grabbing' : 'grab',
          scrollSnapType: 'x mandatory',
        }}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseLeave}
        onTouchStart={(e) => {
          if (!scrollRef.current) return;
          isDragging.current = true;
          moved.current = false;
          startX.current = e.touches[0].pageX - scrollRef.current.offsetLeft;
          scrollLeftStart.current = scrollRef.current.scrollLeft;
        }}
        onTouchMove={(e) => {
          if (!isDragging.current || !scrollRef.current) return;
          const x = e.touches[0].pageX - scrollRef.current.offsetLeft;
          const walk = x - startX.current;
          if (Math.abs(walk) > 3) moved.current = true;
        }}
        onTouchEnd={() => {
          isDragging.current = false;
        }}
      >
        {items.map((player, index) => (
          <div
            key={player.id}
            className="rank-card relative flex-shrink-0"
            style={{
              flex: '0 0 calc(20% - (8px * 4) / 5)',
              scrollSnapAlign: 'start',
            }}
          >
            <div className="absolute left-1.5 top-1.5 z-20 flex h-5 w-5 items-center justify-center rounded-full bg-gradient-to-br from-yellow-400 to-orange-500 text-[10px] font-black text-white shadow-[0_0_6px_rgba(249_115_22_0.7)] sm:h-6 sm:w-6 sm:text-xs">
              {index + 1}
            </div>
            <PlayerCard player={player} onClick={() => handleCardClickInner(player)} bareCard />
          </div>
        ))}
      </div>
   );
};

export default RankingsPage;
