export function getShineLevelsByPosition(position: string): ShineLevel[] {
  const result: ShineLevel[] = [];
  for (let i = 1; i <= 5; i++) {
    const key = `${position}-${i}`;
    if (SHINE_DATA[key]) {
      result.push(SHINE_DATA[key]);
    }
  }
  return result;
}

export function getShineBonusMap(position: string, level: number): Record<string, number> {
  const map: Record<string, number> = {};
  if (level <= 0) return map;
  for (let i = 1; i <= level; i++) {
    const key = `${position}-${i}`;
    const shine = SHINE_DATA[key];
    if (shine) {
      for (const [attr, bonus] of Object.entries(shine.attrs)) {
        map[attr] = (map[attr] ?? 0) + bonus;
      }
    }
  }
  return map;
}

