export type ShineRuleType = 'normal' | 'gaoguang' | 'huangchuan';

const LEGEND_TYPE_MAP: Record<string, ShineRuleType> = {
  '时刻': 'gaoguang',
  '时刻球员': 'gaoguang',
  '经典传奇': 'huangchuan',
};

export function getShineRuleType(playerType: string | null | undefined): ShineRuleType {
  if (!playerType) return 'normal';
  return LEGEND_TYPE_MAP[playerType] ?? 'normal';
}

export function getLegendShineLevels(
  ruleType: ShineRuleType,
  position: string,
): LegendShineLevel[] {
  const rules = ruleType === 'gaoguang' ? GAOGUANG_SHINE_RULES
    : ruleType === 'huangchuan' ? HUANGCHUAN_SHINE_RULES
    : null;
  if (!rules) return [];
  const posRules = rules[position];
  if (!posRules) return [];
  const result: LegendShineLevel[] = [];
  for (let i = 1; i <= 5; i++) {
    if (posRules[String(i)]) {
      result.push(posRules[String(i)]);
    }
  }
  return result;
}

export function getLegendShineBonusMap(
  ruleType: ShineRuleType,
  position: string,
  level: number,
  baseStats: Record<string, number>,
): Record<string, number> {
  const map: Record<string, number> = {};
  if (ruleType === 'normal' || level <= 0) return map;
  const rules = ruleType === 'gaoguang' ? GAOGUANG_SHINE_RULES : HUANGCHUAN_SHINE_RULES;
  const posRules = rules[position];
  if (!posRules) return map;
  for (let i = 1; i <= level; i++) {
    const lv = posRules[String(i)];
    if (!lv) continue;
    if (lv.allAttrPlus && lv.allAttrPlus > 0) {
      for (const attrKey of Object.keys(baseStats)) {
        map[attrKey] = (map[attrKey] ?? 0) + lv.allAttrPlus;
      }
    }
    for (const [attr, bonus] of Object.entries(lv.attrs)) {
      map[attr] = (map[attr] ?? 0) + bonus;
    }
  }
  return map;
}

export function getLegendShineAbilityPointBonus(
  ruleType: ShineRuleType,
  position: string,
  level: number,
): number {
  if (ruleType !== 'huangchuan' || level <= 0) return 0;
  const posRules = HUANGCHUAN_SHINE_RULES[position];
  if (!posRules) return 0;
  let total = 0;
  for (let i = 1; i <= level; i++) {
    const lv = posRules[String(i)];
    if (lv && lv.abilityPointBonus) {
      total += lv.abilityPointBonus;
    }
  }
  return total;
}

export { GAOGUANG_SHINE_RULES, HUANGCHUAN_SHINE_RULES };
