import React, { useState, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import {
  ShieldAlert,
  Plus,
  Pencil,
  Trash2,
  ChevronLeft,
  ChevronRight,
  Loader2,
  Search,
} from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import {
  getSensitiveWordList,
  createSensitiveWord,
  updateSensitiveWord,
  deleteSensitiveWord,
} from '@client/src/api/admin';
import type { SensitiveWordItem } from '@shared/api.interface';
import { toast } from 'sonner';
import { showConfirm } from '@lark-apaas/client-toolkit';

const LEVEL_OPTIONS: { value: 'high' | 'normal'; label: string }[] = [
  { value: 'high', label: '高危' },
  { value: 'normal', label: '一般' },
];

const CATEGORY_OPTIONS = [
  { value: 'politics', label: '政治敏感' },
  { value: 'porn', label: '色情低俗' },
  { value: 'abuse', label: '辱骂攻击' },
  { value: 'ad', label: '广告垃圾' },
  { value: 'other', label: '其他' },
];

function getLevelLabel(level: string): string {
  return level === 'high' ? '高危' : '一般';
}

function getLevelColor(level: string): string {
  return level === 'high'
    ? 'bg-red-500/20 text-red-300 border-red-400/50'
    : 'bg-yellow-500/20 text-yellow-300 border-yellow-400/50';
}

function getCategoryLabel(category: string): string {
  const found = CATEGORY_OPTIONS.find((c) => c.value === category);
  return found ? found.label : category;
}

const AdminSensitiveWordsPage: React.FC = () => {
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(true);
    return () => setMounted(false);
  }, []);
  const [keyword, setKeyword] = useState('');
  const [searchInput, setSearchInput] = useState('');
  const [levelFilter, setLevelFilter] = useState<string>('');
  const [page, setPage] = useState(1);
  const pageSize = 10;
  const [items, setItems] = useState<SensitiveWordItem[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  // 新增/编辑弹窗
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formWord, setFormWord] = useState('');
  const [formLevel, setFormLevel] = useState<'high' | 'normal'>('normal');
  const [formCategory, setFormCategory] = useState('other');
  const [submitting, setSubmitting] = useState(false);

  const fetchList = useCallback(async () => {
    setLoading(true);
    try {
      const data = await getSensitiveWordList({
        keyword: keyword || undefined,
        level: levelFilter || undefined,
        page,
        pageSize,
      });
      setItems(data.items);
      setTotal(data.total);
    } catch (error) {
      logger.error('加载敏感词列表失败', error);
      toast('加载失败，请刷新重试');
    } finally {
      setLoading(false);
    }
  }, [keyword, levelFilter, page]);

  useEffect(() => {
    fetchList();
  }, [fetchList]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setKeyword(searchInput.trim());
    setPage(1);
  };

  const openCreateDialog = () => {
    setEditingId(null);
    setFormWord('');
    setFormLevel('normal');
    setFormCategory('other');
    setDialogOpen(true);
  };

  const openEditDialog = (item: SensitiveWordItem) => {
    setEditingId(item.id);
    setFormWord(item.word);
    setFormLevel(item.level);
    setFormCategory(item.category);
    setDialogOpen(true);
  };

  const handleSubmit = async () => {
    if (!formWord.trim()) {
      toast.error('请输入敏感词');
      return;
    }
    setSubmitting(true);
    try {
      if (editingId) {
        await updateSensitiveWord(editingId, {
          word: formWord.trim(),
          level: formLevel,
          category: formCategory,
        });
        toast('更新成功');
      } else {
        await createSensitiveWord({
          word: formWord.trim(),
          level: formLevel,
          category: formCategory,
        });
        toast('添加成功');
        setPage(1);
      }
      setDialogOpen(false);
      fetchList();
    } catch (error) {
      logger.error('提交失败', error);
      toast('操作失败，请重试');
    } finally {
      setSubmitting(false);
    }
  };

  const handleToggleEnabled = async (item: SensitiveWordItem) => {
    setActionLoading(item.id);
    try {
      await updateSensitiveWord(item.id, { enabled: !item.enabled });
      toast(item.enabled ? '已禁用' : '已启用');
      fetchList();
    } catch (error) {
      logger.error('切换状态失败', error);
      toast('操作失败，请重试');
    } finally {
      setActionLoading(null);
    }
  };

  const handleDelete = async (item: SensitiveWordItem) => {
    if (!await showConfirm(`确定删除敏感词「${item.word}」吗？`)) return;
    setActionLoading(item.id);
    try {
      await deleteSensitiveWord(item.id);
      toast('删除成功');
      fetchList();
    } catch (error) {
      logger.error('删除失败', error);
      toast('操作失败，请重试');
    } finally {
      setActionLoading(null);
    }
  };

  const totalPages = Math.max(1, Math.ceil(total / pageSize));

  return (
    <div className="min-h-[600px] px-4 py-6">
      {/* 标题 + 搜索 + 新增 */}
      <div className="mb-6 flex flex-wrap items-center gap-4">
        <div className="flex items-center gap-3">
          <ShieldAlert className="h-7 w-7 text-cyan-400" />
          <h1 className="text-2xl font-black text-white tracking-wide">
            敏感词管理
          </h1>
        </div>
        <div className="ml-auto flex items-center gap-2">
          <form onSubmit={handleSearch} className="flex items-center">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/40" />
              <input
                type="text"
                value={searchInput}
                onChange={(e) => setSearchInput(e.target.value)}
                placeholder="搜索敏感词"
                className="h-9 w-48 rounded-lg border border-white/10 bg-[#141838]/70 pl-9 pr-4 text-sm text-white placeholder-white/30 outline-none transition-all focus:border-cyan-400/50 focus:shadow-[0_0_12px_rgba(34_211_238_0.25)]"
              />
            </div>
            <button
              type="submit"
              className="ml-2 h-9 rounded-lg border border-cyan-400/40 bg-cyan-400/10 px-3 text-sm font-medium text-cyan-300 transition-all hover:bg-cyan-400/20 hover:shadow-[0_0_12px_rgba(34_211_238_0.4)]"
            >
              搜索
            </button>
          </form>
          <select
            value={levelFilter}
            onChange={(e) => {
              setLevelFilter(e.target.value);
              setPage(1);
            }}
            className="h-9 rounded-lg border border-white/10 bg-[#141838]/70 px-3 text-sm text-white outline-none transition-all focus:border-cyan-400/50"
          >
            <option value="">全部级别</option>
            <option value="high">高危</option>
            <option value="normal">一般</option>
          </select>
          <button
            onClick={openCreateDialog}
            className="flex h-9 items-center gap-1.5 rounded-lg border border-emerald-400/40 bg-emerald-400/10 px-3 text-sm font-medium text-emerald-300 transition-all hover:bg-emerald-400/20 hover:shadow-[0_0_12px_rgba(16_185_129_0.4)]"
          >
            <Plus className="h-4 w-4" />
            新增
          </button>
        </div>
      </div>

      {/* 列表 */}
      {loading ? (
        <div className="flex items-center justify-center py-20">
          <Loader2 className="h-8 w-8 animate-spin text-cyan-400" />
        </div>
      ) : (items || []).length === 0 ? (
        <div className="rounded-xl border border-white/10 bg-[#141838]/40 py-20 text-center text-white/40">
          暂无敏感词
        </div>
      ) : (
        <div className="overflow-hidden rounded-xl border border-cyan-400/20 bg-[#141838]/50 backdrop-blur-sm">
          {/* 表头 */}
          <div className="grid grid-cols-12 gap-2 border-b border-white/10 bg-white/[0.02] px-4 py-3 text-xs font-semibold text-white/60">
            <div className="col-span-3">敏感词</div>
            <div className="col-span-2">级别</div>
            <div className="col-span-2">分类</div>
            <div className="col-span-2">状态</div>
            <div className="col-span-3 text-right">操作</div>
          </div>
          {/* 行 */}
          {(items || []).map((item) => (
            <div
              key={item.id}
              className="grid grid-cols-12 items-center gap-2 border-b border-white/5 px-4 py-3.5 transition-colors last:border-b-0 hover:bg-white/[0.03]"
            >
              <div className="col-span-3">
                <span className="font-medium text-white/90">{item.word}</span>
              </div>
              <div className="col-span-2">
                <span
                  className={`inline-flex rounded-md border px-2 py-0.5 text-xs font-semibold ${getLevelColor(
                    item.level,
                  )}`}
                >
                  {getLevelLabel(item.level)}
                </span>
              </div>
              <div className="col-span-2 text-sm text-white/70">
                {getCategoryLabel(item.category)}
              </div>
              <div className="col-span-2">
                <button
                  onClick={() => handleToggleEnabled(item)}
                  disabled={actionLoading === item.id}
                  className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors disabled:opacity-50 ${
                    item.enabled
                      ? 'bg-emerald-500'
                      : 'bg-white/15'
                  }`}
                >
                  <span
                    className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                      item.enabled ? 'translate-x-4' : 'translate-x-0.5'
                    }`}
                  />
                </button>
              </div>
              <div className="col-span-3 flex flex-wrap justify-end gap-1.5">
                <button
                  onClick={() => openEditDialog(item)}
                  disabled={actionLoading === item.id}
                  className="flex items-center gap-1 rounded-md border border-cyan-400/40 bg-cyan-400/10 px-2.5 py-1 text-xs font-medium text-cyan-300 transition-all hover:bg-cyan-400/20 disabled:opacity-50"
                >
                  <Pencil className="h-3 w-3" />
                  编辑
                </button>
                <button
                  onClick={() => handleDelete(item)}
                  disabled={actionLoading === item.id}
                  className="flex items-center gap-1 rounded-md border border-red-400/40 bg-red-400/10 px-2.5 py-1 text-xs font-medium text-red-300 transition-all hover:bg-red-400/20 disabled:opacity-50"
                >
                  <Trash2 className="h-3 w-3" />
                  删除
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* 分页 */}
      {total > 0 && (
        <div className="mt-6 flex items-center justify-center gap-2">
          <button
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page === 1}
            className="flex h-8 w-8 items-center justify-center rounded-md border border-white/10 bg-[#141838]/50 text-white/70 transition-all hover:border-cyan-400/40 hover:text-white disabled:opacity-30"
          >
            <ChevronLeft className="h-4 w-4" />
          </button>
          <span className="px-3 text-sm text-white/60">
            第 <span className="text-cyan-300">{page}</span> / {totalPages} 页 · 共 {total} 条
          </span>
          <button
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page === totalPages}
            className="flex h-8 w-8 items-center justify-center rounded-md border border-white/10 bg-[#141838]/50 text-white/70 transition-all hover:border-cyan-400/40 hover:text-white disabled:opacity-30"
          >
            <ChevronRight className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* 新增/编辑弹窗 */}
      {dialogOpen && mounted ? createPortal(
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <div className="w-[420px] rounded-xl border border-cyan-400/40 bg-[#141838] p-6 shadow-[0_0_40px_rgba(34_211_238_0.25)]">
            <h3 className="mb-4 text-lg font-bold text-cyan-300">
              {editingId ? '编辑敏感词' : '新增敏感词'}
            </h3>
            <div className="space-y-4">
              <div>
                <label className="mb-2 block text-sm text-white/70">敏感词</label>
                <input
                  type="text"
                  value={formWord}
                  onChange={(e) => setFormWord(e.target.value)}
                  placeholder="请输入敏感词"
                  className="h-9 w-full rounded-lg border border-white/10 bg-[#0f1330]/60 px-3 text-sm text-white placeholder-white/30 outline-none transition-all focus:border-cyan-400/50"
                />
              </div>
              <div>
                <label className="mb-2 block text-sm text-white/70">级别</label>
                <div className="grid grid-cols-2 gap-2">
                  {LEVEL_OPTIONS.map((opt) => (
                    <button
                      key={opt.value}
                      type="button"
                      onClick={() => setFormLevel(opt.value)}
                      className={`rounded-lg border px-4 py-2 text-sm font-semibold transition-all ${
                        formLevel === opt.value
                          ? opt.value === 'high'
                            ? 'border-red-400/70 bg-red-500/15 text-red-200 shadow-[0_0_16px_rgba(239_68_68_0.4)]'
                            : 'border-yellow-400/70 bg-yellow-500/15 text-yellow-200 shadow-[0_0_16px_rgba(234_179_8_0.4)]'
                          : 'border-white/10 bg-[#0f1330]/60 text-white/70 hover:border-white/20'
                      }`}
                    >
                      {opt.label}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <label className="mb-2 block text-sm text-white/70">分类</label>
                <select
                  value={formCategory}
                  onChange={(e) => setFormCategory(e.target.value)}
                  className="h-9 w-full rounded-lg border border-white/10 bg-[#0f1330]/60 px-3 text-sm text-white outline-none transition-all focus:border-cyan-400/50"
                >
                  {CATEGORY_OPTIONS.map((opt) => (
                    <option key={opt.value} value={opt.value}>
                      {opt.label}
                    </option>
                  ))}
                </select>
              </div>
            </div>
            <div className="mt-6 flex justify-end gap-2">
              <button
                onClick={() => setDialogOpen(false)}
                className="rounded-md border border-white/10 bg-white/5 px-4 py-2 text-sm text-white/70 transition-all hover:bg-white/10"
              >
                取消
              </button>
              <button
                onClick={handleSubmit}
                disabled={submitting}
                className="rounded-md bg-gradient-to-r from-cyan-500 to-purple-500 px-4 py-2 text-sm font-semibold text-white shadow-[0_0_16px_rgba(34_211_238_0.5)] transition-all hover:shadow-[0_0_24px_rgba(34_211_238_0.7)] disabled:opacity-50"
              >
                {submitting && <Loader2 className="mr-1.5 inline h-3.5 w-3.5 animate-spin" />}
                {editingId ? '保存' : '添加'}
              </button>
            </div>
          </div>
        </div>,
        document.body,
      ) : null}
    </div>
  );
};

export default AdminSensitiveWordsPage;
