import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';

export interface BlockedUserItem {
  id: string;
  username: string;
  nickname: string;
  avatarUrl: string | null;
  blockedAt: string | null;
}

/** 拉黑指定用户（幂等） */
export async function blockUser(userId: string): Promise<{ success: boolean }> {
  const res = await axiosForBackend.post(`/api/users/${userId}/block`);
  return res.data;
}

/** 取消拉黑 */
export async function unblockUser(userId: string): Promise<{ success: boolean }> {
  const res = await axiosForBackend.delete(`/api/users/${userId}/block`);
  return res.data;
}

/** 当前用户的黑名单列表 */
export async function listBlocks(): Promise<BlockedUserItem[]> {
  const res = await axiosForBackend.get('/api/blocks');
  return res.data;
}
