import React, { useState } from 'react';
import { Star } from 'lucide-react';

interface RatingStarsProps {
  value: number;
  count?: number;
  interactive?: boolean;
  size?: 'sm' | 'md' | 'lg';
  onRate?: (score: number) => void;
  hideValue?: boolean;
}

const SIZE_MAP = {
  sm: { star: 'w-3.5 h-3.5', text: 'text-base' },
  md: { star: 'w-5 h-5', text: 'text-lg' },
  lg: { star: 'w-7 h-7', text: 'text-xl' },
};

const RatingStars: React.FC<RatingStarsProps> = ({
  value,
  count,
  interactive = false,
  size = 'md',
  onRate,
  hideValue = false,
}) => {
  const [hoverValue, setHoverValue] = useState<number>(0);
  const displayValue = interactive && hoverValue > 0 ? hoverValue : value;

  const sizeClass = SIZE_MAP[size];
  const filledColor = '#FFD600';
  const emptyColor = 'hsl(0 0% 100% / 0.2)';

  const handleClick = (score: number) => {
    if (!interactive || !onRate) return;
    onRate(score);
  };

  return (
    <div className="flex items-center gap-2">
      <div
        className={`flex items-center gap-0.5 ${
          interactive ? 'cursor-pointer' : ''
        }`}
        onMouseLeave={() => interactive && setHoverValue(0)}
      >
        {[1, 2, 3, 4, 5].map((i) => {
          const filled = i <= Math.round(displayValue);
          const isHalf = !filled && i - 0.5 <= displayValue;
          return (
            <div
              key={i}
              onMouseEnter={() => interactive && setHoverValue(i)}
              onClick={() => handleClick(i)}
              className={`relative ${
                interactive
                  ? 'transition-transform hover:scale-110'
                  : ''
              }`}
            >
              {filled ? (
                <Star
                  className={`${sizeClass.star} text-[#FFD600] fill-[#FFD600] drop-shadow-[0_0_6px_rgba(255_214_0_0.6)]`}
                />
              ) : isHalf ? (
                <div className="relative">
                  <Star
                    className={`${sizeClass.star}`}
                    style={{ color: emptyColor }}
                  />
                  <div className="absolute inset-0 overflow-hidden" style={{ width: '50%' }}>
                    <Star
                      className={`${sizeClass.star} text-[#FFD600] fill-[#FFD600]`}
                    />
                  </div>
                </div>
              ) : (
                <Star
                  className={`${sizeClass.star}`}
                  style={{ color: emptyColor }}
                />
              )}
            </div>
          );
        })}
      </div>
      {!hideValue && (
        <span className={`${sizeClass.text} font-semibold text-[#FFD600]`}>
          {value.toFixed(1)}
        </span>
      )}
      {count !== undefined && (
        <span className={`${sizeClass.text} text-gray-400`}>
          / 5（{count}人评分）
        </span>
      )}
    </div>
  );
};

export default RatingStars;
