import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  ThumbsUp,
  ThumbsDown,
  Flag,
  Ban,
  Loader2,
  Pin,
   Trash2,
   ArrowLeft,
   MessageSquarePlus,
 } from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { toast } from 'sonner';
import dayjs from 'dayjs';

import { Button } from '@client/src/components/ui/button';
import { Badge } from '@client/src/components/ui/badge';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@client/src/components/ui/dialog';
import { useAuth } from '@client/src/context/AuthContext';
import { useLoginGuard } from '@client/src/hooks/useLoginGuard';
import UserAvatar from '@client/src/components/ui/user-avatar';
import {
  getPostDetail,
  votePost,
  report,
  deletePost,
  adminDeletePost,
  adminPinPost,
  type ForumPostDetail,
  type VoteType,
  type BoardKey,
} from '@client/src/api/forum';
import MediaDisplay from '@client/src/components/MediaDisplay';
import { blockUser, unblockUser } from '@client/src/api/blocks';
import { showConfirm } from '@lark-apaas/client-toolkit';
import FavoriteButton from '@client/src/components/FavoriteButton';
import { toggleFollow, checkFollow } from '@client/src/api/follows';
import CommentSection from '@client/src/components/CommentSection';
import CommentInput from '@client/src/components/CommentInput';
import type { CommentMediaItem } from '@shared/api.interface';
import {
  visitorLocalGet,
  visitorLocalSet,
  visitorLocalHas,
  visitorLocalToggle,
  toastVisitorLocal,
} from '@client/src/utils/visitor-mode';
import { comments as commentsApi } from '@client/src/api';
import { useSetForumDetailHeader } from '@client/src/components/Layout';
import PullToRefresh from '@client/src/components/PullToRefresh';
import { useIsMobile } from '@client/src/hooks/use-mobile';

interface BoardConfig {
  key: BoardKey;
  label: string;
  emoji: string;
  theme: 'orange' | 'cyan' | 'purple';
}

const BOARD_MAP: Record<string, BoardConfig> = {
  international: { key: 'international', label: '国际服', emoji: '🌍', theme: 'orange' },
  cn: { key: 'cn', label: '国服', emoji: '🇨🇳', theme: 'cyan' },
  bug: { key: 'bug', label: '意见建议BUG反馈', emoji: '🐛', theme: 'purple' },
};

const THEME_STYLES: Record<string, { border: string; bg: string; text: string; shadow: string }> = {
  orange: { border: 'border-orange-400/60', bg: 'bg-orange-500/20', text: 'text-orange-300', shadow: 'shadow-[0_0_20px_rgba(249_115_22_0.5)]' },
  cyan: { border: 'border-cyan-400/60', bg: 'bg-cyan-500/20', text: 'text-cyan-300', shadow: 'shadow-[0_0_20px_rgba(34_211_238_0.5)]' },
  purple: { border: 'border-purple-400/60', bg: 'bg-purple-500/20', text: 'text-purple-300', shadow: 'shadow-[0_0_20px_rgba(139_92_246_0.5)]' },
};

const REPORT_REASONS = ['垃圾广告', '色情低俗', '人身攻击', '违法违规', '内容不实', '其他原因'];

const ForumDetailPage: React.FC = () => {
  const { id = '' } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user, getAuthHeaders } = useAuth();
  const { allowLocalAction } = useLoginGuard();
  const isMobile = useIsMobile();
  const commentSectionRef = useRef<import('@client/src/components/CommentSection').CommentSectionRef | null>(null);

  const [post, setPost] = useState<ForumPostDetail | null>(null);
  const [postLoading, setPostLoading] = useState(true);
  const [voteLoading, setVoteLoading] = useState(false);
  const [showReportDialog, setShowReportDialog] = useState(false);
  const [reportReason, setReportReason] = useState('');
  const [reportSubmitting, setReportSubmitting] = useState(false);
  const [commentDialogOpen, setCommentDialogOpen] = useState(false);
  const setForumDetailHeader = useSetForumDetailHeader();
  const [following, setFollowing] = useState(false);
  const [followLoading, setFollowLoading] = useState(false);
  // 游客本机投票状态（kind='forum_vote'，key=post.id）；已登录用户走云端 post.userVote
  const [visitorVote, setVisitorVote] = useState<VoteType | null>(null);

  const isAdmin = user?.role === 'super_admin' || user?.role === 'admin';

  const canDeletePost = (): boolean => {
    if (!user || !post) return false;
    if (isAdmin) return true;
    return post.userId === user.id;
  };

  const handleDeletePost = async () => {
    if (!user || !post) return;
    const confirmed = await showConfirm('确定要删除这条帖子吗？此操作不可撤销。');
    if (!confirmed) return;
    try {
      if (isAdmin) {
        const reason = window.prompt('请输入删除原因（可选）：') || '';
        await adminDeletePost(post.id, reason, getAuthHeaders());
      } else {
        await deletePost(post.id, getAuthHeaders());
      }
      toast.success('删除成功');
      setPost({ ...post, isDeleted: true });
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : '删除失败';
      toast.error(msg);
    }
  };

  const [pinning, setPinning] = useState(false);
  const handleTogglePin = async () => {
    if (!post || pinning) return;
    const nextPin = !post.isPinned;
    setPinning(true);
    try {
      await adminPinPost(post.id, nextPin, getAuthHeaders());
      setPost({
        ...post,
        isPinned: nextPin,
        pinnedAt: nextPin ? new Date().toISOString() : undefined,
      });
      toast.success(nextPin ? '已置顶到板块最前' : '已取消置顶');
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : '操作失败';
      toast.error(msg);
    } finally {
      setPinning(false);
    }
  };

  const fetchPost = useCallback(async () => {
    setPostLoading(true);
    try {
      const data = await getPostDetail(id);
      setPost(data);
      // 游客：读取本机关注 / 投票状态；已登录：走云端 checkFollow
      if (!user) {
        setFollowing(visitorLocalHas('follow_user', data.userId));
        const localVote = visitorLocalGet('forum_vote', data.id);
        setVisitorVote(localVote === 'like' || localVote === 'dislike' ? localVote : null);
      } else if (user.id !== data.userId) {
        try {
          const res = await checkFollow(data.userId, getAuthHeaders());
          setFollowing(res.following);
        } catch (err: unknown) {
          logger.error('检查关注状态失败', err);
          setFollowing(false);
        }
      } else {
        setFollowing(false);
      }
    } catch (error) {
      logger.error('加载帖子详情失败', error);
      setPost(null);
    } finally {
      setPostLoading(false);
    }
  }, [id]);

  useEffect(() => {
    fetchPost();
  }, [fetchPost]);

  const handleRefresh = useCallback(async () => {
    try {
      await Promise.all([
        fetchPost(),
        commentSectionRef.current?.refresh(),
      ]);
    } catch {
      // 单个失败不阻塞整体刷新结束
    }
  }, [fetchPost]);

  useEffect(() => {
    if (!setForumDetailHeader) return;
    if (!post) {
      setForumDetailHeader(null);
      return;
    }
    const cfg = BOARD_MAP[post.board];
    setForumDetailHeader({
      boardKey: post.board,
      boardLabel: cfg.label,
      boardEmoji: cfg.emoji,
      boardTheme: cfg.theme,
    });
    return () => setForumDetailHeader(null);
  }, [post, setForumDetailHeader]);

  const handleVote = async (voteType: VoteType) => {
    if (!allowLocalAction('投票')) return;
    if (!post) return;
    // 游客：仅本机投票，再点同项取消、点另一项切换
    if (!user) {
      const current = visitorLocalGet('forum_vote', post.id);
      const next = current === voteType ? null : voteType;
      visitorLocalSet('forum_vote', post.id, next);
      setVisitorVote(next);
      if (next) toastVisitorLocal('forum_vote');
      return;
    }
    if (voteLoading) return;
    setVoteLoading(true);
    try {
      const result = await votePost(post.id, voteType, getAuthHeaders());
      setPost({ ...post, likeCount: result.likeCount, dislikeCount: result.dislikeCount, userVote: result.userVote });
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : '投票失败';
      toast.error(msg);
    } finally {
      setVoteLoading(false);
    }
  };

  const handleFabClick = () => {
    if (!user) {
      toast.info('请先登录后发表评论');
      navigate('/auth', { state: { from: window.location.pathname } });
      return;
    }
    setCommentDialogOpen(true);
  };

  const handleSubmitComment = async (content: string, mediaUrls: CommentMediaItem[]) => {
    const newComment = await commentsApi.create(
      {
        targetType: 'forum_post',
        targetId: id,
        content,
        mediaUrls: mediaUrls.length > 0 ? mediaUrls : undefined,
      },
      getAuthHeaders(),
    );
    toast.success('评论成功');
    setCommentDialogOpen(false);
    // 触发评论区刷新
    window.dispatchEvent(new CustomEvent('forum-comment-added', { detail: newComment }));
  };

  const handleReport = async () => {
    if (!reportReason) {
      toast.error('请选择举报原因');
      return;
    }
    setReportSubmitting(true);
    try {
      await report({ targetType: 'post', targetId: id, reason: reportReason }, getAuthHeaders());
      toast.success('举报已提交，感谢您的反馈');
      setShowReportDialog(false);
      setReportReason('');
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : '举报失败';
      toast.error(msg);
    } finally {
      setReportSubmitting(false);
    }
  };

  const isAuthor = user && post && user.id === post.userId;

  // 拉黑 / 取消拉黑帖子作者（能看到帖子说明尚未拉黑）
  const [authorBlocked, setAuthorBlocked] = useState(false);
  const [blockBusy, setBlockBusy] = useState(false);
  const handleToggleAuthorBlock = async () => {
    if (!post || blockBusy) return;
    if (!user) {
      toast.info('请先登录');
      navigate('/auth', { state: { from: window.location.pathname } });
      return;
    }
    setBlockBusy(true);
    try {
      if (authorBlocked) {
        await unblockUser(post.userId);
        setAuthorBlocked(false);
        toast.success('已取消拉黑');
      } else {
        await blockUser(post.userId);
        setAuthorBlocked(true);
        toast.success('已拉黑，刷新后不再显示该用户内容');
      }
    } catch {
      toast.error('操作失败，请重试');
    } finally {
      setBlockBusy(false);
    }
  };

  const handleFollowToggle = async (): Promise<void> => {
    if (!allowLocalAction('关注')) return;
    if (!post) return;
    // 游客：仅本机关注（kind='follow_user'，key=post.userId）
    if (!user) {
      const next = visitorLocalToggle('follow_user', post.userId);
      setFollowing(next);
      if (next) toastVisitorLocal('follow_user');
      return;
    }
    setFollowLoading(true);
    const prev = following;
    setFollowing(!prev);
    try {
      const res = await toggleFollow(post.userId, getAuthHeaders());
      setFollowing(res.following);
      toast.success(res.following ? '关注成功' : '已取消关注');
    } catch (err: unknown) {
      logger.error('关注操作失败', err);
      setFollowing(prev);
      toast.error('操作失败');
    } finally {
      setFollowLoading(false);
    }
  };

  if (postLoading) {
    return <div className="flex items-center justify-center py-20"><Loader2 className="h-8 w-8 animate-spin text-cyan-400" /></div>;
  }

  if (!post) {
    return (
      <div className="py-20 text-center">
        <p className="text-base text-gray-400">帖子不存在或已被删除</p>
        <Button variant="outline" onClick={() => navigate('/forum')} className="mt-4 border-white/10 text-cyan-300">
          <ArrowLeft className="mr-1.5 h-4 w-4" />返回列表
        </Button>
      </div>
    );
  }

  const postDeleted = post.isDeleted;

  const boardCfg = BOARD_MAP[post.board];
  const theme = THEME_STYLES[boardCfg.theme];

  // 投票展示：已登录直接用云端值；游客在服务端基础票数上叠加本机投票
  const effectiveUserVote: VoteType | null | undefined = user
    ? post.userVote
    : visitorVote;
  const displayLikeCount =
    post.likeCount + (user ? 0 : visitorVote === 'like' ? 1 : 0);
  const displayDislikeCount =
    post.dislikeCount + (user ? 0 : visitorVote === 'dislike' ? 1 : 0);

  return (
      <PullToRefresh onRefresh={handleRefresh} disabled={!isMobile}>
      <div className="space-y-3 sm:space-y-3 text-white overflow-x-hidden">
      {/* 帖子内容 */}
      <div className="rounded-xl border border-white/10 bg-[#141838]/70 p-3 sm:p-3 backdrop-blur-sm shadow-[0_0_30px_rgba(34_211_238_0.08)]">
        {postDeleted ? (
          <div className="py-12 text-center">
 <h2 className="mb-2 text-2xl font-bold text-gray-400">内容已删除</h2>
               <p className="text-base text-gray-500">
               该帖子已被{post.userId === user?.id ? '您' : '管理员'}删除
             </p>
           </div>
        ) : (
        <>
        <div className="mb-2 sm:mb-3 flex items-start justify-between gap-2 sm:gap-3">
          <h1 className="flex-1 min-w-0 text-6xl sm:text-2xl font-bold text-white leading-tight break-words">{post.title}</h1>
          <div className="flex flex-shrink-0 items-center gap-1 sm:gap-2 mt-0.5 sm:mt-1">
            <Badge
              className={`flex items-center gap-1 text-sm sm:text-xs px-1.5 sm:px-2 py-0.5 sm:py-1 rounded-full whitespace-nowrap border ${theme.border} ${theme.bg} ${theme.text}`}
            >
              <span className="shrink-0">{boardCfg.emoji}</span>
              <span className="hidden sm:inline">{boardCfg.label}</span>
            </Badge>
            {isAdmin && post && !postDeleted && (
              <button
                onClick={handleTogglePin}
                disabled={pinning}
                className={`flex items-center justify-center h-7 w-7 sm:h-8 sm:w-8 transition-colors ${
                  post.isPinned
                    ? 'text-cyan-300 hover:text-cyan-200'
                    : 'text-gray-300 hover:text-cyan-300'
                }`}
                title={post.isPinned ? '取消置顶' : '置顶'}
              >
                {pinning ? (
                  <Loader2 className="h-3.5 w-3.5 animate-spin sm:h-4 sm:w-4" />
                ) : (
                  <Pin
                    className={`h-3.5 w-3.5 sm:h-4 sm:w-4 ${
                      post.isPinned ? 'fill-cyan-300' : ''
                    }`}
                  />
                )}
              </button>
            )}
            {canDeletePost() && !postDeleted && (
              <button
                onClick={handleDeletePost}
                 className="flex items-center justify-center h-7 w-7 sm:h-8 sm:w-8 text-red-400 transition-colors hover:text-red-500"
                 title="删除帖子"
              >
                  <Trash2 className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
              </button>
            )}
            <FavoriteButton targetType="forum_post" targetId={post.id} size="sm" className="sm:p-2" />
          </div>
        </div>
        <div className="mb-3 sm:mb-4 flex flex-wrap items-center gap-x-2 sm:gap-x-3 gap-y-0.5 sm:gap-y-1 text-gray-500 break-all">
           <button
             onClick={() => navigate(`/user/${post.userId}`)}
             className="flex items-center gap-2 min-w-0 group"
           >
             <UserAvatar
               avatarUrl={user?.id === post.userId ? user.avatarUrl : null}
               userName={post.userName}
               size="xl"
             />
             <span className="whitespace-nowrap text-4xl sm:text-sm font-medium text-cyan-300 hover:text-cyan-200 hover:underline underline-offset-2 transition-colors cursor-pointer">{post.userName}</span>
           </button>
             <span className="text-2xl sm:text-sm whitespace-nowrap">{dayjs(post.createdAt).format('YYYY-MM-DD HH:mm')}</span>
           {!isAuthor && (
             <button
               onClick={handleFollowToggle}
               disabled={followLoading}
               className={`ml-auto inline-flex h-12 px-4 items-center justify-center rounded-full text-2xl font-medium transition-all flex-shrink-0 ${
                 following
                   ? 'border border-white/20 bg-white/10 text-white/80 hover:bg-white/15'
                   : 'border border-pink-400/60 bg-pink-500/20 text-pink-300 hover:bg-pink-500/30 shadow-[0_0_10px_rgba(236_72_153_0.3)]'
               }`}
             >
               {following ? '已关注' : '+ 关注'}
             </button>
           )}
          </div>
         <div className="whitespace-pre-wrap text-4xl sm:text-sm leading-[3.6rem] sm:leading-6 text-gray-300">{post.content}</div>

        {post.mediaUrls && post.mediaUrls.length > 0 && !postDeleted && (
          <div className="mt-2.5">
            <MediaDisplay mediaList={post.mediaUrls} />
          </div>
        )}

         {!postDeleted && (
          <div className="mt-3 sm:mt-3 flex items-center gap-2 sm:gap-3 border-t border-white/10 pt-3 sm:pt-2.5">
           <Button
             variant="outline" size="sm" onClick={() => handleVote('like')} disabled={voteLoading}
             className={`h-14 sm:h-9 px-3 sm:px-3 gap-1.5 sm:gap-1.5 border transition-all text-4xl sm:text-sm ${effectiveUserVote === 'like' ? 'border-cyan-400/60 bg-cyan-500/20 text-cyan-300 shadow-[0_0_12px_rgba(34_211_238_0.4)]' : 'border-white/10 bg-[#0A0E27] text-gray-300 hover:border-cyan-400/40 hover:text-cyan-200'}`}
           >
              <ThumbsUp className="h-10! w-10! sm:h-6! sm:w-6!" />{displayLikeCount}
           </Button>
           <Button
             variant="outline" size="sm" onClick={() => handleVote('dislike')} disabled={voteLoading}
             className={`h-14 sm:h-9 px-3 sm:px-3 gap-1.5 sm:gap-1.5 border transition-all text-4xl sm:text-sm ${effectiveUserVote === 'dislike' ? 'border-pink-400/60 bg-pink-500/20 text-pink-300 shadow-[0_0_12px_rgba(236_72_153_0.4)]' : 'border-white/10 bg-[#0A0E27] text-gray-300 hover:border-pink-400/40 hover:text-pink-200'}`}
           >
              <ThumbsDown className="h-10! w-10! sm:h-6! sm:w-6!" />{displayDislikeCount}
           </Button>
           <div className="flex-1" />
           <Button
             variant="outline" size="sm"
              onClick={() => {
                if (!user) { toast.info('请先登录'); navigate('/auth', { state: { from: window.location.pathname } }); return; }
                setShowReportDialog(true);
              }}
             className="h-14 sm:h-9 px-3 sm:px-3 gap-1.5 sm:gap-1.5 border-white/10 bg-[#0A0E27] text-gray-400 hover:border-orange-400/40 hover:text-orange-300 text-4xl sm:text-sm"
           >
             <Flag className="h-10! w-10! sm:h-6! sm:w-6!" />举报
           </Button>
           {user && !isAuthor && (
             <Button
               variant="outline"
               size="sm"
               onClick={handleToggleAuthorBlock}
               disabled={blockBusy}
               className={`h-14 sm:h-9 px-3 sm:px-3 gap-1.5 sm:gap-1.5 text-4xl sm:text-sm border ${
                 authorBlocked
                   ? 'border-red-400/50 bg-red-500/15 text-red-300 hover:border-red-300/60'
                   : 'border-white/10 bg-[#0A0E27] text-gray-400 hover:border-red-400/40 hover:text-red-300'
               }`}
             >
               <Ban className="h-10! w-10! sm:h-6! sm:w-6!" />
               {authorBlocked ? '取消拉黑' : '拉黑'}
             </Button>
           )}
         </div>
        )}
        </>
        )}
      </div>

       <CommentSection targetType="forum_post" targetId={id || ''} ref={commentSectionRef} large />

       {/* FAB 评论按钮 */}
      {!postDeleted && (
        <button
          onClick={handleFabClick}
           className="fixed bottom-[calc(env(safe-area-inset-bottom)+64px)] right-4 z-[100] flex items-center gap-1.5 px-4 py-3 rounded-full bg-gradient-to-r from-cyan-400 to-purple-500 text-white font-bold text-4xl shadow-[0_0_20px_rgba(34_211_238_0.5)] hover:shadow-[0_0_28px_rgba(34_211_238_0.7)] transition-all min-h-[44px] active:scale-95"
        >
          <MessageSquarePlus className="w-9 h-9" />
           <span>回复</span>
        </button>
      )}

      {/* 评论输入弹窗 */}
      <Dialog open={commentDialogOpen} onOpenChange={setCommentDialogOpen}>
        <DialogContent className="fixed bottom-0 left-0 right-0 translate-x-0 translate-y-0 mx-auto w-full max-w-[560px] max-h-[70vh] sm:max-h-[70vh] h-[80vh] sm:h-auto overflow-y-auto rounded-t-2xl rounded-b-none border-white/10 bg-[#141838] text-white p-4 pt-8">
          <CommentInput
            isLoggedIn={!!user}
            variant="dialog"
            onSubmit={handleSubmitComment}
          />
        </DialogContent>
      </Dialog>

      {/* 举报对话框 */}
      <Dialog open={showReportDialog} onOpenChange={setShowReportDialog}>
        <DialogContent className="border-white/10 bg-[#141838] text-white sm:max-w-[420px]">
            <DialogHeader><DialogTitle className="text-2xl font-bold text-white">举报帖子</DialogTitle></DialogHeader>
           <div className="py-2">
              <p className="mb-3 text-base text-gray-400">请选择举报原因：</p>
             <div className="space-y-2">
               {REPORT_REASONS.map((reason) => (
                 <button
                   key={reason} onClick={() => setReportReason(reason)}
                    className={`w-full rounded-lg border px-4 py-2.5 text-left text-base transition-all ${reportReason === reason ? 'border-cyan-400/60 bg-cyan-500/15 text-cyan-200 shadow-[0_0_12px_rgba(34_211_238_0.3)]' : 'border-white/10 bg-[#0A0E27] text-gray-300 hover:border-white/20'}`}
                >
                  {reason}
                </button>
              ))}
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => { setShowReportDialog(false); setReportReason(''); }}
              className="border-white/10 bg-transparent text-gray-300 hover:bg-white/5 hover:text-white">
              取消
            </Button>
            <Button onClick={handleReport} disabled={reportSubmitting || !reportReason}
              className="bg-gradient-to-r from-orange-500 to-pink-500 text-white shadow-[0_0_12px_rgba(249_115_22_0.5)] disabled:opacity-50">
              {reportSubmitting && <Loader2 className="mr-1.5 h-4 w-4 animate-spin" />}
              提交举报
            </Button>
          </DialogFooter>
        </DialogContent>
       </Dialog>
     </div>
      </PullToRefresh>
   );
};

export default ForumDetailPage;
