function hexToRgba(hex: string, alpha: number): string {
  const h = hex.replace('#', '');
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

function lucideDataUrl(iconKey: string, color: string): string {
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" ` +
    `fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">` +
    LUCIDE_INNER[iconKey] + '</svg>';
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

interface ChipStyle {
  fg: string;
  bg: string;
  border?: string;
  font?: string;
  h?: number;
  padX?: number;
  iconImg?: HTMLImageElement | null;
  iconSize?: number;
}

// 胶囊占位宽度（含可选前置图标）
function chipWidth(ctx: CanvasRenderingContext2D, it: ChipStyle & { text: string }): number {
  const padX = it.padX ?? 10;
  ctx.font = it.font ?? 'bold 16px system-ui, sans-serif';
  let w = ctx.measureText(it.text).width + padX * 2;
  if (it.iconImg) w += (it.iconSize ?? 15) + 5;
  return w;
}

function drawChip(
  ctx: CanvasRenderingContext2D,
  text: string,
  x: number,
  y: number,
  opts: ChipStyle,
): number {
  const font = opts.font ?? 'bold 16px system-ui, sans-serif';
  const padX = opts.padX ?? 10;
  const h = opts.h ?? 29;
  ctx.font = font;
  const iconSz = opts.iconImg ? (opts.iconSize ?? 15) : 0;
  const iconGap = opts.iconImg ? 5 : 0;
  const w = ctx.measureText(text).width + padX * 2 + iconSz + iconGap;
  ctx.fillStyle = opts.bg;
  ctx.beginPath();
  const r = h / 2;
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
  ctx.fill();
  if (opts.border) {
    ctx.strokeStyle = opts.border;
    ctx.lineWidth = 1.3;
    ctx.stroke();
  }
  // 前置图标
  let textX = x + padX;
  if (opts.iconImg) {
    ctx.drawImage(opts.iconImg, x + padX, y + (h - iconSz) / 2, iconSz, iconSz);
    textX += iconSz + iconGap;
  }
  ctx.fillStyle = opts.fg;
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'left';
  ctx.fillText(text, textX, y + h / 2 + 1);
  return w;
}

interface FlowItem extends ChipStyle {
  text: string;
}
// 自动换行的胶囊流，返回最终底部 y
function chipFlow(
  ctx: CanvasRenderingContext2D,
  items: FlowItem[],
  x: number,
  y: number,
  maxX: number,
  gap = 7,
  pitch = 42,
): number {
  let cx = x;
  let cy = y;
  items.forEach((it) => {
    const needW = chipWidth(ctx, it);
    if (cx + needW > maxX && cx > x) { cx = x; cy += pitch; }
    drawChip(ctx, it.text, cx, cy, it);
    cx += needW + gap;
  });
  return cy + (items[0]?.h ?? 30);
}

// 仅计算胶囊流需要的行数（不绘制）
function countFlowRows(
  ctx: CanvasRenderingContext2D,
  items: FlowItem[],
  x: number,
  maxX: number,
  gap = 7,
): number {
  let cx = x;
  let rows = 1;
  items.forEach((it) => {
    const needW = chipWidth(ctx, it);
    if (cx + needW > maxX && cx > x) { cx = x; rows += 1; }
    cx += needW + gap;
  });
  return rows;
}

// 详情页同款「进攻/防守风格」图标胶囊
function drawStylePill(
  ctx: CanvasRenderingContext2D,
  icon: HTMLImageElement,
  text: string,
  x: number,
  y: number,
  w: number,
  h: number,
  fg: string,
  bg: string,
  border: string,
): void {
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.roundRect(x, y, w, h, 12);
  ctx.fill();
  ctx.strokeStyle = border;
  ctx.lineWidth = 1.3;
  ctx.stroke();
  ctx.font = `bold 19px system-ui, sans-serif`;
  const tw = ctx.measureText(text).width;
  const isz = 20;
  const total = isz + 7 + tw;
  const sx = x + (w - total) / 2;
  ctx.drawImage(icon, sx, y + (h - isz) / 2, isz, isz);
  ctx.fillStyle = fg;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, sx + isz + 7, y + h / 2 + 1);
}

// 纯色面板（不透明），内部不显示背景图
function drawSolidPanel(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  radius = 20,
): void {
  const g = ctx.createLinearGradient(0, y, 0, y + h);
  g.addColorStop(0, '#111838');
  g.addColorStop(1, '#0b1029');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.roundRect(x, y, w, h, radius);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.10)';
  ctx.lineWidth = 1.3;
  ctx.stroke();
}

export async function renderPlayerShareCanvas(data: PlayerShareData): Promise<HTMLCanvasElement> {
  const { player } = data;
  const W = 1600;
  const H = 1000;
  // 运行时语言（由 I18nProvider 同步到 trTerm）；中文态 T 原样返回，英文态翻英文
  const isEn = trTerm('进攻意识') !== '进攻意识';
  const T = (s?: string | null): string => trTerm(s ?? '');
  // 增能/闪耀胶囊文案形如“基础名 +等级”或“基础名 等级”：只翻译基础名，末尾数值原样保留
  const TBooster = (label: string): string => {
    const m = String(label).match(/^(.*?)\s*(\+?\d+)\s*$/);
    if (!m) return T(label);
    return `${T(m[1].trim())} ${m[2]}`;
  };

  const iconImg = await loadImage(LOCAL_ASSETS.icon);
  const cardImg = await loadImage(
    viaProxy(resolvePlayerCardImage(player.playerImageUrl, player.id)),
  );
  let bgImg: HTMLImageElement | null = null;
  try {
    bgImg = await loadImage(viaProxy(BANNER_URL));
  } catch {
    bgImg = null;
  }

  // 风格 / 加点类别 图标
  const offIcon = await loadImage(lucideDataUrl('swords', '#f9a8d4'));
  const defIcon = await loadImage(lucideDataUrl('shieldcheck', '#6ee7b7'));
  const catIcons: Record<string, HTMLImageElement> = {};
  for (const key of Object.keys(CAT_ICON)) {
    if (catIcons[CAT_ICON[key]]) { catIcons[key] = catIcons[CAT_ICON[key]]; continue; }
    // eslint-disable-next-line no-await-in-loop
    const im = await loadImage(lucideDataUrl(CAT_ICON[key], '#94a3b8'));
    catIcons[key] = im;
    catIcons[CAT_ICON[key]] = im;
  }

  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d')!;

  // ===== 背景：深色渐变打底 =====
  const bg = ctx.createLinearGradient(0, 0, W, H);
  bg.addColorStop(0, '#0a0f2e');
  bg.addColorStop(0.55, '#0c1338');
  bg.addColorStop(1, '#141a4a');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // 主视觉图（cover）+ 压暗
  if (bgImg) {
    const ir = bgImg.width / bgImg.height;
    let dw = W;
    let dh = W / ir;
    let dx = 0;
    let dy = (H - dh) / 2;
    if (dh < H) { dh = H; dw = H * ir; dx = (W - dw) / 2; dy = 0; }
    ctx.drawImage(bgImg, dx, dy, dw, dh);
    ctx.fillStyle = 'rgba(7,10,28,0.66)';
    ctx.fillRect(0, 0, W, H);
  }

  // 斜向渐变条纹
  ctx.save();
  ctx.strokeStyle = 'rgba(255,255,255,0.055)';
  ctx.lineWidth = 2;
  for (let d = -H; d < W; d += 84) {
    ctx.beginPath();
    ctx.moveTo(d, H);
    ctx.lineTo(d + H, 0);
    ctx.stroke();
  }
  ctx.restore();

  // 两团柔和光晕
  const glow = (cx: number, cy: number, r: number, color: string) => {
    const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
    g.addColorStop(0, color);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.fillRect(cx - r, cy - r, r * 2, r * 2);
  };
  glow(160, 120, 440, 'rgba(34,211,238,0.12)');
  glow(1480, 940, 520, 'rgba(217,70,239,0.12)');

  // 顶部品牌带
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'rgba(255,255,255,0.88)';
  ctx.font = 'bold 24px system-ui, sans-serif';
  ctx.fillText(isEn ? 'PlayToStar APP' : 'PlayToStar APP（实况起点）', 40, 40);

  // ===== 面板几何 =====
  const lpX = 24;
  const lpY = 70;
  const lpW = 440;
  const lpH = H - 140; // 860
  const rpX = 480;
  const rpY = 70;
  const rpW = W - rpX - 24; // 1096
  const rpH = H - 140; // 860

  // ============================================================
  // 右侧面板：加点方案（图标+数值）→ 三列属性 → 球员技能
  // ============================================================
  drawSolidPanel(ctx, rpX, rpY, rpW, rpH, 20);
  const rPad = 22;
  const rInnerX = rpX + rPad;
  const rMaxX = rpX + rpW - rPad;
  const rInnerW = rMaxX - rInnerX;

  // ---- 加点方案（10 项，图标+名称+数值）----
  ctx.textAlign = 'left';
  ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#67e8f9';
  ctx.font = 'bold 22px system-ui, sans-serif';
  ctx.fillText(T('加点方案'), rInnerX, rpY + 30);

  // 10 项压缩为一行：图标 + 数值（居中），数值放大
  const allocFlat = ['shooting', 'passing', 'dribbling', 'dexterity', 'lowerBody', 'aerial', 'defending', 'gk1', 'gk2', 'gk3'];
  const aGap = 6;
  const aH = 50;
  const aCellW = (rInnerW - 9 * aGap) / 10;
  const aY = rpY + 42;
  allocFlat.forEach((key, i) => {
    const ax = rInnerX + i * (aCellW + aGap);
    const val = Number(data.allocations[key]) || 0;
    const active = val > 0;
    ctx.fillStyle = active ? 'rgba(56,189,248,0.16)' : 'rgba(255,255,255,0.04)';
    ctx.beginPath();
    ctx.roundRect(ax, aY, aCellW, aH, 11);
    ctx.fill();
    ctx.strokeStyle = active ? 'rgba(56,189,248,0.5)' : 'rgba(255,255,255,0.09)';
    ctx.lineWidth = 1.1;
    ctx.stroke();
    ctx.font = 'bold 28px system-ui, sans-serif';
    const vw = ctx.measureText(String(val)).width;
    const iconSz = 24;
    const ig = 7;
    const groupW = iconSz + ig + vw;
    const gx = ax + (aCellW - groupW) / 2;
    const im = catIcons[key];
    if (im) ctx.drawImage(im, gx, aY + (aH - iconSz) / 2, iconSz, iconSz);
    ctx.fillStyle = active ? '#7dd3fc' : '#52607a';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(String(val), gx + iconSz + ig, aY + aH / 2 + 1);
  });
  const allocBottom = aY + aH;

  // ---- 属性三列（紧凑行距；名称/数值放大）----
  const cols = [
    { title: T('进攻能力'), color: '#fbbf24', list: ATTACK },
    { title: T('防守能力'), color: '#60a5fa', list: DEFENSE },
    { title: T('身体素质'), color: '#34d399', list: POWER },
  ];
  // 三列之间预留固定列间隙，避免相邻列“数值”与下一列“名称”贴在一起造成视觉重叠
  const colGap = 30;
  const colW = (rInnerW - colGap * 2) / 3; // 单列内容宽
  const colX = (ci: number) => rInnerX + ci * (colW + colGap);

  // ---- 球员技能（无标题；排序：ST → 普通 → 新增黄色；ST 用品红标 + Sparkles 图标）----
  const skillH = 44;
  const skillPitch = 52;
  const stIcon = await loadImage(lucideDataUrl('sparkles', '#FF2D95'));
  const regPos = player.position;
  const rawSkills = Array.isArray(player.skills) ? player.skills : [];
  const stNames: string[] = [];
  const normalNames: string[] = [];
  rawSkills.forEach((raw) => {
    const display = normalizeSkillForPlayer(raw, regPos);
    if (isStSkill(display)) stNames.push(display);
    else normalNames.push(display);
  });
  stNames.sort((a, b) => a.localeCompare(b, 'zh'));
  normalNames.sort((a, b) => a.localeCompare(b, 'zh'));
  const toFlow = (display: string, kind: 'st' | 'normal' | 'added'): FlowItem => {
    if (kind === 'st') {
      return {
        text: T(display), fg: '#FF6BB5', bg: 'rgba(255,45,149,0.10)', border: 'rgba(255,45,149,0.50)',
        font: '24px system-ui, sans-serif', h: skillH, padX: 12, iconImg: stIcon, iconSize: 17,
      };
    }
    if (kind === 'added') {
      return {
        text: T(display), fg: '#fde047', bg: 'rgba(250,204,21,0.16)', border: 'rgba(250,204,21,0.6)',
        font: '24px system-ui, sans-serif', h: skillH, padX: 12,
      };
    }
    return {
      text: T(display), fg: '#e2e8f0', bg: 'rgba(255,255,255,0.07)', border: 'rgba(255,255,255,0.17)',
      font: '24px system-ui, sans-serif', h: skillH, padX: 12,
    };
  };
  const skillItems: FlowItem[] = [
    ...stNames.map((n) => toFlow(n, 'st')),
    ...normalNames.map((n) => toFlow(n, 'normal')),
    ...data.extraSkills.map((s) => toFlow(s, 'added')),
  ];

  // 固定紧凑行距：原约 59px，缩小约 30% → 40px；段间统一 1.5 倍行距
  const attrPitch = 40;
  const G = 1.5 * attrPitch;
  const regionBottom = rpY + rpH - 16;
  // 加点行 → 列标题（1.5 倍行距）
  const gridTitleY = allocBottom + G;
  const firstCenter = gridTitleY + 30;
  // 属性 → 技能（1.5 倍行距）
  const attackLastCenter = firstCenter + 9 * attrPitch;
  const skillsFirstCenter = attackLastCenter + 20 + G;
  const skillRows = Math.max(1, countFlowRows(ctx, skillItems, rInnerX, rMaxX, 8));
  const skillsLastCenter = skillsFirstCenter + (skillRows - 1) * skillPitch;
  chipFlow(ctx, skillItems, rInnerX, skillsFirstCenter - skillH / 2, rMaxX, 8, skillPitch);

  cols.forEach((col, ci) => {
    const x0 = colX(ci);
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = col.color;
    ctx.font = 'bold 20px system-ui, sans-serif';
    ctx.fillText(col.title, x0, gridTitleY);
    ctx.strokeStyle = hexToRgba(col.color, 0.35);
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(x0, gridTitleY + 9);
    ctx.lineTo(x0 + colW - 2, gridTitleY + 9);
    ctx.stroke();
    col.list.forEach((e, i) => {
      const v = data.finalAttrValues[e.key];
      if (typeof v !== 'number' || !Number.isFinite(v)) return;
      const ry = firstCenter + i * attrPitch;
      ctx.textBaseline = 'middle';
      ctx.textAlign = 'left';
      ctx.fillStyle = '#dbe3ef';
      ctx.font = '24px system-ui, sans-serif';
      let lab = isEn ? abbrStatEn(T(e.label)) : e.label;
      if (ctx.measureText(lab).width > 150) {
        while (ctx.measureText(`${lab}…`).width > 150 && lab.length > 1) lab = lab.slice(0, -1);
        lab += '…';
      }
      ctx.fillText(lab, x0, ry);
      ctx.fillStyle = valueColor(v);
      ctx.font = 'bold 31px system-ui, sans-serif';
      ctx.textAlign = 'right';
      ctx.fillText(String(Math.round(v)), x0 + colW - 2, ry + 1);
    });
  });

  // ---- 身体素质列：体力（最后一项）下方空白处放小品牌水印（紧凑、无圆）----
  {
    const powerColCenterX = colX(2) + colW / 2;
    const staminaCenterY = firstCenter + 6 * attrPitch;
    const wmScale = 0.62; // 增大一号（与强度榜/阵容水印同档）
    const wmNY = staminaCenterY + 102; // 落在体力与技能之间的空白，不压内容
    // drawBrandWatermark 内部已 ctx.scale 并 ox=cx/scale，故直接传“正常坐标”，不要再乘 scale
    drawBrandWatermark(
      ctx, powerColCenterX, wmNY, iconImg,
      { compact: true, noCircle: true, scale: wmScale },
    );
  }

  // ---- 模型数值：技能下方 1.5 倍行距，单行多格 ----
  {
    const useFields = player.playerModel ? MODEL_FIELDS : SIZE_FIELDS;
    const n = useFields.length;
    const modelH = 66;
    let modelCenter = skillsLastCenter + 24 + G;
    // 防溢出：模型行不得越过面板底
    if (modelCenter + modelH / 2 > regionBottom) modelCenter = regionBottom - modelH / 2;
    const gap = 6;
    const cellW = (rInnerW - (n - 1) * gap) / n;
    useFields.forEach((f, i) => {
      const x0 = rInnerX + i * (cellW + gap);
      let rawVal: unknown;
      if (player.playerModel) {
        const cell = (player.playerModel as Record<string, unknown>)[f.key] as
          | { value?: unknown }
          | undefined;
        rawVal = cell && typeof cell === 'object' && 'value' in cell ? cell.value : cell;
      } else {
        rawVal = (player as unknown as Record<string, unknown>)[f.key];
      }
      const val = rawVal == null ? '--' : String(rawVal);
      roundRect(ctx, x0, modelCenter - modelH / 2, cellW, modelH, 8);
      ctx.fillStyle = 'rgba(255,255,255,0.05)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.12)';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      const cx = x0 + cellW / 2;
      // 标签：中文单行；英文拆两行（长词缩写），并按格宽自适应字号，杜绝相邻格重叠
      let lines: string[];
      if (isEn) {
        const mapped = MODEL_LABEL_EN[f.label];
        if (mapped) {
          lines = mapped.split('\n');
        } else {
          const words = T(f.label).split(/\s+/);
          const mid = Math.ceil(words.length / 2);
          lines = words.length > 1
            ? [words.slice(0, mid).join(' '), words.slice(mid).join(' ')]
            : words;
        }
      } else {
        lines = [f.label];
      }
      const maxLabW = cellW - 8;
      let labSize = 16;
      while (labSize > 11) {
        ctx.font = 'bold ' + labSize + 'px system-ui, sans-serif';
        if (Math.max(...lines.map((l) => ctx.measureText(l).width)) <= maxLabW) break;
        labSize--;
      }
      ctx.fillStyle = '#cbd5e1';
      if (lines.length === 2) {
        ctx.fillText(lines[0], cx, modelCenter - 21);
        ctx.fillText(lines[1], cx, modelCenter - 5);
      } else {
        ctx.font = 'bold 18px system-ui, sans-serif';
        ctx.fillText(lines[0], cx, modelCenter - 15);
      }
      ctx.fillStyle = '#f1f5f9';
      ctx.font = 'bold 23px system-ui, sans-serif';
      ctx.fillText(val, cx, modelCenter + 16);
    });
  }

  // ============================================================
  // 左侧面板：卡面 → 进攻/防守风格胶囊 → 信息胶囊 → 模型数值
  // ============================================================
  drawSolidPanel(ctx, lpX, lpY, lpW, lpH, 20);
  const lPad = 18;
  const lInnerX = lpX + lPad;
  const lInnerW = lpW - lPad * 2;
  const lMaxX = lpX + lpW - lPad;

  // ---- 左侧纵向信息列：年龄 / 身高 / 体重 / 惯用脚（在卡面左边）----
  const infoColW = 74;
  const infoColX = lInnerX;
  const infoColCenterX = infoColX + infoColW / 2;
  // 卡面区域（让出左侧信息列后，卡面整体右移，保持空位居中）
  const cardRegionX = lInnerX + infoColW + 10;
  const cardRegionW = lMaxX - cardRegionX;

  // ---- 卡面（在右侧卡片区内居中）----
  const cardWpx = 248;
  const cardHpx = Math.round(cardWpx * 4 / 3); // 331
  const cardX = cardRegionX + (cardRegionW - cardWpx) / 2;
  const cardY = lpY + 14;
  const cardRadius = 14;
  if (cardImg) {
    ctx.save();
    ctx.beginPath();
    ctx.roundRect(cardX, cardY, cardWpx, cardHpx, cardRadius);
    ctx.clip();
    ctx.drawImage(cardImg, cardX, cardY, cardWpx, cardHpx);
    const tg = ctx.createLinearGradient(0, cardY, 0, cardY + cardHpx);
    tg.addColorStop(0, 'rgba(0,0,0,0.32)');
    tg.addColorStop(0.28, 'rgba(0,0,0,0)');
    tg.addColorStop(0.72, 'rgba(0,0,0,0)');
    tg.addColorStop(1, 'rgba(0,0,0,0.60)');
    ctx.fillStyle = tg;
    ctx.fillRect(cardX, cardY, cardWpx, cardHpx);
    ctx.restore();
  } else {
    ctx.fillStyle = 'rgba(255,255,255,0.06)';
    ctx.beginPath();
    ctx.roundRect(cardX, cardY, cardWpx, cardHpx, cardRadius);
    ctx.fill();
  }
  ctx.strokeStyle = 'rgba(255,255,255,0.14)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.roundRect(cardX, cardY, cardWpx, cardHpx, cardRadius);
  ctx.stroke();

  // ---- 绘制左侧纵向信息列（年龄/身高/体重/惯用脚），与卡面等高均布 ----
  {
    const demoBlocks: { label: string; value: string }[] = [
      { label: '年龄', value: player.age != null ? String(player.age) : '--' },
      { label: '身高', value: player.height != null ? String(player.height) : '--' },
      { label: '体重', value: player.weight != null ? String(player.weight) : '--' },
      { label: '惯用脚', value: player.preferredFoot ?? '--' },
    ];
    const step = cardHpx / demoBlocks.length;
    demoBlocks.forEach((blk, k) => {
      const cy = cardY + (k + 0.5) * step;
      // 分隔小底板
      roundRect(ctx, infoColX, cy - step / 2 + 7, infoColW, step - 14, 10);
      ctx.fillStyle = 'rgba(255,255,255,0.05)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.10)';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px system-ui, sans-serif';
      ctx.fillText(T(blk.label), infoColCenterX, cy - 13);
      ctx.fillStyle = '#f1f5f9';
      ctx.font = 'bold 21px system-ui, sans-serif';
      ctx.fillText(T(blk.value), infoColCenterX, cy + 11);
    });
  }

  // 卡面右上角星标水印（同强度榜卡牌：APP 图标）
  if (iconImg) {
    const wm = 26;
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.9)';
    ctx.shadowBlur = 4;
    ctx.shadowOffsetY = 1;
    ctx.drawImage(iconImg, cardX + cardWpx - wm - 9, cardY + 9, wm, wm);
    ctx.restore();
  }

  // 总评（左上，琥珀）
  const ovr = Math.round(data.overallRating || player.overallRating);
  ctx.textAlign = 'left';
  ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#fcd34d';
  ctx.font = 'bold 42px system-ui, sans-serif';
  ctx.shadowColor = 'rgba(0,0,0,0.75)';
  ctx.shadowBlur = 6;
  ctx.shadowOffsetY = 2;
  ctx.fillText(String(ovr), cardX + 13, cardY + 46);
  ctx.shadowColor = 'transparent';

  // 位置（总评下方青色胶囊）
  const posText = player.position;
  ctx.font = 'bold 16px system-ui, sans-serif';
  const posW = ctx.measureText(posText).width + 19;
  const posY = cardY + 56;
  ctx.fillStyle = 'rgba(34,211,238,0.28)';
  ctx.beginPath();
  ctx.roundRect(cardX + 13, posY, posW, 27, 8);
  ctx.fill();
  ctx.strokeStyle = 'rgba(34,211,238,0.55)';
  ctx.lineWidth = 1.2;
  ctx.stroke();
  ctx.fillStyle = '#cffafe';
  ctx.textBaseline = 'middle';
  ctx.fillText(posText, cardX + 23, posY + 14);

  // 名称（卡面下部居中）
  let nameStr = isEn
    ? (player.nameEn || player.nameZh || 'Player')
    : (player.nameZh || player.nameEn || '球员');
  ctx.textAlign = 'center';
  let nameFont = 21;
  ctx.font = `bold ${nameFont}px system-ui, sans-serif`;
  while (ctx.measureText(nameStr).width > cardWpx - 28 && nameFont > 15) {
    nameFont -= 1;
    ctx.font = `bold ${nameFont}px system-ui, sans-serif`;
  }
  if (ctx.measureText(nameStr).width > cardWpx - 28) {
    while (ctx.measureText(`${nameStr}…`).width > cardWpx - 28 && nameStr.length > 1) {
      nameStr = nameStr.slice(0, -1);
    }
    nameStr += '…';
  }
  ctx.fillStyle = '#ffffff';
  ctx.shadowColor = 'rgba(0,0,0,0.85)';
  ctx.shadowBlur = 5;
  ctx.shadowOffsetY = 1;
  ctx.textBaseline = 'middle';
  ctx.fillText(nameStr, cardX + cardWpx / 2, cardY + cardHpx * 0.86);
  ctx.shadowColor = 'transparent';

  // ---- 进攻 / 防守风格（详情页同款图标胶囊，并排）----
  const spY = cardY + cardHpx + 16;
  const spGap = 10;
  const spW = (lInnerW - spGap) / 2;
  const spH = 44;
  drawStylePill(
    ctx, offIcon, T(offenseStyleDisplay(player.style)),
    lInnerX, spY, spW, spH,
    '#f9a8d4', 'rgba(236,72,153,0.10)', 'rgba(244,115,182,0.35)',
  );
  drawStylePill(
    ctx, defIcon, T(player.defensivePlayStyle || '基础战术'),
    lInnerX + spW + spGap, spY, spW, spH,
    '#6ee7b7', 'rgba(16,185,129,0.10)', 'rgba(52,211,153,0.35)',
  );

  // ---- 行1：逆足频率 / 逆足精度（身高/惯用脚已移到卡面左侧信息列）----
  // 卡面下方胶囊字体统一放大 2 档（20→22）、加高、加宽内边距
  const weakStyle: ChipStyle = {
    fg: '#e2e8f0', bg: 'rgba(255,255,255,0.06)', border: 'rgba(255,255,255,0.16)',
    font: 'bold 22px system-ui, sans-serif', h: 40, padX: 13,
  };
  const baseItems: FlowItem[] = [
    { text: `${T('逆足频率')} ${player.hiddenAttributes?.weakFootFrequency?.level ?? '--'}`, ...weakStyle },
    { text: `${T('逆足精度')} ${player.hiddenAttributes?.weakFootAccuracy?.level ?? '--'}`, ...weakStyle },
  ];
  const row1Bottom = chipFlow(ctx, baseItems, lInnerX, spY + spH + 16, lMaxX, 7, 48);

  // ---- 行2：闪耀 / 第一增能 / 第二增能（同一行，字体放大）----
  const boostItems: FlowItem[] = [];
  if (data.shine) {
    boostItems.push({
      text: T(data.shine.label), fg: '#fbbf24', bg: 'rgba(251,191,36,0.16)', border: 'rgba(251,191,36,0.55)',
      font: 'bold 22px system-ui, sans-serif', h: 40, padX: 13,
    });
  }
  [data.firstBooster, data.secondBooster].forEach((b) => {
    if (!b) return;
    const hex = b.colorHex ?? '#3de3e1';
    boostItems.push({
      text: TBooster(b.label), fg: hex, bg: hexToRgba(hex, 0.17), border: hexToRgba(hex, 0.55),
      font: 'bold 22px system-ui, sans-serif', h: 40, padX: 13,
    });
  });
  const row2Bottom = boostItems.length
    ? chipFlow(ctx, boostItems, lInnerX, row1Bottom + 12, lMaxX, 7, 48)
    : row1Bottom;

  // ---- 行3：教练 + 状态波动（同一行；状态只显示文案，如「稳定」）----
  let row3Bottom = row2Bottom;
  const row3Items: FlowItem[] = [];
  if (data.coach) {
    row3Items.push({
      text: T(data.coach.label), fg: '#fdba74', bg: 'rgba(249,115,22,0.15)',
      border: 'rgba(249,115,22,0.52)', font: 'bold 22px system-ui, sans-serif', h: 40, padX: 13,
    });
  }
  {
    const fcLevel = player.hiddenAttributes?.formConsistency?.level;
    if (typeof fcLevel === 'number') {
      row3Items.push({
        text: T(getFormConsistencyLabel(fcLevel)), fg: '#e2e8f0', bg: 'rgba(255,255,255,0.07)',
        border: 'rgba(255,255,255,0.17)', font: 'bold 22px system-ui, sans-serif', h: 40, padX: 13,
      });
    }
  }
  if (row3Items.length) {
    row3Bottom = chipFlow(ctx, row3Items, lInnerX, row2Bottom + 12, lMaxX, 7, 48);
  }
  const infoBottom = row3Bottom;

  // ---- 适配位置热区图（填满左下角；复刻详情页 3×7 位置网格）----
  interface HeatCell { key: string; row: number; col: number; rowSpan: number; colSpan: number }
  const HEAT_LAYOUT: HeatCell[] = [
    { key: 'LWF', row: 1, col: 1, rowSpan: 2, colSpan: 1 },
    { key: 'CF', row: 1, col: 2, rowSpan: 1, colSpan: 1 },
    { key: 'RWF', row: 1, col: 3, rowSpan: 2, colSpan: 1 },
    { key: 'SS', row: 2, col: 2, rowSpan: 1, colSpan: 1 },
    { key: 'LMF', row: 3, col: 1, rowSpan: 3, colSpan: 1 },
    { key: 'AMF', row: 3, col: 2, rowSpan: 1, colSpan: 1 },
    { key: 'RMF', row: 3, col: 3, rowSpan: 3, colSpan: 1 },
    { key: 'CMF', row: 4, col: 2, rowSpan: 1, colSpan: 1 },
    { key: 'DMF', row: 5, col: 2, rowSpan: 1, colSpan: 1 },
    { key: 'LB', row: 6, col: 1, rowSpan: 2, colSpan: 1 },
    { key: 'CB', row: 6, col: 2, rowSpan: 1, colSpan: 1 },
    { key: 'RB', row: 6, col: 3, rowSpan: 2, colSpan: 1 },
    { key: 'GK', row: 7, col: 2, rowSpan: 1, colSpan: 1 },
  ];
  // 已按需求移除“适配位置”标题文字；热区图直接上移到信息区下方
  const heatTitleY = infoBottom + 8;
  const areaTop = heatTitleY;
  const areaBottom = lpY + lpH - 16;
  const hGap = 4;
  const unitW = (lInnerW - 2 * hGap) / 3;
  const unitH = (areaBottom - areaTop - 6 * hGap) / 7;
  const proficiency = player.positionProficiency ?? {};
  const registeredKey = player.position;
  const heatLevel = (key: string): number => {
    const lv = proficiency[key];
    if (lv === 2) return 2;
    if (lv === 1) return 1;
    if (key === registeredKey) return 2;
    return 0;
  };
  HEAT_LAYOUT.forEach((cell) => {
    const hx = lInnerX + (cell.col - 1) * (unitW + hGap);
    const hy = areaTop + (cell.row - 1) * (unitH + hGap);
    const hw = unitW * cell.colSpan + (cell.colSpan - 1) * hGap;
    const hh = unitH * cell.rowSpan + (cell.rowSpan - 1) * hGap;
    const lv = heatLevel(cell.key);
    const grad = ctx.createLinearGradient(hx, hy, hx + hw, hy + hh);
    let fg = '#94a3b8';
    if (lv === 2) { grad.addColorStop(0, '#22c55e'); grad.addColorStop(1, '#16a34a'); fg = '#ffffff'; }
    else if (lv === 1) { grad.addColorStop(0, '#B0D4E8'); grad.addColorStop(1, '#8FC1D9'); fg = '#0f172a'; }
    else { grad.addColorStop(0, '#1e293b'); grad.addColorStop(1, '#334155'); fg = '#94a3b8'; }
    ctx.beginPath();
    ctx.roundRect(hx, hy, hw, hh, 6);
    ctx.fillStyle = grad;
    ctx.fill();
    const isReg = cell.key === registeredKey;
    if (isReg) {
      ctx.strokeStyle = '#fbbf24';
      ctx.lineWidth = 2;
      ctx.save();
      ctx.shadowColor = 'rgba(251,191,36,0.7)';
      ctx.shadowBlur = 8;
      ctx.stroke();
      ctx.restore();
    } else {
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
    ctx.fillStyle = fg;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = `bold ${cell.rowSpan > 1 ? 14 : 13}px system-ui, sans-serif`;
    ctx.fillText(cell.key, hx + hw / 2, hy + hh / 2 + 1);
  });

  return canvas;
}
