import * as React from 'react';

/**
 * 「滑屏加点」开关（手机竖屏：在加点卡片上左右滑动即可加/减点）。
 *
 * 持久化在 localStorage，默认开启；设置页可关。开关变化通过自定义事件
 * 'pts:slidepoints-changed' 通知同页面内的组件，'storage' 事件覆盖跨标签。
 * 纯前端偏好，与语言、账号无关。
 */
const KEY = 'pts.slidePoints';
const EVENT = 'pts:slidepoints-changed';

function read(): boolean {
  try {
    // 未设置（null）时默认开启；仅显式存 '0' 才关闭
    return localStorage.getItem(KEY) !== '0';
  } catch {
    return true;
  }
}

export function setSlidePointsEnabled(enabled: boolean): void {
  try {
    localStorage.setItem(KEY, enabled ? '1' : '0');
  } catch {
    /* ignore */
  }
  try {
    window.dispatchEvent(new Event(EVENT));
  } catch {
    /* ignore */
  }
}

/** 读取当前滑屏加点是否开启，并在开关变化时自动更新。 */
export function useSlidePoints(): [boolean, (enabled: boolean) => void] {
  const [enabled, setEnabled] = React.useState<boolean>(read);

  React.useEffect(() => {
    const onChange = () => setEnabled(read());
    setEnabled(read());
    window.addEventListener(EVENT, onChange);
    window.addEventListener('storage', onChange);
    return () => {
      window.removeEventListener(EVENT, onChange);
      window.removeEventListener('storage', onChange);
    };
  }, []);

  const update = React.useCallback((v: boolean) => {
    setSlidePointsEnabled(v);
  }, []);

  return [enabled, update];
}
