import type { TierListPayload } from '@client/src/api/tier-lists';
import { resolvePlayerCardImage } from '@client/src/utils/player-card-url';
import { LOCAL_ASSETS, loadFirstImage } from '@client/src/utils/local-assets';
import { ICON_DATA_URI } from '@client/src/utils/brand-icon-data';
import { drawBrandWatermark } from '@client/src/utils/brand-watermark';

function viaProxy(src: string): string {
  try {
    const u = new URL(src);
    if (u.host.endsWith('myqcloud.com')) {
      return `https://playtostar.com/cosimg${u.pathname}`;
    }
  } catch {
    /* 非绝对地址，原样返回 */
  }
  return src;
}

const BANNER_URL =
  'https://efootballpsbete-1488358463.cos.ap-shanghai.myqcloud.com/EF20270916/EF2027/banner/banner.png';

function loadImage(src: string): Promise<HTMLImageElement | null> {
  return new Promise((resolve) => {
    if (!src) {
      resolve(null);
      return;
    }
    const img = new Image();
    img.crossOrigin = 'anonymous';
    let done = false;
    const timer = setTimeout(() => {
      if (!done) {
        done = true;
        resolve(null);
      }
    }, 7000);
    img.onload = () => {
      if (!done) {
        done = true;
        clearTimeout(timer);
        resolve(img);
      }
    };
    img.onerror = () => {
      if (!done) {
        done = true;
        clearTimeout(timer);
        resolve(null);
      }
    };
    img.src = src;
  });
}

function roundRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
): void {
  // 关键：每次都先开启全新子路径。原生 ctx.roundRect 只会把矩形“追加”到当前
  // 路径，若不 beginPath，后续每次 fill() 都会把之前所有矩形重填一遍，
  // 导致后画的层级颜色/文字覆盖前面所有层级。
  ctx.beginPath();
  const rr = (ctx as any).roundRect;
  if (rr) {
    rr.call(ctx, x, y, w, h, r);
    return;
  }
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function drawContain(
  ctx: CanvasRenderingContext2D,
  img: HTMLImageElement,
  x: number,
  y: number,
  w: number,
  h: number,
): void {
  const scale = Math.min(w / img.width, h / img.height);
  const dw = img.width * scale;
  const dh = img.height * scale;
  ctx.drawImage(img, x + (w - dw) / 2, y + (h - dh) / 2, dw, dh);
}

export async function renderTierListCanvas(
  payload: TierListPayload,
): Promise<HTMLCanvasElement> {
  const W = 1080;
  const pad = 26;
  const titleH = 140;
  const labelW = 132;
  const cardW = 168;
  const cardH = Math.round(cardW * (4 / 3));
  const gap = 14;
  const areaX = pad + labelW + gap;
  const areaW = W - pad - areaX;
  const perRow = Math.max(1, Math.floor((areaW + gap) / (cardW + gap)));

  // 预加载全部球员卡图（小图优先，失败回退大图）
  const all = payload.tiers.flatMap((t) => payload.items[t.id] ?? []);
  const iconImg = await loadFirstImage([...LOCAL_ASSETS.iconCandidates, ICON_DATA_URI]);
  const bgImg = await loadImage(viaProxy(BANNER_URL));
  const imgMap = new Map<string, HTMLImageElement | null>();
  await Promise.all(
    all.map(async (item) => {
      if (imgMap.has(item.playerId)) return;
      // 小图目录实测普遍 404，直接用大图（经同源代理）
      const im = await loadImage(
        viaProxy(resolvePlayerCardImage(item.playerImageUrl, item.playerId)),
      );
      imgMap.set(item.playerId, im);
    }),
  );

  // 计算每层高度
  const layout = payload.tiers.map((t) => {
    const n = (payload.items[t.id] ?? []).length;
    const rows = Math.max(1, Math.ceil(n / perRow));
    const contentH = n === 0 ? 96 : rows * cardH + (rows + 1) * gap;
    return { tier: t, items: payload.items[t.id] ?? [], h: Math.max(150, contentH) };
  });

  const H = titleH + layout.reduce((s, l) => s + l.h + gap, 0) + pad + 40;
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d')!;

  // 背景：深色渐变打底（与球员分享图一致）
  const bg = ctx.createLinearGradient(0, 0, W, H);
  bg.addColorStop(0, '#0a0f2e');
  bg.addColorStop(0.55, '#0c1338');
  bg.addColorStop(1, '#141a4a');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  // 主视觉图（cover）+ 压暗
  if (bgImg) {
    const ir = bgImg.width / bgImg.height;
    let dw = W;
    let dh = W / ir;
    let dx = 0;
    let dy = (H - dh) / 2;
    if (dh < H) { dh = H; dw = H * ir; dx = (W - dw) / 2; dy = 0; }
    ctx.drawImage(bgImg, dx, dy, dw, dh);
    ctx.fillStyle = 'rgba(7,10,28,0.66)';
    ctx.fillRect(0, 0, W, H);
  }

  // 斜向渐变条纹
  ctx.save();
  ctx.strokeStyle = 'rgba(255,255,255,0.055)';
  ctx.lineWidth = 2;
  for (let d = -H; d < W; d += 84) {
    ctx.beginPath();
    ctx.moveTo(d, H);
    ctx.lineTo(d + H, 0);
    ctx.stroke();
  }
  ctx.restore();

  // 标题
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 50px system-ui, sans-serif';
  ctx.textBaseline = 'alphabetic';
  ctx.fillText(payload.name || '我的强度榜', pad, 66);
  ctx.fillStyle = '#22e5ff';
  ctx.font = '24px system-ui, sans-serif';
  ctx.fillText('绘制源自 PlayToStar APP', pad, 100);
  // 免责申明：紧随来源行之后，置于左上方
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  ctx.font = '19px system-ui, sans-serif';
  ctx.fillText('卡面版权归 KONAMI 所有 · 本图仅用于学习交流，禁止商业用途', pad, 128);

  let y = titleH;
  for (const l of layout) {
    // 层级标签
    ctx.fillStyle = l.tier.color;
    roundRect(ctx, pad, y, labelW, l.h, 14);
    ctx.fill();
    ctx.fillStyle = '#ffffff';
    const fs = l.tier.name.length > 4 ? 26 : l.tier.name.length > 2 ? 32 : 44;
    ctx.font = `bold ${fs}px system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    // 长名称换行
    if (l.tier.name.length > 4) {
      ctx.fillText(l.tier.name.slice(0, 4), pad + labelW / 2, y + l.h / 2 - 16);
      ctx.fillText(l.tier.name.slice(4), pad + labelW / 2, y + l.h / 2 + 16);
    } else {
      ctx.fillText(l.tier.name, pad + labelW / 2, y + l.h / 2);
    }
    ctx.textAlign = 'left';

    // 卡片区底
    ctx.fillStyle = 'rgba(255,255,255,0.045)';
    roundRect(ctx, areaX, y, areaW, l.h, 14);
    ctx.fill();

    // 空层级：导出图不绘制“把球员拖到这里”等任何提示文字，仅保留空白卡区

    l.items.forEach((item, i) => {
      const col = i % perRow;
      const row = Math.floor(i / perRow);
      const cx = areaX + gap + col * (cardW + gap);
      const cy = y + gap + row * (cardH + gap);

      // 卡底
      const cg = ctx.createLinearGradient(cx, cy, cx, cy + cardH);
      cg.addColorStop(0, '#161d3d');
      cg.addColorStop(1, '#10162f');
      ctx.fillStyle = cg;
      roundRect(ctx, cx, cy, cardW, cardH, 10);
      ctx.fill();

      const im = imgMap.get(item.playerId) ?? null;
      if (im) {
        drawContain(ctx, im, cx + 4, cy + 4, cardW - 8, cardH - 12);
      } else {
        ctx.fillStyle = 'rgba(255,255,255,0.45)';
        ctx.font = 'bold 46px system-ui, sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(
          item.nameZh?.charAt(0) || item.nameEn?.charAt(0) || '?',
          cx + cardW / 2,
          cy + cardH / 2 - 14,
        );
        ctx.textAlign = 'left';
      }

      // 球员名：位置与字号对齐“本尺寸卡牌标准”（约 80% 处、字号 16），深色药丸衬底
      const nm = item.nameZh || item.nameEn || '';
      const showNm = nm.length > 8 ? `${nm.slice(0, 8)}…` : nm;
      ctx.font = 'bold 16px system-ui, sans-serif';
      const nameCy = cy + cardH * 0.8;
      const tw = ctx.measureText(showNm).width;
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      roundRect(ctx, cx + cardW / 2 - tw / 2 - 8, nameCy - 12, tw + 16, 24, 8);
      ctx.fill();
      ctx.fillStyle = '#ffffff';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(showNm, cx + cardW / 2, nameCy);
      ctx.textAlign = 'left';

      // 水印
      if (iconImg) {
        const ws = 26;
        ctx.drawImage(iconImg, cx + cardW - ws - 5, cy + 5, ws, ws);
      }
    });

    y += l.h + gap;
  }

  // ===== 品牌水印（右上方；浅灰 + 行楷、无圆形底纹；统一走 drawBrandWatermark）=====
  drawBrandWatermark(ctx, W - 118, 82, iconImg, { scale: 0.62, noCircle: true });
  ctx.textAlign = 'left';
  ctx.textBaseline = 'alphabetic';

  return canvas;
}
