// 路由路径工具：处理子路径部署（basename=/efootball）下的路径换算。
// window.location.pathname 是含 basename 的“完整路径”，而 react-router 的
// navigate(to) 会在 to 前再拼一次 basename；若直接把完整路径传给 navigate，
// 会出现 /efootball/efootball/... 的双重前缀。故需先剥离 basename。

// 规范化 basename：去尾斜杠；相对 base “.” 与占位符一律按根 “/” 处理
const normalizeBase = (raw: string): string => {
  const t = raw.replace(/\/+$/, '');
  if (!t || t === '.' || t.includes('{{')) return '/';
  return t;
};

export const getBasename = (): string => {
  // 1) index.html / 入口回写的 window.__BASENAME__
  const b =
    typeof window !== 'undefined'
      ? (window as unknown as { __BASENAME__?: string }).__BASENAME__
      : undefined;
  if (typeof b === 'string' && b && !b.includes('{{')) return normalizeBase(b);
  // 2) vite 构建注入的 BASE_URL —— 必须与 index.tsx 中 BrowserRouter 的 basename 同源，
  //    否则 getBasename 误判为 “/” 不剥离前缀，navigate 会拼出双前缀导致 404。
  const vite =
    typeof import.meta !== 'undefined'
      ? (import.meta as unknown as { env?: { BASE_URL?: string } }).env?.BASE_URL
      : undefined;
  if (typeof vite === 'string' && vite) return normalizeBase(vite);
  return '/';
};

// 完整 pathname（含 basename）→ react-router navigate 可用的路径（相对 basename）
export const toRouterPath = (fullPath: string): string => {
  const base = getBasename();
  if (base && base !== '/') {
    if (fullPath === base) return '/';
    if (fullPath.startsWith(base + '/')) return fullPath.slice(base.length) || '/';
    if (fullPath.startsWith(base)) {
      const rest = fullPath.slice(base.length);
      return rest.startsWith('/') ? rest : '/' + rest;
    }
  }
  return fullPath;
};
