/**
 * 全平台统一颜色规则（唯一事实来源）
 * 适用：APP（安卓）、网页（横屏/竖屏）、Canvas 产出的分享图。
 * 所有“进攻/防守风格”“增能胶囊”的颜色都必须从这里取，禁止各处各写一套。
 */

// ─────────────────────────────────────────────────────────
// 一、进攻风格：粉色
// ─────────────────────────────────────────────────────────
export const ATTACK_STYLE = {
  hex: '#f472b6', // 描边/图标（pink-400）
  text: '#f9a8d4', // 文字（pink-300）
  cls: 'bg-pink-500/10 text-pink-300 border-pink-400/30',
};

// ─────────────────────────────────────────────────────────
// 二、防守风格：翠绿色
// ─────────────────────────────────────────────────────────
export const DEFENSE_STYLE = {
  hex: '#34d399', // emerald-400
  text: '#6ee7b7', // emerald-300
  cls: 'bg-emerald-500/10 text-emerald-300 border-emerald-400/30',
};

// ─────────────────────────────────────────────────────────
// 三、增能（Booster）颜色
// 键名沿用旧称呼以兼容静态数据，但“蓝”在新规则里表示【常规青色】
// ─────────────────────────────────────────────────────────
export type BoosterColorKey = '蓝' | '黄' | '橙' | '紫' | '绿' | '灰' | '品红';

export interface BoosterUiColor {
  bg: string;
  border: string;
  text: string;
  glow: string;
  hex: string;
}

export const BOOSTER_COLOR_MAP: Record<string, BoosterUiColor> = {
  // 常规 +4（含）以下、非状态火热 → 青色（图3）
  '蓝': {
    bg: 'bg-[#3de3e1]/15', border: 'border-[#3de3e1]/50',
    text: 'text-[#7df0ee]', glow: 'shadow-[0_0_10px_rgba(61_227_225_0.35)]', hex: '#3de3e1',
  },
  // 单属性增能（通常 +6/+8）→ 黄色
  '黄': {
    bg: 'bg-yellow-400/15', border: 'border-yellow-400/50',
    text: 'text-yellow-300', glow: 'shadow-[0_0_10px_rgba(250_204_21_0.4)]', hex: '#facc15',
  },
  // 全属性增加 → 橙色
  '橙': {
    bg: 'bg-orange-500/15', border: 'border-orange-400/50',
    text: 'text-orange-300', glow: 'shadow-[0_0_10px_rgba(249_115_22_0.4)]', hex: '#f97316',
  },
  // 指定名称的传奇增能 → 紫色
  '紫': {
    bg: 'bg-purple-500/15', border: 'border-purple-400/50',
    text: 'text-purple-300', glow: 'shadow-[0_0_10px_rgba(168_85_247_0.4)]', hex: '#a855f7',
  },
  // 状态火热球员（player_type='传奇'）的增能 → 绿色
  '绿': {
    bg: 'bg-green-500/15', border: 'border-green-400/50',
    text: 'text-green-300', glow: 'shadow-[0_0_10px_rgba(34_197_94_0.4)]', hex: '#22c55e',
  },
  '灰': {
    bg: 'bg-slate-500/15', border: 'border-slate-400/50',
    text: 'text-slate-300', glow: '', hex: '#94a3b8',
  },
  // 兼容保留（新规则不再产出品红；单属性 +8 归黄）
  '品红': {
    bg: 'bg-fuchsia-500/15', border: 'border-fuchsia-400/50',
    text: 'text-fuchsia-300', glow: 'shadow-[0_0_10px_rgba(217_70_239_0.5)]', hex: '#d946ef',
  },
};

// 紫色特殊增能名（精确匹配，已剥离 +N）
export const PURPLE_BOOSTER_NAMES = new Set<string>([
  '王者风范', '小王子', '足球之王', '天选之子',
  '全村的希望', '舞王', '球员', '神锋',
]);

export interface BoosterColorInput {
  /** 增能中文名，已剥离结尾的 +N */
  name: string;
  /** 作用能力条数（bonusDetail 解析） */
  abilityCount: number;
  /** 加成数值，如 1/3/4/6/8 */
  level: number;
  /** 是否“全面提升/全属性” */
  isTotal: boolean;
  /** 所属球员的 player_type；'传奇' 在本库即“状态火热” */
  playerType?: string | null;
}

/**
 * 计算增能颜色键。优先级：
 *   紫色特殊名 → 全属性橙 → 状态火热绿 → 单属性大值黄 → 常规青
 */
export function resolveBoosterColorKey(i: BoosterColorInput): BoosterColorKey {
  if (PURPLE_BOOSTER_NAMES.has(i.name)) return '紫';
  if (i.isTotal || i.abilityCount > 10) return '橙';
  if (i.playerType === '传奇') return '绿';
  if (i.abilityCount === 1 && i.level >= 6) return '黄';
  return '蓝';
}

export function resolveBoosterHex(i: BoosterColorInput): string {
  return BOOSTER_COLOR_MAP[resolveBoosterColorKey(i)]?.hex ?? '#3de3e1';
}
