export function getMissingRecommendedSkills(
  registeredPositions: string[],
  ownedSkills: string[],
): Record<'1' | '2' | '3', string[]> {
  // 已拥有技能先做别名归一（双触/双触过人 视同 两次触球），再与推荐标准名比对
  const ownedSet = new Set(ownedSkills.map((s) => normalizeCommonSkillName(s)));
  const bestLevel = new Map<string, number>();

  for (const pos of registeredPositions) {
    const posData = RECOMMENDED_SKILLS_BY_POSITION[pos];
    if (!posData) continue;
    for (const level of ['1', '2', '3'] as const) {
      const lvlNum = Number(level);
      for (const skill of posData[level]) {
        const current = bestLevel.get(skill);
        if (current === undefined || lvlNum < current) {
          bestLevel.set(skill, lvlNum);
        }
      }
    }
  }

  const result: Record<'1' | '2' | '3', string[]> = { '1': [], '2': [], '3': [] };
  for (const [skill, level] of bestLevel) {
    if (ownedSet.has(skill)) continue;
    const key = String(level) as '1' | '2' | '3';
    result[key].push(skill);
  }
  return result;
}
