export async function create(
  dto: CreateCommentDto,
  headers?: Record<string, string>,
): Promise<CommentItem> {
  try {
    const response = await axiosForBackend.post<CommentItem>(
      '/api/comments',
      dto,
      { headers },
    );
    return response.data;
  } catch (error) {
    logger.error('发表评论失败', error);
    throw error;
  }
}

