import React, { useMemo, useState } from 'react';
import { ChevronDown, ChevronUp } from 'lucide-react';
import ReactECharts from 'echarts-for-react';
import * as echarts from 'echarts/core';
import { RadarComponent, TooltipComponent } from 'echarts/components';
import { RadarChart } from 'echarts/charts';
import { CanvasRenderer } from 'echarts/renderers';
import type { EChartsOption } from 'echarts';
import { getAttrHexColor } from '@client/src/utils/attr-color';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';

echarts.use([RadarComponent, TooltipComponent, RadarChart, CanvasRenderer]);

interface RadarChartProps {
  radarStats: Record<string, number>;
  finalAttrValues: Record<string, number>;
  isGK: boolean;
  compact?: boolean;
}

interface IndicatorDef {
  key: string;
  name: string;
}

// 12 点方向顺时针：进攻、射门、对抗、制空、防守、速度、盘带、传球
const OUT_FIELD_INDICATORS: IndicatorDef[] = [
  { key: 'attack', name: '进攻' },
  { key: 'shooting', name: '射门' },
  { key: 'physical', name: '对抗' },
  { key: 'aerial', name: '制空' },
  { key: 'defending', name: '防守' },
  { key: 'speed', name: '速度' },
  { key: 'dribbling', name: '盘带' },
  { key: 'passing', name: '传球' },
];

const GK_INDICATORS: IndicatorDef[] = [
  { key: 'gkAwareness', name: '守门员意识' },
  { key: 'gkCatching', name: '接球能力' },
  { key: 'gkReflexes', name: '扑救反应' },
  { key: 'gkClearing', name: '守门员扑救' },
  { key: 'gkReach', name: '守门员臂展' },
];

const RADAR_KEY: Record<string, string> = {
  attack: 'radar.attacking', passing: 'radar.passing', shooting: 'radar.shooting',
  dribbling: 'radar.dribbling', speed: 'radar.speed', defending: 'radar.defending',
  aerial: 'radar.aerial', physical: 'radar.physicality',
};

const RadarChartComp: React.FC<RadarChartProps> = ({ radarStats, isGK, compact = false }) => {
  const [radarOpen, setRadarOpen] = useState(true);
  const { t, lang } = useI18n();
  const dispName = (item: IndicatorDef): string => {
    if (lang !== 'en') return item.name;
    if (isGK) return trTerm(item.name);
    return t(RADAR_KEY[item.key] ?? item.name);
  };
  const option = useMemo<EChartsOption>(() => {
    const indicators = isGK ? GK_INDICATORS : OUT_FIELD_INDICATORS;
    const values = indicators.map((item) => radarStats?.[item.key] ?? 40);
    const indicatorList = indicators.map((item, idx) => ({
      name: `{name${idx}|${dispName(item)}} {val${idx}|${Math.round(values[idx])}}`,
      max: 100,
      min: 40,
    }));

    const richStyles: Record<string, { color: string; fontSize?: number; fontWeight?: number; lineHeight?: number; padding?: number[] }> = {};
    indicators.forEach((item, idx) => {
      const v = values[idx];
       richStyles[`name${idx}`] = {
         color: '#cbd5e1',
         fontSize: 16,
         fontWeight: 500,
         lineHeight: 22,
         padding: [0, 4, 0, 0],
       };
       richStyles[`val${idx}`] = {
         color: getAttrHexColor(v),
         fontSize: 19,
         fontWeight: 700,
         lineHeight: 22,
       };
    });

    return {
      tooltip: {
        trigger: 'item',
        backgroundColor: 'rgba(15, 23, 42, 0.95)',
        borderColor: 'rgba(255, 255, 255, 0.15)',
        borderWidth: 1,
        textStyle: {
          color: '#e2e8f0',
          fontSize: 12,
        },
        confine: true,
        padding: [10, 14],
        formatter: (params: any) => {
          const dataValues: number[] = params?.value || [];
          const title = lang === 'en'
            ? (isGK ? 'GK Radar' : 'Ability Radar')
            : (isGK ? '门将五维' : '八维能力');
          let html = `<div style="font-weight:600;font-size:13px;color:#fff;margin-bottom:6px;">${title}</div>`;
          html += `<div style="display:flex;flex-direction:column;gap:4px;min-width:140px;">`;
          indicators.forEach((item, idx) => {
             const v = dataValues[idx] ?? radarStats?.[item.key] ?? 0;
            const color = getAttrHexColor(v);
            html += `<div style="display:flex;justify-content:space-between;align-items:center;gap:16px;">`;
            html += `<span style="color:#cbd5e1;">${dispName(item)}</span>`;
            html += `<span style="color:${color};font-weight:700;">${v.toFixed(1)}</span>`;
            html += `</div>`;
          });
          html += `</div>`;
          return html;
        },
      },
      radar: {
        indicator: indicatorList,
        shape: 'polygon',
        splitNumber: 4,
        axisName: {
          rich: richStyles,
          textAlign: 'center',
        },
        splitLine: {
          lineStyle: {
            color: 'rgba(255, 255, 255, 0.08)',
          },
        },
        splitArea: {
          show: true,
          areaStyle: {
            color: [
              'rgba(0, 229, 255, 0.015)',
              'rgba(0, 229, 255, 0.03)',
              'rgba(255, 45, 149, 0.025)',
              'rgba(255, 45, 149, 0.04)',
            ],
          },
        },
        axisLine: {
          lineStyle: {
            color: 'rgba(255, 255, 255, 0.12)',
          },
        },
        center: ['50%', '52%'],
        radius: '55%',
      },
      series: [
        {
          type: 'radar',
          symbol: 'none',
          data: [
            {
              value: values,
              name: lang === 'en' ? 'Ability' : '能力值',
              areaStyle: {
                color: new echarts.graphic.LinearGradient(0, 0, 1, 1, [
                  { offset: 0, color: 'rgba(0, 229, 255, 0.45)' },
                  { offset: 0.5, color: 'rgba(139, 92, 246, 0.35)' },
                  { offset: 1, color: 'rgba(255, 45, 149, 0.4)' },
                ]),
              },
              lineStyle: {
                color: '#00E5FF',
                width: 3.5,
                shadowColor: 'rgba(0, 229, 255, 0.6)',
                shadowBlur: 10,
              },
              itemStyle: {
                color: '#FF2D95',
                borderColor: '#fff',
                borderWidth: 1,
                shadowColor: 'rgba(255, 45, 149, 0.8)',
                shadowBlur: 6,
              },
            },
          ],
        },
      ],
    };
  }, [radarStats, isGK, lang]);

  if (compact) {
    return (
      <div className="rounded-xl bg-card/80 border border-white/10 backdrop-blur overflow-hidden">
        <button
          onClick={() => setRadarOpen(!radarOpen)}
          className="w-full flex items-center justify-between px-2 py-1 hover:bg-white/5 transition-colors"
        >
          <div className="flex items-center gap-2">
            <span className="w-1 h-4 bg-neon-gradient rounded-full" />
            <h2 className="text-sm font-bold text-white">
              {isGK ? (lang === 'en' ? 'GK Ability Radar' : '门将五维能力') : (lang === 'en' ? 'Ability Radar' : '八维能力')}
            </h2>
            <span className="text-[11px] text-gray-500 font-mono">{lang === 'en' ? 'Overall Ability Radar' : '综合能力评估雷达图'}</span>
          </div>
          {radarOpen ? (
            <ChevronUp className="w-4 h-4 text-gray-400" />
          ) : (
            <ChevronDown className="w-4 h-4 text-gray-400" />
          )}
        </button>
        <div
          className={`transition-all duration-300 ease-in-out overflow-hidden ${
            radarOpen ? 'max-h-[600px] opacity-100' : 'max-h-0 opacity-0'
          }`}
        >
          <div className="px-2 pb-2">
            <ReactECharts option={option} className="h-[280px] w-full" notMerge lazyUpdate />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="rounded-2xl bg-card/80 border border-white/10 backdrop-blur overflow-hidden">
      <button
        onClick={() => setRadarOpen(!radarOpen)}
        className="w-full flex items-center justify-between px-5 py-3 hover:bg-white/5 transition-colors"
      >
        <div className="flex items-center gap-2">
          <span className="w-1 h-5 bg-neon-gradient rounded-full" />
           <h2 className="text-4xl md:text-xl font-bold text-white">
              {isGK ? (lang === 'en' ? 'GK Ability Radar' : '门将五维能力') : (lang === 'en' ? 'Ability Radar' : '八维能力')}
            </h2>
            <span className="text-lg text-gray-500 font-mono">{lang === 'en' ? 'Overall Ability Radar' : '综合能力评估雷达图'}</span>
        </div>
        {radarOpen ? (
          <ChevronUp className="w-4 h-4 text-gray-400" />
        ) : (
          <ChevronDown className="w-4 h-4 text-gray-400" />
        )}
      </button>
      <div
        className={`transition-all duration-300 ease-in-out overflow-hidden ${
          radarOpen ? 'max-h-[600px] opacity-100' : 'max-h-0 opacity-0'
        }`}
      >
        <div className="px-5 pb-5">
          <ReactECharts
            option={option}
             className="h-[360px] w-full"
            notMerge
            lazyUpdate
          />
        </div>
      </div>
    </div>
  );
};

export default RadarChartComp;
