import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';
import { AxiosHeaders } from 'axios';
import { runtimeConfig } from '@client/src/utils/config';
import type {
  RegisterRequest,
  LoginRequest,
  AuthResponse,
  UserInfo,
  AccountBindingInfo,
  WeappLoginResponse,
  WechatWebAuthorizeResponse,
} from '@shared/api.interface';

const TOKEN_KEY = 'pes_auth_token';

function setupAxiosAuthInterceptor(): void {
  if (typeof window === 'undefined') return;
  axiosForBackend.interceptors.request.use(
    (config) => {
      const token = window.localStorage.getItem(TOKEN_KEY);
      if (token && !config.headers?.Authorization) {
        if (!config.headers) config.headers = new AxiosHeaders();
        config.headers.set('Authorization', `Bearer ${token}`);
      }
      return config;
    },
    (error) => Promise.reject(error),
  );
}

setupAxiosAuthInterceptor();

export function getToken(): string {
  if (typeof window === 'undefined') return '';
  return window.localStorage.getItem(TOKEN_KEY) || '';
}

export function setToken(token: string): void {
  window.localStorage.setItem(TOKEN_KEY, token);
}

export function clearToken(): void {
  window.localStorage.removeItem(TOKEN_KEY);
}

export async function register(data: RegisterRequest): Promise<AuthResponse> {
  const res = await axiosForBackend.post('/api/auth/register', data);
  return res.data;
}

export async function login(data: LoginRequest): Promise<AuthResponse> {
  const res = await axiosForBackend.post('/api/auth/login', data);
  return res.data;
}

export async function fetchMe(): Promise<UserInfo | null> {
  const token = getToken();
  const headers = token ? { Authorization: `Bearer ${token}` } : undefined;
  const res = await axiosForBackend.get('/api/auth/me', headers ? { headers } : {});
  return res.data || null;
}

export async function getCurrentUser(): Promise<UserInfo | null> {
  try {
    const user = await fetchMe();
    return user || null;
  } catch {
    const token = getToken();
    if (token) clearToken();
    return null;
  }
}

export async function deactivate(password: string): Promise<void> {
  const token = getToken();
  if (!token) throw new Error('未登录');
  await axiosForBackend.post('/api/auth/deactivate', { password }, {
    headers: { Authorization: `Bearer ${token}` },
  });
  clearToken();
}

export async function getBindingInfo(): Promise<AccountBindingInfo> {
  const res = await axiosForBackend.get('/api/auth/binding');
  return res.data;
}

export async function wechatWebLogin(code: string): Promise<WeappLoginResponse> {
  const res = await axiosForBackend.post('/api/auth/wechat-web', { code });
  return res.data;
}

export async function wechatMobileLogin(code: string): Promise<WeappLoginResponse> {
  const res = await axiosForBackend.post('/api/auth/wechat-mobile', { code });
  return res.data;
}

export async function wechatMobileLoginNative(code: string): Promise<WeappLoginResponse> {
  // 兜底直接写自有后端：APP 内即使 runtime-config/index.html 被缓存成旧版，也不会回退到设备自身源
  const baseUrl = runtimeConfig.API_BASE_URL || 'https://playtostar.com';
  const url = `${baseUrl}/api/auth/wechat-mobile`;
  const res = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ code }),
  });
  if (!res.ok) {
    let message = '登录失败，请重试';
    try {
      const data = await res.json();
      if (data?.message) message = data.message;
    } catch {
      // ignore parse error
    }
    throw new Error(message);
  }
  return res.json();
}

export function logout(): void {
  clearToken();
}

/**
 * APP 内微信「网站应用」网页授权：向自有后端换取带签名 state 的微信授权 URL。
 * 直连自有基址，避免 index.html 被缓存成旧版导致回退到设备自身源。
 */
export async function wechatWebAuthorizeNative(): Promise<WechatWebAuthorizeResponse> {
  const baseUrl = runtimeConfig.API_BASE_URL || 'https://playtostar.com';
  const res = await fetch(`${baseUrl}/api/auth/wechat-web/authorize?client=app`, {
    headers: { Accept: 'application/json' },
  });
  if (!res.ok) {
    throw new Error('获取微信授权地址失败，请稍后重试');
  }
  return res.json();
}

/**
 * APP 内网页授权：用微信一次性 code 换业务 JWT（直连自有基址版）。
 * code 约 5 分钟内一次性有效；AppSecret 只在服务端，这里只传 code。
 */
export async function wechatWebLoginNative(code: string): Promise<WeappLoginResponse> {
  const baseUrl = runtimeConfig.API_BASE_URL || 'https://playtostar.com';
  const res = await fetch(`${baseUrl}/api/auth/wechat-web`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ code }),
  });
  if (!res.ok) {
    let message = '登录失败，请重试';
    try {
      const data = await res.json();
      if (data?.message) message = data.message;
    } catch {
      // ignore parse error
    }
    throw new Error(message);
  }
  return res.json();
}

/**
 * Sign in with Apple（iOS 原生 / 网页 JS 共用后端）。
 * 把客户端拿到的 identityToken 发往后端验签，换取业务 JWT。
 * 直连自有基址，避免 index.html 缓存回退。
 */
export async function appleLoginNative(input: {
  identityToken: string;
  userName?: { name?: string; email?: string } | null;
}): Promise<AuthResponse> {
  const baseUrl = runtimeConfig.API_BASE_URL || 'https://playtostar.com';
  const res = await fetch(`${baseUrl}/api/auth/apple`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      identityToken: input.identityToken,
      userName: input.userName ?? null,
    }),
  });
  if (!res.ok) {
    let message = 'Apple 登录失败，请重试';
    try {
      const data = await res.json();
      if (data?.message) message = data.message;
    } catch {
      // ignore parse error
    }
    throw new Error(message);
  }
  return res.json();
}
