import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  User as UserIcon,
  Settings,
  Star,
  Trophy,
  AlertTriangle,
  ArrowLeft,
  FileText,
  ShieldCheck,
  ChevronRight,
  MessageCircle,
  Smartphone,
  RefreshCw,
  Hand,
  Ban,
} from 'lucide-react';
import { useAuth } from '@client/src/context/AuthContext';
import { useI18n, I18N_ENABLED } from '@client/src/i18n/I18nProvider';
import { useSlidePoints } from '@client/src/hooks/use-slide-points';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { toast } from 'sonner';
import { showConfirm } from '@lark-apaas/client-toolkit';
import AvatarUpload from '@client/src/components/ui/avatar-upload';
import { getBindingInfo } from '@client/src/api/auth';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@client/src/components/ui/dialog';
import { Button } from '@client/src/components/ui/button';
import { Input } from '@client/src/components/ui/input';
import { Loader2 } from 'lucide-react';

const SettingsPage: React.FC = () => {
  const navigate = useNavigate();
  const { t, lang, setLang } = useI18n();
  const [slideOn, setSlideOn] = useSlidePoints();
  const { user, deactivate } = useAuth();

  const [deactivateDialogOpen, setDeactivateDialogOpen] = useState(false);
  const [deactivatePassword, setDeactivatePassword] = useState('');
  const [deactivateStep, setDeactivateStep] = useState(1);
  const [deactivating, setDeactivating] = useState(false);

  // 账号绑定状态（null=尚未加载）
  const [wechatBound, setWechatBound] = useState<boolean | null>(null);
  const [phoneBound, setPhoneBound] = useState<boolean | null>(null);

  useEffect(() => {
    let alive = true;
    if (!user) return;
    getBindingInfo()
      .then((info) => {
        if (!alive) return;
        setWechatBound(!!info.wechatBound);
        setPhoneBound(!!info.phoneBound);
      })
      .catch(() => {
        // 取不到时按“可用/未绑定”兜底，不阻断页面
        if (alive) {
          setWechatBound(false);
          setPhoneBound(false);
        }
      });
    return () => {
      alive = false;
    };
  }, [user]);

  const settingItems = [
    {
      icon: FileText,
      iconColor: 'text-cyan-400',
      iconBg: 'bg-cyan-500/20',
      title: t('用户协议'),
      desc: t('查看服务条款与使用规则'),
      onClick: () => navigate('/terms'),
    },
    {
      icon: Ban,
      iconColor: 'text-red-400',
      iconBg: 'bg-red-500/20',
      title: t('黑名单管理'),
      desc: t('查看与管理你拉黑的用户'),
      onClick: () => navigate('/blocks'),
    },
    {
      icon: RefreshCw,
      iconColor: 'text-emerald-400',
      iconBg: 'bg-emerald-500/20',
      title: t('检查更新'),
      desc: t('查看是否有新版本可升级'),
      onClick: () => {
        const isNative =
          typeof window !== 'undefined' &&
          (window as unknown as { Capacitor?: { isNativePlatform?: () => boolean } })
            .Capacitor?.isNativePlatform?.();
        if (isNative) {
          toast.info(t('正在检查更新…'));
          window.dispatchEvent(new Event('app:check-update'));
        } else {
          toast.message(t('网页版始终为最新，无需更新'));
        }
      },
    },
  ];

  const handleDeactivate = async () => {
    if (!user) return;
    const confirmed = await showConfirm(t('确定要注销账号吗？\n\n注销后账号将无法恢复，所有个人信息将被匿名化，历史发布的内容将保留并显示为「已注销用户」。\n\n请谨慎操作！'));
    if (!confirmed) return;

    setDeactivateStep(1);
    setDeactivatePassword('');
    setDeactivateDialogOpen(true);
  };

  const handleDeactivateNext = async () => {
    if (deactivateStep === 1) {
      setDeactivateStep(2);
      return;
    }
    if (!deactivatePassword.trim()) {
      toast.error(t('请输入登录密码'));
      return;
    }
    setDeactivating(true);
    try {
      await deactivate(deactivatePassword);
      toast(t('账号已注销，感谢您的使用。'));
      setDeactivateDialogOpen(false);
      navigate('/', { replace: true });
    } catch (err) {
      logger.error('注销账号失败', err);
      const msg = err instanceof Error ? err.message : t('注销失败，请稍后重试。');
      toast.error(msg);
    } finally {
      setDeactivating(false);
    }
  };

  const roleLabel: Record<string, string> = {
    super_admin: '超级管理员',
    admin: '管理员',
    user: '普通用户',
  };

  return (
    <div className="max-w-3xl mx-auto px-4 py-8">
      {/* 返回 */}
      <button
        onClick={() => navigate(-1)}
        className="flex items-center gap-1.5 text-4xl md:text-sm text-gray-400 hover:text-cyan-300 transition-colors mb-6"
      >
        <ArrowLeft className="h-5 w-5 md:h-4 md:w-4" />
        {t('返回')}
      </button>

      {/* 标题 */}
      <div className="flex items-center gap-3 mb-8">
        <div className="flex h-12 w-12 md:h-10 md:w-10 items-center justify-center rounded-full bg-neon-gradient shadow-lg box-glow-cyan">
          <Settings className="h-6 w-6 md:h-5 md:w-5 text-white" />
        </div>
        <h1 className="text-6xl md:text-2xl font-bold text-white">{t('账号设置')}</h1>
      </div>

      {/* 账号信息卡片 */}
      {user && (
        <div className="mb-6 rounded-xl border border-white/10 bg-[#141838]/60 backdrop-blur p-6 md:p-6">
          <div className="flex items-center gap-4 md:gap-4">
            <AvatarUpload size="md" showLabel={false} />
            <div className="flex-1">
              <h2 className="text-6xl md:text-lg font-bold text-white">
                {user.nickname || user.username}
              </h2>
              <p className="text-4xl md:text-sm text-gray-400">@{user.username}</p>
              <div className="flex items-center gap-3 mt-2 md:mt-2 flex-wrap">
                <span className="inline-flex items-center gap-1 px-2.5 py-1 md:px-2 md:py-0.5 rounded-full bg-cyan-500/15 border border-cyan-400/30 text-cyan-300 text-2xl md:text-xs">
                  {t(roleLabel[user.role || 'user'])}
                </span>
                <span className="inline-flex items-center gap-1 text-2xl md:text-xs text-yellow-400">
                  <Trophy className="h-4 w-4 md:h-3 md:w-3" />
                  {t('声望')} {user.reputation ?? 0}
                </span>
                <span className="inline-flex items-center gap-1 text-2xl md:text-xs text-emerald-400">
                  <Star className="h-4 w-4 md:h-3 md:w-3" />
                  Lv.{user.level ?? 1}
                </span>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 账号绑定 */}
      <div className="mb-6 rounded-xl border border-white/10 bg-[#141838]/60 backdrop-blur overflow-hidden">
        <div className="p-5 md:p-4 border-b border-white/5">
          <h2 className="text-4xl md:text-base font-semibold text-white">{t('账号绑定')}</h2>
        </div>
        <div>
          <div className="flex items-center gap-4 p-5 md:p-4 border-b border-white/5">
            <div className="flex h-11 w-11 md:h-9 md:w-9 shrink-0 items-center justify-center rounded-full bg-[#07C160]/20">
              <MessageCircle className="h-5 w-5 md:h-4 md:w-4 text-[#07C160]" />
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="text-4xl md:text-base font-semibold text-white">
                {t('微信账号')}
              </h3>
              <p className="text-2xl md:text-xs text-gray-400 mt-1">{t('使用微信快速登录')}</p>
            </div>
            {wechatBound === true ? (
              <span className="shrink-0 px-2.5 py-1 md:px-2 md:py-0.5 rounded-full bg-emerald-500/20 border border-emerald-400/30 text-emerald-300 text-xl md:text-xs">
                {t('已绑定')}
              </span>
            ) : wechatBound === false ? (
              <span className="shrink-0 px-2.5 py-1 md:px-2 md:py-0.5 rounded-full bg-[#07C160]/15 border border-[#07C160]/30 text-[#07C160] text-xl md:text-xs">
                {t('可登录')}
              </span>
            ) : (
              <span className="shrink-0 px-2.5 py-1 md:px-2 md:py-0.5 rounded-full bg-gray-500/20 border border-gray-500/30 text-gray-400 text-xl md:text-xs">
                {t('检测中')}
              </span>
            )}
          </div>
          <div className="flex items-center gap-4 p-5 md:p-4 cursor-not-allowed opacity-60">
            <div className="flex h-11 w-11 md:h-9 md:w-9 shrink-0 items-center justify-center rounded-full bg-purple-500/20">
              <Smartphone className="h-5 w-5 md:h-4 md:w-4 text-purple-400" />
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="text-4xl md:text-base font-semibold text-white">
                {t('手机号')}
              </h3>
              <p className="text-2xl md:text-xs text-gray-400 mt-1">{t('用于账号找回与安全验证')}</p>
            </div>
            <span className="shrink-0 px-2.5 py-1 md:px-2 md:py-0.5 rounded-full bg-gray-500/20 border border-gray-500/30 text-gray-400 text-xl md:text-xs">
              {t('即将可用')}
            </span>
          </div>
        </div>
        <div className="px-5 py-3 md:px-4 md:py-2 border-t border-white/5 bg-white/[0.02]">
          <p className="text-xl md:text-xs text-gray-500">
            {t('微信登录已开放；手机号绑定将在后续版本提供')}
          </p>
        </div>
      </div>

      {/* 语言选择（仅副页英文化版本显示，位于用户协议上方） */}
      {I18N_ENABLED && (
        <div className="mb-6 rounded-xl border border-white/10 bg-[#141838]/60 backdrop-blur p-5 md:p-4">
          <h3 className="text-4xl md:text-base font-semibold text-white mb-1">
            {lang === 'en' ? 'Language' : '语言'}
          </h3>
          <p className="text-2xl md:text-xs text-gray-400 mb-4 md:mb-3">
            {lang === 'en'
              ? 'Choose the display language'
              : '选择界面显示语言'}
          </p>
          <div className="flex gap-3">
            <button
              onClick={() => setLang('zh')}
              className={`flex-1 py-2.5 md:py-2 rounded-lg text-3xl md:text-sm font-medium border transition-colors ${
                lang === 'zh'
                  ? 'bg-cyan-500/20 border-cyan-400/60 text-cyan-200'
                  : 'bg-white/5 border-white/10 text-gray-300 hover:bg-white/10'
              }`}
            >
              中文
            </button>
            <button
              onClick={() => setLang('en')}
              className={`flex-1 py-2.5 md:py-2 rounded-lg text-3xl md:text-sm font-medium border transition-colors ${
                lang === 'en'
                  ? 'bg-cyan-500/20 border-cyan-400/60 text-cyan-200'
                  : 'bg-white/5 border-white/10 text-gray-300 hover:bg-white/10'
              }`}
            >
              English
            </button>
          </div>
        </div>
      )}

      {/* 滑屏加点开关（手机竖屏：直接在属性面板能力数值上左右滑动加/减点） */}
      <div className="mb-6 flex items-center gap-4 rounded-xl border border-white/10 bg-[#141838]/60 p-5 backdrop-blur md:p-4">
        <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-cyan-500/20 md:h-9 md:w-9">
          <Hand className="h-5 w-5 text-cyan-400 md:h-4 md:w-4" />
        </div>
        <div className="min-w-0 flex-1">
          <h3 className="text-4xl font-semibold text-white md:text-base">
            {lang === 'en' ? 'Slide to Allocate' : '滑屏加点'}
          </h3>
          <p className="mt-1 text-2xl text-gray-400 md:text-xs">
            {lang === 'en'
              ? 'On phones, swipe left/right directly on an ability value'
              : '手机竖屏直接在属性面板的能力数值上左右滑动即可加/减点'}
          </p>
        </div>
        <button
          type="button"
          role="switch"
          aria-checked={slideOn}
          aria-label={lang === 'en' ? 'Toggle slide to allocate' : '切换滑屏加点'}
          onClick={() => setSlideOn(!slideOn)}
          className={`relative h-7 w-12 shrink-0 rounded-full transition-colors ${slideOn ? 'bg-cyan-500' : 'bg-white/15'}`}
        >
          <span className={`absolute top-0.5 h-6 w-6 rounded-full bg-white shadow transition-all ${slideOn ? 'left-[22px]' : 'left-0.5'}`} />
        </button>
      </div>

      {/* 协议与政策 */}
      <div className="mb-6 rounded-xl border border-white/10 bg-[#141838]/60 backdrop-blur overflow-hidden">
        {settingItems.map((item, idx) => (
          <button
            key={item.title}
            onClick={item.onClick}
            className={`w-full flex items-center gap-4 p-5 md:p-4 hover:bg-white/5 transition-colors text-left ${
              idx !== settingItems.length - 1 ? 'border-b border-white/5' : ''
            }`}
          >
            <div className={`flex h-11 w-11 md:h-9 md:w-9 shrink-0 items-center justify-center rounded-full ${item.iconBg}`}>
              <item.icon className={`h-5 w-5 md:h-4 md:w-4 ${item.iconColor}`} />
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="text-4xl md:text-base font-semibold text-white">
                {item.title}
              </h3>
              <p className="text-2xl md:text-xs text-gray-400 mt-1">{item.desc}</p>
            </div>
            <ChevronRight className="h-5 w-5 md:h-4 md:w-4 text-gray-500 shrink-0" />
          </button>
        ))}
      </div>

      {/* 注销账号区块 */}
      <div className="rounded-xl border border-red-500/20 bg-red-500/5 backdrop-blur p-6 md:p-6">
        <div className="flex items-start gap-3 md:gap-3 mb-5 md:mb-4">
          <div className="flex h-12 w-12 md:h-10 md:w-10 shrink-0 items-center justify-center rounded-full bg-red-500/20">
            <AlertTriangle className="h-6 w-6 md:h-5 md:w-5 text-red-400" />
          </div>
          <div>
            <h3 className="text-6xl md:text-lg font-bold text-red-300 mb-2 md:mb-1">
              {t('注销账号')}
            </h3>
            <p className="text-3xl md:text-sm text-red-300/70 leading-relaxed">
              {t('注销后账号将无法恢复，所有个人信息将被匿名化，历史发布的内容将保留并显示为「已注销用户」。')}
            </p>
          </div>
        </div>

        <div className="pt-5 md:pt-4 border-t border-red-500/10">
          <button
            onClick={handleDeactivate}
            className="w-full md:w-auto px-8 py-3.5 md:px-6 md:py-2 rounded-lg bg-red-500 text-white text-4xl md:text-sm font-medium hover:bg-red-600 transition-colors shadow-lg shadow-red-500/20"
          >
            {t('注销账号')}
          </button>
        </div>
      </div>

      {/* 注销确认对话框 */}
      <Dialog open={deactivateDialogOpen} onOpenChange={setDeactivateDialogOpen}>
        <DialogContent className="border-red-500/30 bg-[#141838] text-white sm:max-w-[440px]">
          <DialogHeader>
            <DialogTitle className="text-6xl md:text-2xl font-bold text-red-300">
              {deactivateStep === 1 ? t('再次确认注销账号') : t('请输入登录密码')}
            </DialogTitle>
          </DialogHeader>
          <DialogDescription className="text-gray-400">
            {deactivateStep === 1 ? (
              <>
                {t('您正在注销账号')} <span className="text-white font-semibold">{user?.username}</span>。
                <br /><br />
                {t('此操作不可撤销，所有个人信息将被匿名化，历史发布的内容将保留并显示为「已注销用户」。')}
                <br />
                {t('确认继续注销吗？')}
              </>
            ) : (
              <>
                {t('为了确认是您本人操作，请输入当前账号的登录密码：')}
              </>
            )}
          </DialogDescription>
          {deactivateStep === 2 && (
            <div className="py-2">
              <Input
                type="password"
                value={deactivatePassword}
                onChange={(e) => setDeactivatePassword(e.target.value)}
                placeholder={t('请输入登录密码')}
                className="border-white/10 bg-[#0A0E27] text-white focus:border-red-400"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleDeactivateNext();
                }}
              />
            </div>
          )}
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                if (deactivateStep === 2) {
                  setDeactivateStep(1);
                } else {
                  setDeactivateDialogOpen(false);
                }
              }}
              className="border-white/10 bg-transparent text-gray-300 hover:bg-white/5 hover:text-white"
              disabled={deactivating}
            >
              {deactivateStep === 2 ? t('上一步') : t('取消')}
            </Button>
            <Button
              onClick={handleDeactivateNext}
              disabled={deactivating || (deactivateStep === 2 && !deactivatePassword.trim())}
              className="bg-red-500 text-white hover:bg-red-600 shadow-lg shadow-red-500/20 disabled:opacity-50"
            >
              {deactivating ? (
                <><Loader2 className="mr-1.5 h-4 w-4 animate-spin" />{t('处理中...')}</>
              ) : deactivateStep === 1 ? (
                t('确认注销')
              ) : (
                t('提交注销')
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default SettingsPage;
