import React from 'react';
import { Route, Routes } from 'react-router-dom';

import { AuthProvider } from './context/AuthContext';
import Layout from './components/Layout';
import PlayersPage from './pages/players/PlayersPage';
import PlayerDetailPage from './pages/player-detail/PlayerDetailPage';
import PlayerComparePage from './pages/player-compare/PlayerComparePage';
import PlayerCompareSelectPage from './pages/player-compare/PlayerCompareSelectPage';
import RankingsPage from './pages/rankings/RankingsPage';
import RankingPositionPage from './pages/rankings/RankingPositionPage';
import MyTierList from './pages/tier-list/MyTierList';
import MyLineup from './pages/lineup/MyLineup';
import CoachesPage from './pages/coaches/CoachesPage';
import CoachDetailPage from './pages/coach-detail/CoachDetailPage';
import PacksPage from './pages/packs/PacksPage';
import PackDetailPage from './pages/packs/PackDetailPage';
import AuthPage from './pages/auth/AuthPage';
import EncyclopediaPage from './pages/encyclopedia/EncyclopediaPage';
import EncyclopediaDetailPage from './pages/encyclopedia/EncyclopediaDetailPage';
import CoachTacticDetailPage from './pages/encyclopedia/CoachTacticDetailPage';
import AbilityValueDetailPage from './pages/encyclopedia/AbilityValueDetailPage';
import ForumListPage from './pages/forum/ForumListPage';
import ForumDetailPage from './pages/forum/ForumDetailPage';
import AdminReportsPage from './pages/admin/AdminReportsPage';
import AdminUsersPage from './pages/admin/AdminUsersPage';
import AdminSensitiveWordsPage from './pages/admin/AdminSensitiveWordsPage';
import TermsPage from './pages/legal/TermsPage';
import PrivacyPage from './pages/legal/PrivacyPage';
import ProfilePage from './pages/profile/ProfilePage';
import UserProfilePage from './pages/user-profile/UserProfilePage';
import SettingsPage from './pages/settings/SettingsPage';
import BlockListPage from './pages/settings/BlockListPage';
import NotificationsPage from './pages/notifications/NotificationsPage';
import ReputationPage from './pages/reputation/ReputationPage';
import NewsListPage from './pages/news/NewsListPage';
import NewsDetailPage from './pages/news/NewsDetailPage';
import NewsAuthorPage from './pages/news/NewsAuthorPage';
import NewsTagPage from './pages/news/NewsTagPage';
import NotFound from './pages/NotFound/NotFound';
import PrivacyGate from './components/PrivacyGate';
import { useNativeBackButton } from './hooks/useNativeBackButton';

const RoutesComponent = () => {
  useNativeBackButton();
  return (
    <AuthProvider>
      <PrivacyGate>
          <Routes>
        <Route path="auth" element={<AuthPage />} />
        <Route element={<Layout />}>
          <Route index element={<PlayersPage variant="home" />} />
          <Route path="players" element={<PlayersPage variant="list" />} />
          <Route path="rankings" element={<RankingsPage />} />
          <Route path="rankings/:position" element={<RankingPositionPage />} />
          <Route path="tier" element={<MyTierList />} />
          <Route path="tier/:id" element={<MyTierList />} />
          <Route path="lineup" element={<MyLineup />} />
          <Route path="lineup/:id" element={<MyLineup />} />
          <Route path="player/:id" element={<PlayerDetailPage />} />
          <Route path="compare" element={<PlayerComparePage />} />
          <Route path="compare/select" element={<PlayerCompareSelectPage />} />
          <Route path="coaches" element={<CoachesPage />} />
          <Route path="coach/:id" element={<CoachDetailPage />} />
          <Route path="packs" element={<PacksPage />} />
          <Route path="pack/:id" element={<PackDetailPage />} />
           <Route path="encyclopedia" element={<EncyclopediaPage />} />
           <Route path="encyclopedia/ability/:key" element={<AbilityValueDetailPage />} />
           <Route path="encyclopedia/coach-tactic/:id" element={<CoachTacticDetailPage />} />
           <Route path="encyclopedia/:category/:id" element={<EncyclopediaDetailPage />} />
           <Route path="forum" element={<ForumListPage />} />
           <Route path="forum/:id" element={<ForumDetailPage />} />
           <Route path="admin/reports" element={<AdminReportsPage />} />
           <Route path="admin/users" element={<AdminUsersPage />} />
           <Route path="admin/sensitive-words" element={<AdminSensitiveWordsPage />} />
            <Route path="profile" element={<ProfilePage />} />
            <Route path="user/:userId" element={<UserProfilePage />} />
           <Route path="settings" element={<SettingsPage />} />
           <Route path="blocks" element={<BlockListPage />} />
            <Route path="notifications" element={<NotificationsPage />} />
            <Route path="reputation" element={<ReputationPage />} />
            <Route path="news" element={<NewsListPage />} />
            <Route path="news/author/:author" element={<NewsAuthorPage />} />
            <Route path="news/tag/:tag" element={<NewsTagPage />} />
            <Route path="news/:id" element={<NewsDetailPage />} />
         </Route>
         <Route path="terms" element={<TermsPage />} />
         <Route path="privacy" element={<PrivacyPage />} />
         <Route path="*" element={<NotFound />} />
      </Routes>
      </PrivacyGate>
    </AuthProvider>
  );
};

export default RoutesComponent;
