const ST_ALIAS_MAP: Record<string, string> = {};
const ST_ZH_NAMES: string[] = [];

for (const s of ST_SKILLS) {
  ST_ZH_NAMES.push(s.zhName);
  ST_ALIAS_MAP[normalizeForCompare(s.zhName)] = s.zhName;
  for (const alias of s.aliases) {
    ST_ALIAS_MAP[normalizeForCompare(alias)] = s.zhName;
  }
}

function normalizeForCompare(name: string): string {
  return name.trim().toLowerCase().replace(/\s+/g, '');
}

export function isStSkill(skill: string): boolean {
  return Object.prototype.hasOwnProperty.call(ST_ALIAS_MAP, normalizeForCompare(skill));
}

export function normalizeStSkillName(skill: string): string {
  return ST_ALIAS_MAP[normalizeForCompare(skill)] ?? skill;
}

export function getStSkillAliases(skill: string): string[] {
  const normalized = normalizeForCompare(skill);
  const canonical = ST_ALIAS_MAP[normalized];
  if (!canonical) return [skill];
  const entry = ST_SKILLS.find((s: StSkillEntry) => s.zhName === canonical);
  if (!entry) return [skill];
  return [entry.zhName, ...entry.aliases];
}

export const ST_SKILL_ZH_NAMES: string[] = ST_ZH_NAMES;

