import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { X, RotateCcw, Minus, Plus } from 'lucide-react';
import { calcAvailablePoints } from '@client/src/utils/build-categories';

interface LevelCustomizeDialogProps {
  open: boolean;
  minLevel: number;
  maxLevel: number;
  currentLevel: number;
  allocations: Record<string, number>;
  onClose: () => void;
  onConfirm: (level: number) => void;
}

const LevelCustomizeDialog: React.FC<LevelCustomizeDialogProps> = ({
  open,
  minLevel = 1,
  maxLevel = 1,
  currentLevel,
  allocations,
  onClose,
  onConfirm,
}) => {
  const [draftLevel, setDraftLevel] = useState<number>(currentLevel);
  const [inputValue, setInputValue] = useState<string>(String(currentLevel));
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (open) {
      setDraftLevel(currentLevel);
      setInputValue(String(currentLevel));
    }
  }, [open, currentLevel]);

  const availablePoints = calcAvailablePoints(draftLevel, allocations);
  const isOverBudget = availablePoints < 0;
  const earnedPoints = (draftLevel - 1) * 2;

  const handleMinus = () => {
    setDraftLevel((prev) => {
      const next = Math.max(minLevel, prev - 1);
      setInputValue(String(next));
      return next;
    });
  };

  const handlePlus = () => {
    setDraftLevel((prev) => {
      const next = Math.min(maxLevel, prev + 1);
      setInputValue(String(next));
      return next;
    });
  };

  const handleSlider = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = Number(e.target.value);
    const safe = Math.max(minLevel, Math.min(maxLevel, val));
    setDraftLevel(safe);
    setInputValue(String(safe));
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(e.target.value);
  };

  const handleInputBlur = () => {
    const parsed = parseInt(inputValue, 10);
    if (Number.isFinite(parsed)) {
      const safe = Math.max(minLevel, Math.min(maxLevel, parsed));
      setDraftLevel(safe);
      setInputValue(String(safe));
    } else {
      setInputValue(String(draftLevel));
    }
  };

  const handleInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      handleInputBlur();
      inputRef.current?.blur();
    }
  };

  const handleReset = () => {
    setDraftLevel(maxLevel);
    setInputValue(String(maxLevel));
  };

  const handleConfirm = () => {
    onConfirm(draftLevel);
  };

  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    return () => setMounted(false);
  }, []);

  if (!open || !mounted) return null;

  const progressPct = maxLevel > minLevel
    ? ((draftLevel - minLevel) / (maxLevel - minLevel)) * 100
    : 0;

  const portal = (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-black/70 backdrop-blur-sm"
        onClick={onClose}
      />
      <div className="relative w-full max-w-md rounded-2xl bg-[#0f1230] border border-cyan-400/30 shadow-[0_0_40px_rgba(0_229_255_0.15)] overflow-hidden">
        <div className="flex items-center justify-between px-4 py-3 border-b border-white/10">
          <div className="flex items-center gap-2">
            <span className="w-1 h-5 bg-gradient-to-b from-cyan-400 to-purple-500 rounded-full" />
            <h3 className="text-lg font-bold text-white">自定义等级</h3>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-lg text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-4 space-y-5">
          <div className="flex items-center justify-between">
            <span className="text-sm text-gray-400">可选范围</span>
            <span className="text-sm font-medium text-gray-300">
              {minLevel} 级 ~ {maxLevel} 级
            </span>
          </div>

          <div className="flex items-center justify-center gap-3">
            <button
              type="button"
              onClick={handleMinus}
              disabled={draftLevel <= minLevel}
              className="w-10 h-10 flex items-center justify-center rounded-xl bg-white/5 border border-white/10 text-gray-300 hover:bg-white/10 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
            >
              <Minus className="w-5 h-5" />
            </button>

            <div className="relative">
              <input
                ref={inputRef}
                type="text"
                value={inputValue}
                onChange={handleInputChange}
                onBlur={handleInputBlur}
                onKeyDown={handleInputKeyDown}
                className="w-24 text-center text-4xl font-black text-transparent bg-clip-text bg-gradient-to-b from-amber-300 to-amber-500 bg-transparent border-b-2 border-cyan-400/40 focus:border-cyan-300 outline-none pb-1"
              />
              <span className="absolute -right-6 bottom-2 text-base font-bold text-gray-400">级</span>
            </div>

            <button
              type="button"
              onClick={handlePlus}
              disabled={draftLevel >= maxLevel}
              className="w-10 h-10 flex items-center justify-center rounded-xl bg-white/5 border border-white/10 text-gray-300 hover:bg-white/10 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
            >
              <Plus className="w-5 h-5" />
            </button>
          </div>

          <div className="relative pt-1">
            <input
              type="range"
              min={minLevel}
              max={maxLevel}
              value={draftLevel}
              onChange={handleSlider}
              className="w-full h-2 appearance-none bg-white/10 rounded-full cursor-pointer accent-cyan-400"
              style={{
                background: `linear-gradient(to right, #00e5ff ${progressPct}%, rgba(255,255,255,0.1) ${progressPct}%)`,
              }}
            />
            <div className="flex justify-between mt-1 text-xs text-gray-500">
              <span>{minLevel}</span>
              <span>{Math.floor((minLevel + maxLevel) / 2)}</span>
              <span>{maxLevel}</span>
            </div>
          </div>

          <div className="rounded-xl bg-white/[0.03] border border-white/10 p-3 space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-sm text-gray-400">可用加点总数</span>
              <span className="text-lg font-bold text-cyan-300">
                {earnedPoints} 点
              </span>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-sm text-gray-400">剩余可用点数</span>
              <span className={`text-lg font-bold ${isOverBudget ? 'text-red-400' : 'text-emerald-300'}`}>
                {availablePoints >= 0 ? '+' : ''}{availablePoints} 点
              </span>
            </div>
            {isOverBudget && (
              <div className="text-xs text-red-400 bg-red-500/10 rounded-lg px-2 py-1.5 border border-red-500/30">
                当前等级下已分配点数超出可用点数，确定后超出部分将被重置
              </div>
            )}
            {draftLevel !== maxLevel && (
              <button
                type="button"
                onClick={handleReset}
                className="flex items-center gap-1 text-xs text-gray-400 hover:text-cyan-300 transition-colors mt-1"
              >
                <RotateCcw className="w-3.5 h-3.5" />
                <span>恢复默认（{maxLevel} 级）</span>
              </button>
            )}
          </div>
        </div>

        <div className="flex gap-2 px-4 py-3 border-t border-white/10">
          <button
            type="button"
            onClick={onClose}
            className="flex-1 py-2.5 rounded-xl text-sm font-medium text-gray-300 bg-white/5 border border-white/10 hover:bg-white/10 transition-colors"
          >
            取消
          </button>
          <button
            type="button"
            onClick={handleConfirm}
            className="flex-1 py-2.5 rounded-xl text-sm font-bold text-white bg-gradient-to-r from-cyan-500 to-purple-500 hover:from-cyan-400 hover:to-purple-400 transition-colors shadow-[0_0_20px_rgba(0_229_255_0.2)]"
          >
            确定
          </button>
        </div>
      </div>
    </div>
  );

  return createPortal(portal, document.body);
};

export default LevelCustomizeDialog;
