import React, { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Ban, Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import {
  listBlocks,
  unblockUser,
  type BlockedUserItem,
} from '@client/src/api/blocks';
import { useAuth } from '@client/src/context/AuthContext';
import UserAvatar from '@client/src/components/ui/user-avatar';
import { trTerm } from '@client/src/i18n/terms';

const BlockListPage: React.FC = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [items, setItems] = useState<BlockedUserItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [busyId, setBusyId] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      setItems(await listBlocks());
    } catch {
      toast.error(trTerm('加载失败，请重试'));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!user) {
      navigate('/auth', { replace: true });
      return;
    }
    void load();
  }, [user, navigate, load]);

  const handleUnblock = async (id: string) => {
    if (busyId) return;
    setBusyId(id);
    try {
      await unblockUser(id);
      setItems((prev) => prev.filter((x) => x.id !== id));
      toast.success(trTerm('已取消拉黑'));
    } catch {
      toast.error(trTerm('操作失败，请重试'));
    } finally {
      setBusyId(null);
    }
  };

  return (
    <div className="min-h-screen bg-[#0A0E27] text-white p-4 md:p-6">
      <button
        onClick={() => navigate(-1)}
        className="flex items-center gap-1.5 text-4xl md:text-sm text-gray-400 hover:text-cyan-300 transition-colors mb-6"
      >
        <ArrowLeft className="w-7 h-7 md:w-4 md:h-4" />
        {trTerm('返回')}
      </button>
      <div className="flex items-center gap-3 mb-8">
        <div className="flex h-12 w-12 md:h-10 md:w-10 items-center justify-center rounded-full bg-red-500/20">
          <Ban className="h-6 w-6 md:h-5 md:w-5 text-red-400" />
        </div>
        <h1 className="text-6xl md:text-2xl font-bold">
          {trTerm('黑名单管理')}
        </h1>
      </div>

      {loading ? (
        <div className="flex justify-center py-16">
          <Loader2 className="w-10 h-10 md:w-8 md:h-8 animate-spin text-cyan-400" />
        </div>
      ) : items.length === 0 ? (
        <div className="text-center py-16">
          <Ban className="w-16 h-16 md:w-12 md:h-12 text-gray-700 mx-auto mb-3" />
          <p className="text-3xl md:text-sm text-gray-500">
            {trTerm('黑名单为空')}
          </p>
        </div>
      ) : (
        <div className="space-y-3 max-w-2xl">
          {items.map((it) => (
            <div
              key={it.id}
              className="flex items-center gap-4 rounded-xl border border-white/10 bg-[#141838]/60 p-4 md:p-3"
            >
              <button
                onClick={() => navigate(`/user/${it.id}`)}
                className="flex items-center gap-3 flex-1 min-w-0 text-left"
              >
                <UserAvatar
                  avatarUrl={it.avatarUrl}
                  userName={it.nickname || it.username}
                  size="sm"
                />
                <span className="text-3xl md:text-sm font-medium text-cyan-200 truncate">
                  {it.nickname || it.username || trTerm('匿名球迷')}
                </span>
              </button>
              <button
                onClick={() => void handleUnblock(it.id)}
                disabled={busyId === it.id}
                className="px-4 py-2 md:px-3 md:py-1.5 rounded-lg text-3xl md:text-xs border border-red-400/40 text-red-300 hover:bg-red-500/15 transition-colors disabled:opacity-50"
              >
                {trTerm('取消拉黑')}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default BlockListPage;
