import { logger } from '@lark-apaas/client-toolkit/logger';
import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';
import type {
  FollowToggleResponse,
  FollowListResponse,
} from '@shared/api.interface';

export async function toggleFollow(
  userId: string,
  headers?: Record<string, string>,
): Promise<FollowToggleResponse> {
  try {
    const response = await axiosForBackend.post<FollowToggleResponse>(
      `/api/follows/${userId}`,
      {},
      { headers },
    );
    return response.data;
  } catch (error) {
    logger.error('切换关注状态失败', error);
    throw error;
  }
}

export async function checkFollow(
  userId: string,
  headers?: Record<string, string>,
): Promise<{ following: boolean }> {
  try {
    const response = await axiosForBackend.get<{ following: boolean }>(
      `/api/follows/check/${userId}`,
      { headers },
    );
    return response.data;
  } catch (error) {
    logger.error('检查关注状态失败', error);
    throw error;
  }
}

