import { getPlayerTypeLabel } from '../players/player-utils';
import type { Pack } from '@shared/api.interface';

// 包内球员「规范类型」→ 标签短名与排序权重（权重小的排在组合标签前面）
export const PACK_TYPE_SHORT: Record<string, { short: string; rank: number }> = {
  BT球员: { short: 'BT', rank: 0 },
  ST球员: { short: 'ST', rank: 1 },
  史诗传奇: { short: '史诗', rank: 2 },
  高光传奇: { short: '高光', rank: 3 },
  经典传奇: { short: '经典', rank: 4 },
  状态火热: { short: '状态火热', rank: 5 },
  精选球员: { short: '精选', rank: 6 },
  普通球员: { short: '普通', rank: 7 },
};

// 依据包内球员的真实类型，生成组合标签（如「史诗+精选」）与卡片配色
export function getPackTypeInfo(pack: Pack): {
  label: string;
  gradient: string;
} {
  const rawTypes = pack.playerTypes ?? [];
  const canonical = Array.from(
    new Set(rawTypes.map((t) => getPlayerTypeLabel(t))),
  );

  // 后端尚未返回包内类型时的兜底：沿用原 packType，避免出现空标签
  if (canonical.length === 0) {
    return { label: pack.packType || '', gradient: 'from-cyan-500 to-blue-500' };
  }

  const known = canonical
    .filter((c) => PACK_TYPE_SHORT[c])
    .sort((a, b) => PACK_TYPE_SHORT[a].rank - PACK_TYPE_SHORT[b].rank);
  const list = known.length > 0 ? known : canonical;
  const label = list.map((c) => PACK_TYPE_SHORT[c]?.short ?? c).join('+');

  const has = (c: string) => canonical.includes(c);

  let gradient: string;
  if (has('BT球员')) {
    gradient = 'from-amber-400 to-yellow-500'; // 含 BT：金色
  } else if (has('ST球员')) {
    gradient = 'from-blue-500 to-blue-700'; // 含 ST：蓝色
  } else if (canonical.length === 1 && has('史诗传奇')) {
    gradient = 'from-emerald-400 to-green-500'; // 纯史诗：亮绿
  } else if (canonical.length === 1 && has('状态火热')) {
    gradient = 'from-emerald-800 to-teal-900'; // 纯状态火热：墨绿
  } else if (canonical.length === 1 && has('精选球员')) {
    gradient = 'from-slate-500 to-slate-600'; // 纯普通精选：灰
  } else {
    // 混合包（无 BT/ST）：按包内最高稀有类型着色 —— 这是经验判断
    if (has('史诗传奇')) gradient = 'from-emerald-400 to-green-500';
    else if (has('高光传奇') || has('经典传奇'))
      gradient = 'from-pink-500 to-rose-600';
    else if (has('状态火热')) gradient = 'from-emerald-800 to-teal-900';
    else if (has('精选球员')) gradient = 'from-slate-500 to-slate-600';
    else gradient = 'from-cyan-500 to-blue-500';
  }

  return { label, gradient };
}

// 卡片日期展示（与卡包卡片完全一致）：中文“YYYY年M月D日” / 英文“Oct 1, 2026”
const MONTHS_EN_SHORT = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

export function formatPackDateDisplay(cnDate: string, lang: string): string {
  if (!cnDate) return '';
  const toZh = (y: string, mo: string, d?: string) =>
    d ? `${y}年${Number(mo)}月${Number(d)}日` : `${y}年${Number(mo)}月`;

  let m = cnDate.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) {
    if (lang !== 'en') return toZh(m[1], m[2], m[3]);
    return `${MONTHS_EN_SHORT[Number(m[2]) - 1]} ${Number(m[3])}, ${m[1]}`;
  }
  m = cnDate.match(/(\d{4})年(\d{1,2})月(\d{1,2})日?/);
  if (m) {
    if (lang !== 'en') return toZh(m[1], m[2], m[3]);
    return `${MONTHS_EN_SHORT[Number(m[2]) - 1]} ${Number(m[3])}, ${m[1]}`;
  }
  m = cnDate.match(/^(\d{4})-(\d{1,2})$/);
  if (m) {
    if (lang !== 'en') return toZh(m[1], m[2]);
    return `${MONTHS_EN_SHORT[Number(m[2]) - 1]} ${m[1]}`;
  }
  m = cnDate.match(/(\d{4})年(\d{1,2})月/);
  if (m) {
    if (lang !== 'en') return toZh(m[1], m[2]);
    return `${MONTHS_EN_SHORT[Number(m[2]) - 1]} ${m[1]}`;
  }
  return cnDate;
}
