import { logger } from '@lark-apaas/client-toolkit/logger';
import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';
import { getToken } from './auth';
import type {
  ReportListResponse,
  HandleReportDto,
  AdminUserListResponse,
  MuteUserDto,
  MergedReportListResponse,
  SensitiveWordListResponse,
  CreateSensitiveWordDto,
  UpdateSensitiveWordDto,
  SetRoleDto,
} from '@shared/api.interface';

function getAuthHeaders(): Record<string, string> {
  const token = getToken();
  return token ? { Authorization: `Bearer ${token}` } : {};
}

// ========== 举报管理 ==========

export async function getReportList(params: {
  status?: string;
  page?: number;
  pageSize?: number;
}): Promise<ReportListResponse> {
  try {
    const response = await axiosForBackend.get<ReportListResponse>(
      '/api/forum/admin/reports',
      {
        params,
        headers: getAuthHeaders(),
      },
    );
    return response.data;
  } catch (error) {
    logger.error('获取举报列表失败', error);
    throw error;
  }
}

export async function adminDeletePost(
  postId: string,
  reason?: string,
): Promise<{ success: boolean }> {
  try {
    const response = await axiosForBackend.delete<{ success: boolean }>(
      `/api/forum/admin/posts/${postId}`,
      {
        data: { reason },
        headers: getAuthHeaders(),
      },
    );
    return response.data;
  } catch (error) {
    logger.error('管理员删除帖子失败', error);
    throw error;
  }
}

