import { useEffect, useState } from 'react';

/**
 * 检测当前是否运行在 Capacitor 原生壳内（APK / IPA）。
 * 网页（含 /efootball 与妙搭预览）返回 false。
 */
export function isNativeApp(): boolean {
  if (typeof window === 'undefined') return false;
  const cap = (window as any).Capacitor;
  if (!cap) return false;
  if (typeof cap.isNativePlatform === 'function') {
    try {
      return cap.isNativePlatform();
    } catch {
      return false;
    }
  }
  return cap.platform === 'android' || cap.platform === 'ios';
}

export function useIsNativeApp(): boolean {
  const [native, setNative] = useState(false);
  useEffect(() => {
    setNative(isNativeApp());
  }, []);
  return native;
}

/**
 * 是否为「网页横屏」：非原生壳（含 /efootball、/efootball-next 与妙搭预览）且视口为横屏（宽>高）。
 * 用于桌面/横屏网页下收紧百科详情页字体；原生 APP 与手机竖屏网页返回 false（保持原有大字体）。
 */
export function useWebLandscape(): boolean {
  const [landscape, setLandscape] = useState(false);
  useEffect(() => {
    const calc = () => {
      setLandscape(
        !isNativeApp() && window.innerWidth > window.innerHeight,
      );
    };
    calc();
    window.addEventListener('resize', calc);
    window.addEventListener('orientationchange', calc);
    return () => {
      window.removeEventListener('resize', calc);
      window.removeEventListener('orientationchange', calc);
    };
  }, []);
  return landscape;
}
