import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import { ArrowLeft, Loader2 } from 'lucide-react';
import { logger } from '@lark-apaas/client-toolkit/logger';
import { useAuth } from '@client/src/context/AuthContext';
import { useLoginGuard } from '@client/src/hooks/useLoginGuard';
import { ratings } from '@client/src/api';
import RatingStars from '@client/src/components/RatingStars';
import CommentSection from '@client/src/components/CommentSection';
import encyclopediaData from '@client/src/assets/data/encyclopedia.json';
import type { RatingSummary } from '@shared/api.interface';
import { toRouterPath } from '@client/src/utils/router-path';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { trTerm } from '@client/src/i18n/terms';
import { isHiddenSkill } from '@shared/hidden-skills';
import { useWebLandscape } from '@client/src/hooks/use-native-app';
import { skillIconUrl } from '@client/src/utils/skill-icons';
import {
  visitorLocalGet,
  visitorLocalSet,
  toastVisitorLocal,
} from '@client/src/utils/visitor-mode';

// 网页横屏下字体缩小 2 档的映射（仅替换字号类，其余类不动）
const DOWN2: Record<string, string> = {
  'text-5xl': 'text-3xl',
  'text-4xl': 'text-2xl',
  'text-3xl': 'text-xl',
  'text-2xl': 'text-base',
  'text-xl': 'text-sm',
  'text-lg': 'text-sm',
  'text-base': 'text-xs',
};

type CategoryKey =
  | 'attack_styles'
  | 'defense_styles'
  | 'ai_styles'
  | 'team_styles'
  | 'normal_skills'
  | 'showtime_skills';

const CATEGORY_LABELS: Record<CategoryKey, string> = {
  attack_styles: '进攻风格',
  defense_styles: '防守风格',
  ai_styles: 'AI风格',
  team_styles: '球队风格',
  normal_skills: '普通技能',
  showtime_skills: 'ST技能',
};

interface EncyclopediaItem {
  id: string;
  nameZh: string;
  nameEn: string;
  type: string;
  positions: string;
  descriptionZh: string;
  descriptionEn: string;
  notes: string | null;
}

function normalizeItem(item: any, categoryKey: CategoryKey): EncyclopediaItem {
  const isAiOrTeam =
    categoryKey === 'ai_styles' || categoryKey === 'team_styles';
  const isSkillCategory =
    categoryKey === 'normal_skills' || categoryKey === 'showtime_skills';

  if (isAiOrTeam) {
    return {
      id: item.id,
      nameZh: item.name_cn || '',
      nameEn: item.name_en || '',
      type: item.category || '',
      positions: item.positions || '',
      descriptionZh: item.description_cn || '',
      descriptionEn: item.description_en || '',
      notes: item.notes || null,
    };
  }

  if (isSkillCategory) {
    return {
      id: item.id,
      nameZh: item['中文名'] || '',
      nameEn: item['英文名'] || '',
      type: item['类型'] || '',
      positions: '',
      descriptionZh: item['英文描述'] || '',
      descriptionEn: item['适用位置'] || '',
      notes: item['备注'] || item['日文描述'] || null,
    };
  }

  return {
    id: item.id,
    nameZh: item['中文名'] || '',
    nameEn: item['英文名'] || '',
    type: item['类型'] || '',
    positions: item['适用位置'] || '',
    descriptionZh: item['中文描述'] || '',
    descriptionEn: item['英文描述'] || '',
    notes: item['日文描述'] || null,
  };
}

const EncyclopediaDetailPage: React.FC = () => {
  const { category, id } = useParams<{ category: string; id: string }>();
  const { t, lang } = useI18n();
  const compact = useWebLandscape();
  const sc = (cls: string) => (compact ? DOWN2[cls] ?? cls : cls);
  const navigate = useNavigate();
  const location = useLocation();
  const { user, getAuthHeaders } = useAuth();
  const { allowLocalAction } = useLoginGuard();

  // 返回：优先回到来源（如球员详情）；无来源时退回浏览器历史；再退回百科主页
  const handleBack = () => {
    const from = (location.state as { from?: string } | undefined)?.from;
    if (from) navigate(toRouterPath(from));
    else if (window.history.length > 1) navigate(-1);
    else navigate('/encyclopedia');
  };

  const [item, setItem] = useState<EncyclopediaItem | null>(null);
  const [ratingSummary, setRatingSummary] = useState<RatingSummary | null>(null);
  const [ratingLoading, setRatingLoading] = useState(false);
  const [notFound, setNotFound] = useState(false);
  // 游客本机评分（kind='rating'，key=`${targetType}:${item.id}`）；已登录走云端 userScore
  const [visitorScore, setVisitorScore] = useState<number | null>(null);

  const categoryKey = category as CategoryKey;
  const isStyleCategory = categoryKey === 'ai_styles' || categoryKey === 'team_styles';
  const isStCategory = categoryKey === 'showtime_skills';

  // 风格类还是技能类，决定 targetType
  const targetType = useMemo(() => {
    if (
      categoryKey === 'attack_styles' ||
      categoryKey === 'defense_styles' ||
      categoryKey === 'ai_styles' ||
      categoryKey === 'team_styles'
    ) {
      return 'style';
    }
    return 'skill';
  }, [categoryKey]);

  // 查找条目
  useEffect(() => {
    if (!category || !id) return;

    const data = (encyclopediaData as any)[categoryKey] || [];
    const found = data.find((d: any) => d.id === id);
    const norm = found ? normalizeItem(found, categoryKey) : null;
    // 全平台隐藏技能：即使直接访问其 URL，也按"不存在"处理，不显示详情（底层数据保留）
    const hidden = !!norm && (isHiddenSkill(norm.nameZh) || isHiddenSkill(norm.nameEn));

    if (found && !hidden) {
      setItem(norm);
      setNotFound(false);
    } else {
      setItem(null);
      setNotFound(true);
    }
  }, [category, id, categoryKey]);

  // 加载评分
  useEffect(() => {
    if (!item) return;
    ratings
      .getSummary(targetType, item.id)
      .then((data) => {
        setRatingSummary(data);
        // 游客：读取本机评分作为展示分（average/count 仍为服务端值）
        if (!user) {
          const local = visitorLocalGet('rating', `${targetType}:${item.id}`);
          setVisitorScore(local ? Number(local) : null);
        }
      })
      .catch((err) => {
        logger.error('加载评分失败', err);
      });
  }, [item, targetType, user]);

  const handleRate = async (score: number) => {
    if (!allowLocalAction('评分')) return;
    if (!item) return;
    // 游客：仅本机评分，不发云端请求
    if (!user) {
      visitorLocalSet('rating', `${targetType}:${item.id}`, score);
      setVisitorScore(score);
      toastVisitorLocal('rating');
      return;
    }
    setRatingLoading(true);
    try {
      const res = await ratings.submit(
        { targetType, targetId: item.id, score },
        getAuthHeaders(),
      );
      setRatingSummary(res);
    } catch (error) {
      logger.error('评分失败', error);
    } finally {
      setRatingLoading(false);
    }
  };

  if (notFound) {
    return (
      <div className="flex min-h-[60vh] flex-col items-center justify-center">
         <p className={`text-gray-400 mb-4 ${sc('text-2xl')}`}>{t('detail.itemNotFound')}</p>
         <button
           onClick={handleBack}
           className={`flex items-center gap-2 px-4 py-2 rounded-lg bg-cyan-500/20 border border-cyan-400/50 text-cyan-300 ${sc('text-xl')} hover:bg-cyan-500/30 transition-colors`}
         >
          <ArrowLeft className="w-4 h-4" />
          {t('detail.backToEncy')}
        </button>
      </div>
    );
  }

  if (!item) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <Loader2 className="w-8 h-8 text-cyan-400 animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen text-white max-w-4xl mx-auto">
      {/* 返回按钮 */}
       <button
         onClick={handleBack}
         className={`mb-2 flex items-center gap-1.5 ${sc('text-3xl')} text-gray-400 hover:text-cyan-300 transition-colors`}
       >
        <ArrowLeft className="w-5 h-5" />
        {t('detail.backList')}
      </button>

      {/* 头部信息 */}
      <div
        className={`relative rounded-2xl border p-3 mb-2.5 backdrop-blur-sm ${
          isStCategory
            ? 'border-pink-400/50 bg-gradient-to-br from-pink-500/10 to-purple-600/10'
            : 'border-cyan-400/40 bg-[#141838]/60'
        }`}
      >
        {/* ST 徽章 */}
        {isStCategory && (
          <div className="absolute top-4 right-4 z-20 flex h-10 w-10 items-center justify-center rounded-lg bg-gradient-to-br from-pink-500 to-rose-600 text-lg font-bold text-white shadow-[0_0_15px_rgba(236_72_153_0.6)]">
            ST
          </div>
        )}

        <div className="flex items-start justify-between gap-4">
          <div>
              <p className={`${sc('text-xl')} text-gray-400 mb-1`}>
               {t('enc.cat.' + categoryKey)}
             </p>
            <h1
              className={`${sc('text-3xl')} font-bold mb-1 ${
                isStCategory ? 'text-pink-200 text-glow-magenta' : 'text-white'
              }`}
            >
              {lang === 'en' ? item.nameEn : item.nameZh}
            </h1>
             <p className={`${sc('text-xl')} text-gray-400 mb-3`}>{lang === 'en' ? item.nameZh : item.nameEn}</p>

            <div className="flex flex-wrap gap-2">
              {item.type && (
                <span
                  className={`${sc('text-2xl')} px-4 py-1.5 rounded-full border ${
                    isStCategory
                      ? 'border-pink-400/40 text-pink-300 bg-pink-500/10'
                      : 'border-cyan-400/40 text-cyan-300 bg-cyan-500/10'
                  }`}
                >
                  {trTerm(item.type)}
                </span>
              )}
              {item.positions && (
                 <span className={`${sc('text-2xl')} px-4 py-1.5 rounded-full border border-white/15 text-gray-400 bg-white/5`}>
                   {item.positions}
                 </span>
              )}
            </div>
          </div>

          {/* 评分区 */}
          <div className="flex-shrink-0">
            {ratingSummary ? (
              <div className="text-right">
                <RatingStars
                  value={
                    !user
                      ? (visitorScore ?? ratingSummary.average)
                      : (ratingSummary.userScore ?? ratingSummary.average)
                  }
                  count={ratingSummary.count}
                  interactive
                  size="lg"
                  onRate={handleRate}
                />
                 {ratingLoading && (
                   <p className="text-lg text-gray-500 mt-1">{t('detail.submitting')}</p>
                 )}
              </div>
            ) : (
              <div className="flex items-center justify-end">
                <Loader2 className="w-5 h-5 text-cyan-400 animate-spin" />
              </div>
            )}
          </div>
        </div>
      </div>

      {/* 描述（横屏网页下再缩小一档） */}
      <div className="rounded-xl border border-white/10 bg-card/60 p-3 mb-2 backdrop-blur-sm">
          <h3 className={`${compact ? 'text-xl' : 'text-4xl'} font-semibold text-cyan-300 mb-2`}>{t('detail.descTitle')}</h3>
          <p className={`${compact ? 'text-xl' : 'text-4xl'} text-gray-300 leading-relaxed`}>
           {lang === 'en' ? item.descriptionEn : item.descriptionZh}
         </p>
      </div>

      {/* 技能场景配图（描述下方、评论区上方；右下角标注素材来源） */}
      {targetType === 'skill' && skillIconUrl(item.id) && (
        <div className="relative rounded-2xl overflow-hidden border border-white/10 mb-2.5">
          <img
            src={skillIconUrl(item.id)!}
            alt={lang === 'en' ? item.nameEn : item.nameZh}
            loading="lazy"
            className="w-full aspect-[288/173] object-cover"
          />
          <span className="absolute bottom-1 right-1.5 px-1.5 py-0.5 rounded bg-black/35 text-white/75 text-xs pointer-events-none">
            {lang === 'en'
              ? 'Images sourced from the internet'
              : '图片素材来自网络'}
          </span>
        </div>
      )}

      {/* 评论区 */}
      <CommentSection targetType={targetType} targetId={item.id} />

      <div className="h-12" />
    </div>
  );
};

export default EncyclopediaDetailPage;
