/**
 * 游客模式（未登录可用）集中地基
 * --------------------------------
 * 【唯一开关】VISITOR_MODE_ENABLED：一处控制。
 *   - true ：未登录游客可进行「账户数据类」操作，仅持久化到本机 localStorage；
 *   - false：关闭游客模式，这些操作恢复为必须登录（回到全拦状态）。
 *
 * 说明：
 *   - 游客数据统一以 `pts_visitor_*` 为前缀，与登录用户云端数据完全隔离；
 *   - 仅存本机：换设备 / 清缓存即失效；登录后不会自动合并；
 *   - 「保存培养/技能方案」「发帖 / 评论 / 回复」不在此列，始终强制登录
 *     （继续使用 useLoginGuard 的 requireLogin）。
 */

import { toast } from 'sonner';

// ====================================================================
// 1. 集中开关（需要关闭游客模式时，把这里改为 false 即可，无需改动其它文件）
// ====================================================================
export const VISITOR_MODE_ENABLED = true;

/** 当前是否为未登录游客 */
export function isVisitor(user: unknown): boolean {
  return !user;
}

/**
 * 游客是否被允许进行「账户数据类」本地操作。
 * 已登录 -> 走云端（返回 false 表示不应走本地分支）；
 * 未登录且开关开 -> true；未登录且开关关 -> false。
 */
export function canUseVisitorLocal(
  user: unknown,
  enabled: boolean = VISITOR_MODE_ENABLED,
): boolean {
  return !user && enabled;
}

// 统一前缀，便于识别与清理
const PREFIX = 'pts_visitor_';

function safeParse(raw: string | null): string[] {
  if (raw === null) return [];
  try {
    const v = JSON.parse(raw);
    return Array.isArray(v) ? v.filter((x) => typeof x === 'string') : [];
  } catch {
    return [];
  }
}

// ====================================================================
// 2. 集合型本地存储（布尔开关类：点赞 / 收藏 / 关注）
//    每个 kind 对应一个 id 集合；toggle 切换成员关系。
// ====================================================================
export type VisitorSetKind =
  | 'favorite_player'
  | 'favorite_coach'
  | 'favorite_pack'
  | 'favorite_forum_post'
  | 'player_like'
  | 'comment_like'
  | 'follow_user';

function setStorageKey(kind: VisitorSetKind): string {
  return `${PREFIX}set_${kind}`;
}

function readSet(kind: VisitorSetKind): Set<string> {
  if (typeof window === 'undefined') return new Set();
  return new Set(safeParse(window.localStorage.getItem(setStorageKey(kind))));
}

function writeSet(kind: VisitorSetKind, set: Set<string>): void {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(
      setStorageKey(kind),
      JSON.stringify(Array.from(set)),
    );
  } catch {
    // 隐私模式 / 配额不足时静默失败
  }
}

/** 游客本地集合中是否包含指定 id */
export function visitorLocalHas(kind: VisitorSetKind, id: string): boolean {
  if (!VISITOR_MODE_ENABLED) return false; // 开关关闭：不呈现任何本地态
  if (!id) return false;
  return readSet(kind).has(id);
}

/**
 * 切换游客本地集合成员关系，返回切换后的状态（true=已加入）。
 * 开关关闭时不写入，返回 false（动作入口应改用 allowLocalAction 弹出登录）。
 */
export function visitorLocalToggle(kind: VisitorSetKind, id: string): boolean {
  if (!VISITOR_MODE_ENABLED) return false;
  if (!id) return false;
  const set = readSet(kind);
  const next = !set.has(id);
  if (next) set.add(id);
  else set.delete(id);
  writeSet(kind, set);
  return next;
}

/** 返回某类集合的全部 id（如游客收藏的球员列表） */
export function visitorLocalList(kind: VisitorSetKind): string[] {
  if (!VISITOR_MODE_ENABLED) return [];
  return Array.from(readSet(kind));
}

// ====================================================================
// 3. 键值型本地存储（单值类：论坛投票 like/dislike、星级评分 1-5）
// ====================================================================
export type VisitorKvKind = 'forum_vote' | 'rating';

function kvStorageKey(kind: VisitorKvKind): string {
  return `${PREFIX}kv_${kind}`;
}

function readKvMap(kind: VisitorKvKind): Record<string, string> {
  if (typeof window === 'undefined') return {};
  try {
    const raw = window.localStorage.getItem(kvStorageKey(kind));
    if (!raw) return {};
    const v = JSON.parse(raw);
    return v && typeof v === 'object' ? (v as Record<string, string>) : {};
  } catch {
    return {};
  }
}

function writeKvMap(kind: VisitorKvKind, map: Record<string, string>): void {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(kvStorageKey(kind), JSON.stringify(map));
  } catch {
    // ignore
  }
}

/** 读取游客本地单值；不存在返回 null */
export function visitorLocalGet(
  kind: VisitorKvKind,
  key: string,
): string | null {
  if (!VISITOR_MODE_ENABLED) return null; // 开关关闭：不呈现本地值
  if (!key) return null;
  const v = readKvMap(kind)[key];
  return v === undefined ? null : v;
}

/** 写入游客本地单值；传 null / 空串表示移除。开关关闭时不写入。 */
export function visitorLocalSet(
  kind: VisitorKvKind,
  key: string,
  value: string | number | null,
): void {
  if (!VISITOR_MODE_ENABLED) return;
  if (!key) return;
  const map = readKvMap(kind);
  if (value === null || value === '') {
    delete map[key];
  } else {
    map[key] = String(value);
  }
  writeKvMap(kind, map);
}

// ====================================================================
// 4. 文档集合型本地存储（阵容 / 强度榜：整条文档的增删改查）
// ====================================================================
export type VisitorDocKind = 'lineup' | 'tierlist';

function docStorageKey(kind: VisitorDocKind): string {
  return `${PREFIX}docs_${kind}`;
}

/** 列出游客本地某类的全部文档（按更新时间倒序） */
export function visitorLocalListDocs<T extends { id: string; updatedAt?: string }>(
  kind: VisitorDocKind,
): T[] {
  if (!VISITOR_MODE_ENABLED) return []; // 开关关闭：不呈现本地文档
  if (typeof window === 'undefined') return [];
  try {
    const raw = window.localStorage.getItem(docStorageKey(kind));
    const arr = raw ? (JSON.parse(raw) as T[]) : [];
    if (!Array.isArray(arr)) return [];
    return [...arr].sort((a, b) =>
      String(b.updatedAt ?? '').localeCompare(String(a.updatedAt ?? '')),
    );
  } catch {
    return [];
  }
}

/** 读取单条游客本地文档 */
export function visitorLocalGetDoc<T extends { id: string }>(
  kind: VisitorDocKind,
  docId: string,
): T | null {
  if (!VISITOR_MODE_ENABLED) return null;
  if (!docId) return null;
  const all = visitorLocalListDocs<T>(kind);
  return all.find((d) => d.id === docId) ?? null;
}

/** 插入或更新一条游客本地文档（按 id 去重）。开关关闭时不写入。 */
export function visitorLocalUpsertDoc<T extends { id: string }>(
  kind: VisitorDocKind,
  doc: T,
): void {
  if (!VISITOR_MODE_ENABLED) return;
  if (!doc?.id) return;
  const all = visitorLocalListDocs<T>(kind);
  const idx = all.findIndex((d) => d.id === doc.id);
  if (idx >= 0) all[idx] = doc;
  else all.unshift(doc);
  try {
    window.localStorage.setItem(docStorageKey(kind), JSON.stringify(all));
  } catch {
    // 配额不足（文档过大）时静默失败
  }
}

/** 删除一条游客本地文档。开关关闭时不写入。 */
export function visitorLocalRemoveDoc(kind: VisitorDocKind, docId: string): void {
  if (!VISITOR_MODE_ENABLED) return;
  if (!docId) return;
  const all = visitorLocalListDocs<{ id: string }>(kind).filter(
    (d) => d.id !== docId,
  );
  try {
    window.localStorage.setItem(docStorageKey(kind), JSON.stringify(all));
  } catch {
    // ignore
  }
}

/** 生成游客本地文档 id（与云端 id 区分，避免误当云端记录） */
export function visitorLocalDocId(): string {
  return `local_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

// ====================================================================
// 5. 游客提示
// ====================================================================
export const VISITOR_TIP = '游客模式仅本机保存，登录后可永久保存';

// 本次会话内已弹过 toast 的 kind，避免每次操作都打扰
const toasted = new Set<string>();

/**
 * 游客首次进行某类本地保存时弹一次提示 toast。
 * @param dedupKey 去重维度（如 'favorite' / 'lineup'）
 */
export function toastVisitorLocal(dedupKey = 'default'): void {
  if (typeof window === 'undefined') return;
  if (toasted.has(dedupKey)) return;
  toasted.add(dedupKey);
  toast.info(VISITOR_TIP);
}
