import { useEffect, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Capacitor } from '@capacitor/core';
import { App } from '@capacitor/app';
import { runBackIntercept } from '@client/src/utils/back-intercept';

/**
 * 根级路由：在这些页面按硬件返回 / 边缘内滑，直接退出 APP（仅安卓）/ 停留当前页（iOS）。
 * 其余页面一律「返回上一页」。
 */
const ROOT_PATHS = new Set([
  '/',
  '/players',
  '/rankings',
  '/coaches',
  '/packs',
  '/encyclopedia',
  '/forum',
  '/profile',
]);

function normalizePath(pathname: string): string {
  const p = pathname.replace(/\/+$/, '');
  return p === '' ? '/' : p;
}

/**
 * 全局接管原生返回：
 * - Android：硬件返回键（App.backButton）
 * - iOS：Capacitor 为单 WKWebView，SPA 的 pushState 路由不属于系统原生历史，
 *   系统自带的边缘滑动 pop 手势对网页无效；这里在【左边缘 ~24px 内右滑】时
 *   手动触发网页返回，模拟 iOS 原生边缘返回。
 * 必须在 Router 内部调用一次。
 */
export function useNativeBackButton(): void {
  const location = useLocation();
  const navigate = useNavigate();
  // 记录本次启动以来在应用内走过的页面数（用于判断是否还有上一页）
  const stackDepth = useRef(1);

  useEffect(() => {
    stackDepth.current += 1;
  }, [location.pathname]);

  // 统一的“返回”决策（安卓硬件键 / iOS 边缘手势共用），用 ref 避免 listener 闭包过期
  const goBackRef = useRef<() => void>(() => undefined);
  goBackRef.current = () => {
    // 页面内部上下级导航（如榜单子页）优先：返回上级菜单，不退出/不路由回退
    if (runBackIntercept()) return;
    const path = normalizePath(location.pathname);
    if (ROOT_PATHS.has(path)) {
      // 根级页：安卓直接退出 App；iOS 无退出必要，停留当前页
      if (Capacitor.getPlatform() === 'android') void App.exitApp();
      return;
    }
    // 非根页面：优先返回上一页；历史栈为空（如深链直接进入）则回球员页
    if (stackDepth.current > 1) {
      navigate(-1);
    } else {
      navigate('/players');
    }
  };

  // —— Android：硬件返回键 ——
  useEffect(() => {
    if (Capacitor.getPlatform() !== 'android') return undefined;

    let handle: { remove: () => Promise<void> } | undefined;
    let active = true;

    App.addListener('backButton', () => {
      goBackRef.current();
    }).then((h) => {
      if (active) handle = h;
      else void h.remove();
    });

    return () => {
      active = false;
      void handle?.remove();
    };
  }, []);

  // —— iOS：左边缘右滑返回 ——
  useEffect(() => {
    if (Capacitor.getPlatform() !== 'ios') return undefined;

    const EDGE_PX = 24;   // 仅在距左边缘 24px 内起手才触发
    const THRESHOLD_PX = 70; // 右滑超过 70px 才判定为返回
    let startX = 0;
    let startY = 0;
    let tracking = false;
    let fired = false;

    const onTouchStart = (e: TouchEvent) => {
      const t = e.touches[0];
      if (!t) return;
      if (t.clientX <= EDGE_PX) {
        tracking = true;
        fired = false;
        startX = t.clientX;
        startY = t.clientY;
      }
    };
    const onTouchMove = (e: TouchEvent) => {
      if (!tracking || fired) return;
      const t = e.touches[0];
      if (!t) return;
      const dx = t.clientX - startX;
      const dy = t.clientY - startY;
      // 以横向右滑为主、且距离超过阈值 → 返回（避免与上下滚动、纵向手势冲突）
      if (dx > THRESHOLD_PX && Math.abs(dx) > Math.abs(dy) * 1.2) {
        fired = true;
        goBackRef.current();
      }
    };
    const onTouchEnd = () => {
      tracking = false;
      fired = false;
    };

    window.addEventListener('touchstart', onTouchStart, { passive: true });
    window.addEventListener('touchmove', onTouchMove, { passive: true });
    window.addEventListener('touchend', onTouchEnd, { passive: true });
    window.addEventListener('touchcancel', onTouchEnd, { passive: true });

    return () => {
      window.removeEventListener('touchstart', onTouchStart);
      window.removeEventListener('touchmove', onTouchMove);
      window.removeEventListener('touchend', onTouchEnd);
      window.removeEventListener('touchcancel', onTouchEnd);
    };
  }, []);
}
