import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';
import type {
  CoachTactic,
  CoachTacticListResponse,
  CoachTacticListQuery,
} from '@shared/api.interface';

export async function getCoachTacticList(
  params: CoachTacticListQuery = {},
): Promise<CoachTacticListResponse> {
  const response = await axiosForBackend.get('/api/coach-tactics', { params });
  return response.data;
}

export async function getCoachTacticDetail(id: string): Promise<CoachTactic> {
  const response = await axiosForBackend.get(`/api/coach-tactics/${id}`);
  return response.data;
}
