import React from 'react';
import type { Player, PositionRatings } from '@shared/api.interface';
import {
  POSITION_HEATMAP_LAYOUT,
  getProficiencyBgStyle,
  getProficiencyLevel,
} from '@client/src/components/heatmap/position-heatmap-common';
import { useIsNarrowScreen } from '@client/src/hooks/useIsNarrowScreen';

interface ComparePositionHeatmapProps {
  playerList: Player[];
  computedPositionRatings?: Record<string, PositionRatings>;
}

const PLAYER_COLORS = [
  '#00E5FF',
  '#FF9F1C',
  '#4ADE80',
  '#A78BFA',
  '#22D3EE',
  '#F472B6',
];

const POSITION_KEY_MAP: Record<string, keyof PositionRatings> = {
  GK: 'goalkeeper',
  LB: 'leftBack',
  CB: 'centerBack',
  RB: 'rightBack',
  DMF: 'defensiveMidfielder',
  LMF: 'leftMidfielder',
  CMF: 'centralMidfielder',
  RMF: 'rightMidfielder',
  AMF: 'attackingMidfielder',
  LWF: 'leftWing',
  SS: 'secondStriker',
  RWF: 'rightWing',
  CF: 'centerForward',
};

function getPositionRating(
  player: Player,
  posKey: string,
  computedPositionRatings?: Record<string, PositionRatings>,
): number {
  const ratingKey = POSITION_KEY_MAP[posKey];
  if (!ratingKey) return 0;
  const computed = computedPositionRatings?.[player.id];
  if (computed && computed[ratingKey] != null) return computed[ratingKey];
  return player.positionRatings?.[ratingKey] ?? 0;
}

interface SingleHeatmapProps {
  player: Player;
  accentColor: string;
  computedPositionRatings?: Record<string, PositionRatings>;
}

const SingleHeatmap: React.FC<SingleHeatmapProps> = ({
  player,
  accentColor,
  computedPositionRatings,
}) => {
  const phone = useIsNarrowScreen();
  const gridStyle: React.CSSProperties = {
    display: 'grid',
    gridTemplateColumns: '1fr 1fr 1fr',
    gridTemplateRows: 'repeat(7, minmax(0, 1fr))',
    gap: '2px',
    height: '100%',
    width: '100%',
  };

  const getCellStyle = (cell: (typeof POSITION_HEATMAP_LAYOUT)[number]): React.CSSProperties => {
    const proficiency = getProficiencyLevel(
      cell.key,
      player.position,
      player.positionProficiency,
    );
    const bgStyle = getProficiencyBgStyle(proficiency);
    const isHorizontal = cell.layout === 'horizontal';
    const isRegistered = cell.key === player.position;
    return {
      ...bgStyle,
      gridRow: `${cell.row} / span ${cell.rowSpan}`,
      gridColumn: `${cell.col} / span ${cell.colSpan}`,
      borderRadius: '5px',
      display: 'flex',
      flexDirection: isHorizontal ? 'row' : 'column',
      alignItems: 'center',
      justifyContent: 'center',
      gap: isHorizontal ? '4px' : '1px',
      padding: '1px 3px',
      transition: 'all 0.2s ease',
      border: isRegistered
        ? `2px solid ${accentColor}`
        : '1px solid rgba(255,255,255,0.08)',
      boxShadow: isRegistered
        ? `0 0 12px ${accentColor}99, 0 0 4px ${accentColor}66`
        : bgStyle.boxShadow,
      overflow: 'hidden',
    };
  };

  const abbrStyle = (isHorizontal: boolean): React.CSSProperties => ({
    fontSize: isHorizontal ? (phone ? '12px' : '8px') : (phone ? '13px' : '9px'),
    fontWeight: 600,
    opacity: 0.85,
    lineHeight: 1,
    whiteSpace: 'nowrap',
  });

  const numStyle = (isHorizontal: boolean): React.CSSProperties => ({
    fontSize: isHorizontal ? (phone ? '18px' : '12px') : (phone ? '19px' : '13px'),
    fontWeight: 800,
    lineHeight: 1,
    letterSpacing: '-0.3px',
    whiteSpace: 'nowrap',
  });

  return (
    <div className="min-w-0 flex flex-col items-center gap-2">
      <div
        className="w-full rounded-xl border bg-[#0d1230] p-1.5"
        style={{ borderColor: `${accentColor}40` }}
      >
        <div className="relative w-full" style={{ aspectRatio: phone ? '3 / 3.94' : '3 / 2.625' }}>
          <div style={gridStyle}>
            {POSITION_HEATMAP_LAYOUT.map((cell) => {
              const isHorizontal = cell.layout === 'horizontal';
              const rating = getPositionRating(
                player,
                cell.key,
                computedPositionRatings,
              );
              return (
                <div
                  key={cell.key}
                  style={getCellStyle(cell)}
                  title={`${cell.key} · 总评 ${rating}`}
                >
                  <span style={abbrStyle(isHorizontal)}>{cell.key}</span>
                  <span style={numStyle(isHorizontal)}>
                    {rating || '-'}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      </div>
      <div className="text-center w-full min-w-0 px-1">
        <p className={`font-bold text-white truncate ${phone ? 'text-xl' : 'text-sm'}`}>{player.nameZh}</p>
        {player.nameEn && (
          <p className={`text-gray-500 truncate ${phone ? 'text-base' : 'text-xs'}`}>{player.nameEn}</p>
        )}
      </div>
    </div>
  );
};

const ComparePositionHeatmap: React.FC<ComparePositionHeatmapProps> = ({
  playerList,
  computedPositionRatings,
}) => {
  return (
    <div className="rounded-xl bg-[#141838] border border-white/10 overflow-hidden">
      <div className="px-3 sm:px-4 py-2 sm:py-3 bg-white/[0.03]">
        <div className="flex items-center gap-2">
          <span className="w-1 h-4 sm:h-5 bg-gradient-to-b from-amber-400 to-orange-500 rounded-full" />
          <h3 className="text-lg sm:text-2xl font-bold text-white">位置热区对比</h3>
          <span className="text-sm sm:text-lg text-gray-500">13 个位置总评</span>
        </div>
      </div>

      <div className="px-3 sm:px-4 py-3 sm:py-4">
        <div
          className="grid gap-3 sm:gap-4"
          style={{
            gridTemplateColumns: `repeat(${playerList.length}, minmax(0, 1fr))`,
          }}
        >
          {playerList.map((p, idx) => (
            <SingleHeatmap
              key={p.id}
              player={p}
              accentColor={PLAYER_COLORS[idx % PLAYER_COLORS.length]}
              computedPositionRatings={computedPositionRatings}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export default ComparePositionHeatmap;
