/**
 * 状态栏适配（仅原生 App）。
 * 我们整体是深色背景，需要把状态栏顶部的文字/图标设为浅色（白色），
 * 否则系统默认黑色图标会与深色背景融为一体、看不清。
 *
 * 同时读取“原生状态栏高度”写入 CSS 变量 --app-statusbar-height。
 * 原因：部分安卓 WebView / OEM ROM 会把 env(safe-area-inset-top) 报成 0，
 * 导致顶部按钮被状态栏压住；原生高度更可靠，样式里取二者较大值。
 */
import { Capacitor } from '@capacitor/core';
import { StatusBar, Style } from '@capacitor/status-bar';

let started = false;

function applyHeight(height: number): void {
  const px = Number.isFinite(height) && height > 0 ? Math.ceil(height) : 0;
  document.documentElement.style.setProperty('--app-statusbar-height', `${px}px`);
}

export async function setupStatusBar(): Promise<void> {
  if (started) return;
  if (!Capacitor.isNativePlatform()) return;
  started = true;
  try {
    // 深色背景 → 浅色文字/图标
    await StatusBar.setStyle({ style: Style.Dark });
    // 内容（背景图）延伸到状态栏下方；按钮通过 safe-area-inset 避让
    // Android 15+ 强制 edge-to-edge，此调用在不支持的平台上会被忽略
    await StatusBar.setOverlaysWebView({ overlay: true }).catch(() => undefined);

    // 读取原生状态栏高度，作为 env() 失效时的兜底
    try {
      // iPad（iPadOS）WKWebView 可能把 safe-area-inset-top 与状态栏高度都报成 0，
      // 导致顶部导航被状态栏压住；iOS 统一保底 24px（iPhone 刘海的 env 更大，不受影响）。
      const iosMinTop = Capacitor.getPlatform() === 'ios' ? 24 : 0;
      const info = await StatusBar.getInfo();
      applyHeight(
        info.overlays === false ? 0 : Math.max(Number(info.height) || 0, iosMinTop),
      );
      StatusBar.addListener?.('statusBarInfoDidChange', (i) => {
        applyHeight(
          i.overlays === false ? 0 : Math.max(Number(i.height) || 0, iosMinTop),
        );
      }).catch(() => undefined);
    } catch {
      // getInfo 失败时：iOS 仍写入保底，避免 iPad 顶部遮挡
      if (Capacitor.getPlatform() === 'ios') applyHeight(24);
      /* 取不到高度就退回纯 env() */
    }
  } catch {
    // 状态栏设置失败不应阻断启动
  }
}
