import { logger } from '@lark-apaas/client-toolkit/logger';
import { axiosForBackend } from '@lark-apaas/client-toolkit/utils/getAxiosForBackend';

// 球员在阵容中的快照 + 自由点位（x/y 为相对球场区域的 0..1）
export interface LineupItemSnapshot {
  playerId: string;
  nameZh: string;
  nameEn: string;
  position?: string;
  playerImageUrl?: string | null;
  x: number;
  y: number;
}

export interface LineupPayload {
  name: string;
  items: LineupItemSnapshot[];
}

export interface LineupSummary {
  id: string;
  name: string;
  itemCount: number;
  updatedAt: string;
}

export interface LineupDetail extends LineupPayload {
  id: string;
  userId: string;
  createdAt: string;
  updatedAt: string;
}

export async function saveLineup(
  payload: LineupPayload,
  id: string | null,
  headers?: Record<string, string>,
): Promise<{ id: string; updatedAt: string }> {
  try {
    const res = await axiosForBackend.post<{ id: string; updatedAt: string }>(
      '/api/lineups',
      { id, ...payload },
      { headers },
    );
    return res.data;
  } catch (error) {
    logger.error('保存阵容失败', error);
    throw error;
  }
}

export async function getMyLineups(
  headers?: Record<string, string>,
): Promise<{ items: LineupSummary[] }> {
  try {
    const res = await axiosForBackend.get<{ items: LineupSummary[] }>(
      '/api/lineups/my',
      { headers },
    );
    return res.data;
  } catch (error) {
    logger.error('获取我的阵容失败', error);
    throw error;
  }
}

export async function getLineup(id: string): Promise<LineupDetail> {
  try {
    const res = await axiosForBackend.get<LineupDetail>(`/api/lineups/${id}`);
    return res.data;
  } catch (error) {
    logger.error(`获取阵容失败: ${id}`, error);
    throw error;
  }
}

export async function deleteLineup(
  id: string,
  headers?: Record<string, string>,
): Promise<void> {
  try {
    await axiosForBackend.delete(`/api/lineups/${id}`, { headers });
  } catch (error) {
    logger.error(`删除阵容失败: ${id}`, error);
    throw error;
  }
}
