import React from 'react';
import { Play } from 'lucide-react';
import { Image } from '@client/src/components/ui/image';
import type { MediaItem } from '@client/src/api/forum';

interface PostMediaPreviewProps {
  mediaList: MediaItem[];
}

/** 列表中最多铺 9 个缩略图，超出在最后一格用 +N 表示 */
const MAX_VISIBLE = 9;

/**
 * 帖子列表里的媒体预览（参考懂球帝式）：
 * - 1 个：较小的方形缩略图（约占卡片 46% 宽）
 * - 2 个：两列、限宽
 * - 3 个及以上：三列方形网格满宽
 * 视频缩略图中央带播放角标；点击任意位置由外层卡片统一跳详情。
 */
const PostMediaPreview: React.FC<PostMediaPreviewProps> = ({ mediaList }) => {
  if (!mediaList || mediaList.length === 0) return null;

  const total = mediaList.length;
  const visible = mediaList.slice(0, MAX_VISIBLE);

  const wrapClass =
    total === 1
      ? 'w-[46%] max-w-[300px]'
      : total === 2
        ? 'grid w-[72%] max-w-[440px] grid-cols-2 gap-1.5'
        : 'grid grid-cols-3 gap-1.5';

  return (
    <div className={wrapClass}>
      {visible.map((m, idx) => {
        const isLast = idx === visible.length - 1;
        const showOverflow = total > MAX_VISIBLE && isLast;
        return (
          <div
            key={`${m.filename}-${idx}`}
            className="relative aspect-square overflow-hidden rounded-lg border border-white/10 bg-black/40"
          >
            {m.type === 'video' ? (
              <>
                <video
                  src={m.url}
                  preload="metadata"
                  muted
                  playsInline
                  className="h-full w-full object-cover"
                />
                <span className="absolute inset-0 flex items-center justify-center bg-black/25">
                  <Play className="h-7 w-7 fill-white/90 text-white/90" />
                </span>
              </>
            ) : (
              <Image
                src={m.url}
                alt={m.filename}
                className="h-full w-full object-cover"
                loading="lazy"
              />
            )}
            {showOverflow && (
              <span className="absolute inset-0 flex items-center justify-center bg-black/65 text-lg font-bold text-white">
                +{total - MAX_VISIBLE + 1}
              </span>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default PostMediaPreview;
