/**
 * 球员详情页「闪耀 / 教练」按账号锁定的本地持久化。
 * 以登录用户 id 作为 key 的一部分，因此同一设备上不同账号互不影响。
 *
 * 说明：当前实现存于本机 localStorage（设备内跟随账号）；
 * 若要跨设备同步，需要后端在用户记录上增加 preferences 字段。
 */

export type LockKind = 'shine' | 'coach';

export function lockStorageKey(kind: LockKind, userId: string | null | undefined): string {
  const uid = userId && userId.trim().length > 0 ? userId : 'anonymous';
  return `pts_lock_${kind}_${uid}`;
}

export function readLock<T>(kind: LockKind, userId: string | null | undefined): T | null {
  try {
    const raw = localStorage.getItem(lockStorageKey(kind, userId));
    if (raw === null) return null;
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}

export function writeLock<T>(kind: LockKind, userId: string | null | undefined, value: T): void {
  try {
    localStorage.setItem(lockStorageKey(kind, userId), JSON.stringify(value));
  } catch {
    // 隐私模式 / 配额不足时静默失败
  }
}

export function clearLock(kind: LockKind, userId: string | null | undefined): void {
  try {
    localStorage.removeItem(lockStorageKey(kind, userId));
  } catch {
    // ignore
  }
}
