import { useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import { useAuth } from '../context/AuthContext';
import { VISITOR_MODE_ENABLED } from '../utils/visitor-mode';

/**
 * 登录守卫。
 *
 * 两类闸门：
 *  - requireLogin(action)：始终强制登录。
 *      用于「保存培养/技能方案」「发帖 / 评论 / 回复」等必须关联账号的动作。
 *  - allowLocalAction(action)：账户数据类动作（点赞/收藏/关注/投票/评分/阵容/强度榜）。
 *      已登录 -> true（调用方走云端）；
 *      未登录且游客开关开 -> true（调用方走 visitor-mode 的本地 localStorage 分支）；
 *      未登录且游客开关关 -> false，并按原方式 toast + 跳转登录页。
 */
export function useLoginGuard() {
  const { user } = useAuth();
  const navigate = useNavigate();

  const redirectToAuth = useCallback(() => {
    navigate('/auth', { state: { from: window.location.pathname } });
  }, [navigate]);

  const requireLogin = useCallback(
    (action = '进行此操作'): boolean => {
      if (user) return true;
      toast.info(`请先登录后再${action}`);
      redirectToAuth();
      return false;
    },
    [user, redirectToAuth],
  );

  const allowLocalAction = useCallback(
    (action = '进行此操作'): boolean => {
      if (user) return true;
      if (VISITOR_MODE_ENABLED) return true;
      // 游客模式已关闭：恢复为必须登录
      toast.info(`请先登录后再${action}`);
      redirectToAuth();
      return false;
    },
    [user, redirectToAuth],
  );

  return {
    user,
    requireLogin,
    allowLocalAction,
    visitorMode: VISITOR_MODE_ENABLED,
  };
}
