/**
 * 原生分享（仅原生 App）。
 * 调起安卓系统分享面板，可分享到微信、QQ 等已安装的应用。
 * 返回 true 表示已由原生处理（无论用户是否取消），false 表示非原生环境。
 */
import { Capacitor } from '@capacitor/core';
import { Share } from '@capacitor/share';

export async function nativeShare(opts: {
  title: string;
  url: string;
  text?: string;
}): Promise<boolean> {
  if (!Capacitor.isNativePlatform()) return false;
  try {
    const canShare = await Share.canShare().catch(() => ({ value: true }));
    if (canShare && canShare.value === false) return false;
    await Share.share({
      title: opts.title,
      text: opts.text ?? opts.title,
      url: opts.url,
      dialogTitle: opts.title,
    });
  } catch {
    // 用户取消或分享失败，均视为已走原生流程，不再降级
  }
  return true;
}
