export interface CommonSkillEntry {
  /** 标准名（入库 / 展示统一使用这个名字） */
  zhName: string;
  /** 可识别别名（导入 / 匹配 / 审计时自动归一到标准名） */
  aliases: string[];
}

/**
 * 普通技能（非 ST 技能）别名表，统一“标准名 ↔ 别名”口径。
 * 以后再发现同义技能，只需在对应技能的 aliases 里追加一行，
 * 导入解析、客户端展示/匹配、服务端审计都会自动归一，无需改多处。
 */
export const COMMON_SKILLS: CommonSkillEntry[] = [
  // Double Touch：“双触 / 双触过人”统一标准名为“两次触球”
  { zhName: '两次触球', aliases: ['双触', '双触过人'] },
  // Marseille Turn：标准名“马赛回旋”，繁体/粤语旧名“施丹式转身”（施丹=齐达内）为别名
  { zhName: '马赛回旋', aliases: ['施丹式转身'] },
  // 门将高空大脚开球：标准名取短名“门将踢高球”（省字便于显示），
  // 百科长名“门将高空长传”、旧抓取名“守门员踢高球”均为别名
  { zhName: '门将踢高球', aliases: ['门将高空长传', '守门员踢高球', '守门员高弹道凌空球'] },
  // 门将低平大脚开球：标准名“门将踢低球”，
  // 百科长名“门将低空长传”、旧抓取名“守门员踢低球”均为别名
  { zhName: '门将踢低球', aliases: ['门将低空长传', '守门员踢低球', '守门员低弹道凌空球'] },
  // 门将长距离手抛球：标准名“门将大力手抛球”，百科长名“门将远距离投掷”为别名。
  // 注意：勿与外场球员的“大力手抛球”（Long Throws，界外球）混为一谈，二者不是同一技能
  { zhName: '门将大力手抛球', aliases: ['门将远距离投掷', '守门员长距离投掷'] },
  // 门将扑点球：标准名“门将扑点球”，旧抓取名“守门员扑点球”为别名
  { zhName: '门将扑点球', aliases: ['守门员扑点球'] },
];

function normalizeForCompare(name: string): string {
  return String(name ?? '').trim().toLowerCase().replace(/\s+/g, '');
}

const ALIAS_TO_CANONICAL: Record<string, string> = {};
for (const s of COMMON_SKILLS) {
  ALIAS_TO_CANONICAL[normalizeForCompare(s.zhName)] = s.zhName;
  for (const a of s.aliases) {
    ALIAS_TO_CANONICAL[normalizeForCompare(a)] = s.zhName;
  }
}

/** 把技能名归一到标准名；若不是任何别名则原样（trim 后）返回 */
export function normalizeCommonSkillName(name: string): string {
  const key = normalizeForCompare(name);
  return ALIAS_TO_CANONICAL[key] ?? String(name ?? '').trim();
}

/** 是否为可识别的普通技能（标准名或别名） */
export function isCommonSkill(name: string): boolean {
  return Object.prototype.hasOwnProperty.call(ALIAS_TO_CANONICAL, normalizeForCompare(name));
}

/** 取某技能的“标准名 + 全部别名” */
export function getCommonSkillAliases(name: string): string[] {
  const canonical = ALIAS_TO_CANONICAL[normalizeForCompare(name)];
  if (!canonical) return [String(name ?? '').trim()];
  const entry = COMMON_SKILLS.find((s) => s.zhName === canonical);
  return entry ? [entry.zhName, ...entry.aliases] : [canonical];
}

/** 标准普通技能名列表（去重、保持顺序） */
export const COMMON_SKILL_CANONICAL_NAMES: string[] = COMMON_SKILLS.map((s) => s.zhName);
