import React, { useEffect, useRef, useState } from 'react';
import { ArrowLeft, Loader2, Pencil, Pin, Share2, Trash2 } from 'lucide-react';
import { useNavigate, useParams } from 'react-router-dom';
import { toast } from 'sonner';
import { logger } from '@lark-apaas/client-toolkit/logger';

import {
  deleteNews,
  getNewsDetail,
  getNewsList,
  NEWS_PLATFORMS,
  updateNews,
} from '@client/src/api/news';
import type {
  NewsArticle,
  NewsImageLayout,
  NewsPlatform,
  NewsStatus,
} from '@shared/api.interface';
import NewsCarousel from './NewsCarousel';
import { useI18n } from '@client/src/i18n/I18nProvider';
import { useAuth } from '@client/src/context/AuthContext';
import CommentSection from '@client/src/components/CommentSection';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@client/src/components/ui/dialog';
import { renderNewsShareCanvas } from '@client/src/utils/news-share-image';
import { saveOrShareImage } from '@client/src/utils/native-image';

// ISO 时间 -> datetime-local 输入值（本地时区 yyyy-MM-ddTHH:mm）
const toLocalInput = (iso: string): string => {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const p = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(
    d.getHours(),
  )}:${p(d.getMinutes())}`;
};

const inputCls =
  'w-full rounded-md border border-white/15 bg-black/30 px-3 py-2 text-sm text-white outline-none transition focus:border-cyan-400/60';
const labelCls = 'mb-1 block text-xs font-medium text-gray-300';

const NewsDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { t } = useI18n();
  const { user } = useAuth();
  const isAdmin = user?.role === 'admin' || user?.role === 'super_admin';

  const [article, setArticle] = useState<NewsArticle | null>(null);
  const [loading, setLoading] = useState(true);
  const [sharing, setSharing] = useState(false);

  // ---- 编辑表单状态 ----
  const [editOpen, setEditOpen] = useState(false);
  const [editSaving, setEditSaving] = useState(false);
  const [fTitle, setFTitle] = useState('');
  const [fSummary, setFSummary] = useState('');
  const [fTags, setFTags] = useState('');
  const [fPlatform, setFPlatform] = useState<NewsPlatform>('other');
  const [fStatus, setFStatus] = useState<NewsStatus>('published');
  const [fPostedAt, setFPostedAt] = useState('');
  const [fImages, setFImages] = useState('');
  const [fLayout, setFLayout] = useState<NewsImageLayout>('long');
  const [fAuthor, setFAuthor] = useState('');
  const [fAuthorHandle, setFAuthorHandle] = useState('');

  // ---- 删除确认状态 ----
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [pinning, setPinning] = useState(false);
  // 左右滑切换方向：next=下一条（新内容从右滑入）、prev=上一条（从左滑入）
  const [slideDir, setSlideDir] = useState<'next' | 'prev'>('next');

  // 左右滑切换上/下一条：有序 id 列表（与热讯瀑布同序）+ 触摸起点
  const [navIds, setNavIds] = useState<string[]>([]);
  const touchStartRef = useRef<{ x: number; y: number } | null>(null);

  // 拉取一次有序列表，用于定位相邻文章
  useEffect(() => {
    let mounted = true;
    getNewsList({ pageSize: 100 })
      .then((res) => {
        if (mounted) setNavIds(res.items.map((a) => a.id));
      })
      .catch(() => {
        // 列表获取失败时仅禁用滑动切换，不影响正文
      });
    return () => {
      mounted = false;
    };
  }, []);

  useEffect(() => {
    let mounted = true;
    // 切换上/下一条时不显示整页 spinner：仅当当前无内容（首次）才全屏 loading
    setArticle((prev) => {
      if (!prev) setLoading(true);
      return prev;
    });
    getNewsDetail(id || '')
      .then((a) => {
        if (!mounted) return;
        setArticle(a);
        // 文章已删除/不存在：主动从列表缓存移除该 id，普通用户返回即见卡片消失
        if (!a) removeIdFromFeedCache(id || '');
      })
      .finally(() => {
        if (mounted) setLoading(false);
      });
    return () => {
      mounted = false;
    };
  }, [id]);

  // 一键成图：主视觉 + 标题 + 摘要 + 截图 + 宣传语，原生调系统分享 / web 下载
  const handleShare = async () => {
    if (!article || sharing) return;
    setSharing(true);
    try {
      const canvas = await renderNewsShareCanvas(article);
      const url = canvas.toDataURL('image/png');
      await saveOrShareImage(url, `资讯_${article.title || article.id}.png`);
    } catch (shareErr) {
      logger.error('生成资讯分享图失败', shareErr);
      toast.error(t('生成分享图失败，请稍后重试'));
    } finally {
      setSharing(false);
    }
  };

  // 左右滑快速切换上一条 / 下一条（仅触摸）。水平位移需为主且超过阈值，
  // 避免与竖屏上下滚动冲突。
  const SWIPE_THRESHOLD = 55;

// 从 NewsFeed 的 sessionStorage 缓存中移除指定 id（文章被删后，返回列表不再显示该卡片）
function removeIdFromFeedCache(removeId: string): void {
  try {
    const raw = sessionStorage.getItem('news_feed_state');
    if (!raw) return;
    const cache = JSON.parse(raw) as { items?: { id?: string }[] };
    if (!Array.isArray(cache.items)) return;
    cache.items = cache.items.filter((a) => a.id !== removeId);
    sessionStorage.setItem('news_feed_state', JSON.stringify(cache));
  } catch {
    // ignore storage / parse errors
  }
}
  const onTouchStart = (e: React.TouchEvent) => {
    const t0 = e.touches[0];
    touchStartRef.current = { x: t0.clientX, y: t0.clientY };
  };
  const onTouchEnd = (e: React.TouchEvent) => {
    const start = touchStartRef.current;
    touchStartRef.current = null;
    if (!start) return;
    const t1 = e.changedTouches[0];
    const dx = t1.clientX - start.x;
    const dy = t1.clientY - start.y;
    if (Math.abs(dx) < SWIPE_THRESHOLD || Math.abs(dx) <= Math.abs(dy)) return;
    const idx = navIds.indexOf(id || '');
    if (idx < 0) return;
    if (dx < 0) {
      // 左滑 -> 下一条（更旧，index+1）
      const next = navIds[idx + 1];
      if (next) {
        setSlideDir('next');
        navigate(`/news/${next}`, { replace: true });
      } else toast.message('已经是最后一条了');
    } else {
      // 右滑 -> 上一条（更新，index-1）
      const prev = navIds[idx - 1];
      if (prev) {
        setSlideDir('prev');
        navigate(`/news/${prev}`, { replace: true });
      } else toast.message('已经是第一条了');
    }
  };

  // 管理员置顶 / 取消置顶
  const handleTogglePin = async () => {
    if (!article || pinning) return;
    setPinning(true);
    try {
      const updated = await updateNews(article.id, {
        isPinned: !article.isPinned,
      });
      setArticle(updated);
      toast.success(updated.isPinned ? '已置顶到热讯最前' : '已取消置顶');
    } catch (pinErr) {
      logger.error('置顶操作失败', pinErr);
      toast.error('操作失败，请稍后重试');
    } finally {
      setPinning(false);
    }
  };

  // 打开编辑弹窗，用当前内容填充
  const openEdit = () => {
    if (!article) return;
    const edTags = Array.isArray(article.tags) ? article.tags : [];
    const edImages = Array.isArray(article.imageUrls) ? article.imageUrls : [];
    setFTitle(article.title);
    setFSummary(typeof article.summary === 'string' ? article.summary : '');
    setFTags(edTags.join(', '));
    setFPlatform(article.platform);
    setFStatus(article.status);
    setFPostedAt(article.postedAt ? toLocalInput(article.postedAt) : '');
    setFImages(edImages.join('\n'));
    setFLayout(article.imageLayout ?? 'long');
    setFAuthor(article.author || '');
    setFAuthorHandle(article.authorHandle || '');
    setEditOpen(true);
  };

  const handleSaveEdit = async () => {
    if (!article || editSaving) return;
    setEditSaving(true);
    try {
      const tags = fTags
        .split(/[,，\s]+/)
        .map((s) => s.trim())
        .filter(Boolean);
      const imageUrls = fImages
        .split(/\r?\n/)
        .map((s) => s.trim())
        .filter(Boolean);
      const dto: import('@shared/api.interface').NewsUpdateRequest = {
        title: fTitle,
        summary: fSummary,
        tags,
        platform: fPlatform,
        status: fStatus,
        imageUrls,
        imageLayout: fLayout,
        author: fAuthor,
        authorHandle: fAuthorHandle,
      };
      if (fPostedAt) dto.postedAt = new Date(fPostedAt).toISOString();
      const updated = await updateNews(article.id, dto);
      setArticle(updated);
      setEditOpen(false);
      toast.success('热讯已更新');
    } catch (e) {
      logger.error('更新热讯失败', e);
      toast.error('更新失败，请检查权限或稍后重试');
    } finally {
      setEditSaving(false);
    }
  };

  const handleConfirmDelete = async () => {
    if (!article || deleting) return;
    setDeleting(true);
    try {
      await deleteNews(article.id);
      // 清除列表缓存，强制 NewsFeed 返回后重新拉取（被删卡片/概览图不再残留）
      try {
        sessionStorage.removeItem('news_feed_state');
      } catch {
        // ignore
      }
      toast.success('热讯已删除');
      navigate('/news');
    } catch (e) {
      logger.error('删除热讯失败', e);
      toast.error('删除失败，请检查权限或稍后重试');
      setDeleteOpen(false);
    } finally {
      setDeleting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-24">
        <Loader2 className="h-8 w-8 animate-spin text-cyan-400" />
      </div>
    );
  }

  // 无效/残缺数据（已删除但接口返回空对象、或缺关键字段）统一走 notFound，避免后续字段访问崩溃
  if (!article || !article.id) {
    return (
      <div className="mx-auto max-w-3xl px-4 py-16 text-center">
        <p className="text-base text-gray-500">{t('news.notFound')}</p>
        <button
          onClick={() => navigate('/news')}
          className="mt-4 rounded-lg border border-cyan-400/40 bg-cyan-500/10 px-4 py-2 text-sm text-cyan-300"
        >
          {t('news.backToList')}
        </button>
      </div>
    );
  }

  // 字段级兜底：脏数据 / 残缺数据下渲染也不崩溃
  const safeSummary = typeof article.summary === 'string' ? article.summary : '';
  const safeTags: string[] = Array.isArray(article.tags) ? article.tags : [];
  const safeImages: string[] = Array.isArray(article.imageUrls)
    ? article.imageUrls
    : [];

  const paragraphs = safeSummary
    .split(/\n+/)
    .map((s) => s.trim())
    .filter(Boolean);

  return (
    <div
      key={article.id}
      className={`mx-auto w-full max-w-3xl px-4 py-6 landscape:max-w-5xl md:py-8 ${
        slideDir === 'next' ? 'news-slide-next' : 'news-slide-prev'
      }`}
      onTouchStart={onTouchStart}
      onTouchEnd={onTouchEnd}
    >
      {/* 返回 */}
      <button
        onClick={() => navigate('/news')}
        className="mb-4 flex items-center gap-1.5 text-sm text-gray-400 transition hover:text-cyan-300"
      >
        <ArrowLeft className="h-4 w-4" />
        {t('news.backToList')}
      </button>

      {/* 标题 + 管理员操作 + 分享按钮。字号放大仅竖屏/APP 生效，横屏保持原大小 */}
      <div className="portrait:flex portrait:flex-col portrait:gap-4 landscape:flex landscape:flex-row landscape:items-start landscape:justify-between landscape:gap-3">
        <h1 className="font-bold text-white portrait:text-5xl portrait:leading-tight landscape:text-2xl landscape:leading-snug landscape:md:text-[26px]">
          {article.title}
        </h1>
        <div className="flex shrink-0 items-center portrait:gap-3 portrait:self-end landscape:gap-2 landscape:self-auto">
          {/* 仅管理员可见的低调编辑 / 删除图标按钮（普通用户不渲染） */}
          {isAdmin && (
            <>
              <button
                onClick={handleTogglePin}
                disabled={pinning}
                title={article?.isPinned ? t('取消置顶') : t('置顶')}
                aria-label="pin"
                className={`flex items-center justify-center rounded-lg border transition portrait:h-12 portrait:w-12 landscape:h-9 landscape:w-9 ${
                  article?.isPinned
                    ? 'border-cyan-400/70 bg-cyan-500/20 text-cyan-300'
                    : 'border-white/15 bg-white/5 text-gray-300 hover:border-cyan-400/60 hover:text-cyan-300'
                }`}
              >
                {pinning ? (
                  <Loader2 className="animate-spin portrait:h-6 portrait:w-6 landscape:h-4 landscape:w-4" />
                ) : (
                  <Pin
                    className={`portrait:h-6 portrait:w-6 landscape:h-4 landscape:w-4 ${
                      article?.isPinned ? 'fill-cyan-300' : ''
                    }`}
                  />
                )}
              </button>
              <button
                onClick={openEdit}
                title={t('编辑')}
                aria-label="edit"
                className="flex items-center justify-center rounded-lg border border-white/15 bg-white/5 text-gray-300 transition hover:border-cyan-400/60 hover:text-cyan-300 portrait:h-12 portrait:w-12 landscape:h-9 landscape:w-9"
              >
                <Pencil className="portrait:h-6 portrait:w-6 landscape:h-4 landscape:w-4" />
              </button>
              <button
                onClick={() => setDeleteOpen(true)}
                title={t('删除')}
                aria-label="delete"
                className="flex items-center justify-center rounded-lg border border-white/15 bg-white/5 text-gray-300 transition hover:border-red-400/60 hover:text-red-300 portrait:h-12 portrait:w-12 landscape:h-9 landscape:w-9"
              >
                <Trash2 className="portrait:h-6 portrait:w-6 landscape:h-4 landscape:w-4" />
              </button>
            </>
          )}
          <button
            onClick={handleShare}
            disabled={sharing}
            className="flex shrink-0 items-center bg-gradient-to-r from-cyan-500 to-blue-500 font-bold text-white shadow-[0_0_14px_rgba(34_211_238_0.4)] transition hover:brightness-110 disabled:opacity-60 portrait:gap-2.5 portrait:rounded-xl portrait:px-6 portrait:py-3.5 portrait:text-2xl landscape:gap-1.5 landscape:rounded-lg landscape:px-3.5 landscape:py-2 landscape:text-sm"
          >
            {sharing ? (
              <Loader2 className="animate-spin portrait:h-7 portrait:w-7 landscape:h-4 landscape:w-4" />
            ) : (
              <Share2 className="portrait:h-7 portrait:w-7 landscape:h-4 landscape:w-4" />
            )}
            {t('分享')}
          </button>
        </div>
      </div>

      {/* 博主 + 标签行：博主名在最前（可点进博主发帖页），其后标签（可点进同标签）。
          字号较旧版大2档（竖屏 text-2xl / 横屏 text-base）。 */}
      {(article.author || safeTags.length > 0) && (
        <div className="mt-3 flex flex-wrap items-center gap-2">
          {article.author && (
            <button
              onClick={() =>
                navigate(
                  `/news/author/${encodeURIComponent(article.author.trim())}`,
                )
              }
              className="rounded-full border border-cyan-400/40 bg-cyan-400/10 font-semibold text-cyan-300 transition hover:bg-cyan-400/20 portrait:px-4 portrait:py-2 portrait:text-2xl landscape:px-3 landscape:py-1 landscape:text-base"
            >
              @{article.author.trim()}
            </button>
          )}
          {safeTags.map((tag) => (
            <button
              key={tag}
              onClick={() =>
                navigate(`/news/tag/${encodeURIComponent(tag.trim())}`)
              }
              className="rounded-full border border-white/10 bg-white/5 text-gray-300 transition hover:border-cyan-400/40 hover:text-cyan-200 portrait:px-4 portrait:py-2 portrait:text-2xl landscape:px-3 landscape:py-1 landscape:text-base"
            >
              # {tag}
            </button>
          ))}
        </div>
      )}

      {/* 响应式主体：
          竖屏 摘要→截图→评论（上下）；
          横屏 左截图 / 右栏 摘要在上、评论在下 */}
      {/* ===== 竖屏（APP / 竖版网页）：摘要 → 截图 → 评论，线性上下 ===== */}
      <div className="mt-5 flex flex-col landscape:hidden">
        {/* 摘要 */}
        <div className="space-y-3">
          {paragraphs.map((p, i) => (
            <p key={i} className="text-3xl leading-10 text-gray-200">
              {p}
            </p>
          ))}
        </div>

        {/* 截图：宽度撑满、完整展示、不可点开/保存；多图走轮播 */}
        {safeImages.length > 0 && (
          <div className="mt-5 space-y-3">
            {article.imageLayout === 'carousel' ? (
              <NewsCarousel urls={safeImages} />
            ) : (
              safeImages.map((url, i) => (
                <div
                  key={i}
                  className="flex w-full items-center justify-center overflow-hidden rounded-xl border border-white/10 bg-black/30 p-2"
                >
                  <img
                    src={url}
                    alt=""
                    loading="lazy"
                    className="no-save-img h-auto w-full object-contain"
                  />
                </div>
              ))
            )}
          </div>
        )}

        {/* 评论 */}
        <div className="mt-8">
          <CommentSection
            targetType="news_article"
            targetId={article.id}
            sectionId="news-cmt-portrait"
          />
        </div>
      </div>

      {/* ===== 横屏：左列截图（宽度撑满、完整、随页滚动）；右列 摘要在上、评论紧跟在下 ===== */}
      <div className="mt-5 hidden landscape:grid landscape:grid-cols-2 landscape:items-start landscape:gap-x-6">
        {/* 左列：截图，完整全图 */}
        {safeImages.length > 0 && (
          <div className="space-y-3 landscape:col-start-1 landscape:row-start-1 landscape:self-start">
            {article.imageLayout === 'carousel' ? (
              <NewsCarousel urls={safeImages} />
            ) : (
              safeImages.map((url, i) => (
                <div
                  key={i}
                  className="flex w-full items-center justify-center overflow-hidden rounded-xl border border-white/10 bg-black/30 p-2"
                >
                  <img
                    src={url}
                    alt=""
                    loading="lazy"
                    className="no-save-img h-auto w-full object-contain"
                  />
                </div>
              ))
            )}
          </div>
        )}

        {/* 右列：摘要 + 评论同列紧挨，与左列截图高度无关 */}
        <div className="landscape:col-start-2 landscape:row-start-1 landscape:flex landscape:flex-col">
          <div className="space-y-3">
            {paragraphs.map((p, i) => (
              <p key={i} className="text-[15px] leading-7 text-gray-200">
                {p}
              </p>
            ))}
          </div>
          <div className="mt-6">
            <CommentSection
              targetType="news_article"
              targetId={article.id}
              sectionId="news-cmt-landscape"
            />
          </div>
        </div>
      </div>

      {/* ===== 管理员编辑弹窗 ===== */}
      <Dialog
        open={editOpen}
        onOpenChange={(o) => {
          if (!editSaving) setEditOpen(o);
        }}
      >
        <DialogContent className="max-h-[88vh] overflow-y-auto border-cyan-400/30 bg-[#141838] text-white sm:max-w-lg">
          <DialogHeader>
            <DialogTitle className="text-cyan-200">{t('编辑热讯')}</DialogTitle>
            <DialogDescription className="text-gray-400">
              仅管理员可见；保存后前台即时生效。
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-3 py-1">
            <div>
              <label className={labelCls}>{t('标题')}</label>
              <input
                value={fTitle}
                onChange={(e) => setFTitle(e.target.value)}
                className={inputCls}
              />
            </div>
            <div>
              <label className={labelCls}>{t('摘要')}</label>
              <textarea
                rows={5}
                value={fSummary}
                onChange={(e) => setFSummary(e.target.value)}
                className={inputCls}
              />
            </div>
            <div>
              <label className={labelCls}>{t('标签（逗号或空格分隔）')}</label>
              <input
                value={fTags}
                onChange={(e) => setFTags(e.target.value)}
                className={inputCls}
              />
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className={labelCls}>{t('平台')}</label>
                <select
                  value={fPlatform}
                  onChange={(e) => setFPlatform(e.target.value as NewsPlatform)}
                  className={inputCls}
                >
                  {NEWS_PLATFORMS.filter((p) => p.value !== 'all').map((p) => (
                    <option key={p.value} value={p.value}>
                      {p.value}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className={labelCls}>{t('状态')}</label>
                <select
                  value={fStatus}
                  onChange={(e) => setFStatus(e.target.value as NewsStatus)}
                  className={inputCls}
                >
                  <option value="published">{t('发布')}</option>
                  <option value="draft">{t('草稿（下架）')}</option>
                </select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className={labelCls}>博主名</label>
                <input
                  value={fAuthor}
                  onChange={(e) => setFAuthor(e.target.value)}
                  placeholder="如：DRX Tess"
                  className={inputCls}
                />
              </div>
              <div>
                <label className={labelCls}>博主账号 handle</label>
                <input
                  value={fAuthorHandle}
                  onChange={(e) => setFAuthorHandle(e.target.value)}
                  placeholder="如：@drx_tess"
                  className={inputCls}
                />
              </div>
            </div>
            <div>
              <label className={labelCls}>
                {t('原帖发布时间（补档用，可留空）')}
              </label>
              <input
                type="datetime-local"
                value={fPostedAt}
                onChange={(e) => setFPostedAt(e.target.value)}
                className={inputCls}
              />
            </div>
            <div>
              <label className={labelCls}>图片展示形态</label>
              <select
                value={fLayout}
                onChange={(e) => setFLayout(e.target.value as NewsImageLayout)}
                className={inputCls}
              >
                <option value="long">拼接长图（纵向铺开）</option>
                <option value="carousel">多图轮播（左右滑动）</option>
                <option value="single">单图</option>
              </select>
            </div>
            <div>
              <label className={labelCls}>
                {t('图片 URL（每行一个，可删图或调整顺序）')}
              </label>
              <textarea
                rows={3}
                value={fImages}
                onChange={(e) => setFImages(e.target.value)}
                className={inputCls}
              />
            </div>
          </div>

          <DialogFooter>
            <button
              onClick={() => setEditOpen(false)}
              className="rounded-md border border-white/15 px-4 py-2 text-sm text-gray-300 transition hover:bg-white/5"
            >
              {t('取消')}
            </button>
            <button
              onClick={handleSaveEdit}
              disabled={editSaving}
              className="inline-flex items-center gap-1.5 rounded-md bg-gradient-to-r from-cyan-500 to-blue-500 px-4 py-2 text-sm font-bold text-white transition hover:brightness-110 disabled:opacity-60"
            >
              {editSaving && <Loader2 className="h-4 w-4 animate-spin" />}
              {t('保存')}
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ===== 删除确认弹窗 ===== */}
      <Dialog
        open={deleteOpen}
        onOpenChange={(o) => {
          if (!deleting) setDeleteOpen(o);
        }}
      >
        <DialogContent className="border-red-400/30 bg-[#141838] text-white sm:max-w-sm">
          <DialogHeader>
            <DialogTitle className="text-red-200">
              {t('删除这篇热讯？')}
            </DialogTitle>
            <DialogDescription className="text-gray-400">
              将同时删除数据库内容与服务器上的图片，删除后立即消失、不可恢复。
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <button
              onClick={() => setDeleteOpen(false)}
              className="rounded-md border border-white/15 px-4 py-2 text-sm text-gray-300 transition hover:bg-white/5"
            >
              {t('取消')}
            </button>
            <button
              onClick={handleConfirmDelete}
              disabled={deleting}
              className="inline-flex items-center gap-1.5 rounded-md bg-red-500 px-4 py-2 text-sm font-bold text-white transition hover:brightness-110 disabled:opacity-60"
            >
              {deleting && <Loader2 className="h-4 w-4 animate-spin" />}
              {t('确认删除')}
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default NewsDetailPage;
