import { createContext, type RefObject } from 'react';

/**
 * 球员详情页「横屏网页」重排用的插槽。
 * BuildPanel 内部状态/逻辑保持不变，仅把两块 UI 通过 Portal 渲染到
 * PlayerDetailHeader 中的对应插槽：
 *   - slotControls ：能力值 / 位置 / 加点 / 保存（原评分区域，等级右侧）
 *   - slotSynthesis：闪耀 / 教练 / 第二增能（加点方案下方的综合面板）
 * 原生 APP（含平板横屏）不使用该上下文，保持原有内嵌布局。
 */
export interface DetailSlots {
  slotControls: RefObject<HTMLDivElement | null>;
  slotSynthesis: RefObject<HTMLDivElement | null>;
  ready: boolean;
  /** 竖屏：总能力值（替换头部大总评位置） */
  slotPortraitTotalSum?: RefObject<HTMLDivElement | null>;
  /** 竖屏：位置选择（卡牌综合面板内） */
  slotPortraitPosition?: RefObject<HTMLDivElement | null>;
  /** 加点方案标题右侧动作位（我的方案按钮） */
  slotAddPointAction?: RefObject<HTMLDivElement | null>;
}

export const DetailSlotsContext = createContext<DetailSlots | null>(null);
