// Notification localization —— 仅用于副页 /efootball-next（英文态）。
// 通知的 title/content 由后端在生成时以中文整句预生成并存库，前端无法逐句建 key。
// 英文态在前端按通知 type 解析中文句中的参数，再用英文模板重组；
// 帖子/动态等嵌入标题联动其功能页英文名（不逐字硬译）。
// 任一条解析失败都安全回退到后端原文（中文），不报错、不影响点击跳转。
import type { NotificationItem } from '@shared/api.interface';
import { trTerm } from './terms';

type Lang = 'zh' | 'en';

// ---------- 固定标题 ----------
const TITLE_EN: Record<string, string> = {
  你的帖子已被删除: 'Your Post Has Been Deleted',
  你的评论已被删除: 'Your Comment Has Been Deleted',
  声望变动通知: 'Reputation Change',
  '等级提升 🎉': 'Level Up 🎉',
  你已被禁言: 'You Have Been Muted',
  你已被解除禁言: 'Your Mute Has Been Lifted',
  你的账号已被封禁: 'Your Account Has Been Banned',
  你的账号已解封: 'Your Account Has Been Unbanned',
  举报已处理: 'Report Resolved',
  举报已驳回: 'Report Rejected',
};

// ---------- 等级头衔 ----------
const RANK_EN: Record<string, string> = {
  新人球探: 'Rookie Scout',
  业余教练: 'Amateur Coach',
  职业教练: 'Professional Coach',
  战术大师: 'Tactical Master',
  绿茵名宿: 'Pitch Legend',
  传奇教父: 'Legendary Manager',
};

// ---------- 声望原因标签 ----------
const LABEL_EN: Record<string, string> = {
  注册奖励: 'Registration bonus',
  每日登录: 'Daily login',
  发布帖子: 'Post created',
  发表评论: 'Comment posted',
  被点赞: 'Received a like',
  点赞取消回退: 'Like cancelled',
  举报采纳: 'Report adopted',
  内容加精: 'Content featured',
  帖子被删除: 'Post deleted',
  评论被删除: 'Comment deleted',
  禁言处罚: 'Mute penalty',
  封禁处罚: 'Ban penalty',
  等级提升: 'Level up',
  管理员调整: 'Admin adjustment',
};

// ---------- 常见原因 ----------
const REASON_EN: Record<string, string> = {
  违反社区规范: 'violating community guidelines',
  违规内容被删除: 'violating content removed',
  经核查未发现违规内容: 'no violation was found after review',
};

function reasonEn(zh: string): string {
  const t0 = zh.trim();
  if (!t0) return '';
  return REASON_EN[t0] || trTerm(t0) || t0;
}

// 嵌入标题（帖子/动态名）：整体命中术语则直接用；否则按竖线拆分、逐段联动功能页英文名。
function trEmbeddedTitle(raw: string): string {
  const s = raw.trim();
  if (!s) return '';
  if (trTerm(s) !== s) return trTerm(s);
  return s
    .split(/([｜|])/)
    .map((seg) => {
      if (seg === '｜' || seg === '|') return seg;
      const t0 = seg.trim();
      return t0 ? trTerm(t0) || t0 : '';
    })
    .join(' ')
    .replace(/\s*([｜|])\s*/g, ' $1 ');
}

// ---------- 正文解析（返回 null 表示无法识别，调用方回退原文） ----------
function tryRenderContent(c: string): string | null {
  let m: RegExpMatchArray | null;

  // 论坛帖子删除
  m = c.match(/^帖子「(.+?)」因(.+?)删除。原因：(.*)$/);
  if (m) {
    const why = m[3].trim() ? reasonEn(m[3]) : '';
    return `Your post “${trEmbeddedTitle(m[1])}” was deleted by an admin.${why ? ` Reason: ${why}` : ''}`;
  }

  // 论坛/评论服务：评论删除
  m = c.match(/^评论因(.+?)删除。原因：(.*)$/);
  if (m) {
    const why = m[2].trim() ? reasonEn(m[2]) : '';
    return `Your comment was deleted by an admin.${why ? ` Reason: ${why}` : ''}`;
  }

  // 球员页评论删除（admin content_removed）
  m = c.match(/^你在球员页的评论因 (.+?) 已被管理员删除。$/);
  if (m) return `Your comment on a player page was deleted by an admin for ${reasonEn(m[1])}.`;

  // 通用 content_removed（你发布的XX「标题」因 … 已被管理员删除）
  m = c.match(/^你发布的(.+?)(?:「(.+?)」)?因 (.+?) 已被管理员删除。$/);
  if (m) {
    const typeLabel = trTerm(m[1].trim()) || m[1].trim();
    const tgt = m[2] ? ` “${trEmbeddedTitle(m[2])}”` : '';
    return `Your ${typeLabel}${tgt} was deleted by an admin for ${reasonEn(m[3])}.`;
  }

  // 禁言
  m = c.match(/^你因 (.+?) 被禁言 (.+?)，期间无法发布内容。$/);
  if (m)
    return `You have been muted for ${reasonEn(m[1])} for ${m[2].trim()}. You cannot post during this time.`;

  // 解除禁言
  if (c === '你的禁言已解除，可以正常发布内容了。')
    return 'Your mute has been lifted. You can post normally now.';

  // 永久封禁
  m = c.match(/^你因 (.+?) 被永久封禁。$/);
  if (m) return `You have been permanently banned for ${reasonEn(m[1])}.`;

  // 解封
  if (c === '你的账号已解除封禁，可以正常使用了。')
    return 'Your account has been unbanned. You can use it normally now.';

  // 声望：等级提升
  m = c.match(/^恭喜！您的声望达到 (\d+)，升至 Lv\.(\d+) (.+)$/);
  if (m) {
    const rank = RANK_EN[m[3].trim()] || trTerm(m[3]) || m[3];
    return `Congratulations! Your reputation reached ${m[1]}, and you rose to Lv.${m[2]} ${rank}.`;
  }

  // 声望：增减变动
  m = c.match(/^(.+?)：声望 (-?\d+)，当前余额 (-?\d+)$/);
  if (m) {
    const label = LABEL_EN[m[1].trim()] || trTerm(m[1]) || m[1];
    return `${label}: Reputation ${m[2]}, current balance ${m[3]}`;
  }

  // 举报结果：内容已删除
  m = c.match(/^你举报的内容「(.+?)」因违规已被删除。感谢你的反馈。$/);
  if (m)
    return `The content you reported, “${trEmbeddedTitle(m[1])}”, was deleted for violating the rules. Thank you for your feedback.`;

  // 举报结果：驳回
  m = c.match(/^你举报的内容经核查未发现违规，举报已驳回。原因：(.+?)。$/);
  if (m)
    return `The content you reported was reviewed and no violation was found; the report was rejected. Reason: ${reasonEn(m[1])}`;

  return null;
}

// ---------- 对外接口 ----------
export function renderNotificationTitle(item: NotificationItem, lang: Lang): string {
  if (lang !== 'en') return item.title;
  const t0 = item.title.trim();
  return TITLE_EN[t0] || trTerm(t0) || item.title;
}

export function renderNotificationContent(item: NotificationItem, lang: Lang): string {
  if (lang !== 'en') return item.content;
  const c = item.content.trim();
  return tryRenderContent(c) ?? item.content;
}
