/**
 * 全局「返回拦截」栈。
 * 用于页面内部用 state 实现的上下级导航（如榜单：菜单 → 我的强度榜/阵容/位置榜）。
 * 当某个子页面处于打开状态时注册一个处理函数；Android 硬件返回 / 边缘内滑
 * 会优先调用栈顶处理函数（返回上级），而不是直接退出 APP 或路由回退。
 */
export type BackHandler = () => boolean;

const stack: BackHandler[] = [];

/** 注册一个返回拦截函数，返回取消注册的方法。 */
export function pushBackHandler(handler: BackHandler): () => void {
  stack.push(handler);
  return () => {
    const i = stack.lastIndexOf(handler);
    if (i >= 0) stack.splice(i, 1);
  };
}

/**
 * 执行一次返回。若有拦截函数且其返回 true，表示已处理（调用方应停止默认返回）。
 */
export function runBackIntercept(): boolean {
  for (let i = stack.length - 1; i >= 0; i -= 1) {
    try {
      if (stack[i]()) return true;
    } catch {
      // 出错的拦截器视为未处理，继续默认逻辑
    }
  }
  return false;
}
