import * as React from "react"

/**
 * 检测当前是否为横屏（orientation: landscape）。
 * 用于球员详情页切换"一屏三栏"布局。
 */
export function useIsLandscape() {
  // 关键：首次渲染就同步读取当前朝向，避免在 Layout 的普通树/沉浸树之间
  // 反复切换导致页面无限重挂载（重挂会让 state 重新从 false 开始）。
  const [isLandscape, setIsLandscape] = React.useState<boolean>(() =>
    typeof window !== "undefined" &&
    typeof window.matchMedia === "function" &&
    window.matchMedia("(orientation: landscape)").matches
  )

  React.useEffect(() => {
    const mql = window.matchMedia("(orientation: landscape)")
    const onChange = () => setIsLandscape(mql.matches)
    mql.addEventListener("change", onChange)
    setIsLandscape(mql.matches)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return isLandscape
}
