import React, { useRef, useState } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface Props {
  urls: string[];
}

// 热讯「多图轮播」：一次一张、宽度撑满；图片区域内左右滑切换（到边界停、不跳文章）。
// 手势在容器内 stopPropagation，与详情页"左右滑切换上/下一篇"隔离。
const NewsCarousel: React.FC<Props> = ({ urls }) => {
  const [index, setIndex] = useState(0);
  const startXRef = useRef<number | null>(null);
  const n = urls.length;

  if (n === 0) return null;
  const go = (i: number) => setIndex(Math.max(0, Math.min(n - 1, i)));

  const onTouchStart = (e: React.TouchEvent) => {
    e.stopPropagation(); // 阻止冒泡到详情页"切换文章"手势
    startXRef.current = e.touches[0].clientX;
  };
  const onTouchEnd = (e: React.TouchEvent) => {
    e.stopPropagation();
    const x0 = startXRef.current;
    startXRef.current = null;
    if (x0 == null) return;
    const dx = e.changedTouches[0].clientX - x0;
    if (Math.abs(dx) < 45) return;
    if (dx < 0) go(index + 1); // 左滑 -> 下一张（末张停，不切文章）
    else go(index - 1); // 右滑 -> 上一张
  };

  return (
    <div
      className="relative w-full overflow-hidden rounded-xl border border-white/10 bg-black/30 p-2"
      onTouchStart={onTouchStart}
      onTouchEnd={onTouchEnd}
    >
      <div
        className="flex w-full transition-transform duration-300 ease-out"
        style={{ transform: `translateX(-${index * 100}%)` }}
      >
        {urls.map((url, i) => (
          <div key={i} className="w-full flex-shrink-0">
            <img
              src={url}
              alt=""
              loading="lazy"
              draggable={false}
              className="no-save-img h-auto w-full select-none object-contain"
              onContextMenu={(e) => e.preventDefault()}
            />
          </div>
        ))}
      </div>

      {/* 桌面左右箭头（移动端隐藏，用手滑） */}
      {index > 0 && (
        <button
          onClick={() => go(index - 1)}
          aria-label="prev"
          className="absolute left-2 top-1/2 hidden h-9 w-9 -translate-y-1/2 items-center justify-center rounded-full bg-black/55 text-white hover:bg-black/75 lg:flex"
        >
          <ChevronLeft className="h-5 w-5" />
        </button>
      )}
      {index < n - 1 && (
        <button
          onClick={() => go(index + 1)}
          aria-label="next"
          className="absolute right-2 top-1/2 hidden h-9 w-9 -translate-y-1/2 items-center justify-center rounded-full bg-black/55 text-white hover:bg-black/75 lg:flex"
        >
          <ChevronRight className="h-5 w-5" />
        </button>
      )}

      {/* 移动端：悬空透明三角，纯提示、不可点（桌面用上方可点箭头） */}
      {index > 0 && (
        <div className="pointer-events-none absolute left-1 top-1/2 -translate-y-1/2 lg:hidden">
          <div className="flex h-10 w-8 items-center justify-center bg-gradient-to-r from-black/50 to-transparent">
            <ChevronLeft className="h-7 w-7 text-white/60" />
          </div>
        </div>
      )}
      {index < n - 1 && (
        <div className="pointer-events-none absolute right-1 top-1/2 -translate-y-1/2 lg:hidden">
          <div className="flex h-10 w-8 items-center justify-center bg-gradient-to-l from-black/50 to-transparent">
            <ChevronRight className="h-7 w-7 text-white/60" />
          </div>
        </div>
      )}

      {/* 圆点 + 计数 */}
      <div className="mt-2 flex items-center justify-center gap-1.5">
        {urls.map((_, i) => (
          <button
            key={i}
            aria-label={`goto ${i + 1}`}
            onClick={() => go(i)}
            className={`h-1.5 rounded-full transition-all ${
              i === index ? 'w-4 bg-cyan-400' : 'w-1.5 bg-white/30 hover:bg-white/50'
            }`}
          />
        ))}
        <span className="ml-2 text-xs text-gray-400">
          {index + 1}/{n}
        </span>
      </div>
    </div>
  );
};

export default NewsCarousel;
