interface CompareSection {
  title: string;
  accent: string;
  attrs: string[];
}

const COMPARE_SECTIONS: CompareSection[] = [
  { title: '进攻能力', accent: 'from-amber-400 to-orange-500', attrs: ATTACK_ATTRS },
  { title: '身体素质', accent: 'from-emerald-400 to-teal-500', attrs: PHYSICAL_ATTRS },
  { title: '防守能力', accent: 'from-blue-400 to-indigo-500', attrs: DEFENSE_ATTRS },
];


const getOffenseStyleDisplay = (style: string | undefined | null): string => {
  if (!style || !style.trim()) return '基础战术';
  return OFFENSE_STYLES.includes(style) ? style : '基础战术';
};

function getInitial(nameZh: string, nameEn?: string): string {
  if (nameZh) return nameZh.charAt(0);
  if (nameEn) return nameEn.charAt(0);
  return '?';
}

interface PlayerCompareCardProps {
  player: Player;
  stats?: CompareComputedStats;
  playerCount: number;
  onRemove: (id: string) => void;
}

const PlayerCompareCard: React.FC<PlayerCompareCardProps> = ({ player, stats, playerCount, onRemove }) => {
  const [imgError, setImgError] = React.useState(false);
  const initial = getInitial(player.nameZh, player.nameEn);
  const canRemove = playerCount > 2;
  const cardImageUrl = resolvePlayerCardImage(player.playerImageUrl, player.playerId);
  const hasImage = cardImageUrl && !imgError;

  return (
    <div className="flex-shrink-0 w-36 sm:w-32 relative">
      {canRemove && (
        <button
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            onRemove(player.id);
          }}
          className="absolute -top-1.5 -right-1.5 z-20 w-5 h-5 rounded-full bg-red-500/90 hover:bg-red-500 text-white flex items-center justify-center shadow-lg border border-red-400/50 transition-colors"
          title="移除该球员"
        >
          <X className="w-3 h-3" />
        </button>
      )}
      <Link
        to={`/player/${player.id}`}
        className="relative block w-full rounded-xl bg-gradient-to-b from-[#1a2350] to-[#0d1230] shadow-md border border-cyan-400/30 overflow-hidden aspect-[4/5] hover:border-cyan-400/60 hover:shadow-[0_0_12px_rgba(0_229_255_0.2)] transition-all"
      >
        <div className="absolute inset-0 bg-gradient-to-b from-cyan-500/10 via-transparent to-transparent pointer-events-none" />
        {hasImage ? (
          <Image
            src={cardImageUrl}
            alt={player.nameZh}
            className="absolute inset-0 w-full h-full object-contain object-bottom"
            onError={() => setImgError(true)}
          />
        ) : (
          <div className="absolute inset-0 flex items-center justify-center">
            <span className="text-3xl font-bold text-white drop-shadow-lg">
              {initial}
            </span>
          </div>
        )}
      </Link>
    </div>
  );
};

const PlayerComparePage: React.FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();
  const [playerList, setPlayerList] = useState<Player[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [configs, setConfigs] = useState<Record<string, ComparePlayerConfig>>({});
  const [coachList, setCoachList] = useState<Coach[]>([]);
  const [boosterList, setBoosterList] = useState<LocalBooster[]>([]);
  // 一键加载需读取最新列表：用 ref 避免 useCallback 闭包取到旧值
  const coachListRef = useRef<Coach[]>([]);
  const boosterListRef = useRef<LocalBooster[]>([]);
  const boostersLoadedRef = useRef(false);
  useEffect(() => { coachListRef.current = coachList; }, [coachList]);
  useEffect(() => { boosterListRef.current = boosterList; }, [boosterList]);
  const [buildDialogFor, setBuildDialogFor] = useState<string | null>(null);
  const [coachDialogFor, setCoachDialogFor] = useState<string | null>(null);
  const [boosterDialogFor, setBoosterDialogFor] = useState<string | null>(null);
  const [shineDialogFor, setShineDialogFor] = useState<string | null>(null);
  const [collapsedSections, setCollapsedSections] = useState<Record<string, boolean>>({});
  const [activeTab, setActiveTab] = useState<'attrs' | 'radar' | 'body' | 'skills' | 'position'>('attrs');
  const [hideSame, setHideSame] = useState(false);

  // 竖屏手机（网页与 APP，内宽<768）：字号整体放大两档，按宽度判定、不依赖原生平台；
  // 使手机浏览器竖屏与原生 APP 字号一致，横屏/平板/桌面保持紧凑
  const phone = useIsNarrowScreen();
  const isLandscape = useIsLandscape();
  // 仅“网页 + 横屏（含桌面宽屏）”把基本信息字号缩小 2 档；APP、网页竖屏均不调
  const webLandscape = !phone && isLandscape;
  const z = {
    rowLabel: phone ? 'text-2xl' : 'text-sm',
    rowValue: phone ? 'text-3xl' : 'text-base',
    infoLabel: phone ? 'text-2xl' : (webLandscape ? 'text-[11px]' : 'text-sm'),
    infoValue: phone ? 'text-2xl' : (webLandscape ? 'text-xs' : 'text-base'),
    blockTitle: phone ? 'text-3xl' : 'text-lg',
    sectionTitle: phone ? 'text-2xl' : 'text-base',
  };
  // 标题（第一列）列宽：手机加宽以完整容纳 4 汉字标签；网页保持窄列
  const titleCol = phone ? 'w-28' : 'w-14';

  const isValuesSame = (values: (string | number)[]): boolean => {
    if (values.length <= 1) return true;
    return values.every((v) => v === values[0]);
  };

  const getCompareMaxLevel = (player: Player): number => {
    return Math.max(player.maxLevel || 1, 30);
  };

  const updateConfig = useCallback((playerId: string, updater: (cfg: ComparePlayerConfig) => ComparePlayerConfig) => {
    setConfigs((prev) => {
      const prevCfg = prev[playerId];
      if (!prevCfg) return prev;
      return { ...prev, [playerId]: updater(prevCfg) };
    });
  }, []);

  const handleBuildConfirm = useCallback((playerId: string, data: { allocations: Record<string, number>; level: number }) => {
    updateConfig(playerId, (cfg) => ({ ...cfg, allocations: data.allocations, level: data.level }));
    setBuildDialogFor(null);
  }, [updateConfig]);

  const { t, lang } = useI18n();
  const en = lang === 'en';
  // 「加点配置」一键智能加载：优先用该用户保存的培养方案，无方案则自动加点
  const [smartLoading, setSmartLoading] = useState(false);
  const handleSmartLoad = useCallback(async () => {
    if (playerList.length === 0 || smartLoading) return;
    setSmartLoading(true);
    let planItems: BuildPlanItem[] = [];
    try {
      const res = await getMyBuildPlans(1, 200);
      planItems = res.items ?? [];
    } catch {
      planItems = []; // 未登录 / 接口失败：按无方案处理、走自动加点
    }
    // 每个球员取其最新一条方案（列表默认按更新时间倒序）
    const planByPlayer: Record<string, BuildPlanItem> = {};
    for (const it of planItems) {
      if (!planByPlayer[it.playerId]) planByPlayer[it.playerId] = it;
    }
    let savedCount = 0;
    let autoCount = 0;
    for (const p of playerList) {
      if (planByPlayer[p.id]) savedCount += 1;
      else autoCount += 1;
    }
    // 等待教练/增能列表就绪（最多约 4 秒），以便完整恢复教练与第二增能
    const waitDeadline = Date.now() + 4000;
    while (
      (coachListRef.current.length === 0 || !boostersLoadedRef.current) &&
      Date.now() < waitDeadline
    ) {
      await new Promise((r) => setTimeout(r, 200));
    }
    const curCoachList = coachListRef.current;
    const curBoosterList = boosterListRef.current;
    setConfigs((prev) => {
      const next: Record<string, ComparePlayerConfig> = { ...prev };
      for (const p of playerList) {
        const cfg = next[p.id] ?? defaultConfigForPlayer(p);
        const item = planByPlayer[p.id];
        if (item) {
          // 恢复教练、第二增能（按保存的 id 在已加载列表中定位；找不到则保留当前默认）
          let coach = cfg.coach;
          let booster2 = cfg.booster2;
          if (item.coachId) {
            const foundCoach = curCoachList.find((c) => c.id === item.coachId);
            if (foundCoach) coach = foundCoach;
          }
          if (item.secondBoosterId) {
            const foundBooster = curBoosterList.find(
              (b) => String(b.id) === String(item.secondBoosterId),
            );
            if (foundBooster) booster2 = foundBooster;
          }
          next[p.id] = {
            ...cfg,
            allocations: item.allocations ?? cfg.allocations,
            level: item.maxLevel || cfg.level,
            shineLevel: item.shineLevel ?? 0,
            coach,
            booster2,
          };
        } else {
          next[p.id] = { ...cfg, allocations: autoBuildAllocations(p, cfg) };
        }
      }
      return next;
    });
    const tail = en
      ? 'Go save your own build for your favorite players!'
      : '赶紧去给你喜欢的球员保存专属加点！';
    if (savedCount > 0 && autoCount > 0) {
      toast.success(en
        ? `Loaded saved builds (coach, shine, booster 2) for ${savedCount}; ${autoCount} with no build got auto allocation. ${tail}`
        : `已加载 ${savedCount} 名球员的保存方案（含教练、闪耀、第二增能），另 ${autoCount} 名无方案、已自动加点。${tail}`,
        { duration: 8000 });
    } else if (savedCount > 0) {
      toast.success(en
        ? `Loaded saved builds (coach, shine, booster 2) for ${savedCount} player(s). ${tail}`
        : `已加载 ${savedCount} 名球员的保存方案（含教练、闪耀、第二增能）。${tail}`,
        { duration: 8000 });
    } else {
      toast.success(en
        ? `No saved build found \u2014 auto-allocated points for ${autoCount} player(s). ${tail}`
        : `未找到保存方案，已为 ${autoCount} 名球员自动加点。${tail}`,
        { duration: 8000 });
    }
    setSmartLoading(false);
  }, [playerList, smartLoading, en]);

  const handleCoachConfirm = useCallback((playerId: string, coach: Coach | null) => {
    updateConfig(playerId, (cfg) => ({ ...cfg, coach }));
    setCoachDialogFor(null);
  }, [updateConfig]);

  const handleBoosterConfirm = useCallback((playerId: string, booster: LocalBooster | null) => {
    updateConfig(playerId, (cfg) => ({ ...cfg, booster2: booster }));
    setBoosterDialogFor(null);
  }, [updateConfig]);

  const handleShineConfirm = useCallback((playerId: string, level: number) => {
    updateConfig(playerId, (cfg) => ({ ...cfg, shineLevel: level }));
    setShineDialogFor(null);
  }, [updateConfig]);

  const ids = useMemo(() => {
    const raw = searchParams.get('ids');
    if (!raw) return [];
    return raw.split(',').filter(Boolean).slice(0, 4);
  }, [searchParams]);

  const [boostersLoaded, setBoostersLoaded] = useState(false);
  const stickyRef = useRef<HTMLDivElement>(null);
  const stickyPlaceholderRef = useRef<HTMLDivElement>(null);
  const [isStuck, setIsStuck] = useState(false);
  const [stickyTop, setStickyTop] = useState(0);
  const [stickyWidth, setStickyWidth] = useState(0);

  useEffect(() => {
    const placeholder = stickyPlaceholderRef.current;
    const el = stickyRef.current;
    if (!placeholder || !el) return;

    const updateSticky = () => {
      const rect = placeholder.getBoundingClientRect();
      const shouldStick = rect.top <= 0;
      setIsStuck(shouldStick);
      setStickyTop(0);
      if (shouldStick) {
        setStickyWidth(rect.width);
      }
    };

    updateSticky();
    window.addEventListener('scroll', updateSticky, true);
    window.addEventListener('resize', updateSticky);
    const ro = new ResizeObserver(updateSticky);
    ro.observe(placeholder);
    return () => {
      window.removeEventListener('scroll', updateSticky, true);
      window.removeEventListener('resize', updateSticky);
      ro.disconnect();
    };
  }, [playerList.length]);
  const setMainZIndex = useSetMainZIndex();

  useEffect(() => {
    setMainZIndex?.(60);
    return () => setMainZIndex?.(10);
  }, [setMainZIndex]);

  useEffect(() => {
    coachesApi.getCoachList({ page: 1, pageSize: 200 })
      .then((res: { items: Coach[] }) => setCoachList(res.items || []))
      .catch((err: unknown) => logger.error('加载教练列表失败', err));
    boostersApi.getBoosters()
      .then((res: ApiBooster[]) => {
        const list = res.map((b) => apiBoosterToLocal(b));
        setBoosterList(list);
        setBoostersLoaded(true);
        boostersLoadedRef.current = true;
      })
      .catch((err: unknown) => {
        logger.error('加载增能列表失败', err);
        setBoostersLoaded(true);
        boostersLoadedRef.current = true;
      });
  }, []);

  useEffect(() => {
    if (ids.length === 0) {
      setLoading(false);
      setError('未选择球员');
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    players.getPlayersBulk(ids)
      .then((data: Player[]) => {
        if (!cancelled) {
          // 保持用户选择顺序（URL 参数 ids 的顺序）
          const ordered: Player[] = [];
          const dataMap = new Map<string, Player>();
          for (const p of data) dataMap.set(p.id, p);
          for (const id of ids) {
            const p = dataMap.get(id);
            if (p) ordered.push(p);
          }
          setPlayerList(ordered);
          const initialConfigs: Record<string, ComparePlayerConfig> = {};
          for (const p of data) {
            initialConfigs[p.id] = defaultConfigForPlayer(p);
          }
          setConfigs(initialConfigs);
        }
      })
      .catch((err: unknown) => {
        if (!cancelled) {
          logger.error('加载对比球员失败', err);
          setError('加载失败，请稍后重试');
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [ids]);

  useEffect(() => {
    if (!boostersLoaded || playerList.length === 0) return;
    setConfigs((prev) => {
      let changed = false;
      const next: Record<string, ComparePlayerConfig> = { ...prev };
      for (const p of playerList) {
        const cfg = next[p.id];
        if (!cfg) continue;
        if (!cfg.booster1 && p.innateBoosterId) {
          const innate = boosterList.find((b) => String(b.id) === String(p.innateBoosterId)) || null;
          if (innate) {
            next[p.id] = { ...cfg, booster1: innate };
            changed = true;
          }
        }
        const curCfg = next[p.id];
        if (!curCfg.booster2 && p.booster2?.id) {
          const second = boosterList.find((b) => String(b.id) === String(p.booster2?.id)) || null;
          if (second) {
            next[p.id] = { ...curCfg, booster2: second };
            changed = true;
          }
        }
      }
      return changed ? next : prev;
    });
  }, [boostersLoaded, playerList, boosterList]);

  const computedStats = useMemo(() => {
    const map: Record<string, CompareComputedStats> = {};
    for (const p of playerList) {
      const cfg = configs[p.id] ?? defaultConfigForPlayer(p);
      map[p.id] = computePlayerStats(p, cfg);
    }
    return map;
  }, [playerList, configs]);

  const playerCount = playerList.length;

  const toggleSection = (section: string) => {
    setCollapsedSections((prev) => ({ ...prev, [section]: !prev[section] }));
  };

  const handleRemovePlayer = (playerId: string) => {
    const newIds = ids.filter((id) => id !== playerId);
    if (newIds.length < 2) return;
    setSearchParams({ ids: newIds.join(',') });
  };

  const getHiddenDisplay = (ha: HiddenAttributes, key: string): string => {
    const item = ha[key as keyof HiddenAttributes];
    if (!item) return '--';
    return `${item.level} ${item.label}`;
  };

  const overallValues = playerList.map((p) => computedStats[p.id]?.overall ?? p.overallRating);
  const maxOverall = Math.max(...overallValues, 0);

  const visibleSections = COMPARE_SECTIONS.filter((section) =>
    playerList.some((p) => {
      const st = computedStats[p.id];
      return section.attrs.some((a) => (st?.finalAttrs[a] ?? 0) > 0);
    }),
  );

  if (loading) {
    return (
      <div className="min-h-screen bg-[#0A0E27] flex items-center justify-center">
        <div className="text-center">
          <div className="w-12 h-12 border-4 border-cyan-400/30 border-t-cyan-400 rounded-full animate-spin mx-auto mb-4" />
          <p className="text-gray-400 text-xl">加载中...</p>
        </div>
      </div>
    );
  }

  if (error || playerList.length === 0) {
    return (
      <div className="min-h-screen bg-[#0A0E27] flex items-center justify-center">
        <div className="text-center">
          <p className="text-gray-400 mb-4">{error || '暂无对比球员'}</p>
          <button
            onClick={() => navigate(-1)}
            className="px-4 py-2 rounded-lg bg-cyan-500 text-white text-xl font-medium hover:bg-cyan-400 transition-colors"
          >
            返回
          </button>
        </div>
      </div>
    );
  }

  const hasAttrForAnyPlayer = (attr: string): boolean => {
    return playerList.some((p) => {
      const a = (p.attackStats ?? {}) as Record<string, unknown>;
      const d = (p.defenseStats ?? {}) as Record<string, unknown>;
      const pw = (p.powerStats ?? {}) as Record<string, unknown>;
      return a[attr] !== undefined || d[attr] !== undefined || pw[attr] !== undefined;
    });
  };

  const isAttrSame = (attr: string): boolean => {
    const values = playerList.map((p) => computedStats[p.id]?.finalAttrs[attr] ?? 0);
    return values.every((v) => v === values[0]);
  };

  const renderStatRow = (attrKey: string) => {
    const values = playerList.map((p) => computedStats[p.id]?.finalAttrs[attrKey] ?? 0);
    const maxVal = Math.max(...values);
    const minVal = Math.min(...values);
    const tie = maxVal === minVal;
    const textColor = (v: number): string =>
      tie
        ? 'text-gray-200'
        : v === maxVal
          ? 'text-emerald-400'
          : v === minVal
            ? 'text-red-400'
            : 'text-gray-200';

    return (
      <div
        key={attrKey}
        className={`flex items-center border-b border-white/5 last:border-b-0 ${phone ? 'h-12' : 'h-8'}`}
      >
        <div className={`${titleCol} flex-shrink-0 pl-1.5`}>
          <span className={`${z.rowLabel} text-gray-500 whitespace-nowrap leading-none`}>
            {ATTR_LABELS[attrKey] || attrKey}
          </span>
        </div>
        {playerList.map((p, idx) => (
          <div key={p.id} className="flex-1 text-center">
            <span className={`${z.rowValue} font-semibold ${textColor(values[idx])}`}>
              {values[idx]}
            </span>
          </div>
        ))}
      </div>
    );
  };

  const renderHeightRow = () => {
    const values = playerList.map((p) => p.height || 0);
    const maxVal = Math.max(...values);
    const minVal = Math.min(...values);

    return (
      <div key="height" className="flex items-center border-b border-white/5 last:border-b-0">
        <div className={`${titleCol} flex-shrink-0 pl-1.5 py-1`}>
          <span className={`${z.rowLabel} text-gray-500 whitespace-nowrap leading-none`}>{t('cmp.height')}</span>
        </div>
        {playerList.map((p, idx) => (
          <div key={p.id} className="flex-1 text-center py-1">
            <span className={`${z.rowValue} font-semibold text-gray-200`}>
              {values[idx]}cm
            </span>
          </div>
        ))}
      </div>
    );
  };

  const renderInfoRow = (
    label: string,
    values: string[],
    isMax?: (v: string) => boolean,
    onCellClick?: (playerId: string) => void,
    buttonClass?: string,
    onLabelClick?: () => void,
    labelButtonClass?: string,
  ) => (
    <div className="flex items-center border-b border-white/5 last:border-b-0">
      <div className={`${titleCol} flex-shrink-0 pl-1.5 py-1`}>
        {onLabelClick ? (
          <button
            type="button"
            onClick={onLabelClick}
            disabled={smartLoading}
            className={`${z.infoLabel} px-1 py-1 rounded-md font-bold whitespace-nowrap leading-none disabled:opacity-60 ${
              labelButtonClass ||
              'text-white bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-400 hover:to-blue-500 border border-cyan-300/40 shadow-[0_0_10px_rgba(0_229_255_0.4)]'
            }`}
          >
            {label}
          </button>
        ) : (
          <span className={`${z.infoLabel} text-gray-500 whitespace-nowrap leading-none`}>{label}</span>
        )}
      </div>
      {playerList.map((p, idx) => (
        <div key={p.id} className="flex-1 min-w-0 text-center py-1">
          {onCellClick ? (
            <button
              onClick={() => onCellClick(p.id)}
              className={`${z.infoValue} px-1.5 py-1 rounded-md font-bold ${buttonClass || 'text-cyan-300 bg-cyan-500/10 hover:bg-cyan-500/20'}`}
            >
              {values[idx]}
            </button>
          ) : (
            <span className={`${z.infoValue} ${isMax?.(values[idx]) ? 'text-cyan-300 font-semibold' : 'text-gray-400'}`}>{values[idx]}</span>
          )}
        </div>
      ))}
    </div>
  );

  const buildPlayerCard = (player: Player) => (
    <PlayerCompareCard
      key={player.id}
      player={player}
      stats={computedStats[player.id]}
      playerCount={playerCount}
      onRemove={handleRemovePlayer}
    />
  );

  const activePlayer = buildDialogFor ? playerList.find((p) => p.id === buildDialogFor) : null;
  const activeConfig = buildDialogFor ? configs[buildDialogFor] : null;
  const activeStats = buildDialogFor ? computedStats[buildDialogFor] : null;

  return (
    <div className="min-h-screen bg-[#0A0E27] text-white">
      <div className="fixed top-0 left-0 right-0 h-64 bg-gradient-to-b from-cyan-500/10 to-transparent pointer-events-none -z-0" />

      <div className="relative z-10 max-w-5xl sm:max-w-6xl lg:max-w-[1400px] mx-auto px-2 sm:px-3 py-2 sm:py-3">
        <div className="flex items-center gap-2 sm:gap-3 mb-3 sm:mb-4">
          <button
            onClick={() => navigate(-1)}
            className="flex items-center justify-center w-8 h-8 sm:w-9 sm:h-9 rounded-lg bg-white/5 border border-white/10 text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
          </button>
          <div className="flex items-center gap-2">
            <Scale className="w-5 h-5 text-cyan-400" />
            <h1 className="text-base sm:text-lg font-bold text-white">球员对比</h1>
            <span className="px-2 py-0.5 text-sm sm:text-base font-medium rounded-full bg-cyan-500/20 text-cyan-300 border border-cyan-400/30 whitespace-nowrap">
              {playerCount} 人
            </span>
          </div>
        </div>

        <div ref={stickyPlaceholderRef} />
        <div
          ref={stickyRef}
          className={`${isStuck ? 'fixed left-1/2 -translate-x-1/2' : 'relative'} z-[150] bg-[#0A0E27]/95 backdrop-blur-md px-2 pb-1 border-b border-white/10 shadow-[0_4px_20px_rgba(0_0_0_0.4)]`}
          style={{
            top: isStuck ? stickyTop : 0,
            width: isStuck ? stickyWidth : '100%',
          }}
        >
          <div className="overflow-x-auto pb-0.5">
            <div
              className="flex gap-1.5 justify-center"
              style={{ minWidth: playerCount <= 2 ? 'auto' : `${playerCount * 80}px` }}
            >
              {playerList.map((p) => buildPlayerCard(p))}
            </div>
          </div>

          <div className="flex gap-1 p-1 rounded-xl bg-[#141838] border border-white/10 mt-1 overflow-x-auto">
            {[
              { key: 'attrs', label: t('cmp.tab.attrs') },
              { key: 'radar', label: t('cmp.tab.radar') },
              { key: 'body', label: t('cmp.tab.model') },
              { key: 'skills', label: t('cmp.tab.skills') },
              { key: 'position', label: t('cmp.tab.position') },
            ].map((tab) => (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key as typeof activeTab)}
                className={`flex-1 min-w-[60px] sm:min-w-[80px] px-2 sm:px-3 py-1.5 sm:py-2 rounded-lg text-2xl sm:text-xl font-medium transition-all whitespace-nowrap ${
                  activeTab === tab.key
                    ? 'bg-gradient-to-r from-cyan-500/20 to-purple-500/20 text-white border border-cyan-400/40 shadow-[0_0_12px_rgba(0_229_255_0.2)]'
                    : 'text-gray-400 hover:text-gray-200 hover:bg-white/5'
                }`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-2 mt-2">
          {activeTab === 'attrs' && (
            <div className="grid grid-cols-1 sm:grid-cols-[minmax(0,1.25fr)_minmax(0,1fr)_minmax(0,1fr)_minmax(0,1fr)] gap-2 items-start">
              <div className="rounded-xl bg-[#141838] border border-white/10 overflow-hidden">
            <div className="flex items-center justify-between px-2 sm:px-3 py-1.5 sm:py-2 bg-white/[0.03] cursor-pointer" onClick={() => toggleSection('info')}>
              <div className="flex items-center gap-2">
                <span className="w-1 h-5 bg-gradient-to-b from-purple-400 to-pink-500 rounded-full" />
                 <span className={`${z.blockTitle} font-bold text-white`}>基本信息</span>
              </div>
              <div className="flex items-center gap-1.5 sm:gap-2">
                 <button
                   type="button"
                   onClick={(e) => {
                     e.stopPropagation();
                     setHideSame((v) => !v);
                   }}
                   className={`flex items-center gap-1 px-2 py-0.5 rounded-md text-sm sm:text-base font-medium transition-colors flex-shrink-0 ${
                     hideSame
                       ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-400/40'
                       : 'bg-white/5 text-gray-400 border border-white/10 hover:bg-white/10 hover:text-gray-200'
                   }`}
                 >
                   {hideSame ? <EyeOff className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
                   <span className="hidden sm:inline">隐藏相同</span>
                 </button>
                {collapsedSections.info ? (
                  <ChevronDown className="w-4 h-4 text-gray-500 flex-shrink-0" />
                ) : (
                  <ChevronUp className="w-4 h-4 text-gray-500 flex-shrink-0" />
                )}
              </div>
            </div>
             {!collapsedSections.info && (
               <div className="min-w-0">
                  <div className="min-w-0 px-1.5 py-1">
                    <div className={`flex items-center border-b border-white/5 ${phone ? 'h-12' : 'h-8'}`}>
                      <div className={`${titleCol} flex-shrink-0 pl-1.5`}>
                        <span className={`${z.rowLabel} text-gray-500 whitespace-nowrap leading-none`}>{t('cmp.ovr')}</span>
                      </div>
                      {playerList.map((p) => {
                        const ov = computedStats[p.id]?.overall ?? p.overallRating;
                        return (
                          <div key={p.id} className="flex-1 text-center">
                            <span className={`${z.rowValue} font-bold ${ov === maxOverall ? 'text-cyan-400 drop-shadow-[0_0_8px_rgba(34_211_238_0.5)]' : 'text-gray-200'}`}>{ov}</span>
                          </div>
                        );
                      })}
                    </div>
                    {(() => {
                      const infoItems: Array<{ key: string; values: (string | number)[]; node: React.ReactNode }> = [
                        { key: 'offenseStyle', values: playerList.map((p) => getOffenseStyleDisplay(p.style)), node: renderInfoRow(t('cmp.offStyle'), playerList.map((p) => t(getOffenseStyleDisplay(p.style)))) },
                        { key: 'defenseStyle', values: playerList.map((p) => p.defensivePlayStyle || '基础战术'), node: renderInfoRow(t('cmp.defStyle'), playerList.map((p) => t(p.defensivePlayStyle || '基础战术'))) },
                        { key: 'coach', values: playerList.map((p) => { const c = configs[p.id]; return c?.coach?.nameZh || '无教练'; }), node: renderInfoRow(t('cmp.manager'), playerList.map((p) => { const c = configs[p.id]; if (!c?.coach) return t('cmp.noManager'); return en ? ((c.coach as any).nameEn || c.coach.nameZh) : c.coach.nameZh; }), undefined, (id) => setCoachDialogFor(id), 'text-emerald-300 bg-emerald-500/10 hover:bg-emerald-500/20 border border-emerald-400/30') },
                        { key: 'booster1', values: playerList.map((p) => { const c = configs[p.id]; return c?.booster1?.name || '无'; }), node: renderInfoRow(t('cmp.boost1'), playerList.map((p) => { const c = configs[p.id]; return c?.booster1 ? t(c.booster1.name) : t('cmp.none'); })) },
                        { key: 'booster2', values: playerList.map((p) => { const c = configs[p.id]; return c?.booster2?.name || '无增能'; }), node: renderInfoRow(t('cmp.boost2'), playerList.map((p) => { const c = configs[p.id]; return c?.booster2 ? t(c.booster2.name) : t('detail.noBoost'); }), undefined, (id) => setBoosterDialogFor(id), 'text-purple-300 bg-purple-500/10 hover:bg-purple-500/20 border border-purple-400/30') },
                        { key: 'build', values: playerList.map((p) => { const c = configs[p.id]; const lvl = c?.level ?? p.maxLevel ?? 1; const av = c ? calcAvailablePoints(c.level, c.allocations) : 0; return t('cmp.lvPts', { lv: lvl, av }); }), node: renderInfoRow(t('cmp.build'), playerList.map((p) => { const c = configs[p.id]; const lvl = c?.level ?? p.maxLevel ?? 1; const av = c ? calcAvailablePoints(c.level, c.allocations) : 0; return t('cmp.lvPts', { lv: lvl, av }); }), undefined, (id) => setBuildDialogFor(id), 'text-white bg-gradient-to-br from-cyan-300 via-sky-500 to-indigo-600 bg-[length:180%_180%] bg-[position:0%_0%] hover:bg-[position:100%_100%] border border-cyan-200/60 shadow-[0_4px_16px_rgba(6,182,212,0.6),inset_0_1px_0_rgba(255,255,255,0.5),inset_0_-3px_7px_rgba(30,58,138,0.55)] hover:shadow-[0_8px_28px_rgba(6,182,212,0.85),inset_0_1px_0_rgba(255,255,255,0.6),inset_0_-3px_7px_rgba(30,58,138,0.55)] hover:-translate-y-0.5 active:translate-y-0 active:scale-95 transition-all duration-200', handleSmartLoad) },
                        { key: 'shine', values: playerList.map((p) => { const c = configs[p.id]; return c?.shineLevel ? `${c.shineLevel}级` : '无闪耀'; }), node: renderInfoRow(t('cmp.shine'), playerList.map((p) => { const c = configs[p.id]; return c?.shineLevel ? `Lv ${c.shineLevel}` : t('detail.noShine'); }), undefined, (id) => setShineDialogFor(id), 'text-amber-300 bg-amber-500/10 hover:bg-amber-500/20 border border-amber-400/30') },
                        { key: 'height', values: playerList.map((p) => p.height || 0), node: renderHeightRow() },
                        { key: 'preferredFoot', values: playerList.map((p) => normalizePreferredFoot(p.preferredFoot)), node: renderInfoRow(t('cmp.foot'), playerList.map((p) => t(normalizePreferredFoot(p.preferredFoot)))) },
                      ];
                      return infoItems.filter((it) => !hideSame || !isValuesSame(it.values)).map((it) => <React.Fragment key={it.key}>{it.node}</React.Fragment>);
                    })()}
                 </div>
               </div>
             )}
          </div>

          {COMPARE_SECTIONS.filter((section) => {
            // 过滤掉所有球员所有属性值全为 0 的 section（主要用于自动隐藏门将项）
            return playerList.some((p) => {
              const stats = computedStats[p.id];
              return section.attrs.some((attr) => {
                const v = stats?.finalAttrs[attr] ?? 0;
                return v > 0;
              });
            });
          }).map((section) => {
             const collapsed = collapsedSections[section.title];
             return (
               <div
                 key={section.title}
                 className="rounded-xl bg-[#141838] border border-white/10 overflow-hidden"
               >
                  <div
                   className="flex items-center justify-between px-2 sm:px-3 py-1.5 sm:py-2 bg-white/[0.03] cursor-pointer"
                   onClick={() => toggleSection(section.title)}
                  >
                    <div className="flex items-center gap-1.5 min-w-0">
                      <span className={`w-1 h-5 bg-gradient-to-b ${section.accent} rounded-full flex-shrink-0`} />
                       <h3 className={`${z.sectionTitle} font-bold text-white truncate`}>{section.title}</h3>
                    </div>
                    {collapsed ? (
                      <ChevronDown className="w-4 h-4 text-gray-500 flex-shrink-0" />
                    ) : (
                      <ChevronUp className="w-4 h-4 text-gray-500 flex-shrink-0" />
                    )}
                  </div>
                 {!collapsed && (
                   <div className="min-w-0">
                     <div className="min-w-0 px-1.5 py-1">
                          {section.attrs.filter(hasAttrForAnyPlayer).filter((attr) => !hideSame || !isAttrSame(attr)).map((attr) => renderStatRow(attr))}
                      </div>
                   </div>
                 )}
               </div>
             );
           })}
            </div>
          )}

          {activeTab === 'radar' && (
            <CompareRadarChart playerList={playerList} computedStatsMap={computedStats} />
          )}
           {activeTab === 'body' && (
             <CompareBodyModel
               playerList={playerList}
               hideSame={hideSame}
               onToggleHideSame={() => setHideSame((v) => !v)}
             />
           )}
             {activeTab === 'skills' && (
               <CompareSkills
                 playerList={playerList}
                 hideSame={hideSame}
                 onToggleHideSame={() => setHideSame((v) => !v)}
               />
             )}
          {activeTab === 'position' && (
            <ComparePositionHeatmap
              playerList={playerList}
              computedPositionRatings={Object.fromEntries(
                playerList.map((p) => [p.id, computedStats[p.id]?.positionRatings ?? p.positionRatings]),
              )}
            />
          )}
        </div>

        <div className="h-8" />
      </div>

      <CompareBuildDialog
        open={!!buildDialogFor}
        player={activePlayer ?? null}
        initialAllocations={activeConfig?.allocations || {}}
        initialLevel={activeConfig?.level || 1}
        coach={activeConfig?.coach || null}
        booster2={activeConfig?.booster2 || null}
        shineLevel={activeConfig?.shineLevel || 0}
        maxLevel={activePlayer ? getCompareMaxLevel(activePlayer) : 30}
        onClose={() => setBuildDialogFor(null)}
        onConfirm={(data) => buildDialogFor && handleBuildConfirm(buildDialogFor, data)}
      />

      <CompareCoachDialog
        open={!!coachDialogFor}
        coachList={coachList}
        selectedCoach={coachDialogFor ? configs[coachDialogFor]?.coach || null : null}
        onClose={() => setCoachDialogFor(null)}
        onConfirm={(coach) => coachDialogFor && handleCoachConfirm(coachDialogFor, coach)}
      />

      <CompareBoosterDialog
        open={!!boosterDialogFor}
        boosterList={boosterList}
        selectedBooster={boosterDialogFor ? configs[boosterDialogFor]?.booster2 || null : null}
        onClose={() => setBoosterDialogFor(null)}
        onConfirm={(booster) => boosterDialogFor && handleBoosterConfirm(boosterDialogFor, booster)}
      />

      <CompareShineDialog
        open={!!shineDialogFor}
        position={shineDialogFor ? playerList.find((p) => p.id === shineDialogFor)?.position || 'CF' : 'CF'}
        playerType={shineDialogFor ? playerList.find((p) => p.id === shineDialogFor)?.playerType : null}
        currentLevel={shineDialogFor ? configs[shineDialogFor]?.shineLevel || 0 : 0}
        onClose={() => setShineDialogFor(null)}
        onConfirm={(level) => shineDialogFor && handleShineConfirm(shineDialogFor, level)}
      />
    </div>
  );
};

export default PlayerComparePage;
