export async function getMyBuildPlans(
  page: number,
  pageSize: number,
  headers?: Record<string, string>,
  playerId?: string,
): Promise<BuildPlanListResponse> {
  try {
    const response = await axiosForBackend.get<BuildPlanListResponse>(
      '/api/player-builds/plans/my',
      {
        params: { page, pageSize, ...(playerId ? { playerId } : {}) },
        headers,
      },
    );
    return response.data;
  } catch (error) {
    logger.error(
      `获取我的培养方案失败: page=${page} pageSize=${pageSize} playerId=${playerId ?? ''}`,
      error,
    );
    throw error;
  }
}

// 按快照行 id 删除单条（同一球员可能有多条）
export async function deleteBuildPlan(
  snapshotId: string,
  headers?: Record<string, string>,
): Promise<void> {
  try {
    await axiosForBackend.delete(
      `/api/player-builds/plans/snapshot/${snapshotId}`,
      { headers },
    );
  } catch (error) {
    logger.error(`删除培养方案失败: ${snapshotId}`, error);
    throw error;
  }
}
